 className="monitoring-structure-warning-action"
 onClick={() => onRiskScopeChange?.("trial", {})}
 >
 返回试验范围并重新选择
 </button>
 </div>
 </section>
 )}
 {riskFocusMessage && (
 <section className="monitoring-structure-warning" role="alert" aria-label="风险深链未找到">
 <AlertTriangle size={17} aria-hidden="true" />
