 ? `${documentSession?.protocol_id || "研究方案"}_${documentSession?.version || "当前版本"}_方案终稿.docx`
 : `${documentSession?.protocol_id || "研究方案"}_${documentSession?.version || "当前版本"}_草稿预览.docx`;
