 : !workingCopyAuthoritative
 ? "当前历史工作版本已隔离"
 : editorFrozen
 ? "当前作者确认版本已冻结，请先解除冻结"
 : "将已提交的结构化干预规则生成可继续编辑的本章正文"}
 >
 <FileCheck2 size={15} /> {interventionProjectionBusy ? "应用中" : "应用规则到正文"}
 </button>
 )}
 {isLegacyGreenfieldTemplate && (
 <button
