 <button type="button" onClick={rollbackTemplateUpgrade} disabled={templateUpgradeBusy} title="仅在升级后尚未保存任何新工作副本时可恢复">
 <RotateCcw size={14} /> {templateUpgradeBusy ? "处理中" : "恢复升级前版本"}
 </button>
