 stored = JSON.parse(localStorage.getItem(key) || "null");
 } catch {
 return;
 }
 if (!stored || !stored.job_id || stored.project_id !== projectId) return;
 if (isStaleCompletion(stored, projectId, operation === "initial" ? (selectedSection || "") : "")) {
