 intervalMs: 2000,
 maxLoops: 150,
 onUpdate: (st) => {
 if (!stillCurrent()) return;
 setRevisionJobs((map) => {
 const prev = map?.[operation];
 if (!prev || prev.job_id !== stored.job_id) return map;
 return setOperationJob(map, operation, {
