 className={finding.finding_id === selectedContentFinding.finding_id ? "active" : ""}
 onClick={() => {
 setSelectedContentFindingId(finding.finding_id);
 setContentDispositionReason("");
 setContentDispositionAcknowledged(false);
 }}
