 flex-wrap: wrap;
 gap: 8px;
 padding: 10px 22px;
 background: #f0f6fb;
 border-bottom: 1px solid #e1eaf2;
}

.monitoring-assurance-mode-row button,
.monitoring-assurance-refresh {
 display: inline-flex;
 align-items: center;
 gap: 5px;
 min-height: 30px;
 padding: 5px 10px;
 border: 1px solid transparent;
 border-radius: 8px;
 background: transparent;
 color: #4b6175;
 cursor: pointer;
 font-size: 12px;
}

.monitoring-assurance-mode-row button.active { border-color: #75a6c8; background: #ffffff; color: #17537d; font-weight: 700; }
.monitoring-assurance-mode-row > button:not(.monitoring-assurance-refresh) { flex-direction: column; align-items: flex-start; min-width: min(220px, 100%); text-align: left; }
.monitoring-assurance-mode-row > button:not(.monitoring-assurance-refresh) small { display: block; max-width: 330px; color: #718391; font-size: 10px; font-weight: 400; line-height: 1.35; }
.monitoring-assurance-mode-row > button.active:not(.monitoring-assurance-refresh) small { color: #52728a; }
.monitoring-assurance-mode-row .monitoring-assurance-refresh { margin-left: auto; border-color: #c7d6e3; background: #ffffff; }
.monitoring-assurance-mode-row button:disabled { cursor: wait; opacity: .65; }

.monitoring-assurance-snapshot-grid {
