 grid-template-columns: repeat(5, minmax(0, 1fr));
 gap: 8px;
 padding: 14px 22px;
}

.monitoring-assurance-evidence { min-width: 0; padding: 9px 10px; border: 1px solid #dce7ef; border-radius: 9px; background: #ffffff; }
.monitoring-assurance-evidence.success { border-color: #a7d7bd; background: #f3fbf6; }
.monitoring-assurance-evidence.warning { border-color: #efd18c; background: #fffaf0; }
.monitoring-assurance-evidence span { display: block; color: #6d7f8e; font-size: 11px; }
.monitoring-assurance-evidence strong { display: block; overflow: hidden; margin-top: 3px; color: #1c3b52; font-size: 12px; text-overflow: ellipsis; white-space: nowrap; }

.monitoring-assurance-blocker {
 display: flex;
 gap: 10px;
 margin: 0 22px 12px;
 padding: 11px 12px;
 border: 1px solid #efc7a9;
 border-radius: 10px;
 background: #fff7f1;
 color: #7d4a2c;
}

.monitoring-assurance-blocker svg { flex: 0 0 auto; margin-top: 2px; }
.monitoring-assurance-blocker div { display: grid; gap: 3px; }
.monitoring-assurance-blocker span, .monitoring-assurance-blocker small { line-height: 1.45; }
.monitoring-assurance-blocker small { color: #986443; }

.monitoring-assurance-create-row {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 margin: 0 22px 12px;
 padding: 10px 12px;
 border: 1px solid #b9d8c5;
 border-radius: 10px;
 background: #f4fbf6;
 color: #356749;
 font-size: 12px;
}

.monitoring-assurance-message { display: flex; align-items: center; gap: 6px; margin: 0 22px 10px; color: #31724b; font-size: 12px; }

.monitoring-assurance-body { display: grid; grid-template-columns: minmax(220px, .7fr) minmax(0, 1.3fr); gap: 14px; padding: 0 22px 20px; }
.monitoring-assurance-task-list, .monitoring-assurance-detail { min-width: 0; padding: 12px; border: 1px solid #e0e9f1; border-radius: 10px; background: rgba(255,255,255,.85); }
.monitoring-assurance-section-title { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 10px; color: #27465b; font-size: 13px; }
.monitoring-assurance-section-title > span { color: #738596; font-size: 11px; }

.monitoring-assurance-task { display: flex; align-items: center; justify-content: space-between; gap: 8px; width: 100%; margin-top: 6px; padding: 9px 10px; border: 1px solid #e1eaf1; border-radius: 8px; background: #ffffff; color: #29465a; cursor: pointer; text-align: left; }
.monitoring-assurance-task:hover, .monitoring-assurance-task.selected { border-color: #77a8c8; background: #f3f9fd; }
.monitoring-assurance-task > span:first-child { min-width: 0; display: grid; gap: 2px; }
