.monitoring-assurance-status { display: inline-flex; flex: 0 0 auto; align-items: center; padding: 3px 7px; border-radius: 999px; background: #eef2f5; color: #5d6e7c; font-size: 11px; }
.monitoring-assurance-status.success { background: #e8f7ed; color: #2d7147; }
.monitoring-assurance-status.warning { background: #fff4d7; color: #8a650e; }
.monitoring-assurance-status.danger { background: #fff0ec; color: #a13e2d; }

.monitoring-assurance-task-meta, .monitoring-assurance-counts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin: 12px 0; }
.monitoring-assurance-task-meta span, .monitoring-assurance-counts span { padding: 8px; border-radius: 8px; background: #f5f8fa; color: #6d7d89; font-size: 11px; }
.monitoring-assurance-task-meta b, .monitoring-assurance-counts b { display: block; overflow: hidden; margin-top: 3px; color: #27465b; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; }
.monitoring-assurance-evidence-banner { display: flex; align-items: flex-start; gap: 8px; padding: 10px; border: 1px solid #d9e6ef; border-radius: 9px; background: #f7fbfe; color: #3c6179; }
.monitoring-assurance-evidence-banner div { display: grid; gap: 3px; }
.monitoring-assurance-evidence-banner span { color: #6d8090; font-size: 11px; line-height: 1.45; }

.monitoring-assurance-action-status { display: grid; gap: 8px; margin-top: 12px; padding: 10px; border: 1px solid #d9e6ef; border-radius: 9px; background: #fbfdff; }
.monitoring-assurance-action-status-title { display: flex; align-items: center; justify-content: space-between; gap: 8px; color: #4c6475; font-size: 11px; }
