.monitoring-assurance-action-status-row { min-width: 0; display: grid; gap: 3px; padding: 8px; border: 1px solid #e0e9f1; border-radius: 8px; background: #f7fafc; }
.monitoring-assurance-action-status-row.success { border-color: #b9dcc5; background: #f4fbf6; }
.monitoring-assurance-action-status-row.warning { border-color: #eed69c; background: #fffaf0; }
.monitoring-assurance-action-status-row.danger { border-color: #efc5b6; background: #fff6f2; }
.monitoring-assurance-action-status-label { color: #718391; font-size: 10px; }
