.monitoring-assurance-provenance { margin-top: 10px; border: 1px solid #eed69c; border-radius: 9px; background: #fffaf0; color: #7a5b15; }
.monitoring-assurance-provenance summary { display: flex; align-items: center; gap: 6px; padding: 8px 10px; color: #765817; cursor: pointer; font-size: 11px; font-weight: 700; list-style: none; }
