 eventCategoryClassName,
 eventTone,
 hasActualTimelineDate,
 metricDataCoverage,
 metricDisplayRows,
 metricRiskCount,
 monitoringStatusClass,
 plannedVisitAxis,
 profileDomainCoverage,
 profileMetricEmptyStateMessage,
