 };
}

function point({ pointId, eventId, subjectId, siteId, domain, evidenceId, locator, riskIds = [] }) {
 return {
 point_id: pointId,
 event_id: eventId,
 event_sha256: HASH_A,
 subject_id: subjectId,
 site_id: siteId,
 domain,
 field_name: "VALUE",
