 && dockClosed.risk_page === "2"
 && dockClosed.risk_page_size === "25"
 && dockClosed.risk_scroll_top === "840"
 && dockClosed.risk_snapshot_id === "snapshot-1",
 "dock close preserves sort, pagination, scroll position, and pinned snapshot",
);

