 ["other_non_investigational", "其他非试验用药"],
];
const NON_IP_RULE_CLASS_OPTIONS = RULE_CLASS_OPTIONS.filter(([value]) => ["background", "rescue", "other_non_investigational"].includes(value));
const CM_RULE_CLASS_OPTIONS = RULE_CLASS_OPTIONS.filter(([value]) => ["allowed_cm", "prohibited_cm"].includes(value));
const POLICY_OPTIONS = [
 ["allowed", "允许"],
 ["allowed_if_stable", "允许（病情稳定时）"],
 ["allowed_with_approval", "允许（需批准）"],
 ["allowed_with_timing", "允许（限时）"],
 ["prohibited", "禁止"],
 ["rescue_policy", "补救策略"],
];
const LINK_ACTION_OPTIONS = [
 ["hold", "暂停IP"],
 ["stop", "停止IP"],
 ["no_auto_ip_action", "不自动改变IP"],
 ["resume", "恢复IP"],
];

const PANELS = [
 ["regimen", "试验药物与给药"],
 ["ip_actions", "试验用药品调整与处置"],
 ["non_ip", "非试验用药与补救"],
 ["cm", "合并用药"],
];

const uid = (prefix) => `${prefix}_${typeof globalThis.crypto?.randomUUID === "function" ? globalThis.crypto.randomUUID() : Math.random().toString(36).slice(2, 10)}`;

function emptyRules() {
 return {
 schema_version: SCHEMA_VERSION,
 authority: "legacy",
 ip_regimens: [],
 ip_adjustment_policy: "unspecified",
 no_planned_adjustment_statement: "",
 ip_action_rules: [],
 non_ip_treatment_rules: [],
 cross_object_links: [],
 };
}

function ensureRules(value) {
 if (!value || typeof value !== "object") return emptyRules();
 return {
 schema_version: SCHEMA_VERSION,
 authority: value.authority === "structured" ? "structured" : "legacy",
 ip_regimens: Array.isArray(value.ip_regimens) ? value.ip_regimens : [],
 ip_adjustment_policy: ADJUSTMENT_POLICY_OPTIONS.some(([k]) => k === value.ip_adjustment_policy) ? value.ip_adjustment_policy : "unspecified",
 no_planned_adjustment_statement: String(value.no_planned_adjustment_statement || ""),
 ip_action_rules: Array.isArray(value.ip_action_rules) ? value.ip_action_rules : [],
 non_ip_treatment_rules: Array.isArray(value.non_ip_treatment_rules) ? value.non_ip_treatment_rules : [],
 cross_object_links: Array.isArray(value.cross_object_links) ? value.cross_object_links : [],
 };
}

function newRowRegimen() {
 return { regimen_id: uid("reg"), product_name: "", product_role: "investigational_product", dose_and_frequency: "", route: "", treatment_period: "", adherence_notes: "", source_location: "" };
}
function newRowIpAction() {
 return { rule_id: uid("ipr"), action_kind: "temporary_interruption", trigger: "", severity_or_threshold: "", confirmation_required: "", exceptions: [], study_product_action: "", retest_recovery: "", approvers: [], wait_period: "", permanent_discontinuation_condition: "", taper_steps: [], linked_non_ip_rule_ids: [], source_location: "", notes: "" };
}
function newRowNonIp() {
 return { rule_id: uid("nir"), rule_class: "background", policy: "allowed", agent_or_category: "", collection_window: "", timing_restrictions: [], washout_or_window: "", cm_dose_rule: "", phase_applicability: "", exceptions: [], source_location: "", notes: "" };
}
function newRowLink() {
 return { link_id: uid("lnk"), source_rule_id: "", source_kind: "rescue", target_kind: "ip", target_rule_id: "", action: "no_auto_ip_action", resume_condition: "", notes: "", source_location: "" };
}

export function InterventionRulesEditor({ value, onChange, panel = "", onPanelChange }) {
 const [collapsed, setCollapsed] = useState(false);
 const rules = ensureRules(value);
 const activePanel = PANELS.some(([key]) => key === panel) ? panel : "regimen";

 useEffect(() => {
 if (panel && !PANELS.some(([key]) => key === panel)) onPanelChange?.("regimen");
 }, [panel, onPanelChange]);

 const update = (patch) => {
 const next = { ...rules, ...patch };
 const hasStructuredContent = next.ip_regimens.length
 || next.ip_action_rules.length
 || next.non_ip_treatment_rules.length
 || next.cross_object_links.length
 || next.ip_adjustment_policy !== "unspecified"
 || next.no_planned_adjustment_statement.trim();
 if (hasStructuredContent && next.authority !== "structured") next.authority = "structured";
 onChange(next);
 };

 const listOps = (field, factory) => ({
 add: () => update({ [field]: [...rules[field], factory()] }),
 addWith: (override) => update({ [field]: [...rules[field], { ...factory(), ...override }] }),
 removeItem: (index) => update({ [field]: rules[field].filter((_, i) => i !== index) }),
 setItem: (index, patch) => update({ [field]: rules[field].map((item, i) => (i === index ? { ...item, ...patch } : item)) }),
 });

 const toggleCollapsed = () => setCollapsed((v) => !v);
 const setPanel = (key) => onPanelChange?.(key);

 const ipActionIds = rules.ip_action_rules.map((r) => r.rule_id);
 const nonIpIds = rules.non_ip_treatment_rules.map((r) => r.rule_id);

 return (
 <section className="intervention-rules-editor">
 <header className="intervention-rules-head" onClick={toggleCollapsed} role="button" tabIndex={0} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); toggleCollapsed(); } }}>
 <span className="intervention-rules-toggle">{collapsed ? <ChevronRight size={14} /> : <ChevronDown size={14} />}</span>
 <div>
 <strong>结构化干预规则编辑器</strong>
 <small>试验药物与给药、剂量调整、非试验用药/补救、合并用药分栏维护；IP与CM边界不混用。</small>
 </div>
 <span className={`intervention-rules-authority ${rules.authority}`}>{rules.authority === "structured" ? "结构化" : "兼容模式"}</span>
 </header>
 {!collapsed && (
 <>
 <div className="intervention-rules-segments" role="tablist">
 {PANELS.map(([key, label]) => (
 <button key={key} type="button" role="tab" aria-selected={activePanel === key} className={activePanel === key ? "active" : ""} onClick={() => setPanel(key)}>{label}</button>
 ))}
 </div>
 <div className="intervention-rules-body">
 {activePanel === "regimen" && <RegimenPanel rules={rules} ops={listOps("ip_regimens", newRowRegimen)} />}
 {activePanel === "ip_actions" && <IpActionsPanel rules={rules} update={update} ops={listOps("ip_action_rules", newRowIpAction)} nonIpIds={nonIpIds} />}
 {activePanel === "non_ip" && <NonIpPanel rules={rules} ops={listOps("non_ip_treatment_rules", newRowNonIp)} linkOps={listOps("cross_object_links", newRowLink)} ipActionIds={ipActionIds} />}
 {activePanel === "cm" && <CmPanel rules={rules} ops={listOps("non_ip_treatment_rules", newRowNonIp)} linkOps={listOps("cross_object_links", newRowLink)} ipActionIds={ipActionIds} />}
 </div>
 </>
 )}
 </section>
 );
}

function DenseRow({ index, onDelete, deleteLabel, children }) {
 return (
 <div className="intervention-rules-row">
 <span className="intervention-rules-row-index">{String(index + 1).padStart(2, "0")}</span>
 <div className="intervention-rules-row-fields">{children}</div>
 <button type="button" className="icon-button intervention-rules-row-delete" onClick={onDelete} title={deleteLabel}><Trash2 size={14} /></button>
 </div>
 );
}

function MiniInput({ label, value, onChange, placeholder, span }) {
 return (
 <label className={`intervention-rules-mini ${span ? `span-${span}` : ""}`}>
 <span>{label}</span>
 <input value={value || ""} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} />
 </label>
 );
}
function MiniSelect({ label, value, onChange, options, disabled = false }) {
 return (
 <label className="intervention-rules-mini">
 <span>{label}</span>
 <select value={value || ""} onChange={(e) => onChange(e.target.value)} disabled={disabled}>
 {options.map(([val, lbl]) => <option key={val} value={val}>{lbl}</option>)}
 </select>
 </label>
 );
}
function MiniArea({ label, value, onChange, placeholder, rows }) {
 return (
 <label className="intervention-rules-mini span-full">
 <span>{label}</span>
 <textarea rows={rows || 2} value={value || ""} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} />
 </label>
 );
}

function MiniListInput({ label, value, onChange, span = 2 }) {
 return <MiniInput label={label} value={(value || []).join("；")} onChange={(text) => onChange(text.split(/[;；\n]+/).map((item) => item.trim()).filter(Boolean))} span={span} />;
}

function PanelAddButton({ label, onClick }) {
 return <button type="button" className="intervention-rules-add" onClick={onClick}><Plus size={14} /> {label}</button>;
}

function EmptyHint({ text }) {
 return <p className="intervention-rules-empty">{text}</p>;
}

function RegimenPanel({ rules, ops }) {
 return (
 <div className="intervention-rules-panel">
 <p className="intervention-rules-panel-hint">试验药物常规给药方案（IP）。CM剂量调整不在此处。</p>
 {rules.ip_regimens.length === 0 && <EmptyHint text="尚未登记试验药物给药方案。" />}
 {rules.ip_regimens.map((row, i) => (
 <DenseRow key={row.regimen_id} index={i} onDelete={() => ops.removeItem(i)} deleteLabel="删除给药方案">
 <MiniInput label="产品名称" value={row.product_name} onChange={(v) => ops.setItem(i, { product_name: v })} />
 <MiniSelect label="产品角色" value={row.product_role} onChange={(v) => ops.setItem(i, { product_role: v })} options={PRODUCT_ROLE_OPTIONS} />
 <MiniInput label="用法用量" value={row.dose_and_frequency} onChange={(v) => ops.setItem(i, { dose_and_frequency: v })} span={2} />
 <MiniInput label="给药途径" value={row.route} onChange={(v) => ops.setItem(i, { route: v })} />
 <MiniInput label="治疗时期" value={row.treatment_period} onChange={(v) => ops.setItem(i, { treatment_period: v })} />
 <MiniInput label="依从性说明" value={row.adherence_notes} onChange={(v) => ops.setItem(i, { adherence_notes: v })} span={2} />
 <MiniInput label="来源定位" value={row.source_location} onChange={(v) => ops.setItem(i, { source_location: v })} span={2} />
 </DenseRow>
 ))}
 <PanelAddButton label="新增给药方案" onClick={ops.add} />
 </div>
 );
}

function IpActionsPanel({ rules, update, ops, nonIpIds }) {
 const policy = rules.ip_adjustment_policy;
 return (
 <div className="intervention-rules-panel">
 <div className="intervention-rules-policy-bar">
 <label className="intervention-rules-mini">
 <span>剂量调整策略</span>
 <select value={policy} onChange={(e) => update({ ip_adjustment_policy: e.target.value })}>
 {ADJUSTMENT_POLICY_OPTIONS.map(([val, lbl]) => <option key={val} value={val}>{lbl}</option>)}
 </select>
 </label>
 {policy === "no_planned_adjustment" && (
 <label className="intervention-rules-mini span-full">
 <span>无计划性调整说明（必填）</span>
 <input value={rules.no_planned_adjustment_statement || ""} onChange={(e) => update({ no_planned_adjustment_statement: e.target.value })} placeholder="说明本研究无计划性常规剂量调整，可包含安全中断/永久停药/减量/随访规则" />
 </label>
 )}
 </div>
 {rules.ip_action_rules.length === 0 && <EmptyHint text="尚未登记试验药物剂量调整规则。" />}
 {rules.ip_action_rules.map((row, i) => (
 <DenseRow key={row.rule_id} index={i} onDelete={() => ops.removeItem(i)} deleteLabel="删除IP调整规则">
 <MiniSelect label="调整类型" value={row.action_kind} onChange={(v) => ops.setItem(i, { action_kind: v })} options={ACTION_KIND_OPTIONS} />
 <MiniInput label="触发条件" value={row.trigger} onChange={(v) => ops.setItem(i, { trigger: v })} span={3} />
 <MiniInput label="严重程度/阈值" value={row.severity_or_threshold} onChange={(v) => ops.setItem(i, { severity_or_threshold: v })} span={2} />
 <MiniInput label="确认要求" value={row.confirmation_required} onChange={(v) => ops.setItem(i, { confirmation_required: v })} span={2} />
 <MiniArea label="试验药物处置" value={row.study_product_action} onChange={(v) => ops.setItem(i, { study_product_action: v })} />
 <MiniArea label="复测/恢复条件" value={row.retest_recovery} onChange={(v) => ops.setItem(i, { retest_recovery: v })} />
 <MiniInput label="等待期" value={row.wait_period} onChange={(v) => ops.setItem(i, { wait_period: v })} span={2} />
 <MiniListInput label="例外条件" value={row.exceptions} onChange={(v) => ops.setItem(i, { exceptions: v })} />
 {row.action_kind === "permanent_discontinuation" && (
 <MiniArea label="永久停药条件" value={row.permanent_discontinuation_condition} onChange={(v) => ops.setItem(i, { permanent_discontinuation_condition: v })} />
 )}
 {row.action_kind === "discontinuation_taper" && <MiniListInput label="递减步骤" value={row.taper_steps} onChange={(v) => ops.setItem(i, { taper_steps: v })} span={4} />}
 <MiniInput label="审批人" value={(row.approvers || []).join("、")} onChange={(v) => ops.setItem(i, { approvers: v.split(/[、,;，；\n]+/).map((s) => s.trim()).filter(Boolean) })} span={2} />
 <MiniInput label="来源定位" value={row.source_location} onChange={(v) => ops.setItem(i, { source_location: v })} span={2} />
 <MiniArea label="备注" value={row.notes} onChange={(v) => ops.setItem(i, { notes: v })} />
 </DenseRow>
 ))}
 <PanelAddButton label="新增IP剂量调整规则" onClick={ops.add} />
 {nonIpIds.length > 0 && rules.ip_action_rules.length > 0 && (
 <p className="intervention-rules-panel-hint">非试验治疗或 CM 对试验用药品的影响，请在对应规则面板建立显式关联。</p>
 )}
 </div>
 );
}

function NonIpPanel({ rules, ops, linkOps, ipActionIds }) {
 const filtered = rules.non_ip_treatment_rules.map((row, originalIndex) => ({ row, originalIndex })).filter(({ row }) => ["background", "rescue", "other_non_investigational"].includes(row.rule_class));
 const sourceRuleIds = filtered.map(({ row }) => row.rule_id);
 return (
 <div className="intervention-rules-panel">
 <p className="intervention-rules-panel-hint">背景治疗、补救治疗及其他非试验用药。合并用药（允许/禁止）请在"合并用药"面板维护。</p>
 {filtered.length === 0 && <EmptyHint text="尚未登记非试验用药/补救治疗规则。" />}
 {filtered.map(({ row, originalIndex }, displayIndex) => (
 <DenseRow key={row.rule_id} index={displayIndex} onDelete={() => ops.removeItem(originalIndex)} deleteLabel="删除非IP规则">
 <MiniSelect label="规则类别" value={row.rule_class} onChange={(v) => ops.setItem(originalIndex, { rule_class: v, policy: v === "rescue" ? "rescue_policy" : row.policy === "rescue_policy" ? "allowed" : row.policy })} options={NON_IP_RULE_CLASS_OPTIONS} />
 <MiniSelect label="策略" value={row.policy} onChange={(v) => ops.setItem(originalIndex, { policy: v })} options={POLICY_OPTIONS} />
 <MiniInput label="药物/类别" value={row.agent_or_category} onChange={(v) => ops.setItem(originalIndex, { agent_or_category: v })} span={2} />
 <MiniInput label="采集窗口" value={row.collection_window} onChange={(v) => ops.setItem(originalIndex, { collection_window: v })} />
 <MiniListInput label="时间限制" value={row.timing_restrictions} onChange={(v) => ops.setItem(originalIndex, { timing_restrictions: v })} />
 <MiniInput label="洗脱/时间窗" value={row.washout_or_window} onChange={(v) => ops.setItem(originalIndex, { washout_or_window: v })} span={2} />
 <MiniInput label="阶段适用性" value={row.phase_applicability} onChange={(v) => ops.setItem(originalIndex, { phase_applicability: v })} span={2} />
 <MiniInput label="CM剂量规则" value={row.cm_dose_rule} onChange={(v) => ops.setItem(originalIndex, { cm_dose_rule: v })} span={2} />
 <MiniListInput label="例外条件" value={row.exceptions} onChange={(v) => ops.setItem(originalIndex, { exceptions: v })} />
 <MiniInput label="来源定位" value={row.source_location} onChange={(v) => ops.setItem(originalIndex, { source_location: v })} span={2} />
 <MiniArea label="备注" value={row.notes} onChange={(v) => ops.setItem(originalIndex, { notes: v })} />
 </DenseRow>
 ))}
 <PanelAddButton label="新增非IP规则" onClick={ops.add} />
 <CrossObjectLinks rules={rules} linkOps={linkOps} ipActionIds={ipActionIds} sourceRuleIds={sourceRuleIds} defaultSourceKind="rescue" />
 </div>
 );
}

function CmPanel({ rules, ops, linkOps, ipActionIds }) {
 const cmRows = rules.non_ip_treatment_rules.map((row, originalIndex) => ({ row, originalIndex })).filter(({ row }) => ["allowed_cm", "prohibited_cm"].includes(row.rule_class));
 const sourceRuleIds = cmRows.map(({ row }) => row.rule_id);
 return (
 <div className="intervention-rules-panel">
 <p className="intervention-rules-panel-hint">合并用药允许/禁止规则。CM剂量变更不会生成IP剂量调整规则。</p>
 {cmRows.length === 0 && <EmptyHint text="尚未登记合并用药规则。新增非IP规则后选择允许的合并用药或禁止的合并用药类别即可。" />}
 {cmRows.map(({ row, originalIndex }, displayIndex) => (
 <DenseRow key={row.rule_id} index={displayIndex} onDelete={() => ops.removeItem(originalIndex)} deleteLabel="删除CM规则">
 <MiniSelect label="规则类别" value={row.rule_class} onChange={(v) => ops.setItem(originalIndex, { rule_class: v, policy: v === "prohibited_cm" ? "prohibited" : row.policy === "prohibited" ? "allowed" : row.policy })} options={CM_RULE_CLASS_OPTIONS} />
 <MiniSelect label="策略" value={row.policy} onChange={(v) => ops.setItem(originalIndex, { policy: v })} options={POLICY_OPTIONS} />
 <MiniInput label="药物/类别" value={row.agent_or_category} onChange={(v) => ops.setItem(originalIndex, { agent_or_category: v })} span={2} />
 <MiniInput label="CM剂量规则" value={row.cm_dose_rule} onChange={(v) => ops.setItem(originalIndex, { cm_dose_rule: v })} span={2} />
 <MiniInput label="采集窗口" value={row.collection_window} onChange={(v) => ops.setItem(originalIndex, { collection_window: v })} />
 <MiniListInput label="时间限制" value={row.timing_restrictions} onChange={(v) => ops.setItem(originalIndex, { timing_restrictions: v })} />
 <MiniInput label="洗脱/时间窗" value={row.washout_or_window} onChange={(v) => ops.setItem(originalIndex, { washout_or_window: v })} span={2} />
 <MiniInput label="阶段适用性" value={row.phase_applicability} onChange={(v) => ops.setItem(originalIndex, { phase_applicability: v })} span={2} />
 <MiniListInput label="例外条件" value={row.exceptions} onChange={(v) => ops.setItem(originalIndex, { exceptions: v })} />
 <MiniInput label="来源定位" value={row.source_location} onChange={(v) => ops.setItem(originalIndex, { source_location: v })} span={2} />
 <MiniArea label="备注" value={row.notes} onChange={(v) => ops.setItem(originalIndex, { notes: v })} />
 </DenseRow>
 ))}
 <PanelAddButton label="新增CM规则" onClick={() => ops.addWith({ rule_class: "allowed_cm" })} />
 <CrossObjectLinks rules={rules} linkOps={linkOps} ipActionIds={ipActionIds} sourceRuleIds={sourceRuleIds} defaultSourceKind="cm" />
 </div>
 );
}

function CrossObjectLinks({ rules, linkOps, ipActionIds, sourceRuleIds, defaultSourceKind }) {
 const links = rules.cross_object_links.map((link, originalIndex) => ({ link, originalIndex })).filter(({ link }) => sourceRuleIds.includes(link.source_rule_id));
 if (!sourceRuleIds.length || !ipActionIds.length) return null;
 const nonIpById = new Map(rules.non_ip_treatment_rules.map((rule) => [rule.rule_id, rule]));
 const ipActionById = new Map(rules.ip_action_rules.map((rule) => [rule.rule_id, rule]));
 const sourceKind = (ruleId) => {
 const ruleClass = nonIpById.get(ruleId)?.rule_class;
 if (ruleClass === "rescue") return "rescue";
 if (ruleClass === "background") return "background";
 if (["allowed_cm", "prohibited_cm"].includes(ruleClass)) return "cm";
 return "other_non_ip";
 };
 const sourceOptions = sourceRuleIds.map((id) => {
 const rule = nonIpById.get(id);
 return [id, `${rule?.agent_or_category || "未命名规则"} (${id})`];
 });
 const targetOptions = ipActionIds.map((id) => {
 const rule = ipActionById.get(id);
 const actionLabel = ACTION_KIND_OPTIONS.find(([value]) => value === rule?.action_kind)?.[1] || "试验用药品处置";
 return [id, `${actionLabel}${rule?.trigger ? ` · ${rule.trigger}` : ""} (${id})`];
 });
 return (
 <div className="intervention-rules-links">
 <header><strong>跨对象关联</strong><span>明确非试验治疗或 CM 是否触发试验用药品暂停、停止或恢复；不会把两类规则合并。</span></header>
 {links.map(({ link, originalIndex }, displayIndex) => (
 <DenseRow key={link.link_id} index={displayIndex} onDelete={() => linkOps.removeItem(originalIndex)} deleteLabel="删除关联">
 <MiniSelect label="来源规则" value={link.source_rule_id} onChange={(v) => linkOps.setItem(originalIndex, { source_rule_id: v, source_kind: sourceKind(v) })} options={sourceOptions} />
 <MiniSelect label="来源类型" value={sourceKind(link.source_rule_id)} onChange={() => {}} options={[["rescue", "补救治疗"], ["cm", "合并用药"], ["background", "背景治疗"], ["other_non_ip", "其他非试验治疗"]]} disabled />
 <MiniSelect label="目标试验用药品规则" value={link.target_rule_id} onChange={(v) => linkOps.setItem(originalIndex, { target_rule_id: v })} options={[["", "—无—"], ...targetOptions]} />
 <MiniSelect label="动作" value={link.action} onChange={(v) => linkOps.setItem(originalIndex, { action: v })} options={LINK_ACTION_OPTIONS} />
 <MiniInput label="恢复条件" value={link.resume_condition} onChange={(v) => linkOps.setItem(originalIndex, { resume_condition: v })} span={2} />
 <MiniInput label="来源定位" value={link.source_location} onChange={(v) => linkOps.setItem(originalIndex, { source_location: v })} span={2} />
 <MiniArea label="补充说明" value={link.notes} onChange={(v) => linkOps.setItem(originalIndex, { notes: v })} />
 </DenseRow>
 ))}
 <PanelAddButton label="新增跨对象关联" onClick={() => linkOps.addWith({ source_rule_id: sourceRuleIds[0], source_kind: sourceKind(sourceRuleIds[0]) || defaultSourceKind, target_rule_id: ipActionIds[0] })} />
 </div>
 );
}

import { useEffect, useMemo, useRef, useState } from "react";
import {
 CheckCircle2,
 FileCheck2,
 FileText,
 RefreshCw,
 ShieldAlert,
 X,
} from "lucide-react";

const ACTOR = "medical_manager";

const LEGACY_BOOTSTRAP_CONFIRMED_PATHS = Object.freeze([
 "framing.protocol_id",
 "framing.version",
 "framing.document_title",
 "framing.indication",
 "framing.study_phase",
 "framing.investigational_product",
 "framing.target_mechanism",
 "framing.design_pattern",
 "framing.population_intent",
 "picos.population_summary",
 "picos.intervention_summary",
 "picos.comparator_summary",
 "picos.primary_endpoint",
]);

function apiErrorText(error) {
 return String(error?.detail || error?.message || error || "请求失败");
}

async function readJsonOrThrow(response) {
 const payload = await response.json().catch(() => ({}));
 if (!response.ok) {
 const error = new Error(payload?.detail || `请求失败（${response.status}）`);
 error.status = response.status;
 error.detail = payload?.detail || "";
 throw error;
 }
 return payload;
}

function roleLabel(role) {
 return role === "synopsis" ? "方案摘要" : "完整研究方案";
}

function extractionStageLabel(jobStatus) {
 return {
 queued: "等待独立AI处理",
 parsing: "正在解析文件内容",
 ai_synthesis: "正在提取研究设计",
 validating: "正在合并并核对结果",
 }[jobStatus] || "正在处理原始文件";
}

function clone(value) {
 return value == null ? value : JSON.parse(JSON.stringify(value));
}

function warningList(candidate) {
 return Array.from(new Set(
 (candidate?.source?.validation_warnings || []).filter(Boolean),
 ));
}

function storageKey(projectId) {
 return `mw-legacy-bootstrap:${projectId}`;
}

function readStoredImportKey(projectId) {
 try {
 return globalThis.sessionStorage?.getItem(storageKey(projectId)) || "";
 } catch {
 return "";
 }
}

function writeStoredImportKey(projectId, value) {
 try {
 globalThis.sessionStorage?.setItem(storageKey(projectId), value);
 } catch {
 // The server-side idempotency key still protects the active request.
 }
}

function clearStoredImportKey(projectId) {
 try {
 globalThis.sessionStorage?.removeItem(storageKey(projectId));
 } catch {
 // A blocked session store must not make the import workflow unusable.
 }
}

function TextField({
 fieldPath,
 label,
 value,
 onChange,
 wide = false,
 multiline = false,
}) {
 const confirmedPath = LEGACY_BOOTSTRAP_CONFIRMED_PATHS.includes(fieldPath)
 ? fieldPath
 : undefined;
 return (
 <label className={wide ? "span-2" : ""} data-confirmed-path={confirmedPath}>
 <span>{label}</span>
 {multiline
 ? <textarea rows={3} value={value || ""} onChange={(event) => onChange(event.target.value)} />
 : <input value={value || ""} onChange={(event) => onChange(event.target.value)} />}
 </label>
 );
}

export function LegacyAuthoringBootstrapPanel({
 projectId,
 expectedIndication = "",
 onConfirmed,
 onOpenBinding,
}) {
 const [status, setStatus] = useState(null);
 const [open, setOpen] = useState(false);
 const [busy, setBusy] = useState("");
 const [message, setMessage] = useState("");
 const [importKey, setImportKey] = useState("");
 const [framing, setFraming] = useState(null);
 const [picos, setPicos] = useState(null);
 const [synopsisText, setSynopsisText] = useState("");
 const [confirmedRole, setConfirmedRole] = useState("protocol");
 const [roleOverrideReason, setRoleOverrideReason] = useState("");
 const [acknowledgedWarnings, setAcknowledgedWarnings] = useState([]);
 const [validationOverrideReason, setValidationOverrideReason] = useState("");
 const requestRef = useRef(0);

 const detectedRole = status?.detected_source_role || status?.source_role || "protocol";
 const warnings = useMemo(() => warningList(status?.candidate), [status?.candidate]);
 const roleOverridden = Boolean(confirmedRole && confirmedRole !== detectedRole);
 const allWarningsAcknowledged = warnings.every((warning) => acknowledgedWarnings.includes(warning));
 const missingCoreFields = useMemo(() => {
 if (!framing || !picos) return [];
 const fields = [
 ["方案号", framing.protocol_id],
 ["版本", framing.version],
 ["方案标题", framing.document_title],
 ["适应症", framing.indication],
 ["研究分期", framing.study_phase],
 ["试验药物", framing.investigational_product],
 ["总体设计", framing.design_pattern],
 ["目标研究人群", framing.population_intent],
 ["研究人群", picos.population_summary],
 ["干预措施", picos.intervention_summary],
 ["主要终点及评价时间", picos.primary_endpoint],
 ["方案摘要文本", synopsisText],
 ];
 return fields.filter(([, value]) => !String(value || "").trim()).map(([label]) => label);
 }, [framing, picos, synopsisText]);
 const confirmationReady = Boolean(
 status?.state === "review_pending"
 && status?.candidate?.source?.source_id
 && framing
 && picos
 && synopsisText.trim()
 && missingCoreFields.length === 0
 && allWarningsAcknowledged
 && (!warnings.length || validationOverrideReason.trim().length >= 10)
 && (!roleOverridden || roleOverrideReason.trim().length >= 10)
 );

 const loadStatus = async (key = importKey, { quiet = false } = {}) => {
 const requestId = requestRef.current + 1;
 requestRef.current = requestId;
 if (!quiet) setBusy("loading");
 try {
 const query = key ? `?import_idempotency_key=${encodeURIComponent(key)}` : "";
 const payload = await fetch(
 `/api/projects/${projectId}/medical-writing/legacy-authoring-bootstrap${query}`,
 ).then(readJsonOrThrow);
 if (requestId !== requestRef.current) return null;
 setStatus(payload);
 setConfirmedRole(
 payload.confirmed_source_role
 || payload.author_confirmed_source_role
 || payload.source_role
 || "protocol",
 );
 if (payload.import_idempotency_key) {
 setImportKey(payload.import_idempotency_key);
 writeStoredImportKey(projectId, payload.import_idempotency_key);
 }
 if (payload.candidate) {
 setFraming(clone(payload.candidate.proposed_framing));
 setPicos(clone(payload.candidate.proposed_picos));
 setSynopsisText(payload.candidate.proposed_synopsis_text || "");
 }
 if (["bound", "not_eligible"].includes(payload.state)) {
 clearStoredImportKey(projectId);
 }
 setMessage(payload.message || "");
 return payload;
 } catch (error) {
 if (requestId !== requestRef.current) return null;
 setMessage(apiErrorText(error));
 return null;
 } finally {
 if (requestId === requestRef.current && !quiet) setBusy("");
 }
 };

 useEffect(() => {
 const stored = readStoredImportKey(projectId);
 setImportKey(stored);
 loadStatus(stored);
 return () => {
 requestRef.current += 1;
 };
 // The bootstrap source is scoped by project and immutable source hash.
 // eslint-disable-next-line react-hooks/exhaustive-deps
 }, [projectId]);

 useEffect(() => {
 if (!["extracting"].includes(status?.state) || !importKey) return undefined;
 let cancelled = false;
 let timer;
 const poll = async () => {
 await loadStatus(importKey, { quiet: true });
 if (!cancelled) timer = globalThis.setTimeout(poll, 3000);
 };
 timer = globalThis.setTimeout(poll, 3000);
 return () => {
 cancelled = true;
 globalThis.clearTimeout(timer);
 };
 // eslint-disable-next-line react-hooks/exhaustive-deps
 }, [status?.state, importKey]);

 useEffect(() => {
 if (!open) return undefined;
 const handleKeyDown = (event) => {
 if (event.key === "Escape") setOpen(false);
 };
 globalThis.addEventListener?.("keydown", handleKeyDown);
 return () => globalThis.removeEventListener?.("keydown", handleKeyDown);
 }, [open]);

 useEffect(() => {
 setAcknowledgedWarnings([]);
 setValidationOverrideReason("");
 }, [
 status?.candidate?.source?.content_sha256,
 status?.candidate?.source?.extraction_revision,
 ]);

 const startExtraction = async () => {
 if (!status?.document_id || !status?.source_sha256) return;
 const retrySuffix = status.state === "failed" ? `-${Date.now()}` : "";
 const key = `legacy-extract-${projectId}-${status.source_sha256.slice(0, 16)}${retrySuffix}`.slice(0, 200);
 setBusy("prepare");
 setMessage("");
 try {
 const payload = await fetch(
 `/api/projects/${projectId}/medical-writing/legacy-authoring-bootstrap/prepare`,
 {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 expected_document_id: status.document_id,
 expected_source_sha256: status.source_sha256,
 expected_indication: expectedIndication || "",
 actor: ACTOR,
 idempotency_key: key,
 }),
 },
 ).then(readJsonOrThrow);
 setImportKey(payload.import_idempotency_key || key);
 writeStoredImportKey(projectId, payload.import_idempotency_key || key);
 setStatus(payload);
 setMessage("正在从原始文件提取研究框架、PICOS和方案摘要。");
 } catch (error) {
 setMessage(apiErrorText(error));
 } finally {
 setBusy("");
 }
 };

 const updateFraming = (field, value) => {
 setFraming((current) => ({ ...current, [field]: value }));
 };

 const updatePicos = (field, value) => {
 setPicos((current) => ({ ...current, [field]: value }));
 };

 const toggleWarning = (warning) => {
 setAcknowledgedWarnings((current) => (
 current.includes(warning)
 ? current.filter((item) => item !== warning)
 : [...current, warning]
 ));
 };

 const confirmCandidate = async () => {
 if (!confirmationReady) return;
 setBusy("confirm");
 setMessage("");
 try {
 const payload = await fetch(
 `/api/projects/${projectId}/medical-writing/legacy-authoring-bootstrap/confirm`,
 {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 expected_document_id: status.document_id,
 expected_source_sha256: status.source_sha256,
 import_idempotency_key: importKey,
 source_id: status.candidate.source.source_id,
 framing,
 picos,
 synopsis_text: synopsisText,
 confirmed_source_role: confirmedRole,
 source_role_override_reason: roleOverridden ? roleOverrideReason.trim() : "",
 acknowledged_validation_warnings: acknowledgedWarnings,
 validation_override_reason: warnings.length ? validationOverrideReason.trim() : "",
 actor: ACTOR,
 idempotency_key: `legacy-confirm-${projectId}-${status.source_sha256.slice(0, 16)}`.slice(0, 200),
 }),
 },
 ).then(readJsonOrThrow);
 setStatus(payload);
 clearStoredImportKey(projectId);
 setMessage("研究设计基线已建立；原始文件保持只读，下一步核对影响并重绑定。");
 await onConfirmed?.(payload);
 } catch (error) {
 setMessage(apiErrorText(error));
 } finally {
 setBusy("");
 }
 };

 if (!status || ["bound", "not_eligible"].includes(status.state)) return null;

 return (
 <>
 <section className={`legacy-bootstrap-bar ${status.state === "failed" ? "is-error" : ""}`}>
 <div>
 {status.state === "confirmed_ready_for_binding"
 ? <CheckCircle2 size={17} />
 : status.state === "failed"
 ? <ShieldAlert size={17} />
 : <FileText size={17} />}
 <span>
 <strong>
 {status.state === "confirmed_ready_for_binding"
 ? "已从原始方案建立研究设计基线"
 : status.state === "extracting"
 ? "正在解析原始方案"
 : status.state === "review_pending"
 ? "研究设计候选待作者核对"
 : status.state === "failed"
 ? "原始方案解析未完成"
 : "原始方案尚未建立研究设计基线"}
 </strong>
 <small>
 {status.source_filename || "原始方案"}
 {` · 系统识别为${roleLabel(detectedRole)}`}
 </small>
 </span>
 </div>
 {status.state === "confirmed_ready_for_binding"
 ? <button type="button" onClick={onOpenBinding}><FileCheck2 size={14} /> 核对影响并重绑定</button>
 : <button type="button" onClick={() => setOpen(true)}>
 {status.state === "review_pending" ? "核对提取结果" : status.state === "extracting" ? "查看进度" : "建立研究设计基线"}
 </button>}
 </section>

 {open && (
 <div className="legacy-bootstrap-layer" role="presentation" onMouseDown={(event) => {
 if (event.target === event.currentTarget) setOpen(false);
 }}>
 <aside className="legacy-bootstrap-drawer" role="dialog" aria-modal="true" aria-label="原始方案研究设计基线">
 <header>
 <div>
 <span>原始方案导入</span>
 <strong>建立可追溯的研究设计基线</strong>
 </div>
 <button type="button" onClick={() => setOpen(false)} title="关闭"><X size={18} /></button>
 </header>

 <div className="legacy-bootstrap-source">
 <FileText size={18} />
 <span>
 <strong title={status.source_filename}>{status.source_filename}</strong>
 <small>原始文件只读 · {status.source_sha256?.slice(0, 12)}…</small>
 </span>
 <em>{roleLabel(detectedRole)}</em>
 </div>

 {status.state === "eligible" || status.state === "failed" ? (
 <section className="legacy-bootstrap-start">
 <p>独立AI将提取研究框架、PICOS和方案摘要；完成后直接核对并修订候选。</p>
 {message && <small className={status.state === "failed" ? "danger" : ""}>{message}</small>}
 <button type="button" className="primary-button" onClick={startExtraction} disabled={Boolean(busy)}>
 <RefreshCw size={15} /> {busy === "prepare" ? "正在启动" : status.state === "failed" ? "重新解析" : "AI提取研究设计"}
 </button>
 </section>
 ) : status.state === "extracting" ? (
 <section className="legacy-bootstrap-progress" aria-live="polite">
 <RefreshCw size={20} className="spin" />
 <strong>{extractionStageLabel(status.job_status)}</strong>
 <span>可关闭面板继续其他工作，完成后将自动显示可编辑候选。</span>
 <ol aria-label="提取进度">
 <li className="is-complete"><CheckCircle2 size={14} /> 文件解析</li>
 <li className={status.job_status === "validating" ? "is-complete" : "is-active"}>
 {status.job_status === "validating"
 ? <CheckCircle2 size={14} />
 : <RefreshCw size={14} className="spin" />}
 研究设计提取
 </li>
 <li className={status.job_status === "validating" ? "is-active" : ""}>
 <FileCheck2 size={14} /> 合并核对
 </li>
 </ol>
 </section>
 ) : status.state === "review_pending" && framing && picos ? (
 <div className="legacy-bootstrap-review">
 <section className="legacy-bootstrap-role">
 <div>
 <strong>文件角色</strong>
 <small>系统识别只作为建议；您的选择即为本项目确认。</small>
 </div>
 <select value={confirmedRole} onChange={(event) => setConfirmedRole(event.target.value)}>
 <option value="protocol">完整研究方案</option>
 <option value="synopsis">方案摘要</option>
 </select>
 {roleOverridden && (
 <label>
 <span>调整理由</span>
 <textarea rows={2} value={roleOverrideReason} onChange={(event) => setRoleOverrideReason(event.target.value)} placeholder="说明为何原文件应按所选角色使用；不少于10个字符。" />
 </label>
 )}
 </section>

 <section>
 <header><strong>研究基本信息</strong><small>AI已预填；仅修订不准确处。</small></header>
 <div className="legacy-bootstrap-grid">
 <TextField fieldPath="framing.protocol_id" label="方案号" value={framing.protocol_id} onChange={(value) => updateFraming("protocol_id", value)} />
 <TextField fieldPath="framing.version" label="版本" value={framing.version} onChange={(value) => updateFraming("version", value)} />
 <TextField fieldPath="framing.document_title" wide label="方案标题" value={framing.document_title} onChange={(value) => updateFraming("document_title", value)} />
 <TextField fieldPath="framing.indication" label="适应症" value={framing.indication} onChange={(value) => updateFraming("indication", value)} />
 <TextField fieldPath="framing.study_phase" label="研究分期" value={framing.study_phase} onChange={(value) => updateFraming("study_phase", value)} />
 <TextField fieldPath="framing.investigational_product" label="试验药物" value={framing.investigational_product} onChange={(value) => updateFraming("investigational_product", value)} />
 <TextField fieldPath="framing.target_mechanism" label="靶点/作用机制" value={framing.target_mechanism} onChange={(value) => updateFraming("target_mechanism", value)} />
 <TextField fieldPath="framing.design_pattern" wide multiline label="总体设计" value={framing.design_pattern} onChange={(value) => updateFraming("design_pattern", value)} />
 <TextField fieldPath="framing.population_intent" wide multiline label="目标研究人群" value={framing.population_intent} onChange={(value) => updateFraming("population_intent", value)} />
 </div>
 </section>

 <section>
 <header><strong>PICOS核心设计</strong><small>保留提取的完整结构化对象。</small></header>
 <div className="legacy-bootstrap-grid">
 <TextField fieldPath="picos.population_summary" wide multiline label="研究人群" value={picos.population_summary} onChange={(value) => updatePicos("population_summary", value)} />
 <TextField fieldPath="picos.intervention_summary" wide multiline label="干预措施" value={picos.intervention_summary} onChange={(value) => updatePicos("intervention_summary", value)} />
 <TextField fieldPath="picos.comparator_summary" wide multiline label="对照" value={picos.comparator_summary} onChange={(value) => updatePicos("comparator_summary", value)} />
 <TextField fieldPath="picos.primary_endpoint" wide multiline label="主要终点及评价时间" value={picos.primary_endpoint} onChange={(value) => updatePicos("primary_endpoint", value)} />
 <TextField wide multiline label="方案摘要文本" value={synopsisText} onChange={setSynopsisText} />
 </div>
 </section>

 {status.candidate.conflict_notes?.length > 0 && (
 <section className="legacy-bootstrap-conflicts">
 <header><strong>提取冲突</strong><small>请直接在上方候选中修正；不会作为自动确认事实。</small></header>
 <ul>{status.candidate.conflict_notes.map((item) => <li key={item}>{item}</li>)}</ul>
 </section>
 )}

 {warnings.length > 0 && (
 <section className="legacy-bootstrap-warnings">
 <header><strong>内容校验提示</strong><small>逐项确认后仍可沿用，原提示会持续保留。</small></header>
 {warnings.map((warning) => (
 <label key={warning}>
 <input type="checkbox" checked={acknowledgedWarnings.includes(warning)} onChange={() => toggleWarning(warning)} />
 <span>{warning}</span>
 </label>
 ))}
 <label>
 <span>沿用理由</span>
 <textarea rows={2} value={validationOverrideReason} onChange={(event) => setValidationOverrideReason(event.target.value)} placeholder="说明为何该文件仍可用于当前项目；不少于10个字符。" />
 </label>
 </section>
 )}
 {missingCoreFields.length > 0 && (
 <section className="legacy-bootstrap-missing" role="status">
 <strong>还需补全 {missingCoreFields.length} 项</strong>
 <span>{missingCoreFields.join("、")}</span>
 </section>
 )}
 </div>
 ) : null}

 <footer>
 <span className={message && /失败|错误|变化|冲突/.test(message) ? "danger" : ""}>
 {["review_pending", "confirmed_ready_for_binding"].includes(status.state) ? message : ""}
 </span>
 <div>
 <button type="button" onClick={() => setOpen(false)}>稍后处理</button>
 {status.state === "review_pending" && (
 <button type="button" className="primary-button" onClick={confirmCandidate} disabled={!confirmationReady || Boolean(busy)}>
 <FileCheck2 size={15} /> {busy === "confirm" ? "正在建立" : "确认并建立研究设计"}
 </button>
 )}
 </div>
 </footer>
 </aside>
 </div>
 )}
 </>
 );
}

.phase1-parts-editor {
 min-width: 0;
 display: grid;
 gap: 10px;
 border-top: 1px solid var(--line);
 padding-top: 12px;
}

.phase1-parts-editor > header {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 16px;
}

.phase1-parts-editor > header > div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.phase1-parts-editor > header strong {
 font-size: 13px;
}

.phase1-parts-editor > header span,
.phase1-parts-editor > header small {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.phase1-parts-editor > header button {
 flex: 0 0 auto;
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.phase1-part-selector {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(4, minmax(0, 1fr));
 border: 1px solid var(--line);
 border-radius: 4px;
 overflow: hidden;
 background: #fff;
}

.phase1-part-selector label {
 min-width: 0;
 min-height: 40px;
 display: flex;
 align-items: center;
 gap: 7px;
 border-right: 1px solid var(--soft-line);
 border-bottom: 1px solid var(--soft-line);
 padding: 7px 9px;
 color: var(--muted);
 font-size: 11px;
 cursor: pointer;
}

.phase1-part-selector label:nth-child(4n) {
 border-right: 0;
}

.phase1-part-selector label:nth-last-child(-n + 4) {
 border-bottom: 0;
}

.phase1-part-selector label.selected {
 box-shadow: inset 3px 0 0 var(--brand);
 background: #fff7f2;
 color: var(--text);
 font-weight: 600;
}

.phase1-part-selector input {
 width: auto;
 min-width: 14px;
 margin: 0;
}

.phase1-part-sequence {
 max-width: none;
}

.phase1-part-list {
 min-width: 0;
 display: grid;
 border: 1px solid var(--line);
 border-radius: 4px;
 overflow: hidden;
 background: #fff;
}

.phase1-part-item + .phase1-part-item {
 border-top: 1px solid var(--line);
}

.phase1-part-item > summary {
 min-width: 0;
 min-height: 48px;
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 align-items: center;
 gap: 12px;
 padding: 8px 12px;
 background: #f8f9fa;
 cursor: pointer;
}

.phase1-part-item > summary::marker {
 color: var(--muted);
}

.phase1-part-item > summary > span {
 min-width: 0;
 display: flex;
 align-items: baseline;
 gap: 8px;
}

.phase1-part-item > summary small {
 overflow: hidden;
 color: var(--muted);
 font-size: 10px;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.phase1-part-item > summary > em {
 border-radius: 3px;
 padding: 3px 7px;
 background: #fff1df;
 color: #986019;
 font-size: 10px;
 font-style: normal;
}

.phase1-part-item > summary > em.ready {
 background: #e8f5ec;
 color: #2d7144;
}

.phase1-part-item[open] > summary {
 border-bottom: 1px solid var(--line);
 background: #fff;
}

.phase1-part-fields {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 10px 12px;
 padding: 12px;
}

.phase1-part-fields .phase1-part-label,
.phase1-part-fields .phase1-part-wide {
 grid-column: 1 / -1;
}

.phase1-part-fields textarea {
 min-height: 72px;
 resize: vertical;
}

.phase1-part-empty {
 margin: 0;
 border-left: 3px solid var(--info);
 padding: 8px 10px;
 background: var(--info-bg);
 color: var(--muted);
 font-size: 11px;
 line-height: 1.5;
}

@media (max-width: 1180px) {
 .phase1-part-selector {
 grid-template-columns: repeat(2, minmax(0, 1fr));
 }

 .phase1-part-selector label:nth-child(4n) {
 border-right: 1px solid var(--soft-line);
 }

 .phase1-part-selector label:nth-child(2n) {
 border-right: 0;
 }

 .phase1-part-selector label:nth-last-child(-n + 4) {
 border-bottom: 1px solid var(--soft-line);
 }

 .phase1-part-selector label:nth-last-child(-n + 2) {
 border-bottom: 0;
 }
}

.authoring-population-structure {
 min-width: 0;
 display: grid;
 gap: 8px;
}

