 }),
 }).then(readJson);
 if (activeProjectRef.current !== requestProjectId) return;
 setFactConversation(factConversationFromBackend(response, ""));
 setMessage(response.ai_message?.text || "产品事实已拆解，请采用、修订或拒绝候选。");
 } catch (error) {
 setMessage(`事实采集未完成：${error.message}`);
