 {!selectedDocumentCandidate?.public_documents?.length && !selectedManualArtifacts.length && <div className="writing-reference-empty">该候选研究未发现公开 Protocol，可在上方导入已取得的研究方案原文。</div>}
 </div>
 </div>
 )}
