 chapter_index: 1,
 chapter_total: 1,
 chunk_count: 5,
 chunk_completed: 5,
 generation_status: "candidate_ready",
 pipeline_stage: "candidate_ready",
 pipeline_stage_detail: "翻译完成，可核对并使用",
};

