check(
 panelSource.includes("pipelineStageDetail: String(item.pipeline_stage_detail || \"\")")
 && panelSource.includes('row.generationStatus === "running" && row.pipelineStageDetail'),
 "translation rows retain and prioritize the real pipeline stage detail while running",
);
check(
 journeySource.includes('data-testid="writing-reference-compact-current-progress"')
 && journeySource.includes("{compactProgress.progressCompleted}/{compactProgress.progressTotal}")
 && journeySource.includes("{compactProgress.progressPercent}%")
 && journeySource.includes('data-testid="writing-reference-compact-progressbar"')
 && journeySource.includes('data-testid="writing-reference-full-progressbar"')
 && journeySource.includes('aria-valuenow={compactProgress.progressPercent}'),
 "compact progress always renders the concrete step, completed/total, and percentage",
);

console.log(`progressJourneyLogic: ${passed} passed`);

export function alignedArtifactId(artifacts, currentArtifactId, nctId) {
 const items = Array.isArray(artifacts) ? artifacts : [];
 const currentArtifact = items.find((item) => item.artifact_id === currentArtifactId);
 if (currentArtifact?.nct_id === nctId) return currentArtifactId;
 const nextArtifact = items.find((item) => item.nct_id === nctId && item.source_current)
 || items.find((item) => item.nct_id === nctId);
 return nextArtifact?.artifact_id || "";
}

import assert from "node:assert/strict";
import test from "node:test";

import { alignedArtifactId } from "./referenceIdentity.mjs";

const artifacts = [
 { artifact_id: "artifact-a-old", nct_id: "NCTA", source_current: false },
 { artifact_id: "artifact-a-current", nct_id: "NCTA", source_current: true },
 { artifact_id: "artifact-b", nct_id: "NCTB", source_current: true },
];

test("candidate selection replaces a cross-study artifact with the current study artifact", () => {
 assert.equal(
 alignedArtifactId(artifacts, "artifact-b", "NCTA"),
 "artifact-a-current",
 );
});

test("candidate selection preserves an artifact already bound to the same study", () => {
 assert.equal(
 alignedArtifactId(artifacts, "artifact-a-old", "NCTA"),
 "artifact-a-old",
 );
});

test("candidate selection clears artifact state when the study has no prepared document", () => {
 assert.equal(alignedArtifactId(artifacts, "artifact-b", "NCTC"), "");
});

const ACTIVE_JOB_STATUSES = new Set(["starting", "queued", "running", "resuming"]);
const PIPELINE_ACTIVE_STAGES = new Set(["queued", "triaging"]);
const PIPELINE_FAILURE_STAGES = new Set(["failed", "cancelled"]);

export function triageProgress(run, candidateCount = 0) {
 const chunks = Array.isArray(run?.chunks) ? run.chunks : [];
 const counts = chunks.reduce((result, chunk) => {
 const status = String(chunk?.status || "pending");
 result[status] = (result[status] || 0) + 1;
 return result;
 }, { pending: 0, running: 0, succeeded: 0, failed: 0 });
 const resultCount = chunks
 .filter((chunk) => chunk?.status === "succeeded")
 .reduce((sum, chunk) => sum + (Array.isArray(chunk?.results) ? chunk.results.length : 0), 0);
 const totalCandidates = chunks.reduce(
 (sum, chunk) => sum + (Array.isArray(chunk?.nct_ids) ? chunk.nct_ids.length : 0),
 0,
 ) || Number(candidateCount || 0);

 return {
 ...counts,
 totalChunks: chunks.length,
 completedChunks: counts.succeeded + counts.failed,
 resultCount,
 totalCandidates,
 };
}

export function mergeTriageSelections(current, results, { reset = false } = {}) {
 const next = reset ? {} : { ...(current || {}) };
 for (const result of Array.isArray(results) ? results : []) {
 const nctId = String(result?.nct_id || "").trim();
 const classification = String(result?.classification || "").trim();
 if (!nctId || !classification) continue;
 if (reset || !next[nctId]) next[nctId] = classification;
 }
 return next;
}

function pipelineMatchesRun(pipeline, run, snapshotId) {
 if (!pipeline || typeof pipeline !== "object") return false;
 if (snapshotId && pipeline.snapshot_id && pipeline.snapshot_id !== snapshotId) return false;
 if (run?.run_id && pipeline.triage_run_id && pipeline.triage_run_id !== run.run_id) return false;
 return true;
}

function conciseFailureDetail({ run, jobStatus, pipeline, pipelineRelevant, progress }) {
 if (pipelineRelevant && PIPELINE_FAILURE_STAGES.has(pipeline?.stage)) {
 const raw = String(pipeline?.error_summary || "");
 if (raw.includes("分诊超时")) return "分诊未在预期时间内完成";
 return String(pipeline?.detail || "分诊未完成").trim();
 }
 if (jobStatus === "cancelled") return "本次分诊已取消";
 if (jobStatus === "failed") return "后台分诊任务未完成";
 if (run?.error_message) return String(run.error_message).trim();
 if (progress.failed) return `${progress.failed} 个分诊批次未完成`;
 return "分诊未完成";
}

/**
 * Convert the persisted business run, durable job, and parent pipeline into a
 * small operator-facing state. No timeout is inferred locally: a terminal
 * failure is only surfaced when one of the APIs reports it.
 */
export function deriveTriagePresentation({ run, jobStatus = "", hasActiveJob = false, pipeline = null, snapshotId = "", candidateCount = 0 } = {}) {
 const progress = triageProgress(run, candidateCount);
 const runStatus = String(run?.status || "");
 const pipelineRelevant = pipelineMatchesRun(pipeline, run, snapshotId);
 const pipelineStage = pipelineRelevant ? String(pipeline?.stage || "") : "";
 // A retry receives a fresh durable job before the parent pipeline has a
 // reason to clear its earlier failure. The new job is the current authority
 // during that interval; without it the UI would immediately re-report the
 // old parent failure and stop its own refresh loop.
 const hasTerminalPipelineFailure = PIPELINE_FAILURE_STAGES.has(pipelineStage) && !hasActiveJob;
 const hasTerminalJobFailure = jobStatus === "failed" || jobStatus === "cancelled";

 if (runStatus === "confirmed") {
 return { kind: "confirmed", progress, retryable: false, message: "分诊结果已确认并锁定。" };
 }
 if (runStatus === "projection_pending") {
 return { kind: "projection_pending", progress, retryable: false, message: "分诊已确认，正在同步到写作旅程。" };
 }
 if (runStatus === "review_ready") {
 return { kind: "review_ready", progress, retryable: false, message: `AI建议已就绪，共 ${progress.resultCount}/${progress.totalCandidates} 项，确认前可逐项微调。` };
 }
 if (runStatus === "stale") {
 return { kind: "stale", progress, retryable: false, message: "项目框架或检索结果已更新，请按当前信息重新分诊。" };
 }

 const failed = runStatus === "failed"
 || runStatus === "partial_failed"
 || hasTerminalJobFailure
 || hasTerminalPipelineFailure;
 if (failed) {
 return {
 kind: "failed",
 progress,
 retryable: Boolean(run?.run_id),
 message: `${conciseFailureDetail({ run, jobStatus, pipeline, pipelineRelevant, progress })}。可直接重试当前分诊。`,
 };
 }

 const running = runStatus === "queued"
 || runStatus === "running"
 || ACTIVE_JOB_STATUSES.has(jobStatus)
 || (pipelineRelevant && PIPELINE_ACTIVE_STAGES.has(pipelineStage));
 if (running) {
 const progressText = progress.totalChunks
 ? `已完成 ${progress.completedChunks}/${progress.totalChunks} 个分诊批次${progress.totalCandidates ? `；已返回 ${progress.resultCount}/${progress.totalCandidates} 项建议` : ""}`
 : "正在读取分诊任务";
 return { kind: "running", progress, retryable: false, message: `${progressText}。` };
 }

 return { kind: "idle", progress, retryable: false, message: "" };
}

import assert from "node:assert/strict";
import {
 deriveTriagePresentation,
 mergeTriageSelections,
 triageProgress,
} from "./triagePresentationState.mjs";

let passed = 0;
function check(condition, message) {
 assert.ok(condition, message);
 passed += 1;
}

const queuedRun = {
 run_id: "run-1",
 snapshot_id: "snapshot-1",
 status: "queued",
 chunks: [
 { chunk_id: "c1", status: "succeeded", nct_ids: ["NCT1", "NCT2"], results: [{ nct_id: "NCT1" }, { nct_id: "NCT2" }] },
 { chunk_id: "c2", status: "running", nct_ids: ["NCT3"], results: [] },
 { chunk_id: "c3", status: "pending", nct_ids: ["NCT4"], results: [] },
 ],
};

const progress = triageProgress(queuedRun, 4);
check(progress.totalChunks === 3, "reports total chunks from persisted run");
check(progress.completedChunks === 1 && progress.resultCount === 2, "reports completed chunks and returned candidates");
check(progress.totalCandidates === 4, "reports persisted candidate coverage");

const incrementalSelections = mergeTriageSelections(
 { NCT1: "indirect_reference" },
 [
 { nct_id: "NCT1", classification: "excluded" },
 { nct_id: "NCT2", classification: "direct_competitor" },
 ],
);
check(
 incrementalSelections.NCT1 === "indirect_reference",
 "preserves a medical writer override when the same run gains another chunk",
);
check(
 incrementalSelections.NCT2 === "direct_competitor",
 "adds classifications that arrive in a later chunk of the same run",
);
const resetSelections = mergeTriageSelections(
 { OLD: "excluded", NCT1: "indirect_reference" },
 [{ nct_id: "NCT1", classification: "excluded" }],
 { reset: true },
);
check(
 Object.keys(resetSelections).length === 1 && resetSelections.NCT1 === "excluded",
 "replaces selections when a new triage run is adopted",
);

const running = deriveTriagePresentation({
 run: queuedRun,
 jobStatus: "running",
 snapshotId: "snapshot-1",
 candidateCount: 4,
});
check(running.kind === "running", "keeps a normal queued/running run active");
check(!running.retryable, "does not expose retry during a normal active run");
check(running.message.includes("2/4 项建议"), "shows returned candidate coverage while the run is active");

const pipelineFailure = deriveTriagePresentation({
 run: queuedRun,
 jobStatus: "failed",
 snapshotId: "snapshot-1",
 pipeline: {
 stage: "failed",
 snapshot_id: "snapshot-1",
 triage_run_id: "run-1",
 error_summary: "分诊超时",
 },
 candidateCount: 4,
});
check(pipelineFailure.kind === "failed", "surfaces real parent pipeline failure even when run remains queued");
check(pipelineFailure.retryable, "allows same-run recovery after terminal failure");
check(pipelineFailure.message.includes("未在预期时间内完成"), "turns the API timeout into concise operator-facing language");

const unrelatedPipeline = deriveTriagePresentation({
 run: queuedRun,
 jobStatus: "queued",
 snapshotId: "snapshot-1",
 pipeline: { stage: "failed", snapshot_id: "older-snapshot", triage_run_id: "old-run", error_summary: "旧错误" },
});
check(unrelatedPipeline.kind === "running", "does not leak an older pipeline failure into the current snapshot");

const activeRetry = deriveTriagePresentation({
 run: { ...queuedRun, status: "running" },
 jobStatus: "queued",
 hasActiveJob: true,
 snapshotId: "snapshot-1",
 pipeline: { stage: "failed", snapshot_id: "snapshot-1", triage_run_id: "run-1", error_summary: "旧的超时记录" },
});
check(activeRetry.kind === "running", "a newly accepted retry takes precedence over the parent’s previous failure");

const reviewReady = deriveTriagePresentation({
 run: { ...queuedRun, status: "review_ready" },
 jobStatus: "completed",
 snapshotId: "snapshot-1",
 candidateCount: 4,
});
check(reviewReady.kind === "review_ready" && !reviewReady.retryable, "preserves normal review-ready path");

const confirmedWithAdvancingPipeline = deriveTriagePresentation({
 run: { ...queuedRun, status: "confirmed" },
 jobStatus: "completed",
 snapshotId: "snapshot-1",
 pipeline: { stage: "preparing", snapshot_id: "snapshot-1", triage_run_id: "run-1" },
 candidateCount: 4,
});
check(confirmedWithAdvancingPipeline.kind === "confirmed", "confirmed run stays confirmed even when parent pipeline has advanced past the confirm gate");

const confirmedWithOldAwaitingPipeline = deriveTriagePresentation({
 run: { ...queuedRun, status: "confirmed" },
 jobStatus: "completed",
 snapshotId: "snapshot-1",
 pipeline: { stage: "awaiting_triage_confirm", snapshot_id: "snapshot-1", triage_run_id: "run-1" },
 candidateCount: 4,
});
check(confirmedWithOldAwaitingPipeline.kind === "confirmed", "confirmed run stays confirmed even when parent pipeline still shows awaiting_triage_confirm (stale)");

console.log(`triagePresentationState: ${passed} passed`);

