 padding: 12px;
}

.ai-role-nav button {
 display: grid;
 gap: 3px;
 width: 100%;
 border: 1px solid transparent;
 border-radius: 4px;
 background: transparent;
 padding: 10px;
 text-align: left;
}

.ai-role-nav button:hover {
