 background: #fff7ef;
 box-shadow: inset 3px 0 0 #cf6c22;
}

.ai-role-nav span {
 color: #26313a;
 font-size: 13px;
 font-weight: 700;
}

.ai-role-nav small {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
 overflow-wrap: anywhere;
}

.ai-role-editor {
 min-width: 0;
 padding: 18px;
}

.ai-role-editor-heading {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 16px;
 margin-bottom: 14px;
}

.ai-role-editor-heading > div {
 display: grid;
 gap: 4px;
 min-width: 0;
}

.ai-role-editor-heading strong {
 font-size: 15px;
}

.ai-role-editor-heading span {
 color: var(--muted);
 font-size: 12px;
 line-height: 1.55;
}

.ai-role-blocker,
.ai-role-warning {
 margin: 0 0 12px;
 border-left: 3px solid #d9822b;
 background: #fff8ef;
 padding: 8px 10px;
 color: #75451b;
 font-size: 12px;
 line-height: 1.5;
}

.ai-role-warning {
 border-left-color: #4d78b8;
 background: #f4f7fb;
 color: #365783;
}

.ai-settings-dialog > footer button {
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.ai-settings-grid {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: 14px 16px;
 padding: 0;
}

.ai-settings-grid label {
 display: grid;
 gap: 6px;
 min-width: 0;
}

.ai-settings-grid label.wide {
 grid-column: 1 / -1;
}

.ai-settings-grid label > span {
 color: #4d5965;
 font-size: 12px;
 font-weight: 700;
}

.ai-model-inventory {
 color: #66727d;
 font-size: 11px;
 line-height: 1.45;
 overflow-wrap: anywhere;
}

.ai-settings-grid input,
.ai-settings-grid select {
 width: 100%;
 min-height: 38px;
 border: 1px solid #cfd6dd;
 border-radius: 4px;
 background: #fff;
 padding: 7px 10px;
 color: #27313a;
}

.ai-settings-grid input:focus,
.ai-settings-grid select:focus {
 border-color: #cb681f;
 outline: 2px solid rgba(203, 104, 31, 0.12);
 outline-offset: 0;
}

.ai-settings-boundary,
.ai-settings-notice {
 margin: 0 18px 14px;
 color: var(--muted);
 font-size: 12px;
 line-height: 1.6;
}

.ai-settings-notice {
 color: #704018;
 border-left: 3px solid #e3a15e;
 padding-left: 9px;
}

.module-list,
.task-list {
 display: grid;
 gap: 6px;
}

.module-row,
.task-row,
.candidate-row,
.approval-list button,
.section-tree button {
 width: 100%;
 min-height: 44px;
 border: 1px solid var(--soft-line);
 background: #fff;
 border-radius: 4px;
 display: grid;
 align-items: center;
 gap: 8px;
 text-align: left;
}

.module-row {
 grid-template-columns: minmax(120px, 1fr) 120px 18px;
 padding: 8px;
}

.module-row > div:first-child {
 display: flex;
 flex-direction: column;
 min-width: 0;
}

.module-row span {
 color: var(--muted);
 font-size: 12px;
}

.progress {
 height: 22px;
 display: grid;
 grid-template-columns: 1fr 38px;
 align-items: center;
 gap: 6px;
}

.progress span {
 height: 6px;
 background: var(--orange);
 border-radius: 4px;
}

.progress em {
 font-size: 12px;
 color: var(--muted);
 font-style: normal;
 text-align: right;
}

.heatmap {
 display: grid;
 gap: 6px;
}

.heat-row {
 display: grid;
 grid-template-columns: 58px repeat(5, minmax(54px, 1fr));
 gap: 4px;
 align-items: center;
}

.heat-row > span {
 color: var(--muted);
 font-size: 12px;
}

.heat-cell {
 min-height: 48px;
 border: 1px solid var(--line);
 border-radius: 4px;
 display: grid;
 align-content: center;
 gap: 2px;
 background: #f6fbf8;
 color: var(--text);
}

.heat-cell b {
 font-size: 11px;
 white-space: normal;
 line-height: 1.25;
}

.heat-cell em {
 font-style: normal;
 font-weight: 700;
}

.heat-cell.level-1 {
 background: #fff8e8;
 border-color: #ffdfad;
}

.heat-cell.level-2 {
 background: #fff1ec;
 border-color: #ffccb8;
}

.heat-cell.level-3 {
 background: #fff0f0;
 border-color: #ffc9c9;
 color: var(--danger);
}

.heatmap-note {
 margin-top: 10px;
 display: grid;
 gap: 4px;
 color: var(--muted);
 font-size: 12px;
}

.heatmap-note p,
.empty-unread {
 margin: 0;
}

.empty-unread {
 padding: 14px;
 color: var(--muted);
 font-size: 13px;
}

.risk-severity-summary {
 display: grid;
 grid-template-columns: repeat(4, minmax(0, 1fr));
 gap: 8px;
 margin-bottom: 12px;
}

.risk-severity-summary > button {
 min-height: 84px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 padding: 10px;
 display: grid;
 grid-template-columns: 1fr auto;
 align-items: center;
 text-align: left;
}

.risk-severity-summary > button strong {
 font-size: 24px;
}

.risk-severity-summary > button span:last-child {
 grid-column: 1 / -1;
 color: var(--muted);
 font-size: 12px;
}

.task-row {
 grid-template-columns: 42px minmax(0, 1fr) 82px 72px;
 padding: 7px 8px;
}

.task-row > strong,
.task-row > span {
 min-width: 0;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.inbox-boundary-note {
 margin: 10px 12px 12px;
 color: var(--muted);
 font-size: 12px;
 line-height: 1.6;
}

.inbox-scope-note {
 margin: 7px 12px 8px;
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.source-health-list,
.handoff-list {
 display: grid;
 gap: 6px;
 margin-bottom: 12px;
}

.source-health-row,
.handoff-row {
 width: 100%;
 min-height: 54px;
 border: 1px solid var(--soft-line);
 background: #fff;
 border-radius: 4px;
 padding: 8px;
 display: grid;
 grid-template-columns: 112px minmax(0, 1fr);
 gap: 4px 8px;
 text-align: left;
 align-items: start;
}

.source-health-row strong,
.source-health-row small,
.handoff-row strong,
.handoff-row small {
 min-width: 0;
 overflow: hidden;
 text-overflow: ellipsis;
}

.source-health-row strong,
.handoff-row strong {
 white-space: nowrap;
}

.source-health-row small,
.handoff-row small {
 grid-column: 2;
 color: var(--muted);
 line-height: 1.35;
 display: -webkit-box;
 -webkit-line-clamp: 2;
 -webkit-box-orient: vertical;
}

.monitoring-command-surface {
 display: grid;
 gap: 0;
 margin-bottom: 12px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 overflow: hidden;
}

.monitoring-project-strip {
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(260px, 0.9fr) minmax(540px, 1.8fr) minmax(240px, auto);
 align-items: stretch;
}

.monitoring-project-identity {
 min-width: 0;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr) auto;
 align-items: center;
 gap: 10px;
 padding: 10px 12px;
 border-left: 3px solid #526e5d;
 border-right: 1px solid var(--soft-line);
}

.monitoring-project-identity > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.monitoring-project-identity span,
.monitoring-project-identity small {
 color: var(--muted);
 font-size: 11px;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.monitoring-project-identity strong {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.monitoring-project-facts {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(6, minmax(86px, 1fr));
 align-items: stretch;
}

.monitoring-project-facts > div {
 min-width: 0;
 display: grid;
 align-content: center;
 gap: 2px;
 padding: 8px 10px;
 border-right: 1px solid var(--soft-line);
}

.monitoring-project-facts strong {
 font-size: 16px;
}

.monitoring-project-facts span {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.35;
}

.monitoring-scope-control {
 min-width: 255px;
 display: grid;
 align-content: center;
 justify-items: end;
 gap: 5px;
 padding: 8px 12px;
}

.monitoring-scope-control > span {
 color: var(--muted);
 font-size: 11px;
}

.monitoring-boundary-note {
 display: flex;
 align-items: baseline;
 gap: 8px 14px;
 margin-top: 10px;
 padding: 8px 2px 2px;
 border-top: 1px solid var(--soft-line);
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.monitoring-boundary-note strong {
 flex: none;
 color: var(--text-secondary);
}

.monitoring-structure-warning {
 display: flex;
 align-items: flex-start;
 gap: 9px;
 margin-top: 10px;
 padding: 9px 11px;
 border: 1px solid #e7b45a;
 border-left: 3px solid var(--orange);
 border-radius: 4px;
 background: #fffaf0;
 color: var(--text-secondary);
}

.monitoring-structure-warning > svg {
 flex: none;
 margin-top: 1px;
 color: var(--orange);
}

.monitoring-structure-warning > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.monitoring-structure-warning strong {
 color: var(--text);
 font-size: 12px;
}

.monitoring-structure-warning span,
.monitoring-structure-warning small {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
 overflow-wrap: anywhere;
}

.monitoring-structure-warning-action {
 justify-self: start;
 margin-top: 4px;
 padding: 3px 8px;
 border: 1px solid #d79a2f;
 border-radius: 4px;
 background: #fffdf8;
 color: #8b5a08;
 font-size: 11px;
 font-weight: 600;
 line-height: 1.35;
 cursor: pointer;
}

.monitoring-structure-warning-action:hover,
.monitoring-structure-warning-action:focus-visible {
 border-color: #a96c0c;
 background: #fff3d6;
 color: #6f4605;
}

.batch-box,
.mapping-alert,
.filter-strip {
 border: 1px solid var(--line);
 background: var(--surface);
 border-radius: 4px;
 min-height: 48px;
 display: flex;
 align-items: center;
 gap: 10px;
 padding: 8px 10px;
}

.batch-box div {
 display: grid;
}

.batch-box span,
.trend-note {
 color: var(--muted);
 font-size: 12px;
}

.mapping-alert {
 color: var(--warning);
 background: var(--warning-bg);
 border-color: #ffd99d;
}

.filter-strip {
 flex-wrap: wrap;
}

.upload-gate {
 margin-bottom: 12px;
}

.monitoring-batch-panel {
 margin-bottom: 12px;
 padding: 0;
 overflow: hidden;
}

.monitoring-batch-panel-head {
 min-height: 48px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 padding: 8px 12px;
 border-bottom: 1px solid var(--line);
}

.monitoring-batch-panel-head > div:first-child {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.monitoring-batch-panel-head span,
.monitoring-batch-upload span,
.monitoring-batch-summary span,
.monitoring-batch-action span,
.monitoring-batch-action small {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.4;
}

.monitoring-batch-workspace {
 display: grid;
 gap: 10px;
 padding: 12px;
}

.monitoring-batch-upload {
 display: grid;
 grid-template-columns: auto minmax(260px, 1fr) auto;
 align-items: center;
 gap: 10px;
 padding-bottom: 10px;
 border-bottom: 1px solid var(--soft-line);
}

.monitoring-batch-upload > input {
 display: none;
}

.monitoring-batch-upload > button:first-of-type {
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.monitoring-batch-upload > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.monitoring-batch-upload strong {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.monitoring-batch-list {
 display: flex;
 align-items: center;
 gap: 6px;
 min-height: 36px;
 overflow-x: auto;
}

.monitoring-batch-list > button {
 flex: none;
 min-width: 240px;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr) auto;
 align-items: center;
 gap: 7px;
 padding: 7px 9px;
 border: 1px solid var(--line);
 background: #fff;
}

.monitoring-batch-list > button.active {
 border-color: #d58a43;
 box-shadow: inset 3px 0 0 #d66f19;
}

.monitoring-batch-list > button > span:nth-child(2) {
 min-width: 0;
 overflow: hidden;
 color: var(--text-secondary);
 text-overflow: ellipsis;
 white-space: nowrap;
}

.monitoring-batch-empty {
