 color: var(--brand);
 font-weight: 800;
}

.risk-checklist-table {
 width: 100%;
 overflow-x: auto;
 background: #fff;
}

.risk-checklist-column-state {
 min-height: 34px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
 padding: 4px 10px;
 border-bottom: 1px solid var(--soft-line);
 color: var(--muted);
 font-size: 11px;
}

.risk-checklist-actions {
