 align-items: center;
 gap: 6px;
}

.risk-checklist-actions .icon-button {
 width: 34px;
 min-width: 34px;
 height: 34px;
}

.risk-checklist-header,
.risk-checklist-row {
 min-width: 1120px;
 display: grid;
 grid-template-columns: 118px 92px 94px 188px minmax(320px, 1fr) 152px 156px;
 align-items: stretch;
}

.risk-checklist-header {
