 grid-template-columns: minmax(0, 1fr) 30px;
 align-items: stretch;
 border-right: 1px solid var(--soft-line);
}

.risk-checklist-sort,
.risk-checklist-filter-trigger {
 min-width: 0;
 border: 0;
 background: transparent;
 color: inherit;
 display: flex;
 align-items: center;
 font: inherit;
}

.risk-checklist-sort {
 padding: 0 4px 0 9px;
 justify-content: space-between;
 gap: 5px;
 text-align: left;
}

.risk-checklist-filter-trigger {
