 gap: 8px;
 color: var(--text);
 font-size: 12px;
 font-weight: 500;
}

.risk-checklist-header-cell:nth-child(n + 6) .risk-checklist-filter-popover {
 right: 6px;
 left: auto;
}

.risk-checklist-filter-popover > strong {
 font-size: 12px;
}

.risk-checklist-filter-popover input,
.risk-checklist-filter-popover select {
 width: 100%;
 min-width: 0;
 height: 32px;
 border: 1px solid var(--line);
 border-radius: 4px;
