 background: #fffaf1;
}

.risk-checklist-stale button {
 min-height: 26px;
 padding: 0 8px;
 border: 1px solid #e7c98d;
 border-radius: 4px;
 background: #fff;
 color: #7b541f;
 display: inline-flex;
 align-items: center;
 gap: 5px;
}

.risk-checklist-error {
 color: var(--danger);
 background: var(--danger-bg);
}

.risk-checklist-error button {
 min-height: 26px;
 padding: 0 8px;
 border: 1px solid #e2b6b6;
 border-radius: 4px;
 background: #fff;
 color: var(--danger);
 display: inline-flex;
 align-items: center;
 gap: 5px;
 white-space: nowrap;
}

.risk-checklist-row > span {
 min-width: 0;
 padding: 8px;
 border-right: 1px solid var(--soft-line);
 display: flex;
 align-items: center;
 gap: 4px;
 overflow-wrap: anywhere;
}

.risk-checklist-row {
 min-height: 52px;
 border-bottom: 1px solid var(--soft-line);
 color: var(--text);
 font-size: 12px;
 cursor: pointer;
}

.risk-checklist-row:hover,
.risk-checklist-row.selected {
 background: #fff8f3;
}

.risk-checklist-row:focus-visible {
 outline: 2px solid var(--brand);
 outline-offset: -2px;
}

.risk-category-cell,
.risk-title-cell {
 align-content: center;
