.risk-evidence-stage.protocol { border-left: 4px solid #7d8fb0; }
.risk-evidence-stage.rule { border-left: 4px solid #b1864d; }
.risk-evidence-stage.locator { border-left: 4px solid #aebbc2; background: #f8fafb; }

