 min-height: 98px;
 border: 0;
 border-bottom: 1px solid var(--soft-line);
 background: #fff;
 color: var(--text);
 padding: 12px;
 display: grid;
 gap: 8px;
 text-align: left;
}

.risk-card-row:hover,
.risk-card-row.selected {
 background: #fff8f3;
}

.risk-card-title,
.risk-card-meta {
 display: flex;
 align-items: center;
 gap: 8px;
 min-width: 0;
}

.risk-card-title {
 justify-content: space-between;
}

.risk-card-title strong {
 min-width: 0;
 white-space: normal;
 line-height: 1.35;
}

.risk-card-meta {
 flex-wrap: wrap;
 color: #3b4650;
}

.risk-card-meta span {
 min-height: 22px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 2px 7px;
 background: #fbfcfd;
 font-size: 12px;
}

.risk-card-source {
 color: var(--muted);
 font-size: 12px;
}

.risk-detail {
 min-height: 430px;
 border-color: #ffd9c2;
}

.risk-meta,
.button-row,
.rail-tabs,
.approval-meta {
 display: flex;
 flex-wrap: wrap;
 gap: 7px;
 align-items: center;
}

.evidence-chain,
.checklist,
.query-box,
.subject-shortcut,
.full-draft-panel,
.revision-form,
.revision-thread-list,
.revision-thread,
.export-gate {
 margin-top: 12px;
 border-top: 1px solid var(--soft-line);
 padding-top: 10px;
}

.evidence-chain h3,
.checklist h3,
.query-box h3,
.full-draft-panel h3,
.revision-form h3,
.revision-thread-list h3,
.revision-thread h3,
.export-gate h3 {
 margin: 0 0 7px;
 font-size: 14px;
}

.full-draft-panel {
 margin-top: 12px;
 border: 1px solid #b8d9cd;
 border-radius: 10px;
 padding: 12px;
 background: linear-gradient(145deg, #f4fbf8 0%, #ffffff 72%);
}

.full-draft-panel-head {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 10px;
}

.full-draft-panel-head > div {
 display: grid;
 gap: 5px;
}

.full-draft-panel-head > span {
 color: #26705a;
 font-size: 12px;
 font-weight: 800;
}

.full-draft-panel > p {
 margin: 8px 0;
 color: var(--muted);
 font-size: 12px;
 line-height: 1.55;
}

.full-draft-review-list {
 display: grid;
 gap: 8px;
 max-height: 420px;
 overflow: auto;
 margin: 10px 0;
 padding-right: 3px;
}

.full-draft-review-item {
 border: 1px solid #d7e8e1;
 border-radius: 8px;
 padding: 9px 10px;
 background: #fff;
}

.full-draft-review-item-head {
 display: flex;
 align-items: baseline;
 justify-content: space-between;
 gap: 8px;
 color: #195d4b;
 font-size: 12px;
}

.full-draft-review-item-head span {
 flex: 0 0 auto;
 color: var(--muted);
 font-size: 11px;
}

.full-draft-review-item p {
 margin: 7px 0 5px;
 color: var(--ink);
 font-size: 12px;
 line-height: 1.65;
 white-space: pre-wrap;
}

.full-draft-review-item small {
 display: block;
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.disposition-steps {
 display: flex;
 flex-wrap: wrap;
 gap: 6px;
 margin-bottom: 10px;
}

.disposition-step {
 min-height: 24px;
 display: inline-flex;
 align-items: center;
}

.disposition-step.current {
 font-weight: 800;
}

.disposition-field {
 display: grid;
 gap: 5px;
 margin: 8px 0;
 color: var(--muted);
 font-size: 12px;
 font-weight: 700;
}

.disposition-field textarea {
 min-height: 74px;
 font-size: 13px;
 line-height: 1.5;
}

.disposition-field select {
 min-height: 34px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
 padding: 0 9px;
 font: inherit;
}

.evidence-chain p,
.revision-form p,
.revision-thread p,
.export-gate p,
.risk-list p {
 margin: 6px 0;
 color: #37414b;
}

.revision-form,
.revision-thread {
 display: grid;
 gap: 8px;
}

.revision-form label,
.revision-thread label {
 display: grid;
 gap: 5px;
 color: var(--muted);
 font-size: 12px;
 font-weight: 700;
}

.revision-form select,
.revision-form textarea,
.revision-thread textarea {
 width: 100%;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 padding: 8px;
 color: var(--ink);
 font: inherit;
 font-size: 13px;
}

.revision-form textarea,
.revision-thread textarea {
 min-height: 78px;
 resize: vertical;
}

.revision-form .selected-text {
 display: grid;
 gap: 4px;
 color: #5d6470;
 font-size: 12px;
 line-height: 1.5;
 overflow-wrap: anywhere;
}

.revision-message,
.revision-boundary-line {
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #f7f8fa;
 padding: 8px;
 color: var(--muted);
 font-size: 12px;
 line-height: 1.5;
}

.revision-progress {
 display: grid;
 gap: 6px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 padding: 9px 10px;
 color: var(--ink);
 font-size: 12px;
}

.revision-progress > div:first-child {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
}

.revision-progress strong {
 min-width: 0;
 overflow-wrap: anywhere;
 font-weight: 650;
}

.revision-progress small {
 color: var(--muted);
}

.revision-progress-track {
 height: 5px;
 overflow: hidden;
 border-radius: 3px;
 background: #edf0f3;
}

.revision-progress-track > span {
 display: block;
 height: 100%;
 background: var(--orange);
 transition: width 180ms ease-out;
}

.revision-thread-head {
 display: flex;
 justify-content: space-between;
 gap: 8px;
 align-items: center;
}

.revision-thread-list {
 display: grid;
 gap: 6px;
}

.revision-thread-list > button {
 min-width: 0;
 justify-content: space-between;
 grid-template-columns: minmax(0, 1fr) auto;
 border-color: var(--line);
 background: #fff;
}

.revision-thread-list > button.active {
 border-color: var(--orange);
 background: #fff8f3;
}

.revision-ledger-head {
 display: flex;
 justify-content: space-between;
 gap: 10px;
 align-items: flex-start;
}

.revision-ledger-head h3,
.revision-ledger-head p {
 margin: 0;
}

.revision-ledger-head p,
.revision-ledger-head > span {
 color: var(--muted);
 font-size: 12px;
}

.revision-ledger-head > span {
 white-space: nowrap;
 font-weight: 700;
}

.revision-turn-ledger {
 display: grid;
 gap: 8px;
 max-height: 520px;
 overflow-y: auto;
 padding-right: 3px;
}

.revision-turn {
 min-width: 0;
 border: 1px solid var(--line);
 border-left: 3px solid #a9b2bc;
 border-radius: 4px;
 background: #fff;
}

.revision-turn.current {
 border-left-color: var(--orange);
 background: #fffaf6;
}

.revision-turn > header,
.revision-turn > footer {
 display: flex;
 justify-content: space-between;
 gap: 8px;
 align-items: center;
 padding: 7px 9px;
}

.revision-turn > header {
 border-bottom: 1px solid var(--soft-line);
}

.revision-turn > header > div {
 min-width: 0;
 display: flex;
 gap: 8px;
 align-items: baseline;
}

.revision-turn > header strong {
 font-size: 13px;
}

.revision-turn > header span,
.revision-turn > footer span {
 color: var(--muted);
 font-size: 11px;
 overflow-wrap: anywhere;
}

.revision-turn-grid {
 display: grid;
 grid-template-columns: minmax(0, 0.78fr) minmax(0, 1.22fr);
}

.revision-turn-request,
.revision-turn-candidate {
 min-width: 0;
 display: grid;
 align-content: start;
 gap: 4px;
 padding: 9px;
}

.revision-turn-request {
 border-right: 1px solid var(--soft-line);
 background: #fbfcfd;
}

.revision-turn-request > span,
.revision-turn-candidate > span {
 color: var(--muted);
 font-size: 11px;
 font-weight: 800;
}

.revision-turn-request p,
.revision-turn-candidate p {
 margin: 0 0 5px;
 color: var(--ink);
 font-size: 12px;
 line-height: 1.48;
 overflow-wrap: anywhere;
}

.table-cell-revision-diff {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 6px;
}

.table-cell-revision-diff > div {
 min-width: 0;
 border: 1px solid var(--soft-line);
 padding: 7px;
 background: #fbfcfd;
}

.table-cell-revision-diff > div:last-child {
 border-color: #e7b58f;
 background: #fffaf6;
}

.table-cell-revision-diff span {
 display: block;
 margin-bottom: 4px;
 color: var(--muted);
 font-size: 10px;
 font-weight: 800;
}

.revision-local-diff,
.revision-impact-panel {
 display: grid;
 gap: 5px;
 margin: 3px 0 7px;
 border: 1px solid var(--soft-line);
 padding: 7px;
 background: #fbfcfd;
}

.revision-local-diff > span,
.revision-impact-panel > span {
 color: var(--muted);
 font-size: 10px;
 font-weight: 800;
}

.revision-local-diff-text {
 white-space: pre-wrap;
 overflow-wrap: anywhere;
 font-size: 12px;
 line-height: 1.55;
}

.revision-local-diff-text mark {
 padding: 1px 2px;
 color: inherit;
}

.revision-diff-equal {
 background: transparent;
}

.revision-diff-delete {
 background: #ffe2e0;
 color: #9f2f27;
 text-decoration: line-through;
}

.revision-diff-insert {
 background: #dff5e6;
 color: #176b38;
}

.revision-local-diff small,
.revision-impact-panel small {
 color: var(--muted);
 font-size: 10px;
}

.revision-impact-panel.unresolved {
 border-color: #e7b58f;
 background: #fffaf6;
}

.revision-impact-panel p {
 margin: 0;
 font-size: 11px;
}

.revision-impact-panel ul {
 display: grid;
 gap: 4px;
 margin: 0;
 padding-left: 15px;
}

.revision-impact-panel li {
 display: grid;
 gap: 1px;
 font-size: 11px;
}

.revision-impact-panel li span {
 color: var(--ink);
}

.revision-impact-panel li small {
 overflow-wrap: anywhere;
}

.revision-impact-downstream strong {
 color: #a15e12;
}

.revision-impact-unresolved strong {
 color: #9f2f27;
}

.revision-protected-token-panel {
 display: grid;
 gap: 5px;
 margin: 3px 0 7px;
 border: 1px solid #b7d2c0;
 padding: 7px;
 background: #f5fbf7;
}

.revision-protected-token-panel > span {
 color: #35734b;
 font-size: 10px;
 font-weight: 800;
}

.revision-protected-token-panel p {
 margin: 0;
 font-size: 11px;
}

.revision-protected-token-panel ul {
 display: grid;
 gap: 4px;
 margin: 0;
 padding-left: 15px;
}

.revision-protected-token-panel li {
 display: grid;
 gap: 1px;
 font-size: 11px;
}

.revision-protected-token-panel li span {
 color: var(--ink);
}

.revision-protected-token-panel.unresolved {
 border-color: #e7b58f;
 background: #fffaf6;
}

.revision-protected-token-panel.unresolved > span {
 color: #a15e12;
}

.revision-protected-token-panel.violated {
 border-color: #e0aaa6;
 background: #fff5f4;
}

.revision-protected-token-panel.violated > span,
.revision-protected-token-panel.violated li strong {
 color: #9f2f27;
}

.revision-turn > footer {
 justify-content: flex-start;
 flex-wrap: wrap;
 border-top: 1px solid var(--soft-line);
 background: #fbfcfd;
}

.revision-current-action {
 display: grid;
 gap: 8px;
 border-top: 1px solid var(--soft-line);
 padding-top: 9px;
}

.revision-current-action > strong {
 font-size: 13px;
}

.revision-current-action textarea {
 min-height: 66px;
}

.revision-application-band {
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 gap: 10px;
 align-items: center;
 border: 1px solid var(--line);
 border-left: 3px solid var(--orange);
 border-radius: 4px;
 background: #fffaf6;
 padding: 10px;
}

.revision-application-band > div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.revision-application-band strong {
 font-size: 13px;
}

.revision-application-band span {
 color: var(--muted);
 font-size: 12px;
 line-height: 1.45;
 overflow-wrap: anywhere;
}

.revision-application-band.pending {
 border-left-color: #d68a15;
 background: var(--warning-bg);
}

.revision-application-band.needs-write-retry {
 border-left-color: #d68a15;
 background: #fffaf2;
}

.revision-application-band.applied {
 border-left-color: var(--success);
 background: var(--success-bg);
}

.revision-application-actions {
 min-width: max-content;
 display: inline-flex;
 align-items: center;
 justify-content: flex-end;
 gap: 7px;
}

.source-ref-list {
 display: flex;
 flex-wrap: wrap;
 gap: 6px;
 margin-top: 8px;
}

.source-ref-list span {
 max-width: 100%;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fbfcfd;
 color: #4a5662;
 padding: 4px 7px;
 font-size: 12px;
 line-height: 1.35;
 overflow-wrap: anywhere;
}

.boundary-note {
 border-left: 3px solid #e67b2c;
 background: #fff7ed;
 padding: 7px 9px;
}

.checklist {
 display: grid;
 grid-template-columns: repeat(2, minmax(180px, 1fr));
 gap: 8px;
}

.checklist h3 {
 grid-column: 1 / -1;
}

.checklist label {
 display: flex;
 align-items: center;
 gap: 8px;
 min-height: 30px;
}

.checklist input[type="checkbox"] {
 width: auto;
 min-width: 14px;
}

textarea,
input {
 width: 100%;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 9px;
 color: var(--text);
 background: #fff;
}

textarea {
 min-height: 72px;
 resize: vertical;
}

.subject-shortcut {
 display: grid;
 grid-template-columns: minmax(220px, 1fr) auto;
 gap: 12px;
 align-items: center;
 color: var(--muted);
}

.subject-shortcut > div:first-child {
 display: grid;
 gap: 3px;
}

.subject-grid {
 display: grid;
 grid-template-columns: minmax(520px, 1.2fr) minmax(260px, 0.7fr) minmax(300px, 0.8fr);
 gap: 12px;
 margin-top: 12px;
}

.segmented {
 border: 1px solid var(--line);
 border-radius: 4px;
 display: flex;
 overflow: hidden;
}

.segmented button {
 border: 0;
 border-right: 1px solid var(--line);
 border-radius: 0;
}

.segmented button.active {
 background: var(--orange);
 color: #fff;
}

.subject-catalog-select {
 display: block;
 min-width: min(320px, 100%);
}

.subject-catalog-select select {
 width: 100%;
 height: 34px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
 font: inherit;
 font-size: 13px;
 padding: 0 10px;
}

.timeline {
 min-height: 170px;
 display: grid;
 grid-template-columns: repeat(7, minmax(80px, 1fr));
 grid-auto-columns: minmax(80px, 1fr);
 align-items: center;
 gap: 8px;
 position: relative;
 padding-top: 22px;
 overflow-x: auto;
}

.timeline::before {
 content: "";
 position: absolute;
 left: 18px;
 right: 18px;
 top: 86px;
 height: 2px;
 background: var(--line);
}

.timeline-event {
 min-height: 96px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 display: grid;
 align-content: center;
 gap: 4px;
 padding: 8px;
 position: relative;
}

.timeline-event::before {
 content: "";
 width: 10px;
 height: 10px;
 border-radius: 50%;
 position: absolute;
 left: 10px;
 top: -16px;
 background: var(--info);
}

.timeline-event.critical {
 border-color: #ffc9c9;
 background: var(--danger-bg);
}

.timeline-event.critical::before {
 background: var(--danger);
}

.timeline-event.warning {
 border-color: #ffd99d;
 background: var(--warning-bg);
}

.timeline-event.warning::before {
 background: var(--warning);
}

.timeline-event.good::before {
 background: var(--success);
}

.timeline-event span,
.timeline-event em {
 font-size: 12px;
 color: var(--muted);
 font-style: normal;
}

.trend-chart {
 min-height: 180px;
 display: flex;
 align-items: flex-end;
 gap: 14px;
 padding: 8px 4px 0;
}

.empty-state {
 width: 100%;
 min-height: 150px;
 border: 1px dashed var(--line);
 border-radius: 4px;
 display: grid;
 place-items: center;
 color: var(--muted);
 font-size: 13px;
}

.trend-col {
 flex: 1;
 display: grid;
 justify-items: center;
 gap: 5px;
}

.trend-col span {
 width: 22px;
 min-height: 20px;
 max-height: 120px;
 background: var(--info);
 border-radius: 4px 4px 0 0;
}

.trend-col b {
 font-size: 12px;
}

.trend-col em {
 font-size: 12px;
 color: var(--muted);
 font-style: normal;
}

.profile-summary {
 display: grid;
 gap: 10px;
}

.profile-summary > span {
 color: var(--muted);
}

.lab-list {
 display: grid;
 gap: 6px;
}

.lab-list > div,
.detail-grid > div {
 min-height: 36px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 display: grid;
 grid-template-columns: 80px 1fr auto;
 gap: 8px;
 align-items: center;
 padding: 6px 8px;
}

.risk-list p {
 display: flex;
 align-items: center;
 gap: 6px;
 color: var(--warning);
}

.review-focus {
 border-top: 1px solid var(--soft-line);
 padding-top: 10px;
 display: grid;
 gap: 6px;
}

.review-focus h3 {
 margin: 0;
 font-size: 13px;
}

.review-focus p {
 margin: 0;
 color: var(--muted);
 font-size: 13px;
}

.timeline-toolbar {
 display: grid;
 grid-template-columns: 260px minmax(320px, 1fr) 220px;
 gap: 12px;
 margin-bottom: 12px;
 align-items: end;
}

.timeline-toolbar > div {
 display: grid;
 gap: 6px;
}

.reference-timeline-page {
 --ref-ink: #2d2926;
 --ref-muted: #746f68;
 --ref-line: #eadfce;
 --ref-axis: #cdbb8f;
 --ref-brown: #9a6a19;
 --ref-orange: #bf5a00;
 --ref-card-bg: #fffaf2;
 background: #fffdf8;
 color: var(--ref-ink);
}

.reference-subject-head {
 border: 1px solid var(--ref-line);
 border-radius: 4px;
 background: #fffdf8;
 padding: 16px 16px 12px;
 display: flex;
 justify-content: space-between;
 gap: 16px;
 margin-bottom: 10px;
}

.reference-subject-head h2 {
 margin: 0 0 4px;
 font-size: 24px;
 letter-spacing: 0;
}

.reference-subject-head strong {
 color: var(--ref-brown);
}

.reference-subject-head p {
 margin: 6px 0 0;
 color: var(--ref-muted);
 font-size: 13px;
}

.reference-subject-actions {
 min-width: 170px;
 display: flex;
 flex-direction: column;
 align-items: flex-end;
 justify-items: end;
 gap: 8px;
 color: var(--ref-ink);
 font-weight: 700;
}

.reference-subject-actions button {
 white-space: nowrap;
}

.reference-subject-switch {
 border: 1px solid var(--ref-line);
 border-radius: 4px;
 background: #fffefa;
 padding: 8px 10px;
 display: flex;
 align-items: center;
 gap: 10px;
 margin-bottom: 10px;
}

.reference-subject-switch > span {
 color: var(--ref-muted);
 font-weight: 800;
 font-size: 13px;
}

.reference-subject-switch .segmented {
 max-width: 320px;
}

.reference-subject-switch .subject-catalog-select {
 max-width: 380px;
 flex: 1 1 280px;
}

.reference-risk-cards {
 display: grid;
 grid-template-columns: repeat(3, minmax(260px, 1fr));
 gap: 12px;
 margin-bottom: 12px;
}

.reference-risk-card {
 min-height: 88px;
 border: 1px solid #e4c7a1;
 border-left: 4px solid #d47a1d;
 border-radius: 6px;
 background: var(--ref-card-bg);
 padding: 12px 14px;
 display: grid;
 gap: 7px;
 align-content: start;
 overflow: hidden;
}

.reference-risk-card.plain {
 border-left-width: 1px;
}

.reference-risk-card h3 {
 margin: 0;
 font-size: 16px;
}

.reference-risk-card p {
 margin: 0;
 color: var(--ref-muted);
 line-height: 1.55;
 font-size: 13px;
 overflow-wrap: anywhere;
}

.timeline-context-summary {
 min-height: 42px;
 border: 1px solid var(--ref-line);
 border-left: 3px solid #708090;
 border-radius: 4px;
 background: #fffefa;
 padding: 8px 12px;
 display: flex;
 align-items: baseline;
 gap: 12px;
 margin-bottom: 10px;
}

.timeline-context-summary.focused {
 border-left-color: var(--orange);
 background: #fff9f1;
}

.timeline-context-summary strong {
 flex: 0 0 auto;
 font-size: 13px;
}

.timeline-context-summary span {
 color: var(--ref-muted);
 font-size: 12px;
}

.profile-data-warning {
 margin: 10px 0 0;
 padding: 9px 12px;
 border: 1px solid color-mix(in srgb, var(--danger) 32%, var(--ref-line));
 border-radius: 8px;
 color: var(--danger);
 background: color-mix(in srgb, var(--danger) 7%, white);
 font-size: 12px;
 line-height: 1.55;
}

.timeline-context-summary .profile-data-warning {
 flex-basis: 100%;
}

.reference-timeline-shell {
 border: 1px solid var(--ref-line);
 border-radius: 6px;
 background: #fffefa;
 padding: 0;
 overflow: hidden;
}

.timeline-category-legend {
 display: flex;
 flex-wrap: wrap;
 gap: 8px;
 padding: 10px 14px;
 min-width: 0;
}

.timeline-shell-toolbar {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 border-bottom: 1px solid #f1e8db;
 background: #fffefa;
}

.timeline-zoom-control {
 display: inline-flex;
 align-items: center;
 gap: 4px;
 flex: 0 0 auto;
 padding-right: 12px;
}

.timeline-zoom-control button {
 width: 30px;
 height: 30px;
 padding: 0;
 display: grid;
 place-items: center;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
}

.timeline-zoom-control span {
 width: 46px;
 text-align: center;
 font-size: 12px;
 font-weight: 700;
 color: var(--muted);
}

.timeline-category-chip {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 min-height: 24px;
 border: 1px solid var(--category-stroke, #b8c0ca);
 border-radius: 999px;
 background: var(--category-tint, #f6f7f9);
 color: #2b2f35;
 padding: 3px 9px;
 font-size: 12px;
 font-weight: 700;
 white-space: nowrap;
}

.timeline-category-chip > span {
 width: 10px;
 height: 10px;
 border-radius: 3px;
 background: var(--category-fill, #b7d4ea);
 box-shadow: inset 0 0 0 1px var(--category-stroke, #506270);
}

.reference-timeline-scroll {
 overflow-x: auto;
 padding: 0;
}

.reference-timeline-canvas {
 min-width: 0;
 min-height: 0;
 position: relative;
 padding: 0;
}

.reference-timeline-svg {
 width: 100%;
 min-width: 1180px;
 height: auto;
 display: block;
 background: #fffefa;
 padding: 8px;
}

.reference-svg-axis {
 stroke: var(--ref-axis);
 stroke-width: 4;
 stroke-linecap: round;
}

.reference-svg-date,
.reference-svg-visit-label,
.reference-svg-visit-date,
.reference-svg-event-label,
.reference-svg-event-empty {
 fill: var(--ref-muted);
 font-weight: 700;
}

.reference-svg-date {
 font-size: 12px;
}

.reference-svg-visit-line {
 stroke: #eee5d5;
 stroke-width: 1;
}

.reference-svg-visit-dot {
 fill: #8c6a2b;
 stroke: #fffefa;
 stroke-width: 2;
}

.reference-svg-visit-dot.unscheduled {
 fill: #fffefa;
 stroke: #bf5a00;
 stroke-width: 2.5;
}

.reference-svg-visit-label,
.reference-svg-visit-date {
 font-size: 10px;
}

.reference-svg-lane-title {
 fill: var(--ref-ink);
 font-size: 15px;
 font-weight: 800;
}

.reference-svg-lane-rule {
 stroke: #f1e8db;
 stroke-width: 1;
}

.reference-svg-lane-rule.soft {
 stroke: #f7f1e8;
}

.reference-svg-event-label {
 font-size: 10px;
 fill: #4b463f;
}

.reference-svg-event-empty {
 font-size: 10px;
 fill: #aaa198;
}

.reference-svg-event-block {
 fill: var(--category-fill, var(--lane-fill, #b7d4ea));
 stroke: var(--risk-stroke, var(--category-stroke, var(--lane-stroke, #506270)));
 stroke-width: 1.6;
}

.reference-svg-event-inline {
 fill: #ffffff;
 font-size: 9px;
 font-weight: 800;
 pointer-events: none;
}

.reference-svg-event-undated {
 fill: #6b7280;
 font-size: 9px;
 font-weight: 700;
}

.reference-svg-boundary-arrow {
 fill: #4f3d31;
 font-size: 15px;
 font-weight: 800;
 pointer-events: none;
}

.event-category-adverse-event {
 --category-fill: #5b8def;
 --category-stroke: #2859a8;
 --category-tint: #edf4ff;
}

.event-category-adverse-event-review {
 --category-fill: #2f6ea4;
 --category-stroke: #174d79;
 --category-tint: #e8f3fb;
}

.event-category-dose-adjustment {
 --category-fill: #8e65d6;
 --category-stroke: #6541a6;
 --category-tint: #f3efff;
}

.event-category-dose-adjustment-paused {
 --category-fill: #7c3aed;
 --category-stroke: #4c1d95;
 --category-tint: #f1ecff;
}

.event-category-dose-adjustment-resumed {
 --category-fill: #a855f7;
 --category-stroke: #6b21a8;
 --category-tint: #f7edff;
}

.event-category-study-drug-dispensing {
 --category-fill: #6f63c2;
 --category-stroke: #44388f;
 --category-tint: #f0effb;
}

.event-category-study-drug-administration {
 --category-fill: #168fa0;
 --category-stroke: #0b6170;
 --category-tint: #e8f7f8;
}

.event-category-study-drug-adherence {
 --category-fill: #b37a25;
 --category-stroke: #754b0f;
 --category-tint: #fff6e6;
}

.event-category-background-treatment {
 --category-fill: #2e8b78;
 --category-stroke: #176252;
 --category-tint: #e9f7f3;
}

.event-category-non-drug-treatment {
 --category-fill: #708090;
 --category-stroke: #465461;
 --category-tint: #f0f3f5;
}

.event-category-concomitant-medication {
 --category-fill: #4ca66a;
 --category-stroke: #2f7548;
 --category-tint: #ecf8f0;
}

.event-category-concomitant-medication-risk {
 --category-fill: #cf6f2a;
 --category-stroke: #8a4210;
 --category-tint: #fff2e7;
}

.event-category-medical-history {
 --category-fill: #a8743f;
 --category-stroke: #765020;
 --category-tint: #f8f1e8;
}

.event-category-lab {
 --category-fill: #e6a23c;
 --category-stroke: #9b6815;
 --category-tint: #fff4de;
}

.event-category-lab-hematology {
 --category-fill: #d97706;
 --category-stroke: #92400e;
 --category-tint: #fff7ed;
}

.event-category-lab-chemistry {
 --category-fill: #b45309;
 --category-stroke: #78350f;
 --category-tint: #fff4df;
}

.event-category-efficacy-score {
 --category-fill: #2aa198;
 --category-stroke: #14736d;
 --category-tint: #e8f8f6;
}

.event-category-protocol-deviation {
 --category-fill: #d15f5f;
 --category-stroke: #9e3434;
 --category-tint: #fff0f0;
}

.event-category-query {
 --category-fill: #5b677a;
 --category-stroke: #374151;
 --category-tint: #f1f4f8;
}

.event-category-other {
 --category-fill: #95a3b3;
 --category-stroke: #64748b;
 --category-tint: #f4f6f8;
}

.reference-svg-event-block.lane-ae {
 --lane-fill: #8db7e8;
 --lane-stroke: #3d6fa7;
}

.reference-svg-event-block.lane-ip {
 --lane-fill: #b79be8;
 --lane-stroke: #7152b8;
}

.reference-svg-event-block.lane-background {
 --lane-fill: #76b8aa;
 --lane-stroke: #347d6e;
}

.reference-svg-event-block.lane-non-drug {
 --lane-fill: #9aa7b4;
 --lane-stroke: #596875;
}

.reference-svg-event-block.lane-cm {
 --lane-fill: #79c99a;
 --lane-stroke: #3c8a5d;
}

.reference-svg-event-block.lane-mh {
 --lane-fill: #c6ad86;
 --lane-stroke: #7d6035;
}

.reference-svg-event-block.lane-lab {
 --lane-fill: #f2c45c;
 --lane-stroke: #a76f12;
}

.reference-svg-event-block.lane-efficacy {
 --lane-fill: #55b9ad;
 --lane-stroke: #14736d;
}

.reference-svg-event-block.lane-pd-query {
 --lane-fill: #e9948c;
 --lane-stroke: #ad4b42;
}

.reference-svg-event-block.lane-other {
 --lane-fill: #a8b2bf;
 --lane-stroke: #667382;
}

.reference-svg-event-block.warning {
 --risk-stroke: #9a5b00;
 stroke-width: 2.2;
}

.reference-svg-event-block.critical {
 --risk-stroke: #a32020;
 stroke-width: 2.6;
}

.reference-svg-event-block.good {
 stroke-width: 1.8;
}

.reference-svg-event-block.source {
 stroke-dasharray: 3 2;
}

.reference-svg-event-block.normal {
 stroke-width: 1.6;
}

.timeline-toolbar span {
 color: var(--muted);
 font-size: 12px;
 line-height: 1.5;
}

.timeline-risk-cards {
 display: grid;
 grid-template-columns: repeat(3, minmax(220px, 1fr));
 gap: 12px;
 margin-bottom: 12px;
}

.timeline-risk-card {
 border: 1px solid #ffd6a8;
 border-left: 4px solid var(--orange);
 border-radius: 4px;
 background: #fffaf2;
 padding: 12px;
 display: grid;
 gap: 6px;
}

.timeline-risk-card span {
 color: var(--muted);
 font-size: 12px;
}

.timeline-canvas {
 min-height: 390px;
 overflow-x: auto;
}

.visit-axis-panel {
 overflow: hidden;
}

.visit-axis-scroll {
 overflow-x: auto;
 padding-bottom: 6px;
}

.visit-axis-canvas {
 min-width: 980px;
 min-height: 500px;
 position: relative;
 padding: 74px 28px 24px;
}

.visit-axis-line {
 position: absolute;
 left: 46px;
 right: 46px;
 top: 96px;
 height: 2px;
 background: var(--line);
}

.visit-marker {
 width: 116px;
 position: absolute;
 top: 38px;
 transform: translateX(-50%);
 display: grid;
 justify-items: center;
 gap: 4px;
 text-align: center;
}

.visit-marker.below {
 top: 106px;
}

.visit-marker b {
 width: 10px;
 height: 10px;
 border-radius: 50%;
 background: var(--orange);
 border: 2px solid #fff;
 box-shadow: 0 0 0 2px #ffd6a8;
}

.visit-marker span {
 font-weight: 800;
}

.visit-marker em {
 color: var(--muted);
 font-style: normal;
 font-size: 12px;
}

.event-lanes {
 display: grid;
 gap: 10px;
 margin-top: 112px;
}

.timeline-lane-track {
 min-height: 70px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fbfcfd;
 display: grid;
 grid-template-columns: 120px minmax(0, 1fr);
 align-items: stretch;
 overflow: hidden;
}

.timeline-lane-track > strong {
 display: flex;
 align-items: center;
 padding: 10px;
 border-right: 1px solid var(--soft-line);
 background: #fff;
}

.timeline-lane-track > div {
 position: relative;
 min-height: 70px;
}

.lane-event-pin {
 max-width: 190px;
 min-width: 128px;
 position: absolute;
 top: 10px;
 transform: translateX(-12px);
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 padding: 6px 8px;
 display: grid;
 gap: 2px;
 text-align: left;
 white-space: normal;
}

.lane-event-pin.critical {
 border-color: #ffc9c9;
 background: var(--danger-bg);
}

.lane-event-pin.warning {
 border-color: #ffd99d;
 background: var(--warning-bg);
}

.lane-event-pin.good {
 border-color: #bfe7ce;
 background: var(--success-bg);
}

.lane-event-pin span,
.lane-event-pin em {
 color: var(--muted);
 font-size: 11px;
 font-style: normal;
}

.lane-event-pin b {
 font-size: 12px;
 line-height: 1.3;
}

.timeline-axis {
 min-width: 860px;
 display: grid;
 grid-template-columns: repeat(7, minmax(110px, 1fr));
 align-items: center;
 padding: 20px 30px 8px;
 border-bottom: 4px solid #d8c59e;
}

.axis-point {
 display: grid;
 justify-items: center;
 gap: 5px;
 color: var(--muted);
 font-size: 12px;
}

.axis-point b {
 width: 9px;
 height: 9px;
 border-radius: 50%;
 background: #9a7130;
}

.axis-point em {
 font-style: normal;
 text-align: center;
}

.timeline-lanes {
 min-width: 860px;
 display: grid;
 gap: 14px;
 padding: 18px 18px 8px;
}

.lane-row {
 display: grid;
 grid-template-columns: 120px 1fr;
 gap: 12px;
 align-items: start;
}

.lane-row > div {
 display: flex;
 flex-wrap: wrap;
 gap: 8px;
}

.lane-event {
 min-height: 28px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 padding: 4px 8px;
}

.lane-event.critical,
.lane-event.warning {
 border-color: #ffd6a8;
 background: #fff7ec;
 color: var(--warning);
}

.timeline-detail-grid,
.profile-two-col {
 display: grid;
 grid-template-columns: repeat(2, minmax(320px, 1fr));
 gap: 12px;
 margin-top: 12px;
}

.timeline-detail-grid .panel:last-child {
 grid-column: 1 / -1;
}

.timeline-detail-card {
 min-height: 0;
}

.timeline-detail-row {
 border-bottom: 1px solid var(--soft-line);
 border-left: 4px solid var(--category-fill, transparent);
 background: linear-gradient(90deg, var(--category-tint, transparent), transparent 74%);
 padding: 8px 10px;
 display: grid;
 grid-template-columns: minmax(104px, max-content) minmax(0, 1fr);
 gap: 10px;
 align-items: start;
}

.timeline-detail-row:last-child {
 border-bottom: 0;
}

.timeline-detail-row div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.timeline-detail-row > .tag {
 justify-self: start;
 max-width: 150px;
 white-space: normal;
 text-align: center;
 line-height: 1.25;
}

.timeline-detail-row span,
.timeline-detail-row em {
 color: var(--muted);
 font-size: 12px;
 line-height: 1.5;
 font-style: normal;
}

.timeline-detail-more {
 width: 100%;
 border: 0;
 border-top: 1px solid var(--soft-line);
 background: #fafbfc;
 color: var(--muted);
 padding: 9px 12px;
 font-size: 12px;
 text-align: center;
}

.chart-baseline line {
 stroke: #66574d;
 stroke-width: 1.2;
 stroke-dasharray: 5 4;
 opacity: 0.72;
}

.chart-baseline text {
 fill: #66574d;
 font-size: 9px;
 font-weight: 700;
}

.metric-chart-head .metric-baseline-note {
 color: #6a5d54;
 font-size: 11px;
 line-height: 1.45;
}

.chart-point.baseline {
 stroke: #4d3c30;
 stroke-width: 2;
}

.metric-points-toggle {
 width: 100%;
 border: 0;
 border-top: 1px solid var(--soft-line);
 background: #fafbfc;
 color: var(--muted);
 padding: 8px 12px;
 font-size: 12px;
 text-align: center;
}

.profile-hero {
 min-height: 98px;
 border-radius: 4px;
 background: #202136;
 color: #fff;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 16px;
 padding: 18px 22px;
 margin-bottom: 12px;
}

.profile-hero > div {
 min-width: 0;
}

.profile-hero span,
.profile-hero p {
 color: #c8ccda;
}

.profile-hero h2,
.profile-hero p {
 margin: 4px 0 0;
 overflow-wrap: anywhere;
}

.profile-filter-bar {
 display: grid;
 grid-template-columns: minmax(0, 1.2fr) minmax(0, 1.4fr) minmax(220px, 0.8fr);
 gap: 12px;
 align-items: end;
 margin-bottom: 12px;
}

.profile-filter-bar > div,
.profile-filter-bar label {
 min-width: 0;
 display: grid;
 gap: 6px;
}

.profile-filter-bar strong {
 color: var(--muted);
 font-size: 12px;
}

.profile-filter-bar .segmented {
 max-width: 100%;
 overflow-x: auto;
 justify-content: flex-start;
}

.profile-center-select {
 width: 100%;
 height: 36px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 0 30px 0 10px;
 background: #fff;
 color: var(--text);
 font: inherit;
}

.profile-filter-bar .subject-switch {
 flex-wrap: nowrap;
}

.profile-filter-bar label > span {
 min-width: 0;
 height: 36px;
 border: 1px solid var(--line);
 border-radius: 4px;
 display: grid;
 grid-template-columns: 18px minmax(0, 1fr);
 gap: 6px;
 align-items: center;
 padding: 0 9px;
 background: #fff;
}

.profile-filter-bar input {
 min-width: 0;
 width: 100%;
 border: 0;
 outline: none;
}

.profile-workbench {
 display: grid;
 grid-template-columns: 240px minmax(0, 1fr);
 gap: 12px;
 min-width: 0;
}

.profile-subject-list {
 display: grid;
 align-content: start;
 gap: 7px;
 min-width: 0;
 max-height: calc(100vh - 240px);
 overflow-y: auto;
}

.profile-subject-list > .section-title {
 position: sticky;
 top: 0;
 z-index: 2;
 margin: -2px -2px 0;
 padding: 2px 2px 8px;
 background: #fff;
}

.profile-subject-list button {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fff;
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 gap: 4px;
 align-items: center;
 padding: 8px;
 text-align: left;
 min-width: 0;
}

.profile-subject-list button.selected {
 border-color: var(--orange);
 background: #fff8f3;
 scroll-margin-block: 8px;
}

.profile-subject-list button > span {
 grid-column: 1 / -1;
}

.profile-subject-list span {
 color: var(--muted);
 font-size: 12px;
 overflow-wrap: anywhere;
}

.profile-tree {
 display: grid;
 gap: 10px;
}

.profile-tree-group {
 display: grid;
 gap: 6px;
}

.profile-tree-center {
 min-height: 30px;
 border-bottom: 1px solid var(--soft-line);
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
 color: var(--text);
}

.profile-main {
 display: grid;
 gap: 12px;
 min-width: 0;
}

.profile-summary-band {
 display: grid;
 grid-template-columns: repeat(4, minmax(140px, 1fr));
 gap: 10px;
 min-width: 0;
}

.profile-summary-band > div {
 min-width: 0;
 min-height: 70px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 display: grid;
 place-items: center;
 align-content: center;
 background: #fbfcfd;
}

.profile-summary-band strong {
 font-size: 22px;
 color: var(--orange);
 max-width: 100%;
 overflow-wrap: anywhere;
 text-align: center;
}

.profile-summary-band span {
 color: var(--muted);
 font-size: 12px;
 text-align: center;
}

.profile-section {
 min-width: 0;
}

.profile-info-grid {
 display: grid;
 grid-template-columns: repeat(4, minmax(0, 1fr));
 gap: 8px;
}

.profile-info-grid > div {
 min-width: 0;
 min-height: 58px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 display: grid;
 align-content: center;
 gap: 3px;
 padding: 8px 10px;
 background: #fbfcfd;
}

.profile-info-grid span {
 color: var(--muted);
 font-size: 12px;
}

.profile-info-grid strong {
 min-width: 0;
 overflow-wrap: anywhere;
}

.profile-context-list {
 display: grid;
 gap: 6px;
 margin-top: 10px;
}

.profile-context-list p,
.profile-review-focus p {
 margin: 0;
 border-left: 3px solid var(--orange);
 padding: 6px 8px;
 background: #fff8f3;
 overflow-wrap: anywhere;
}

.profile-trend-table {
 border: 1px solid var(--line);
 border-radius: 4px;
 overflow: hidden;
}

.profile-trend-table > div {
 display: grid;
 grid-template-columns: 120px 100px 1fr;
 gap: 12px;
 align-items: center;
 min-height: 38px;
 padding: 7px 10px;
 border-bottom: 1px solid var(--soft-line);
}

.profile-trend-table > div:first-child {
 background: #f7f8fa;
}

.profile-trend-table > div:last-child {
 border-bottom: 0;
}

.metric-chart-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(min(100%, 360px), 1fr));
 gap: 12px;
 min-width: 0;
}

.metric-chart {
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 padding: 10px;
 overflow: hidden;
 min-width: 0;
}

.metric-chart-head {
 display: flex;
 justify-content: space-between;
 gap: 8px;
 margin-bottom: 8px;
 min-width: 0;
}

.metric-chart-head div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.metric-chart-head strong {
 min-width: 0;
 overflow-wrap: anywhere;
}

.metric-chart-head span {
 color: var(--muted);
 font-size: 12px;
 overflow-wrap: anywhere;
}

.metric-chart svg {
 width: 100%;
 height: auto;
 display: block;
 background: #fbfcfd;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
}

.chart-axis-line {
 stroke: #d5dae0;
 stroke-width: 1;
}

.chart-ref-line {
 stroke: #b96b00;
 stroke-dasharray: 5 4;
 stroke-width: 1;
}

.chart-point-reference line {
 stroke: #b68a4c;
 stroke-width: 1;
 opacity: 0.7;
}

.chart-line {
 fill: none;
 stroke: var(--info);
 stroke-width: 2.5;
}

.chart-point {
 fill: #fff;
 stroke: var(--info);
 stroke-width: 2;
}

.chart-point.risk {
 stroke: var(--danger);
 fill: var(--danger-bg);
}

.chart-label,
.chart-value {
 fill: var(--muted);
 font-size: 11px;
}

.profile-domain-footnote {
 margin: 2px 2px 0;
 color: var(--muted);
 font-size: 11px;
}

.chart-value {
 fill: var(--text);
 font-weight: 700;
}

.metric-point-list {
 display: grid;
 gap: 5px;
 margin-top: 8px;
}

.metric-point-list > div {
 min-height: 30px;
 display: grid;
 grid-template-columns: 44px minmax(0, 1fr) minmax(58px, auto);
 gap: 8px;
 align-items: center;
 border-bottom: 1px solid var(--soft-line);
 padding-bottom: 5px;
 min-width: 0;
}

.metric-point-list > div:last-child {
 border-bottom: 0;
}

.metric-point-list span {
 color: var(--muted);
 font-size: 12px;
 min-width: 0;
 overflow-wrap: anywhere;
}

.profile-risk-prompts p {
 align-items: flex-start;
}

.profile-risk-prompts span {
 color: var(--warning);
 line-height: 1.5;
}

.profile-review-focus {
 display: grid;
 gap: 6px;
 margin-top: 10px;
}

.profile-pd-query-grid {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 12px;
}

.profile-pd-query-grid h3 {
 margin: 0 0 8px;
 font-size: 14px;
}

.profile-query-card {
 min-width: 0;
 min-height: 44px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 gap: 8px;
 align-items: flex-start;
 padding: 8px;
 margin-bottom: 7px;
 background: #fbfcfd;
}

.profile-query-card div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.profile-query-card strong,
.profile-query-card span {
 min-width: 0;
 overflow-wrap: anywhere;
}

.profile-query-card span {
 color: var(--muted);
 font-size: 12px;
 line-height: 1.5;
}

.profile-event-index {
 display: grid;
 gap: 6px;
}

.profile-event-index > div {
 min-height: 34px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 display: grid;
 grid-template-columns: 46px minmax(0, 1fr);
 gap: 8px;
 align-items: center;
 padding: 6px 8px;
}

.profile-event-index span {
 overflow-wrap: anywhere;
}

.eligibility-layout {
 display: grid;
 grid-template-columns: 300px minmax(420px, 1fr) 360px;
 gap: 12px;
}

.eligibility-status {
 min-height: 68px;
 display: grid;
 grid-template-columns: 1.1fr 1.2fr 0.85fr 1fr 1fr;
 gap: 10px;
 margin-bottom: 12px;
}

.source-admission-band {
 display: grid;
 gap: 10px;
 margin-bottom: 12px;
 border-left: 3px solid var(--orange);
}

.source-admission-head {
 display: grid;
 grid-template-columns: 18px max-content minmax(0, 1fr) 32px;
 align-items: center;
 gap: 8px;
}

.source-admission-head > span {
 min-width: 0;
 color: var(--muted);
 font-size: 12px;
 overflow-wrap: anywhere;
}

.source-admission-cards {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 border-top: 1px solid var(--soft-line);
}

.source-admission-card {
 min-width: 0;
 display: grid;
 align-content: start;
 gap: 8px;
 padding: 10px 12px 4px 0;
}

.source-admission-card + .source-admission-card {
 border-left: 1px solid var(--soft-line);
 padding-left: 12px;
 padding-right: 0;
}

.source-admission-card.needs-confirmation {
 box-shadow: inset 3px 0 0 #f59e0b;
 padding-left: 10px;
}

.source-admission-card-head,
.source-admission-card-foot,
.content-confirmation-actions {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.module-source-admission {
 margin: 12px 0;
 border: 1px solid var(--line);
 border-left: 3px solid var(--warning);
 border-radius: 4px;
 background: #fffdf9;
 min-width: 0;
}

.module-source-admission.ready {
 border-left-color: var(--success);
 background: #fbfdfb;
}

.module-source-admission-head {
 min-height: 42px;
 display: grid;
 grid-template-columns: auto auto minmax(220px, 1fr) auto auto auto;
 gap: 8px;
 align-items: center;
 padding: 6px 10px;
 min-width: 0;
}

.module-source-admission-head > span {
 color: var(--muted);
 font-size: 12px;
 min-width: 0;
 overflow-wrap: anywhere;
}

.module-source-admission-toggle {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 gap: 4px;
 padding: 4px 8px;
}

.module-source-admission-toggle svg {
 transition: transform 140ms ease;
}

.module-source-admission-toggle svg.expanded {
 transform: rotate(90deg);
}

.module-source-admission-body {
 border-top: 1px solid var(--soft-line);
 padding: 10px;
 min-width: 0;
}

.module-source-admission-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
 gap: 8px;
 min-width: 0;
}

.module-source-admission-source {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fff;
 padding: 9px;
 display: grid;
 align-content: start;
 gap: 8px;
 min-width: 0;
}

.module-source-admission-source.needs-confirmation {
 border-color: #e6b36d;
 background: #fffaf3;
}

.module-source-admission-source-head {
 display: flex;
 justify-content: space-between;
 gap: 8px;
 align-items: flex-start;
 min-width: 0;
}

.module-source-admission-source-head > div:first-child {
 display: grid;
 gap: 2px;
 min-width: 0;
}

.module-source-admission-source-head > div:first-child span,
.module-source-admission-source > p,
.module-source-confirmed-record span,
.module-source-confirmed-record small {
 min-width: 0;
 overflow-wrap: anywhere;
}

.module-source-admission-source-head > div:first-child span,
.module-source-admission-source > p,
.module-source-confirmed-record small {
 color: var(--muted);
 font-size: 12px;
}

.module-source-admission-source-head > div:last-child {
 display: flex;
 flex-wrap: wrap;
 justify-content: flex-end;
 gap: 4px;
}

.module-source-admission-source > p {
 margin: 0;
 line-height: 1.45;
}

.module-source-admission-checks {
 display: grid;
 border-top: 1px solid var(--soft-line);
}

.module-source-admission-checks > div {
 min-height: 34px;
 display: grid;
 grid-template-columns: minmax(78px, 0.8fr) auto minmax(120px, 1.8fr);
 gap: 7px;
 align-items: center;
 border-bottom: 1px solid var(--soft-line);
 padding: 5px 0;
 min-width: 0;
}

.module-source-admission-checks b,
.module-source-admission-checks small {
 font-size: 12px;
}

.module-source-admission-checks small {
 color: var(--muted);
 min-width: 0;
 overflow-wrap: anywhere;
 display: -webkit-box;
 -webkit-box-orient: vertical;
 -webkit-line-clamp: 3;
 overflow: hidden;
}

.module-source-admission-source > button {
 justify-self: start;
 display: inline-flex;
 align-items: center;
 gap: 5px;
}

.module-source-confirmed-record {
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 gap: 7px;
 align-items: center;
 padding: 6px 8px;
 border-left: 3px solid var(--success);
 background: var(--success-bg);
}

.module-source-confirmed-record small {
 grid-column: 2;
}

.module-source-confirmation {
 max-height: 44vh;
 overflow-y: auto;
 margin-top: 10px;
 border: 1px solid #e6b36d;
 border-radius: 4px;
 background: #fffaf3;
 padding: 10px;
 display: grid;
 gap: 9px;
}

.module-source-confirmation > p,
.module-source-confirmation > small {
 margin: 0;
 color: var(--muted);
 line-height: 1.5;
}

.module-source-confirmation fieldset {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 display: grid;
 gap: 6px;
 padding: 8px;
}

.module-source-confirmation legend {
 padding: 0 5px;
 font-weight: 700;
}

.module-source-confirmation-reason {
 display: grid;
 gap: 5px;
}

.module-source-confirmation-reason textarea {
 width: 100%;
 resize: vertical;
}

.source-admission-card-tags {
 display: flex;
 flex-wrap: wrap;
 justify-content: flex-end;
 gap: 5px;
}

.source-admission-card-body {
 display: grid;
 grid-template-columns: minmax(0, 1.2fr) max-content max-content;
 gap: 6px 12px;
 color: var(--muted);
 font-size: 11px;
}

.source-admission-card-body > span {
 min-width: 0;
 overflow-wrap: anywhere;
}

.source-admission-card-body > span:last-child {
 grid-column: 1 / -1;
}

.source-admission-raw-note {
 margin: 0;
 padding: 6px 8px;
 color: #7c4a03;
 background: #fffaf0;
 border-left: 2px solid #f59e0b;
 font-size: 11px;
 line-height: 1.45;
}

.source-admission-checks {
 display: grid;
 border-top: 1px solid var(--soft-line);
}

.source-admission-checks > div {
 min-width: 0;
 display: grid;
 grid-template-columns: 100px 56px minmax(0, 1fr);
 gap: 8px;
 padding: 5px 0;
 border-bottom: 1px solid var(--soft-line);
 font-size: 11px;
}

.source-admission-checks small {
 min-width: 0;
 max-height: 38px;
 overflow: auto;
 color: var(--muted);
 overflow-wrap: anywhere;
}

.source-admission-card-foot {
 justify-content: flex-end;
}

.source-admission-band > .content-confirmation {
 grid-column: auto;
}

.content-confirmation-actions {
 justify-content: flex-start;
}

@media (max-width: 1260px) {
 .eligibility-status {
 grid-template-columns: repeat(3, minmax(0, 1fr));
 }

 .source-admission-cards {
 grid-template-columns: minmax(0, 1fr);
 }

 .source-admission-card + .source-admission-card {
 border-left: 0;
 border-top: 1px solid var(--soft-line);
 padding-left: 0;
 }
}

.eligibility-status > div {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 10px;
 display: grid;
 gap: 4px;
 background: #fbfcfd;
}

.eligibility-status span {
 color: var(--muted);
 font-size: 12px;
}

.eligibility-raw-intake {
 display: grid;
 gap: 10px;
 margin-bottom: 12px;
 border-left: 3px solid var(--orange);
}

.raw-intake-head {
 min-height: 30px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
}

.raw-intake-head > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.raw-intake-head span,
.eligibility-raw-intake p,
.raw-intake-grid span {
 color: var(--muted);
 font-size: 12px;
}

.raw-intake-head strong {
 overflow-wrap: anywhere;
}

.raw-intake-grid {
 display: grid;
 grid-template-columns: repeat(4, minmax(160px, 1fr));
 gap: 8px;
}

.raw-intake-grid > div {
 min-height: 58px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fbfcfd;
 padding: 8px;
 display: grid;
 gap: 4px;
}

.eligibility-raw-intake p {
 margin: 0;
 line-height: 1.5;
 overflow-wrap: anywhere;
}

.search-row {
 height: 38px;
 display: grid;
 grid-template-columns: 18px 1fr;
 gap: 8px;
 align-items: center;
 margin-bottom: 10px;
}

.candidate-panel,
.rule-tree,
.review-panel,
.evidence-tree {
 min-height: 0;
}

.candidate-row {
 grid-template-columns: 82px 62px 46px minmax(96px, 1fr);
 padding: 7px;
 margin-bottom: 6px;
}

.candidate-row.selected,
.approval-list button.selected,
.section-tree button.active {
 border-color: var(--orange);
 background: #fff8f3;
}

.candidate-row em {
 color: var(--muted);
 font-style: normal;
 font-size: 12px;
 line-height: 1.25;
}

.rule-node,
.evidence-node {
 min-height: 38px;
 border-bottom: 1px solid var(--soft-line);
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
}

.rule-node.warning {
 color: var(--warning);
}

.review-result {
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 12px;
 background: #fbfcfd;
 margin-bottom: 12px;
}

.eligibility-side {
 display: grid;
 gap: 12px;
}

.verdict-strip {
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 12px;
 background: #fbfcfd;
 display: grid;
 gap: 7px;
 margin-bottom: 12px;
}

.verdict-strip span {
 color: var(--muted);
}

.review-report {
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 12px;
 margin-bottom: 12px;
}

.review-report h3,
.review-report p {
 margin-top: 0;
}

.report-grid {
 display: grid;
 grid-template-columns: repeat(2, minmax(180px, 1fr));
 gap: 8px;
}

.report-grid > div {
 min-height: 56px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 8px;
 display: grid;
 gap: 4px;
 background: #fbfcfd;
}

.report-grid span {
 color: var(--muted);
 font-size: 12px;
}

.review-result h3 {
 margin: 8px 0 5px;
}

.button-grid {
 display: grid;
 grid-template-columns: repeat(2, minmax(120px, 1fr));
 gap: 8px;
 margin-bottom: 12px;
}

.evidence-node {
 justify-content: flex-start;
}

.evidence-node div {
 display: grid;
}

.evidence-node span {
 color: var(--muted);
 font-size: 12px;
}

.eligibility-controls {
 display: grid;
 grid-template-columns: minmax(0, 1fr) 300px;
 gap: 12px;
 margin-bottom: 12px;
}

.phase-tabs {
 display: flex;
 gap: 8px;
 overflow-x: auto;
 min-width: 0;
}

.phase-tabs > div {
 min-width: 190px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 padding: 9px 10px;
 display: grid;
 gap: 3px;
 text-align: left;
}

.phase-tabs > div.active {
 border-color: var(--orange);
 background: #fff8f3;
}

.phase-tabs span,
.phase-cell span,
.quiet-text {
 color: var(--muted);
 font-size: 12px;
}

.eligibility-workbench {
 display: grid;
 grid-template-columns: minmax(420px, 0.9fr) minmax(520px, 1.25fr) minmax(280px, 0.65fr);
 grid-template-areas: "subjects review side";
 gap: 12px;
 align-items: start;
}

.eligibility-workbench > * {
 min-width: 0;
}

.eligibility-subjects-panel {
 grid-area: subjects;
}

.eligibility-subjects-panel .eligibility-table-wrap {
 max-height: 720px;
 overflow: auto;
}

.eligibility-review-panel {
 grid-area: review;
}

.eligibility-side {
 grid-area: side;
}

.eligibility-table-wrap,
.rule-review-table-wrap {
 width: 100%;
 overflow-x: auto;
 border: 1px solid var(--line);
 border-radius: 4px;
}

.eligibility-subject-table,
.rule-review-table {
 width: 100%;
 min-width: 780px;
 table-layout: fixed;
 border-collapse: collapse;
 background: #fff;
}

.eligibility-subject-table {
 min-width: 100%;
}

.rule-review-table {
 min-width: 920px;
}

.eligibility-subject-table th,
.eligibility-subject-table td,
.rule-review-table th,
.rule-review-table td {
 border-bottom: 1px solid var(--soft-line);
 padding: 8px;
 text-align: left;
 vertical-align: top;
 font-size: 12px;
 overflow-wrap: anywhere;
 word-break: break-word;
}

.eligibility-subject-table th:nth-child(1) { width: 28%; }
.eligibility-subject-table th:nth-child(2) { width: 18%; }
.eligibility-subject-table th:nth-child(3) { width: 24%; }
.eligibility-subject-table th:nth-child(4) { width: 30%; }

.eligibility-subject-table th,
.rule-review-table th {
 color: var(--muted);
 background: #f7f8fa;
 font-weight: 700;
 white-space: nowrap;
}

.eligibility-subject-table tr.selected td {
 background: #fff8f3;
}

.raw-subject-summary {
 display: grid;
 grid-template-columns: repeat(5, minmax(0, 1fr));
 gap: 8px;
 margin-bottom: 10px;
}

.raw-subject-summary > div {
 min-width: 0;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fbfcfd;
 padding: 8px;
}

.raw-subject-summary strong,
.raw-subject-summary span {
 display: block;
 min-width: 0;
 overflow-wrap: anywhere;
}

.raw-subject-summary span {
 color: var(--muted);
 font-size: 11px;
 margin-top: 2px;
}

.raw-pending-state {
 color: var(--muted);
 font-size: 13px;
 line-height: 1.65;
 overflow-wrap: anywhere;
}

.legacy-comparison {
 border-color: #e0d6c3;
 background: #fffdf8;
}

.subject-link {
 border: 0;
 background: transparent;
 color: var(--info);
 font-weight: 800;
 padding: 0;
}

.phase-cell {
 width: 100%;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fff;
 display: grid;
 gap: 4px;
 padding: 6px;
 text-align: left;
}

.phase-cell.active {
 border-color: var(--orange);
 background: #fff8f3;
}

.eligibility-verdict {
 grid-template-columns: auto minmax(130px, 0.7fr) minmax(220px, 1fr);
 align-items: center;
}

.eligibility-verdict span:last-child {
 grid-column: 1 / -1;
}

.eligibility-report-grid {
 margin-bottom: 12px;
}

.criteria-list,
.action-list,
.evidence-list {
 display: grid;
 gap: 6px;
 max-height: 360px;
 overflow-y: auto;
 padding-right: 2px;
}

.criteria-row,
.action-item {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fff;
 min-width: 0;
 padding: 8px;
 display: grid;
 gap: 8px;
}

.criteria-row {
 grid-template-columns: 58px minmax(0, 1fr);
}

.criteria-row div,
.action-item div,
.evidence-node div {
 min-width: 0;
}

.criteria-row strong,
.action-item strong,
.evidence-node strong {
 display: block;
 overflow-wrap: anywhere;
}

.criteria-row span,
.action-item span,
.evidence-node span {
 overflow-wrap: anywhere;
}

.action-item {
 grid-template-columns: 18px minmax(0, 1fr);
 color: var(--warning);
 background: var(--warning-bg);
 border-color: #ffd99d;
}

.eligibility-rule-tabs {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 6px;
 margin-bottom: 8px;
}

.eligibility-rule-tabs button {
 min-width: 0;
 min-height: 34px;
 padding: 6px 8px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 font-size: 12px;
}

.eligibility-rule-tabs button.active {
 border-color: var(--orange);
 background: #fff8f3;
 color: var(--orange-dark);
 font-weight: 800;
}

.eligibility-rule-source {
 display: grid;
 gap: 3px;
 padding: 8px;
 margin-bottom: 8px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fbfcfd;
}

.eligibility-rule-source strong {
 font-size: 12px;
}

.eligibility-rule-source span,
.eligibility-rule-boundary {
 color: var(--muted);
 font-size: 11px;
 overflow-wrap: anywhere;
}

.eligibility-rule-tree-scroll {
 max-height: 520px;
 overflow-y: auto;
 padding-right: 3px;
 scrollbar-width: thin;
}

.eligibility-rule-node {
 margin-left: calc(var(--rule-depth) * 10px);
 padding-left: calc(var(--rule-depth) * 2px);
}

.eligibility-rule-node-main {
 min-width: 0;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 gap: 7px;
 align-items: start;
 border-left: 2px solid #dbe1e8;
 border-bottom: 1px solid var(--soft-line);
 padding: 7px 5px 7px 8px;
}

.eligibility-rule-node-main > div {
 min-width: 0;
}

.eligibility-rule-node-main strong,
.eligibility-rule-node-main span {
 display: block;
 overflow-wrap: anywhere;
}

.eligibility-rule-node-main strong {
 font-size: 12px;
 line-height: 1.55;
}

.eligibility-rule-node-main span {
 margin-top: 3px;
 color: var(--muted);
 font-size: 10px;
}

.eligibility-rule-boundary {
 margin: 8px 0 0;
 padding-top: 8px;
 border-top: 1px solid var(--soft-line);
 line-height: 1.55;
}

.eligibility-rule-task-panel .criteria-list {
 max-height: 180px;
}

.eligibility-boundary-line {
 margin: -2px 0 12px;
 padding: 8px 10px;
 border-left: 3px solid var(--warning);
 background: #fffaf2;
 color: #66512f;
 font-size: 12px;
 line-height: 1.5;
}

.eligibility-conflict-banner {
 min-height: 44px;
 margin-bottom: 12px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 border-color: #e4b067;
 background: #fffaf2;
}

.eligibility-workbench {
 grid-template-columns: 270px minmax(430px, 1fr) 400px;
 grid-template-areas: "subjects review side";
 align-items: stretch;
 min-height: 620px;
 height: min(730px, calc(100vh - 270px));
}

.eligibility-workbench > .panel {
 min-height: 0;
 height: 100%;
 overflow: hidden;
}

.eligibility-subjects-panel,
.eligibility-criterion-ledger,
.eligibility-inspector {
 display: flex;
 flex-direction: column;
}

.eligibility-subject-summary {
 min-height: 34px;
 margin-bottom: 8px;
 padding: 7px 8px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fbfcfd;
 color: var(--muted);
 font-size: 11px;
}

.eligibility-subject-summary strong {
 color: var(--text);
}

.eligibility-subject-search {
 flex: 0 0 38px;
 margin-bottom: 8px;
}

.eligibility-subjects-panel .eligibility-table-wrap {
 flex: 1;
 max-height: none;
 overflow-y: auto;
 overflow-x: hidden;
}

.eligibility-subject-table th:nth-child(1) { width: 38%; }
.eligibility-subject-table th:nth-child(2) { width: 20%; }
.eligibility-subject-table th:nth-child(3) { width: 42%; }

.eligibility-criterion-ledger {
 grid-area: review;
}

.eligibility-criterion-ledger .eligibility-rule-tabs {
 flex: 0 0 38px;
}

.eligibility-rule-tabs button {
 display: flex;
 align-items: center;
 justify-content: center;
 gap: 6px;
}

.eligibility-rule-tabs button span {
 min-width: 44px;
 color: inherit;
 font-size: 11px;
}

.eligibility-aggregate-strip {
 flex: 0 0 auto;
 min-height: 42px;
 margin-bottom: 8px;
 padding: 7px 8px;
 display: flex;
 align-items: center;
 flex-wrap: wrap;
 gap: 6px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fbfcfd;
}

.eligibility-aggregate-strip > span:last-child {
 color: var(--muted);
 font-size: 11px;
}

.eligibility-criterion-list {
 min-height: 0;
 flex: 1;
 overflow-y: auto;
 border: 1px solid var(--line);
 border-radius: 4px;
 scrollbar-width: thin;
}

.eligibility-criterion-row {
 width: 100%;
 min-height: 58px;
 padding: 8px;
 display: grid;
 grid-template-columns: 58px minmax(0, 1fr) minmax(104px, auto);
 gap: 8px;
 align-items: start;
 border: 0;
 border-bottom: 1px solid var(--soft-line);
 background: #fff;
 color: var(--text);
 text-align: left;
}

.eligibility-criterion-row:last-child {
 border-bottom: 0;
}

.eligibility-criterion-row:hover,
.eligibility-criterion-row.selected {
 background: #fff8f3;
}

.eligibility-criterion-row.selected {
 box-shadow: inset 3px 0 0 var(--orange);
}

.eligibility-criterion-id {
 color: var(--orange-dark);
 font-weight: 800;
 font-size: 12px;
}

.eligibility-criterion-text {
 display: -webkit-box;
 min-width: 0;
 overflow: hidden;
 -webkit-box-orient: vertical;
 -webkit-line-clamp: 3;
 font-size: 12px;
 line-height: 1.45;
 overflow-wrap: anywhere;
}

.eligibility-criterion-row .tag {
 max-width: 132px;
 white-space: normal;
 min-height: 26px;
 height: auto;
 line-height: 1.25;
 text-align: center;
}

.eligibility-inspector {
 grid-area: side;
}

.eligibility-inspector .icon-button {
 width: 34px;
 height: 34px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
}

.eligibility-inspector-scroll {
 min-height: 0;
 flex: 1;
 overflow-y: auto;
 padding-right: 3px;
 scrollbar-width: thin;
}

.eligibility-criterion-detail,
.eligibility-evidence-section,
.eligibility-ai-draft-block,
.eligibility-decision-block,
.eligibility-current-state {
 padding: 10px 0;
 border-top: 1px solid var(--soft-line);
}

.eligibility-criterion-detail {
 padding-top: 0;
 border-top: 0;
}

.eligibility-inspector-kicker,
.eligibility-subsection-head {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.eligibility-inspector-kicker > span,
.eligibility-subsection-head > span,
.eligibility-source-locator {
 color: var(--muted);
 font-size: 11px;
 overflow-wrap: anywhere;
}

.eligibility-criterion-detail > p,
.eligibility-ai-draft-block > p {
 margin: 8px 0;
 font-size: 13px;
 line-height: 1.55;
}

.eligibility-child-criteria {
 margin-top: 9px;
 display: grid;
 gap: 5px;
}

.eligibility-child-criteria > div {
 display: grid;
 grid-template-columns: 48px minmax(0, 1fr);
 gap: 7px;
 padding: 6px 7px;
 background: #f7f8fa;
}

.eligibility-child-criteria span {
 color: var(--muted);
 font-size: 11px;
}

.eligibility-child-criteria p {
 margin: 0;
 font-size: 11px;
 line-height: 1.45;
}

.eligibility-evidence-section {
 display: grid;
 gap: 6px;
}

.eligibility-evidence-option {
 min-width: 0;
 padding: 7px;
 display: grid;
 grid-template-columns: 18px minmax(0, 1fr) auto;
 gap: 7px;
 align-items: start;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fff;
}

.eligibility-evidence-option.selected {
 border-color: #db9b52;
 background: #fffaf5;
}

.eligibility-evidence-option > span {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.eligibility-evidence-option strong,
.eligibility-evidence-option small {
 overflow-wrap: anywhere;
}

.eligibility-evidence-option small {
 color: var(--muted);
 font-size: 10px;
 line-height: 1.35;
}

.eligibility-ai-draft-block {
 background: #f8fbff;
 padding-left: 8px;
 padding-right: 8px;
}

.eligibility-decision-block {
 display: grid;
 gap: 8px;
}

.eligibility-decision-block label {
 display: grid;
 gap: 5px;
 color: #4a5560;
 font-size: 12px;
 font-weight: 700;
}

.eligibility-decision-block select,
.eligibility-decision-block textarea {
 width: 100%;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
 padding: 8px;
 font: inherit;
 font-weight: 400;
 resize: vertical;
}

.eligibility-inline-warning {
 margin: 0;
 padding: 7px 8px;
 color: #7a3a0c;
 background: #fff6e7;
 font-size: 11px;
}

.eligibility-action-grid {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 7px;
}

.eligibility-action-grid button,
.eligibility-ai-draft-block .secondary-button,
.eligibility-conflict-banner .secondary-button,
.eligibility-review-retry {
 min-height: 34px;
 padding: 0 9px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 6px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
 font-weight: 700;
}

.eligibility-action-grid .primary-button {
 border-color: var(--orange);
 background: var(--orange);
 color: #fff;
}

.eligibility-action-grid button:disabled,
.eligibility-ai-draft-block button:disabled,
.eligibility-inspector .icon-button:disabled {
 cursor: not-allowed;
 opacity: 0.45;
}

.eligibility-current-state {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 4px 10px;
 color: var(--muted);
 font-size: 11px;
}

.eligibility-current-state strong {
 grid-column: 1 / -1;
 color: var(--text);
}

.eligibility-support-band {
 margin-top: 12px;
 display: grid;
 grid-template-columns: repeat(4, minmax(0, 1fr));
 gap: 0;
 padding: 0;
 overflow: hidden;
}

.eligibility-support-band > div {
 min-width: 0;
 min-height: 58px;
 padding: 9px 10px;
 display: grid;
 align-content: center;
 gap: 4px;
 border-right: 1px solid var(--soft-line);
 background: #fbfcfd;
}

.eligibility-support-band > div:last-child {
 border-right: 0;
}

.eligibility-support-band span {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.4;
 overflow-wrap: anywhere;
}

.eligibility-head-actions,
.eligibility-qc-pane-head,
.eligibility-qc-image-tools,
.eligibility-qc-paging,
.eligibility-qc-message {
 display: flex;
 align-items: center;
}

.eligibility-head-actions {
 justify-content: flex-end;
 gap: 8px;
}

.eligibility-qc-entry,
.eligibility-qc-return,
.eligibility-qc-message .secondary-button {
 min-height: 34px;
 padding: 0 10px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 6px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
 font-weight: 700;
}

.eligibility-qc-entry:hover,
.eligibility-qc-return:hover,
.eligibility-qc-message .secondary-button:hover {
 border-color: #d99854;
 background: #fff8f3;
}

.eligibility-qc-page {
 min-width: 0;
 height: calc(100vh - 72px);
 display: flex;
 flex-direction: column;
 overflow: hidden;
}

.eligibility-qc-boundary {
 min-height: 42px;
 margin-bottom: 10px;
 padding: 8px 10px;
 display: flex;
 align-items: center;
 gap: 8px;
 border: 1px solid #f0d4aa;
 border-left: 3px solid var(--warning);
 border-radius: 4px;
 background: #fffaf2;
 color: #66512f;
 font-size: 12px;
 line-height: 1.45;
}

.eligibility-qc-boundary svg {
 flex: 0 0 auto;
}

.eligibility-qc-message {
 min-height: 42px;
 margin-bottom: 10px;
 padding: 7px 10px;
 justify-content: space-between;
 gap: 12px;
 border: 1px solid var(--line);
 border-radius: 4px;
 font-size: 12px;
}

.eligibility-qc-message.error,
.eligibility-qc-message.conflict {
 border-color: #e4b067;
 background: #fffaf2;
 color: #744812;
}

.eligibility-qc-message.success {
 border-color: #aad0b7;
 background: var(--success-bg);
 color: var(--success);
}

.eligibility-qc-overflow {
 min-height: 0;
 flex: 1;
 overflow: auto;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: var(--surface);
}

.eligibility-qc-workspace {
 min-width: 1220px;
 min-height: 680px;
 height: 100%;
 display: grid;
 grid-template-columns: 300px minmax(520px, 1fr) 410px;
 background: #fff;
}

.eligibility-qc-queue-pane,
.eligibility-qc-image-pane,
.eligibility-qc-review-pane {
 min-width: 0;
 min-height: 0;
 display: flex;
 flex-direction: column;
 overflow: hidden;
}

.eligibility-qc-queue-pane,
.eligibility-qc-image-pane {
 border-right: 1px solid var(--line);
}

.eligibility-qc-pane-head {
 flex: 0 0 56px;
 min-width: 0;
 padding: 8px 10px;
 justify-content: space-between;
 gap: 10px;
 border-bottom: 1px solid var(--line);
 background: #fbfcfd;
}

.eligibility-qc-pane-head > div:first-child {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.eligibility-qc-pane-head strong {
 font-size: 13px;
}

.eligibility-qc-pane-head span {
 min-width: 0;
 color: var(--muted);
 font-size: 11px;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.eligibility-qc-pane-head .icon-button {
 width: 32px;
 height: 32px;
 flex: 0 0 auto;
}

.eligibility-qc-progress {
 padding: 8px 10px;
 display: grid;
 gap: 5px;
 border-bottom: 1px solid var(--soft-line);
 background: #fff;
}

.eligibility-qc-progress > div {
 display: flex;
 align-items: center;
 justify-content: space-between;
 color: var(--muted);
 font-size: 11px;
}

.eligibility-qc-progress > div strong {
 color: var(--text);
}

.eligibility-qc-progress > span {
 height: 5px;
 overflow: hidden;
 border-radius: 2px;
 background: #e9edf1;
}

.eligibility-qc-progress i {
 height: 100%;
 display: block;
 background: var(--orange);
}

.eligibility-qc-filters {
 padding: 7px 8px;
 display: grid;
 grid-template-columns: repeat(5, minmax(0, 1fr));
 gap: 4px;
 border-bottom: 1px solid var(--soft-line);
 background: #fbfcfd;
}

.eligibility-qc-filters button,
.eligibility-qc-image-tools button,
.eligibility-qc-paging button,
.eligibility-qc-result-options button {
 min-height: 30px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--muted);
 font-size: 11px;
}

.eligibility-qc-filters button.active,
.eligibility-qc-image-tools button.active {
 border-color: #d99854;
 background: #fff6ee;
 color: var(--orange-dark);
 font-weight: 700;
}

.eligibility-qc-queue-list {
 min-height: 0;
 flex: 1;
 overflow-y: auto;
 scrollbar-width: thin;
}

.eligibility-qc-queue-list > button {
 width: 100%;
 min-height: 58px;
 padding: 7px 8px;
 display: grid;
 grid-template-columns: 32px minmax(0, 1fr) auto;
 align-items: center;
 gap: 7px;
 border: 0;
 border-bottom: 1px solid var(--soft-line);
 background: #fff;
 color: var(--text);
 text-align: left;
}

.eligibility-qc-queue-list > button:hover,
.eligibility-qc-queue-list > button.selected {
 background: #fff8f3;
}

.eligibility-qc-queue-list > button.selected {
 box-shadow: inset 3px 0 0 var(--orange);
}

.eligibility-qc-sequence {
 color: #8a949e;
 font-size: 11px;
 font-variant-numeric: tabular-nums;
}

.eligibility-qc-queue-copy {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.eligibility-qc-queue-copy strong,
.eligibility-qc-queue-copy small {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.eligibility-qc-queue-copy strong {
 font-size: 12px;
}

.eligibility-qc-queue-copy small {
 color: var(--muted);
 font-size: 10px;
}

.eligibility-qc-queue-list .tag {
 max-width: 76px;
 min-height: 24px;
 padding: 2px 5px;
 white-space: normal;
 line-height: 1.2;
 text-align: center;
}

.eligibility-qc-empty {
 margin: 0;
 padding: 18px 12px;
 color: var(--muted);
 font-size: 12px;
 text-align: center;
}

.eligibility-qc-paging {
 flex: 0 0 42px;
 padding: 6px 8px;
 justify-content: space-between;
 gap: 6px;
 border-top: 1px solid var(--line);
 background: #fbfcfd;
}

.eligibility-qc-paging button {
 min-width: 64px;
 padding: 0 7px;
}

.eligibility-qc-paging span {
 color: var(--muted);
 font-size: 10px;
}

.eligibility-qc-image-tools {
 flex: 0 0 auto;
 gap: 4px;
}

.eligibility-qc-image-tools button {
 min-width: 32px;
 padding: 0 7px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
}

.eligibility-qc-image-tools span {
 width: 42px;
 color: var(--text);
 text-align: center;
 font-variant-numeric: tabular-nums;
}

.eligibility-qc-image-stage {
 min-height: 0;
 flex: 1;
 padding: 18px;
 overflow: auto;
 background: #eef1f4;
 text-align: center;
}

.eligibility-qc-image-stage img {
 display: block;
 max-width: none;
 margin: 0 auto;
 background: #fff;
 box-shadow: 0 1px 6px rgba(32, 36, 42, 0.18);
}

.eligibility-qc-image-stage img.fit {
 width: auto;
 height: auto;
 max-width: 100%;
 max-height: 100%;
}

.eligibility-qc-empty-stage {
 min-height: 100%;
 display: flex;
 align-items: center;
 justify-content: center;
 flex-direction: column;
 gap: 8px;
 color: var(--muted);
 font-size: 12px;
}

.eligibility-qc-review-scroll {
 min-height: 0;
 flex: 1;
 overflow-y: auto;
 scrollbar-width: thin;
}

.eligibility-qc-meta {
 margin: 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 border-bottom: 1px solid var(--line);
}

.eligibility-qc-meta > div {
 min-width: 0;
 padding: 8px 10px;
 display: grid;
 gap: 2px;
 border-right: 1px solid var(--soft-line);
 border-bottom: 1px solid var(--soft-line);
}

.eligibility-qc-meta > div:nth-child(2n) {
 border-right: 0;
}

.eligibility-qc-meta dt {
 color: var(--muted);
 font-size: 10px;
}

.eligibility-qc-meta dd {
 min-width: 0;
 margin: 0;
 overflow: hidden;
 color: var(--text);
 font-size: 11px;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.eligibility-qc-text-block,
.eligibility-qc-form {
 padding: 10px;
 border-bottom: 1px solid var(--line);
}

.eligibility-qc-text-block > div {
 margin-bottom: 7px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.eligibility-qc-text-block > div span {
 color: var(--muted);
 font-size: 10px;
}

.eligibility-qc-text-block pre {
 min-height: 220px;
 max-height: 330px;
 margin: 0;
 padding: 9px;
 overflow: auto;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fbfcfd;
 color: #30363d;
 font-family: inherit;
 font-size: 12px;
 line-height: 1.65;
 white-space: pre-wrap;
 word-break: break-word;
}

.eligibility-qc-form {
 display: grid;
 gap: 9px;
 border-bottom: 0;
}

.eligibility-qc-result-options {
 display: grid;
 grid-template-columns: repeat(3, minmax(0, 1fr));
 gap: 5px;
}

.eligibility-qc-result-options button {
 min-height: 38px;
 padding: 4px 6px;
 color: var(--text);
 line-height: 1.25;
}

.eligibility-qc-result-options button.active {
 font-weight: 700;
}

.eligibility-qc-result-options button.active.success {
 border-color: #83bb97;
 background: var(--success-bg);
 color: var(--success);
}

.eligibility-qc-result-options button.active.danger {
 border-color: #e3a5a5;
 background: var(--danger-bg);
 color: var(--danger);
}

.eligibility-qc-result-options button.active.warning {
 border-color: #e4b067;
 background: var(--warning-bg);
 color: var(--warning);
}

.eligibility-qc-form label {
 display: grid;
 gap: 5px;
 color: #4a5560;
 font-size: 11px;
 font-weight: 700;
}

.eligibility-qc-form select,
.eligibility-qc-form textarea {
 width: 100%;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
 padding: 8px;
 font: inherit;
 font-weight: 400;
}

.eligibility-qc-form textarea {
 resize: vertical;
}

.eligibility-qc-form > p {
 margin: 0;
 padding: 7px 8px;
 border-left: 3px solid var(--info);
 background: var(--info-bg);
 color: #37516f;
 font-size: 11px;
 line-height: 1.45;
}

.eligibility-qc-submit {
 min-height: 38px;
 justify-content: center;
}

@media (max-width: 900px) {
 .eligibility-head-actions {
 align-items: stretch;
 flex-direction: column;
 }

 .eligibility-qc-page {
 height: calc(100vh - 130px);
 }

 .eligibility-qc-boundary,
 .eligibility-qc-message {
 flex: 0 0 auto;
 }

 .eligibility-qc-overflow {
 overflow: auto;
 }

 .eligibility-qc-workspace {
 min-width: 1220px;
 }
}

.writing-runtime-gate-page {
 min-height: calc(100vh - 72px);
 display: grid;
 align-items: start;
}

.writing-runtime-gate {
 width: min(900px, calc(100% - 48px));
 margin: 72px auto 0;
 padding: 24px;
 display: grid;
 grid-template-columns: 44px minmax(0, 1fr) auto;
 gap: 16px;
 align-items: start;
 border: 1px solid #d8dee8;
 border-left: 4px solid #d97706;
 background: #fff;
 box-shadow: 0 8px 24px rgb(15 23 42 / 7%);
}

.writing-runtime-gate.checking {
 border-left-color: #2563eb;
}

.writing-runtime-gate-icon {
 width: 40px;
 height: 40px;
 display: grid;
 place-items: center;
 color: #b45309;
 background: #fff7ed;
 border: 1px solid #fed7aa;
}

.writing-runtime-gate.checking .writing-runtime-gate-icon {
 color: #1d4ed8;
 background: #eff6ff;
 border-color: #bfdbfe;
}

.writing-runtime-gate.checking .writing-runtime-gate-icon svg {
 animation: writing-runtime-spin 1.2s linear infinite;
}

.writing-runtime-gate-copy {
 min-width: 0;
}

.writing-runtime-gate-eyebrow {
 display: block;
 margin-bottom: 6px;
 color: #64748b;
 font-size: 12px;
 font-weight: 700;
}

.writing-runtime-gate h1 {
 margin: 0;
 color: #172033;
 font-size: 20px;
 line-height: 1.4;
}

.writing-runtime-gate p,
.writing-runtime-gate li {
 color: #475569;
 font-size: 14px;
 line-height: 1.7;
}

.writing-runtime-gate p {
 margin: 10px 0 0;
}

.writing-runtime-gate ul {
 margin: 10px 0 0;
 padding-left: 20px;
}

.writing-runtime-gate-meta {
 margin-top: 16px;
 display: flex;
 flex-wrap: wrap;
 gap: 6px 14px;
 color: #64748b;
 font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
 font-size: 11px;
}

.writing-runtime-gate > button {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 white-space: nowrap;
}

@keyframes writing-runtime-spin {
 to { transform: rotate(360deg); }
}

.writing-study-schema-layout {
 grid-template-columns: minmax(0, 1fr);
}

.writing-study-schema-layout .writing-editor-core {
 min-width: 0;
}

.study-schema-editor {
 display: flex;
 flex-direction: column;
 min-height: 680px;
 border: 1px solid var(--line);
 background: var(--surface);
 color: var(--text);
}

.study-schema-editor.is-fullscreen {
 position: fixed;
 inset: 16px;
 z-index: 160;
 min-height: 0;
 box-shadow: 0 20px 70px rgba(22, 31, 40, 0.24);
}

.study-schema-toolbar {
 min-height: 62px;
 padding: 10px 12px 10px 16px;
 border-bottom: 1px solid var(--line);
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 16px;
 background: #fbfcfd;
}

.study-schema-toolbar > div:first-child {
 min-width: 0;
 display: grid;
 grid-template-columns: auto minmax(0, auto) auto;
 align-items: baseline;
 column-gap: 10px;
}

.study-schema-toolbar span,
.study-schema-toolbar small {
 color: var(--muted);
}

.study-schema-toolbar strong {
 font-size: 16px;
}

.study-schema-toolbar small {
 font-size: 12px;
}

.study-schema-toolbar .study-schema-output-hint {
 padding-left: 8px;
 border-left: 1px solid var(--line);
 color: var(--info);
 font-weight: 700;
}

.study-schema-toolbar-actions {
 display: flex;
 gap: 6px;
 align-items: center;
 flex: 0 0 auto;
}

.study-schema-zoom {
 height: 32px;
 display: grid;
 grid-template-columns: 30px 44px 30px;
 align-items: center;
 border: 1px solid var(--line);
 background: #fff;
}

.study-schema-zoom button {
 width: 30px;
 height: 30px;
 padding: 0;
 border: 0;
 background: transparent;
 color: var(--text);
 display: inline-flex;
 align-items: center;
 justify-content: center;
}

.study-schema-zoom span {
 color: var(--muted);
 font-size: 11px;
 text-align: center;
}

.study-schema-toolbar-actions button,
.study-schema-add,
.study-schema-fact-state button,
.study-schema-nudge button,
.study-schema-inspector .danger-button {
 min-height: 32px;
 padding: 6px 9px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 5px;
}

.study-schema-workspace {
 min-height: 530px;
 flex: 1 1 auto;
 display: grid;
 grid-template-columns: 250px minmax(520px, 1fr) 286px;
 overflow: hidden;
}

.study-schema-structure,
.study-schema-inspector {
 min-width: 0;
 background: #fbfcfd;
 overflow: auto;
}

.study-schema-structure {
 border-right: 1px solid var(--line);
}

.study-schema-inspector {
 border-left: 1px solid var(--line);
 padding: 14px;
}

.study-schema-tabs {
 display: grid;
 grid-template-columns: repeat(3, 1fr);
 border-bottom: 1px solid var(--line);
 background: #fff;
}

.study-schema-tabs button {
 height: 40px;
 border: 0;
 border-bottom: 2px solid transparent;
 background: transparent;
 color: var(--muted);
}

.study-schema-tabs button.active {
 border-bottom-color: var(--orange);
 color: var(--orange-dark);
 font-weight: 700;
}

.study-schema-list {
 display: flex;
 flex-direction: column;
 gap: 7px;
 padding: 10px;
}

.study-schema-list-item {
 width: 100%;
 min-height: 58px;
 padding: 8px 9px;
 border: 1px solid transparent;
 border-radius: 4px;
 background: transparent;
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 gap: 2px 8px;
 text-align: left;
}

.study-schema-list-item:hover {
 background: #fff;
 border-color: var(--line);
}

.study-schema-list-item.active {
 background: #fff7f1;
 border-color: #f2b58f;
}

.study-schema-list-item span {
 grid-column: 1;
 color: var(--muted);
 font-size: 12px;
}

.study-schema-list-item strong {
 grid-column: 1;
 min-width: 0;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.study-schema-list-item svg {
 grid-column: 2;
 grid-row: 1 / 3;
 align-self: center;
 color: var(--warning);
}

.study-schema-list-item:has(svg[data-lucide="circle-check-big"]) svg {
 color: var(--success);
}

.study-schema-add {
 width: 100%;
 border-style: dashed;
 color: var(--info);
}

.study-schema-form-row {
 padding: 10px;
 border: 1px solid var(--line);
 background: #fff;
}

.study-schema-form-row label,
.study-schema-inspector label,
.study-schema-commit label {
 display: flex;
 flex-direction: column;
 gap: 5px;
}

.study-schema-form-row label > span,
.study-schema-inspector label > span,
.study-schema-commit label > span,
.study-schema-nudge > span {
 color: var(--muted);
 font-size: 12px;
}

.study-schema-form-row input,
.study-schema-form-row select,
.study-schema-inspector input,
.study-schema-inspector select,
.study-schema-inspector textarea,
.study-schema-commit input {
 width: 100%;
 min-height: 34px;
 padding: 7px 8px;
 border: 1px solid #cfd5dc;
 border-radius: 3px;
 background: #fff;
 color: var(--text);
}

.study-schema-inspector textarea {
 resize: vertical;
 line-height: 1.55;
}

.study-schema-inline-fields {
 display: grid;
 grid-template-columns: minmax(76px, 0.7fr) minmax(120px, 1.3fr);
 gap: 8px;
 margin-top: 8px;
}

.study-schema-canvas-column {
 min-width: 0;
 display: flex;
 flex-direction: column;
 background: #f3f5f7;
}

.study-schema-canvas {
 flex: 1 1 auto;
 min-height: 480px;
 padding: 20px;
 overflow: auto;
 display: flex;
 align-items: center;
 justify-content: center;
 background-color: #f8f9fb;
 background-image: linear-gradient(#e9edf1 1px, transparent 1px), linear-gradient(90deg, #e9edf1 1px, transparent 1px);
 background-size: 24px 24px;
}

.study-schema-canvas img {
 display: block;
 flex: 0 0 auto;
 max-width: none;
 min-width: min(100%, 780px);
 height: auto;
 border: 1px solid #d7dce2;
 background: #fff;
 box-shadow: 0 4px 14px rgba(31, 42, 53, 0.08);
}

.study-schema-canvas-placeholder,
.study-schema-inspector-empty {
 color: var(--muted);
 text-align: center;
}

.study-schema-legend {
 min-height: 38px;
 padding: 9px 14px;
 border-top: 1px solid var(--line);
 display: flex;
 gap: 18px;
 align-items: center;
 color: var(--muted);
 font-size: 12px;
 background: #fff;
}

.study-schema-legend span {
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.study-schema-legend i {
 width: 10px;
 height: 10px;
 border-radius: 2px;
}

.study-schema-legend i.candidate {
 background: #f59f00;
}

.study-schema-legend i.confirmed {
 background: #1f7a42;
}

.study-schema-inspector > header {
 display: flex;
 flex-direction: column;
 gap: 3px;
 margin-bottom: 14px;
 padding-bottom: 10px;
 border-bottom: 1px solid var(--line);
}

.study-schema-inspector > header span {
 color: var(--muted);
 font-size: 12px;
}

.study-schema-inspector > label {
 margin-bottom: 11px;
}

.study-schema-fact-state {
 margin: 14px 0;
 padding: 10px;
 border-left: 3px solid var(--warning);
 background: var(--warning-bg);
 display: grid;
 grid-template-columns: 1fr auto;
 gap: 4px 8px;
}

.study-schema-fact-state span {
 color: var(--muted);
 font-size: 12px;
}

.study-schema-fact-state button {
 grid-column: 1 / -1;
 margin-top: 5px;
}

.study-schema-nudge {
 margin: 12px 0;
 padding-top: 12px;
 border-top: 1px solid var(--line);
}

.study-schema-nudge > div {
 display: grid;
 grid-template-columns: repeat(4, 34px);
 gap: 5px;
 margin: 7px 0;
}

.study-schema-nudge button {
 width: 34px;
 height: 32px;
 padding: 0;
}

.study-schema-nudge small {
 color: var(--muted);
 line-height: 1.5;
}

.study-schema-inspector .danger-button {
 width: 100%;
 margin-top: 8px;
 border-color: #efb6b6;
 color: var(--danger);
}

.study-schema-empty {
 min-height: 560px;
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 gap: 10px;
 text-align: center;
}

.study-schema-empty p {
 max-width: 520px;
 margin: 0;
 color: var(--muted);
}

.study-schema-footer {
 min-height: 82px;
 padding: 10px 14px;
 border-top: 1px solid var(--line);
 display: grid;
 grid-template-columns: minmax(260px, 1fr) minmax(420px, 0.9fr);
 gap: 18px;
 align-items: center;
 background: #fff;
}

.study-schema-issues {
 min-width: 0;
 display: flex;
 flex-direction: column;
 gap: 2px;
}

.study-schema-issues span,
.study-schema-issues small {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
 color: var(--muted);
 font-size: 12px;
}

.study-schema-issues span.blocker {
 color: var(--danger);
}

.study-schema-commit {
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 gap: 8px;
 align-items: end;
}

.study-schema-commit button {
 height: 34px;
}

.study-schema-message {
 margin: 0;
 padding: 7px 14px;
 border-top: 1px solid #cfe1f9;
 color: var(--info);
 background: var(--info-bg);
 font-size: 12px;
}

.study-schema-message.danger {
 border-top-color: #efb6b6;
 color: var(--danger);
 background: var(--danger-bg);
}

@media (max-width: 1280px) {
 .study-schema-workspace {
 grid-template-columns: 220px minmax(500px, 1fr) 260px;
 }

 .study-schema-toolbar > div:first-child {
 grid-template-columns: auto minmax(0, 1fr);
 }

 .study-schema-toolbar small {
 grid-column: 1 / -1;
 }
}

.audit-box {
 border: 1px solid var(--line);
 border-radius: 4px;
 margin-top: 10px;
 padding: 10px;
 display: grid;
 gap: 4px;
 background: #fbfcfd;
}

.audit-box span {
 color: var(--muted);
 font-size: 12px;
 overflow-wrap: anywhere;
}

.writing-layout {
 display: grid;
 grid-template-columns: minmax(720px, 1.72fr) minmax(360px, 0.72fr);
 grid-template-areas: "editor ai";
 gap: 12px;
 align-items: stretch;
}

.writing-editor-first-layout {
 min-height: 760px;
}

.writing-layout.writing-pre-document-layout {
 grid-template-columns: minmax(0, 1fr);
 grid-template-areas: "editor";
 min-height: 680px;
 height: auto;
}

.writing-pre-document-core {
 min-width: 0;
 min-height: 680px;
}

@media (min-width: 1281px) {
 .writing-editor-first-layout {
 height: min(820px, calc(100vh - 158px));
 min-height: 720px;
 }
}

@media (min-width: 1281px) and (max-height: 850px) {
 .writing-editor-first-layout,
 .writing-layout.writing-pre-document-layout {
 height: calc(100vh - 162px);
 min-height: 0;
 }

 .writing-layout.writing-pre-document-layout > .writing-pre-document-core {
 min-height: 0;
 }
}

.writing-section-strip {
 padding: 12px;
 margin-bottom: 0;
}

.writing-title-actions {
 display: flex;
 align-items: center;
 gap: 6px;
}

.writing-title-actions > button {
 min-height: 36px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.writing-title-actions > .writing-study-consistency-trigger {
