.writing-study-rebind-summary {
 display: grid;
 grid-template-columns: repeat(3, minmax(0, 1fr));
 border-top: 1px solid var(--line);
 border-bottom: 1px solid var(--line);
}

.writing-study-rebind-summary > div {
 padding: 9px 12px;
 display: grid;
 gap: 2px;
 border-right: 1px solid var(--line);
}

.writing-study-rebind-summary > div:last-child {
 border-right: 0;
}

.writing-study-rebind-summary span,
.writing-study-rebind-section-list small {
 color: var(--muted);
 font-size: 11px;
}

.writing-study-rebind-summary strong {
 font-size: 15px;
}

.writing-study-rebind-scope-note {
 margin: 0;
 padding: 9px 11px;
 border-left: 3px solid var(--orange);
 background: #fff9f2;
 color: var(--text-secondary);
 font-size: 12px;
 line-height: 1.6;
}

.writing-study-rebind-details {
 min-height: 0;
 overflow: hidden;
 border: 1px solid var(--line);
 background: #fff;
}

.writing-study-rebind-details[open] {
 display: grid;
 grid-template-rows: auto minmax(0, 1fr);
}

.writing-study-rebind-details > summary {
 min-height: 40px;
 padding: 0 11px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 color: var(--text);
 font-size: 12px;
 font-weight: 600;
 cursor: pointer;
}

.writing-study-rebind-details > summary span {
 color: var(--muted);
 font-size: 11px;
 font-weight: 400;
}

.writing-study-rebind-section-list {
 min-height: 0;
 overflow: auto;
 border-top: 1px solid var(--line);
}

.writing-study-rebind-section-list > div,
.writing-study-rebind-section-list > button {
 width: 100%;
 min-height: 44px;
 padding: 8px 10px;
 border: 0;
 border-bottom: 1px solid var(--line);
 border-radius: 0;
 background: #fff;
 display: grid;
 grid-template-columns: 62px minmax(0, 1fr) auto;
 align-items: center;
 gap: 8px;
 text-align: left;
}

.writing-study-rebind-section-list > button.active {
 background: #fff8f1;
 box-shadow: inset 3px 0 0 var(--orange);
}

.writing-study-rebind-section-list > div small {
 grid-column: 2 / -1;
}

.writing-study-reconciliation-form {
 display: grid;
 gap: 9px;
}

.writing-study-reconciliation-form > p {
 margin: 0;
 color: var(--muted);
 font-size: 12px;
 line-height: 1.5;
}

.writing-study-reconciliation-form > label:not(.writing-study-rebind-check) {
 display: grid;
 gap: 5px;
 font-size: 12px;
 font-weight: 600;
}

.writing-study-reconciliation-form textarea {
 min-height: 76px;
 resize: vertical;
}

.writing-study-rebind-check {
 display: grid;
 grid-template-columns: 16px minmax(0, 1fr);
 gap: 8px;
 align-items: start;
 font-size: 12px;
 line-height: 1.5;
}

.writing-study-rebind-check input {
 width: 14px;
 height: 14px;
 margin-top: 3px;
}

.writing-study-rebind-drawer > footer {
 justify-content: flex-end;
 align-items: center;
 padding-top: 10px;
 padding-bottom: 0;
 border-top: 1px solid var(--line);
 border-bottom: 0;
}

.writing-study-rebind-drawer > footer button {
 min-height: 34px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.new-project-trigger {
 min-height: 38px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
 white-space: nowrap;
}

.modal-backdrop {
 position: fixed;
 inset: 0;
 z-index: 100;
 background: rgba(29, 37, 45, 0.32);
 display: grid;
 place-items: center;
 padding: 24px;
}

.new-project-dialog {
 width: min(980px, calc(100vw - 48px));
 max-height: calc(100vh - 48px);
 overflow-y: auto;
 padding: 22px;
}

.new-project-dialog > header,
.new-project-dialog > footer {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
}

.new-project-dialog > header {
 padding-bottom: 16px;
 border-bottom: 1px solid var(--line);
}

.new-project-dialog > header span {
 color: var(--orange-dark);
 font-size: 12px;
 font-weight: 700;
}

.new-project-dialog > header h2 {
 margin: 4px 0 0;
 font-size: 21px;
}

.new-project-entry-mode {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 10px;
 margin: 18px 0;
}

.new-project-entry-mode button {
 min-height: 78px;
 display: grid;
 grid-template-columns: auto 1fr;
 grid-template-rows: auto auto;
 align-items: center;
 column-gap: 10px;
 text-align: left;
 background: #fff;
 border: 1px solid var(--line);
 padding: 12px;
}

.new-project-entry-mode button.active {
 border-color: var(--orange);
 background: #fff8f3;
}

.new-project-entry-mode button svg {
 grid-row: 1 / 3;
 color: var(--orange-dark);
}

.new-project-entry-mode button span {
 color: var(--muted);
 font-size: 12px;
}

.new-project-fields {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 12px;
}

.new-project-fields label {
 display: grid;
 gap: 6px;
 color: #46515b;
 font-size: 12px;
}

.new-project-fields input,
.new-project-fields select {
 width: 100%;
 min-height: 38px;
}

.new-project-fields [aria-invalid="true"] {
 border-color: var(--danger);
 box-shadow: 0 0 0 1px rgba(197, 55, 48, 0.12);
}

.new-project-field-error {
 color: var(--danger);
 font-size: 11px;
 line-height: 1.35;
}

.new-project-dialog > footer {
 justify-content: flex-end;
 margin-top: 18px;
 padding-top: 16px;
 border-top: 1px solid var(--line);
}

.new-project-message {
 margin: 12px 0 0;
 color: var(--danger);
 font-size: 13px;
}

.file-first-synopsis-intake,
.file-first-synopsis-review {
 display: grid;
 gap: 14px;
}

.file-first-dropzone {
 min-height: 150px;
 position: relative;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr) auto;
 align-items: center;
 gap: 16px;
 padding: 24px;
 border: 1px dashed #d5a26d;
 background: #fffaf6;
}

.file-first-dropzone > input {
 position: absolute;
 inset: 0;
 width: 100%;
 height: 100%;
 opacity: 0;
 cursor: pointer;
}

.file-first-dropzone > svg {
 color: var(--orange-dark);
}

.file-first-dropzone > div {
 display: grid;
 gap: 5px;
}

.file-first-dropzone > div span {
 color: var(--muted);
 font-size: 12px;
}

.file-first-dropzone > button {
 position: relative;
 z-index: 1;
 display: inline-flex;
 align-items: center;
 gap: 6px;
 border-color: var(--orange);
 color: var(--orange-dark);
 background: #fff;
}

.file-first-progress,
.file-first-error {
 display: flex;
 align-items: center;
 gap: 10px;
 padding: 12px 14px;
 border: 1px solid var(--line);
 background: #f8fafb;
}

.file-first-progress > svg {
 color: var(--orange-dark);
}

.file-first-progress > div {
 flex: 1;
 display: grid;
 gap: 3px;
}

.file-first-progress > button {
 min-height: 30px;
 padding: 0 10px;
 background: #fff;
}

.file-first-progress span {
 color: var(--muted);
 font-size: 12px;
}

.file-first-error {
 color: var(--danger);
 border-color: #efc6c3;
 background: #fff8f7;
}

.file-first-error span {
 flex: 1;
}

.file-first-error button,
.file-first-synopsis-review > header button {
 display: inline-flex;
 align-items: center;
 gap: 5px;
}

.file-first-synopsis-review > header,
.file-first-synopsis-review > footer {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
}

.file-first-synopsis-review > header {
 padding: 10px 12px;
 border-left: 3px solid var(--orange);
 background: #fff8f3;
}

.file-first-synopsis-review > header > div {
 display: grid;
 gap: 3px;
 min-width: 0;
}

.file-first-synopsis-review > header span {
 color: var(--orange-dark);
 font-size: 11px;
 font-weight: 700;
}

.file-first-synopsis-review > header strong {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.file-first-core-fields {
 display: grid;
 grid-template-columns: repeat(4, minmax(0, 1fr));
 gap: 10px;
}

.file-first-core-fields label,
.file-first-design-summary label {
 display: grid;
 gap: 5px;
 color: #46515b;
 font-size: 12px;
}

.file-first-core-fields label.span-2 {
 grid-column: span 2;
}

.file-first-core-fields input,
.file-first-core-fields select,
.file-first-design-summary textarea,
.file-first-warnings textarea {
 width: 100%;
}

.file-first-design-summary {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 10px;
}

.file-first-design-summary textarea {
 min-height: 66px;
 resize: vertical;
}

.file-first-findings {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 10px;
}

.file-first-findings > div {
 display: grid;
 gap: 4px;
 padding: 10px 12px;
 border: 1px solid var(--line);
 background: #fbfcfd;
}

.file-first-findings span {
 color: var(--muted);
 font-size: 12px;
 line-height: 1.55;
}

.file-first-warnings {
 display: grid;
 gap: 8px;
 padding: 12px;
 border: 1px solid #efcf9c;
 background: #fffaf0;
}

.file-first-warnings label {
 display: flex;
 align-items: flex-start;
 gap: 8px;
 font-size: 12px;
}

.file-first-synopsis-review > footer {
 padding-top: 13px;
 border-top: 1px solid var(--line);
}

.file-first-synopsis-review > footer > span {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 color: #57636d;
 font-size: 12px;
}

.file-first-synopsis-review > footer button {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 min-width: 154px;
 justify-content: center;
}

.file-first-inline-error {
 margin: 0;
 display: flex;
 align-items: center;
 gap: 6px;
 color: var(--danger);
 font-size: 12px;
}

.module-error-state {
 min-height: 180px;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr) auto;
 align-items: center;
 gap: 16px;
 border-left: 3px solid var(--danger);
}

.module-error-state p {
 margin: 5px 0 0;
 color: var(--muted);
}

.monitoring-read-unavailable {
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 align-items: start;
 gap: 12px;
 border-left: 3px solid var(--orange);
 background: #fffaf5;
 color: var(--text);
}

.monitoring-read-unavailable > svg {
 color: var(--orange);
 margin-top: 1px;
}

.monitoring-read-unavailable strong {
 display: block;
 font-size: 14px;
}

.monitoring-read-unavailable p {
 margin: 5px 0 0;
 color: var(--muted);
 line-height: 1.55;
}

.monitoring-read-unavailable small {
 display: block;
 margin-top: 7px;
 color: var(--muted);
 font-size: 11px;
}

.monitoring-read-unavailable.is-compact {
 margin: 8px 0 0;
 padding: 9px 10px;
}

.monitoring-read-pending {
 border-left: 3px solid var(--brand);
 background: #f7fbfe;
}

.monitoring-read-pending strong {
 display: block;
 font-size: 14px;
}

.monitoring-read-pending p {
 margin: 5px 0 0;
 color: var(--muted);
 line-height: 1.55;
}

.writing-ai-core .revision-thread-list,
.writing-ai-core .revision-thread,
.writing-ai-core .export-gate,
.writing-ai-core .selected-text,
.writing-ai-core .revision-evidence-package,
.writing-ai-core .revision-form > p:not(.revision-message) {
 display: none;
}

.writing-ai-candidates {
 display: grid;
 gap: 9px;
 padding: 12px;
 border-top: 1px solid var(--line);
 overflow-y: auto;
}

.writing-ai-candidates > header,
.writing-ai-candidates article > div {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.writing-ai-candidates > header span,
.writing-ai-candidates > header strong {
 display: block;
}

.writing-ai-candidates > header span {
 color: var(--muted);
 font-size: 11px;
}

.writing-ai-candidates > header strong {
 margin-top: 2px;
 font-size: 14px;
}

.writing-ai-candidates > header em {
 color: var(--muted);
 font-size: 12px;
 font-style: normal;
}

.writing-ai-candidates article {
 border: 1px solid var(--soft-line);
 border-left: 3px solid #6687b9;
 padding: 10px;
 background: #fff;
}

.writing-ai-candidates article p {
 max-height: 112px;
 margin: 8px 0;
 overflow-y: auto;
 color: #36414b;
 font-size: 13px;
 line-height: 1.55;
}

.writing-ai-candidates article > button {
 min-height: 32px;
 display: inline-flex;
 align-items: center;
 gap: 5px;
}

.writing-document-map {
 grid-area: map;
 min-height: 760px;
 border-top: 3px solid #8b7652;
 display: grid;
 grid-template-rows: auto auto minmax(0, 1fr);
 gap: 10px;
 align-content: start;
 overflow: hidden;
}

.writing-section-strip-head {
 min-height: 28px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 padding-bottom: 8px;
 border-bottom: 1px solid var(--soft-line);
 color: var(--muted);
 font-size: 12px;
}

.writing-section-strip-head strong {
 min-width: 0;
 color: var(--text);
 font-size: 14px;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.writing-map-summary {
 display: grid;
 grid-template-columns: 1fr;
 gap: 6px;
}

.writing-map-summary > div {
 min-width: 0;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 8px;
 background: #fbfcfd;
}

.writing-map-summary strong {
 display: block;
 color: var(--text);
 font-size: 15px;
}

.writing-map-summary span {
 display: block;
 margin-top: 2px;
 color: var(--muted);
 font-size: 11px;
}

.writing-section-buttons {
 min-height: 0;
 display: grid;
 gap: 8px;
 padding-top: 0;
 overflow-x: hidden;
 overflow-y: auto;
 scrollbar-width: thin;
}

.writing-section-buttons button {
 --writing-section-depth: 0;
 width: 100%;
 min-height: 58px;
 grid-template-columns: 1fr auto;
 padding: 8px;
 margin-bottom: 0;
}

.writing-section-buttons button > span {
 min-width: 0;
 padding-left: calc(var(--writing-section-depth) * 10px);
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.writing-section-buttons button.root-section > span {
 font-weight: 700;
}

.writing-section-buttons button.nested-section > span {
 border-left: 2px solid #d9dee5;
}

.section-tree .progress,
.writing-section-buttons .progress {
 grid-column: 1 / -1;
}

.editor-panel {
 grid-area: editor;
 min-height: 760px;
 min-width: 0;
 border-top: 3px solid var(--orange);
 display: flex;
 flex-direction: column;
 overflow: hidden;
}

.editor-toolbar {
 display: flex;
 gap: 6px;
 flex-wrap: wrap;
 border-bottom: 1px solid var(--line);
 padding-bottom: 10px;
 margin-bottom: 14px;
}

.approval-lock {
 min-height: 36px;
 border: 1px solid #bfe4c9;
 border-radius: 4px;
 display: flex;
 align-items: center;
 gap: 8px;
 padding: 8px 10px;
 margin-bottom: 10px;
 background: var(--success-bg);
 color: var(--success);
 font-size: 13px;
}

.approval-lock.warning {
 border-color: #ffd99d;
 background: var(--warning-bg);
 color: var(--warning);
}

.writing-editor-availability-note {
 margin: 5px 2px 0;
 color: var(--muted);
 font-size: 11px;
 line-height: 1.4;
}

.approval-lock.working-copy-active-note {
 border-color: #bdd2ff;
 background: var(--info-bg);
 color: var(--info);
}

.approval-lock > span {
 min-width: 0;
 flex: 1 1 auto;
 overflow-wrap: anywhere;
}

.working-copy-status-bar {
 border: 1px solid var(--line);
 border-left: 3px solid var(--orange);
 border-radius: 4px;
 padding: 4px 6px;
 margin-bottom: 5px;
 background: #fbfcfd;
 display: grid;
 grid-template-columns: minmax(300px, 0.75fr) minmax(0, 1.55fr);
 align-items: center;
 gap: 6px;
}

.writing-intervention-projection-conflict {
 min-height: 42px;
 margin-bottom: 7px;
 padding: 7px 9px;
 border: 1px solid #e5b56f;
 border-left: 3px solid #b85c20;
 background: #fffaf2;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
}

.writing-intervention-projection-conflict > div:first-child {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 gap: 8px;
 color: #7e4219;
}

.writing-intervention-projection-conflict span {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.writing-intervention-projection-conflict strong {
 font-size: 12px;
}

.writing-intervention-projection-conflict small {
 color: #8b6849;
 font-size: 11px;
 overflow-wrap: anywhere;
}

.writing-intervention-projection-conflict-actions {
 display: flex;
 flex: 0 0 auto;
 gap: 6px;
}

.writing-intervention-projection-conflict-actions button {
 min-height: 30px;
 white-space: nowrap;
}

.working-copy-status-main {
 display: flex;
 gap: 6px;
 align-items: center;
 min-width: 0;
}

.working-copy-status-main > .working-copy-identity {
 min-width: 0;
 display: flex;
 align-items: baseline;
 gap: 5px;
}

.working-copy-status-main span,
.working-copy-status-main time,
.working-copy-status-bar > p {
 color: var(--muted);
 font-size: 11px;
}

.working-copy-status-main strong {
 min-width: 0;
 font-size: 12px;
 overflow-wrap: anywhere;
}

.working-copy-status-main .working-copy-save-state {
 padding-left: 6px;
 border-left: 1px solid var(--soft-line);
 white-space: nowrap;
}

.working-copy-status-main time {
 margin-left: auto;
 white-space: nowrap;
}

.working-copy-status-bar > p {
 margin: 0;
}

.working-copy-actions {
 display: flex;
 flex-wrap: nowrap;
 justify-content: flex-end;
 gap: 5px;
 overflow-x: auto;
}

.working-copy-actions button {
 min-height: 26px;
 padding: 0 7px;
 display: inline-flex;
 align-items: center;
 gap: 4px;
 font-size: 12px;
}

.working-copy-actions .content-quality-trigger.has-blocking {
 border-color: #efb58f;
 background: #fff7f2;
 color: #a44712;
}

.working-copy-actions .content-quality-trigger.is-clear {
 border-color: #b9d9c2;
 background: #f3fbf5;
 color: #24663a;
}

.document-export-progress {
 grid-column: 1 / -1;
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(120px, 0.3fr) minmax(0, 1fr) auto;
 align-items: center;
 gap: 8px;
 padding: 2px 2px 0;
 color: var(--muted);
 font-size: 11px;
}

.document-export-progress-track {
 height: 4px;
 border-radius: 2px;
 overflow: hidden;
 background: #e2e7ed;
}

.document-export-progress-track > span {
 display: block;
 height: 100%;
 border-radius: inherit;
 background: var(--orange);
 transition: width 180ms ease;
}

.document-export-progress strong {
 min-width: 0;
 overflow: hidden;
 color: var(--text);
 font-size: 11px;
 font-weight: 600;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.document-export-progress > span {
 white-space: nowrap;
}

.medical-writing-preview-panel {
 margin: 0 0 8px;
 padding: 10px 12px;
 border: 1px solid #e4b36f;
 border-left: 3px solid #c87919;
 border-radius: 6px;
 background: #fffaf2;
 color: var(--text);
}

.medical-writing-preview-panel.verified {
 border-color: #b8d9c0;
 border-left-color: #2f7b45;
 background: #f5fbf6;
}

.medical-writing-preview-panel.stale {
 border-color: #e5b3b3;
 border-left-color: #b33d3d;
 background: #fff7f7;
}

.medical-writing-preview-panel-header,
.medical-writing-preview-panel-actions,
.medical-writing-preview-summary,
.medical-writing-preview-meta {
 display: flex;
 align-items: center;
}

.medical-writing-preview-panel-header {
 justify-content: space-between;
 gap: 10px;
}

.medical-writing-preview-panel-header > div:first-child {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.medical-writing-preview-eyebrow {
 color: var(--muted);
 font-size: 10px;
}

.medical-writing-preview-panel-header strong {
 font-size: 13px;
}

.medical-writing-preview-panel-actions {
 gap: 4px;
}

.medical-writing-preview-panel-actions button {
 min-height: 25px;
 padding: 0 7px;
 display: inline-flex;
 align-items: center;
 gap: 4px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
 font-size: 11px;
}

.medical-writing-preview-panel-actions .medical-writing-preview-close {
 width: 25px;
 justify-content: center;
 padding: 0;
}

.medical-writing-preview-summary {
 align-items: flex-start;
 gap: 12px;
 margin-top: 8px;
}

.medical-writing-preview-page-count {
 flex: 0 0 auto;
 display: flex;
 align-items: center;
 gap: 6px;
 color: #a44712;
}

.medical-writing-preview-panel.verified .medical-writing-preview-page-count {
 color: #24663a;
}

.medical-writing-preview-page-count span {
 display: grid;
 gap: 1px;
}

.medical-writing-preview-page-count strong {
 font-size: 16px;
}

.medical-writing-preview-page-count small {
 color: var(--muted);
 font-size: 10px;
 white-space: nowrap;
}

.medical-writing-preview-summary p,
.medical-writing-preview-warning,
.medical-writing-preview-message,
.medical-writing-preview-more {
 margin: 0;
 font-size: 11px;
 line-height: 1.5;
}

.medical-writing-preview-summary p {
 color: var(--muted);
}

.medical-writing-preview-warning {
 margin-top: 7px;
 color: #7e4b10;
}

.medical-writing-preview-panel.verified .medical-writing-preview-warning {
 color: #24663a;
}

.medical-writing-preview-message {
 margin-top: 6px;
 color: #a44712;
}

.medical-writing-preview-meta {
 flex-wrap: wrap;
 gap: 8px 14px;
 margin-top: 8px;
 color: var(--muted);
 font-size: 10px;
}

.medical-writing-preview-meta code {
 padding: 1px 3px;
 border-radius: 3px;
 background: rgba(0, 0, 0, 0.04);
 color: var(--text);
 font-size: 10px;
}

.medical-writing-preview-pages {
 display: grid;
 grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
 gap: 5px;
 margin: 8px 0 0;
 padding: 0;
 list-style: none;
}

.medical-writing-preview-pages li {
 min-width: 0;
 padding: 5px 7px;
 display: grid;
 gap: 2px;
 border: 1px solid rgba(123, 91, 45, 0.18);
 border-radius: 4px;
 background: rgba(255, 255, 255, 0.7);
}

.medical-writing-preview-pages li span {
 font-size: 11px;
 font-weight: 650;
}

.medical-writing-preview-pages li small {
 color: var(--muted);
 font-size: 10px;
}

.medical-writing-preview-more {
 margin-top: 7px;
 color: var(--muted);
}

.approval-lock button {
 min-height: 28px;
 flex: 0 0 auto;
 white-space: nowrap;
}

.writing-editor-blocker {
 min-height: 34px;
 margin-bottom: 5px;
 padding: 4px 7px;
 border: 1px solid #e5b56f;
 border-left: 3px solid #c87919;
 border-radius: 3px;
 background: #fffaf2;
 display: flex;
 align-items: center;
 gap: 7px;
 color: #7e4b10;
}

.writing-editor-blocker > strong {
 min-width: 0;
 flex: 1 1 auto;
 color: var(--text);
 font-size: 12px;
 line-height: 1.35;
}

.writing-editor-blocker details {
 position: relative;
 flex: 0 0 auto;
 color: var(--muted);
 font-size: 11px;
}

.writing-editor-blocker summary {
 cursor: pointer;
 white-space: nowrap;
}

.writing-editor-blocker details[open] {
 align-self: flex-start;
 max-width: min(520px, 48vw);
}

.writing-editor-blocker details p {
 margin: 5px 0 0;
 color: var(--muted);
 line-height: 1.45;
 overflow-wrap: anywhere;
}

.writing-editor-blocker > button {
 min-height: 26px;
 padding: 0 8px;
 flex: 0 0 auto;
 white-space: nowrap;
 font-size: 12px;
}

.writing-drafting-readiness {
 margin-bottom: 5px;
 padding: 7px 9px;
 border: 1px solid #c9d8e9;
 border-left: 3px solid #4e78a5;
 border-radius: 3px;
 background: #f7faff;
 display: flex;
 align-items: flex-start;
 gap: 8px;
 color: #315b86;
}

.writing-drafting-readiness > div {
 min-width: 0;
 flex: 1 1 auto;
 display: grid;
 gap: 2px;
}

.writing-drafting-readiness strong {
 color: var(--text);
 font-size: 12px;
 line-height: 1.35;
}

.writing-drafting-readiness span,
.writing-drafting-readiness summary,
.writing-drafting-readiness li {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.writing-drafting-readiness summary {
 width: fit-content;
 cursor: pointer;
}

.writing-drafting-readiness ul {
 margin: 4px 0 0;
 padding-left: 18px;
}

.writing-drafting-readiness > button {
 min-height: 28px;
 padding: 0 9px;
 flex: 0 0 auto;
 white-space: nowrap;
}

.writing-version-panel {
 min-width: 0;
 display: grid;
 align-content: start;
 gap: 12px;
}

.writing-version-panel > header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
 padding-bottom: 9px;
 border-bottom: 1px solid var(--line);
}

.writing-version-panel > header > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.writing-version-panel > header span,
.writing-version-summary span,
.writing-quarantine-entry span,
.writing-freeze-history-list span {
 color: var(--muted);
 font-size: 11px;
}

.writing-version-panel > header strong {
 font-size: 15px;
}

.writing-version-panel > header button,
.writing-binding-recovery-actions button {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.writing-version-summary {
 display: grid;
 grid-template-columns: repeat(3, minmax(0, 1fr));
 gap: 8px;
}

.writing-version-summary > div {
 min-width: 0;
 display: grid;
 align-content: start;
 gap: 4px;
}

.writing-version-summary strong {
 font-size: 12px;
 overflow-wrap: anywhere;
}

.writing-version-message,
.writing-version-readiness p,
.writing-quarantine-entry p {
 margin: 0;
 font-size: 12px;
 line-height: 1.55;
 overflow-wrap: anywhere;
}

.writing-version-message.danger {
 padding: 7px 8px;
 border-left: 3px solid var(--danger);
 background: var(--danger-bg);
 color: var(--danger);
}

.writing-version-readiness {
 display: grid;
 justify-items: start;
 gap: 6px;
 padding: 8px 0;
 border-top: 1px solid var(--line);
 border-bottom: 1px solid var(--line);
}

.writing-version-disclosure {
 min-width: 0;
 border-bottom: 1px solid var(--line);
 padding-bottom: 8px;
}

.writing-version-disclosure > summary {
 min-height: 32px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
 cursor: pointer;
 font-size: 12px;
 font-weight: 700;
 list-style: none;
}

.writing-version-disclosure > summary::-webkit-details-marker {
 display: none;
}

.writing-quarantine-entry,
.writing-freeze-history-list {
 display: grid;
 gap: 8px;
 padding-top: 8px;
}

.writing-quarantine-entry > div:first-child,
.writing-freeze-history-list > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.writing-quarantine-entry > p {
 color: #7e4b10;
}

.writing-binding-recovery-form {
 display: grid;
 gap: 9px;
 padding-top: 9px;
 border-top: 1px dashed #d5ad74;
}

.writing-binding-recovery-form > label:not(.writing-binding-recovery-check) {
 display: grid;
 gap: 5px;
 font-size: 12px;
 font-weight: 700;
}

.writing-binding-recovery-form textarea {
 min-height: 84px;
 resize: vertical;
}

.writing-binding-recovery-check {
 display: grid;
 grid-template-columns: 16px minmax(0, 1fr);
 align-items: start;
 gap: 7px;
 color: var(--muted);
 font-size: 11px;
 line-height: 1.5;
}

.writing-binding-recovery-check input {
 margin: 2px 0 0;
}

.writing-binding-recovery-actions {
 display: flex;
 flex-wrap: wrap;
 justify-content: flex-end;
 gap: 7px;
}

.writing-freeze-history-list > div {
 padding: 7px 0;
 border-top: 1px solid #edf0f3;
}

.writing-freeze-history-list > div:first-child {
 border-top: 0;
}

.writing-freeze-history-list > div.is-current {
 padding-left: 7px;
 border-left: 3px solid var(--success);
}

.writing-freeze-history-list > div > div {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.writing-freeze-history-list strong {
 font-size: 12px;
}

.writing-content-quality-dock {
 position: fixed;
 right: 18px;
 bottom: 18px;
 z-index: 52;
 width: min(1080px, calc(100vw - 230px));
 height: min(680px, calc(100vh - 112px));
 min-height: 480px;
 display: grid;
 grid-template-rows: auto auto auto auto minmax(0, 1fr) auto;
 overflow: hidden;
 border: 1px solid #efb58f;
 border-radius: 6px;
 background: #fff;
 box-shadow: 0 18px 50px rgba(45, 52, 60, 0.22);
}

.writing-content-quality-head {
 min-height: 52px;
 padding: 8px 12px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 border-bottom: 1px solid var(--line);
 background: #fffaf6;
}

.writing-content-quality-head > div {
 min-width: 0;
 display: flex;
 align-items: center;
 gap: 8px;
}

.writing-content-quality-head > div:first-child {
 overflow: hidden;
}

.writing-content-quality-head strong {
 flex: 0 0 auto;
 font-size: 15px;
}

.writing-content-quality-head span:not(.tag) {
 min-width: 0;
 color: var(--muted);
 font-size: 12px;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.writing-content-quality-summary {
 min-height: 44px;
 padding: 6px 12px;
 display: flex;
 align-items: center;
 gap: 18px;
 border-bottom: 1px solid var(--soft-line);
 background: #fbfcfd;
 color: var(--muted);
 font-size: 12px;
}

.writing-content-quality-summary span {
 display: inline-flex;
 align-items: baseline;
 gap: 4px;
 white-space: nowrap;
}

.writing-content-quality-summary strong {
 color: var(--text);
 font-size: 15px;
}

.writing-content-quality-summary button,
.writing-content-disposition-actions button {
 min-height: 32px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.writing-content-quality-summary button {
 margin-left: auto;
}

.writing-content-quality-message,
.writing-content-quality-unsaved {
 margin: 0;
 padding: 7px 12px;
 border-bottom: 1px solid var(--soft-line);
 background: var(--info-bg);
 color: var(--info);
 font-size: 12px;
 overflow-wrap: anywhere;
}

.writing-content-quality-message.danger {
 background: var(--danger-bg);
 color: var(--danger);
}

.writing-content-quality-unsaved {
 background: var(--warning-bg);
 color: var(--warning);
}

.writing-content-quality-body {
 min-height: 0;
 display: grid;
 grid-template-columns: 290px minmax(0, 1fr);
}

.writing-content-quality-list {
 min-width: 0;
 min-height: 0;
 padding: 8px;
 display: grid;
 align-content: start;
 gap: 6px;
 overflow-y: auto;
 border-right: 1px solid var(--line);
 background: #f8f9fa;
}

.writing-content-quality-list > button {
 width: 100%;
 min-width: 0;
 min-height: 92px;
 padding: 9px;
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 gap: 5px 8px;
 text-align: left;
 background: #fff;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
}

.writing-content-quality-list > button:hover,
.writing-content-quality-list > button.active {
 border-color: #efb58f;
 background: #fff9f5;
}

.writing-content-quality-list > button > span:first-child {
 min-width: 0;
 color: #8b4a21;
 font-size: 12px;
 font-weight: 700;
 overflow-wrap: anywhere;
}

.writing-content-quality-list > button > strong {
 grid-column: 1 / -1;
 min-width: 0;
 max-height: 42px;
 color: var(--text);
 font-size: 12px;
 line-height: 1.5;
 overflow: hidden;
 overflow-wrap: anywhere;
}

.writing-content-quality-list .tag {
 justify-self: end;
}

.writing-content-quality-detail {
 min-width: 0;
 min-height: 0;
 padding: 14px 16px;
 overflow-y: auto;
}

.writing-content-primary-evidence {
 padding: 0 0 14px 12px;
 border-left: 3px solid var(--orange);
 border-bottom: 1px solid var(--soft-line);
}

.writing-content-primary-evidence > div {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 color: var(--muted);
 font-size: 12px;
}

.writing-content-primary-evidence blockquote {
 max-height: 210px;
 margin: 10px 0;
 padding: 10px 12px;
 overflow-y: auto;
 border: 1px solid #f0d7c6;
 border-radius: 4px;
 background: #fffaf6;
 color: #2f3338;
 font-size: 15px;
 line-height: 1.7;
 overflow-wrap: anywhere;
}

.writing-content-primary-evidence mark {
 padding: 1px 3px;
 background: #ffd6bd;
 color: #8f3100;
 font-weight: 800;
}

.writing-content-primary-evidence p {
 margin: 0;
 color: #515861;
 font-size: 13px;
 line-height: 1.55;
}

.writing-content-traceability {
 padding: 10px 0;
 border-bottom: 1px solid var(--soft-line);
}

.writing-content-traceability summary {
 color: var(--muted);
 font-size: 12px;
 cursor: pointer;
}

.writing-content-traceability dl {
 margin: 10px 0 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 8px 14px;
}

.writing-content-traceability dl > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.writing-content-traceability dt {
 color: var(--muted);
 font-size: 11px;
}

.writing-content-traceability dd {
 margin: 0;
 color: var(--text);
 font-size: 12px;
 overflow-wrap: anywhere;
}

.writing-content-prior-disposition {
 padding: 10px 0;
 border-bottom: 1px solid var(--soft-line);
}

.writing-content-prior-disposition span,
.writing-content-prior-disposition small {
 color: var(--muted);
 font-size: 11px;
}

.writing-content-prior-disposition p {
 margin: 5px 0;
 color: var(--text);
 font-size: 13px;
 line-height: 1.5;
 overflow-wrap: anywhere;
}

.writing-content-disposition-form {
 padding-top: 12px;
 display: grid;
 gap: 10px;
}

.writing-content-disposition-form > label:first-child {
 display: grid;
 gap: 6px;
 color: var(--text);
 font-size: 12px;
 font-weight: 700;
}

.writing-content-disposition-form textarea {
 min-height: 78px;
 resize: vertical;
 font-weight: 400;
}

.writing-content-acknowledgement {
 display: grid;
 grid-template-columns: 16px minmax(0, 1fr);
 align-items: start;
 gap: 7px;
 color: #5e5148;
 font-size: 12px;
 line-height: 1.5;
}

.writing-content-acknowledgement input {
 margin-top: 2px;
}

.writing-content-disposition-actions {
 display: flex;
 flex-wrap: wrap;
 gap: 8px;
}

.writing-content-quality-clear {
 min-height: 0;
 display: grid;
 place-content: center;
 justify-items: center;
 gap: 8px;
 padding: 28px;
 color: var(--success);
 text-align: center;
}

.writing-content-quality-clear p {
 max-width: 560px;
 margin: 0;
 color: var(--muted);
 font-size: 12px;
}

.writing-content-quality-dock > footer {
 min-height: 32px;
 padding: 7px 12px;
 border-top: 1px solid var(--line);
 background: #fbfcfd;
 color: var(--muted);
 font-size: 11px;
}

.working-copy-message {
 border: 1px solid #c9ddff;
 border-radius: 4px;
 background: var(--info-bg);
 color: var(--info);
 padding: 8px 10px;
 margin-bottom: 10px;
 font-size: 12px;
 overflow-wrap: anywhere;
}

.working-copy-message.danger {
 border-color: #ffc9c9;
 background: var(--danger-bg);
 color: var(--danger);
}

.working-copy-load-error,
.working-copy-recovery-prompt {
 min-height: 42px;
 margin-bottom: 8px;
 padding: 8px 10px;
 border: 1px solid #efb58f;
 border-left: 3px solid #b85c20;
 background: #fff8f3;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 color: #7e4219;
 font-size: 12px;
}

.working-copy-load-error > span {
 min-width: 0;
 overflow-wrap: anywhere;
}

.working-copy-load-error button,
.working-copy-recovery-prompt button {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 gap: 5px;
 white-space: nowrap;
}

.working-copy-recovery-prompt {
 border-color: #c9ddff;
 border-left-color: #4f7fc4;
 background: #f5f9ff;
 color: #315f9f;
}

.working-copy-recovery-prompt.is-conflict {
 border-color: #efb58f;
 border-left-color: #b85c20;
 background: #fff8f3;
 color: #7e4219;
}

.working-copy-recovery-prompt > div:first-child {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.working-copy-recovery-prompt > div:last-child {
 display: flex;
 flex: 0 0 auto;
 gap: 6px;
}

.working-copy-recovery-prompt span,
.working-copy-recovery-prompt small {
 overflow-wrap: anywhere;
}

.writing-unsaved-navigation-backdrop {
 position: fixed;
 inset: 0;
 z-index: 150;
 padding: 24px;
 background: rgba(28, 35, 42, 0.32);
 display: grid;
 place-items: center;
}

.writing-unsaved-navigation-backdrop.app-navigation-guard {
 z-index: 180;
}

.writing-unsaved-navigation-dialog {
 width: min(520px, calc(100vw - 48px));
 padding: 18px;
 border: 1px solid #e0a96a;
 border-radius: 6px;
 background: #fff;
 box-shadow: 0 22px 64px rgba(24, 33, 42, 0.28);
 display: grid;
 gap: 18px;
}

.writing-unsaved-navigation-dialog > header {
 display: grid;
 grid-template-columns: 22px minmax(0, 1fr);
 gap: 10px;
 color: #8a520d;
}

.writing-unsaved-navigation-dialog > header > div {
 min-width: 0;
 display: grid;
 gap: 5px;
}

.writing-unsaved-navigation-dialog > header strong {
 color: var(--text);
 font-size: 16px;
}

.writing-unsaved-navigation-dialog > header span {
 color: var(--muted);
 line-height: 1.55;
 overflow-wrap: anywhere;
}

.writing-unsaved-navigation-actions {
 display: flex;
 justify-content: flex-end;
 gap: 8px;
}

.writing-unsaved-navigation-actions button {
 min-height: 34px;
}

@media (min-width: 1281px) and (max-height: 920px) {
 .writing-editor-first-layout {
 height: calc(100vh - 154px);
 min-height: 0;
 }

 .writing-editor-core,
 .writing-ai-core {
 min-height: 0;
 }

 .working-copy-status-bar {
 flex: 0 0 auto;
 }
}

.rich-editor-shell {
 flex: 1;
 display: flex;
 flex-direction: column;
 gap: 10px;
 min-height: 0;
 overflow: hidden;
}

.rich-editor-shell.document-fullscreen {
 position: fixed;
 inset: 8px;
 z-index: 120;
 padding: 10px 12px 12px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 box-shadow: 0 18px 54px rgba(24, 33, 42, 0.24);
}

.rich-editor-fullscreen-actions {
 min-width: 0;
 margin-left: auto;
 display: flex;
 align-items: center;
 gap: 5px;
}

.rich-editor-fullscreen-actions > span {
 max-width: 150px;
 padding: 4px 7px;
 border: 1px solid var(--line);
 background: #f7f8fa;
 color: var(--muted);
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.rich-editor-fullscreen-actions > span.is-dirty {
 border-color: #e5b56f;
 background: #fff9ef;
 color: #8a520d;
}

.rich-editor-fullscreen-actions button {
 min-height: 28px;
 padding: 0 8px;
 display: inline-flex;
 align-items: center;
 gap: 5px;
 white-space: nowrap;
}

.rich-editor-fullscreen-actions .rich-editor-fullscreen-save {
 border-color: var(--orange);
 background: #fff8f3;
 color: var(--orange-dark);
 font-weight: 700;
}

.rich-editor-shell.document-fullscreen .rich-editor-fullscreen-button {
 margin-left: 0;
 flex: 0 0 auto;
}

.real-document-session-blocked .blocked-editor-canvas {
 min-height: 520px;
 padding: 32px 36px;
 background: #fbfcfd;
 color: var(--muted);
}

.real-document-session-blocked .blocked-editor-canvas h2 {
 color: var(--text);
 font-size: 20px;
 margin: 0 0 16px;
}

.authoring-journey-shell {
 flex: 1;
 min-height: 0;
 display: flex;
 flex-direction: column;
 gap: 10px;
 padding: 3px 2px 2px;
 overflow: hidden;
}

/* Authoring details must follow native disclosure semantics. Component-level
 display rules otherwise keep collapsed field cards in the layout, so the
 journey scroll container cannot expose the controls when the user opens it. */
.authoring-journey-shell details:not([open]) > :not(summary) {
 display: none !important;
}

.authoring-journey-header,
.authoring-journey-footer,
.authoring-stage-strip,
.authoring-group-tabs,
.authoring-impact-actions,
.authoring-corpus-stage > header,
.authoring-search-plan > div:first-child,
.authoring-writing-entry,
.authoring-writing-entry > div {
 display: flex;
 align-items: center;
}

.authoring-journey-header {
 min-height: 48px;
 justify-content: space-between;
 gap: 16px;
 padding-bottom: 9px;
 border-bottom: 1px solid var(--line);
}

.authoring-journey-header > div:first-child,
.authoring-journey-state,
.authoring-field-section > header,
.authoring-corpus-stage > header > div,
.authoring-search-plan > div:first-child > span,
.authoring-writing-entry > div > span {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.authoring-journey-header span,
.authoring-journey-state small,
.authoring-field-section > header span,
.authoring-field > span,
.authoring-corpus-stage > header span,
.authoring-search-plan small,
.authoring-writing-entry small,
.authoring-journey-footer > span {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.authoring-journey-header h2 {
 margin: 0;
 color: var(--text);
 font-size: 18px;
 line-height: 1.35;
}

.authoring-focus-context {
 width: fit-content;
 max-width: 100%;
 overflow: hidden;
 border-left: 2px solid var(--brand);
 padding-left: 7px;
 color: var(--text-secondary) !important;
 font-size: 11px;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.authoring-journey-state {
 grid-template-columns: auto auto;
 column-gap: 8px;
 text-align: right;
}

.authoring-journey-state small {
 grid-column: 1 / -1;
}

.authoring-entry-mode,
.synopsis-import-stage {
 min-width: 0;
 display: grid;
 gap: 12px;
 align-content: start;
}

.authoring-entry-mode > header,
.synopsis-import-stage > header,
.synopsis-source-review > header,
.synopsis-extraction-review > header,
.synopsis-validation-review > header,
.synopsis-findings-grid section > header {
 min-width: 0;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
}

.authoring-entry-mode > header > div,
.synopsis-import-stage > header > div,
.synopsis-extraction-review > header > div,
.synopsis-validation-review > header > div,
.synopsis-validation-review > header > div > span {
