 font-size: 11px;
 line-height: 1.45;
}

.authoring-entry-mode-options {
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
}

.authoring-entry-mode-options > button {
 width: 100%;
 min-width: 0;
 min-height: 64px;
 display: grid;
 grid-template-columns: 28px minmax(0, 1fr) auto;
 align-items: center;
 gap: 10px;
 border: 0;
 border-bottom: 1px solid var(--line);
 border-radius: 0;
 padding: 10px 12px;
 background: #fff;
 color: var(--text);
 text-align: left;
}

.authoring-entry-mode-options > button:last-child {
 border-bottom: 0;
}

.authoring-entry-mode-options > button:hover:not(:disabled),
.authoring-entry-mode-options > button:focus-visible {
 background: #fff7f1;
 color: var(--brand);
}

.authoring-entry-mode-options > button > span {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.authoring-entry-mode-options small,
.authoring-entry-mode > p {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.authoring-entry-mode > p {
 display: flex;
 align-items: center;
 gap: 6px;
 margin: 0;
}

.synopsis-import-status,
.synopsis-validation {
 display: inline-flex;
 align-items: center;
 width: max-content;
 max-width: 100%;
 border: 1px solid currentColor;
 border-radius: 3px;
 padding: 3px 6px;
 font-size: 11px;
 line-height: 1.2;
}

.synopsis-import-status.pending,
.synopsis-validation.not_assessed {
 background: #f7f8fa;
 color: var(--muted);
}

.synopsis-import-status.review,
.synopsis-validation.warning {
 background: var(--warning-bg);
 color: var(--warning);
}

.synopsis-validation.mismatch {
 background: var(--danger-bg);
 color: var(--danger);
}

.synopsis-validation.matched {
 background: var(--success-bg);
 color: var(--success);
}

.synopsis-upload-bar {
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 align-items: stretch;
 gap: 8px;
}

.synopsis-file-picker {
 min-width: 0;
 min-height: 54px;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 align-items: center;
 gap: 9px;
 border: 1px dashed #d6aa8a;
 border-radius: 4px;
 padding: 8px 10px;
 background: #fffaf6;
 color: var(--brand);
 cursor: pointer;
}

.synopsis-file-picker input {
 position: absolute;
 width: 1px;
 height: 1px;
 overflow: hidden;
 clip: rect(0 0 0 0);
 white-space: nowrap;
 clip-path: inset(50%);
}

.synopsis-file-picker > span {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.synopsis-file-picker strong,
.synopsis-file-picker small {
 min-width: 0;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.synopsis-file-picker small {
 color: var(--muted);
 font-size: 11px;
}

.synopsis-upload-bar > button,
.synopsis-import-footer > button {
 min-height: 36px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 6px;
}

.synopsis-source-review,
.synopsis-extraction-review,
.synopsis-validation-review {
 min-width: 0;
 display: grid;
 gap: 9px;
 border-top: 1px solid var(--line);
 padding-top: 10px;
}

.synopsis-source-review dl {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(3, minmax(0, 1fr));
 margin: 0;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
}

.synopsis-source-review dl > div {
 min-width: 0;
 display: grid;
 grid-template-columns: 72px minmax(0, 1fr);
 align-items: center;
 gap: 8px;
 padding: 8px 9px;
 border-right: 1px solid var(--soft-line);
 border-bottom: 1px solid var(--soft-line);
}

.synopsis-source-review dl > div:nth-child(3n) {
 border-right: 0;
}

.synopsis-source-review dl > div:nth-last-child(-n + 3) {
 border-bottom: 0;
}

.synopsis-source-review dt {
 color: var(--muted);
 font-size: 11px;
}

.synopsis-source-review dd {
 min-width: 0;
 margin: 0;
 overflow: hidden;
 color: var(--text);
 font-size: 12px;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.synopsis-findings-grid {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 8px;
}

.synopsis-findings-grid section {
 min-width: 0;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 9px 10px;
 background: #fff;
}

.synopsis-findings-grid section > header span {
