 font-size: 11px;
}

.synopsis-findings-grid ul {
 display: flex;
 flex-wrap: wrap;
 gap: 5px;
 margin: 8px 0 0;
 padding: 0;
 list-style: none;
}

.synopsis-findings-grid li {
 border: 1px solid #e8cba7;
 border-radius: 3px;
 padding: 3px 6px;
 background: #fffaf1;
 color: var(--text-secondary);
 font-size: 11px;
 overflow-wrap: anywhere;
}

.synopsis-findings-grid p {
 margin: 8px 0 0;
 color: var(--muted);
 font-size: 11px;
}

.synopsis-instrument-candidates {
 min-width: 0;
 display: grid;
 gap: 8px;
 border-top: 1px solid var(--line);
 padding-top: 10px;
}

.synopsis-instrument-candidates > header {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 16px;
}

.synopsis-instrument-candidates > header > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.synopsis-instrument-candidates > header span,
.synopsis-instrument-candidates > header small {
 color: var(--muted);
 font-size: 11px;
}

.synopsis-instrument-candidates > div {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 6px;
}

.synopsis-instrument-candidates article {
 min-width: 0;
 display: grid;
 grid-template-columns: 52px minmax(0, 1fr) auto;
 align-items: start;
 gap: 9px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 8px 9px;
 background: #fff;
}

.synopsis-instrument-candidates article > span {
 overflow: hidden;
 border-radius: 3px;
 padding: 4px 5px;
 background: #eef5ff;
 color: #2559a7;
 font-size: 11px;
 font-weight: 700;
 text-align: center;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.synopsis-instrument-summary {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.synopsis-instrument-candidates article strong,
.synopsis-instrument-candidates article small {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.synopsis-instrument-candidates article small {
 color: var(--muted);
 font-size: 11px;
}

.synopsis-instrument-candidates article em {
 color: var(--warning);
 font-size: 11px;
 font-style: normal;
 white-space: nowrap;
}

.synopsis-instrument-evidence {
 min-width: 0;
 grid-column: 1 / -1;
 display: grid;
 gap: 5px;
 border-top: 1px solid #e6ebf1;
 padding-top: 7px;
}

.synopsis-instrument-evidence > div,
.synopsis-instrument-evidence details > div {
 min-width: 0;
 display: grid;
 grid-template-columns: 34px minmax(0, 1fr);
 gap: 3px 7px;
}

.synopsis-instrument-evidence span {
 color: #2559a7;
 font-size: 10px;
 font-weight: 700;
}

.synopsis-instrument-evidence blockquote,
.synopsis-instrument-evidence p {
 min-width: 0;
 max-height: 74px;
 overflow: auto;
 margin: 0;
 color: var(--text-secondary);
 font-size: 11px;
 line-height: 1.55;
 overflow-wrap: anywhere;
}

.synopsis-instrument-evidence small {
 grid-column: 2;
 overflow: hidden;
 color: var(--muted);
 font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
 font-size: 9px;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.synopsis-instrument-evidence details {
 min-width: 0;
}

.synopsis-instrument-evidence details[open] {
 display: grid;
 gap: 6px;
}

.synopsis-instrument-evidence summary {
 width: max-content;
 max-width: 100%;
 cursor: pointer;
 color: #2559a7;
 font-size: 10px;
}

.synopsis-instrument-evidence.missing p {
 color: var(--danger);
}

.synopsis-validation-review > header > div {
 grid-template-columns: auto minmax(0, 1fr);
 align-items: start;
 color: var(--warning);
}

.synopsis-validation-review > header > span {
 color: var(--warning);
 font-size: 11px;
 font-weight: 700;
}

.synopsis-validation-review > div {
 border: 1px solid #efca93;
 border-radius: 4px;
 background: var(--warning-bg);
}

.synopsis-validation-review > div > label {
 min-width: 0;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 align-items: start;
 gap: 8px;
 padding: 8px 10px;
 border-bottom: 1px solid #efca93;
}

.synopsis-validation-review > div > label:last-child {
 border-bottom: 0;
}

.synopsis-validation-review input {
 width: auto;
 margin: 2px 0 0;
}

.synopsis-validation-review label > span {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.synopsis-validation-review label small,
.synopsis-override-reason > span {
