 font-size: 11px;
}

.synopsis-override-reason {
 display: grid;
 gap: 5px;
}

.synopsis-override-reason textarea,
.synopsis-extraction-review input,
.synopsis-extraction-review select,
.synopsis-extraction-review textarea {
 width: 100%;
 min-width: 0;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 7px 9px;
 background: #fff;
 color: var(--text);
 font: inherit;
 font-size: 12px;
 line-height: 1.5;
}

.synopsis-extraction-review input,
.synopsis-extraction-review select {
 height: 34px;
 padding-top: 0;
 padding-bottom: 0;
}

.synopsis-extraction-review textarea,
.synopsis-override-reason textarea {
 resize: vertical;
}

.synopsis-import-footer {
