}

.authoring-field input,
.authoring-field select,
.authoring-field textarea,
.authoring-override textarea {
 width: 100%;
 min-width: 0;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 7px 9px;
 background: #fff;
 color: var(--text);
 font: inherit;
 font-size: 12px;
 line-height: 1.5;
}

.authoring-field input,
.authoring-field select {
