 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
}

.authoring-instrument-list {
 max-height: 620px;
 overflow-y: auto;
}

.authoring-instrument-list > button {
 width: 100%;
 min-width: 0;
 min-height: 52px;
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 align-items: center;
 gap: 8px;
 border: 0;
 border-bottom: 1px solid var(--soft-line);
 border-radius: 0;
 padding: 8px 9px;
 background: #fff;
 color: var(--text);
 text-align: left;
}

.authoring-instrument-list > button:last-child {
 border-bottom: 0;
}

.authoring-instrument-list > button.selected {
 background: #fff6ef;
 box-shadow: inset 3px 0 0 var(--brand);
}

.authoring-instrument-list > button > span {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.authoring-instrument-list small {
 overflow: hidden;
 color: var(--muted);
 font-size: 10px;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.instrument-state {
 border: 1px solid var(--line);
 border-radius: 3px;
 padding: 2px 5px;
 color: var(--muted);
 font-size: 10px;
 font-style: normal;
}

.instrument-state.confirmed {
 border-color: #9fc5a9;
 background: #f2faf4;
 color: var(--success);
}

.instrument-state.needs_review {
 border-color: #efca93;
 background: var(--warning-bg);
 color: var(--warning);
}

.authoring-instrument-editor {
 display: grid;
 gap: 12px;
 padding: 11px;
}

.authoring-instrument-editor-head {
 padding-bottom: 8px;
 border-bottom: 1px solid var(--soft-line);
}

.authoring-instrument-editor-head .danger-quiet {
 border-color: #edb8b8;
 color: var(--danger);
}

.authoring-instrument-bindings {
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(0, 1.5fr) minmax(240px, 0.8fr);
 gap: 12px;
 margin: 0;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 10px;
}

.authoring-instrument-bindings legend {
 padding: 0 5px;
 color: var(--text-secondary);
 font-size: 11px;
 font-weight: 600;
}

.authoring-instrument-bindings > div {
 display: flex;
 flex-wrap: wrap;
 align-content: start;
 gap: 6px;
}

.authoring-instrument-bindings > div label,
.authoring-instrument-confirm > label {
 display: inline-flex;
 align-items: flex-start;
 gap: 6px;
 color: var(--text-secondary);
 font-size: 11px;
 line-height: 1.4;
}

.authoring-instrument-bindings input,
.authoring-instrument-confirm input {
 width: auto;
 min-width: 14px;
 margin: 1px 0 0;
}

.authoring-instrument-governance {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 10px;
}

.authoring-instrument-governance section {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 8px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 9px;
 background: #fafbfc;
}

.authoring-instrument-governance section > header {
 grid-column: 1 / -1;
}

.authoring-instrument-governance label {
 min-width: 0;
 display: grid;
 gap: 4px;
}

.authoring-instrument-governance label:last-child {
 grid-column: 1 / -1;
}

.authoring-instrument-governance label > span {
 color: var(--muted);
 font-size: 10px;
}

.authoring-instrument-governance input,
.authoring-instrument-governance select {
 width: 100%;
 min-width: 0;
 height: 32px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 0 8px;
 background: #fff;
 color: var(--text);
 font: inherit;
 font-size: 11px;
}

.authoring-instrument-confirm {
 justify-content: flex-start;
 flex-wrap: wrap;
 border-top: 1px solid var(--soft-line);
 padding-top: 10px;
}

.authoring-instrument-confirm button {
 margin-left: auto;
}

.authoring-instrument-confirm button.confirmed {
 border-color: #9fc5a9;
 background: #f2faf4;
 color: var(--success);
}

.authoring-instrument-appendix {
 min-width: 0;
 display: grid;
 gap: 9px;
 border: 1px solid #dfc8b5;
 border-radius: 4px;
 padding: 10px;
 background: #fffaf6;
}

.authoring-instrument-appendix > header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
}

.authoring-instrument-appendix > header > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.authoring-instrument-appendix > header span,
.authoring-instrument-appendix p,
.authoring-instrument-appendix-result small,
.authoring-instrument-appendix-actions small {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.authoring-instrument-appendix > header em {
 flex: 0 0 auto;
 border: 1px solid var(--line);
 border-radius: 3px;
 padding: 3px 6px;
 color: var(--muted);
 background: #fff;
 font-size: 10px;
 font-style: normal;
}

.authoring-instrument-appendix > header em.ready {
 border-color: #9fc5a9;
 color: var(--success);
 background: #f2faf4;
}

.authoring-instrument-appendix-result {
 min-width: 0;
 display: flex;
 align-items: center;
 gap: 8px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 8px;
 background: #fff;
}

.authoring-instrument-appendix-result > span {
 min-width: 0;
 display: grid;
}

.authoring-instrument-appendix-result strong {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.authoring-instrument-appendix-actions {
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 gap: 8px;
}

.authoring-instrument-appendix-actions label {
 min-width: 0;
 min-height: 40px;
 display: flex;
 align-items: center;
 gap: 8px;
 border: 1px dashed #cfaa8b;
 border-radius: 4px;
 padding: 7px 9px;
 background: #fff;
 cursor: pointer;
}

.authoring-instrument-appendix-actions label > input {
 position: absolute;
 width: 1px;
 height: 1px;
 overflow: hidden;
 opacity: 0;
}

.authoring-instrument-appendix-actions label > span {
 min-width: 0;
 display: grid;
}

.authoring-instrument-appendix-actions label strong {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.authoring-instrument-appendix-actions button {
 min-height: 40px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 5px;
 white-space: nowrap;
}

.authoring-instrument-appendix > p {
 margin: 0;
}

.authoring-instrument-appendix > p.success {
 color: var(--success);
}

.authoring-instrument-appendix > p.warning {
 color: var(--warning);
}

.authoring-choice-grid {
 display: grid;
 grid-template-columns: repeat(4, minmax(0, 1fr));
 gap: 7px;
}

.authoring-choice-grid label {
 min-width: 0;
 min-height: 38px;
 display: flex;
 align-items: center;
 gap: 7px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 7px 9px;
 background: #fff;
 color: var(--text);
 font-size: 12px;
}

.authoring-choice-grid label.selected {
 border-color: #f3b98f;
 background: #fff6ef;
}

.authoring-choice-grid input,
.authoring-gate-checklist input {
 width: auto;
 min-width: 14px;
 flex: 0 0 auto;
 margin: 0;
}

.authoring-prefill-panel {
 min-width: 0;
 display: grid;
 gap: 12px;
 margin-bottom: 12px;
 border-top: 2px solid var(--orange);
 border-bottom: 1px solid var(--line);
 padding: 12px 0 14px;
 background: #fff;
}

.authoring-prefill-panel > header,
.authoring-prefill-panel > header > div,
.authoring-prefill-panel > header span {
 min-width: 0;
 display: flex;
 align-items: center;
}

.authoring-prefill-panel > header {
 justify-content: space-between;
 gap: 12px;
}

.authoring-prefill-panel > header > div {
 gap: 8px;
 color: var(--orange-dark);
}

.authoring-prefill-panel > header span {
 align-items: flex-start;
 flex-direction: column;
 gap: 2px;
 color: var(--text);
}

.authoring-prefill-panel > header small {
 color: var(--muted);
 font-size: 11px;
}

.authoring-prefill-panel > header button {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 0 9px;
 background: #fff;
 color: var(--text);
 font-size: 12px;
}

.authoring-prefill-header-actions,
.authoring-prefill-preparation,
.authoring-prefill-section-tabs,
.authoring-prefill-primary-actions {
 min-width: 0;
 display: flex;
 align-items: center;
}

.authoring-prefill-header-actions {
 flex: 0 0 auto;
 gap: 6px;
}

.authoring-prefill-panel > header .authoring-prefill-batch-button {
 border-color: #d7a47d;
 background: #fff8f2;
 color: #8f430f;
 font-weight: 700;
}

/* W4-A recommendation-first composite package panel */
.authoring-package-panel {
 min-width: 0;
 display: grid;
 gap: 8px;
 margin: 4px 0 12px;
 border: 1px solid #e6d2c0;
 border-radius: 6px;
 padding: 10px 12px;
 background: linear-gradient(180deg, #fffaf5 0%, #fff 42%);
}

.authoring-package-panel.empty {
 background: #fafafa;
 border-color: var(--line);
}

.authoring-package-panel > header {
 display: flex;
 align-items: flex-start;
 gap: 8px;
 color: var(--orange-dark);
}

.authoring-package-panel > header > div {
 display: grid;
 gap: 2px;
 color: var(--text);
}

.authoring-package-panel > header small {
 color: var(--muted);
 font-size: 11px;
}

.authoring-package-guidance-checklist {
 margin: 6px 0 0;
 padding-left: 18px;
 color: var(--text);
 font-size: 12px;
 line-height: 1.5;
}

.authoring-package-guidance-checklist li + li {
 margin-top: 2px;
}

.authoring-package-module-includes,
.authoring-package-why-recommend {
 display: grid;
 gap: 4px;
}

.authoring-package-module-includes > strong,
.authoring-package-why-recommend > strong,
.authoring-package-tradeoffs > strong {
 font-size: 11px;
 color: #8f430f;
}

.authoring-package-module-includes ul,
.authoring-package-tradeoffs ul {
 margin: 0;
 padding-left: 18px;
 font-size: 12px;
 line-height: 1.45;
}


.authoring-package-tabs {
 display: flex;
 flex-wrap: wrap;
 gap: 6px;
}

.authoring-package-tabs button {
 min-height: 34px;
 display: inline-flex;
 flex-direction: column;
 align-items: flex-start;
 gap: 1px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 5px 10px;
 background: #fff;
 color: var(--text);
 font-size: 12px;
}

.authoring-package-tabs button.active {
 border-color: #d7a47d;
 background: #fff4ea;
 color: #8f430f;
 font-weight: 700;
}

.authoring-package-tabs button small {
 color: var(--muted);
 font-size: 10px;
 font-weight: 400;
}

.authoring-package-workspace {
 display: grid;
 grid-template-columns: minmax(0, 1fr) minmax(220px, 260px);
 gap: 12px;
 align-items: start;
}

.authoring-package-candidates {
 min-width: 0;
 display: grid;
 gap: 6px;
}

.authoring-package-candidate {
 min-width: 0;
 border: 1px solid var(--line);
 border-radius: 5px;
 background: #fff;
 overflow: hidden;
}

.authoring-package-candidate.recommended {
 border-color: #d7a47d;
 box-shadow: inset 3px 0 0 #e87524;
}

.authoring-package-candidate.selected {
 border-color: #c57a3a;
 background: #fffdfb;
}

.authoring-package-candidate.pending {
 border-style: dashed;
}

.authoring-package-candidate.confirmed {
 border-color: #b8d5c1;
 box-shadow: inset 3px 0 0 #4f9b6a;
}

.authoring-package-candidate-select {
 width: 100%;
 min-height: 44px;
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 8px;
 border: 0;
 padding: 7px 10px 8px;
 background: #fafbfc;
 color: var(--text);
 font-size: 12px;
 text-align: left;
}

.authoring-package-candidate.selected .authoring-package-candidate-select {
 border-bottom: 1px solid var(--soft-line, #e8ebef);
 background: #fff9f4;
}

.authoring-package-candidate-select-copy {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.authoring-package-candidate-role {
 display: inline-flex;
 align-items: center;
 gap: 5px;
 color: #8f430f;
 font-size: 10px;
 font-weight: 700;
}

.authoring-package-candidate-select-copy > strong {
 min-width: 0;
 overflow: hidden;
 color: var(--text);
 font-size: 12px;
 line-height: 1.35;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.authoring-package-candidate-select-copy > small {
 display: -webkit-box;
 overflow: hidden;
 color: var(--muted);
 font-size: 11px;
 font-weight: 400;
 line-height: 1.35;
 -webkit-box-orient: vertical;
 -webkit-line-clamp: 1;
}

.authoring-package-candidate-confidence {
 flex: 0 0 auto;
 padding-top: 1px;
 color: var(--muted);
 font-size: 10px;
 white-space: nowrap;
}

.authoring-package-candidate-body {
 display: grid;
 gap: 7px;
 padding: 8px 10px 10px;
}

.authoring-package-rationale,
.authoring-package-insufficient-flag,
.authoring-package-no-alternatives,
.authoring-package-pending-hint {
 margin: 0;
 color: var(--muted);
 font-size: 12px;
 line-height: 1.45;
}

.authoring-package-insufficient-flag {
 color: #9a4b12;
}

.authoring-package-evidence {
 display: grid;
 gap: 6px;
}

.authoring-package-source-text {
 margin: 0;
 border-left: 3px solid #e87524;
 padding: 7px 10px;
 background: #fff8f2;
}

.authoring-package-source-text span,
.authoring-package-evidence.insufficient > span {
 display: block;
 margin-bottom: 3px;
 color: #8f430f;
 font-size: 11px;
 font-weight: 700;
}

.authoring-package-source-text p,
.authoring-package-evidence.insufficient p {
 margin: 0;
 color: var(--text);
 font-size: 12px;
 line-height: 1.5;
 white-space: pre-wrap;
}

.authoring-package-evidence.insufficient {
 border: 1px dashed #e0b48d;
 border-radius: 4px;
 padding: 8px 10px;
 background: #fffaf5;
}

.authoring-package-trace-details,
.authoring-package-review-details,
.authoring-package-run-meta,
.authoring-package-optional-overrides {
 border-top: 1px solid var(--soft-line, #e8ebef);
 padding-top: 6px;
}

.authoring-package-trace-details > summary,
.authoring-package-review-details > summary,
.authoring-package-run-meta > summary,
.authoring-package-optional-overrides > summary {
 cursor: pointer;
 color: var(--muted);
 font-size: 11px;
}

.authoring-package-review-details[open] > summary {
 margin-bottom: 7px;
 color: #8f430f;
 font-weight: 700;
}

.authoring-package-review-grid {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 8px 14px;
}

.authoring-package-trace-details ul,
.authoring-package-tradeoffs ul,
.authoring-package-gaps ul,
.authoring-package-limitations ul,
.authoring-package-targets ul {
 margin: 4px 0 0;
 padding-left: 16px;
 color: var(--text);
 font-size: 12px;
}

.authoring-package-tradeoffs,
.authoring-package-gaps,
.authoring-package-limitations,
.authoring-package-targets {
 display: grid;
 gap: 3px;
}

.authoring-package-tradeoffs > strong,
.authoring-package-gaps > strong,
.authoring-package-limitations > strong,
.authoring-package-targets > strong {
 font-size: 11px;
 color: var(--muted);
}

.authoring-package-run-meta dl {
 display: grid;
 gap: 4px;
 margin: 6px 0 0;
}

.authoring-package-run-meta dl > div {
 display: grid;
 grid-template-columns: 72px minmax(0, 1fr);
 gap: 6px;
 font-size: 11px;
}

.authoring-package-run-meta dt {
 color: var(--muted);
}

.authoring-package-run-meta dd {
 margin: 0;
 overflow-wrap: anywhere;
}

.authoring-package-path-decisions {
 display: grid;
 gap: 8px;
 border: 1px solid #e6d2c0;
 border-radius: 4px;
 padding: 8px;
 background: #fffaf5;
}

.authoring-package-path-decisions > header {
 display: flex;
 align-items: flex-start;
 gap: 6px;
 color: #8f430f;
 font-size: 12px;
}

.authoring-package-path-row {
 display: grid;
 gap: 6px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 8px;
 background: #fff;
}

.authoring-package-path-row.skipped {
 opacity: 0.72;
 background: #f7f8fa;
}

.authoring-package-path-head {
 display: flex;
 flex-wrap: wrap;
 align-items: baseline;
 justify-content: space-between;
 gap: 4px 8px;
}

.authoring-package-path-head small {
 color: var(--muted);
 font-size: 10px;
}

.authoring-package-path-candidate span,
.authoring-package-path-override span {
 display: block;
 margin-bottom: 2px;
 color: var(--muted);
 font-size: 11px;
}

.authoring-package-path-candidate p {
 margin: 0;
 font-size: 12px;
 line-height: 1.4;
 white-space: pre-wrap;
}

.authoring-package-path-override textarea {
 width: 100%;
 min-height: 52px;
 border: 1px solid var(--line);
 border-radius: 3px;
 padding: 6px 8px;
 font: inherit;
 font-size: 12px;
 resize: vertical;
}

.authoring-package-path-skip {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 font-size: 12px;
 color: var(--muted);
}

.authoring-package-actions {
 min-width: 0;
 display: grid;
 gap: 10px;
 border: 1px solid var(--line);
 border-radius: 5px;
 padding: 10px;
 background: #fff;
 position: sticky;
 top: 8px;
}

.authoring-package-action-summary {
 display: grid;
 gap: 4px;
}

.authoring-package-action-summary p {
 margin: 0;
 color: var(--muted);
 font-size: 12px;
 line-height: 1.45;
}

.authoring-package-adopt-button {
 min-height: 36px;
 width: 100%;
 justify-content: center;
}

.authoring-package-pending-badge {
 display: inline-flex;
 align-items: center;
 gap: 4px;
 margin: 0;
 color: #8f430f;
 font-size: 12px;
 font-weight: 700;
}

.authoring-package-receipt {
 display: grid;
 gap: 8px;
 border: 1px solid #b8d5c1;
 border-radius: 5px;
 padding: 10px;
 background: #f3faf5;
}

.authoring-package-receipt.replayed {
 border-color: #9bb8d6;
 background: #f3f7fc;
}

.authoring-package-receipt.stale {
 border-color: #e0b48d;
 background: #fff8f2;
}

.authoring-package-receipt > header {
 display: flex;
 align-items: flex-start;
 gap: 8px;
}

.authoring-package-receipt > header > div {
 display: grid;
 gap: 2px;
}

.authoring-package-receipt > header small {
 color: var(--muted);
 font-size: 11px;
}

.authoring-package-receipt-flag {
 margin: 0;
 font-size: 12px;
 font-weight: 700;
}

.authoring-package-receipt-flag.replayed {
 color: #2f5f8f;
}

.authoring-package-receipt-flag.stale {
 color: #9a4b12;
}

.authoring-package-receipt-categories {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
 gap: 8px;
}

.authoring-package-receipt-category {
 border-radius: 4px;
 padding: 7px 8px;
 background: #fff;
 border: 1px solid var(--line);
}

.authoring-package-receipt-category.applied {
 border-color: #b8d5c1;
 background: #f7fcf8;
}

.authoring-package-receipt-category.overridden {
 border-color: #c7b0e0;
 background: #faf7fd;
}

.authoring-package-receipt-category.derived {
 border-color: #9bb8d6;
 background: #f5f9fd;
}

.authoring-package-receipt-category.skipped {
 border-color: #d7dbe1;
 background: #f7f8fa;
}

.authoring-package-receipt-category.invalidated {
 border-color: #e0b48d;
 background: #fffaf5;
}

.authoring-package-receipt-category strong {
 display: block;
 margin-bottom: 4px;
 font-size: 11px;
}

.authoring-package-receipt-category ul {
 margin: 0;
 padding-left: 14px;
 font-size: 11px;
 line-height: 1.4;
}

.authoring-package-receipt-category li small {
 display: block;
 color: var(--muted);
}

@media (max-width: 1366px) {
 .authoring-package-workspace {
 grid-template-columns: 1fr;
 }

 .authoring-package-actions {
 position: static;
 }
}

.authoring-prefill-preparation {
 gap: 8px;
}

.authoring-prefill-preparation span {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 gap: 5px;
 border: 1px solid var(--line);
 border-radius: 3px;
 padding: 0 9px;
 background: #fff;
 color: var(--muted);
 font-size: 11px;
}

.authoring-prefill-preparation span.done {
 border-color: #b8d5c1;
 background: #f3faf5;
 color: #2d7144;
}

.authoring-prefill-preparation span.running {
 border-color: #efc8aa;
 background: #fff8f2;
 color: #9b4e18;
}

.authoring-prefill-progress {
 position: relative;
 min-height: 24px;
 display: flex;
 align-items: center;
 gap: 9px;
 overflow: hidden;
 border-radius: 3px;
 padding: 0 8px;
 background: #f3f4f6;
 font-size: 11px;
}

.authoring-prefill-progress > span {
 position: absolute;
 inset: 0 auto 0 0;
 background: #f6e8da;
 opacity: 0.72;
}

.authoring-prefill-progress strong,
.authoring-prefill-progress small {
 position: relative;
 z-index: 1;
}

.authoring-prefill-progress small {
 color: var(--muted);
}

.authoring-prefill-batch-state {
 min-height: 30px;
 display: flex;
 align-items: center;
 gap: 10px;
 border-left: 3px solid #4f9b6a;
 padding: 5px 9px;
 background: #f3faf5;
 color: #2d7144;
 font-size: 11px;
}

.authoring-prefill-batch-state.stopped {
