 align-items: flex-start;
 justify-content: space-between;
 gap: 8px;
}

.authoring-prefill-field-head > span {
 flex-direction: column;
 gap: 2px;
}

.authoring-prefill-field-head small {
 color: var(--muted);
 font-size: 10px;
}

.authoring-prefill-field-head em {
 flex: 0 0 auto;
 border-radius: 3px;
 padding: 2px 6px;
 background: #fff0e5;
 color: #a45116;
 font-size: 10px;
 font-style: normal;
}

.authoring-prefill-field.confirmed .authoring-prefill-field-head em {
 background: #e8f5ec;
 color: #2d7144;
}

.authoring-prefill-field.deferred .authoring-prefill-field-head em {
