 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 0 8px;
 background: #fff;
 color: var(--text);
 font-size: 11px;
 white-space: nowrap;
}

.authoring-prefill-primary-actions button.primary-button {
 border-color: var(--orange);
 background: var(--orange);
 color: #fff;
}

.authoring-prefill-primary-actions button.selected {
