 display: grid;
 gap: 4px;
}

.authoring-prefill-candidate-copy > div {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.authoring-prefill-candidate-copy > div span {
 display: inline-flex;
 align-items: center;
 gap: 4px;
 color: #a45116;
 font-size: 10px;
 font-weight: 700;
}

.authoring-prefill-candidates > section.selected .authoring-prefill-candidate-copy > div span {
 color: #2d7144;
}

.authoring-prefill-candidate-copy > div small,
.authoring-prefill-candidate-copy p {
 color: var(--muted);
 font-size: 10px;
}

.authoring-prefill-candidate-copy > strong {
 overflow-wrap: anywhere;
 font-size: 12px;
 line-height: 1.5;
}

.authoring-prefill-candidate-copy p {
 margin: 0;
 line-height: 1.45;
}

.authoring-prefill-candidate-actions {
 display: flex;
 align-items: flex-start;
 gap: 5px;
}

.authoring-prefill-candidate-actions button,
.authoring-prefill-edit button {
 min-height: 28px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 0 8px;
 background: #fff;
 color: var(--text);
 font-size: 11px;
 white-space: nowrap;
}

.authoring-prefill-candidate-actions button.primary-button,
.authoring-prefill-edit button.primary-button {
