 min-width: 0;
 min-height: 70px;
 padding: 8px;
 border: 1px solid var(--line);
 border-radius: 4px;
 font-size: 13px;
 line-height: 1.5;
 resize: vertical;
 font-family: inherit;
}

.authoring-conversation-input button {
