 font-size: 11px;
 line-height: 1.45;
 overflow-wrap: anywhere;
}

.rich-table-sync-band {
 display: grid;
 gap: 7px;
 padding: 8px 10px;
 border: 1px solid var(--line);
 border-bottom: 0;
 background: #fbfcfd;
}

.rich-table-sync-heading,
.rich-table-sync-heading > div,
.rich-table-sync-metrics {
 display: flex;
 align-items: center;
}

.rich-table-sync-heading {
 min-width: 0;
 justify-content: space-between;
 gap: 14px;
}

.rich-table-sync-heading > div:first-child {
 min-width: 0;
 gap: 8px;
}

.rich-table-sync-heading > div:first-child > span {
 flex: 0 0 auto;
 color: var(--orange-dark);
 font-size: 11px;
 font-weight: 700;
}

.rich-table-sync-heading strong {
 min-width: 0;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
 font-size: 13px;
}

.rich-table-sync-metrics {
 flex: 0 0 auto;
 gap: 10px;
 color: var(--muted);
 font-size: 11px;
}

.rich-table-scroll-controls {
 display: inline-flex;
 align-items: center;
 gap: 3px;
