 border-radius: 4px;
 background: #fff;
 color: var(--text);
 display: grid;
 place-items: center;
}

.rich-table-scroll-controls button:hover:not(:disabled) {
 border-color: var(--orange);
 color: var(--orange-dark);
 background: #fff8f3;
}

.rich-table-scroll-controls button:disabled {
 color: var(--muted);
 background: #f7f8fa;
 opacity: 0.45;
}

.rich-table-sync-notes {
 max-height: 126px;
 display: grid;
 gap: 4px;
 padding: 7px 8px;
 border-left: 2px solid var(--orange);
 background: #fff;
 overflow: auto;
}

.rich-table-source-caption {
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 gap: 8px;
