 font-size: 11px;
 line-height: 1.45;
}

.rich-table-source-caption span {
 color: var(--orange-dark);
 font-weight: 700;
}

.rich-table-source-caption strong {
 color: var(--text);
 font-weight: 500;
 overflow-wrap: anywhere;
}

.rich-table-sync-notes p {
 display: grid;
 grid-template-columns: minmax(24px, auto) minmax(0, 1fr);
 gap: 7px;
