}

.protocol-editor .ProseMirror {
 min-height: 100%;
 padding: 18px 20px;
 outline: 0;
 overflow-x: auto;
}

.protocol-editor h2,
.protocol-editor .ProseMirror h2 {
 font-size: 22px;
 margin: 12px 0;
}

.protocol-editor .ProseMirror [data-style-preset="heading_1"] {
 font-family: "黑体", Arial, sans-serif;
 font-size: 16pt;
 font-weight: 700;
}

.protocol-editor .ProseMirror [data-style-preset="heading_2"] {
 font-family: "黑体", Arial, sans-serif;
 font-size: 14pt;
 font-weight: 700;
}

.protocol-editor .ProseMirror [data-style-preset="heading_3"] {
 font-family: "黑体", Arial, sans-serif;
 font-size: 12pt;
 font-weight: 700;
}

.protocol-editor .ProseMirror [data-style-preset="heading_4"] {
 font-family: "黑体", Arial, sans-serif;
 font-size: 10.5pt;
 font-weight: 700;
}

.protocol-editor .ProseMirror [data-style-preset="body"] {
 font-family: "宋体", Arial, sans-serif;
 font-size: 10.5pt;
}

.protocol-editor .ProseMirror [data-style-preset="note"] {
 font-family: "宋体", Arial, sans-serif;
 font-size: 9pt;
 color: #525961;
}

.protocol-editor p,
.protocol-editor .ProseMirror p {
