 font-family: Arial, sans-serif;
 font-size: 0.72em;
 font-weight: 600;
 line-height: 0;
 text-decoration: underline;
 text-decoration-thickness: 1px;
 text-underline-offset: 2px;
}

.rich-cross-reference-picker {
 display: inline-flex;
 align-items: center;
 gap: 5px;
 min-width: 0;
 color: #4b5563;
}

.rich-cross-reference-picker select {
 width: 126px;
 min-width: 0;
}

.protocol-editor .ProseMirror .protocol-cross-reference {
 color: #1f5f99;
 text-decoration: underline;
 text-decoration-style: dotted;
 text-underline-offset: 2px;
 cursor: default;
}

.protocol-editor .ProseMirror .source-docx-image {
 margin: 18px auto;
 width: min(100%, 760px);
