 background: #fff8f3;
}

.protocol-editor table,
.protocol-editor .ProseMirror table {
 width: 100%;
 min-width: max-content;
 max-width: none;
 border-collapse: collapse;
 margin: 18px 0;
 table-layout: auto;
}

.protocol-editor th,
.protocol-editor td,
.protocol-editor .ProseMirror th,
.protocol-editor .ProseMirror td {
 border: 1px solid var(--line);
