 min-width: 0;
 min-height: 96px;
 display: grid;
 gap: 5px;
 border: 0;
 border-bottom: 1px solid var(--line);
 border-radius: 0;
 padding: 10px 12px;
 color: var(--text);
 background: transparent;
 text-align: left;
}

.shared-phase1-corpus-workspace > nav > button.active {
