 padding: 18px;
 color: var(--muted);
 font-size: 12px;
}

.shared-phase1-corpus-detail {
 min-width: 0;
 display: grid;
 align-content: start;
 gap: 12px;
 padding: 14px;
}

.shared-phase1-corpus-detail > header {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 12px;
}

.shared-phase1-corpus-detail > header > div:first-child {
