 display: grid;
 gap: 3px;
}

.shared-phase1-corpus-detail > header > div:last-child {
 display: flex;
 flex-wrap: wrap;
 justify-content: flex-end;
 gap: 5px;
}

.shared-phase1-corpus-detail > header span,
.shared-phase1-corpus-detail > header small {
