 font-size: 11px;
}

.shared-phase1-applicability,
.shared-phase1-review-comment {
 margin: 0;
 display: flex;
 align-items: flex-start;
 gap: 8px;
 border-left: 3px solid var(--info);
 padding: 7px 10px;
 color: #34495e;
 background: var(--info-bg);
 font-size: 12px;
 line-height: 1.5;
}

.shared-phase1-applicability span,
.shared-phase1-review-comment {
 min-width: 0;
 overflow-wrap: anywhere;
}

.shared-phase1-applicability b,
.shared-phase1-review-comment b {
 margin-right: 6px;
}

.shared-phase1-text-compare {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 border: 1px solid var(--line);
 border-radius: 4px;
 overflow: hidden;
}

.shared-phase1-text-compare > section {
 min-width: 0;
 display: grid;
 grid-template-rows: auto minmax(260px, auto);
}

.shared-phase1-text-compare > section + section {
 border-left: 1px solid var(--line);
}

.shared-phase1-text-compare header {
 min-height: 38px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
 padding: 8px 10px;
 border-bottom: 1px solid var(--line);
 background: #f7f8fa;
}

.shared-phase1-text-compare header span,
.shared-phase1-text-compare header a {
 color: var(--muted);
 font-size: 10px;
}

.shared-phase1-text-compare header a {
 display: inline-flex;
 align-items: center;
 gap: 4px;
}

.shared-phase1-text-compare p {
 min-width: 0;
 max-height: 390px;
 margin: 0;
 overflow-y: auto;
 padding: 12px;
 white-space: pre-wrap;
 overflow-wrap: anywhere;
 color: #26323d;
 font-size: 12px;
 line-height: 1.65;
}

.shared-phase1-lineage {
 border-top: 1px solid var(--soft-line);
 padding-top: 8px;
 color: var(--muted);
 font-size: 11px;
}

.shared-phase1-lineage summary {
 cursor: pointer;
 color: #425466;
}

.shared-phase1-lineage dl {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 6px 14px;
}

.shared-phase1-lineage dl > div {
