 display: grid;
 grid-template-columns: 62px minmax(0, 1fr);
 gap: 6px;
}

.shared-phase1-lineage dd {
 margin: 0;
 overflow-wrap: anywhere;
}

.shared-phase1-review-actions {
 min-width: 0;
 display: grid;
 gap: 8px;
 border-top: 1px solid var(--line);
 padding-top: 10px;
}

.shared-phase1-review-actions label {
 min-width: 0;
 display: grid;
 gap: 5px;
 color: var(--muted);
 font-size: 11px;
 font-weight: 700;
}

.shared-phase1-review-actions textarea {
 min-height: 68px;
 resize: vertical;
}

.shared-phase1-review-actions > div {
 display: flex;
 justify-content: flex-end;
 gap: 7px;
}

.writing-reference-candidate-filters {
 display: grid;
 grid-template-columns: minmax(280px, 1fr) 170px auto;
 gap: 8px;
 align-items: center;
}

.writing-reference-candidate-filters label {
 min-width: 0;
 display: flex;
 align-items: center;
 gap: 6px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 0 8px;
 background: #fff;
}

.writing-reference-candidate-filters input {
 min-width: 0;
 width: 100%;
 height: 32px;
 border: 0;
 outline: 0;
}

.writing-reference-candidate-filters select {
 height: 34px;
}

.writing-reference-candidate-filters > span,
.writing-reference-pagination span {
 color: var(--muted);
 font-size: 11px;
}

.writing-reference-pagination {
 display: flex;
 justify-content: flex-end;
 align-items: center;
 gap: 8px;
}

.writing-reference-triage-finalize,
.writing-reference-alignment {
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 gap: 8px 12px;
 align-items: end;
 border-top: 1px solid var(--soft-line);
 padding-top: 10px;
}

.writing-reference-triage-finalize > div,
.writing-reference-alignment > div {
 grid-column: 1 / -1;
 display: grid;
 gap: 2px;
}

.writing-reference-triage-finalize > div span,
.writing-reference-alignment > div span {
 color: var(--muted);
 font-size: 11px;
}

.writing-reference-triage-finalize label,
.writing-reference-alignment label {
 min-width: 0;
 display: grid;
 gap: 4px;
 color: var(--muted);
 font-size: 11px;
 font-weight: 700;
}

.writing-reference-triage-finalize textarea,
.writing-reference-alignment textarea {
 min-height: 64px;
 resize: vertical;
}

.writing-reference-alignment label:last-of-type {
 grid-column: 1 / -1;
}

.writing-reference-alignment button {
 grid-column: 2;
 justify-self: end;
}

.writing-reference-header {
 min-height: 36px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
 border-bottom: 1px solid var(--soft-line);
 padding-bottom: 8px;
}

.writing-reference-header > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.writing-reference-header span {
 color: var(--muted);
 font-size: 11px;
}

.writing-reference-header strong {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.writing-reference-header .icon-button {
 width: 32px;
 min-width: 32px;
 min-height: 30px;
 padding: 0;
 display: inline-flex;
 align-items: center;
 justify-content: center;
}

.writing-reference-boundary,
.writing-reference-message,
.writing-reference-invalid,
.writing-reference-admitted {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 8px;
 font-size: 12px;
 line-height: 1.5;
}

.writing-reference-boundary {
 color: #38516a;
 background: var(--info-bg);
 border-color: #c9ddff;
}

.writing-reference-message {
 color: var(--success);
 background: var(--success-bg);
 border-color: #bfe7ce;
}

.writing-reference-message.danger,
.writing-reference-invalid {
 color: var(--danger);
 background: var(--danger-bg);
 border-color: #ffc9c9;
}

.writing-reference-invalid,
.writing-reference-admitted {
 display: flex;
 align-items: flex-start;
 gap: 6px;
}

.writing-reference-admitted {
 color: var(--success);
 background: var(--success-bg);
 border-color: #bfe7ce;
}

.writing-reference-views {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 4px;
}

.writing-reference-views button {
 min-width: 0;
 min-height: 30px;
 padding: 0 6px;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
 background: #f7f8fa;
 border: 1px solid var(--line);
 color: var(--text);
}

.writing-reference-views button.active {
 color: var(--orange-dark);
 border-color: #f6b58e;
 background: #fff6f0;
 font-weight: 700;
}

.writing-reference-view {
 width: 100%;
 min-width: 0;
 min-height: 0;
 display: flex;
 flex: 1;
 flex-direction: column;
 gap: 10px;
}

.writing-reference-manual-upload {
 display: grid;
 grid-template-columns: minmax(0, 1fr) minmax(112px, 160px);
 gap: 8px;
 align-items: end;
 border: 1px solid var(--line);
 border-left: 3px solid var(--info);
 border-radius: 4px;
 padding: 9px;
 background: #f8fbff;
}

.writing-reference-panel.authoring-mode .writing-reference-manual-upload {
 grid-template-columns: minmax(260px, 1.5fr) minmax(130px, 0.6fr) minmax(150px, 0.7fr) max-content;
}

.writing-reference-manual-upload-head {
 grid-column: 1 / -1;
 display: flex;
 align-items: flex-start;
 gap: 8px;
}

.writing-reference-manual-upload-head > span {
 width: 28px;
 height: 28px;
 flex: 0 0 auto;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 border: 1px solid #bfdbfe;
 border-radius: 4px;
 color: var(--info);
 background: #fff;
}

.writing-reference-manual-upload-head > div,
.writing-reference-manual-upload label {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.writing-reference-manual-upload-head small,
.writing-reference-manual-upload label,
.writing-reference-manual-upload-state {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.4;
}

.writing-reference-manual-upload input,
.writing-reference-manual-upload select {
 width: 100%;
 min-width: 0;
 height: 34px;
}

.writing-reference-manual-upload input[type="file"] {
 padding: 5px 7px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 font-size: 11px;
}

.writing-reference-manual-upload .primary-button {
 min-height: 34px;
 white-space: nowrap;
}

.writing-reference-manual-upload-state {
 grid-column: 1 / -1;
 overflow-wrap: anywhere;
}

.writing-reference-document-row.manual {
