 grid-template-columns: minmax(0, 1fr) 104px;
 gap: 7px;
}

.writing-reference-search label,
.writing-reference-actions label,
.writing-reference-review label,
.writing-reference-select {
 display: grid;
 gap: 4px;
 color: var(--muted);
 font-size: 12px;
 font-weight: 700;
}

.writing-reference-search .primary-button {
