 justify-content: center;
}

.writing-reference-snapshot {
 margin: 0;
 color: var(--muted);
 font-size: 11px;
 overflow-wrap: anywhere;
}

.writing-reference-list {
 min-height: 0;
 display: flex;
 flex: 1;
 flex-direction: column;
 gap: 6px;
 overflow-y: auto;
 padding-right: 2px;
}

.writing-reference-list > button,
.writing-reference-document-row,
.writing-reference-brief {
 width: 100%;
 min-width: 0;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 8px;
 background: #fff;
 text-align: left;
}

.writing-reference-list > button {
 display: grid;
 gap: 5px;
}

.writing-reference-list > button.active {
 border-color: #f6b58e;
 box-shadow: inset 3px 0 0 var(--orange);
 background: #fffaf7;
}

.writing-reference-list > button > span,
.writing-reference-document-row > div,
.writing-reference-selection-head,
.writing-reference-review-state {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 7px;
}

.writing-reference-validation {
 min-width: 0;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 8px;
 display: grid;
 gap: 7px;
 background: #fff;
 font-size: 12px;
}

.writing-reference-validation.requires-review {
