 background: #fffbf3;
}

.writing-reference-validation > div:first-child {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.writing-reference-validation p,
.writing-reference-validation small {
 margin: 0;
 color: var(--muted);
 line-height: 1.45;
}

.writing-reference-structure-review {
 min-width: 0;
 border: 1px solid #f0c989;
 border-left: 3px solid #ea580c;
 border-radius: 4px;
 padding: 8px;
 display: grid;
 gap: 7px;
 background: #fffaf5;
 font-size: 12px;
}

.writing-reference-structure-review.approved {
 border-color: #bfe7ce;
 border-left-color: var(--success);
 background: var(--success-bg);
}

.writing-reference-structure-review > div:first-child,
.writing-reference-anchor-list {
 display: flex;
 align-items: center;
 gap: 6px;
}

.writing-reference-structure-review > div:first-child {
 justify-content: space-between;
}

.writing-reference-structure-review p,
.writing-reference-structure-review small {
 margin: 0;
 color: var(--muted);
 line-height: 1.45;
 overflow-wrap: anywhere;
}

.writing-reference-structure-review label {
 display: grid;
 gap: 4px;
 color: var(--muted);
 font-size: 12px;
 font-weight: 700;
}

.writing-reference-structure-review textarea {
 min-height: 58px;
 resize: vertical;
}

.writing-reference-structure-review .button-row {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 5px;
}

.writing-reference-anchor-list {
 flex-wrap: wrap;
}

.writing-reference-anchor-list span {
 border: 1px solid #d9dee5;
 border-radius: 3px;
 padding: 2px 5px;
 background: #fff;
 color: #4c5967;
 font-size: 10px;
}

.writing-reference-span-controls {
 width: 100%;
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(150px, 0.8fr) minmax(240px, 1.4fr) auto;
 align-items: end;
 gap: 8px;
}

.writing-reference-span-pager {
 min-height: 34px;
 display: flex;
 align-items: center;
 justify-content: flex-end;
 gap: 5px;
 color: var(--muted);
 font-size: 11px;
 white-space: nowrap;
}

.writing-reference-span-pager button {
 width: 30px;
 min-width: 30px;
 height: 30px;
 padding: 0;
}

.writing-reference-select,
.writing-reference-span-controls label,
.writing-reference-span-controls select {
 min-width: 0;
 max-width: 100%;
}

.writing-reference-select select,
.writing-reference-span-controls select {
 width: 100%;
}

@media (max-width: 1399px) {
 .writing-reference-span-controls {
 grid-template-columns: minmax(140px, 0.8fr) minmax(220px, 1.2fr);
 }

 .writing-reference-span-pager {
 grid-column: 1 / -1;
 }
}

.writing-reference-panel:not(.authoring-mode) .writing-reference-span-controls {
 grid-template-columns: minmax(0, 1fr);
}

.writing-reference-panel:not(.authoring-mode) .writing-reference-span-pager {
 grid-column: 1;
 justify-content: flex-start;
 white-space: normal;
}

.writing-reference-validation-checks {
 display: grid;
 gap: 4px;
}

.writing-reference-validation-checks > div {
 display: grid;
 grid-template-columns: 64px 48px minmax(0, 1fr);
 gap: 6px;
 align-items: start;
 padding-top: 4px;
 border-top: 1px solid var(--soft-line);
}

.writing-reference-validation-checks b {
 font-size: 11px;
}

.writing-reference-validation-checks small {
 min-width: 0;
 overflow-wrap: anywhere;
 word-break: break-word;
}

.writing-reference-override {
 border-top: 1px solid var(--soft-line);
 padding-top: 7px;
 display: grid;
 gap: 6px;
}

.writing-reference-validation.requires-review {
 border-left: 3px solid #ea580c;
 background: #fffaf5;
}

.writing-reference-override textarea {
 min-height: 64px;
 resize: vertical;
}

.writing-reference-override-warning {
 display: flex;
 align-items: flex-start;
 gap: 6px;
 color: #9a3412;
 font-size: 11px;
 line-height: 1.45;
}

.writing-reference-override-warning svg {
 flex: 0 0 auto;
 margin-top: 1px;
}

.writing-reference-override fieldset {
 min-width: 0;
 margin: 0;
 padding: 7px;
 border: 1px solid #fed7aa;
 border-radius: 4px;
 display: grid;
 gap: 6px;
}

.writing-reference-override legend {
 padding: 0 4px;
 color: var(--muted);
 font-size: 11px;
}

.writing-reference-override-check {
 display: grid;
 grid-template-columns: 16px minmax(0, 1fr);
 align-items: start;
 gap: 6px;
 cursor: pointer;
}

.writing-reference-override-check input {
 margin: 2px 0 0;
}

.writing-reference-override-check span,
.writing-reference-override-check small {
 min-width: 0;
 display: block;
}

.writing-reference-override-check small {
 margin-top: 2px;
 overflow-wrap: anywhere;
 color: var(--muted);
 line-height: 1.4;
}

.writing-reference-override-record {
 display: grid;
 grid-template-columns: max-content minmax(0, 1fr);
 align-items: start;
 gap: 8px;
 padding: 7px;
 border: 1px solid #bfdbfe;
 border-radius: 4px;
 background: #eff6ff;
}

.writing-reference-override-record p {
 min-width: 0;
 margin: 0;
 overflow-wrap: anywhere;
 font-size: 11px;
 line-height: 1.45;
}

.writing-reference-override-record strong {
 display: block;
 margin-bottom: 2px;
}

.writing-reference-list > button strong,
.writing-reference-list > button small,
.writing-reference-document-row strong,
.writing-reference-brief strong,
.writing-reference-brief small {
 min-width: 0;
 overflow-wrap: anywhere;
}

.writing-reference-list > button > strong {
 display: -webkit-box;
 -webkit-box-orient: vertical;
 -webkit-line-clamp: 2;
 overflow: hidden;
 line-height: 1.4;
}

.writing-reference-list small,
.writing-reference-document-row p,
.writing-reference-brief small {
 margin: 0;
 color: var(--muted);
 font-size: 11px;
 line-height: 1.4;
}

.writing-reference-actions,
.writing-reference-review {
 min-width: 0;
 border-top: 1px solid var(--soft-line);
 padding-top: 9px;
 display: grid;
 gap: 8px;
}

.writing-reference-actions textarea,
.writing-reference-review textarea {
 min-height: 68px;
 resize: vertical;
}

.writing-reference-actions .button-row,
.writing-reference-review .button-row {
 display: grid;
 grid-template-columns: repeat(3, minmax(0, 1fr));
 gap: 5px;
}

.writing-reference-actions .button-row button,
.writing-reference-review .button-row button {
 min-width: 0;
 min-height: 34px;
 padding: 4px 6px;
 white-space: normal;
 line-height: 1.25;
}

.writing-reference-document-row {
 display: grid;
 gap: 7px;
}

.writing-reference-document-row > div {
 justify-content: flex-start;
}

.writing-reference-document-row code,
.writing-reference-source code,
.writing-reference-brief code {
 color: #4c5967;
 font-size: 10px;
 overflow-wrap: anywhere;
 white-space: normal;
}

.writing-reference-document-row a,
.writing-reference-document-row button {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 5px;
}

.writing-reference-document-row a {
 border: 1px solid var(--line);
 border-radius: 4px;
 color: var(--text);
 text-decoration: none;
}

.writing-reference-source,
.writing-reference-translation {
 min-width: 0;
 max-width: 100%;
 display: grid;
 gap: 6px;
}

.writing-reference-source > span,
.writing-reference-translation > span {
 color: var(--muted);
 font-size: 11px;
 font-weight: 700;
}

.writing-reference-source p,
.writing-reference-translation p {
 min-width: 0;
 max-width: 100%;
 max-height: 180px;
 margin: 0;
 overflow-y: auto;
 overflow-wrap: anywhere;
 word-break: break-word;
 white-space: pre-wrap;
 line-height: 1.55;
}

.writing-reference-cross-page-source {
 border-top: 1px solid var(--soft-line);
 padding-top: 6px;
}

.writing-reference-cross-page-source summary {
 color: #314a61;
 cursor: pointer;
 font-size: 11px;
 font-weight: 700;
}

.writing-reference-cross-page-source > div {
 margin-top: 6px;
 display: grid;
 gap: 7px;
}

.writing-reference-cross-page-source section {
 min-width: 0;
 border-left: 2px solid #d0a55d;
 padding-left: 8px;
}

.writing-reference-cross-page-source section p {
 max-height: 96px;
 margin-top: 3px;
 font-size: 12px;
}

.writing-reference-cross-page-source small {
 color: var(--muted);
 font-size: 10px;
}

.writing-reference-translation {
 border-top: 1px solid var(--soft-line);
 padding-top: 8px;
}

.writing-reference-review-state {
 align-items: flex-start;
 justify-content: flex-start;
 color: var(--muted);
 font-size: 12px;
}

.writing-reference-selection-head {
 min-height: 30px;
 border-bottom: 1px solid var(--soft-line);
 padding-bottom: 7px;
}

.writing-reference-selection-head span {
 color: var(--info);
 font-weight: 700;
}

.writing-reference-brief {
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 gap: 8px;
 align-items: start;
}

.writing-reference-brief > span {
 min-width: 0;
 display: grid;
 gap: 5px;
}

.writing-reference-brief small {
 white-space: pre-wrap;
}

.writing-reference-brief.invalid {
 background: #fafafa;
 color: var(--muted);
}

.writing-reference-brief.invalid small {
 text-decoration: line-through;
}

.writing-reference-empty {
 min-height: 110px;
 border: 1px dashed var(--line);
 border-radius: 4px;
 display: grid;
 place-items: center;
 padding: 14px;
 color: var(--muted);
 text-align: center;
}

.diff-box {
 display: grid;
 gap: 8px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 10px;
}

.diff-box del {
 color: var(--danger);
 background: var(--danger-bg);
 text-decoration: line-through;
}

.diff-box ins {
