 font-size: 11px;
 line-height: 1.45;
}

.authoring-open-competitor-drawer {
 flex: 0 0 auto;
 min-height: 34px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
 white-space: nowrap;
}

.authoring-competitor-drawer-host {
