 inset: 0;
 z-index: 48;
 pointer-events: none;
}

.authoring-competitor-drawer-host.is-open {
 pointer-events: auto;
}

.authoring-competitor-drawer-backdrop {
 position: absolute;
 inset: 0;
 border: 0;
 padding: 0;
 margin: 0;
 background: rgba(29, 39, 49, 0.28);
 opacity: 0;
 transition: opacity 0.18s ease;
 cursor: pointer;
}

.authoring-competitor-drawer-host.is-open .authoring-competitor-drawer-backdrop {
 opacity: 1;
}

.authoring-competitor-drawer {
 position: absolute;
 top: 0;
 right: 0;
 width: min(560px, 100vw);
 height: 100vh;
 border: 0;
 border-left: 1px solid var(--line);
 border-radius: 0;
 display: grid;
 grid-template-rows: auto minmax(0, 1fr);
 gap: 0;
