 ? {}
 : {
 "data-line-height": attributes.lineHeight,
 style: `line-height: ${attributes.lineHeight}`,
 },
 },
 spacingBeforePt: {
 default: null,
 parseHTML: (element) => numericDataAttribute(element, "data-spacing-before-pt"),
 renderHTML: (attributes) => attributes.spacingBeforePt == null
 ? {}
 : {
