 >
 {[1, 1.15, 1.25, 1.5, 2].map((value) => <option key={value} value={value}>{value}</option>)}
 </select>
 </label>
 <div className="rich-paragraph-settings">
 <button
 type="button"
 className={paragraphSettingsOpen ? "active" : ""}
 disabled={formattingDisabled}
