 ));
 if (target) insertCrossReference(editor, target);
 event.target.value = "";
 }}
 >
 <option value="">交叉引用</option>
 {(documentIndex?.tables || []).length > 0 && (
 <optgroup label="表">
 {documentIndex.tables.map((item) => (
 <option key={`table:${item.object_id}`} value={`table:${item.object_id}`}>
 {item.display_label}
