 title="选择要查看或编辑的表格"
 >
 {tableBlocks.map((block, index) => (
 <option key={block.block_id} value={block.block_id}>
 {`表格 ${index + 1}｜${block.structured_table?.title || block.title || block.title_hint || section.title}`}
 </option>
 ))}
 </select>
 </label>
 )}
 {activeTableBlock && (
 <button
 type="button"
 className="rich-table-designer-button"
