 title={readOnly ? "全屏查看当前表格" : "全屏编辑当前表格结构与附注"}
 aria-label={readOnly ? "全屏查看当前表格" : "全屏编辑当前表格结构与附注"}
 onClick={() => setDesignerOpen(true)}
 >
 <Maximize2 size={15} />
 </button>
 )}
 {!readOnly && (
 <div className="rich-table-template-menu">
 <button
 type="button"
