.monitoring-assurance-provenance-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px; }
.monitoring-assurance-provenance-grid > div { display: grid; gap: 3px; min-width: 0; padding: 7px 8px; border: 1px solid #f0dfb2; border-radius: 7px; background: rgba(255,255,255,.56); }
