.monitoring-assurance-readiness-counts span { padding: 6px 7px; border-radius: 7px; background: rgba(255,255,255,.72); color: #718391; font-size: 10px; }
.monitoring-assurance-readiness-counts b { display: block; margin-top: 2px; color: #27465b; font-size: 12px; }
.monitoring-assurance-readiness-content span, .monitoring-assurance-readiness-notice span { color: #607b8d; font-size: 10px; line-height: 1.45; overflow-wrap: anywhere; }
