.monitoring-assurance-rollup-empty { margin: 9px 0 2px; color: #7c8d9b; font-size: 11px; }
.monitoring-assurance-rollup-more { display: block; margin-top: 6px; color: #8494a0; font-size: 10px; }

.monitoring-assurance-audit {
 display: grid;
 gap: 8px;
 margin-top: 12px;
 padding-top: 12px;
 border-top: 1px solid #e3ebf2;
}
.monitoring-assurance-audit-title { display: flex; align-items: center; justify-content: space-between; gap: 8px; color: #4c6475; font-size: 11px; }
.monitoring-assurance-audit-title strong { display: inline-flex; align-items: center; gap: 5px; color: #27465b; }
.monitoring-assurance-audit-title span { color: #8292a0; font-size: 10px; }
.monitoring-assurance-audit-notice { display: flex; align-items: flex-start; gap: 7px; padding: 8px 9px; border: 1px solid #eed69c; border-radius: 8px; background: #fffaf0; color: #8a650e; }
.monitoring-assurance-audit.error .monitoring-assurance-audit-notice { border-color: #efc5b6; background: #fff6f2; color: #a13e2d; }
.monitoring-assurance-audit-notice > div { min-width: 0; display: grid; gap: 2px; }
.monitoring-assurance-audit-notice strong { font-size: 11px; }
.monitoring-assurance-audit-notice span { color: #806f57; font-size: 10px; line-height: 1.4; overflow-wrap: anywhere; }
.monitoring-assurance-audit.error .monitoring-assurance-audit-notice span { color: #8f6658; }
.monitoring-assurance-audit-notice button { flex: 0 0 auto; margin-left: auto; padding: 3px 6px; border: 1px solid #d6b6a4; border-radius: 5px; background: #fff; color: #9a4d35; cursor: pointer; font-size: 10px; }
.monitoring-assurance-audit-empty { margin: 0; padding: 8px 9px; border: 1px solid #e0e9f1; border-radius: 8px; background: #f8fbfd; color: #748793; font-size: 10px; line-height: 1.45; }
.monitoring-assurance-audit-list { display: grid; gap: 0; max-height: 220px; overflow: auto; margin: 0; padding: 0; list-style: none; border: 1px solid #e0e9f1; border-radius: 8px; background: #fff; }
.monitoring-assurance-audit-list li { display: grid; grid-template-columns: 22px minmax(0, 1fr) auto; align-items: center; gap: 7px; min-height: 36px; padding: 5px 8px; border-bottom: 1px solid #edf2f5; }
.monitoring-assurance-audit-list li:last-child { border-bottom: 0; }
.monitoring-assurance-audit-index { display: inline-flex; align-items: center; justify-content: center; width: 20px; height: 20px; border-radius: 50%; background: #eef4f8; color: #35657f; font-size: 10px; font-weight: 700; }
.monitoring-assurance-audit-list li > div { min-width: 0; display: grid; gap: 2px; }
.monitoring-assurance-audit-list strong { overflow: hidden; color: #294b61; font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-assurance-audit-list small { overflow: hidden; color: #788a98; font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-assurance-audit-list code { max-width: 104px; overflow: hidden; color: #6d8290; font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-assurance-audit-footnote { margin: 0; color: #8494a0; font-size: 9px; line-height: 1.4; overflow-wrap: anywhere; }

@media (max-width: 900px) {
 .monitoring-assurance-snapshot-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
 .monitoring-assurance-body { grid-template-columns: 1fr; }
 .monitoring-assurance-rollup-stats { grid-template-columns: repeat(3, minmax(0, 1fr)); }
 .monitoring-assurance-rollup-grid { grid-template-columns: 1fr; }
 .monitoring-assurance-action-status-list { grid-template-columns: 1fr; }
 .monitoring-assurance-provenance-grid { grid-template-columns: 1fr; }
}

@media (max-width: 600px) {
 .monitoring-assurance-head, .monitoring-assurance-mode-row, .monitoring-assurance-snapshot-grid, .monitoring-assurance-body { padding-left: 12px; padding-right: 12px; }
 .monitoring-assurance-blocker, .monitoring-assurance-create-row, .monitoring-assurance-message { margin-left: 12px; margin-right: 12px; }
 .monitoring-assurance-snapshot-grid { grid-template-columns: 1fr 1fr; }
 .monitoring-assurance-create-row { align-items: flex-start; flex-direction: column; }
 .monitoring-assurance-rollup-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
 .monitoring-assurance-conservation { align-items: flex-start; flex-direction: column; gap: 2px; }
}

import { useCallback, useEffect, useMemo, useState } from "react";
import {
 ArrowUpRight,
 BarChart3,
 CheckCircle2,
 ClipboardCheck,
 Database,
 History,
 MapPin,
 RefreshCw,
 ShieldAlert,
 UserRound,
 XCircle,
} from "lucide-react";

import {
 createMedicalMonitoringAssuranceApi,
 MedicalMonitoringAssuranceApiError,
} from "./medicalMonitoringAssuranceApi.mjs";
import {
 ASSURANCE_MODES,
 FROZEN_IDENTITY_FIELDS,
 assuranceEvidenceState,
 assuranceActionAvailability,
 assuranceAuditActionLabel,
 assuranceModeLabel,
 assuranceModeDescription,
 assuranceReadinessInput,
 assuranceReadinessPayload,
 assuranceReadinessState,
 assuranceStatusLabel,
 assuranceStatusTone,
 assuranceTaskCreationAllowed,
 assuranceTaskDisplayKey,
 assuranceTaskList,
 completeFrozenIdentity,
 missingFrozenIdentityFields,
} from "./medicalMonitoringAssurance.mjs";
import {
 assuranceRollupNumber,
 assuranceRollupRowDisplayKey,
 projectAssuranceRollup,
} from "./medicalMonitoringAssuranceRollup.mjs";
import {
 MedicalMonitoringAssuranceShapeError,
 normalizeAssuranceCreateResponse,
 normalizeAssuranceAuditPayload,
 normalizeAssuranceProofPayload,
 normalizeAssuranceReadinessPayload,
 normalizeAssuranceRollupPayload,
 normalizeAssuranceTaskList,
 normalizeAssuranceTaskPayload,
} from "./medicalMonitoringAssuranceView.mjs";
import {
 MedicalMonitoringPrincipalShapeError,
 monitoringPrincipalBlocker,
 monitoringPrincipalReady,
 monitoringPrincipalStatusLabel,
 normalizeMonitoringPrincipal,
} from "./medicalMonitoringPrincipal.mjs";
import MedicalMonitoringAssuranceRemediation from "./MedicalMonitoringAssuranceRemediation.jsx";
import {
 createMedicalMonitoringProjectRequestScope,
} from "./medicalMonitoringProjectRequestScope.mjs";
import "./MedicalMonitoringAssurancePanel.css";

function requestKey(prefix) {
 const random = globalThis.crypto?.randomUUID?.()
 || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
 return `${prefix}-${random}`;
}

function apiErrorMessage(error, fallback) {
 if (error instanceof MedicalMonitoringAssuranceApiError) return error.message;
 return error?.message || fallback;
}

function readIdentity({ currentSnapshot, sourceManifest, rawMonitoring }) {
 return currentSnapshot?.assurance_frozen_identity
 || sourceManifest?.assurance_frozen_identity
 || rawMonitoring?.assurance_frozen_identity
 || {};
}

function readPrincipal({ currentSnapshot, sourceManifest, rawMonitoring }) {
 return currentSnapshot?.monitoring_principal
 || sourceManifest?.monitoring_principal
 || rawMonitoring?.monitoring_principal
 || null;
}

function snapshotFacts(currentSnapshot = {}) {
 return [
 ["风险快照", currentSnapshot.snapshot_id || "未生成"],
 ["来源修订", currentSnapshot.source_revision || "未返回"],
 ["规则修订", currentSnapshot.rule_profile_revision || "未返回"],
 ["引擎版本", currentSnapshot.engine_version || "未返回"],
 ];
}

function EvidenceCard({ label, value, tone = "neutral" }) {
 return (
 <div className={`monitoring-assurance-evidence ${tone}`}>
 <span>{label}</span>
 <strong>{value}</strong>
 </div>
 );
}

function RollupStat({ label, value, tone = "neutral" }) {
 return (
 <div className={`monitoring-assurance-rollup-stat ${tone}`}>
 <span>{label}</span>
 <strong>{assuranceRollupNumber(value)}</strong>
 </div>
 );
}

function explicitArrayCount(value) {
 return Array.isArray(value) ? value.length : null;
}

function shortHash(value) {
 const text = String(value || "");
 return text ? `${text.slice(0, 10)}…${text.slice(-6)}` : "待返回";
}

function AssuranceAuditChain({ audit, loading, error, blockedReason, onRetry }) {
 if (blockedReason) {
 return (
 <section className="monitoring-assurance-audit blocked" aria-label="保障任务审计链读取阻断">
 <div className="monitoring-assurance-audit-title"><strong><ShieldAlert size={14} /> 审计链</strong><span>身份阻断</span></div>
 <div className="monitoring-assurance-audit-notice"><ShieldAlert size={15} /><div><strong>暂不能读取服务端审计链</strong><span>{blockedReason}</span></div></div>
 </section>
 );
 }
 if (loading) {
 return (
 <section className="monitoring-assurance-audit" aria-label="保障任务审计链读取中" role="status">
 <div className="monitoring-assurance-audit-title"><strong><History size={14} /> 审计链</strong><span>读取中</span></div>
 <p className="monitoring-assurance-audit-empty">正在读取服务端链证据。</p>
 </section>
 );
 }
 if (error) {
 return (
 <section className="monitoring-assurance-audit error" aria-label="保障任务审计链读取失败">
 <div className="monitoring-assurance-audit-title"><strong><History size={14} /> 审计链</strong><span>读取失败</span></div>
 <div className="monitoring-assurance-audit-notice"><ShieldAlert size={15} /><div><strong>链证据未加载</strong><span>{error}</span></div><button type="button" onClick={onRetry}>重试</button></div>
 </section>
 );
 }
 if (!audit) return null;
 if (!audit.items.length) {
 return (
 <section className="monitoring-assurance-audit empty" aria-label="保障任务审计链为空">
 <div className="monitoring-assurance-audit-title"><strong><History size={14} /> 审计链</strong><span>0 条</span></div>
 <p className="monitoring-assurance-audit-empty">当前任务尚无服务端审计事件；空链已由服务端身份授权后返回。</p>
 </section>
 );
 }
 return (
 <section className="monitoring-assurance-audit" aria-label="保障任务审计链">
 <div className="monitoring-assurance-audit-title"><strong><History size={14} /> 审计链</strong><span>{audit.items.length} 条 · 服务端已校验</span></div>
 <ol className="monitoring-assurance-audit-list">
 {audit.items.map((event, index) => (
 <li key={event.audit_id}>
 <span className="monitoring-assurance-audit-index">{index + 1}</span>
 <div><strong>{assuranceAuditActionLabel(event.action)}</strong><small>{event.occurred_at} · v{event.aggregate_version_before} → v{event.aggregate_version_after}</small></div>
 <code title={event.event_hash}>{shortHash(event.event_hash)}</code>
 </li>
 ))}
 </ol>
 <p className="monitoring-assurance-audit-footnote">验证身份：{audit.principal_id}；仅展示链摘要，不展开原始审计 payload。</p>
 </section>
 );
}

function AssuranceReadiness({ readiness, loading, error, blockedReason, input }) {
 const state = assuranceReadinessState({ readiness, input });
 if (blockedReason) {
 return (
 <section className="monitoring-assurance-readiness blocked" aria-label="保障任务 readiness 阻断">
 <div className="monitoring-assurance-readiness-title"><strong><ClipboardCheck size={14} /> 覆盖与冻结身份 readiness</strong><span>阻断</span></div>
 <div className="monitoring-assurance-readiness-notice"><ShieldAlert size={15} /><div><strong>暂不能核验完成门</strong><span>{blockedReason}</span></div></div>
 </section>
 );
 }
 if (loading) {
 return (
 <section className="monitoring-assurance-readiness" aria-label="保障任务 readiness 读取中" role="status">
 <div className="monitoring-assurance-readiness-title"><strong><ClipboardCheck size={14} /> 覆盖与冻结身份 readiness</strong><span>读取中</span></div>
 <p className="monitoring-assurance-readiness-empty">正在核验当前任务的冻结身份与项目/中心/个例覆盖。</p>
 </section>
 );
 }
 if (error) {
 return (
 <section className="monitoring-assurance-readiness error" aria-label="保障任务 readiness 读取失败">
 <div className="monitoring-assurance-readiness-title"><strong><ClipboardCheck size={14} /> 覆盖与冻结身份 readiness</strong><span>读取失败</span></div>
 <div className="monitoring-assurance-readiness-notice"><ShieldAlert size={15} /><div><strong>readiness 未加载</strong><span>{error}</span></div></div>
 </section>
 );
 }
 if (!readiness && !input?.available) return null;
 return (
 <section className={`monitoring-assurance-readiness ${state.tone}`} aria-label="保障任务 readiness">
 <div className="monitoring-assurance-readiness-title"><strong><ClipboardCheck size={14} /> 覆盖与冻结身份 readiness</strong><span>{state.label}</span></div>
 {input?.available && (
 <div className="monitoring-assurance-readiness-counts" aria-label="readiness 覆盖计数">
 <span>受试者 <b>{input.actual_subjects}</b></span>
 <span>中心 <b>{input.actual_sites}</b></span>
 <span>关键域 <b>{input.critical_domains_expected ? `${input.critical_domains_covered}/${input.critical_domains_expected}` : "未配置"}</b></span>
 </div>
 )}
 <div className="monitoring-assurance-readiness-content">
 <strong>{state.ready ? "当前任务可进入证据完成门" : "当前任务仍不能进入证据完成门"}</strong>
 <span>{state.ready ? "服务端已确认冻结身份未漂移，且已提供项目、中心与个例覆盖计数。" : state.blockingReason}</span>
 </div>
 </section>
 );
}

function AssuranceActionStatus({ availability, task, evidence }) {
 const summary = task || {};
 const evidenceReady = evidence?.ready === true;
 const reviewReady = summary.medical_review_recorded === true;
 const completed = summary.status === "completed";
 const rows = [
 {
 label: "证据生成",
 state: evidenceReady ? "已具备" : availability.canRecordEvidence ? "待受控生成" : "阻断",
 tone: evidenceReady ? "success" : availability.canRecordEvidence ? "warning" : "danger",
 detail: evidenceReady ? evidence.label : (availability.evidenceBlocker || "尚未形成可核验证据。"),
 },
 {
 label: "医学复核",
 state: reviewReady ? "已记录" : availability.canReview ? "待复核" : "阻断",
 tone: reviewReady ? "success" : availability.canReview ? "warning" : "danger",
 detail: reviewReady ? "服务端已记录医学复核。" : (availability.reviewBlocker || "证据未先完成，不能进入医学复核。"),
 },
 {
 label: "完成保障",
 state: completed ? "已完成" : availability.canComplete ? "待确认" : "阻断",
 tone: completed ? "success" : availability.canComplete ? "warning" : "danger",
 detail: completed ? "任务已由服务端完成。" : (availability.completeBlocker || "完成前仍需满足所有完成门。"),
 },
 ];
 return (
 <section className="monitoring-assurance-action-status" aria-label="保障动作完成顺序">
 <div className="monitoring-assurance-action-status-title"><strong><ClipboardCheck size={14} /> 动作完成顺序</strong><span>服务端门禁</span></div>
 <div className="monitoring-assurance-action-status-list">
 {rows.map((row) => (
 <div className={`monitoring-assurance-action-status-row ${row.tone}`} key={row.label}>
 <span className="monitoring-assurance-action-status-label">{row.label}</span>
 <strong>{row.state}</strong>
 <small>{row.detail}</small>
 </div>
 ))}
 </div>
 <p className="monitoring-assurance-action-status-note">当前仅展示服务端动作合同与阻断原因；不会在 readiness 未通过或运行时 gate 未放行时替用户提交证据、复核或签名。</p>
 </section>
 );
}

function AssuranceProvenanceDisclosure({ provenanceStatus }) {
 if (provenanceStatus !== "mixed_provenance") return null;
 return (
 <details className="monitoring-assurance-provenance">
 <summary><ShieldAlert size={14} /> 为什么当前 proof 不能作为完成证据</summary>
 <div className="monitoring-assurance-provenance-body">
 <p>当前 proof 同时包含服务端重算结果与调用方携带字段；在这些字段尚未全部绑定到可复核的服务端权威执行来源前，它只能用于只读诊断，不能通过锁库前完成门。</p>
 <div className="monitoring-assurance-provenance-grid">
 <div><strong>可以做什么</strong><span>查看返回结构、定位失败或缺口，并把问题交给正式复核。</span></div>
 <div><strong>仍缺什么</strong><span>服务端 evidence-run ledger，或签名清单的全字段服务端重验。</span></div>
 </div>
 <small>待选择并实现一种证据权威路线后，系统才会重新核验；当前状态不代表项目已完成。</small>
 </div>
 </details>
 );
}

function AssuranceRollup({ rollup, onClose, onRiskScopeChange, onSelectSubject, onOpenSubjectView }) {
 const view = projectAssuranceRollup(rollup);
 const severityEntries = view.distributions.severity.slice(0, 4);
 const maxSeverity = Math.max(1, ...severityEntries.map((entry) => entry.value));
 const subjectRows = view.subjects.slice(0, 8);
 const siteRows = view.sites.slice(0, 6);
 const openSite = (row) => {
 if (!onRiskScopeChange || row?.identityState !== "ready") return;
 onClose?.();
 onRiskScopeChange("site", { siteId: row.siteId });
 };
 const openSubject = (row, page) => {
 if (!onOpenSubjectView || row?.identityState !== "ready" || !row.subjectId) return;
 onSelectSubject?.(row.subjectId);
 onClose?.();
 onOpenSubjectView(page, "", row.subjectId);
 };
 const focusRemediation = (row) => {
 if (row.subjectId && row.subjectId !== "未标识受试者" && onOpenSubjectView) {
 onSelectSubject?.(row.subjectId);
 onClose?.();
 onOpenSubjectView("patientProfile", "", row.subjectId);
 return;
 }
 if (row.siteId && row.siteId !== "未标识中心") {
 onClose?.();
 onRiskScopeChange?.("site", { siteId: row.siteId });
 }
 };

 return (
 <section className="monitoring-assurance-rollup" aria-label="项目中心受试者三级风险总览">
 <div className="monitoring-assurance-section-title">
 <strong><BarChart3 size={15} /> 三级风险总览</strong>
 <span>{view.riskSnapshotId ? `快照 ${view.riskSnapshotId}` : "当前任务汇总"}</span>
 </div>
 <div className="monitoring-assurance-rollup-stats">
 <RollupStat label="项目风险" value={view.trial.totalRiskCount} />
 <RollupStat label="开放风险" value={view.trial.openRiskCount} tone="warning" />
 <RollupStat label="开放高风险" value={view.trial.openHighRiskCount} tone="danger" />
 <RollupStat label="已关闭" value={view.trial.closedRiskCount} tone="success" />
 <RollupStat label="缺关闭证据" value={view.trial.closedWithoutEvidenceCount} tone={view.trial.closedWithoutEvidenceCount ? "danger" : "neutral"} />
 </div>
 <div className={`monitoring-assurance-conservation ${view.conservation.ok ? "ok" : "blocked"}`} role="status">
 <strong>{view.conservation.ok ? "三级对账通过" : "三级对账阻断"}</strong>
 <span>{view.conservation.ok ? "项目、中心、个例使用同一 risk_instance_id 集合。" : "风险身份或显式计数不守恒；当前只读展示，不允许完成保障任务。"}</span>
 </div>
 {severityEntries.length > 0 && (
 <div className="monitoring-assurance-distribution" aria-label="风险严重度分布">
 <div className="monitoring-assurance-mini-title">严重度分布</div>
 {severityEntries.map((entry) => (
 <div className="monitoring-assurance-distribution-row" key={entry.label}>
 <span>{entry.label}</span>
 <i><b style={{ width: `${Math.round((entry.value / maxSeverity) * 100)}%` }} /></i>
 <strong>{entry.value}</strong>
 </div>
 ))}
 </div>
 )}
 <div className="monitoring-assurance-rollup-grid">
 <div className="monitoring-assurance-rollup-list">
 <div className="monitoring-assurance-mini-title"><MapPin size={14} /> 中心层 <span>{view.sites.length} 个</span></div>
 {!siteRows.length && <p className="monitoring-assurance-rollup-empty">暂无中心级风险引用。</p>}
 {siteRows.map((row, index) => (
 <div className="monitoring-assurance-rollup-row" key={assuranceRollupRowDisplayKey(row, "site", index)}>
 <div><strong>{row.siteId}</strong><small>{assuranceRollupNumber(row.totalRiskCount)} 项风险 · 开放 {assuranceRollupNumber(row.openRiskCount)}</small></div>
 <span className={row.openHighRiskCount ? "danger" : "neutral"}>高风险 {assuranceRollupNumber(row.openHighRiskCount)}</span>
 {row.identityState === "ready" && onRiskScopeChange
 ? <button type="button" title={`查看中心 ${row.siteId} 的风险`} onClick={() => openSite(row)}><ArrowUpRight size={14} /></button>
 : <small title={row.identityIssue}>身份待核对，仅可读</small>}
 </div>
 ))}
 {view.sites.length > siteRows.length && <small className="monitoring-assurance-rollup-more">仅显示开放风险优先的前 {siteRows.length} 个中心。</small>}
 </div>
 <div className="monitoring-assurance-rollup-list">
 <div className="monitoring-assurance-mini-title"><UserRound size={14} /> 个例层 <span>{view.subjects.length} 个</span></div>
 {!subjectRows.length && <p className="monitoring-assurance-rollup-empty">暂无个例级风险引用。</p>}
 {subjectRows.map((row, index) => (
 <div className="monitoring-assurance-rollup-row subject" key={assuranceRollupRowDisplayKey(row, "subject", index)}>
 <div><strong>{row.subjectId}</strong><small>中心 {row.siteId} · 风险 {assuranceRollupNumber(row.totalRiskCount)} · 开放 {assuranceRollupNumber(row.openRiskCount)}</small></div>
 {row.identityState === "ready" && onOpenSubjectView ? (
 <span className="monitoring-assurance-subject-actions">
 <button type="button" title={`打开 ${row.subjectId} Patient Profile`} onClick={() => openSubject(row, "patientProfile")}>Profile</button>
 <button type="button" title={`打开 ${row.subjectId} Subject Timeline`} onClick={() => openSubject(row, "subjectTimeline")}>Timeline</button>
 </span>
 ) : <small title={row.identityIssue}>身份待核对，仅可读</small>}
 </div>
 ))}
 {view.subjects.length > subjectRows.length && <small className="monitoring-assurance-rollup-more">仅显示开放风险优先的前 {subjectRows.length} 个个例。</small>}
 </div>
 </div>
 <MedicalMonitoringAssuranceRemediation matrix={rollup?.remediation_matrix} onFocusRow={focusRemediation} />
 </section>
 );
}

export default function MedicalMonitoringAssurancePanel(props) {
 return (
 <MedicalMonitoringAssurancePanelForProject
 key={props.projectId}
 {...props}
 />
 );
}

function MedicalMonitoringAssurancePanelForProject({
 projectId,
 open,
 onClose,
 onOpenSubjectView,
 onRiskScopeChange,
 onSelectSubject,
 currentSnapshot,
 sourceManifest,
 rawMonitoring,
}) {
 const api = useMemo(() => createMedicalMonitoringAssuranceApi(), []);
 const requestScope = useMemo(
 () => createMedicalMonitoringProjectRequestScope(projectId),
 [projectId],
 );
 const [mode, setMode] = useState("pre_lock");
 const [items, setItems] = useState([]);
 const [selectedTaskId, setSelectedTaskId] = useState("");
 const [selectedTask, setSelectedTask] = useState(null);
 const [proof, setProof] = useState(null);
 const [proofProvenanceStatus, setProofProvenanceStatus] = useState("");
 const [rollup, setRollup] = useState(null);
 const [audit, setAudit] = useState(null);
 const [auditLoading, setAuditLoading] = useState(false);
 const [auditError, setAuditError] = useState("");
 const [auditBlockedReason, setAuditBlockedReason] = useState("");
 const [readiness, setReadiness] = useState(null);
 const [readinessLoading, setReadinessLoading] = useState(false);
 const [readinessError, setReadinessError] = useState("");
 const [readinessBlockedReason, setReadinessBlockedReason] = useState("");
 const [readinessInput, setReadinessInput] = useState(null);
 const [loading, setLoading] = useState(false);
 const [detailLoading, setDetailLoading] = useState(false);
 const [creating, setCreating] = useState(false);
 const [message, setMessage] = useState("");
 const [error, setError] = useState("");
 const [principalClock, setPrincipalClock] = useState(() => Date.now());
 const frozenIdentity = useMemo(
 () => readIdentity({ currentSnapshot, sourceManifest, rawMonitoring }),
 [currentSnapshot, rawMonitoring, sourceManifest],
 );
 const identityReady = completeFrozenIdentity(frozenIdentity);
 const missingIdentity = missingFrozenIdentityFields(frozenIdentity);
 const authorityWritePermitted = currentSnapshot?.assurance_write_permitted === true
 || sourceManifest?.assurance_write_permitted === true
 || rawMonitoring?.assurance_write_permitted === true;
 const principalState = useMemo(() => {
 const rawPrincipal = readPrincipal({ currentSnapshot, sourceManifest, rawMonitoring });
 if (!rawPrincipal) return { principal: null, error: "" };
 try {
 return {
 principal: normalizeMonitoringPrincipal(rawPrincipal, { projectId }),
 error: "",
 };
 } catch (nextError) {
 return {
 principal: null,
 error: nextError instanceof MedicalMonitoringPrincipalShapeError
 ? nextError.message
 : "服务端认证 principal 结构无法验证。",
 };
 }
 }, [currentSnapshot, projectId, rawMonitoring, sourceManifest]);
 useEffect(() => {
 const expiresAt = principalState.principal?.expiresAt;
 if (!expiresAt) return undefined;
 const remaining = new Date(expiresAt).getTime() - Date.now();
 if (!Number.isFinite(remaining) || remaining <= 0) {
 setPrincipalClock(Date.now());
 return undefined;
 }
 const timer = globalThis.setTimeout(() => setPrincipalClock(Date.now()), remaining + 1);
 return () => globalThis.clearTimeout(timer);
 }, [principalState.principal?.expiresAt]);
 const principalNow = useMemo(() => new Date(principalClock), [principalClock]);
 const principalReady = monitoringPrincipalReady(principalState.principal, { projectId, now: principalNow });
 const taskCreationAllowed = assuranceTaskCreationAllowed(frozenIdentity, authorityWritePermitted)
 && principalReady;
 const taskSummaries = useMemo(() => assuranceTaskList(items), [items]);
 const activeTask = selectedTask || taskSummaries.find((task) => task.id === selectedTaskId && task.identityState === "ready") || null;
 const evidence = assuranceEvidenceState({ task: selectedTask || activeTask || { mode }, proof, rollup });
 const visibleEvidence = proofProvenanceStatus === "mixed_provenance" && !proof
 ? {
 ...evidence,
 label: "证据来源混合",
 provenanceStatus: proofProvenanceStatus,
 ready: false,
 blockingReason: "证据来源混合，不能作为全量重算完成证明。",
 }
 : { ...evidence, blockingReason: evidence.blockingReason };
 const actionAvailability = useMemo(() => assuranceActionAvailability({
 task: selectedTask || activeTask || { mode },
 principalReady,
 authorityWritePermitted,
 evidenceReady: visibleEvidence.ready,
 evidenceRecorded: Boolean(proof || rollup),
 evidenceBlockingReason: evidence.blockingReason,
 ...(visibleEvidence.provenanceStatus === "mixed_provenance"
 ? { evidenceBlockingReason: visibleEvidence.blockingReason }
 : {}),
 readinessReady: readiness?.ready === true,
 }), [activeTask, authorityWritePermitted, mode, principalReady, proof, readiness?.ready, rollup, selectedTask, visibleEvidence.blockingReason, visibleEvidence.ready]);

 const clearLoadedState = useCallback(() => {
 setItems([]);
 setSelectedTaskId("");
 setSelectedTask(null);
 setProof(null);
 setProofProvenanceStatus("");
 setRollup(null);
 setAudit(null);
 setAuditError("");
 setAuditBlockedReason("");
 setReadiness(null);
 setReadinessError("");
 setReadinessBlockedReason("");
 setReadinessInput(null);
 }, []);

 const loadTasks = useCallback(async (nextMode = mode) => {
 if (!projectId) return;
 const request = requestScope.begin("assurance-task-list");
 setLoading(true);
 setError("");
 try {
 const payload = normalizeAssuranceTaskList(
 await api.listTasks(projectId, { mode: nextMode, signal: request.signal }),
 { projectId, mode: nextMode },
 );
 if (!requestScope.isCurrent(request)) return;
 const nextItems = Array.isArray(payload.items) ? payload.items : [];
 setItems(nextItems);
 const nextTaskSummaries = assuranceTaskList(nextItems);
 const nextId = nextTaskSummaries.find((task) => task.identityState === "ready")?.id || "";
 setSelectedTaskId((current) => current && nextTaskSummaries.some((task) => task.id === current && task.identityState === "ready") ? current : nextId);
 if (!nextId) {
 setSelectedTask(null);
 setProof(null);
 setProofProvenanceStatus("");
 setRollup(null);
 }
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return;
 if (nextError instanceof MedicalMonitoringAssuranceShapeError || nextError?.name !== "AbortError") {
 clearLoadedState();
 setError(apiErrorMessage(nextError, "保障任务读取失败。"));
 }
 } finally {
 if (requestScope.isCurrent(request)) setLoading(false);
 requestScope.finish(request);
 }
 }, [api, clearLoadedState, mode, projectId, requestScope]);

 const loadAudit = useCallback(async (taskId = selectedTaskId) => {
 if (!projectId || !taskId) {
 setAudit(null);
 setAuditLoading(false);
 setAuditError("");
 setAuditBlockedReason("");
 return;
 }
 setAudit(null);
 setAuditError("");
 setAuditBlockedReason("");
 setAuditLoading(false);
 if (!principalReady) {
 setAuditBlockedReason(monitoringPrincipalBlocker(
 principalState.principal,
 principalState.error,
 { now: principalNow },
 ));
 return;
 }
 const request = requestScope.begin("assurance-audit");
 setAuditLoading(true);
 try {
 const payload = normalizeAssuranceAuditPayload(
 await api.getAudit(projectId, taskId, { signal: request.signal }),
 { projectId, taskId },
 );
 if (!requestScope.isCurrent(request)) return;
 setAudit(payload);
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return;
 if (nextError?.name !== "AbortError") {
 setAuditError(apiErrorMessage(nextError, "保障任务审计链读取失败。"));
 }
 } finally {
 if (requestScope.isCurrent(request)) setAuditLoading(false);
 requestScope.finish(request);
 }
 }, [api, principalNow, principalReady, principalState.error, principalState.principal, projectId, requestScope, selectedTaskId]);

 useEffect(() => {
 requestScope.activate();
 return () => requestScope.dispose();
 }, [requestScope]);

 useEffect(() => {
 if (!open) return undefined;
 setMessage("");
 loadTasks(mode);
 return () => requestScope.cancel("assurance-task-list");
 }, [loadTasks, mode, open, requestScope]);

 useEffect(() => {
 if (!open || !selectedTaskId || !projectId) return undefined;
 const request = requestScope.begin("assurance-task-detail");
 setDetailLoading(true);
 setError("");
 setProofProvenanceStatus("");
 let rejectedProofProvenanceStatus = "";
 Promise.all([
 api.getTask(projectId, selectedTaskId, { signal: request.signal }),
 mode === "pre_lock"
 ? api.getProof(projectId, selectedTaskId, { signal: request.signal }).catch((nextError) => {
 if (nextError?.status === 404) return null;
 throw nextError;
 })
 : api.getRollups(projectId, selectedTaskId, { signal: request.signal }).catch((nextError) => {
 if (nextError?.status === 404) return null;
 throw nextError;
 }),
 ])
 .then(([rawTaskPayload, rawEvidencePayload]) => {
 if (!requestScope.isCurrent(request)) return;
 const taskPayload = normalizeAssuranceTaskPayload(rawTaskPayload, {
 projectId,
 taskId: selectedTaskId,
 });
 rejectedProofProvenanceStatus = mode === "pre_lock"
 ? String(rawEvidencePayload?.proof?.provenance_status || "").trim()
 : "";
 setSelectedTask(taskPayload.task || null);
 setProofProvenanceStatus(rejectedProofProvenanceStatus);
 if (mode === "pre_lock") {
 setProof(rawEvidencePayload
 ? normalizeAssuranceProofPayload(rawEvidencePayload, {
 projectId,
 taskId: selectedTaskId,
 }).proof
 : null);
 setRollup(null);
 } else {
 setRollup(rawEvidencePayload
 ? normalizeAssuranceRollupPayload(rawEvidencePayload, {
 projectId,
 taskId: selectedTaskId,
 }).rollup
 : null);
 setProof(null);
 }
 })
 .catch((nextError) => {
 if (!requestScope.isCurrent(request)) return;
 if (nextError?.name !== "AbortError") {
 if (rejectedProofProvenanceStatus === "mixed_provenance") {
 setProof(null);
 setRollup(null);
 setError("proof 已读取但来源混合；页面保留只读诊断并阻断完成门。");
 } else {
 setSelectedTask(null);
 setProof(null);
 setRollup(null);
 setProofProvenanceStatus("");
 setError(apiErrorMessage(nextError, "保障任务详情读取失败。"));
 }
 }
 })
 .finally(() => {
 if (requestScope.isCurrent(request)) setDetailLoading(false);
 requestScope.finish(request);
 });
 return () => requestScope.cancel("assurance-task-detail");
 }, [api, mode, open, projectId, requestScope, selectedTaskId]);

 useEffect(() => {
 if (!open || !selectedTaskId || !projectId) {
 setReadiness(null);
 setReadinessLoading(false);
 setReadinessError("");
 setReadinessBlockedReason("");
 setReadinessInput(null);
 return undefined;
 }
 const readinessTask = selectedTask || taskSummaries.find((task) => task.id === selectedTaskId) || {};
 const input = assuranceReadinessInput({
 currentSnapshot,
 sourceManifest,
 rawMonitoring,
 currentIdentity: frozenIdentity,
 task: readinessTask,
 });
 setReadiness(null);
 setReadinessInput(input);
 setReadinessError("");
 setReadinessBlockedReason("");
 if (!identityReady) {
 setReadinessBlockedReason(`冻结身份不完整，不能核验 readiness：${missingFrozenIdentityFields(frozenIdentity).join("、")}`);
 return undefined;
 }
 if (!principalReady) {
 setReadinessBlockedReason(monitoringPrincipalBlocker(
 principalState.principal,
 principalState.error,
 { now: principalNow },
 ));
 return undefined;
 }
 if (!input.available) {
 setReadinessBlockedReason(`项目覆盖计数未完整提供：${input.missingFields.join("、")}`);
 return undefined;
 }
 const request = requestScope.begin("assurance-readiness");
 setReadinessLoading(true);
 api.evaluateReadiness(projectId, selectedTaskId, assuranceReadinessPayload(input), { signal: request.signal })
 .then((payload) => {
 if (!requestScope.isCurrent(request)) return;
 setReadiness(normalizeAssuranceReadinessPayload(payload, {
 projectId,
 taskId: selectedTaskId,
 expectedVersion: input.expected_version,
 }));
 })
 .catch((nextError) => {
 if (!requestScope.isCurrent(request)) return;
 if (nextError?.name !== "AbortError") setReadinessError(apiErrorMessage(nextError, "readiness 读取失败。"));
 })
 .finally(() => {
 if (requestScope.isCurrent(request)) setReadinessLoading(false);
 requestScope.finish(request);
 });
 return () => requestScope.cancel("assurance-readiness");
 }, [api, currentSnapshot, frozenIdentity, identityReady, principalNow, principalReady, principalState.error, principalState.principal, projectId, rawMonitoring, requestScope, selectedTask, selectedTaskId, sourceManifest, taskSummaries]);

 useEffect(() => {
 if (!open || !selectedTaskId || !projectId) {
 setAudit(null);
 setAuditLoading(false);
 setAuditError("");
 setAuditBlockedReason("");
 return undefined;
 }
 loadAudit(selectedTaskId);
 return () => requestScope.cancel("assurance-audit");
 }, [loadAudit, open, projectId, requestScope, selectedTaskId]);

 const createTask = async () => {
 if (!taskCreationAllowed || creating) return;
 const request = requestScope.begin("assurance-task-create");
 setCreating(true);
 setError("");
 setMessage("");
 try {
 const payload = normalizeAssuranceCreateResponse(
 await api.createTask(projectId, {
 mode,
 frozen_identity: Object.fromEntries(FROZEN_IDENTITY_FIELDS.map((field) => [field, String(frozenIdentity[field]).trim()])),
 idempotency_key: requestKey(`assurance-${mode}`),
 owner: "医学经理",
 }, { signal: request.signal }),
 { projectId, mode },
 );
 if (!requestScope.isCurrent(request)) return;
 setMessage(payload.replayed ? "已复用同一幂等请求的保障任务。" : "保障任务已创建，等待后续证据步骤。 ");
 await loadTasks(mode);
 if (!requestScope.isCurrent(request)) return;
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return;
 setError(apiErrorMessage(nextError, "保障任务创建失败。"));
 } finally {
 if (requestScope.isCurrent(request)) setCreating(false);
 requestScope.finish(request);
 }
 };

 if (!open) return null;
 return (
 <section className="monitoring-assurance-panel" aria-label="锁库前与核查前保障工作区">
 <header className="monitoring-assurance-head">
 <div>
 <span className="monitoring-assurance-eyebrow"><ClipboardCheck size={14} /> P8 保障工作区</span>
 <h2>锁库前 / 核查前</h2>
 <p>冻结版本、全量重算、三级对账和医学决定集中在同一任务；当前页面首次加载只读取，不会创建或修改任务。</p>
 </div>
 <button type="button" className="icon-button" title="关闭保障工作区" onClick={onClose}><XCircle size={18} /></button>
 </header>
 <div className="monitoring-assurance-mode-row" role="tablist" aria-label="保障模式">
 {ASSURANCE_MODES.map((value) => (
 <button type="button" role="tab" aria-selected={mode === value} className={mode === value ? "active" : ""} key={value} onClick={() => { setMode(value); setSelectedTask(null); setProof(null); setProofProvenanceStatus(""); setRollup(null); setAudit(null); setAuditError(""); setAuditBlockedReason(""); }}>
 <span>{assuranceModeLabel(value)}</span>
 <small>{assuranceModeDescription(value)}</small>
 </button>
 ))}
 <button type="button" className="monitoring-assurance-refresh" onClick={() => loadTasks(mode)} disabled={loading} title="重新读取当前模式的保障任务"><RefreshCw size={14} />{loading ? "读取中" : "刷新"}</button>
 </div>
 <div className="monitoring-assurance-snapshot-grid">
 {snapshotFacts(currentSnapshot).map(([label, value]) => <EvidenceCard key={label} label={label} value={value} />)}
 <EvidenceCard label="冻结身份" value={identityReady ? "完整，可创建" : `缺少 ${missingIdentity.length} 项`} tone={identityReady ? "success" : "warning"} />
 <EvidenceCard label="认证身份" value={monitoringPrincipalStatusLabel(principalState.principal, { now: principalNow })} tone={principalReady ? "success" : "warning"} />
 </div>
 {!taskCreationAllowed && (
 <div className="monitoring-assurance-blocker" role="status">
 <ShieldAlert size={17} />
 <div><strong>创建任务暂时阻断</strong><span>只有完整冻结身份、服务端认证 principal 且 authority 明确允许写入时才可创建；页面不会猜测版本或绕过 B6/风险权威门禁。</span><small>{missingIdentity.length
 ? `缺失身份：${missingIdentity.join("、")}`
 : !authorityWritePermitted
 ? "当前 authority 尚未明确允许写入（assurance_write_permitted 未为 true）"
 : monitoringPrincipalBlocker(principalState.principal, principalState.error, { now: principalNow })}</small></div>
 </div>
 )}
 {taskCreationAllowed && <div className="monitoring-assurance-create-row"><span>当前页面已取得完整冻结身份且 authority 已允许写入，可显式创建该模式任务。</span><button type="button" className="primary-button" onClick={createTask} disabled={creating}>{creating ? "创建中" : `创建${assuranceModeLabel(mode)}任务`}</button></div>}
 {error && <p className="gate-error">{error}</p>}
 {message && <p className="monitoring-assurance-message"><CheckCircle2 size={15} />{message}</p>}
 <div className="monitoring-assurance-body">
 <div className="monitoring-assurance-task-list">
 <div className="monitoring-assurance-section-title"><strong>{assuranceModeLabel(mode)}任务</strong><span>{taskSummaries.length} 条</span></div>
 {loading && <div className="empty-state">正在读取保障任务。</div>}
 {!loading && !taskSummaries.length && <div className="empty-state">当前模式尚无保障任务；完成冻结身份后才可创建。</div>}
 {!loading && taskSummaries.map((task, index) => (
 <button type="button" disabled={task.identityState !== "ready"} className={`monitoring-assurance-task ${selectedTaskId === task.id && task.identityState === "ready" ? "selected" : ""}`} key={assuranceTaskDisplayKey(task, index)} onClick={() => task.identityState === "ready" && setSelectedTaskId(task.id)}>
 <span><strong>{task.id}</strong><small>{task.owner || "未指定负责人"}</small></span>
 <span className={`monitoring-assurance-status ${task.identityState === "ready" ? assuranceStatusTone(task.status) : "danger"}`} title={task.identityIssue || undefined}>{task.identityState === "ready" ? assuranceStatusLabel(task.status) : "身份重复，仅可读"}</span>
 </button>
 ))}
 </div>
 <div className="monitoring-assurance-detail">
 {!activeTask && <div className="empty-state">选择一个任务查看冻结身份和证据状态。</div>}
 {activeTask && (
 <>
 <div className="monitoring-assurance-section-title"><strong>{assuranceModeLabel(activeTask.mode)}</strong><span className={`monitoring-assurance-status ${assuranceStatusTone(activeTask.status)}`}>{assuranceStatusLabel(activeTask.status)}</span></div>
 {detailLoading && <div className="empty-state">正在读取任务详情。</div>}
 {!detailLoading && (
 <>
 <div className="monitoring-assurance-task-meta"><span>任务版本 <b>{activeTask.version || "-"}</b></span><span>医学复核 <b>{activeTask.medical_review_recorded ? "已记录" : "未记录"}</b></span><span>更新 <b>{activeTask.updated_at || "-"}</b></span></div>
 <AssuranceReadiness readiness={readiness} loading={readinessLoading} error={readinessError} blockedReason={readinessBlockedReason} input={readinessInput} />
 <div className="monitoring-assurance-evidence-banner"><Database size={16} /><div><strong>{visibleEvidence.label}</strong><span>{visibleEvidence.ready ? "完成门条件已具备，仍需后端任务状态允许下一步。" : (visibleEvidence.blockingReason || "证据尚未满足完成门；页面不提供绕过门禁的操作。")}</span></div></div>
 <AssuranceActionStatus availability={actionAvailability} task={activeTask} evidence={visibleEvidence} />
 <AssuranceProvenanceDisclosure provenanceStatus={visibleEvidence.provenanceStatus || proofProvenanceStatus} />
 {activeTask.mode === "pre_lock" && proof && <div className="monitoring-assurance-counts"><span>全量重算失败 <b>{assuranceRollupNumber(proof.failures)}</b></span><span>跳过 <b>{assuranceRollupNumber(proof.skips)}</b></span><span>开放高风险 <b>{assuranceRollupNumber(proof.open_high_risk_count)}</b></span><span>缺关闭证据 <b>{assuranceRollupNumber(proof.closed_risks_lacking_evidence_count)}</b></span></div>}
 {activeTask.mode === "pre_inspection" && rollup && <div className="monitoring-assurance-counts"><span>受试者层 <b>{assuranceRollupNumber(explicitArrayCount(rollup.subject_rollup))}</b></span><span>中心层 <b>{assuranceRollupNumber(explicitArrayCount(rollup.site_rollup))}</b></span><span>证据项 <b>{assuranceRollupNumber(explicitArrayCount(rollup.evidence_manifest))}</b></span><span>整改项 <b>{assuranceRollupNumber(explicitArrayCount(rollup.remediation_matrix))}</b></span></div>}
 {activeTask.mode === "pre_inspection" && rollup && <AssuranceRollup rollup={rollup} onClose={onClose} onRiskScopeChange={onRiskScopeChange} onSelectSubject={onSelectSubject} onOpenSubjectView={onOpenSubjectView} />}
 <AssuranceAuditChain audit={audit} loading={auditLoading} error={auditError} blockedReason={auditBlockedReason} onRetry={() => loadAudit(activeTask.task_id)} />
 </>
 )}
 </>
 )}
 </div>
 </div>
 </section>
 );
}

.monitoring-assurance-remediation {
 display: grid;
 gap: 8px;
 margin-top: 2px;
 padding: 9px 10px;
 border: 1px solid #e0e9f1;
 border-radius: 8px;
 background: #ffffff;
}

.monitoring-assurance-remediation.partial { border-color: #ead8a9; background: #fffdf7; }
.monitoring-assurance-remediation.malformed { border-color: #ecc6b5; background: #fff8f3; }
.monitoring-assurance-remediation.empty { color: #738596; font-size: 11px; }
.monitoring-assurance-remediation header { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.monitoring-assurance-remediation header > div:first-child { display: grid; gap: 2px; min-width: 0; }
.monitoring-assurance-remediation header strong { display: inline-flex; align-items: center; gap: 5px; color: #315568; font-size: 12px; }
.monitoring-assurance-remediation header span { color: #718391; font-size: 10px; line-height: 1.35; }
.monitoring-assurance-remediation-counts { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 4px; }
.monitoring-assurance-remediation-counts em { padding: 3px 6px; border-radius: 999px; background: #eef3f6; color: #617986; font-size: 9px; font-style: normal; white-space: nowrap; }
.monitoring-assurance-remediation-counts em.open { background: #fff4d7; color: #8a650e; }
.monitoring-assurance-remediation-counts em.missing { background: #fff0ec; color: #a13e2d; }
.monitoring-assurance-remediation-table { overflow: hidden; border: 1px solid #e4ebef; border-radius: 6px; }
.monitoring-assurance-remediation-row { min-height: 38px; display: grid; grid-template-columns: 1.05fr 1fr .8fr 1.35fr 26px; align-items: center; gap: 7px; padding: 5px 7px; border-bottom: 1px solid #edf2f5; color: #536b78; font-size: 10px; }
.monitoring-assurance-remediation-row:last-child { border-bottom: 0; }
.monitoring-assurance-remediation-row.header { min-height: 30px; background: #f6f9fb; color: #768895; font-size: 9px; font-weight: 700; }
.monitoring-assurance-remediation-row > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-assurance-remediation-row > span:first-child { display: grid; gap: 2px; }
.monitoring-assurance-remediation-row > span:first-child strong { font-size: 10px; }
.monitoring-assurance-remediation-row > span:first-child strong.severity-critical, .monitoring-assurance-remediation-row > span:first-child strong.severity-high { color: #a13e2d; }
.monitoring-assurance-remediation-row > span:first-child strong.severity-medium { color: #8a650e; }
.monitoring-assurance-remediation-row > span:first-child small { color: #778996; }
.monitoring-assurance-remediation-row code { min-width: 0; overflow: hidden; color: #748793; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-assurance-remediation-row .evidence-present { color: #2f7049; }
.monitoring-assurance-remediation-row .evidence-missing { color: #a13e2d; font-weight: 700; }
.monitoring-assurance-remediation-row button { display: inline-flex; align-items: center; justify-content: center; min-width: 24px; min-height: 23px; padding: 2px; border: 1px solid #d4e2eb; border-radius: 5px; background: #fff; color: #2c668e; cursor: pointer; }
.monitoring-assurance-remediation-row button:disabled { cursor: not-allowed; opacity: .45; }
.monitoring-assurance-remediation-more, .monitoring-assurance-remediation-warning { color: #8494a0; font-size: 9px; line-height: 1.4; }
.monitoring-assurance-remediation-warning { display: flex; align-items: flex-start; gap: 5px; margin: 0; color: #8e5337; }
.monitoring-assurance-remediation p { margin: 0; line-height: 1.45; }

@media (max-width: 720px) {
 .monitoring-assurance-remediation header { display: grid; }
 .monitoring-assurance-remediation-counts { justify-content: flex-start; }
 .monitoring-assurance-remediation-row { grid-template-columns: 1fr 1fr .75fr 1fr 24px; }
}


import { AlertTriangle, ArrowUpRight, ClipboardList } from "lucide-react";

import {
 assuranceRemediationDisplayKey,
 assuranceRemediationSeverityLabel,
 assuranceRemediationStatusLabel,
 normalizeMedicalMonitoringAssuranceRemediation,
} from "./medicalMonitoringAssuranceRemediation.mjs";
import "./MedicalMonitoringAssuranceRemediation.css";

function display(value) {
 return value || "待核对";
}

function evidenceLabel(value) {
 if (value === true) return "已提供";
 if (value === false) return "缺失";
 return "待核对";
}

export default function MedicalMonitoringAssuranceRemediation({ matrix, onFocusRow }) {
 const view = normalizeMedicalMonitoringAssuranceRemediation(matrix);
 if (view.status === "empty") {
 return (
 <section className="monitoring-assurance-remediation empty" aria-label="整改清单">
 <div className="monitoring-assurance-mini-title"><ClipboardList size={14} /> 现场自查优先项</div>
 <p>当前任务未返回整改矩阵；不能据此判定没有待核对风险。</p>
 </section>
 );
 }
 if (view.status === "malformed") {
 return (
 <section className="monitoring-assurance-remediation malformed" aria-label="整改清单">
 <div className="monitoring-assurance-mini-title"><AlertTriangle size={14} /> 整改矩阵形状异常</div>
 <p role="alert">暂不展示整改项；请回到任务证据核对原始矩阵。</p>
 </section>
 );
 }

 const rows = view.rows.slice(0, 8);
 return (
 <section className={`monitoring-assurance-remediation ${view.status}`} aria-label="现场自查整改清单">
 <header>
 <div>
 <strong><ClipboardList size={14} /> 现场自查优先项</strong>
 <span>按开放状态、显式严重度和关闭证据缺失排序；不代表未显示项已完成。</span>
 </div>
 <div className="monitoring-assurance-remediation-counts">
 <em>矩阵 {view.totalCount ?? "待核对"}</em>
 <em className="open">开放 {view.openCount}</em>
 <em className="missing">缺关闭证据 {view.missingClosureEvidenceCount}</em>
 </div>
 </header>
 <div className="monitoring-assurance-remediation-table" role="table" aria-label="优先整改项">
 <div className="monitoring-assurance-remediation-row header" role="row">
 <span>风险级别 / 状态</span><span>个例 / 中心</span><span>关闭证据</span><span>实例</span><span />
 </div>
 {rows.map((row, index) => {
 const identityAmbiguous = row.identityState !== "ready";
 return (
 <div className="monitoring-assurance-remediation-row" role="row" key={assuranceRemediationDisplayKey(row, index)}>
 <span><strong className={`severity-${row.severity || "unknown"}`}>{assuranceRemediationSeverityLabel(row.severity)}</strong><small>{assuranceRemediationStatusLabel(row.status)}</small></span>
 <span>{display(row.subjectId)} / {display(row.siteId)}</span>
 <span className={row.closureEvidencePresent === true ? "evidence-present" : "evidence-missing"}>{evidenceLabel(row.closureEvidencePresent)}</span>
 <code title={row.identityIssue || row.riskInstanceId}>{display(row.riskInstanceId)}{identityAmbiguous ? " · 身份待核对" : ""}</code>
 <button type="button" title={identityAmbiguous ? "身份重复，仅可读" : "聚焦该整改项的个例或中心"} onClick={() => !identityAmbiguous && onFocusRow?.(row)} disabled={identityAmbiguous || (!row.subjectId && !row.siteId)}><ArrowUpRight size={13} /></button>
 </div>
 );
 })}
 </div>
 {view.rows.length > rows.length && <small className="monitoring-assurance-remediation-more">仅显示前 {rows.length} 项；其余 {view.rows.length - rows.length} 项仍在当前矩阵中。</small>}
 {view.issues.length > 0 && <p className="monitoring-assurance-remediation-warning" role="alert"><AlertTriangle size={13} />部分矩阵字段待核对；异常项未用于排序或补值。</p>}
 </section>
 );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
 AlertTriangle,
 BookOpenCheck,
 CheckCircle2,
 Database,
 RefreshCw,
 Upload,
 X,
} from "lucide-react";

import {
 MedicalMonitoringApiError,
 createMedicalMonitoringApi,
} from "./medicalMonitoringApi.mjs";
import MedicalMonitoringDailyRunPanel from "./MedicalMonitoringDailyRunPanel.jsx";
import MedicalMonitoringFieldMappingPanel from "./MedicalMonitoringFieldMappingPanel.jsx";
import MedicalMonitoringProtocolPreparationPanel from "./MedicalMonitoringProtocolPreparationPanel.jsx";
import MedicalMonitoringRuleReleasePanel from "./MedicalMonitoringRuleReleasePanel.jsx";
import {
 createMedicalMonitoringProjectRequestScope,
} from "./medicalMonitoringProjectRequestScope.mjs";
import {
 normalizeBatchDetail,
 normalizeBatchIntakeResult,
 normalizeBatchList,
 normalizeBatchMutationResult,
 normalizeClassificationConfirmationDetail,
 normalizeContentConfirmationDetail,
} from "./medicalMonitoringBatchView.mjs";
import { monitoringFieldMappingCopy } from "./medicalMonitoringModels.mjs";

const STATE_LABELS = {
 draft: "已解析",
 parsed: "待确认完整性",
 validated: "校验完成",
 confirmed: "完整性已确认",
 frozen: "不可变候选批次",
};

const SOURCE_CLASS_LABELS = {
 raw_full_snapshot: "原始全量快照",
 raw_full_snapshot_candidate: "原始全量快照（待确认）",
 verified_derived_full_snapshot: "已验证派生全量快照",
 comparison_workbook: "比较文件（不可作基线）",
 mixed_monitoring_workbook: "混合监查文件（不可作基线）",
 raw_snapshot_with_format_defect: "格式异常快照（不可作基线）",
 restored_transitional: "还原过渡文件（不可作基线）",
 processed_full_snapshot: "处理后全量快照（需B级确认）",
 unknown_blocked: "无法识别",
};

function sourceClassLabel(value) {
 return SOURCE_CLASS_LABELS[value] || value || "-";
}

function requestKey(prefix) {
 const random = globalThis.crypto?.randomUUID?.()
 || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
 return `${prefix}-${random}`;
}

function detailFromError(error) {
 if (!(error instanceof MedicalMonitoringApiError)) return null;
 const detail = error.detail?.detail;
 return detail && typeof detail === "object" ? detail : null;
}

function stateTone(state) {
 if (state === "frozen") return "success";
 if (state === "draft" || state === "parsed") return "warning";
 return "info";
}

function BatchState({ state }) {
 return (
 <span className={`monitoring-batch-state ${stateTone(state)}`}>
 {STATE_LABELS[state] || state}
 </span>
 );
}

export default function MedicalMonitoringBatchPanel(props) {
 return (
 <MedicalMonitoringBatchPanelForProject
 key={props.projectId}
 {...props}
 />
 );
}

function MedicalMonitoringBatchPanelForProject({
 projectId,
 onClose,
 aiStatus = {},
}) {
 const api = useMemo(() => createMedicalMonitoringApi(), []);
 const requestScope = useMemo(
 () => createMedicalMonitoringProjectRequestScope(projectId),
 [projectId],
 );
 const fileInputRef = useRef(null);
 const [batches, setBatches] = useState([]);
 const [activeBatch, setActiveBatch] = useState(null);
 const [file, setFile] = useState(null);
 const [intakeKey, setIntakeKey] = useState("");
 const [overrideReason, setOverrideReason] = useState("");
 const [pendingConfirmation, setPendingConfirmation] = useState(null);
 const [acknowledgedCodes, setAcknowledgedCodes] = useState([]);
 const [fullSnapshotConfirmed, setFullSnapshotConfirmed] = useState(false);
 const [fieldMappingOpen, setFieldMappingOpen] = useState(false);
 const [protocolPreparationOpen, setProtocolPreparationOpen] = useState(false);
 const [ruleReleaseOpen, setRuleReleaseOpen] = useState(false);
 const [busy, setBusy] = useState(false);
 const [message, setMessage] = useState("");
 const [error, setError] = useState("");
 const mappingCopy = useMemo(
 () => monitoringFieldMappingCopy(aiStatus),
 [aiStatus],
 );

 const clearBatchState = useCallback(() => {
 setBatches([]);
 setActiveBatch(null);
 setPendingConfirmation(null);
 setAcknowledgedCodes([]);
 setFullSnapshotConfirmed(false);
 }, []);

 const loadBatches = useCallback(async (focusBatchId = "") => {
 const request = requestScope.begin("batch-view");
 try {
 const payload = normalizeBatchList(await api.listBatches(
 projectId,
 { signal: request.signal },
 ));
 if (!requestScope.isCurrent(request)) return null;
 const nextBatches = payload.batches;
 setBatches(nextBatches);
 const focusedBatches = focusBatchId
 ? nextBatches.filter((batch) => batch.batch_id === focusBatchId && batch.displayIdentityState === "ready")
 : [];
 if (focusBatchId && focusedBatches.length !== 1) {
 setActiveBatch(null);
 return null;
 }
 const batchId = focusedBatches[0]?.batch_id
 || nextBatches.find((batch) => batch.displayIdentityState === "ready")?.batch_id;
 if (!batchId) {
 setActiveBatch(null);
 return null;
 }
 const nextBatch = normalizeBatchDetail(await api.getBatch(
 projectId,
 batchId,
 { signal: request.signal },
 ));
 if (!requestScope.isCurrent(request)) return null;
 setActiveBatch(nextBatch);
 setFullSnapshotConfirmed(false);
 return nextBatch;
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return null;
 throw nextError;
 } finally {
 requestScope.finish(request);
 }
 }, [api, projectId, requestScope]);

 const refreshBatches = useCallback(async (focusBatchId = "") => {
 setBusy(true);
 setError("");
 try {
 return await loadBatches(focusBatchId);
 } catch (nextError) {
 if (nextError?.name !== "AbortError") {
 clearBatchState();
 }
 setError(nextError.message || "批次读取失败");
 return null;
 } finally {
 setBusy(false);
 }
 }, [clearBatchState, loadBatches]);

 useEffect(() => {
 requestScope.activate();
 return () => requestScope.dispose();
 }, [requestScope]);

 useEffect(() => {
 let mounted = true;
 setBusy(true);
 setError("");
 loadBatches()
 .catch((nextError) => {
 if (mounted) {
 if (nextError?.name !== "AbortError") {
 clearBatchState();
 }
 setError(nextError.message || "批次读取失败");
 }
 })
 .finally(() => {
 if (mounted) setBusy(false);
 });
 return () => {
 mounted = false;
 requestScope.cancel("batch-view");
 };
 }, [clearBatchState, loadBatches, requestScope]);

 const retryIntake = async (classificationReason = overrideReason) => {
 if (!file) return;
 const request = requestScope.begin("batch-intake");
 const currentKey = intakeKey || requestKey("monitoring-intake");
 if (!intakeKey) setIntakeKey(currentKey);
 setBusy(true);
 setError("");
 setMessage("");
 try {
 const result = normalizeBatchIntakeResult(await api.intakeBatchFile(projectId, file, {
 signal: request.signal,
 idempotencyKey: currentKey,
 classificationOverrideReason: classificationReason,
 }));
 if (!requestScope.isCurrent(request)) return;
 const batchId = result.batch.batch.batch_id;
 setPendingConfirmation(null);
 setAcknowledgedCodes([]);
 setMessage("批次已解析并保存，尚未运行医学风险规则。");
 await loadBatches(batchId);
 if (!requestScope.isCurrent(request)) return;
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return;
 const detail = detailFromError(nextError);
 if (detail?.code === "source_content_confirmation_required") {
 try {
 const contentDetail = normalizeContentConfirmationDetail(detail);
 const unresolved = contentDetail.validation.checks
 .filter((check) => ["warning", "mismatch"].includes(check.outcome))
 .map((check) => check.check_code);
 setAcknowledgedCodes([]);
 setPendingConfirmation({
 kind: "content",
 sourceEntryId: contentDetail.source_entry_id,
 validation: contentDetail.validation,
 unresolved,
 });
 } catch (shapeError) {
 clearBatchState();
 setError(shapeError.message || "来源内容校验回执字段异常");
 }
 return;
 }
 if (detail?.code === "listing_classification_confirmation_required") {
 try {
 const classificationDetail = normalizeClassificationConfirmationDetail(detail);
 setPendingConfirmation({
 kind: "classification",
 classification: classificationDetail.classification,
 sourceEntryId: classificationDetail.source_entry_id,
 });
 } catch (shapeError) {
 clearBatchState();
 setError(shapeError.message || "来源分类回执字段异常");
 }
 return;
 }
 if (nextError?.name !== "AbortError") {
 clearBatchState();
 }
 setError(nextError.message || "批次导入失败");
 } finally {
 if (requestScope.isCurrent(request)) setBusy(false);
 requestScope.finish(request);
 }
 };

 const confirmContent = async () => {
 const pending = pendingConfirmation;
 if (pending?.kind !== "content") return;
 const request = requestScope.begin("content-confirmation");
 setBusy(true);
 setError("");
 try {
 await api.confirmSourceContent(projectId, pending.sourceEntryId, {
 reason: overrideReason.trim(),
 acknowledged_check_codes: acknowledgedCodes,
 expected_revision: pending.validation.revision,
 idempotency_key: requestKey("monitoring-content-confirmation"),
 }, { signal: request.signal });
 if (!requestScope.isCurrent(request)) return;
 setPendingConfirmation(null);
 await retryIntake();
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return;
 setError(nextError.message || "内容确认失败");
 setBusy(false);
 } finally {
 requestScope.finish(request);
 }
 };

 const confirmClassification = async () => {
 setPendingConfirmation(null);
 await retryIntake(overrideReason.trim());
 };

 const transitionToParsed = async () => {
 if (!activeBatch) return;
 const request = requestScope.begin("batch-transition");
 setBusy(true);
 setError("");
 try {
 const result = normalizeBatchMutationResult(await api.transitionBatch(projectId, activeBatch.batch_id, {
 target_state: "parsed",
 expected_version: activeBatch.version,
 idempotency_key: requestKey("monitoring-parsed"),
 }, { signal: request.signal }));
 if (!requestScope.isCurrent(request)) return;
 await loadBatches(result.batch.batch_id);
 if (!requestScope.isCurrent(request)) return;
 setMessage("解析结果已确认。请核对数据域及本次是否为完整全量导出。");
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return;
 if (nextError?.name !== "AbortError") {
 clearBatchState();
 }
 setError(nextError.message || "解析确认失败");
 } finally {
 if (requestScope.isCurrent(request)) setBusy(false);
 requestScope.finish(request);
 }
 };

 const freezeBatch = async () => {
 if (!activeBatch || !fullSnapshotConfirmed) return;
 const request = requestScope.begin("batch-freeze");
 const activeSource = activeBatch.sources?.[0];
 const isProcessedSource = activeSource?.source_class === "processed_full_snapshot";
 setBusy(true);
 setError("");
 try {
 const frozen = normalizeBatchMutationResult(await api.confirmBatchFullSnapshot(
 projectId,
 activeBatch.batch_id,
 {
 full_snapshot_proof: {
 confirmed: true,
 basis: isProcessedSource
 ? `医学经理确认 ${activeSource?.file_name || "该文件"} 为完整项目级处理后快照，可用于增量比较；不作为原始EDC权威证据。`
 : `医学经理确认 ${activeSource?.file_name || "该文件"} 为本次完整全量EDC导出。`,
 confirmed_by: "medical_manager",
 ...(isProcessedSource ? {
 source_authority_grade: "B",
 processed_source_acknowledged: true,
 } : {}),
 },
 expected_version: activeBatch.version,
 idempotency_key: requestKey("monitoring-full-snapshot"),
 },
 { signal: request.signal },
 ));
 if (!requestScope.isCurrent(request)) return;
 await loadBatches(frozen.batch.batch_id);
 if (!requestScope.isCurrent(request)) return;
 setMessage("批次已冻结为不可变候选；完成差异分析、风险复核和医学确认后才会成为下一批比较基线。");
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return;
 const detail = detailFromError(nextError);
 if ([
 "monitoring_mapping_required",
 "monitoring_mapping_difference_review_required",
 ].includes(detail?.code)) {
 setFieldMappingOpen(true);
 setMessage(
 detail.code === "monitoring_mapping_required"
 ? "请先完成字段识别与校对，再确认本批次。"
 : "检测到字段结构变化，请先校对差异字段。",
 );
 } else {
 if (nextError?.name !== "AbortError") {
 clearBatchState();
 }
 setError(nextError.message || "批次确认失败");
 }
 } finally {
 if (requestScope.isCurrent(request)) setBusy(false);
 requestScope.finish(request);
 }
 };

 const selectBatch = async (batchId) => {
 const matchingBatches = batches.filter((batch) => batch.batch_id === batchId);
 if (matchingBatches.length !== 1 || matchingBatches[0].displayIdentityState !== "ready") {
 setError("该批次身份重复或待核对，暂不能打开。");
 return;
 }
 const request = requestScope.begin("batch-view");
 setBusy(true);
 setError("");
 try {
 const nextBatch = normalizeBatchDetail(await api.getBatch(
 projectId,
 batchId,
 { signal: request.signal },
 ));
 if (!requestScope.isCurrent(request)) return;
 setActiveBatch(nextBatch);
 setFullSnapshotConfirmed(false);
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return;
 if (nextError?.name !== "AbortError") {
 clearBatchState();
 }
 setError(nextError.message || "批次读取失败");
 } finally {
 if (requestScope.isCurrent(request)) setBusy(false);
 requestScope.finish(request);
 }
 };

 const source = activeBatch?.sources?.[0];
 const processedBaselineEligible = source?.source_class === "processed_full_snapshot"
 && Boolean(source?.medical_override_reason?.trim());
 const baselineEligible = source?.source_class === "raw_full_snapshot"
 || source?.source_class === "raw_full_snapshot_candidate"
 || source?.source_class === "verified_derived_full_snapshot"
 || processedBaselineEligible;
 const unresolvedCount = pendingConfirmation?.unresolved?.length || 0;
 const allContentChecksAcknowledged = unresolvedCount > 0
 && acknowledgedCodes.length === unresolvedCount;

 return (
 <section className="panel monitoring-batch-panel" aria-label="医学监查批次管理">
 <div className="monitoring-batch-panel-head">
 <div>
 <span>数据批次</span>
 <strong>导入定期 EDC data listing</strong>
 </div>
 <div className="button-row">
 <button
 className="monitoring-protocol-prep-entry"
 type="button"
 onClick={() => setProtocolPreparationOpen(true)}
 >
 <BookOpenCheck size={15} />
 准备方案规则
 </button>
 <button
 className="monitoring-protocol-prep-entry"
 type="button"
 onClick={() => setRuleReleaseOpen(true)}
 >
 <CheckCircle2 size={15} />
 规则发布
 </button>
 <button
 className="icon-button"
 type="button"
 title="刷新批次"
 onClick={() => refreshBatches(activeBatch?.batch_id)}
 disabled={busy}
 >
 <RefreshCw size={15} />
 </button>
 <button className="icon-button" type="button" title="关闭" onClick={onClose}>
 <X size={16} />
 </button>
 </div>
 </div>

 <div className="monitoring-batch-workspace">
 <div className="monitoring-batch-upload">
 <input
 ref={fileInputRef}
 type="file"
 accept=".csv,.xls,.xlsx,.xlsm"
 onChange={(event) => {
 const nextFile = event.target.files?.[0] || null;
 setFile(nextFile);
 setIntakeKey(nextFile ? requestKey("monitoring-intake") : "");
 setPendingConfirmation(null);
 setOverrideReason("");
 setAcknowledgedCodes([]);
 setError("");
 setMessage("");
 }}
 />
 <button
 type="button"
 onClick={() => {
 if (!fileInputRef.current) return;
 // Selecting the same file again must still create a fresh intake request.
 fileInputRef.current.value = "";
 fileInputRef.current.click();
 }}
 >
 <Upload size={16} />
 {file ? "更换文件" : "选择 listing"}
 </button>
 <div>
 <strong>{file?.name || "尚未选择文件"}</strong>
 <span>支持 CSV、XLS、XLSX、XLSM；导入后保留原文件。</span>
 </div>
 <button
 className="primary-button"
 type="button"
 disabled={!file || busy}
 onClick={() => retryIntake()}
 >
 {busy ? "处理中" : "导入并解析"}
 </button>
 </div>

 <div className="monitoring-batch-list" aria-label="历史批次">
 {batches.length ? batches.map((batch) => {
 const ambiguous = batch.displayIdentityState !== "ready";
 return (
 <button
 type="button"
 className={!ambiguous && activeBatch?.batch_id === batch.batch_id ? "active" : ""}
 key={batch.displayKey}
 disabled={ambiguous}
 aria-disabled={ambiguous ? "true" : undefined}
 title={ambiguous ? batch.displayIdentityIssue : undefined}
 onClick={() => {
 if (!ambiguous) selectBatch(batch.batch_id);
 }}
 >
 <Database size={15} />
 <span>{new Date(batch.created_at).toLocaleString("zh-CN")}</span>
 <BatchState state={batch.state} />
 {ambiguous && <span className="monitoring-batch-state warning">身份待核对</span>}
 </button>
 );
 }) : <span className="monitoring-batch-empty">当前项目尚无导入批次</span>}
 </div>

 {activeBatch && (
 <div className="monitoring-batch-summary">
 <div>
 <span>文件</span>
 <strong>{source?.file_name || "-"}</strong>
 </div>
 <div>
 <span>记录</span>
 <strong>{activeBatch.row_count?.toLocaleString?.("zh-CN") || activeBatch.row_count || "-"}</strong>
 </div>
 <div>
 <span>数据域</span>
 <strong>{activeBatch.expected_domains?.length || 0}</strong>
 </div>
 <div>
 <span>来源类型</span>
 <strong title={source?.source_class || ""}>
 {source?.source_class === "raw_full_snapshot_candidate" && activeBatch.state === "frozen"
 ? "原始全量快照（已确认）"
 : sourceClassLabel(source?.source_class)}
 </strong>
 </div>
 <BatchState state={activeBatch.state} />
 </div>
 )}

 {activeBatch?.expected_domains?.length > 0 && (
 <div className="monitoring-domain-strip">
 {activeBatch.expected_domains.map((domain) => (
 <span key={domain}>{domain}</span>
 ))}
 </div>
 )}

 {activeBatch?.state === "draft" && (
 <div className="monitoring-batch-action">
 <div>
 <strong>解析已完成</strong>
 <span>确认记录数和数据域后进入完整性核对；此操作不会运行风险规则。</span>
 </div>
 <button className="primary-button" type="button" disabled={busy} onClick={transitionToParsed}>
 确认解析结果
 </button>
 </div>
 )}

 {activeBatch?.state === "parsed" && (
 <div className="monitoring-batch-action">
 <label>
 <input
 type="checkbox"
 checked={fullSnapshotConfirmed}
 disabled={!baselineEligible}
 onChange={(event) => setFullSnapshotConfirmed(event.target.checked)}
 />
 <span>
 <strong>
 {source?.source_class === "processed_full_snapshot"
 ? "确认这是完整项目级 EDC 快照（B级处理后来源）"
 : "确认这是本次完整全量 EDC 导出"}
 </strong>
 <small>
 {source?.source_class === "processed_full_snapshot"
 ? "可用于增量比较；不改变处理后来源身份，也不能作为原始 EDC 权威证据。"
 : "缺失记录将只有在前后两批均完成此确认后才可解释为删除。"}
 </small>
 </span>
 </label>
 <button
 className="primary-button"
 type="button"
 disabled={!fullSnapshotConfirmed || !baselineEligible || busy}
 onClick={freezeBatch}
 >
 冻结候选批次
 </button>
 </div>
 )}

 {activeBatch?.state === "parsed" && source?.source_class === "processed_full_snapshot"
 && !processedBaselineEligible && (
 <p className="monitoring-batch-inline-note">
 处理后快照只有在文件基本信息已由医学经理确认并记录理由后，才可按 B 级来源用于
 增量比较；其来源身份不会被改写。
 </p>
 )}

 {activeBatch?.state === "parsed" && !baselineEligible
 && source?.source_class !== "processed_full_snapshot" && (
 <p className="monitoring-batch-inline-note">
 当前来源类型不能作为全量比较基线；文件仍可保留用于人工复核，但不会被改写为原始快照。
 </p>
 )}

 {["parsed", "frozen"].includes(activeBatch?.state) && !fieldMappingOpen && (
 <div className="monitoring-batch-action monitoring-batch-mapping-entry">
 <div>
 <strong>{mappingCopy.entryTitle}</strong>
 <span>{mappingCopy.entryDescription}</span>
 </div>
 <button
 className="primary-button"
 type="button"
 title={mappingCopy.entryDescription}
 onClick={() => setFieldMappingOpen(true)}
 >
 {mappingCopy.entryAction}
 </button>
 </div>
 )}

 {["parsed", "frozen"].includes(activeBatch?.state) && fieldMappingOpen && (
 <MedicalMonitoringFieldMappingPanel
 projectId={projectId}
 batch={activeBatch}
 aiStatus={aiStatus}
 onClose={() => setFieldMappingOpen(false)}
 onConfirmed={() => {
 setFieldMappingOpen(false);
 setMessage("项目字段映射已启用，可继续确认本批次。");
 refreshBatches(activeBatch.batch_id);
 }}
 />
 )}

 {activeBatch?.state === "frozen" && !fieldMappingOpen && (
 <MedicalMonitoringDailyRunPanel
 projectId={projectId}
 batch={activeBatch}
 api={api}
 onMappingRequired={() => setFieldMappingOpen(true)}
 onRulePackRequired={() => setRuleReleaseOpen(true)}
 onBaselineConfirmed={() => {
 setMessage("本次医学监查已确认，该批次已成为下一次比较基线。");
 refreshBatches(activeBatch.batch_id);
 }}
 />
 )}

 {pendingConfirmation?.kind === "content" && (
 <div className="monitoring-batch-confirmation">
 <div>
 <AlertTriangle size={17} />
 <strong>请核对文件基本信息</strong>
 </div>
 <p>{pendingConfirmation.validation?.summary}</p>
 {pendingConfirmation.validation.checks
 .filter((check) => ["warning", "mismatch"].includes(check.outcome))
 .map((check) => (
 <label key={check.check_code}>
 <input
 type="checkbox"
 checked={acknowledgedCodes.includes(check.check_code)}
 onChange={(event) => setAcknowledgedCodes((current) => (
 event.target.checked
 ? [...current, check.check_code]
 : current.filter((code) => code !== check.check_code)
 ))}
 />
 <span>
 <strong>{check.label}</strong>
 <small>{check.observed_value || "未识别到可核对信息"}</small>
 </span>
 </label>
 ))}
 <textarea
 value={overrideReason}
 onChange={(event) => setOverrideReason(event.target.value)}
 placeholder="说明为何确认该文件属于当前项目和本次数据批次。"
 />
 <button
 className="primary-button"
 type="button"
 disabled={!allContentChecksAcknowledged || overrideReason.trim().length < 10 || busy}
 onClick={confirmContent}
 >
 确认并继续
 </button>
 </div>
 )}

 {pendingConfirmation?.kind === "classification" && (
 <div className="monitoring-batch-confirmation">
 <div>
 <AlertTriangle size={17} />
 <strong>确认来源类型</strong>
 </div>
 <p>
 系统识别为{sourceClassLabel(pendingConfirmation.classification?.source_class)}。
 {pendingConfirmation.classification.content_warnings.join(" ")}
 </p>
 <textarea
 value={overrideReason}
 onChange={(event) => setOverrideReason(event.target.value)}
 placeholder="说明继续导入该文件的医学用途；确认不会改变来源分类。"
 />
 <button
 className="primary-button"
 type="button"
 disabled={overrideReason.trim().length < 10 || busy}
 onClick={confirmClassification}
 >
 保留原分类并继续
 </button>
 </div>
 )}

 {message && (
 <p className="monitoring-batch-message">
 <CheckCircle2 size={15} />
 {message}
 </p>
 )}
 {error && <p className="monitoring-batch-error">{error}</p>}
 </div>
 {protocolPreparationOpen && (
 <MedicalMonitoringProtocolPreparationPanel
 projectId={projectId}
 aiStatus={aiStatus}
 onClose={() => setProtocolPreparationOpen(false)}
 onOpenRuleRelease={() => {
 setProtocolPreparationOpen(false);
 setRuleReleaseOpen(true);
 }}
 />
 )}
 {ruleReleaseOpen && (
 <MedicalMonitoringRuleReleasePanel
 projectId={projectId}
 onClose={() => setRuleReleaseOpen(false)}
 onOpenProtocolPreparation={() => {
 setRuleReleaseOpen(false);
 setProtocolPreparationOpen(true);
 }}
 onOpenMapping={() => {
 setRuleReleaseOpen(false);
 setFieldMappingOpen(true);
 }}
 onPublished={() => refreshBatches(activeBatch?.batch_id)}
 />
 )}
 </section>
 );
}

.monitoring-daily-ai-candidates {
 display: grid;
 gap: 7px;
 padding: 9px 10px;
 border: 1px solid #d9e4ea;
 background: #fbfdfe;
}

.monitoring-daily-ai-candidates.partial, .monitoring-daily-ai-candidates.unavailable { border-color: #ead8a9; background: #fffdf7; }
.monitoring-daily-ai-candidates.malformed { border-color: #ecc6b5; background: #fff8f3; }
.monitoring-daily-ai-candidates header { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.monitoring-daily-ai-candidates-head > div { display: grid; gap: 2px; min-width: 0; }
.monitoring-daily-ai-candidates-head strong, .monitoring-daily-ai-candidates header > strong { display: inline-flex; align-items: center; gap: 5px; color: #315568; font-size: 12px; }
.monitoring-daily-ai-candidates-head span { color: #718391; font-size: 10px; line-height: 1.35; }
.monitoring-daily-ai-candidates-count { flex: 0 0 auto; padding: 3px 6px; border-radius: 999px; background: #edf5f8; color: #55788a; font-size: 10px; }
.monitoring-daily-ai-candidate-row { display: grid; gap: 5px; padding: 8px; border: 1px solid #e3eaee; background: #fff; }
.monitoring-daily-ai-candidate-row-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
.monitoring-daily-ai-candidate-row-head > div { display: grid; gap: 2px; min-width: 0; }
.monitoring-daily-ai-candidate-row-head strong { overflow: hidden; color: #315568; font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-daily-ai-candidate-row-head span { color: #738590; font-size: 9px; }
.monitoring-daily-ai-candidate-confidence { flex: 0 0 auto; max-width: 180px; overflow: hidden; padding: 3px 6px; border-radius: 999px; background: #eef3f6; color: #617986; font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-daily-ai-candidate-confidence.warning { background: #fff4d7; color: #8a650e; }
.monitoring-daily-ai-candidate-confidence.danger { background: #fff0ec; color: #a13e2d; }
.monitoring-daily-ai-candidate-row p { display: -webkit-box; overflow: hidden; margin: 0; color: #536b78; font-size: 10px; line-height: 1.4; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.monitoring-daily-ai-candidate-claims { display: grid; gap: 3px; }
.monitoring-daily-ai-candidate-claims span { overflow: hidden; color: #536b78; font-size: 9px; line-height: 1.35; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-daily-ai-candidate-claims span::first-letter { color: #55788a; }
.monitoring-daily-ai-candidate-claims small { color: #8494a0; font-size: 9px; }
.monitoring-daily-ai-candidate-facts { display: grid; gap: 4px; padding: 6px 7px; border-left: 3px solid #8aaec5; background: #f7fbfc; color: #536b78; font-size: 9px; line-height: 1.4; }
.monitoring-daily-ai-candidate-facts > strong { color: #315568; font-size: 9px; }
.monitoring-daily-ai-candidate-facts blockquote { display: grid; gap: 2px; margin: 0; padding: 0; }
.monitoring-daily-ai-candidate-facts blockquote span { color: #405f6e; }
.monitoring-daily-ai-candidate-facts blockquote small, .monitoring-daily-ai-candidate-facts > small { color: #8494a0; font-size: 9px; }
.monitoring-daily-ai-candidate-meta { display: flex; flex-wrap: wrap; gap: 4px 12px; color: #748691; font-size: 9px; }
.monitoring-daily-ai-candidate-provenance { border-top: 1px solid #edf1f3; padding-top: 4px; color: #6d818c; font-size: 9px; }
.monitoring-daily-ai-candidate-provenance summary { cursor: pointer; color: #55788a; list-style-position: inside; }
.monitoring-daily-ai-candidate-provenance summary::marker { color: #8ea4ae; }
.monitoring-daily-ai-candidate-provenance-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 4px 10px; margin-top: 5px; }
.monitoring-daily-ai-candidate-provenance-grid span { min-width: 0; overflow-wrap: anywhere; }
.monitoring-daily-ai-candidate-provenance-grid code, .monitoring-daily-ai-candidate-provenance-sources code { color: #627f8d; font-size: 9px; }
.monitoring-daily-ai-candidate-provenance-grid strong { color: #8b5b2b; font-weight: 600; }
.monitoring-daily-ai-candidate-provenance-sources { display: grid; gap: 4px; margin-top: 5px; padding: 6px 7px; border: 1px solid #e8eef1; background: #fbfdfe; }
.monitoring-daily-ai-candidate-provenance-sources > div { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: 6px; min-width: 0; align-items: baseline; }
.monitoring-daily-ai-candidate-provenance-sources > div > span { min-width: 0; overflow: hidden; color: #536f7c; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-daily-ai-candidate-provenance-sources small, .monitoring-daily-ai-candidate-provenance-note { color: #8494a0; font-size: 9px; line-height: 1.4; }
.monitoring-daily-ai-candidate-provenance-note { display: block; margin-top: 5px; }
.monitoring-daily-ai-candidate-evidence { display: flex; flex-wrap: wrap; gap: 4px 7px; align-items: center; }
.monitoring-daily-ai-candidate-evidence code { max-width: 260px; overflow: hidden; color: #6c8491; font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-daily-ai-candidate-evidence span, .monitoring-daily-ai-candidate-evidence small, .monitoring-daily-ai-candidates-more, .monitoring-daily-ai-candidates-source { color: #8494a0; font-size: 9px; line-height: 1.4; }
.monitoring-daily-ai-candidates-empty, .monitoring-daily-ai-candidates-warning { display: flex; align-items: flex-start; gap: 5px; margin: 0; color: #8e5337; font-size: 10px; line-height: 1.4; }
.monitoring-daily-ai-candidates-empty { color: #6f818b; }
.monitoring-daily-ai-candidates-source { display: block; }

@media (max-width: 620px) {
 .monitoring-daily-ai-candidates-head { display: grid; }
 .monitoring-daily-ai-candidate-row-head { display: grid; }
 .monitoring-daily-ai-candidate-provenance-grid { grid-template-columns: 1fr; }
 .monitoring-daily-ai-candidate-provenance-sources > div { grid-template-columns: 1fr; gap: 2px; }
}

import { AlertTriangle, Bot, FileWarning } from "lucide-react";

import {
 medicalMonitoringAiCandidateConfidenceTone,
 medicalMonitoringAiCandidateClaimKey,
 medicalMonitoringAiCandidateDisplayKey,
 medicalMonitoringAiCandidateEvidenceKey,
 medicalMonitoringAiCandidateReviewStateLabel,
 medicalMonitoringAiCandidateStatusLabel,
 medicalMonitoringAiClaimKindLabel,
 normalizeMedicalMonitoringDailyAiCandidates,
} from "./medicalMonitoringDailyAiCandidates.mjs";
import "./MedicalMonitoringDailyAiCandidates.css";

function display(value) {
 return value || "待核对";
}

function shortHash(value) {
 if (typeof value !== "string" || !value.trim()) return "待核对";
 const clean = value.trim();
 return clean.length > 16 ? `${clean.slice(0, 12)}…` : clean;
}

function provenanceReady(candidate) {
 return Boolean(
 candidate.inputRevisionSha256
 && candidate.promptVersion
 && candidate.createdAt
 && candidate.evidence.length > 0
 && candidate.evidence.every((item) => (
 item.sourceEntryId
 && item.sourceContentSha256
 && item.inputRevisionSha256
 && item.locator
 )),
 );
}

function CandidateRow({ candidate }) {
 const confidence = candidate.confidenceSummary;
 const tone = medicalMonitoringAiCandidateConfidenceTone(confidence);
 const evidence = candidate.evidence.slice(0, 2);
 return (
 <article className="monitoring-daily-ai-candidate-row">
 <div className="monitoring-daily-ai-candidate-row-head">
 <div>
 <strong>{candidate.title}</strong>
 <span>个例 {display(candidate.subjectId)} · {display(candidate.candidateType)} · {medicalMonitoringAiCandidateStatusLabel(candidate.status)}</span>
 </div>
 <span className={`monitoring-daily-ai-candidate-confidence ${tone}`}>{display(confidence?.label)}</span>
 </div>
 <section className="monitoring-daily-ai-candidate-facts" aria-label="候选引用的来源事实">
 <strong>候选引用的来源事实</strong>
 {evidence.length > 0
 ? evidence.map((item, index) => (
 <blockquote key={`fact-${medicalMonitoringAiCandidateEvidenceKey(item, index)}`}>
 <span>{item.quote || "来源事实正文待核对"}</span>
 <small>证据 {display(item.evidenceId)}</small>
 </blockquote>
 ))
 : <span>来源事实正文待核对</span>}
 <small>引用只反映显式来源片段，不等于医学风险确认；来源定位在下方。</small>
 </section>
 <p>{display(candidate.text)}</p>
 {candidate.claims.length > 0 && (
 <div className="monitoring-daily-ai-candidate-claims" aria-label="候选声明">
 {candidate.claims.slice(0, 2).map((claim, index) => (
 <span
 key={medicalMonitoringAiCandidateClaimKey(claim, index)}
 title={claim.identityIssue ? `${claim.text} · ${claim.identityIssue}` : claim.text}
 >
 {medicalMonitoringAiClaimKindLabel(claim.kind)} · {claim.text}
 {claim.identityState !== "ready" && " · 身份待核对"}
 </span>
 ))}
 {candidate.claims.length > 2 && <small>其余 {candidate.claims.length - 2} 条声明仍绑定在候选中。</small>}
 </div>
 )}
 <div className="monitoring-daily-ai-candidate-meta">
 <span>声明 {candidate.claims.length} 条</span>
 <span>证据 {candidate.evidence.length} 条</span>
 <span>{medicalMonitoringAiCandidateReviewStateLabel(candidate)}</span>
 </div>
 <details className="monitoring-daily-ai-candidate-provenance">
 <summary>查看来源身份 {provenanceReady(candidate) ? "· 字段齐全" : "· 待核对"}</summary>
 <div className="monitoring-daily-ai-candidate-provenance-grid">
 <span>候选输入修订 <code title={candidate.inputRevisionSha256 || undefined}>{shortHash(candidate.inputRevisionSha256)}</code></span>
 <span>提示词版本 <code>{display(candidate.promptVersion)}</code></span>
 <span>生成时间 <code>{display(candidate.createdAt)}</code></span>
 <span>身份状态 <strong>{provenanceReady(candidate) ? "字段齐全，仍需回源核对" : "字段缺失或异常"}</strong></span>
 </div>
 <div className="monitoring-daily-ai-candidate-provenance-sources">
 {candidate.evidence.slice(0, 2).map((item, index) => (
 <div key={`provenance-${medicalMonitoringAiCandidateEvidenceKey(item, index)}`}>
 <span>{display(item.sourceEntryId)} · {display(item.locator)}</span>
 <code title={item.sourceContentSha256 || undefined}>源哈希 {shortHash(item.sourceContentSha256)}</code>
 <code title={item.inputRevisionSha256 || undefined}>输入 {shortHash(item.inputRevisionSha256)}</code>
 </div>
 ))}
 {!candidate.evidence.length && <span>来源身份待核对</span>}
 {candidate.evidence.length > 2 && <small>其余 {candidate.evidence.length - 2} 条来源身份仍绑定在候选中。</small>}
 </div>
 <small className="monitoring-daily-ai-candidate-provenance-note">来源身份只用于版本与回源核对，不是医学风险结论；哈希不代表原始数据内容。</small>
 </details>
 <div className="monitoring-daily-ai-candidate-evidence">
 {evidence.length > 0
 ? evidence.map((item, index) => <code key={medicalMonitoringAiCandidateEvidenceKey(item, index)}>{item.sourceEntryId} · {item.locator}</code>)
 : <span>来源证据待核对</span>}
 {candidate.evidence.length > evidence.length && <small>其余 {candidate.evidence.length - evidence.length} 条证据仍绑定在候选中。</small>}
 </div>
 </article>
 );
}

export default function MedicalMonitoringDailyAiCandidates({ candidates, candidateCount }) {
 const view = normalizeMedicalMonitoringDailyAiCandidates({ candidates, candidateCount });
 if (view.status === "unavailable") {
 return (
 <section className="monitoring-daily-ai-candidates unavailable" aria-label="AI候选线索">
 <header><strong><Bot size={14} /> AI候选线索</strong><AlertTriangle size={14} /></header>
 <p role="alert">已声明有候选线索，但候选明细未返回；不能据此确认或排除风险。</p>
 </section>
 );
 }
 if (view.status === "malformed" || !view.value) {
 return (
 <section className="monitoring-daily-ai-candidates malformed" aria-label="AI候选线索">
 <header><strong><Bot size={14} /> AI候选线索</strong><FileWarning size={14} /></header>
 <p role="alert">候选线索格式异常，暂不展示候选内容；请回到 AI 任务账本核对。</p>
 </section>
 );
 }
 const rows = view.value.candidates.slice(0, 6);
 return (
 <section className={`monitoring-daily-ai-candidates ${view.status}`} aria-label="AI候选线索预览">
 <header className="monitoring-daily-ai-candidates-head">
 <div>
 <strong><Bot size={14} /> AI候选线索预览</strong>
 <span>候选只代表 source-bound 线索；不自动采纳、不替代医学判断。</span>
 </div>
 <span className="monitoring-daily-ai-candidates-count">候选 {view.value.candidateCount ?? "待核对"}</span>
 </header>
 {!rows.length && (
 <p className="monitoring-daily-ai-candidates-empty">当前未返回候选线索；这不等于当前批次无风险。</p>
 )}
 {rows.map((candidate, index) => <CandidateRow key={medicalMonitoringAiCandidateDisplayKey(candidate, index)} candidate={candidate} />)}
 {view.value.candidates.length > rows.length && (
 <small className="monitoring-daily-ai-candidates-more">仅显示前 {rows.length} 条；其余候选仍需逐条医学复核。</small>
 )}
 {view.issues.length > 0 && (
 <p className="monitoring-daily-ai-candidates-warning" role="alert">
 <AlertTriangle size={13} />部分候选字段待核对；来源身份不完整或异常时，不得确认或作为无风险依据。
 </p>
 )}
 <small className="monitoring-daily-ai-candidates-source">此卡只读展示当前运行的候选与声明证据；没有采纳、驳回或风险处置操作。</small>
 </section>
 );
}

.monitoring-daily-ai-evidence {
 display: grid;
 gap: 8px;
 padding: 9px 10px;
 border: 1px solid #d9e4ea;
 background: #fbfdfe;
}

.monitoring-daily-ai-evidence.partial { border-color: #ead8a9; background: #fffdf7; }
.monitoring-daily-ai-evidence.unavailable, .monitoring-daily-ai-evidence.malformed { border-color: #ecc6b5; background: #fff8f3; }
.monitoring-daily-ai-evidence.not_submitted { border-color: #dfe8ed; background: #fcfdfd; }
.monitoring-daily-ai-evidence header { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.monitoring-daily-ai-evidence-head > div { display: grid; gap: 2px; min-width: 0; }
.monitoring-daily-ai-evidence-head strong, .monitoring-daily-ai-evidence header > strong { display: inline-flex; align-items: center; gap: 5px; color: #315568; font-size: 12px; }
.monitoring-daily-ai-evidence-head span { color: #718391; font-size: 10px; line-height: 1.35; }
.monitoring-daily-ai-evidence-status { display: inline-flex; align-items: center; gap: 4px; flex: 0 0 auto; padding: 3px 6px; border-radius: 999px; background: #edf5f8; color: #55788a; font-size: 10px; }
.monitoring-daily-ai-evidence.ready .monitoring-daily-ai-evidence-status { background: #edf7f0; color: #36734d; }
.monitoring-daily-ai-evidence.partial .monitoring-daily-ai-evidence-status, .monitoring-daily-ai-evidence.unavailable .monitoring-daily-ai-evidence-status { background: #fff0e5; color: #9a583b; }
.monitoring-daily-ai-evidence-meta { display: flex; flex-wrap: wrap; gap: 5px 12px; color: #6c808c; font-size: 10px; }
.monitoring-daily-ai-evidence-grid { display: grid; grid-template-columns: repeat(5, minmax(72px, 1fr)); gap: 5px; }
.monitoring-daily-ai-evidence-metric { display: grid; gap: 3px; min-width: 0; padding: 6px 7px; border: 1px solid #e3eaee; background: #fff; }
.monitoring-daily-ai-evidence-metric span { overflow: hidden; color: #71818b; font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-daily-ai-evidence-metric strong { color: #315568; font-size: 16px; line-height: 1; }
.monitoring-daily-ai-evidence-metric.positive strong { color: #2f7049; }
.monitoring-daily-ai-evidence-metric.attention strong { color: #9c5e19; }
.monitoring-daily-ai-evidence-metric.danger strong { color: #a94f3d; }
.monitoring-daily-ai-evidence-progress { display: grid; gap: 4px; }
.monitoring-daily-ai-evidence-progress-label { display: flex; justify-content: space-between; color: #6f818b; font-size: 10px; }
.monitoring-daily-ai-evidence-progress-label strong { color: #315568; }
.monitoring-daily-ai-evidence-progress-track { overflow: hidden; height: 5px; border-radius: 999px; background: #e7eef2; }
.monitoring-daily-ai-evidence-progress-track span { display: block; height: 100%; border-radius: inherit; background: #5c9bb5; transition: width .2s ease; }
.monitoring-daily-ai-evidence-failures { display: grid; gap: 4px; padding: 7px 8px; border: 1px solid #f0d9d0; background: #fff9f6; color: #7a655d; font-size: 10px; }
.monitoring-daily-ai-evidence-failures strong { color: #984f39; font-size: 10px; }
.monitoring-daily-ai-evidence-failures div { display: grid; grid-template-columns: auto auto minmax(0, 1fr); gap: 7px; min-width: 0; align-items: baseline; }
.monitoring-daily-ai-evidence-failures code { flex: 0 0 auto; max-width: 140px; overflow: hidden; color: #9b604b; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-daily-ai-evidence-failures span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
