.monitoring-daily-ai-failure-kind.invalid_structure, .monitoring-daily-ai-failure-kind.low_confidence { background: #fff0ec; color: #a14f3b; }
.monitoring-daily-ai-failure-kind.unavailable, .monitoring-daily-ai-failure-kind.stale_input, .monitoring-daily-ai-failure-kind.blocked { background: #f1f3f4; color: #687983; }
.monitoring-daily-ai-evidence-failures small, .monitoring-daily-ai-evidence-source { color: #8494a0; font-size: 9px; line-height: 1.4; }
