import { AlertTriangle, Database, FileWarning } from "lucide-react";

import {
 dailyDiffCountLabel,
 normalizeMedicalMonitoringDailyDiff,
} from "./medicalMonitoringDailyDiffView.mjs";
import "./MedicalMonitoringDailyDiffSummary.css";

const METRICS = [
 ["newRows", "新增记录", "neutral"],
 ["changedRows", "变更记录", "attention"],
 ["persistingRows", "持续记录", "neutral"],
 ["removedRows", "移除记录", "attention"],
 ["rereviewRows", "需重新复核", "attention"],
 ["fieldChanges", "字段变更", "neutral"],
 ["schemaChanges", "结构变化", "danger"],
 ["identityMatchTotal", "身份匹配", "neutral"],
];

const CHANGE_KIND_LABELS = {
 added: "新增值",
 removed: "移除值",
 changed: "值变更",
 cleared: "清空值",
};

const DETAIL_GROUPS = [
 ["newKeys", "新增记录"],
 ["changedKeys", "变更记录"],
 ["rereviewKeys", "需重新复核"],
 ["removedKeys", "移除记录"],
 ["removalBlockedKeys", "身份阻断的移除"],
 ["missingDomains", "缺失数据域"],
];

function evidenceLabel(value) {
 if (value === true) return "已声明";
 if (value === false) return "未声明";
 return "待核对";
}

function DiffMetric({ field, label, tone, counts }) {
 return (
 <div className={`monitoring-daily-diff-metric ${tone}`}>
 <span>{label}</span>
 <strong>{dailyDiffCountLabel(counts[field])}</strong>
 </div>
 );
}

function clip(value, max = 84) {
 const text = String(value || "");
 return text.length > max ? `${text.slice(0, max - 1)}…` : text;
}

function KeyDetailGroup({ label, items }) {
 if (!Array.isArray(items) || items.length === 0) return null;
 return (
 <div className="monitoring-daily-diff-detail-group">
 <strong>{label}</strong>
 <ul>
 {items.map((item) => <li key={`${label}-${item}`} title={item}>{clip(item)}</li>)}
 </ul>
 </div>
 );
}

function DiffDetailDisclosure({ details }) {
 const hasDetails = [
 details?.fieldChanges,
 details?.schemaDiffs,
 details?.identityMatchSamples,
 ...DETAIL_GROUPS.map(([field]) => details?.[field]),
 ].some((items) => Array.isArray(items) && items.length > 0);
 if (!hasDetails && !details?.truncated) return null;

 return (
 <details className="monitoring-daily-diff-details">
 <summary>查看结构、字段与回源核对明细</summary>
 <p className="monitoring-daily-diff-detail-note">
 明细只用于定位差异来源，不是医学风险结论；请回到对应来源行、字段和风险证据完成复核。
 </p>
 {details?.schemaDiffs?.length > 0 && (
 <div className="monitoring-daily-diff-detail-section">
 <strong>结构变化</strong>
 <ul className="monitoring-daily-diff-schema-list">
 {details.schemaDiffs.map((item) => (
 <li key={`schema-${item.domain}`}>
 <span>{item.domain}</span>
 {item.addedFields.length > 0 && <small>新增列：{item.addedFields.join("、")}</small>}
 {item.removedFields.length > 0 && <small>移除列：{item.removedFields.join("、")}</small>}
 </li>
 ))}
 </ul>
 </div>
 )}
 {details?.fieldChanges?.length > 0 && (
 <div className="monitoring-daily-diff-detail-section">
 <strong>字段变化（最多展示 8 条）</strong>
 <ul className="monitoring-daily-diff-field-list">
 {details.fieldChanges.map((item, index) => (
 <li key={`${item.businessKey}-${item.fieldName}-${index}`}>
 <span>{item.domain} · {item.fieldName} · {CHANGE_KIND_LABELS[item.changeKind] || item.changeKind}</span>
 <small title={item.businessKey}>业务键：{clip(item.businessKey)}</small>
 <small>上一批：{item.previousLocator || "定位待核对"}；本批：{item.currentLocator || "定位待核对"}</small>
 </li>
 ))}
 </ul>
 </div>
 )}
 {details?.identityMatchSamples?.length > 0 && (
 <div className="monitoring-daily-diff-detail-section">
 <strong>身份匹配样本（最多展示 8 条）</strong>
 <ul className="monitoring-daily-diff-field-list">
 {details.identityMatchSamples.map((item, index) => (
 <li key={`${item.previousBusinessKey}-${index}`}>
 <span>{item.matchBasis}</span>
 <small>上一批：{clip(item.previousBusinessKey)}</small>
 <small>本批：{clip(item.currentBusinessKey)}</small>
 </li>
 ))}
 </ul>
 </div>
 )}
 <div className="monitoring-daily-diff-detail-groups">
 {DETAIL_GROUPS.map(([field, label]) => (
 <KeyDetailGroup key={field} label={label} items={details?.[field]} />
 ))}
 </div>
 {details?.truncated && (
 <small className="monitoring-daily-diff-detail-truncated">
 记录较多，仅展示各类前 8 条；计数仍以服务端冻结 diff 快照为准。
 </small>
 )}
 </details>
 );
}

export default function MedicalMonitoringDailyDiffSummary({ diff }) {
 const view = normalizeMedicalMonitoringDailyDiff(diff);
 if (view.status === "empty") {
 return (
 <div className="monitoring-daily-diff-summary empty" role="status">
 <Database size={14} aria-hidden="true" />
 <span>当前运行尚未生成批次差异快照；不把未生成差异视为无变化。</span>
 </div>
 );
 }
 if (view.status === "malformed" || !view.value) {
 return (
 <section className="monitoring-daily-diff-summary malformed" aria-label="批次差异证据">
 <header>
 <strong>批次差异证据</strong>
 <FileWarning size={15} aria-hidden="true" />
 </header>
 <p className="monitoring-daily-diff-warning" role="alert">
 差异快照格式异常，暂不展示计数；请回到源批次与下方运行步骤核对。
 </p>
 </section>
 );
 }

 const { value } = view;
 return (
 <section className={`monitoring-daily-diff-summary ${view.status}`} aria-label="批次差异摘要">
 <header className="monitoring-daily-diff-head">
 <div>
 <strong>本批次与比较基线的显式差异</strong>
 <span>只展示冻结 diff 快照中的计数；差异数量不等于风险数量。</span>
 </div>
 <span className="monitoring-daily-diff-evidence">
 完整快照：{evidenceLabel(value.fullSnapshotProven)}
 </span>
 </header>
 <div className="monitoring-daily-diff-meta">
 <span>{value.previousBatchId || "比较基线待核对"} → {value.currentBatchId || "当前批次待核对"}</span>
 <span>{value.algorithmVersion || "算法版本待核对"}</span>
 </div>
 <div className="monitoring-daily-diff-grid">
 {METRICS.map(([field, label, tone]) => (
 <DiffMetric key={field} field={field} label={label} tone={tone} counts={value.counts} />
 ))}
 </div>
 <div className="monitoring-daily-diff-removal">
 <span>移除处置证据</span>
 <strong>可确认 {dailyDiffCountLabel(value.counts.removalEligibleRows)}</strong>
 <strong>阻断 {dailyDiffCountLabel(value.counts.removalBlockedRows)}</strong>
 <span>缺失域 {dailyDiffCountLabel(value.counts.missingDomains)}</span>
 </div>
 <DiffDetailDisclosure details={value.details} />
 {value.safetyReasons?.length > 0 && (
 <div className="monitoring-daily-diff-safety" role="alert">
 <AlertTriangle size={14} aria-hidden="true" />
 <div>
 <strong>继续规则 / AI 前先处理</strong>
 <ul>
 {value.safetyReasons.map((reason) => (
 <li key={reason.code}>
 <span>{reason.label}</span>
 <small>{reason.action}</small>
 </li>
 ))}
 </ul>
 </div>
 </div>
 )}
 {view.issues.length > 0 && (
 <p className="monitoring-daily-diff-warning" role="alert">
 <AlertTriangle size={13} aria-hidden="true" />
 部分差异字段待核对；未提供或形状异常的字段保持为“待核对”，不会补成 0。
 </p>
 )}
 <small className="monitoring-daily-diff-source">
 快照 {value.snapshotId || "标识待核对"} · 输出摘要 {value.outputSha256 || "待核对"}
 </small>
 </section>
 );
}

.monitoring-daily-run-evidence {
 display: grid;
 gap: 8px;
 padding: 9px 10px;
 border: 1px solid #d9e4ea;
 background: #fbfdfe;
}

.monitoring-daily-run-evidence.partial { border-color: #ead8a9; background: #fffdf7; }
.monitoring-daily-run-evidence.malformed { border-color: #ecc6b5; background: #fff8f3; }
.monitoring-daily-run-evidence.empty { color: #738596; font-size: 11px; }
.monitoring-daily-run-evidence header { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.monitoring-daily-run-evidence-head > div:first-child { display: grid; gap: 2px; min-width: 0; }
.monitoring-daily-run-evidence-head strong, .monitoring-daily-run-evidence header > strong { display: inline-flex; align-items: center; gap: 5px; color: #315568; font-size: 12px; }
.monitoring-daily-run-evidence-head span { color: #718391; font-size: 10px; line-height: 1.35; }
.monitoring-daily-run-evidence-counts { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 4px; }
.monitoring-daily-run-evidence-counts em { padding: 3px 6px; border-radius: 999px; background: #edf5f8; color: #55788a; font-size: 9px; font-style: normal; white-space: nowrap; }
.monitoring-daily-run-evidence-counts em.running { background: #fff4d7; color: #8a650e; }
.monitoring-daily-run-evidence-counts em.danger { background: #fff0ec; color: #a13e2d; }
.monitoring-daily-run-evidence-table { overflow: hidden; border: 1px solid #e4ebef; border-radius: 6px; }
.monitoring-daily-run-evidence-row { min-height: 34px; display: grid; grid-template-columns: 1.05fr .8fr .45fr 1.35fr .8fr 1.35fr; align-items: center; gap: 6px; padding: 5px 7px; border-bottom: 1px solid #edf2f5; color: #536b78; font-size: 10px; }
.monitoring-daily-run-evidence-row:last-child { border-bottom: 0; }
.monitoring-daily-run-evidence-row.header { min-height: 28px; background: #f6f9fb; color: #768895; font-size: 9px; font-weight: 700; }
.monitoring-daily-run-evidence-row > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-daily-run-evidence-row .step-label { display: inline-flex; align-items: center; gap: 5px; color: #315568; font-weight: 700; }
.monitoring-daily-run-evidence-row .step-label > span { display: inline-flex; color: #6b94a5; }
.monitoring-daily-run-evidence-row .step-status { color: #6c808c; }
.monitoring-daily-run-evidence-row .step-status.completed { color: #2f7049; font-weight: 700; }
.monitoring-daily-run-evidence-row .step-status.running { color: #8a650e; font-weight: 700; }
.monitoring-daily-run-evidence-row .step-status.failed, .monitoring-daily-run-evidence-row .step-status.unknown { color: #a13e2d; font-weight: 700; }
.monitoring-daily-run-evidence-row .evidence-present { color: #2f7049; }
.monitoring-daily-run-evidence-row .evidence-missing { color: #a13e2d; font-weight: 700; }
.monitoring-daily-run-evidence-row .step-details { display: flex; gap: 4px; }
.monitoring-daily-run-evidence-row .step-details small { overflow: hidden; padding: 2px 4px; border-radius: 3px; background: #f1f5f7; color: #6e7f88; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-daily-run-evidence-warning { display: flex; align-items: flex-start; gap: 5px; margin: 0; color: #8e5337; font-size: 10px; line-height: 1.4; }
.monitoring-daily-run-evidence-source { color: #8494a0; font-size: 9px; line-height: 1.4; }
.monitoring-daily-run-evidence p { margin: 0; line-height: 1.45; }

@media (max-width: 900px) {
 .monitoring-daily-run-evidence-row { grid-template-columns: 1.1fr .8fr .5fr 1.25fr .8fr 1fr; }
}

@media (max-width: 680px) {
 .monitoring-daily-run-evidence-head { display: grid; }
 .monitoring-daily-run-evidence-counts { justify-content: flex-start; }
 .monitoring-daily-run-evidence-row { grid-template-columns: 1.2fr .85fr .5fr 1fr; }
 .monitoring-daily-run-evidence-row > span:nth-child(5), .monitoring-daily-run-evidence-row > span:nth-child(6) { display: none; }
}

import { AlertTriangle, CheckCircle2, Circle, Clock3, FileWarning } from "lucide-react";

import {
 medicalMonitoringRunStepCountLabel,
 medicalMonitoringRunStepEvidenceLabel,
 medicalMonitoringRunStepStatusLabel,
 normalizeMedicalMonitoringDailyRunEvidence,
} from "./medicalMonitoringDailyRunEvidence.mjs";
import "./MedicalMonitoringDailyRunEvidence.css";

function display(value) {
 return value || "待核对";
}

function rowIcon(status) {
 if (status === "completed") return <CheckCircle2 size={13} aria-hidden="true" />;
 if (status === "running") return <Clock3 size={13} aria-hidden="true" />;
 if (status === "not_started" || status === "not_applicable") return <Circle size={13} aria-hidden="true" />;
 return <AlertTriangle size={13} aria-hidden="true" />;
}

export default function MedicalMonitoringDailyRunEvidence({ steps }) {
 const view = normalizeMedicalMonitoringDailyRunEvidence(steps);
 if (view.status === "empty") {
 return (
 <section className="monitoring-daily-run-evidence empty" aria-label="运行步骤账本">
 <header><strong><Clock3 size={14} /> 运行步骤账本</strong></header>
 <p>当前运行尚未生成步骤记录；不据此判定任何步骤已完成或无风险。</p>
 </section>
 );
 }
 if (view.status === "malformed" || !view.value) {
 return (
 <section className="monitoring-daily-run-evidence malformed" aria-label="运行步骤账本">
 <header><strong><FileWarning size={14} /> 运行步骤账本</strong></header>
 <p role="alert">步骤账本格式异常，暂不展示步骤状态；请回到运行详情核对原始记录。</p>
 </section>
 );
 }

 const { rows, summary } = view.value;
 return (
 <section className={`monitoring-daily-run-evidence ${view.status}`} aria-label="运行步骤账本">
 <header className="monitoring-daily-run-evidence-head">
 <div>
 <strong><Clock3 size={14} /> 运行步骤账本</strong>
 <span>显示每一步的显式状态、尝试次数和输出证据；未开始不等于已通过。</span>
 </div>
 <div className="monitoring-daily-run-evidence-counts">
 <em>完成 {summary.completed}</em>
 <em className="running">运行中 {summary.running}</em>
 <em className={summary.failed > 0 ? "danger" : ""}>失败 {summary.failed}</em>
 </div>
 </header>

 <div className="monitoring-daily-run-evidence-table" role="table" aria-label="医学监查运行步骤">
 <div className="monitoring-daily-run-evidence-row header" role="row">
 <span>步骤</span><span>状态</span><span>尝试</span><span>更新时间</span><span>输出证据</span><span>详情</span>
 </div>
 {rows.map((row) => (
 <div className="monitoring-daily-run-evidence-row" role="row" key={`${row.stepName}-${row.sourceIndex ?? "missing"}`}>
 <span className="step-label"><span>{rowIcon(row.status)}</span>{row.label}</span>
 <span className={`step-status ${row.status || "unknown"}`}>{medicalMonitoringRunStepStatusLabel(row.status)}</span>
 <span>{medicalMonitoringRunStepCountLabel(row.attemptCount)}</span>
 <span title={display(row.updatedAt)}>{display(row.updatedAt)}</span>
 <span className={row.outputBound ? "evidence-present" : "evidence-missing"}>{medicalMonitoringRunStepEvidenceLabel(row)}</span>
 <span className="step-details">
 {row.details.length > 0
 ? row.details.slice(0, 2).map((detail) => <small key={detail.field}>{detail.label} {detail.value}</small>)
 : row.status === "not_started" || row.status === "not_applicable" ? "—" : "待核对"}
 </span>
 </div>
 ))}
 </div>

 {(summary.outputMissing > 0 || summary.unknownRecorded > 0) && (
 <p className="monitoring-daily-run-evidence-warning" role="alert">
 <AlertTriangle size={13} />{summary.outputMissing > 0 ? `${summary.outputMissing} 个已完成步骤缺少输出摘要；` : ""}{summary.unknownRecorded > 0 ? `${summary.unknownRecorded} 个账本步骤未在标准流程内；` : ""}请核对原始运行证据。
 </p>
 )}
 {view.issues.length > 0 && (
 <p className="monitoring-daily-run-evidence-warning" role="alert">
 <AlertTriangle size={13} />部分步骤字段待核对；异常值未补写，也不作为无风险依据。
 </p>
 )}
 <small className="monitoring-daily-run-evidence-source">步骤账本来自当前运行详情的显式记录；此卡不重试、补写或改变运行状态。</small>
 </section>
 );
}

import { useCallback, useEffect, useMemo, useState } from "react";
import {
 AlertTriangle,
 CheckCircle2,
 Circle,
 RefreshCw,
} from "lucide-react";

import {
 MedicalMonitoringApiError,
 createMedicalMonitoringApi,
} from "./medicalMonitoringApi.mjs";
import {
 canStartMonitoringDailyRun,
 monitoringDailyRunRemediation,
} from "./medicalMonitoringDailyRunStartGate.mjs";
import {
 completedDailyRunStep,
 dailyRunBaselineRevision,
 dailyRunAiAssemblyGate,
 dailyRunProgressCount,
 dailyRunRiskCount,
 newestDailyRun,
 normalizeDailyRunAiProgress,
 normalizeDailyRunDetail,
 normalizeDailyRunList,
 normalizeDailyRunReadiness,
} from "./medicalMonitoringDailyRunView.mjs";
import { monitoringModeForDailyRun } from "./medicalMonitoringModeCatalog.mjs";
import MedicalMonitoringDailyDiffSummary from "./MedicalMonitoringDailyDiffSummary.jsx";
import MedicalMonitoringDailyAiEvidence from "./MedicalMonitoringDailyAiEvidence.jsx";
import MedicalMonitoringDailyAiCandidates from "./MedicalMonitoringDailyAiCandidates.jsx";
import MedicalMonitoringDailyRunEvidence from "./MedicalMonitoringDailyRunEvidence.jsx";
import {
 createMedicalMonitoringProjectRequestScope,
} from "./medicalMonitoringProjectRequestScope.mjs";

const RUN_STEPS = [
 { key: "prepare", label: "批次准备" },
 { key: "diff", label: "差异分析" },
 { key: "rules", label: "医学规则" },
 { key: "ai", label: "AI复核" },
 { key: "confirm", label: "风险确认" },
];

const STATUS_STEP = {
 prepared: 0,
 diffing: 1,
 drift_review_required: 1,
 rules_running: 2,
 ai_running: 3,
 analysis_partial: 3,
 risk_review: 4,
 ready_to_confirm: 4,
 confirmed: 5,
 superseded: 0,
};

function requestKey(prefix) {
 const random = globalThis.crypto?.randomUUID?.()
 || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
 return `${prefix}-${random}`;
}

function apiErrorMessage(error) {
 if (error instanceof MedicalMonitoringApiError) {
 const detail = error.detail?.detail;
 if (detail && typeof detail === "object" && detail.message) {
 return detail.message;
 }
 }
 return error?.message || "日常医学监查运行失败";
}

export default function MedicalMonitoringDailyRunPanel({
 projectId,
 batch,
 api: suppliedApi,
 onMappingRequired,
 onRulePackRequired,
 onBaselineConfirmed,
}) {
 const dailyMode = monitoringModeForDailyRun();
 const fallbackApi = useMemo(() => createMedicalMonitoringApi(), []);
 const api = suppliedApi || fallbackApi;
 const requestScope = useMemo(
 () => createMedicalMonitoringProjectRequestScope(projectId),
 [projectId],
 );
 const [runList, setRunList] = useState(null);
 const [detail, setDetail] = useState(null);
 const [aiProgress, setAiProgress] = useState(null);
 const [readiness, setReadiness] = useState(null);
 const [busy, setBusy] = useState(false);
 const [error, setError] = useState("");
 const [readinessError, setReadinessError] = useState("");
 const [aiProgressError, setAiProgressError] = useState("");

 const load = useCallback(async ({ quiet = false } = {}) => {
 if (!batch?.batch_id) return;
 const request = requestScope.begin("daily-run-state");
 if (!quiet) setBusy(true);
 setError("");
 setReadinessError("");
 setAiProgressError("");
 try {
 const rawList = await api.listDailyRuns(
 projectId,
 { signal: request.signal },
 );
 if (!requestScope.isCurrent(request)) return;
 const normalizedList = normalizeDailyRunList(rawList, { projectId });
 if (!normalizedList.ok) throw new Error(normalizedList.error);
 const list = normalizedList.value;
 const active = list.active_run?.batch_id === batch.batch_id
 && typeof list.active_run.run_id === "string"
 && list.active_run.run_id.trim()
 ? list.active_run
 : null;
 const selected = active || newestDailyRun(list.items, batch.batch_id);
 setRunList(list);
 if (!selected) {
 setDetail(null);
 setAiProgress(null);
 try {
 const rawReadiness = await api.getDailyRunReadiness(
 projectId,
 batch.batch_id,
 { signal: request.signal },
 );
 const normalizedReadiness = normalizeDailyRunReadiness(rawReadiness, {
 projectId,
 batchId: batch.batch_id,
 });
 if (!normalizedReadiness.ok) throw new Error(normalizedReadiness.error);
 setReadiness(normalizedReadiness.value);
 } catch (nextError) {
 if (requestScope.isCurrent(request)) {
 setReadiness(null);
 setReadinessError(apiErrorMessage(nextError, "日常监查就绪状态读取失败"));
 }
 }
 return;
 }
 const rawDetail = await api.getDailyRun(
 projectId,
 selected.run_id,
 { signal: request.signal },
 );
 if (!requestScope.isCurrent(request)) return;
 const normalizedDetail = normalizeDailyRunDetail(rawDetail, {
 projectId,
 runId: selected.run_id,
 });
 if (!normalizedDetail.ok) throw new Error(normalizedDetail.error);
 const nextDetail = normalizedDetail.value;
 setDetail(nextDetail);
 try {
 const rawReadiness = await api.getDailyRunReadiness(
 projectId,
 batch.batch_id,
 { signal: request.signal },
 );
 const normalizedReadiness = normalizeDailyRunReadiness(rawReadiness, {
 projectId,
 batchId: batch.batch_id,
 });
 if (!normalizedReadiness.ok) throw new Error(normalizedReadiness.error);
 setReadiness(normalizedReadiness.value);
 } catch (nextError) {
 if (requestScope.isCurrent(request)) {
 setReadiness(null);
 setReadinessError(apiErrorMessage(nextError, "日常监查就绪状态读取失败"));
 }
 }
 if (
 ["ai_running", "analysis_partial", "risk_review", "ready_to_confirm", "confirmed"]
 .includes(nextDetail.run.status)
 && completedDailyRunStep(nextDetail, "independent_ai_submission")
 ) {
 try {
 const rawAiProgress = await api.getDailyRunAiProgress(
 projectId,
 selected.run_id,
 { signal: request.signal },
 );
 const normalizedAiProgress = normalizeDailyRunAiProgress(rawAiProgress, {
 projectId,
 runId: selected.run_id,
 });
 if (!normalizedAiProgress.ok) throw new Error(normalizedAiProgress.error);
 setAiProgress(normalizedAiProgress.value);
 } catch (nextError) {
 if (requestScope.isCurrent(request)) {
 setAiProgress(null);
 setAiProgressError(apiErrorMessage(nextError, "AI复核进度读取失败"));
 }
 }
 } else {
 setAiProgress(null);
 setAiProgressError("");
 }
 } catch (nextError) {
 if (requestScope.isCurrent(request) && nextError.name !== "AbortError") {
 setDetail(null);
 setAiProgress(null);
 setReadiness(null);
 setReadinessError("");
 setAiProgressError("");
 setError(apiErrorMessage(nextError));
 }
 } finally {
 if (requestScope.isCurrent(request) && !quiet) setBusy(false);
 requestScope.finish(request);
 }
 }, [api, batch?.batch_id, projectId, requestScope]);

 useEffect(() => {
 requestScope.activate();
 return () => requestScope.dispose();
 }, [requestScope]);

 useEffect(() => {
 load();
 }, [load, batch?.active_mapping_revision, batch?.version]);

 const run = detail?.run || null;
 const aiSubmitted = completedDailyRunStep(detail, "independent_ai_submission");
 const aiAssemblyGate = dailyRunAiAssemblyGate(detail, aiProgress);
 const aiStillRunning = run?.status === "ai_running" && aiAssemblyGate.running;
 const aiAssemblyBlocked = run?.status === "ai_running"
 && aiSubmitted
 && !aiStillRunning
 && !aiAssemblyGate.canAssemble;
 const generatedRiskCount = dailyRunRiskCount(detail);
 const currentBaselineRevision = dailyRunBaselineRevision(runList);
 const baselineRevisionUnavailable = run?.status === "ready_to_confirm"
 && currentBaselineRevision === null;
 const aiCompletedCount = dailyRunProgressCount(aiProgress?.completed);
 const aiTotalCount = dailyRunProgressCount(aiProgress?.total);

 useEffect(() => {
 if (!aiStillRunning) return undefined;
 const timer = globalThis.setTimeout(() => load({ quiet: true }), 2500);
 return () => globalThis.clearTimeout(timer);
 }, [aiStillRunning, load, aiProgress?.completed, aiProgress?.running]);

 const execute = async (operation) => {
 if (busy) return;
 setBusy(true);
 setError("");
 try {
 await operation();
 await load({ quiet: true });
 } catch (nextError) {
 setError(apiErrorMessage(nextError));
 } finally {
 setBusy(false);
 }
 };

 const mappingChangedAfterDrift = run?.status === "drift_review_required"
 && batch.active_mapping_revision
 && batch.active_mapping_revision !== run.mapping_revision;

 let action = null;
 const remediation = monitoringDailyRunRemediation(readiness);
 if (!run && !canStartMonitoringDailyRun(readiness)) {
 action = null;
 } else if (
 (!run || run.status === "superseded" || mappingChangedAfterDrift)
 && canStartMonitoringDailyRun(readiness)
 ) {
 action = {
 label: mappingChangedAfterDrift ? "按新映射重新分析" : "开始医学监查",
 run: () => api.prepareDailyRun(projectId, {
 batch_id: batch.batch_id,
 idempotency_key: requestKey("daily-run"),
 }),
 };
 } else if (["prepared", "diffing"].includes(run.status)) {
 action = {
 label: run.baseline_batch_id ? "分析批次差异" : "开始规则分析",
 run: () => api.processDailyRun(projectId, run.run_id, {
 expected_version: run.version,
 owner: "medical_manager",
 }),
 };
 } else if (run.status === "drift_review_required") {
 action = {
 label: "核对批次差异",
 run: async () => onMappingRequired?.(),
 local: true,
 };
 } else if (run.status === "rules_running") {
 action = {
 label: "运行医学规则",
 run: () => api.executeDailyRunRules(projectId, run.run_id, {
 expected_version: run.version,
 owner: "medical_manager",
 }),
 };
 } else if (run.status === "ai_running" && !aiSubmitted) {
 action = {
 label: "启动 AI 复核",
 run: () => api.submitDailyRunAi(projectId, run.run_id, {
 expected_version: run.version,
 owner: "medical_manager",
 }),
 };
 } else if (run.status === "ai_running" && aiAssemblyGate.canAssemble) {
 action = {
 label: "汇总风险项",
 run: () => api.assembleDailyRunRisks(projectId, run.run_id, {
 expected_version: run.version,
 owner: "medical_manager",
 }),
 };
 } else if (run.status === "analysis_partial") {
 action = {
 label: "确认按现有结果继续",
 run: () => api.acknowledgeDailyRunPartial(projectId, run.run_id, {
 expected_version: run.version,
 }),
 };
 } else if (run.status === "risk_review") {
 action = {
 label: "风险项已复核",
 run: () => api.markDailyRunReady(projectId, run.run_id, {
 expected_version: run.version,
 }),
 };
 } else if (run.status === "ready_to_confirm" && currentBaselineRevision !== null) {
 action = {
 label: "确认并设为比较基线",
 run: () => api.confirmDailyRun(projectId, run.run_id, {
 expected_run_version: run.version,
 expected_baseline_revision: currentBaselineRevision,
 confirmed_by: "medical_manager",
 }),
 confirmed: true,
 };
 }
 if (!run && remediation?.key === "mapping") {
 action = {
 label: remediation.label,
 run: async () => onMappingRequired?.(),
 local: true,
 };
 } else if (!run && remediation?.key === "rule_pack") {
 action = {
 label: remediation.label,
 run: async () => onRulePackRequired?.(),
 local: true,
 };
 }

 const currentStep = run ? (STATUS_STEP[run.status] ?? 0) : 0;
 let summary = "冻结批次后运行差异分析、规则识别和 AI 复核。";
 if (!run && readiness && !readiness.ready) {
 summary = readiness.message;
 } else if (mappingChangedAfterDrift) {
 summary = "字段映射已更新，可按新映射重新分析本批次。";
 } else if (run?.status === "drift_review_required") {
 summary = "批次差异存在结构、来源完整性或删除身份阻断，请查看下方差异证据后再继续。";
 } else if (run?.status === "analysis_partial") {
 summary = "部分记录未完成 AI 复核；现有结果可继续审阅，未完成项不会被视为无风险。";
 } else if (run?.status === "risk_review") {
 summary = generatedRiskCount === null
 ? "已生成风险项，但风险计数证据缺失，请打开风险清单核对。"
 : `已生成 ${generatedRiskCount} 条风险项，请完成核对。`;
 } else if (run?.status === "ready_to_confirm") {
 summary = baselineRevisionUnavailable
 ? "当前比较基线版本格式异常，暂不能确认本批次。"
 : "风险项已复核。确认后，本批次才成为下一次比较基线。";
 } else if (run?.status === "confirmed") {
 summary = "本次医学监查已确认，该批次现为项目比较基线。";
 } else if (aiStillRunning) {
 summary = `AI 正在复核：${aiCompletedCount ?? "待确认"}/${aiTotalCount ?? "待确认"} 个受试者已完成。`;
 } else if (aiAssemblyBlocked) {
 summary = "AI 已提交，但当前进度账本缺失或未与提交任务数一致，暂不能汇总风险项。";
 }

 const needsAttention = ["drift_review_required", "analysis_partial"].includes(run?.status);

 return (
 <section className="monitoring-daily-run" aria-label={dailyMode.label}>
 <div className="monitoring-daily-run-head">
 <div>
 <strong>{dailyMode.label}</strong>
 <span>{summary}</span>
 </div>
 <button
 className="icon-button"
 type="button"
 title="刷新运行状态"
 aria-label="刷新运行状态"
 onClick={() => load()}
 disabled={busy}
 >
 <RefreshCw size={15} className={aiStillRunning ? "is-spinning" : ""} />
 </button>
 </div>

 <ol className="monitoring-daily-run-steps">
 {RUN_STEPS.map((step, index) => {
 const completed = currentStep > index;
 const active = currentStep === index && run?.status !== "confirmed";
 return (
 <li
 key={step.key}
 className={`${completed ? "completed" : ""} ${active ? "active" : ""}`}
 >
 {completed
 ? <CheckCircle2 size={16} />
 : <Circle size={16} />}
 <span>{step.label}</span>
 </li>
 );
 })}
 </ol>

 {detail && <MedicalMonitoringDailyDiffSummary diff={detail.diff} />}

 {detail && (
 <MedicalMonitoringDailyAiEvidence
 progress={aiProgress}
 run={run}
 submitted={aiSubmitted}
 />
 )}

 {detail && aiProgress && (
 <MedicalMonitoringDailyAiCandidates
 candidates={aiProgress.candidates}
 candidateCount={aiProgress.candidate_count}
 />
 )}

 {detail && <MedicalMonitoringDailyRunEvidence steps={detail.steps} />}

 {needsAttention && (
 <div className="monitoring-daily-run-attention" role="status">
 <AlertTriangle size={16} />
 <span>{summary}</span>
 </div>
 )}

 <div className="monitoring-daily-run-action">
 <span>
 {run?.status === "confirmed" && run.confirmed_at
 ? `确认时间：${new Date(run.confirmed_at).toLocaleString("zh-CN")}`
 : run?.status === "confirmed"
 ? "本次医学监查已确认。"
 : readiness?.ready
 ? "启动后进入正式日常医学监查状态机。"
 : "请完成上方提示的下一步。"}
 </span>
 {aiStillRunning && (
 <button className="primary-button" type="button" disabled>
 AI 正在复核
 </button>
 )}
 {aiAssemblyBlocked && (
 <button className="primary-button" type="button" disabled>
 等待 AI 任务账本
 </button>
 )}
 {!aiStillRunning && !aiAssemblyBlocked && action && (
 <button
 className="primary-button"
 type="button"
 disabled={busy}
 onClick={() => (
 action.local
 ? action.run()
 : execute(async () => {
 await action.run();
 if (action.confirmed) onBaselineConfirmed?.();
 })
 )}
 >
 {busy ? "处理中" : action.label}
 </button>
 )}
 </div>

 {error && <p className="monitoring-daily-run-error">{error}</p>}
 {readinessError && <p className="monitoring-daily-run-error" role="alert">{readinessError}</p>}
 {aiProgressError && <p className="monitoring-daily-run-error" role="alert">{aiProgressError}</p>}
 </section>
 );
}

import { useCallback, useEffect, useMemo, useState } from "react";
import {
 Check,
 ChevronRight,
 LoaderCircle,
 Pencil,
 RefreshCw,
 Sparkles,
 X,
} from "lucide-react";

import {
 MedicalMonitoringApiError,
 createMedicalMonitoringApi,
} from "./medicalMonitoringApi.mjs";
import { semanticQualityPresentation } from "./medicalMonitoringFieldMappingState.mjs";
import {
 MedicalMonitoringFieldMappingShapeError,
 normalizeFieldMappingRun,
 normalizeFieldMappingStatus,
 normalizeMappingDraft,
 normalizeMappingRevision,
 medicalMonitoringFieldMappingEvidenceKey,
} from "./medicalMonitoringFieldMappingView.mjs";
import { monitoringFieldMappingCopy } from "./medicalMonitoringModels.mjs";
import {
 createMedicalMonitoringProjectRequestScope,
} from "./medicalMonitoringProjectRequestScope.mjs";

const TERMINAL_JOB_STATES = new Set([
 "completed",
 "failed",
 "blocked",
 "stale_input",
 "cancelled",
]);

const FIELD_KIND_LABELS = {
 source_collected: "来源采集字段",
 source_metadata: "来源技术字段",
 standardized_coded: "标准编码字段",
 deterministic_derived: "确定性派生字段",
 unmapped: "暂不映射",
};
const LOW_CONFIDENCE_THRESHOLD = 0.85;

function requestKey(prefix) {
 const random = globalThis.crypto?.randomUUID?.()
 || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
 return `${prefix}-${random}`;
}

function errorText(error, fallback) {
 if (error instanceof MedicalMonitoringApiError) {
 const detail = error.detail?.detail;
 if (detail && typeof detail === "object" && detail.message) {
 return detail.message;
 }
 }
 return error?.message || fallback;
}

function confidenceLabel(value) {
 const number = Number(value);
 if (!Number.isFinite(number)) return "-";
 return `${Math.round(number * 100)}%`;
}

export default function MedicalMonitoringFieldMappingPanel({
 projectId,
 batch,
 aiStatus = {},
 onClose,
 onConfirmed,
}) {
 const api = useMemo(() => createMedicalMonitoringApi(), []);
 const requestScope = useMemo(
 () => createMedicalMonitoringProjectRequestScope(projectId),
 [projectId],
 );
 const [mappingRun, setMappingRun] = useState(null);
 const [jobDetails, setJobDetails] = useState([]);
 const [draft, setDraft] = useState(null);
 const [confirmedRevision, setConfirmedRevision] = useState(null);
 const [activeMapping, setActiveMapping] = useState(null);
 const [activeDomain, setActiveDomain] = useState("all");
 const [attentionFilter, setAttentionFilter] = useState("attention");
 const [search, setSearch] = useState("");
 const [selectedFieldKey, setSelectedFieldKey] = useState("");
 const [fieldForm, setFieldForm] = useState(null);
 const [confirmationReason, setConfirmationReason] = useState(
 "已核对本批次字段语义、试验药物与非试验用药边界，确认用于后续批次解析和医学规则运行。",
 );
 const [busy, setBusy] = useState(false);
 const [message, setMessage] = useState("");
 const [error, setError] = useState("");
 const mappingCopy = useMemo(
 () => monitoringFieldMappingCopy(aiStatus),
 [aiStatus],
 );

 const clearMappingState = useCallback(() => {
 setMappingRun(null);
 setJobDetails([]);
 setDraft(null);
 setConfirmedRevision(null);
 setActiveMapping(null);
 setSelectedFieldKey("");
 setFieldForm(null);
 }, []);

 const applyStatus = useCallback((status) => {
 const normalized = normalizeFieldMappingStatus(status);
 setMappingRun(normalized.job_details.length
 ? {
 batch_id: normalized.batch_id,
 profile_sha256: normalized.profile_sha256,
 input_sha256: normalized.input_sha256,
 field_count: normalized.field_count,
 job_count: normalized.job_count,
 jobs: normalized.job_details.map((item) => item.job),
 }
 : null);
 setJobDetails(normalized.job_details);
 setDraft(normalized.draft
 ? {
 ...normalized.draft,
 semantic_quality: normalized.semantic_quality
 || normalized.draft.semantic_quality
 || null,
 }
 : null);
 setActiveMapping(normalized.active_mapping);
 return normalized.job_details;
 }, []);

 const refreshStatus = useCallback(async () => {
 const request = requestScope.begin("field-mapping-status");
 try {
 const status = await api.getFieldMappingStatus(
 projectId,
 batch.batch_id,
 { signal: request.signal },
 );
 if (!requestScope.isCurrent(request)) return [];
 const nextJobs = applyStatus(status);
 setError("");
 return nextJobs;
 } finally {
 requestScope.finish(request);
 }
 }, [api, applyStatus, batch.batch_id, projectId, requestScope]);

 useEffect(() => {
 requestScope.activate();
 return () => requestScope.dispose();
 }, [requestScope]);

 useEffect(() => {
 const request = requestScope.begin("field-mapping-status");
 clearMappingState();
 setError("");
 setMessage("");
 setBusy(true);
 api.getFieldMappingStatus(projectId, batch.batch_id, { signal: request.signal })
 .then(async (status) => {
 if (!requestScope.isCurrent(request)) return;
 const normalizedStatus = normalizeFieldMappingStatus(status);
 applyStatus(normalizedStatus);
 if (normalizedStatus.draft?.status === "confirmed") {
 setMessage("当前批次已存在正式字段映射。");
 return;
 }
 const mappingRevision = normalizedStatus.active_mapping?.mapping_revision;
 if (!normalizedStatus.draft && mappingRevision) {
 const revision = normalizeMappingRevision(await api.getMappingRevision(
 projectId,
 mappingRevision,
 { signal: request.signal },
 ));
 if (!requestScope.isCurrent(request)) return;
 setDraft({
 ...revision,
 draft_id: revision.draft_id,
 version: revision.draft_version,
 status: "confirmed",
 confirmed_revision_id: revision.mapping_revision,
 });
 setMessage("当前项目已启用以下正式字段映射。");
 }
 })
 .catch((nextError) => {
 if (requestScope.isCurrent(request)) {
 if (nextError?.name !== "AbortError") {
 clearMappingState();
 }
 setError(errorText(nextError, "字段映射状态读取失败"));
 }
 })
 .finally(() => {
 if (requestScope.isCurrent(request)) setBusy(false);
 requestScope.finish(request);
 });
 return () => {
 requestScope.cancel("field-mapping-status");
 };
 }, [api, applyStatus, batch.batch_id, clearMappingState, projectId, requestScope]);

 useEffect(() => {
 if (!mappingRun?.jobs?.length) return undefined;
 const allTerminal = jobDetails.length === mappingRun.jobs.length
 && jobDetails.every((item) => TERMINAL_JOB_STATES.has(item.job?.status));
 if (allTerminal) return undefined;
 let cancelled = false;
 const timer = window.setTimeout(() => {
 refreshStatus().catch((nextError) => {
 if (!cancelled) {
 if (nextError?.name !== "AbortError") {
 clearMappingState();
 }
 setError(errorText(nextError, "字段识别进度读取失败"));
 }
 });
 }, jobDetails.length ? 3500 : 600);
 return () => {
 cancelled = true;
 window.clearTimeout(timer);
 };
 }, [clearMappingState, jobDetails, mappingRun, refreshStatus]);

 const startMapping = async ({ retryFailed = false } = {}) => {
 requestScope.cancel("field-mapping-status");
 const request = requestScope.begin("field-mapping-start");
 setBusy(true);
 setError("");
 setMessage("");
 clearMappingState();
 setDraft(null);
 setConfirmedRevision(null);
 try {
 const run = normalizeFieldMappingRun(
 await api.startFieldMapping(projectId, batch.batch_id, {
 retryFailed,
 signal: request.signal,
 }),
 );
 if (!requestScope.isCurrent(request)) return;
 setMappingRun(run);
 setJobDetails([]);
 setMessage(
 run.jobs?.every((job) => job.status === "completed")
 ? mappingCopy.completedMessage
 : mappingCopy.runningMessage,
 );
 await refreshStatus();
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return;
 if (nextError instanceof MedicalMonitoringFieldMappingShapeError) {
 clearMappingState();
 }
 setError(errorText(nextError, "字段识别未能启动"));
 } finally {
 if (requestScope.isCurrent(request)) setBusy(false);
 requestScope.finish(request);
 }
 };

 const allCompleted = mappingRun?.jobs?.length > 0
 && jobDetails.length === mappingRun.jobs.length
 && jobDetails.every((item) => item.job?.status === "completed");
 const terminalCount = jobDetails.filter(
 (item) => TERMINAL_JOB_STATES.has(item.job?.status),
 ).length;
 const failedJobs = jobDetails.filter(
 (item) => item.job?.status && item.job.status !== "completed"
 && TERMINAL_JOB_STATES.has(item.job.status),
 );
 const candidateMappings = useMemo(
 () => jobDetails.flatMap((item) => item.candidates.flatMap((candidate) => (
 candidate.structured_payload.field_mappings
 ))),
 [jobDetails],
 );

 const acceptAndAssemble = async () => {
 if (!allCompleted || !mappingRun?.profile_sha256) return;
 const request = requestScope.begin("field-mapping-adopt");
 setBusy(true);
 setError("");
 try {
 const nextDraft = normalizeMappingDraft(
 await api.adoptFieldMappingRun(projectId, {
 batchId: batch.batch_id,
 fullProfileSha256: mappingRun.profile_sha256,
 reason: "采用本次完整字段建议进入映射校对。",
 }, { signal: request.signal }),
 );
 if (!requestScope.isCurrent(request)) return;
 setDraft(nextDraft);
 setMessage("AI建议已汇总为可编辑草稿。请重点核对低置信度和试验药物相关字段。");
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return;
 if (nextError instanceof MedicalMonitoringFieldMappingShapeError) {
 clearMappingState();
 }
 setError(errorText(nextError, "字段映射草稿生成失败"));
 } finally {
 if (requestScope.isCurrent(request)) setBusy(false);
 requestScope.finish(request);
 }
 };

 const domains = useMemo(
 () => [...new Set((draft?.fields || candidateMappings).map((item) => item.domain))].sort(),
 [candidateMappings, draft],
 );
 const candidateByField = useMemo(
 () => new Map(candidateMappings.map((item) => [
 `${item.domain}::${item.source_field}`,
 item,
 ])),
 [candidateMappings],
 );
 const attentionReason = useCallback((field) => {
 const role = String(field.recommended_role || "").toLowerCase();
 if (field.field_kind === "unmapped") return "暂未映射";
 if (Number(field.confidence) < LOW_CONFIDENCE_THRESHOLD) return "低置信度";
 if (/(^|_)(ip|cm|dose|dosing|adherence|compliance)(_|$)/.test(role)) {
 return "用药边界";
 }
 if (field.field_kind === "standardized_coded") return "编码依据";
 if (field.field_kind === "deterministic_derived") return "派生依据";
 return "";
 }, []);
 const displayedFields = useMemo(() => {
 const source = draft?.fields || candidateMappings;
 const needle = search.trim().toLocaleLowerCase("zh-CN");
 return source.filter((item) => (
 (activeDomain === "all" || item.domain === activeDomain)
 && (
 attentionFilter === "all"
 || (attentionFilter === "attention" && attentionReason(item))
 || (attentionFilter === "unmapped" && item.field_kind === "unmapped")
 || (
 attentionFilter === "low"
 && Number(item.confidence) < LOW_CONFIDENCE_THRESHOLD
 )
 || (
 attentionFilter === "medication"
 && attentionReason(item) === "用药边界"
 )
 || (
 attentionFilter === "lineage"
 && ["standardized_coded", "deterministic_derived"].includes(
 item.field_kind,
 )
 )
 )
 && (
 !needle
 || item.source_field.toLocaleLowerCase("zh-CN").includes(needle)
 || item.recommended_role.toLocaleLowerCase("zh-CN").includes(needle)
 )
 ));
 }, [
 activeDomain,
 attentionFilter,
 attentionReason,
 candidateMappings,
 draft,
 search,
 ]);
 const confirmedReadOnly = draft?.status === "confirmed";
 const semanticQuality = draft?.semantic_quality || null;
 const semanticQualityState = useMemo(
 () => semanticQualityPresentation(semanticQuality),
 [semanticQuality],
 );
 const changedFields = useMemo(() => {
 if (!draft) return [];
 return draft.fields.filter((field) => {
 const original = candidateByField.get(
 `${field.domain}::${field.source_field}`,
 );
 if (!original) return false;
 return [
 "recommended_role",
 "field_kind",
 "uncertainty",
 "user_action",
 ].some((key) => JSON.stringify(field[key]) !== JSON.stringify(original[key]))
 || JSON.stringify(field.standards_reference || null)
 !== JSON.stringify(original.standards_reference || null)
 || JSON.stringify(field.derivation_lineage || null)
 !== JSON.stringify(original.derivation_lineage || null);
 });
 }, [candidateByField, draft]);
 const attentionCount = useMemo(
 () => (draft?.fields || []).filter((field) => attentionReason(field)).length,
 [attentionReason, draft],
 );

 const selectField = (field) => {
 const key = `${field.domain}::${field.source_field}`;
 const original = candidateByField.get(key);
 setSelectedFieldKey(key);
 setFieldForm({
 domain: field.domain,
 source_field: field.source_field,
 recommended_role: field.recommended_role,
 field_kind: field.field_kind,
 uncertainty: field.uncertainty,
 user_action: field.user_action,
 standards_reference: field.standards_reference || null,
 derivation_lineage: field.derivation_lineage || null,
 evidence_summary: original?.evidence_summary || [],
 });
 };

 const changeFieldKind = (value) => {
 setFieldForm((current) => {
 let derivationLineage = current.derivation_lineage;
 if (value === "standardized_coded") {
 derivationLineage = {
 source_fields: derivationLineage?.source_fields || [],
 coding_system: derivationLineage?.coding_system || "",
 dictionary_version: derivationLineage?.dictionary_version || "",
 };
 } else if (value === "deterministic_derived") {
 derivationLineage = {
 source_fields: derivationLineage?.source_fields || [],
 formula: derivationLineage?.formula || "",
 };
 } else {
 derivationLineage = null;
 }
 return {
 ...current,
 field_kind: value,
 derivation_lineage: derivationLineage,
 };
 });
 };

 const updateLineage = (key, value) => {
 setFieldForm((current) => ({
 ...current,
 derivation_lineage: {
 ...(current.derivation_lineage || {}),
 [key]: value,
 },
 }));
 };

 const saveField = async () => {
 if (!draft || !fieldForm) return;
 const request = requestScope.begin("field-mapping-edit");
 setBusy(true);
 setError("");
 try {
 const nextDraft = normalizeMappingDraft(await api.editMappingDraftField(
 projectId,
 draft.draft_id,
 {
 domain: fieldForm.domain,
 source_field: fieldForm.source_field,
 patch: {
 recommended_role: fieldForm.recommended_role.trim(),
 field_kind: fieldForm.field_kind,
 uncertainty: fieldForm.uncertainty.trim(),
 user_action: fieldForm.user_action.trim(),
 standards_reference: fieldForm.standards_reference,
 derivation_lineage: fieldForm.derivation_lineage
 ? {
 ...fieldForm.derivation_lineage,
 source_fields: (
 fieldForm.derivation_lineage.source_fields || []
 ).map((item) => item.trim()).filter(Boolean),
 }
 : null,
 },
 expected_version: draft.version,
 idempotency_key: requestKey("monitoring-mapping-field"),
 },
 { signal: request.signal },
 ));
 if (!requestScope.isCurrent(request)) return;
 setDraft(nextDraft);
 setSelectedFieldKey("");
 setFieldForm(null);
 setMessage(`已保存 ${fieldForm.domain}.${fieldForm.source_field} 的修订。`);
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return;
 if (nextError instanceof MedicalMonitoringFieldMappingShapeError) {
 clearMappingState();
 }
 setError(errorText(nextError, "字段修订保存失败"));
 } finally {
 if (requestScope.isCurrent(request)) setBusy(false);
 requestScope.finish(request);
 }
 };

 const confirmDraft = async () => {
 if (!draft || confirmationReason.trim().length < 10) return;
 const request = requestScope.begin("field-mapping-confirm");
 setBusy(true);
 setError("");
 try {
 const revision = normalizeMappingRevision(await api.confirmMappingDraft(
 projectId,
 draft.draft_id,
 {
 expected_version: draft.version,
 confirmed_by: "medical_manager",
 confirmation_reason: confirmationReason.trim(),
 idempotency_key: requestKey("monitoring-mapping-confirm"),
 expected_project_version: activeMapping?.project_version || 0,
 },
 { signal: request.signal },
 ));
 if (!requestScope.isCurrent(request)) return;
 setConfirmedRevision(revision);
 setDraft((current) => current && {
 ...current,
 status: "confirmed",
 confirmed_revision_id: revision.mapping_revision,
 });
 setMessage("字段映射已确认，可作为后续批次与规则运行的正式映射版本。");
 setActiveMapping(revision.activation || activeMapping);
 onConfirmed?.(revision);
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return;
 if (nextError instanceof MedicalMonitoringFieldMappingShapeError) {
 clearMappingState();
 }
 setError(errorText(nextError, "字段映射确认失败"));
 } finally {
 if (requestScope.isCurrent(request)) setBusy(false);
 requestScope.finish(request);
 }
 };

 return (
 <section className="monitoring-mapping-panel" aria-label="字段识别与映射校对">
 <header className="monitoring-mapping-head">
 <div>
 <span>{confirmedReadOnly ? "正式字段映射" : "字段识别"}</span>
 <strong>{batch.sources?.[0]?.file_name || "当前批次"}</strong>
 <small>
 {confirmedReadOnly
 ? "当前项目已启用；可查看重点字段、依据与历史确认内容。"
 : mappingCopy.headerDescription}
 </small>
 </div>
 <button className="icon-button" type="button" title="关闭" onClick={onClose}>
 <X size={16} />
 </button>
 </header>

 {!mappingRun && !draft && (
 <div className="monitoring-mapping-start">
 <Sparkles size={22} />
 <div>
 <strong>{mappingCopy.startTitle}</strong>
 <span>{mappingCopy.startDescription}</span>
 </div>
 <button
 className="primary-button"
 type="button"
 disabled={busy}
 title={mappingCopy.startDescription}
 onClick={startMapping}
 >
 {busy ? "正在启动" : mappingCopy.startAction}
 </button>
 </div>
 )}

 {mappingRun && !draft && (
 <>
 <div className="monitoring-mapping-progress">
 <div>
 {allCompleted
 ? <Check size={17} />
 : <LoaderCircle className="spin" size={17} />}
 <strong>
 {allCompleted
 ? `${mappingRun.field_count} 个字段已识别`
 : `${terminalCount}/${mappingRun.job_count} 个识别单元已完成`}
 </strong>
 </div>
 <span>{mappingCopy.progressDescription}</span>
 <button
 className="icon-button"
 type="button"
 title="刷新进度"
 onClick={() => refreshStatus()}
 disabled={busy}
 >
 <RefreshCw size={15} />
 </button>
 </div>
 {failedJobs.length > 0 && (
 <div className="monitoring-mapping-error">
 <span>部分字段尚未生成可用建议，不影响已完成内容或冻结原始数据。</span>
 <button
 className="text-button"
 type="button"
 disabled={busy}
 onClick={() => startMapping({ retryFailed: true })}
 >
 重试失败部分
 </button>
 </div>
 )}
 {allCompleted && (
 <div className="monitoring-mapping-review">
 <div>
 <strong>{candidateMappings.length} 个字段建议可进入校对</strong>
 <span>采用建议不会直接运行风险规则；下一步仍可逐字段修改。</span>
 </div>
 <button className="primary-button" type="button" disabled={busy} onClick={acceptAndAssemble}>
 采用建议并校对
 <ChevronRight size={15} />
 </button>
 </div>
 )}
 </>
 )}

 {draft && (
 <div className="monitoring-mapping-editor">
 <div className="monitoring-mapping-toolbar">
 <select
 value={attentionFilter}
 onChange={(event) => setAttentionFilter(event.target.value)}
 >
 <option value="attention">待关注 ({attentionCount})</option>
 <option value="unmapped">暂未映射</option>
 <option value="low">低置信度</option>
 <option value="medication">用药边界</option>
 <option value="lineage">编码与派生</option>
 <option value="all">全部字段</option>
 </select>
 <select value={activeDomain} onChange={(event) => setActiveDomain(event.target.value)}>
 <option value="all">全部数据域</option>
 {domains.map((domain) => <option value={domain} key={domain}>{domain}</option>)}
 </select>
 <input
 value={search}
 onChange={(event) => setSearch(event.target.value)}
 placeholder="搜索原始字段或建议角色"
 />
 <span>{displayedFields.length}/{draft.fields.length} 个字段</span>
 </div>

 <div className="monitoring-mapping-table" role="table" aria-label="字段映射草稿">
 <div className="monitoring-mapping-row header" role="row">
 <span>来源字段</span>
 <span>建议角色</span>
 <span>字段类型</span>
 <span>置信度</span>
 <span aria-label="操作" />
 </div>
 {displayedFields.map((field) => {
 const key = `${field.domain}::${field.source_field}`;
 return (
 <button
 type="button"
 role="row"
 className={`monitoring-mapping-row ${selectedFieldKey === key ? "active" : ""}`}
 key={key}
 onClick={() => selectField(field)}
 >
 <span><b>{field.domain}</b>{field.source_field}</span>
 <span title={field.recommended_role}>{field.recommended_role}</span>
 <span>{FIELD_KIND_LABELS[field.field_kind] || field.field_kind}</span>
 <span
 className={
 Number(field.confidence) < LOW_CONFIDENCE_THRESHOLD
 ? "low"
 : ""
 }
 >
 {confidenceLabel(field.confidence)}
 </span>
 <Pencil size={14} />
 </button>
 );
 })}
 </div>

 {fieldForm && (
 <div className="monitoring-mapping-field-editor">
 <div>
 <strong>{fieldForm.domain}.{fieldForm.source_field}</strong>
 <button className="icon-button" type="button" title="关闭字段编辑" onClick={() => setFieldForm(null)}>
 <X size={14} />
 </button>
 </div>
 <label>
 建议角色
 <input
 disabled={confirmedReadOnly}
 value={fieldForm.recommended_role}
 onChange={(event) => setFieldForm((current) => ({
 ...current,
 recommended_role: event.target.value,
 }))}
 />
 </label>
 <label>
 字段类型
 <select
 disabled={confirmedReadOnly}
 value={fieldForm.field_kind}
 onChange={(event) => changeFieldKind(event.target.value)}
 >
 {Object.entries(FIELD_KIND_LABELS).map(([value, label]) => (
 <option value={value} key={value}>{label}</option>
 ))}
 </select>
 </label>
 {fieldForm.evidence_summary?.length > 0 && (
 <section className="monitoring-mapping-evidence">
 <strong>原始画像依据</strong>
 {fieldForm.evidence_summary.map((item, index) => (
 <div key={medicalMonitoringFieldMappingEvidenceKey(item, index)}>
 <span>
 {item.profile?.non_empty_count}/{item.profile?.total_rows}
 {" 条非空 · "}
 {item.profile?.inferred_type || "类型待定"}
 </span>
 <small>{item.locator || "来源定位待核对"}</small>
 {!item.evidence_id && !item.locator && (
 <small>来源证据身份缺失；不可据此确认映射</small>
 )}
 </div>
 ))}
 </section>
 )}
 {fieldForm.standards_reference && (
 <section className="monitoring-mapping-evidence">
 <strong>标准参照（仅作参照）</strong>
 <span>
 {fieldForm.standards_reference.reference_name}
 {" · "}
 {fieldForm.standards_reference.reference_concept}
 </span>
 <small>{fieldForm.standards_reference.uncertainty}</small>
 </section>
 )}
 {fieldForm.field_kind === "standardized_coded" && (
 <fieldset className="monitoring-mapping-lineage">
 <legend>编码血缘</legend>
 <label>
 来源字段
 <input
 disabled={confirmedReadOnly}
 value={(fieldForm.derivation_lineage?.source_fields || []).join(", ")}
 onChange={(event) => updateLineage(
 "source_fields",
 event.target.value.split(","),
 )}
 placeholder="如 AETERM, AEDECOD"
 />
 </label>
 <label>
 编码体系
 <input
 disabled={confirmedReadOnly}
 value={fieldForm.derivation_lineage?.coding_system || ""}
 onChange={(event) => updateLineage(
 "coding_system",
 event.target.value,
 )}
 placeholder="如 MedDRA"
 />
 </label>
 <label>
 词典版本
 <input
 disabled={confirmedReadOnly}
 value={fieldForm.derivation_lineage?.dictionary_version || ""}
 onChange={(event) => updateLineage(
 "dictionary_version",
 event.target.value,
 )}
 placeholder="填写版本或对应版本字段"
 />
 </label>
 </fieldset>
 )}
 {fieldForm.field_kind === "deterministic_derived" && (
 <fieldset className="monitoring-mapping-lineage">
 <legend>派生血缘</legend>
 <label>
 来源字段
 <input
 disabled={confirmedReadOnly}
 value={(fieldForm.derivation_lineage?.source_fields || []).join(", ")}
 onChange={(event) => updateLineage(
 "source_fields",
 event.target.value.split(","),
 )}
 placeholder="以逗号分隔"
 />
 </label>
 <label>
 计算规则
 <textarea
 disabled={confirmedReadOnly}
 rows={3}
 value={fieldForm.derivation_lineage?.formula || ""}
 onChange={(event) => updateLineage(
 "formula",
 event.target.value,
 )}
 />
 </label>
 </fieldset>
 )}
 <label>
 不确定性
 <textarea
 disabled={confirmedReadOnly}
 rows={3}
 value={fieldForm.uncertainty}
 onChange={(event) => setFieldForm((current) => ({
 ...current,
 uncertainty: event.target.value,
 }))}
 />
 </label>
 <label>
 建议核对
 <textarea
 disabled={confirmedReadOnly}
 rows={2}
 value={fieldForm.user_action}
 onChange={(event) => setFieldForm((current) => ({
 ...current,
 user_action: event.target.value,
 }))}
 />
 </label>
 {!confirmedReadOnly && (
 <button className="primary-button" type="button" disabled={busy} onClick={saveField}>
 保存修订
 </button>
 )}
 </div>
 )}

 <footer className="monitoring-mapping-confirm">
 {semanticQuality && (
 <div
 className={`monitoring-mapping-quality-summary ${semanticQualityState.level}`}
 >
 <strong>{semanticQualityState.title}</strong>
 {semanticQualityState.detail && (
 <span>{semanticQualityState.detail}</span>
 )}
 </div>
 )}
 <div className="monitoring-mapping-change-summary">
 <strong>{changedFields.length} 项已修订</strong>
 <span>{attentionCount} 项属于重点校对范围</span>
 </div>
 <label>
 <span>{confirmedReadOnly ? "启用说明" : "确认说明"}</span>
 <input
 value={confirmationReason}
 onChange={(event) => setConfirmationReason(event.target.value)}
 disabled={confirmedReadOnly}
 />
 </label>
 <button
 className="primary-button"
 type="button"
 disabled={
 confirmedReadOnly
 || busy
 || semanticQualityState.blocksConfirmation
 || confirmationReason.trim().length < 10
 }
 onClick={confirmDraft}
 >
 {confirmedReadOnly ? "已启用" : "确认字段映射"}
 </button>
 </footer>
 {confirmedRevision && (
 <p className="monitoring-mapping-success">
 <Check size={15} />
 正式映射已生成，后续批次将继续保留该版本的来源与修订记录。
 </p>
 )}
 </div>
 )}

 {message && <p className="monitoring-mapping-message">{message}</p>}
 {error && <p className="monitoring-mapping-error">{error}</p>}
 </section>
 );
}

.monitoring-rule-template-compact,
.monitoring-rule-template-ready,
.monitoring-rule-template-manual,
.monitoring-rule-template-error,
.monitoring-rule-template-compiled {
 min-height: 38px;
 display: flex;
 align-items: center;
 gap: 8px;
 padding: 8px 10px;
 border-left: 3px solid #7d9586;
 background: #f6f9f7;
 color: var(--text-secondary);
 font-size: 11px;
 line-height: 1.5;
}

.monitoring-rule-template-compact svg {
 flex: 0 0 auto;
 animation: monitoring-spin 900ms linear infinite;
}

.monitoring-rule-template-ready {
 justify-content: space-between;
 gap: 12px;
}

.monitoring-rule-template-ready button,
.monitoring-rule-template-actions button {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 5px;
 padding: 4px 9px;
 border: 1px solid #a8b9af;
 border-radius: 4px;
 background: #fff;
 color: #385345;
 font-size: 11px;
 font-weight: 600;
 white-space: nowrap;
}

.monitoring-rule-template-ready button:hover,
.monitoring-rule-template-actions button:hover {
 border-color: #7d9586;
 background: #f0f6f2;
}

.monitoring-rule-template-ready button:disabled,
.monitoring-rule-template-actions button:disabled {
 cursor: not-allowed;
 opacity: 0.55;
}

.monitoring-rule-template-manual {
 border-left-color: #c49047;
 background: #fffaf2;
 color: #765324;
}

.monitoring-rule-template-error {
 border-left-color: var(--danger);
 background: #fff5f4;
 color: #91362f;
}

.monitoring-rule-template-compiled {
 border-left-color: #5d9070;
 background: var(--success-bg);
 color: #285f3d;
}

.monitoring-rule-template-compiled button {
 flex: 0 0 auto;
 min-height: 28px;
 padding: 3px 9px;
 border: 1px solid #82ad90;
 border-radius: 4px;
 background: #fff;
 color: #25633b;
 font-size: 11px;
 font-weight: 600;
 white-space: nowrap;
}

.monitoring-rule-template-compiled button:hover {
 background: #eef6f0;
}

.monitoring-rule-template-compiled > div {
 display: grid;
 gap: 1px;
}

.monitoring-rule-template-compiled strong {
 font-size: 12px;
}

.monitoring-rule-template-compiled span {
 color: #557362;
 font-size: 10px;
}

.monitoring-rule-template-review {
 display: grid;
 gap: 8px;
 padding-top: 3px;
 border-top: 1px solid var(--soft-line);
}

.monitoring-rule-template-review > header {
 min-height: 30px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
}

.monitoring-rule-template-review > header strong {
 font-size: 12px;
}

.monitoring-rule-template-review > header span {
 color: var(--muted);
 font-size: 10px;
}

.monitoring-rule-template-list {
 display: grid;
 gap: 9px;
}

.monitoring-rule-template-candidate {
 display: grid;
 gap: 8px;
 padding: 10px;
 border: 1px solid #d7e0da;
 border-left: 3px solid #6f8979;
 border-radius: 4px;
 background: #fff;
}

.monitoring-rule-template-candidate > header {
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 align-items: center;
 gap: 8px;
}

.monitoring-rule-template-candidate > header span {
 padding: 2px 5px;
 border: 1px solid #e2c69f;
 border-radius: 3px;
 background: #fff8ee;
 color: #9b5a1f;
 font-size: 10px;
}

.monitoring-rule-template-candidate > header strong {
 min-width: 0;
 font-size: 12px;
}

.monitoring-rule-template-confidence {
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 align-items: baseline;
 gap: 4px 8px;
 padding: 7px 9px;
 border-left: 3px solid #7d9586;
 background: #f6f9f7;
 color: #385345;
 font-size: 10px;
 line-height: 1.45;
}

.monitoring-rule-template-confidence > span {
 color: var(--muted);
}

.monitoring-rule-template-confidence.low {
 border-left-color: #c49047;
 background: #fffaf2;
 color: #765324;
}

.monitoring-rule-template-confidence p {
 grid-column: 1 / -1;
 margin: 0;
 color: #765324;
}

.monitoring-rule-template-candidate > p {
 margin: 0;
 color: var(--text-secondary);
 font-size: 12px;
 line-height: 1.6;
}

.monitoring-rule-template-candidate dl {
 display: grid;
 gap: 0;
 margin: 0;
 border-top: 1px solid var(--soft-line);
}

.monitoring-rule-template-candidate dl > div {
 display: grid;
 grid-template-columns: 76px minmax(0, 1fr);
 gap: 10px;
 padding: 6px 0;
 border-bottom: 1px solid var(--soft-line);
}

.monitoring-rule-template-candidate dt {
 color: var(--muted);
 font-size: 10px;
}

.monitoring-rule-template-candidate dd {
 margin: 0;
 color: var(--text-secondary);
 font-size: 11px;
 line-height: 1.55;
}

.monitoring-rule-template-tradeoffs {
 display: grid;
 gap: 2px;
 margin: 0;
 padding: 0;
 list-style: none;
}

.monitoring-rule-template-tradeoffs li::before {
 content: "·";
 margin-right: 5px;
 color: #d66f19;
}

.monitoring-rule-template-fields {
 display: flex;
 flex-wrap: wrap;
 gap: 5px;
}

.monitoring-rule-template-fields > span {
 display: inline-grid;
 gap: 1px;
 padding: 3px 6px;
 border: 1px solid #d8dfdb;
 border-radius: 3px;
 background: #f8faf9;
 color: #385345;
 font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
 font-size: 10px;
}

.monitoring-rule-template-fields small {
 color: var(--muted);
 font-family: inherit;
 font-size: 9px;
}

.monitoring-rule-template-candidate blockquote {
 display: grid;
 gap: 5px;
 margin: 0;
 padding: 8px 10px;
 border-left: 3px solid #d66f19;
 background: #fffaf4;
}

.monitoring-rule-template-candidate blockquote strong {
 color: #70441f;
 font-size: 10px;
}

.monitoring-rule-template-candidate blockquote p {
 margin: 0;
 color: var(--text-secondary);
 font-size: 12px;
 line-height: 1.6;
}

.monitoring-rule-template-candidate blockquote small {
 color: var(--muted);
 font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
 font-size: 9px;
 overflow-wrap: anywhere;
}

.monitoring-rule-template-actions {
 display: flex;
 align-items: center;
 justify-content: flex-end;
 gap: 7px;
}

.monitoring-rule-template-actions-wrap {
 display: grid;
 gap: 7px;
}

.monitoring-rule-template-confirmation {
 display: grid;
 gap: 4px;
}

.monitoring-rule-template-confirmation > span {
 color: #765324;
 font-size: 10px;
}

.monitoring-rule-template-confirmation textarea {
 width: 100%;
 min-height: 52px;
 padding: 6px 8px;
 border: 1px solid #e0c99f;
 background: #fff;
 color: var(--text-secondary);
 font-size: 12px;
 line-height: 1.45;
 resize: vertical;
}

.monitoring-rule-template-actions .monitoring-rule-template-adopt {
 border-color: #82ad90;
 background: var(--success-bg);
 color: #25633b;
}

.monitoring-rule-template-inline-error {
 margin: 0;
 color: var(--danger);
 font-size: 10px;
 line-height: 1.45;
}

import { useCallback, useEffect, useMemo, useState } from "react";
import {
 BookOpenCheck,
 Check,
 CheckCircle2,
 CircleAlert,
 FileSearch,
 LoaderCircle,
 RefreshCw,
 Sparkles,
 X,
 XCircle,
} from "lucide-react";

import {
 MedicalMonitoringApiError,
 createMedicalMonitoringApi,
} from "./medicalMonitoringApi.mjs";
import {
 PROTOCOL_PREPARATION_STATUS_LABELS,
 acceptedProtocolCandidateFact,
 acceptedProtocolFacts,
 applyProtocolCandidateDecision,
 buildProtocolCandidateDecisionPayload,
 candidateReferencedEvidence,
 candidateConfidenceSummary,
 candidateStructuredSections,
 confirmedProtocolVersions,
 newlyAcceptedProtocolDecisionFact,
 protocolCandidateDecisionLabel,
 protocolFactTypeOptions,
 protocolPreparationCandidateDisplayKey,
 protocolPreparationCandidateIdentityReady,
 protocolPreparationEvidenceDisplayKey,
 protocolPreparationProgress,
 protocolPreparationStartAction,
 protocolPreparationTopicDisplayKey,
 protocolPreparationTopicTone,
 protocolPreparationVersionDisplayKey,
 normalizeProtocolPreparationStatus,
 resolveProtocolCandidateInputRevision,
 shouldPollProtocolPreparation,
} from "./medicalMonitoringProtocolPreparation.mjs";
import {
 applyRuleTemplateRecommendationDecision,
 buildRuleTemplateRecommendationDecisionPayload,
 buildRuleTemplateRecommendationStartPayload,
 ruleTemplateRecommendationViewModel,
 shouldPollRuleTemplateRecommendation,
} from "./medicalMonitoringRuleTemplateRecommendation.mjs";
import {
 MedicalMonitoringRuleTemplateShapeError,
 normalizeRuleTemplateDecisionResponse,
 normalizeRuleTemplateRecommendationPayload,
} from "./medicalMonitoringRuleTemplateView.mjs";
import {
 createMedicalMonitoringProjectRequestScope,
} from "./medicalMonitoringProjectRequestScope.mjs";
import "./MedicalMonitoringProtocolPreparationPanel.css";

const POLL_INTERVAL_MS = 5000;
const DEFAULT_REJECTION_REASON = "该候选不适用于当前方案监查。";

function normalizeStatusOrThrow(payload) {
 const normalized = normalizeProtocolPreparationStatus(payload);
 if (!normalized.ok) throw new Error(normalized.error);
 return normalized.value;
}

function errorText(error, fallback) {
 if (error instanceof MedicalMonitoringApiError) {
 const detail = error.detail?.detail;
 if (detail && typeof detail === "object" && detail.message) {
 return detail.message;
 }
 }
 return error?.message || fallback;
}

function versionOptionLabel(version) {
 return [
 version.source_title,
 version.version_label,
 version.version_date,
 ].filter(Boolean).join(" · ");
}

function TopicStateIcon({ status }) {
 if (status === "running" || status === "queued") {
 return <LoaderCircle className="monitoring-protocol-prep-spinner" size={15} />;
 }
 if (status === "reviewed") return <CheckCircle2 size={15} />;
 if (["failed", "blocked", "stale_input", "cancelled"].includes(status)) {
 return <CircleAlert size={15} />;
 }
 return <BookOpenCheck size={15} />;
}

function RuleTemplateRecommendation({
 state,
 onStart,
 onDecision,
 onOpenRuleRelease,
 aiAvailable = false,
}) {
 const [confirmationReasons, setConfirmationReasons] = useState({});
 const view = ruleTemplateRecommendationViewModel({
 payload: state?.payload,
 loading: state?.loading,
 busy: state?.busy,
 error: state?.error,
 });

 if (view.mode === "loading" || view.mode === "progress") {
 return (
 <div className="monitoring-rule-template-compact" aria-live="polite">
 <LoaderCircle size={14} />
 <span>
 {view.mode === "loading" ? "正在读取规则建议" : view.label}
 </span>
 </div>
 );
 }

 if (view.mode === "ready") {
 return (
 <div className="monitoring-rule-template-ready">
 <span>
 {aiAvailable
 ? "方案事实已确认，可生成与当前字段映射匹配的确定性规则建议。"
 : "方案事实已确认；独立AI当前不可运行，配置后再生成规则建议。"}
 </span>
 <button type="button" disabled={!view.canStart || !aiAvailable} onClick={onStart}>
 <Sparkles size={14} />
 {aiAvailable ? "生成规则建议" : "等待独立AI"}
 </button>
 </div>
 );
 }

 if (view.mode === "manual_review") {
 return (
 <div className="monitoring-rule-template-manual">
 <CircleAlert size={14} />
 <span>{view.message || "该条款暂不适合转换为确定性规则，请人工处理。"}</span>
 </div>
 );
 }

 if (view.mode === "compiled") {
 return (
 <div className="monitoring-rule-template-compiled">
 <CheckCircle2 size={15} />
 <div>
 <strong>采用已完成，规则为医学已确认状态</strong>
 <span>请在「规则发布」中组建规则包，完成影子样本核对、确认与发布。</span>
 </div>
 {onOpenRuleRelease && (
 <button type="button" onClick={onOpenRuleRelease}>
 前往规则发布
 </button>
 )}
 </div>
 );
 }

 if (view.mode === "error") {
 return (
 <div className="monitoring-rule-template-error">
 <CircleAlert size={14} />
 <span>{view.message || "规则建议暂不可用，请刷新当前方案状态后重试。"}</span>
 </div>
 );
 }

 if (view.mode === "reviewed") {
 return (
 <div className="monitoring-rule-template-manual">
 <span>本组规则建议均未采用，可保留为人工核对项。</span>
 </div>
 );
 }

 if (view.mode !== "candidate_review") return null;

 return (
 <section className="monitoring-rule-template-review">
 <header>
 <strong>选择规则建议</strong>
 <span>采用即完成确定性编译</span>
 </header>
 <div className="monitoring-rule-template-list">
 {view.candidates.map((candidate, index) => {
 const decision = state?.candidateDecisions?.[candidate.candidateId];
 const proposed = candidate.status === "proposed";
 const confidenceSummary = candidate.confidenceSummary;
 const lowConfidence = confidenceSummary?.requires_additional_evidence;
 const confirmationReason = confirmationReasons[candidate.candidateId] || "";
 return (
 <article
 key={candidate.candidateId}
 className="monitoring-rule-template-candidate"
 >
 <header>
 <span>建议 {index + 1}</span>
 <strong>{candidate.title}</strong>
 </header>
 <div className={`monitoring-rule-template-confidence${lowConfidence ? " low" : ""}`}>
 <strong>{confidenceSummary?.label || "需人工确认来源"}</strong>
 {confidenceSummary?.confidence_floor !== null
 && confidenceSummary?.confidence_floor !== undefined && (
 <span>
 最低 {Math.round(confidenceSummary.confidence_floor * 100)}%
 （阈值 {Math.round((confidenceSummary.threshold || 0.70) * 100)}%）
 </span>
 )}
 {lowConfidence && (
 <p>采用前请补充来源核对、数据缺口或医学确认理由；系统不会自动采用。</p>
 )}
 </div>
 {candidate.summary && <p>{candidate.summary}</p>}
 <dl>
 {candidate.rationale && (
 <div>
 <dt>推荐理由</dt>
 <dd>{candidate.rationale}</dd>
 </div>
 )}
 {candidate.tradeoffs.length > 0 && (
 <div>
 <dt>取舍</dt>
 <dd>
 <ul className="monitoring-rule-template-tradeoffs">
 {candidate.tradeoffs.map((tradeoff) => (
 <li key={tradeoff}>{tradeoff}</li>
 ))}
 </ul>
 </dd>
 </div>
 )}
 {candidate.requiredDomains.length > 0 && (
 <div>
 <dt>所需数据域</dt>
 <dd>{candidate.requiredDomains.join("、")}</dd>
 </div>
 )}
 {candidate.mappingFields.length > 0 && (
 <div>
 <dt>所需字段</dt>
 <dd className="monitoring-rule-template-fields">
 {candidate.mappingFields.map((field) => (
 <span key={`${field.role}-${field.domain}-${field.field}`}>
 {field.domain}.{field.field}
 {field.role && <small>{field.role}</small>}
 </span>
 ))}
 </dd>
 </div>
 )}
 </dl>
 {candidate.sourceText && (
 <blockquote>
 <strong>方案原文</strong>
 <p>{candidate.sourceText}</p>
 {candidate.sourceLocator && <small>{candidate.sourceLocator}</small>}
 </blockquote>
 )}
 {proposed && (
 <div className="monitoring-rule-template-actions-wrap">
 {lowConfidence && (
 <label className="monitoring-rule-template-confirmation">
 <span>低置信度确认说明（必填）</span>
 <textarea
 value={confirmationReason}
 disabled={Boolean(decision?.busy)}
 maxLength={2000}
 rows={2}
 placeholder="写明已核对的来源、数据缺口或医学确认依据"
 onChange={(event) => setConfirmationReasons((current) => ({
 ...current,
 [candidate.candidateId]: event.target.value,
 }))}
 />
 </label>
 )}
 <div className="monitoring-rule-template-actions">
 <button
 className="monitoring-rule-template-adopt"
 type="button"
 disabled={Boolean(decision?.busy) || (lowConfidence && !confirmationReason.trim())}
 onClick={() => onDecision(candidate, "accepted", confirmationReason.trim())}
 >
 {decision?.busy
 ? <LoaderCircle size={14} />
 : <Check size={14} />}
 采用
 </button>
 <button
 type="button"
 disabled={Boolean(decision?.busy)}
 onClick={() => onDecision(candidate, "rejected")}
 >
 <XCircle size={14} />
 不采用
 </button>
 </div>
 </div>
 )}
 {decision?.error && (
 <p className="monitoring-rule-template-inline-error">
 {decision.error}
 </p>
 )}
 </article>
 );
 })}
 </div>
 </section>
 );
}

function CandidateDetail({
 candidate,
 topic,
 decisionState,
 onDecision,
 ruleTemplateState,
 onStartRuleTemplate,
 onRuleTemplateDecision,
 onOpenRuleRelease,
 aiAvailable,
}) {
 const sections = candidateStructuredSections(candidate);
 const referencedEvidence = candidateReferencedEvidence(candidate);
 const factTypeOptions = protocolFactTypeOptions(topic);
 const [factType, setFactType] = useState(
 factTypeOptions.length === 1 ? factTypeOptions[0].value : "",
 );
 const [rejecting, setRejecting] = useState(false);
 const [rejectionReason, setRejectionReason] = useState(
 DEFAULT_REJECTION_REASON,
 );
 const [confirmationReason, setConfirmationReason] = useState("");
 const pending = candidate.status === "proposed";
 const deciding = Boolean(decisionState?.busy);
 const requiresFactType = factTypeOptions.length > 1;
 const confidenceSummary = candidateConfidenceSummary(candidate);
 const lowConfidence = confidenceSummary.requires_additional_evidence;
 const candidateIdentityReady = protocolPreparationCandidateIdentityReady(candidate);
 const acceptDisabled = deciding
 || !candidateIdentityReady
 || (requiresFactType && !factType)
 || (lowConfidence && !confirmationReason.trim());
 const acceptedFact = acceptedProtocolCandidateFact(candidate);

 return (
 <section className="monitoring-protocol-candidate">
 <header>
 <div>
 <strong>{candidate.title || "结构化条款候选"}</strong>
 <span className={candidate.status || "proposed"}>
 {protocolCandidateDecisionLabel(candidate)}
 </span>
 </div>
 </header>

 <div className={`monitoring-protocol-confidence${lowConfidence ? " low" : ""}`}>
 <strong>{confidenceSummary.label}</strong>
 {confidenceSummary.confidence_floor !== null && (
 <span>
 最低 {Math.round(confidenceSummary.confidence_floor * 100)}%
 （阈值 {Math.round(confidenceSummary.threshold * 100)}%）
 </span>
 )}
 {lowConfidence && (
 <p>接受前请补充原文核对、数据缺口或医学确认理由；系统不会自动采用。</p>
 )}
 </div>

 {candidate.text && (
 <div className="monitoring-protocol-candidate-text">
 <span>条款正文</span>
 <p>{candidate.text}</p>
 </div>
 )}

 {sections.length > 0 && (
 <dl className="monitoring-protocol-structured-fields">
 {sections.map((section) => (
 <div key={section.key}>
 <dt>{section.label}</dt>
 <dd>
 {section.values.map((value) => <p key={value}>{value}</p>)}
 </dd>
 </div>
 ))}
 </dl>
 )}

 {referencedEvidence.length > 0 && (
 <div className="monitoring-protocol-evidence">
 <strong>方案原文</strong>
 {referencedEvidence.map((evidence, index) => (
 <blockquote key={protocolPreparationEvidenceDisplayKey(evidence, index)}>
 <p>{evidence.quote || "未返回可展示的方案原文。"}</p>
 {evidence.locator && <small>{evidence.locator}</small>}
 </blockquote>
 ))}
 </div>
 )}

 {pending && (
 <div className="monitoring-protocol-candidate-decision">
 {!candidateIdentityReady && (
 <p className="monitoring-protocol-candidate-error">
 候选身份缺失或重复，暂不能提交接受/驳回；请回到方案准备状态核对原始候选。
 </p>
 )}
 {requiresFactType && (
 <label>
 <span>归入</span>
 <select
 value={factType}
 disabled={deciding}
 onChange={(event) => setFactType(event.target.value)}
 >
 <option value="">选择条款类型</option>
 {factTypeOptions.map((option) => (
 <option key={option.value} value={option.value}>
 {option.label}
 </option>
 ))}
 </select>
 </label>
 )}

 {lowConfidence && (
 <label className="monitoring-protocol-confidence-confirmation">
 <span>低置信度确认说明（必填）</span>
 <textarea
 value={confirmationReason}
 disabled={deciding}
 maxLength={2000}
 rows={2}
 placeholder="写明已核对的方案原文、数据缺口或医学确认依据"
 onChange={(event) => setConfirmationReason(event.target.value)}
 />
 </label>
 )}

 {!rejecting ? (
 <div className="monitoring-protocol-candidate-actions">
 <button
 className="monitoring-protocol-candidate-accept"
 type="button"
 disabled={acceptDisabled}
 onClick={() => onDecision({
 decision: "accepted",
 factType,
 reason: lowConfidence ? confirmationReason.trim() : "",
 })}
 >
 {deciding ? <LoaderCircle size={14} /> : <Check size={14} />}
 接受
 </button>
 <button
 className="monitoring-protocol-candidate-reject"
 type="button"
 disabled={deciding || !candidateIdentityReady}
 onClick={() => setRejecting(true)}
 >
 <XCircle size={14} />
 驳回
 </button>
 </div>
 ) : (
 <div className="monitoring-protocol-rejection">
 <label>
 <span>驳回理由</span>
 <input
 value={rejectionReason}
 disabled={deciding}
 maxLength={2000}
 onChange={(event) => setRejectionReason(event.target.value)}
 />
 </label>
 <div>
 <button
 type="button"
 disabled={deciding || !candidateIdentityReady}
 onClick={() => setRejecting(false)}
 >
 取消
 </button>
 <button
 className="monitoring-protocol-candidate-reject"
 type="button"
 disabled={deciding || !candidateIdentityReady}
 onClick={() => onDecision({
 decision: "rejected",
 reason: rejectionReason || DEFAULT_REJECTION_REASON,
 })}
 >
 {deciding
 ? <LoaderCircle size={14} />
 : <XCircle size={14} />}
 确认驳回
 </button>
 </div>
 </div>
 )}

 {decisionState?.error && (
 <p className="monitoring-protocol-candidate-error">
 {decisionState.error}
 </p>
 )}
 </div>
 )}

 {acceptedFact && (
 <RuleTemplateRecommendation
 state={ruleTemplateState}
 onStart={() => onStartRuleTemplate(acceptedFact)}
 onDecision={(ruleCandidate, decision, reason) => (
 onRuleTemplateDecision(acceptedFact, ruleCandidate, decision, reason)
 )}
 onOpenRuleRelease={onOpenRuleRelease}
 aiAvailable={aiAvailable}
 />
 )}
 </section>
 );
}

export default function MedicalMonitoringProtocolPreparationPanel(props) {
 return (
 <MedicalMonitoringProtocolPreparationPanelForProject
 key={props.projectId}
 {...props}
 />
 );
}

function MedicalMonitoringProtocolPreparationPanelForProject({
 projectId,
 aiStatus = {},
 onClose,
 onOpenRuleRelease,
}) {
 const api = useMemo(() => createMedicalMonitoringApi(), []);
 const requestScope = useMemo(
 () => createMedicalMonitoringProjectRequestScope(projectId),
 [projectId],
 );
 const [versions, setVersions] = useState([]);
 const [selectedVersionId, setSelectedVersionId] = useState("");
 const [status, setStatus] = useState(null);
 const [loadingVersions, setLoadingVersions] = useState(true);
 const [loadingStatus, setLoadingStatus] = useState(false);
 const [starting, setStarting] = useState(false);
 const [pollStopped, setPollStopped] = useState(false);
 const [error, setError] = useState("");
 const [candidateDecisions, setCandidateDecisions] = useState({});
 const [ruleTemplateStates, setRuleTemplateStates] = useState({});
 const independentAiReady = aiStatus?.semantic_ai_tasks_enabled === true;

 useEffect(() => {
 requestScope.activate();
 return () => requestScope.dispose();
 }, [requestScope]);

 useEffect(() => {
 const request = requestScope.begin("protocol-versions");
 setVersions([]);
 setSelectedVersionId("");
 setStatus(null);
 setCandidateDecisions({});
 setRuleTemplateStates({});
 setLoadingVersions(true);
 setError("");
 api.listProtocolVersions(projectId, { signal: request.signal })
 .then((payload) => {
 if (!requestScope.isCurrent(request)) return;
 const confirmed = confirmedProtocolVersions(payload);
 setVersions(confirmed);
 setSelectedVersionId((current) => confirmed.some(
 (version) => version.protocol_version_id === current && version.displayIdentityState === "ready",
 ) ? current : confirmed.find((version) => version.displayIdentityState === "ready")?.protocol_version_id || "");
 })
 .catch((nextError) => {
 if (requestScope.isCurrent(request)) {
 setVersions([]);
 setSelectedVersionId("");
 setStatus(null);
 setCandidateDecisions({});
 setRuleTemplateStates({});
 setError(errorText(nextError, "已确认方案版本读取失败"));
 }
 })
 .finally(() => {
 if (requestScope.isCurrent(request)) setLoadingVersions(false);
 requestScope.finish(request);
 });
 return () => requestScope.cancel("protocol-versions");
 }, [api, projectId, requestScope]);

 const readStatus = useCallback(async ({ resumePolling = false } = {}) => {
 if (!selectedVersionId) return null;
 const request = requestScope.begin("protocol-status");
 setLoadingStatus(true);
 setError("");
 if (resumePolling) setPollStopped(false);
 try {
 const payload = await api.getProtocolPreparationStatus(
 projectId,
 selectedVersionId,
 { signal: request.signal },
 );
 if (!requestScope.isCurrent(request)) return null;
 const normalized = normalizeStatusOrThrow(payload);
 setStatus(normalized);
 return normalized;
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return null;
 setStatus(null);
 setCandidateDecisions({});
 setRuleTemplateStates({});
 setPollStopped(true);
 setError(errorText(nextError, "方案规则准备状态读取失败"));
 return null;
 } finally {
 if (requestScope.isCurrent(request)) setLoadingStatus(false);
 requestScope.finish(request);
 }
 }, [api, projectId, requestScope, selectedVersionId]);

 useEffect(() => {
 if (!selectedVersionId) {
 requestScope.cancel("protocol-status");
 setStatus(null);
 setLoadingStatus(false);
 return undefined;
 }
 setStatus(null);
 setCandidateDecisions({});
 setRuleTemplateStates({});
 setPollStopped(false);
 readStatus().catch(() => {});
 return () => requestScope.cancel("protocol-status");
 }, [readStatus, requestScope, selectedVersionId]);

 useEffect(() => {
 if (
 !selectedVersionId
 || !status
 || pollStopped
 || !shouldPollProtocolPreparation(status)
 ) {
 return undefined;
 }
 const timer = window.setTimeout(() => {
 readStatus().catch(() => {});
 }, POLL_INTERVAL_MS);
 return () => window.clearTimeout(timer);
 }, [pollStopped, readStatus, selectedVersionId, status]);

 const progress = protocolPreparationProgress(status);
 const acceptedFactItems = useMemo(
 () => acceptedProtocolFacts(status),
 [status],
 );
 const acceptedFactKey = acceptedFactItems
 .map(({ fact }) => `${fact.fact_revision_id}:v${fact.state_version}`)
 .join("|");
 const hasReadyTopic = (status?.topics || [])
 .some((topic) => topic.status === "ready");
 const startAction = protocolPreparationStartAction(status);
 const canStart = Boolean(
 selectedVersionId
 && status
 && (hasReadyTopic || startAction.available)
 && independentAiReady
 && !starting,
 );

 const startAllTopics = async () => {
 if (!canStart) return;
 const request = requestScope.begin("protocol-start");
 setStarting(true);
 setError("");
 try {
 const payload = await api.startProtocolPreparation(
 projectId,
 selectedVersionId,
 { signal: request.signal },
 );
 if (!requestScope.isCurrent(request)) return;
 setStatus(normalizeStatusOrThrow(payload));
 setPollStopped(false);
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return;
 setError(errorText(nextError, "方案规则准备未能启动"));
 } finally {
 if (requestScope.isCurrent(request)) setStarting(false);
 requestScope.finish(request);
 }
 };

 const updateRuleTemplateState = useCallback((factRevisionId, updater) => {
 setRuleTemplateStates((current) => {
 const previous = current[factRevisionId] || {};
 const next = typeof updater === "function"
 ? updater(previous)
 : { ...previous, ...updater };
 return {
 ...current,
 [factRevisionId]: next,
 };
 });
 }, []);

 const readRuleTemplateStatus = useCallback(async (
 fact,
 { showLoading = false } = {},
 ) => {
 const factRevisionId = fact.fact_revision_id;
 const request = requestScope.begin(
 `rule-template:${factRevisionId}`,
 );
 updateRuleTemplateState(factRevisionId, (current) => ({
 ...current,
 loading: showLoading,
 error: "",
 }));
 try {
 const payload = normalizeRuleTemplateRecommendationPayload(
 await api.getRuleTemplateRecommendationStatus(
 projectId,
 factRevisionId,
 {
 expectedFactStateVersion: fact.state_version,
 signal: request.signal,
 },
 ),
 projectId,
 factRevisionId,
 );
 if (!requestScope.isCurrent(request)) return null;
 updateRuleTemplateState(factRevisionId, (current) => ({
 ...current,
 payload,
 loading: false,
 error: "",
 }));
 return payload;
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return null;
 updateRuleTemplateState(factRevisionId, (current) => ({
 ...current,
 payload: null,
 loading: false,
 error: errorText(nextError, "规则建议状态读取失败"),
 }));
 return null;
 } finally {
 requestScope.finish(request);
 }
 }, [api, projectId, requestScope, updateRuleTemplateState]);

 const startRuleTemplateRecommendation = useCallback(async (fact) => {
 const factRevisionId = fact.fact_revision_id;
 const request = requestScope.begin(
 `rule-template:${factRevisionId}`,
 );
 updateRuleTemplateState(factRevisionId, (current) => ({
 ...current,
 busy: true,
 loading: false,
 error: "",
 }));
 try {
 const payload = normalizeRuleTemplateRecommendationPayload(
 await api.startRuleTemplateRecommendation(
 projectId,
 factRevisionId,
 buildRuleTemplateRecommendationStartPayload(fact),
 { signal: request.signal },
 ),
 projectId,
 factRevisionId,
 );
 if (!requestScope.isCurrent(request)) return null;
 updateRuleTemplateState(factRevisionId, (current) => ({
 ...current,
 payload,
 busy: false,
 error: "",
 }));
 return payload;
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return null;
 updateRuleTemplateState(factRevisionId, (current) => ({
 ...current,
 payload: null,
 busy: false,
 error: errorText(nextError, "规则建议未能启动"),
 }));
 return null;
 } finally {
 requestScope.finish(request);
 }
 }, [api, projectId, requestScope, updateRuleTemplateState]);

 useEffect(() => {
 acceptedFactItems.forEach(({ fact }) => {
 if (ruleTemplateStates[fact.fact_revision_id]) return;
 readRuleTemplateStatus(fact, { showLoading: true });
 });
 // acceptedFactKey is the stable restore boundary; state updates must not
 // repeatedly re-read facts that are already present in this drawer.
 // eslint-disable-next-line react-hooks/exhaustive-deps
 }, [acceptedFactKey, readRuleTemplateStatus]);

 useEffect(() => {
 const pollingFacts = acceptedFactItems
 .map(({ fact }) => fact)
 .filter((fact) => shouldPollRuleTemplateRecommendation(
 ruleTemplateStates[fact.fact_revision_id]?.payload,
 ));
 if (pollingFacts.length === 0) return undefined;
 const timer = window.setTimeout(() => {
 pollingFacts.forEach((fact) => {
 readRuleTemplateStatus(fact).catch(() => {});
 });
 }, POLL_INTERVAL_MS);
 return () => window.clearTimeout(timer);
 }, [
 acceptedFactItems,
 readRuleTemplateStatus,
 ruleTemplateStates,
 ]);

 const decideRuleTemplateRecommendation = async (
 fact,
 candidate,
 decision,
 confirmationReason = "",
 ) => {
 const factRevisionId = fact.fact_revision_id;
 const currentState = ruleTemplateStates[factRevisionId] || {};
 if (currentState.candidateDecisions?.[candidate.candidateId]?.busy) return;
 const request = requestScope.begin(
 `rule-template-decision:${factRevisionId}:${candidate.candidateId}`,
 );
 updateRuleTemplateState(factRevisionId, (current) => ({
 ...current,
 candidateDecisions: {
 ...(current.candidateDecisions || {}),
 [candidate.candidateId]: { busy: true, error: "" },
 },
 }));
 try {
 const { candidateId, payload } =
 buildRuleTemplateRecommendationDecisionPayload({
 decision,
 statusPayload: currentState.payload,
 candidate: {
 candidate_id: candidate.candidateId,
 status: candidate.status,
 },
 fact,
 reason: decision === "rejected"
 ? "当前建议不适用于本项目的医学监查。"
 : confirmationReason,
 });
 const response = normalizeRuleTemplateDecisionResponse(
 await api.decideRuleTemplateRecommendation(
 projectId,
 factRevisionId,
 candidateId,
 payload,
 { signal: request.signal },
 ),
 projectId,
 candidateId,
 );
 if (!requestScope.isCurrent(request)) return;
 updateRuleTemplateState(factRevisionId, (current) => ({
 ...current,
 payload: applyRuleTemplateRecommendationDecision(
 current.payload,
 candidateId,
 response,
 ),
 candidateDecisions: {
 ...(current.candidateDecisions || {}),
 [candidateId]: { busy: false, error: "" },
 },
 }));
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return;
 updateRuleTemplateState(factRevisionId, (current) => ({
 ...current,
 payload: nextError instanceof MedicalMonitoringRuleTemplateShapeError
 ? null
 : current.payload,
 candidateDecisions: {
 ...(current.candidateDecisions || {}),
 [candidate.candidateId]: {
 busy: false,
 error: errorText(nextError, "规则建议决定未能保存"),
 },
 },
 }));
 } finally {
 requestScope.finish(request);
 }
 };

 const decideCandidate = async (
 topic,
 candidate,
 { decision, factType = "", reason = "" },
 ) => {
 if (
 !selectedVersionId
 || candidate?.status !== "proposed"
 || !protocolPreparationCandidateIdentityReady(candidate)
 || candidateDecisions[candidate.candidate_id]?.busy
 ) {
 return;
 }
 const candidateId = candidate.candidate_id;
 const request = requestScope.begin(
 `protocol-candidate-decision:${candidateId}`,
 );
 setCandidateDecisions((current) => ({
 ...current,
 [candidateId]: { busy: true, error: "" },
 }));
 try {
 let jobPayload = null;
 if (!resolveProtocolCandidateInputRevision(topic, candidate, null)) {
 if (!topic.job?.job_id) {
 throw new Error("候选运行信息不可用，请刷新后重试。");
 }
 jobPayload = await api.getMonitoringAiJob(
 projectId,
 topic.job.job_id,
 { signal: request.signal },
 );
 if (!requestScope.isCurrent(request)) return;
 const currentCandidate = (jobPayload?.candidates || [])
 .find((item) => item?.candidate_id === candidateId);
 if (currentCandidate && currentCandidate.status !== "proposed") {
 throw new Error("候选状态已变化，请刷新后查看当前决定。");
 }
 }
 const payload = buildProtocolCandidateDecisionPayload({
 decision,
 topic,
 candidate,
 jobPayload,
 factType,
 reason,
 });
 const response = await api.decideProtocolPreparationCandidate(
 projectId,
 selectedVersionId,
 candidateId,
 payload,
 { signal: request.signal },
 );
 if (!requestScope.isCurrent(request)) return;
 setStatus((current) => applyProtocolCandidateDecision(
 current,
 candidateId,
 response,
 ));
 setCandidateDecisions((current) => ({
 ...current,
 [candidateId]: { busy: false, error: "" },
 }));
 const newlyAcceptedFact = newlyAcceptedProtocolDecisionFact(response);
 if (newlyAcceptedFact) {
 await startRuleTemplateRecommendation(newlyAcceptedFact);
 }
 await readStatus();
 } catch (nextError) {
 if (!requestScope.isCurrent(request)) return;
 setCandidateDecisions((current) => ({
 ...current,
 [candidateId]: {
 busy: false,
 error: errorText(nextError, "候选决定未能保存"),
 },
 }));
 } finally {
 requestScope.finish(request);
 }
 };

 return (
 <div className="monitoring-protocol-prep-host">
 <button
 className="monitoring-protocol-prep-backdrop"
 type="button"
 aria-label="关闭方案监查准备"
 onClick={onClose}
 />
 <aside
 className="monitoring-protocol-prep-drawer"
 role="dialog"
 aria-modal="true"
 aria-label="方案监查准备"
 >
 <header className="monitoring-protocol-prep-head">
 <div>
 <span>项目资料</span>
 <strong>准备方案规则</strong>
 <small>从已确认方案提取监查候选；关闭后任务仍在后台继续。</small>
 </div>
 <button
 className="icon-button"
 type="button"
 title="关闭"
 onClick={onClose}
 >
 <X size={17} />
 </button>
 </header>

 <div className="monitoring-protocol-prep-body">
 <section className="monitoring-protocol-version-row">
 <label htmlFor="monitoring-protocol-version">方案版本</label>
 {loadingVersions ? (
 <span className="monitoring-protocol-loading">
 <LoaderCircle size={15} />
 正在读取
 </span>
 ) : versions.length === 0 ? (
 <p>当前项目尚无已确认且可解析的方案版本。</p>
 ) : versions.length === 1 && versions[0].displayIdentityState === "ready" ? (
 <strong>{versionOptionLabel(versions[0])}</strong>
 ) : versions.length === 1 ? (
 <span className="monitoring-protocol-version-warning" title={versions[0].displayIdentityIssue}>
 {versionOptionLabel(versions[0])} · 身份待核对
 </span>
 ) : (
 <select
 id="monitoring-protocol-version"
 value={selectedVersionId}
 onChange={(event) => {
 setSelectedVersionId(event.target.value);
 setError("");
 }}
 >
 <option value="">选择本次监查适用的方案版本</option>
 {versions.map((version, index) => {
 const ambiguous = version.displayIdentityState !== "ready";
 return (
 <option
 key={version.displayKey || protocolPreparationVersionDisplayKey(version, index)}
 value={version.protocol_version_id || ""}
 disabled={ambiguous}
 >
 {versionOptionLabel(version)}{ambiguous ? " · 身份待核对" : ""}
 </option>
 );
 })}
 </select>
 )}
 </section>

 {selectedVersionId && (
 <section className="monitoring-protocol-prep-summary">
 <div>
 <span>准备进度</span>
 <strong>
 {progress.submitted
 ? `${progress.completed}/${progress.total} 个主题已完成`
 : "方案原文已就绪，可一键准备"}
 </strong>
 </div>
 <div className="monitoring-protocol-prep-actions">
 <button
 className="icon-button"
 type="button"
 title="刷新状态"
 disabled={loadingStatus}
 onClick={() => readStatus({ resumePolling: true })}
 >
 <RefreshCw size={15} />
 </button>
 <button
 className="primary-button"
 type="button"
 disabled={!canStart}
 onClick={startAllTopics}
 >
 {starting ? (
 <LoaderCircle size={15} />
 ) : (
 <Sparkles size={15} />
 )}
 {starting ? "正在提交" : startAction.label}
 </button>
 </div>
 <div
 className="monitoring-protocol-progress"
 role="progressbar"
 aria-valuemin="0"
 aria-valuemax={progress.total || 8}
 aria-valuenow={progress.completed}
 >
 <i style={{ width: `${progress.percent}%` }} />
 </div>
 {progress.candidateCount > 0 && (
 <small>{progress.candidateCount} 条候选等待用户确认</small>
 )}
 </section>
 )}

 {loadingStatus && !status && (
 <p className="monitoring-protocol-loading">
 <LoaderCircle size={15} />
 正在核对方案原文和准备状态
 </p>
 )}

 {error && (
 <div className="monitoring-protocol-prep-error">
 <CircleAlert size={16} />
 <span>{error}</span>
 {selectedVersionId && (
 <button
 type="button"
 onClick={() => readStatus({ resumePolling: true })}
 >
 重新读取
 </button>
 )}
 </div>
 )}

 {status?.topics?.length > 0 && (
 <section className="monitoring-protocol-topic-list" aria-label="方案监查主题">
 {status.topics.map((topic, topicIndex) => (
 <details key={protocolPreparationTopicDisplayKey(topic, topicIndex)}>
 <summary>
 <TopicStateIcon status={topic.status} />
 <strong>{topic.label}</strong>
 {topic.candidates?.length > 0 && (
 <span>{topic.candidates.length} 条候选</span>
 )}
 <em className={protocolPreparationTopicTone(topic.status)}>
 {PROTOCOL_PREPARATION_STATUS_LABELS[topic.status]
 || topic.status}
 </em>
 </summary>
 <div className="monitoring-protocol-topic-detail">
 {topic.data_gap && <p>{topic.data_gap}</p>}
 {topic.status === "ready" && (
 <p>
 {independentAiReady
 ? "已找到相关方案原文，启动后将生成结构化监查候选。"
 : "已找到相关方案原文；独立AI当前不可运行，配置后再生成语义候选。"}
 </p>
 )}
 {["queued", "running"].includes(topic.status) && (
 <p>
 {independentAiReady
 ? "独立AI正在分析相关方案原文，无需停留在当前页面。"
 : "独立AI当前不可运行；队列/运行状态不等于已生成语义候选，请配置后再确认。"}
 </p>
 )}
 {(topic.candidates || []).map((candidate, candidateIndex) => (
 <CandidateDetail
 key={protocolPreparationCandidateDisplayKey(candidate, candidateIndex)}
 candidate={candidate}
 topic={topic}
 decisionState={
 candidateDecisions[candidate.candidate_id]
 }
 onDecision={(nextDecision) => decideCandidate(
 topic,
 candidate,
 nextDecision,
 )}
 ruleTemplateState={
 acceptedProtocolCandidateFact(candidate)
 ? ruleTemplateStates[
 candidate.fact.fact_revision_id
 ]
 : null
 }
 onStartRuleTemplate={startRuleTemplateRecommendation}
 onRuleTemplateDecision={
 decideRuleTemplateRecommendation
 }
 onOpenRuleRelease={onOpenRuleRelease}
 aiAvailable={independentAiReady}
 />
 ))}
 {["failed", "blocked", "stale_input", "cancelled"].includes(topic.status)
 && (
 <p>
 {topic.job?.failure_message
 || "该主题需要重新核对方案来源或运行状态。"}
 </p>
 )}
 </div>
 </details>
 ))}
 </section>
 )}

 {!selectedVersionId && versions.length > 1 && (
 <div className="monitoring-protocol-prep-empty">
 <FileSearch size={22} />
 <p>请选择本次医学监查适用的已确认方案版本。</p>
 </div>
 )}
 </div>

 <footer className="monitoring-protocol-prep-foot">
 <span>
 采用规则建议即为医学决定；后续在「规则发布」抽屉完成影子样本核对、确认与发布。
 </span>
 </footer>
 </aside>
 </div>
 );
}

import { useEffect, useMemo, useRef, useState } from "react";
import {
 ArrowDownUp,
 ChevronLeft,
 ChevronRight,
 Download,
 Filter,
 RefreshCw,
 RotateCcw,
 X,
} from "lucide-react";
import {
 activeRiskChecklistFilters,
 DEFAULT_RISK_CHECKLIST_QUERY,
 normalizeRiskChecklistQuery,
 resetRiskChecklistForQueryChange,
 RISK_CHECKLIST_COLUMNS,
} from "./medicalMonitoringChecklistState.mjs";
import {
 riskChecklistCategoryTags,
 riskEvidenceCoverageMessage,
 riskEvidenceCoverageSummary,
 riskEvidenceLineageMessage,
 riskEvidenceLineageSummary,
 riskRowEvidenceBadge,
 riskDispositionStatusLabel,
 medicalMonitoringRiskDisplayKey,
 severityLabel,
} from "./medicalMonitoringModels.mjs";

const DISPOSITION_OPTIONS = [
 "pending_review",
 "reviewed",
 "query_draft",
 "submitted_for_approval",
 "explained_no_external_action",
 "data_correction",
 "follow_up",
 "pd_update",
 "safety_pv_collaboration",
 "continue_observation",
 "duplicate_not_applicable",
];

function severityTone(severity) {
 if (severity === "critical") return "danger";
 if (severity === "high" || severity === "medium") return "warning";
 return "neutral";
}

function filterValueLabel(filter, taxonomyByCode) {
 if (filter.key === "severity") return severityLabel(filter.value);
 if (filter.key === "riskCategoryCode") {
 return taxonomyByCode.get(filter.value)?.label || "其他医学复核";
 }
 if (filter.key === "dispositionStatus") {
 return riskDispositionStatusLabel(filter.value);
 }
 return filter.value;
}

function riskRowAccessibleLabel(risk) {
 const categories = riskChecklistCategoryTags(risk).join("、");
 const disposition = riskDispositionStatusLabel(
 risk.dispositionState || risk.disposition_state || risk.status,
 );
 return [
 risk.subject ? `受试者 ${risk.subject}` : "受试者未提供",
 risk.site ? `中心 ${risk.site}` : "中心未提供",
 `级别 ${severityLabel(risk.severity) || "未提供"}`,
 categories ? `类别 ${categories}` : "",
 risk.title || "风险标题未提供",
 `当前处置 ${disposition}`,
 risk.identityAmbiguous ? "风险身份重复，仅可读，暂不可定位" : "",
 risk.unread ? "未读" : "",
 ].filter(Boolean).join("，");
}

function taxonomyCategoryRows(taxonomy) {
 return Array.isArray(taxonomy?.categories)
 ? taxonomy.categories.filter((item) => item && typeof item === "object" && !Array.isArray(item))
 : [];
}

function FilterControl({ column, value, taxonomy, onChange }) {
 if (column.kind === "severity") {
 return (
 <select value={value} onChange={(event) => onChange(event.target.value)} autoFocus>
 <option value="">全部级别</option>
 <option value="critical">紧急</option>
 <option value="high">高</option>
 <option value="medium">中</option>
 <option value="low">低</option>
 </select>
 );
 }
 if (column.kind === "category") {
 return (
 <select value={value} onChange={(event) => onChange(event.target.value)} autoFocus>
 <option value="">全部类别</option>
 {taxonomyCategoryRows(taxonomy).map((category) => (
 <option value={category.code} key={category.code}>{category.label}</option>
 ))}
 </select>
 );
 }
 if (column.kind === "disposition") {
 return (
 <select value={value} onChange={(event) => onChange(event.target.value)} autoFocus>
 <option value="">全部处置</option>
 {DISPOSITION_OPTIONS.map((status) => (
 <option value={status} key={status}>{riskDispositionStatusLabel(status)}</option>
 ))}
 </select>
 );
 }
 return (
 <input
 type={column.kind === "date" ? "date" : "text"}
 value={value}
 onChange={(event) => onChange(event.target.value)}
 placeholder={column.kind === "date" ? "YYYY-MM-DD" : `输入${column.label}`}
 autoFocus
 />
 );
}

export function MedicalMonitoringRiskChecklist({
 rows = [],
 selectedRiskId = "",
 onSelect,
 query = DEFAULT_RISK_CHECKLIST_QUERY,
 onQueryChange,
 taxonomy = null,
 total = null,
 loading = false,
 error = "",
 isCurrentSnapshot = true,
 onRefreshCurrent,
 onRetry,
 onExport,
 exporting = false,
 lockedFilterKeys = [],
}) {
 const normalizedQuery = normalizeRiskChecklistQuery(query);
 const [openFilterKey, setOpenFilterKey] = useState("");
 const [draftValue, setDraftValue] = useState("");
 const filterLayerRef = useRef(null);
 const safeRows = Array.isArray(rows)
 ? rows.filter((row) => row && typeof row === "object" && !Array.isArray(row))
 : [];
 const riskIdentityCounts = new Map();
 safeRows.forEach((risk) => {
 const identity = typeof risk.id === "string" ? risk.id.trim() : "";
 if (identity) riskIdentityCounts.set(identity, (riskIdentityCounts.get(identity) || 0) + 1);
 });
 const displayRows = safeRows.map((risk, sourceIndex) => {
 const identity = typeof risk.id === "string" ? risk.id.trim() : "";
 const duplicate = Boolean(identity && (riskIdentityCounts.get(identity) || 0) > 1);
 return {
 ...risk,
 sourceIndex: Number.isInteger(risk.sourceIndex) ? risk.sourceIndex : sourceIndex,
 identityAmbiguous: risk.identityAmbiguous === true || duplicate,
 identityIssue: risk.identityIssue || (duplicate
 ? "风险身份重复；保留证据但暂不可定位"
 : ""),
 };
 });
 const safeTaxonomyCategories = useMemo(() => taxonomyCategoryRows(taxonomy), [taxonomy]);
 const totalIsKnown = typeof total === "number" && Number.isInteger(total) && total >= 0;
 const safeTotal = totalIsKnown ? total : 0;
 const taxonomyByCode = useMemo(
 () => new Map(safeTaxonomyCategories.map((item) => [item.code, item])),
 [safeTaxonomyCategories],
 );
 const activeFilters = activeRiskChecklistFilters(normalizedQuery);
 const pageCount = Math.max(1, Math.ceil(safeTotal / normalizedQuery.pageSize));
 const hasReportedRowsButNoSafeRows = !loading && !error && safeTotal > 0 && safeRows.length === 0;
 const lineageSummary = riskEvidenceLineageSummary(displayRows);
 const locked = new Set(Array.isArray(lockedFilterKeys) ? lockedFilterKeys : []);
 const interactive = typeof onQueryChange === "function";
 const evidenceCoverage = riskEvidenceCoverageSummary(displayRows);
 const totalLabel = error
 ? "风险数量未读取"
 : loading
 ? "正在读取风险"
 : !totalIsKnown
 ? "风险数量待读取"
 : `共 ${safeTotal} 条`;

 useEffect(() => {
 if (!openFilterKey) return undefined;
 const closeOnOutsideClick = (event) => {
 if (!filterLayerRef.current?.contains(event.target)) setOpenFilterKey("");
 };
 const closeOnEscape = (event) => {
 if (event.key === "Escape") setOpenFilterKey("");
 };
 document.addEventListener("mousedown", closeOnOutsideClick);
 document.addEventListener("keydown", closeOnEscape);
 return () => {
 document.removeEventListener("mousedown", closeOnOutsideClick);
 document.removeEventListener("keydown", closeOnEscape);
 };
 }, [openFilterKey]);

 const updateQuery = (next) => onQueryChange?.(normalizeRiskChecklistQuery(next));
 const applyFilter = (column) => {
 updateQuery(resetRiskChecklistForQueryChange(normalizedQuery, {
 [column.filterKey]: draftValue,
 }));
 setOpenFilterKey("");
 };
 const clearFilter = (filterKey) => {
 updateQuery(resetRiskChecklistForQueryChange(normalizedQuery, {
 [filterKey]: "",
 }));
 };
 const toggleSort = (columnKey) => {
 const direction = normalizedQuery.sortBy === columnKey
 && normalizedQuery.sortDirection === "asc"
 ? "desc"
 : "asc";
 updateQuery(resetRiskChecklistForQueryChange(normalizedQuery, {
 sortBy: columnKey,
 sortDirection: direction,
 }));
 };
 const resetAll = () => updateQuery(DEFAULT_RISK_CHECKLIST_QUERY);
 const hasNonDefaultSort = normalizedQuery.sortBy !== DEFAULT_RISK_CHECKLIST_QUERY.sortBy
 || normalizedQuery.sortDirection !== DEFAULT_RISK_CHECKLIST_QUERY.sortDirection;

 return (
 <div className="risk-checklist-table" role="table" aria-label="项目医学风险Checklist">
 <div className="risk-checklist-column-state">
 <span>
 {totalLabel}
 {activeFilters.length ? ` · 已筛选 ${activeFilters.length} 项` : ""}
 </span>
 {(typeof onExport === "function" || interactive) && (
 <div className="risk-checklist-actions">
 {typeof onExport === "function" && (
 <button
 type="button"
 className="icon-button"
 disabled={loading || exporting}
 aria-label="导出当前筛选风险及证据"
 title={exporting ? "正在生成风险及证据导出包" : "导出当前筛选风险及证据"}
 onClick={onExport}
 >
 <Download size={15} />
 </button>
 )}
 {interactive && (
 <button
 className="icon-text-button"
 disabled={!activeFilters.length && !hasNonDefaultSort}
 title="清除筛选并恢复默认排序"
 onClick={resetAll}
 >
 <RotateCcw size={14} />重置
 </button>
 )}
 </div>
 )}
 </div>
 {lineageSummary.status !== "empty" && (
 <div className="risk-checklist-column-state" role="status" aria-label="风险来源绑定状态">
 <span>{riskEvidenceLineageMessage(lineageSummary)}</span>
 </div>
 )}
 {evidenceCoverage.status !== "empty" && (
 <div className="risk-checklist-column-state" role="status" aria-label="当前页证据覆盖状态">
 <span>{riskEvidenceCoverageMessage(evidenceCoverage)}</span>
 </div>
 )}
 {interactive && activeFilters.length > 0 && (
 <div className="risk-checklist-filter-chips" aria-label="已应用筛选">
 {activeFilters.map((filter) => (
 <button
 type="button"
 key={filter.key}
 onClick={() => clearFilter(filter.key)}
 title={`清除${filter.label}筛选`}
 >
 <span>{filter.label}</span>
 <strong>{filterValueLabel(filter, taxonomyByCode)}</strong>
 <X size={12} />
 </button>
 ))}
 <button type="button" className="clear-all" onClick={resetAll}>清除全部</button>
 </div>
 )}
 {!isCurrentSnapshot && (
 <div className="risk-checklist-stale" role="status">
 <span>当前查看的是较早快照，分页内容仍保持一致。</span>
 <button type="button" onClick={() => onRefreshCurrent?.()}><RefreshCw size={13} />查看最新</button>
 </div>
 )}
 {error && (
 <div className="risk-checklist-error" role="alert">
 <span>{error}</span>
 {typeof onRetry === "function" && (
 <button type="button" onClick={onRetry} disabled={loading}>
 <RefreshCw size={13} />重试读取
 </button>
 )}
 </div>
 )}
 <div className="risk-checklist-header" role="row" ref={filterLayerRef}>
 {RISK_CHECKLIST_COLUMNS.map((column) => {
 const filterActive = Boolean(normalizedQuery[column.filterKey]);
 const filterLocked = locked.has(column.filterKey);
 return (
 <div className="risk-checklist-header-cell" role="columnheader" key={column.key}>
 <button
 type="button"
 className={`risk-checklist-sort ${normalizedQuery.sortBy === column.key ? "active" : ""}`}
 aria-sort={normalizedQuery.sortBy === column.key
 ? normalizedQuery.sortDirection === "asc" ? "ascending" : "descending"
 : "none"}
 onClick={() => toggleSort(column.key)}
 title={`按${column.label}排序`}
 disabled={!interactive}
 >
 <span>{column.label}</span><ArrowDownUp size={13} />
 </button>
 {interactive && (
 <button
 type="button"
 className={`risk-checklist-filter-trigger ${filterActive ? "active" : ""}`}
 aria-label={`筛选${column.label}`}
 title={filterLocked ? `当前范围已限定${column.label}` : `筛选${column.label}`}
 disabled={filterLocked}
 onClick={() => {
 setOpenFilterKey((current) => current === column.key ? "" : column.key);
 setDraftValue(normalizedQuery[column.filterKey] || "");
 }}
 >
 <Filter size={13} />
 </button>
 )}
 {openFilterKey === column.key && (
 <div className="risk-checklist-filter-popover">
 <strong>{column.label}</strong>
 <FilterControl
 column={column}
 value={draftValue}
 taxonomy={taxonomy}
 onChange={setDraftValue}
 />
 <div>
 <button
 type="button"
 onClick={() => {
 setDraftValue("");
 updateQuery(resetRiskChecklistForQueryChange(normalizedQuery, {
 [column.filterKey]: "",
 }));
 setOpenFilterKey("");
 }}
 >
 清除
 </button>
 <button type="button" className="primary" onClick={() => applyFilter(column)}>
 应用
 </button>
 </div>
 </div>
 )}
 </div>
 );
 })}
 </div>
 <div className="risk-checklist-body" aria-busy={loading}>
 {loading && safeRows.length === 0
 ? Array.from({ length: 6 }, (_, index) => (
 <div className="risk-checklist-row skeleton" role="row" key={`loading-${index}`}>
 {RISK_CHECKLIST_COLUMNS.map((column) => (
 <span role="cell" key={column.key}><i /></span>
 ))}
 </div>
 ))
 : displayRows.map((risk, index) => {
 const selectable = typeof onSelect === "function" && risk.identityAmbiguous !== true;
 return (
 <div
 className={`risk-checklist-row ${selectedRiskId === risk.id && !risk.identityAmbiguous ? "selected" : ""}`}
 key={medicalMonitoringRiskDisplayKey(risk, risk.sourceIndex ?? index)}
 role="row"
 tabIndex={selectable ? 0 : -1}
 aria-selected={selectedRiskId === risk.id && !risk.identityAmbiguous}
 aria-disabled={risk.identityAmbiguous ? "true" : undefined}
 aria-label={riskRowAccessibleLabel(risk)}
 onClick={() => selectable && onSelect?.(risk)}
 onKeyDown={(event) => {
 if (event.key !== "Enter" && event.key !== " ") return;
 event.preventDefault();
 if (selectable) onSelect?.(risk);
 }}
 >
 <span role="cell"><strong>{risk.subject || "-"}</strong></span>
 <span role="cell">{risk.site || "-"}</span>
 <span role="cell">
 <i className={`tag ${severityTone(risk.severity)}`}>{severityLabel(risk.severity)}</i>
 </span>
 <span className="risk-category-cell" role="cell">
 {riskChecklistCategoryTags(risk).map((category) => (
 <i className={`tag ${category === "Safety/PV" ? "warning" : "neutral"}`} key={category}>
 {category}
 </i>
 ))}
 </span>
 <span className="risk-title-cell" role="cell">
 {risk.unread && <i className="risk-unread-dot" aria-label="未读" title="未读" />}
 <strong>{risk.title}</strong>
 <i
 className={`tag ${riskRowEvidenceBadge(risk).status === "bound" ? "success" : riskRowEvidenceBadge(risk).status === "partial" ? "warning" : "danger"}`}
 title={riskRowEvidenceBadge(risk).status === "bound" ? "仅表示有显式定位，不代表医学风险已确认关闭" : "请回到来源证据核对，不能将缺失/异常视为无风险"}
 >
 {riskRowEvidenceBadge(risk).label}
 </i>
 {risk.identityAmbiguous && (
 <i
 className="tag warning"
 title={risk.identityIssue || "风险身份重复；保留证据但暂不可定位"}
 >
 身份重复，仅可读
 </i>
 )}
 </span>
 <span role="cell">
 <i className="tag neutral">
 {riskDispositionStatusLabel(
 risk.dispositionState || risk.disposition_state || risk.status,
 )}
 </i>
 </span>
 <span role="cell">{risk.age}</span>
 </div>
 );
 })}
 {hasReportedRowsButNoSafeRows ? (
 <div className="empty-state risk-checklist-shape-warning" role="alert">
 当前页没有可安全展示的风险记录；接口报告 {safeTotal} 条，不能据此判定无风险。请刷新或检查快照/数据形状。
 </div>
 ) : !loading && !safeRows.length && !error && (
 <div className="empty-state">当前条件下没有风险项；这不等同于项目无风险。</div>
 )}
 </div>
 {interactive && !error && <div className="risk-checklist-pagination" aria-label="风险列表分页">
 <span>第 {Math.min(normalizedQuery.page, pageCount)} / {pageCount} 页</span>
 <label>
 <span>每页</span>
 <select
 value={normalizedQuery.pageSize}
 onChange={(event) => updateQuery(resetRiskChecklistForQueryChange(normalizedQuery, {
 pageSize: Number(event.target.value),
 }))}
 >
 {[25, 50, 100, 200].map((size) => <option key={size} value={size}>{size}</option>)}
 </select>
 </label>
 <button
 type="button"
 className="icon-button"
 title="上一页"
 disabled={loading || normalizedQuery.page <= 1}
 onClick={() => updateQuery({ ...normalizedQuery, page: normalizedQuery.page - 1 })}
 >
 <ChevronLeft size={15} />
 </button>
 <button
 type="button"
 className="icon-button"
 title="下一页"
 disabled={loading || normalizedQuery.page >= pageCount}
 onClick={() => updateQuery({ ...normalizedQuery, page: normalizedQuery.page + 1 })}
 >
 <ChevronRight size={15} />
 </button>
 </div>}
 </div>
 );
}

export default MedicalMonitoringRiskChecklist;

.monitoring-risk-evidence-context {
 display: grid;
 gap: 8px;
 padding: 9px 10px;
 border: 1px solid #d9e4ea;
 background: #fbfdfe;
}

.monitoring-risk-evidence-context.partial { border-color: #ead8a9; background: #fffdf7; }
.monitoring-risk-evidence-context.malformed { border-color: #ecc6b5; background: #fff8f3; }
.monitoring-risk-evidence-context > header { display: flex; align-items: flex-start; gap: 6px; }
.monitoring-risk-evidence-context > header > div { display: grid; gap: 2px; min-width: 0; flex: 1; }
.monitoring-risk-evidence-context header strong { color: #315568; font-size: 12px; }
.monitoring-risk-evidence-context header span { color: #718391; font-size: 10px; line-height: 1.35; }
.monitoring-risk-evidence-context header em { flex: 0 0 auto; padding: 3px 6px; border-radius: 999px; font-size: 10px; font-style: normal; }
.monitoring-risk-evidence-context header em.needs-action { background: #fff0e4; color: #99501a; }
.monitoring-risk-evidence-context header em.unread { background: #eef4ff; color: #42618b; }
.monitoring-risk-evidence-context-grid { display: grid; grid-template-columns: 1.2fr 1.2fr 1fr; gap: 6px; }
.monitoring-risk-evidence-context-grid > div { min-width: 0; display: grid; gap: 3px; padding: 6px 7px; border: 1px solid #e3eaee; background: #fff; }
.monitoring-risk-evidence-context-grid span { color: #71818b; font-size: 9px; }
.monitoring-risk-evidence-context-grid strong { overflow: hidden; color: #315568; font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-risk-evidence-context-states { display: flex; flex-wrap: wrap; gap: 5px; }
.monitoring-risk-context-state { display: inline-flex; align-items: center; gap: 4px; padding: 4px 6px; border-radius: 999px; background: #eef3f6; color: #667d8a; font-size: 10px; }
.monitoring-risk-context-state small { color: inherit; font-size: 9px; opacity: .78; }
.monitoring-risk-context-state.state-bound { background: #e8f6ed; color: #2f7049; }
.monitoring-risk-context-state.state-reference_only, .monitoring-risk-context-state.state-batch_only { background: #fff6df; color: #8b641b; }
.monitoring-risk-context-state.state-missing, .monitoring-risk-context-state.state-malformed { background: #fff0ec; color: #a14938; }
.monitoring-risk-context-state.safety { background: #f1ecff; color: #634e93; }
.monitoring-risk-evidence-context-warning { display: flex; align-items: flex-start; gap: 5px; margin: 0; color: #8e5337; font-size: 10px; line-height: 1.4; }
.monitoring-risk-evidence-context-ids { color: #8a989f; font-size: 9px; line-height: 1.35; overflow-wrap: anywhere; }

@media (max-width: 720px) {
 .monitoring-risk-evidence-context-grid { grid-template-columns: 1fr; }
}


import { AlertTriangle, CheckCircle2, CircleHelp, Link2, ShieldAlert } from "lucide-react";

import {
 normalizeMedicalMonitoringRiskEvidenceContext,
 riskEvidenceContextLineageLabel,
 riskEvidenceContextStateLabel,
} from "./medicalMonitoringRiskEvidenceContext.mjs";
import { riskDispositionStatusLabel, severityLabel } from "./medicalMonitoringModels.mjs";
import "./MedicalMonitoringRiskEvidenceContext.css";

function display(value, fallback = "待核对") {
 return value || fallback;
}

function EvidenceStateIcon({ state }) {
 if (state === "bound") return <CheckCircle2 size={13} aria-hidden="true" />;
 if (state === "malformed") return <ShieldAlert size={13} aria-hidden="true" />;
 return <CircleHelp size={13} aria-hidden="true" />;
}

export default function MedicalMonitoringRiskEvidenceContext({ risk }) {
 const view = normalizeMedicalMonitoringRiskEvidenceContext(risk);
 if (view.status === "malformed" || !view.value) {
 return (
 <section className="monitoring-risk-evidence-context malformed" aria-label="风险上下文">
 <AlertTriangle size={14} aria-hidden="true" />
 <span>风险上下文格式异常；暂不展示身份与证据摘要，请回到风险清单核对。</span>
 </section>
 );
 }

 const { value } = view;
 const evidenceClass = `state-${value.evidence.status}`;
 const lineageClass = `state-${value.lineage.status}`;
 return (
 <section className={`monitoring-risk-evidence-context ${view.status}`} aria-label="风险身份与证据摘要">
 <header>
 <div>
 <strong>风险上下文</strong>
 <span>先核对身份、来源链路与证据状态，再进行医学判断或处置。</span>
 </div>
 {value.needsAction === true && <em className="needs-action">需行动</em>}
 {value.unread === true && <em className="unread">未读</em>}
 </header>
 <div className="monitoring-risk-evidence-context-grid">
 <div><span>范围</span><strong>{display(value.scopeLabel)}</strong></div>
 <div><span>受试者 / 中心</span><strong>{display(value.subjectId, "项目层面")} / {display(value.siteId, "未提供")}</strong></div>
 <div><span>风险级别 / 状态</span><strong>{display(severityLabel(value.severity))} / {display(riskDispositionStatusLabel(value.dispositionState || value.status))}</strong></div>
 </div>
 <div className="monitoring-risk-evidence-context-states">
 <span className={`monitoring-risk-context-state ${evidenceClass}`}>
 <EvidenceStateIcon state={value.evidence.status} />
 {riskEvidenceContextStateLabel(value.evidence.status)}
 <small>{value.evidence.locatorCount === null ? "待核对" : `${value.evidence.locatorCount} 条定位`}</small>
 </span>
 <span className={`monitoring-risk-context-state ${lineageClass}`}>
 <Link2 size={13} aria-hidden="true" />
 {riskEvidenceContextLineageLabel(value.lineage.status)}
 <small>{display(value.sourceVersion || value.snapshotId || value.batch)}</small>
 </span>
 {value.safetyPvFlag === true && <span className="monitoring-risk-context-state safety">Safety/PV 标记</span>}
 </div>
 {view.issues.length > 0 && (
 <p className="monitoring-risk-evidence-context-warning" role="alert">
 <AlertTriangle size={13} aria-hidden="true" />
 部分身份/证据字段形状异常；异常字段未补值，也不表示风险已关闭。
 </p>
 )}
 <small className="monitoring-risk-evidence-context-ids">
 实例 {display(value.riskInstanceId)} · 风险键 {display(value.riskKey)} · 快照 {display(value.snapshotId)}
 </small>
 </section>
 );
}


.monitoring-risk-history-trend {
 margin: 0 0 12px;
 padding: 10px 12px;
 border: 1px solid #dce7ef;
 border-radius: 9px;
 background: #f8fbfd;
}

.monitoring-risk-history-trend.empty { color: #7c8d9b; font-size: 11px; }
.monitoring-risk-history-trend header { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.monitoring-risk-history-trend header div { display: grid; gap: 2px; }
.monitoring-risk-history-trend header strong { color: #2c5068; font-size: 12px; }
.monitoring-risk-history-trend header span { color: #718493; font-size: 10px; line-height: 1.4; }
.monitoring-risk-history-trend header em { flex: 0 0 auto; padding: 3px 6px; border-radius: 999px; background: #eef4f8; color: #557389; font-size: 10px; font-style: normal; }
.monitoring-risk-history-trend.warning, .monitoring-risk-history-trend.partial { border-color: #ecd9a6; background: #fffdf6; }
.monitoring-risk-history-trend.malformed { border-color: #efc7b3; background: #fff8f3; }

.monitoring-risk-history-trend-warning { display: flex; align-items: flex-start; gap: 5px; margin: 7px 0 0; color: #8d4f32; font-size: 10px; line-height: 1.4; }
.monitoring-risk-history-trend-track { display: grid; grid-template-columns: repeat(8, minmax(54px, 1fr)); gap: 5px; margin: 10px 0 0; padding: 0; list-style: none; }
.monitoring-risk-history-trend-track li { position: relative; min-width: 0; padding-top: 8px; border-top: 1px solid #cbdbe6; }
.monitoring-risk-history-trend-track li::before { position: absolute; top: -1px; left: 0; width: 100%; height: 1px; background: #cbdbe6; content: ""; }
.monitoring-risk-history-trend-track li.current { border-top-color: #8aaec5; }
.monitoring-risk-history-trend-dot { position: absolute; top: -5px; left: 3px; width: 9px; height: 9px; border: 2px solid #fff; border-radius: 50%; background: #9aabb5; box-shadow: 0 0 0 1px #9aabb5; }
.monitoring-risk-history-trend-dot.danger { background: #c84d3b; box-shadow: 0 0 0 1px #c84d3b; }
.monitoring-risk-history-trend-dot.high { background: #db7b31; box-shadow: 0 0 0 1px #db7b31; }
.monitoring-risk-history-trend-dot.medium { background: #d0a32a; box-shadow: 0 0 0 1px #d0a32a; }
.monitoring-risk-history-trend-dot.low { background: #4c9a70; box-shadow: 0 0 0 1px #4c9a70; }
.monitoring-risk-history-trend-point { display: grid; min-width: 0; gap: 2px; padding-right: 3px; }
.monitoring-risk-history-trend-point strong { overflow: hidden; color: #2c5068; font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-risk-history-trend-point span, .monitoring-risk-history-trend-point small { overflow: hidden; color: #728493; font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }
.monitoring-risk-history-trend-point em { display: inline-flex; align-items: center; gap: 2px; width: max-content; padding: 2px 4px; border-radius: 999px; background: #eef3f6; color: #688093; font-size: 9px; font-style: normal; }
.monitoring-risk-history-trend-point em.direction-up { background: #fff0ec; color: #a13e2d; }
.monitoring-risk-history-trend-point em.direction-down { background: #e8f7ed; color: #2f7049; }
.monitoring-risk-history-trend-more, .monitoring-risk-history-trend-note { display: block; margin-top: 7px; color: #7b8c99; font-size: 9px; line-height: 1.4; }

@media (max-width: 720px) {
 .monitoring-risk-history-trend-track { grid-template-columns: repeat(4, minmax(70px, 1fr)); row-gap: 12px; }
}

import { AlertTriangle, ArrowDown, ArrowUp, Minus, Orbit } from "lucide-react";

import {
 medicalMonitoringRiskSeverityTone,
 medicalMonitoringRiskTrendDirectionLabel,
 normalizeMedicalMonitoringRiskHistoryTrend,
} from "./medicalMonitoringRiskHistoryTrend.mjs";
import "./MedicalMonitoringRiskHistoryTrend.css";

function DirectionIcon({ direction }) {
 if (direction === "up") return <ArrowUp size={12} aria-hidden="true" />;
 if (direction === "down") return <ArrowDown size={12} aria-hidden="true" />;
 if (direction === "steady") return <Minus size={12} aria-hidden="true" />;
 return <Orbit size={12} aria-hidden="true" />;
}

export default function MedicalMonitoringRiskHistoryTrend({ instances = [] }) {
 const view = normalizeMedicalMonitoringRiskHistoryTrend(instances);
 if (view.status === "empty") {
 return <div className="monitoring-risk-history-trend empty">当前风险没有可比较的跨批次实例。</div>;
 }
 return (
 <section className={`monitoring-risk-history-trend ${view.status}`} aria-label="风险跨批次变化趋势">
 <header>
 <div>
 <strong>风险级别与批次变化</strong>
 <span>只显示同一风险实例的显式历史；方向不是临床因果结论，也不表示缺失点等于风险消失。</span>
 {view.points.some((point) => point.displayIdentityState !== "ready") && (
 <span>部分历史点身份待核对；原始记录保留，但暂不能确认单点来源。</span>
 )}
 </div>
 {view.summary && <em>{view.summary.transitionCount} 次级别变化</em>}
 </header>
 {view.status === "malformed" && (
 <p className="monitoring-risk-history-trend-warning" role="alert"><AlertTriangle size={13} /> 历史字段形状异常；异常值未用于计算方向，请回到下方原始历史表核对。</p>
 )}
 <ol className="monitoring-risk-history-trend-track">
 {view.points.slice(-8).map((point) => (
 <li key={point.displayKey} className={point.isCurrent ? "current" : ""}>
 <div className={`monitoring-risk-history-trend-dot ${medicalMonitoringRiskSeverityTone(point.severity)}`} title={point.severityLabel} />
 <div className="monitoring-risk-history-trend-point">
 <strong>{point.severityLabel}</strong>
 <span>{point.batchDelta || "批次变化待核对"}</span>
 <small title={point.displayIdentityIssue || undefined}>
 {point.sourceBatchId || point.snapshotId || "快照标识待核对"}
 {point.displayIdentityState !== "ready" ? ` · ${point.displayIdentityState === "duplicate" ? "身份重复" : "身份待核对"}` : ""}
 </small>
 <em className={`direction-${point.direction}`}><DirectionIcon direction={point.direction} />{medicalMonitoringRiskTrendDirectionLabel(point.direction)}</em>
 </div>
 </li>
 ))}
 </ol>
 {view.points.length > 8 && <small className="monitoring-risk-history-trend-more">趋势条仅显示最近 8 个实例；下方历史表保留完整链路。</small>}
 {view.issues.length > 0 && view.status !== "malformed" && <p className="monitoring-risk-history-trend-note">部分历史字段待核对；系统不会把缺失字段补成稳定趋势。</p>}
 </section>
 );
}

