 font-size: 12px;
 font-weight: 650;
}

.timeline-event-inspector-source {
 display: grid;
 gap: 3px;
 border-top: 1px solid #dce8ee;
 padding-top: 6px;
}

.timeline-event-inspector-source code {
 overflow-wrap: anywhere;
 color: var(--text);
 font-size: 11px;
}

.timeline-event-inspector > p {
 margin: 0;
 line-height: 1.45;
}

@media (max-width: 560px) {
 .profile-domain-coverage-header {
 align-items: flex-start;
 flex-direction: column;
 }

 .profile-domain-coverage-grid {
 grid-template-columns: repeat(2, minmax(0, 1fr));
 }

 .profile-metric-candidate-header,
 .profile-metric-candidate-row {
 align-items: flex-start;
 flex-direction: column;
 }

 .profile-metric-candidate-row > div:last-child {
 justify-items: start;
 text-align: left;
 }

 .metric-point-inspector dl {
 grid-template-columns: minmax(0, 1fr);
 }

 .timeline-event-inspector dl {
 grid-template-columns: minmax(0, 1fr);
 }
}

