function isExplicitZero(value) {
 if (typeof value === "number") return Number.isInteger(value) && value === 0;
 return typeof value === "string" && value.trim() === "0";
}

function nonNegativeInteger(value) {
 return typeof value === "number" && Number.isInteger(value) && value >= 0
 ? value
 : null;
}

function candidateSources({ currentSnapshot, sourceManifest, rawMonitoring }) {
 const roots = [currentSnapshot, sourceManifest, rawMonitoring];
 return roots.flatMap((root) => (
 root && typeof root === "object" && !Array.isArray(root)
 ? [root.assurance_readiness, root.readiness, root]
 : []
 )).filter((value) => value && typeof value === "object" && !Array.isArray(value));
}

function firstCount(sources, keys) {
 for (const source of sources) {
 for (const key of keys) {
 const count = nonNegativeInteger(source[key]);
 if (count !== null) return count;
 }
 }
 return null;
}

function firstArrayCount(sources, keys) {
 for (const source of sources) {
 for (const key of keys) {
 if (Array.isArray(source[key])) return source[key].length;
 }
 }
 return null;
}

/**
 * Build the read-only readiness request from explicit project-bound facts.
 * Missing coverage is preserved as a blocker; it is never guessed as zero.
 */
export function assuranceReadinessInput({
 currentSnapshot,
 sourceManifest,
 rawMonitoring,
 currentIdentity = {},
 task = {},
} = {}) {
 const sources = candidateSources({ currentSnapshot, sourceManifest, rawMonitoring });
 const rollups = sources
 .map((source) => source.rollup)
 .filter((value) => value && typeof value === "object" && !Array.isArray(value));
 const actualSubjects = firstCount(sources, READINESS_COUNT_KEYS.actualSubjects)
 ?? firstArrayCount(rollups, ["subjects", "subject_rollup"]);
 const actualSites = firstCount(sources, READINESS_COUNT_KEYS.actualSites)
 ?? firstArrayCount(rollups, ["sites", "site_rollup"]);
 const plannedSubjects = firstCount(sources, READINESS_COUNT_KEYS.plannedSubjects);
 const plannedSites = firstCount(sources, READINESS_COUNT_KEYS.plannedSites);
 const criticalDomainsCovered = firstCount(sources, READINESS_COUNT_KEYS.criticalDomainsCovered);
 const criticalDomainsExpected = firstCount(sources, READINESS_COUNT_KEYS.criticalDomainsExpected);
 const expectedVersion = nonNegativeInteger(task.version);
 const missingFields = [];
 if (expectedVersion === null || expectedVersion < 1) missingFields.push("expected_version");
 if (actualSubjects === null) missingFields.push("actual_subjects");
 if (actualSites === null) missingFields.push("actual_sites");
 return {
 available: missingFields.length === 0,
 missingFields,
 expected_version: expectedVersion || 0,
 current_identity: currentIdentity && typeof currentIdentity === "object" ? { ...currentIdentity } : {},
 planned_subjects: plannedSubjects ?? 0,
 actual_subjects: actualSubjects ?? 0,
 planned_sites: plannedSites ?? 0,
 actual_sites: actualSites ?? 0,
 critical_domains_covered: criticalDomainsCovered ?? 0,
 critical_domains_expected: criticalDomainsExpected ?? 0,
 };
}

export function assuranceReadinessState({ readiness = null, input = null } = {}) {
 if (!input?.available) {
 return {
 ready: false,
 tone: "warning",
 label: "等待覆盖计数",
 blockingReason: input?.missingFields?.length
 ? `尚未提供可核验字段：${input.missingFields.join("、")}`
 : "尚未形成可核验的 readiness 请求。",
 };
 }
 if (!readiness) {
 return {
 ready: false,
 tone: "warning",
 label: "等待 readiness 结果",
 blockingReason: "服务端尚未返回当前任务的 readiness 结果。",
 };
 }
 const ready = readiness.ready === true;
 return {
 ready,
 tone: ready ? "success" : "danger",
 label: ready ? "覆盖与冻结身份已核验" : "readiness 完成门未通过",
 blockingReason: ready
 ? ""
 : (readiness.gaps?.length ? readiness.gaps.join("；") : "服务端返回未就绪，但未提供具体缺口。"),
 };
}

/** Remove local availability metadata before sending the strict backend request. */
export function assuranceReadinessPayload(input = {}) {
 return Object.fromEntries(
 Object.entries(input).filter(([key]) => key !== "available" && key !== "missingFields"),
 );
}

export function assuranceModeLabel(mode) {
 return MODE_LABELS[mode] || "保障任务";
}

export function assuranceModeMonitoringId(mode) {
 return monitoringModeFromAssuranceMode(mode);
}

export function assuranceModeDescription(mode) {
 const definition = monitoringModeDefinition(assuranceModeMonitoringId(mode));
 return definition
 ? `${definition.label} · ${definition.baseline}`
 : "当前保障任务模式尚未绑定商业运行策略。";
}

export function assuranceStatusLabel(status) {
 return STATUS_LABELS[status] || status || "未知状态";
}

export function assuranceStatusTone(status) {
 return STATUS_TONES[status] || "neutral";
}

export function assuranceAuditActionLabel(action) {
 return AUDIT_ACTION_LABELS[action] || action || "未知审计动作";
}

export function completeFrozenIdentity(identity = {}) {
 return FROZEN_IDENTITY_FIELDS.every((field) => (
 identity[field] !== null
 && identity[field] !== undefined
 && String(identity[field]).trim().length > 0
 ));
}

export function assuranceTaskCreationAllowed(identity = {}, writePermitted = false) {
 return completeFrozenIdentity(identity) && writePermitted === true;
}

export function missingFrozenIdentityFields(identity = {}) {
 return FROZEN_IDENTITY_FIELDS.filter((field) => (
 identity[field] === null
 || identity[field] === undefined
 || !String(identity[field]).trim()
 ));
}

export function assuranceTaskSummary(task = {}) {
 const identity = task.frozen_identity || {};
 return {
 id: String(task.task_id || ""),
 mode: String(task.mode || ""),
 modeLabel: assuranceModeLabel(task.mode),
 status: String(task.status || ""),
 statusLabel: assuranceStatusLabel(task.status),
 statusTone: assuranceStatusTone(task.status),
 version: Number(task.version || 0),
 identityHash: String(task.identity_hash || ""),
 identityReady: completeFrozenIdentity(identity),
 medicalReviewRecorded: task.medical_review_recorded === true,
 proofId: String(task.full_recompute_proof_id || ""),
 owner: String(task.owner || ""),
 lockImpact: String(task.lock_impact || ""),
 updatedAt: String(task.updated_at || ""),
 };
}

function preInspectionEvidenceState(rollup) {
 const projected = projectAssuranceRollup(rollup);
 if (!projected.available) {
 return {
 label: "等待三级汇总",
 tone: "warning",
 ready: false,
 blockingReason: "尚未返回可核验的三级汇总。",
 };
 }

 const blockers = [];
 if (!projected.conservation.ok) {
 blockers.push("项目、中心、个例的风险身份或显式计数不守恒");
 }
 if (projected.trial.closedWithoutEvidenceCount !== 0) {
 blockers.push(
 projected.trial.closedWithoutEvidenceCount === null
 ? "缺少已关闭风险的关闭依据计数"
 : `有 ${projected.trial.closedWithoutEvidenceCount} 项已关闭风险缺少关闭依据`,
 );
 }

 const ready = blockers.length === 0;
 return {
 label: ready ? "三级汇总与关闭依据已核验" : "三级汇总已记录，但完成门未通过",
 tone: ready ? "success" : "danger",
 ready,
 blockingReason: ready ? "" : blockers.join("；"),
 };
}

export function assuranceEvidenceProvenanceState(proof = null) {
 const status = proof && typeof proof === "object"
 ? String(proof.provenance_status || "").trim()
 : "";
 if (ACCEPTED_EVIDENCE_PROVENANCE_STATUSES.has(status)) {
 return {
 status,
 ready: true,
 label: status === ASSURANCE_EVIDENCE_PROVENANCE_STATUSES.SERVER_EVIDENCE_RUN_LEDGER
 ? "服务端 evidence-run ledger 已声明"
 : "签名 evidence manifest 已经服务端全字段重验",
 blockingReason: "",
 };
 }
 if (status === "mixed" || status === "mixed_provenance") {
 return {
 status,
 ready: false,
 label: "证据来源混合",
 blockingReason: "证据来源混合，不能作为全量重算完成证明。",
 };
 }
 return {
 status,
 ready: false,
 label: "证据权威未确认",
 blockingReason: "服务端未声明可接受的证据权威，不能作为全量重算完成证明。",
 };
}

export function assuranceEvidenceState({ task = {}, proof = null, rollup = null } = {}) {
 const summary = assuranceTaskSummary(task);
 if (summary.mode === "pre_lock") {
 const provenance = assuranceEvidenceProvenanceState(proof);
 const ready = Boolean(proof)
 && provenance.ready
 && isExplicitZero(proof.failures)
 && isExplicitZero(proof.skips)
 && proof.subject_reconciliation_ok === true
 && proof.site_reconciliation_ok === true
 && proof.trial_reconciliation_ok === true;
 return {
 label: !proof
 ? "等待全量重算证明"
 : ready
 ? "全量重算证明已核验"
 : provenance.label === "证据权威未确认" || provenance.label === "证据来源混合"
 ? provenance.label
 : "全量重算证明已记录，但完成门未通过",
 tone: ready ? "success" : proof ? "danger" : "warning",
 ready,
 provenanceStatus: provenance.status,
 blockingReason: proof
 ? (provenance.ready ? "全量重算失败、跳过或三级对账未通过。" : provenance.blockingReason)
 : "尚未返回全量重算证明。",
 };
 }
 if (summary.mode === "pre_inspection") {
 return preInspectionEvidenceState(rollup);
 }
 return {
 label: "未识别的保障模式",
 tone: "danger",
 ready: false,
 blockingReason: "当前任务模式无法进入完成门。",
 };
}

/**
 * Describe the server-backed assurance action sequence without granting a
 * client-side bypass. Evidence must exist before medical review, and both
 * evidence plus review/readiness must exist before completion.
 */
export function assuranceActionAvailability({
 task = {},
 principalReady = false,
 authorityWritePermitted = false,
 evidenceReady = false,
 evidenceRecorded = false,
 evidenceBlockingReason = "",
 readinessReady = false,
} = {}) {
 const summary = assuranceTaskSummary({
 ...task,
 task_id: task.task_id || task.id,
 });
 const baseBlockers = [];
 if (!summary.id) baseBlockers.push("未选择保障任务");
 if (!Number.isInteger(summary.version) || summary.version < 1) baseBlockers.push("任务版本不可核验");
 if (!principalReady) baseBlockers.push("服务端认证 principal 未就绪");
 if (!authorityWritePermitted) baseBlockers.push("当前 authority 未允许保障写入");
 if (["completed", "superseded"].includes(summary.status)) baseBlockers.push("任务已结束，不能继续写入");
 const baseReady = baseBlockers.length === 0;
 const evidenceExists = evidenceRecorded === true || evidenceReady === true;
 const evidenceBlocker = evidenceReady
 ? ""
 : evidenceBlockingReason || (evidenceExists ? "已有证据但其权威尚未核验" : "尚未形成可核验的证据结果");
 const reviewBlocker = !evidenceReady
 ? evidenceBlocker
 : summary.medicalReviewRecorded
 ? "医学复核已记录"
 : "等待医学复核确认";
 const completeBlocker = !evidenceReady
 ? evidenceBlocker
 : !summary.medicalReviewRecorded
 ? "医学复核尚未记录"
 : !readinessReady
 ? "readiness 完成门尚未通过"
 : "";
 return {
 baseReady,
 baseBlockers,
 canRecordEvidence: baseReady && !evidenceExists,
 canReview: baseReady && evidenceReady && !summary.medicalReviewRecorded,
 canComplete: baseReady && evidenceReady && summary.medicalReviewRecorded && readinessReady,
 evidenceBlocker: baseReady && !evidenceReady && !evidenceExists
 ? ""
 : (baseBlockers.join("；") || evidenceBlocker),
 reviewBlocker: baseReady && evidenceReady && !summary.medicalReviewRecorded ? "" : (baseBlockers.join("；") || reviewBlocker),
 completeBlocker: baseReady && evidenceReady && summary.medicalReviewRecorded && readinessReady
 ? ""
 : (baseBlockers.join("；") || completeBlocker),
 };
}

export function assuranceTaskList(items = []) {
 const summaries = (Array.isArray(items) ? items : [])
 .map((item, sourceIndex) => ({ ...assuranceTaskSummary(item), sourceIndex }))
 .filter((task) => task.id);
 const identityCounts = new Map();
 summaries.forEach((task) => identityCounts.set(task.id, (identityCounts.get(task.id) || 0) + 1));
 return summaries
 .map((task) => {
 const duplicate = (identityCounts.get(task.id) || 0) > 1;
 return {
 ...task,
 identityState: duplicate ? "duplicate" : "ready",
 identityIssue: duplicate ? "保障任务 task_id 重复；仅可读，暂不可选择" : "",
 };
 })
 .sort((left, right) => (
 String(right.updatedAt).localeCompare(String(left.updatedAt))
 || left.mode.localeCompare(right.mode)
 || left.id.localeCompare(right.id)
 ));
}

/** UI-only key; never becomes the task ID sent to an assurance API. */
export function assuranceTaskDisplayKey(task = {}, index = 0) {
 const identity = String(task.id || task.task_id || "").trim() || "missing";
 const sourceIndex = Number.isInteger(task.sourceIndex) && task.sourceIndex >= 0
 ? task.sourceIndex
 : Number.isInteger(index) && index >= 0 ? index : 0;
 return `assurance-task:${identity}:${sourceIndex}`;
}

import assert from "node:assert/strict";
import {
 ASSURANCE_MODES,
 ASSURANCE_EVIDENCE_PROVENANCE_STATUSES,
 FROZEN_IDENTITY_FIELDS,
 assuranceEvidenceState,
 assuranceEvidenceProvenanceState,
 assuranceActionAvailability,
 assuranceReadinessInput,
 assuranceReadinessPayload,
 assuranceReadinessState,
 assuranceModeLabel,
 assuranceModeDescription,
 assuranceModeMonitoringId,
 assuranceStatusLabel,
 assuranceStatusTone,
 assuranceTaskCreationAllowed,
 assuranceTaskDisplayKey,
 assuranceTaskList,
 completeFrozenIdentity,
 missingFrozenIdentityFields,
} from "./medicalMonitoringAssurance.mjs";
import { createMedicalMonitoringAssuranceApi } from "./medicalMonitoringAssuranceApi.mjs";

let passed = 0;
function check(condition, message) {
 assert.ok(condition, message);
 passed += 1;
}

const identity = Object.fromEntries(FROZEN_IDENTITY_FIELDS.map((field) => [field, `${field}-v1`]));
check(ASSURANCE_MODES.join(",") === "pre_lock,pre_inspection", "declares both P8 assurance modes");
check(completeFrozenIdentity(identity), "accepts a complete frozen identity");
check(!completeFrozenIdentity({ ...identity, risk_snapshot_id: "" }), "rejects an incomplete frozen identity");
check(!assuranceTaskCreationAllowed(identity, false), "keeps task creation blocked without explicit authority write permission");
check(assuranceTaskCreationAllowed(identity, true), "allows task creation only with complete identity and explicit authority permission");
check(missingFrozenIdentityFields({ ...identity, rule_pack_revision: "" }).join(",") === "rule_pack_revision", "reports missing identity fields");
check(assuranceModeLabel("pre_lock") === "锁库前保障", "labels pre-lock mode");
check(assuranceModeLabel("pre_inspection") === "核查前保障", "labels pre-inspection mode");
check(assuranceModeMonitoringId("pre_lock") === "pre_lock_total", "binds pre-lock to the commercial total mode");
check(assuranceModeMonitoringId("pre_inspection") === "post_lock_fixed_total", "binds pre-inspection to the fixed-total mode");
check(assuranceModeDescription("pre_inspection").includes("固定总量"), "surfaces fixed-total semantics for pre-inspection");
check(assuranceStatusLabel("running") === "执行中", "labels running status");
check(assuranceStatusTone("blocked") === "danger", "marks blocked status as dangerous");

const tasks = assuranceTaskList([
 {
 task_id: "task-old",
 mode: "pre_inspection",
 status: "draft",
 version: 1,
 updated_at: "2026-08-01T00:00:00Z",
 },
 {
 task_id: "task-new",
 mode: "pre_lock",
 status: "running",
 version: 2,
 updated_at: "2026-08-02T00:00:00Z",
 frozen_identity: identity,
 medical_review_recorded: true,
 },
]);
check(tasks.length === 2 && tasks[0].id === "task-new", "sorts assurance tasks by latest update");
check(tasks[0].identityReady && tasks[0].medicalReviewRecorded, "preserves identity and medical review state");
const duplicateTasks = assuranceTaskList([
 { task_id: "duplicate-task", mode: "pre_lock", status: "draft", version: 1, updated_at: "2026-08-03T00:00:00Z" },
 { task_id: "duplicate-task", mode: "pre_lock", status: "running", version: 2, updated_at: "2026-08-04T00:00:00Z" },
]);
check(duplicateTasks.every((task) => task.identityState === "duplicate"), "marks duplicate assurance task ids as ambiguous");
check(assuranceTaskDisplayKey(duplicateTasks[0], 0) !== assuranceTaskDisplayKey(duplicateTasks[1], 1), "uses source-index display keys for duplicate assurance tasks");
check(
 assuranceEvidenceState({ task: { mode: "pre_lock" }, proof: { provenance_status: ASSURANCE_EVIDENCE_PROVENANCE_STATUSES.SERVER_EVIDENCE_RUN_LEDGER, failures: 0, skips: 0, subject_reconciliation_ok: true, site_reconciliation_ok: true, trial_reconciliation_ok: true } }).ready,
 "accepts a clean pre-lock proof",
);
check(
 !assuranceEvidenceState({ task: { mode: "pre_lock" }, proof: { provenance_status: ASSURANCE_EVIDENCE_PROVENANCE_STATUSES.SERVER_EVIDENCE_RUN_LEDGER, failures: 1, skips: 0, subject_reconciliation_ok: true, site_reconciliation_ok: true, trial_reconciliation_ok: true } }).ready,
 "blocks a pre-lock proof with failures",
);
check(
 !assuranceEvidenceState({ task: { mode: "pre_lock" }, proof: { provenance_status: ASSURANCE_EVIDENCE_PROVENANCE_STATUSES.SERVER_EVIDENCE_RUN_LEDGER, failures: false, skips: 0, subject_reconciliation_ok: true, site_reconciliation_ok: true, trial_reconciliation_ok: true } }).ready,
 "blocks a pre-lock proof with a boolean failure count",
);
check(
 !assuranceEvidenceState({ task: { mode: "pre_lock" }, proof: { provenance_status: ASSURANCE_EVIDENCE_PROVENANCE_STATUSES.SERVER_EVIDENCE_RUN_LEDGER, failures: 0, skips: "", subject_reconciliation_ok: true, site_reconciliation_ok: true, trial_reconciliation_ok: true } }).ready,
 "blocks a pre-lock proof with a blank skip count",
);
check(
 assuranceEvidenceProvenanceState({ provenance_status: ASSURANCE_EVIDENCE_PROVENANCE_STATUSES.SIGNED_MANIFEST_SERVER_REVALIDATED }).ready,
 "accepts the future signed-manifest authority only after server revalidation is declared",
);
check(
 !assuranceEvidenceState({ task: { mode: "pre_lock" }, proof: { provenance_status: "mixed_provenance", failures: 0, skips: 0, subject_reconciliation_ok: true, site_reconciliation_ok: true, trial_reconciliation_ok: true } }).ready,
 "blocks mixed-provenance proof even when counts and reconciliation are clean",
);
check(
 assuranceEvidenceState({ task: { mode: "pre_lock" }, proof: { failures: 0, skips: 0, subject_reconciliation_ok: true, site_reconciliation_ok: true, trial_reconciliation_ok: true } }).blockingReason.includes("权威"),
 "blocks proof with no declared evidence authority",
);
const cleanPreInspectionRollup = {
 risk_snapshot_id: "snapshot-1",
 subject_rollup: [],
 site_rollup: [],
 trial_rollup: {
 total_risk_count: 0,
 closed_risks_lacking_evidence_count: 0,
 risk_instance_ids: [],
 },
 distributions: {},
 remediation_matrix: [],
 evidence_manifest: [],
 content_sha256: "a".repeat(64),
};
check(
 assuranceEvidenceState({ task: { mode: "pre_inspection" }, rollup: cleanPreInspectionRollup }).ready,
 "accepts a conserved pre-inspection rollup with closure evidence counts",
);
check(
 !assuranceEvidenceState({
 task: { mode: "pre_inspection" },
 rollup: {
 ...cleanPreInspectionRollup,
 trial_rollup: { ...cleanPreInspectionRollup.trial_rollup, total_risk_count: 1, risk_instance_ids: ["risk-1"] },
 },
 }).ready,
 "blocks a pre-inspection rollup with non-conserved risk identities",
);
check(
 assuranceEvidenceState({
 task: { mode: "pre_inspection" },
 rollup: {
 ...cleanPreInspectionRollup,
 trial_rollup: { ...cleanPreInspectionRollup.trial_rollup, closed_risks_lacking_evidence_count: 1 },
 },
 }).blockingReason.includes("关闭依据"),
 "reports missing closure evidence instead of promoting the rollup",
);
check(
 !assuranceEvidenceState({ task: { mode: "pre_inspection" }, rollup: { site_rollup: [] } }).ready,
 "blocks an incomplete pre-inspection rollup payload",
);
const readinessInput = assuranceReadinessInput({
 currentSnapshot: {
 subjects_evaluated: 4,
 rollup: { sites: [{ scope_id: "site-1" }, { scope_id: "site-2" }] },
 assurance_readiness: { planned_subjects: 4, planned_sites: 2 },
 },
 currentIdentity: identity,
 task: { version: 2 },
});
check(readinessInput.available && readinessInput.actual_subjects === 4 && readinessInput.actual_sites === 2, "builds readiness counts from explicit snapshot and rollup facts");
check(readinessInput.planned_subjects === 4 && readinessInput.planned_sites === 2, "preserves optional planned coverage counts");
check(!Object.hasOwn(assuranceReadinessPayload(readinessInput), "missingFields") && !Object.hasOwn(assuranceReadinessPayload(readinessInput), "available"), "strips local readiness metadata before the strict backend request");
check(
 assuranceReadinessState({ input: readinessInput, readiness: { ready: true, gaps: [] } }).ready,
 "promotes only a server-returned ready state",
);
const incompleteReadinessInput = assuranceReadinessInput({ task: { version: 2 }, currentIdentity: identity });
check(!incompleteReadinessInput.available && incompleteReadinessInput.missingFields.includes("actual_sites"), "does not guess missing coverage as zero");
check(!assuranceReadinessState({ input: incompleteReadinessInput }).ready, "keeps readiness visibly blocked when coverage is missing");
const actionTask = tasks[1];
const actionBlocked = assuranceActionAvailability({ task: actionTask, evidenceReady: false, readinessReady: false });
check(!actionBlocked.canRecordEvidence && actionBlocked.baseBlockers.includes("服务端认证 principal 未就绪"), "blocks assurance writes without a verified principal");
const actionEvidence = assuranceActionAvailability({
 task: actionTask,
 principalReady: true,
 authorityWritePermitted: true,
 evidenceReady: false,
 readinessReady: false,
});
check(actionEvidence.canRecordEvidence && !actionEvidence.canReview, "allows only evidence generation before evidence exists");
const actionUntrustedEvidence = assuranceActionAvailability({
 task: actionTask,
 principalReady: true,
 authorityWritePermitted: true,
 evidenceReady: false,
 evidenceRecorded: true,
 evidenceBlockingReason: "证据来源混合，不能作为全量重算完成证明。",
 readinessReady: false,
});
check(!actionUntrustedEvidence.canRecordEvidence && actionUntrustedEvidence.evidenceBlocker.includes("来源混合"), "does not offer re-recording for a present but non-authoritative proof");
const actionReview = assuranceActionAvailability({
 task: actionTask,
 principalReady: true,
 authorityWritePermitted: true,
 evidenceReady: true,
 readinessReady: false,
});
check(actionReview.canReview && !actionReview.canComplete, "requires medical review and readiness before completion");
const actionComplete = assuranceActionAvailability({
 task: { ...actionTask, medical_review_recorded: true },
 principalReady: true,
 authorityWritePermitted: true,
 evidenceReady: true,
 readinessReady: true,
});
check(actionComplete.canComplete, "opens completion only after evidence, review and readiness gates");

const calls = [];
const api = createMedicalMonitoringAssuranceApi({
 fetchImpl: async (path, options = {}) => {
 calls.push({ path, options });
 return { ok: true, status: 200, json: async () => ({ project_id: "proj", items: [] }) };
 },
});
await api.listTasks("proj/with space", { mode: "pre_lock" });
await api.getProof("proj", "task-1");
const auditSignal = { aborted: false };
await api.getAudit("proj", "task-1", { signal: auditSignal });
await api.evaluateReadiness("proj", "task-1", { expected_version: 2, current_identity: identity });
await api.recordFullRecomputeProof("proj", "task-1", { expected_version: 2, idempotency_key: "proof-1", actor: "medical_manager", proof_payload: { failures: 0 } });
await api.generateRollups("proj", "task-1", { expected_version: 2, idempotency_key: "rollup-1", actor: "medical_manager" });
await api.recordMedicalReview("proj", "task-1", { expected_version: 2, idempotency_key: "review-1", actor: "medical_manager", review_payload: { conclusion: "confirmed" } });
await api.completeTask("proj", "task-1", { expected_version: 2, idempotency_key: "complete-1", confirmed_by: "medical_manager", reauthenticated: true, signature_evidence_sha256: "a".repeat(64) });
await api.createTask("proj", { mode: "pre_lock", frozen_identity: identity, idempotency_key: "key" });
check(calls[0].path.includes("proj%2Fwith%20space") && calls[0].path.endsWith("?mode=pre_lock"), "encodes project and mode in task listing");
check(calls[1].path.endsWith("/task-1/full-recompute-proof"), "builds proof endpoint path");
check(calls[2].path.endsWith("/task-1/audit") && calls[2].options.signal === auditSignal && !calls[2].options.method, "builds read-only audit endpoint with caller cancellation signal");
const readinessCall = calls.find((call) => call.path.endsWith("/task-1/readiness"));
check(readinessCall?.options.method === "POST" && readinessCall.options.headers["Content-Type"] === "application/json", "uses the read-only readiness contract with explicit JSON POST");
const createCall = calls.find((call) => call.path.endsWith("/monitoring/assurance/tasks"));
check(createCall?.options.method === "POST" && createCall.options.headers["Content-Type"] === "application/json", "uses JSON POST only for explicit task creation");
const actionCalls = calls.filter((call) => call.options.method === "POST" && /\/tasks\/task-1\/(full-recompute-proof|rollups|medical-review|complete)$/.test(call.path));
check(actionCalls.length === 4 && actionCalls.every((call) => call.options.method === "POST"), "exposes all four server-backed assurance action routes as JSON POST");
check(actionCalls.every((call) => !Object.hasOwn(JSON.parse(call.options.body), "actor") && !Object.hasOwn(JSON.parse(call.options.body), "confirmed_by")), "strips client identity fields from assurance action payloads");

console.log(`medicalMonitoringAssurance: ${passed} passed`);

export class MedicalMonitoringAssuranceApiError extends Error {
 constructor(message, { status = 0, detail = null } = {}) {
 super(message);
 this.name = "MedicalMonitoringAssuranceApiError";
 this.status = status;
 this.detail = detail;
 }
}

function projectPath(projectId) {
 return encodeURIComponent(String(projectId || ""));
}

function taskPath(projectId, taskId = "") {
 return `/api/projects/${projectPath(projectId)}/monitoring/assurance/tasks/${encodeURIComponent(String(taskId))}`;
}

function serverOwnedTaskActionPayload(payload = {}) {
 const next = payload && typeof payload === "object" && !Array.isArray(payload)
 ? { ...payload }
 : {};
 // The backend derives actor/confirmed_by from its verified principal. Keep
 // transitional client identity fields out of every feature-owned action.
 delete next.actor;
 delete next.confirmed_by;
 return next;
}

export function createMedicalMonitoringAssuranceApi({ fetchImpl = globalThis.fetch } = {}) {
 if (typeof fetchImpl !== "function") {
 throw new MedicalMonitoringAssuranceApiError("当前环境不支持医学监查保障 API 请求。");
 }

 const request = async (path, options = {}) => {
 let response;
 try {
 response = await fetchImpl(path, {
 ...options,
 headers: { Accept: "application/json", ...(options.headers || {}) },
 });
 } catch (error) {
 if (error?.name === "AbortError") throw error;
 throw new MedicalMonitoringAssuranceApiError(error?.message || "医学监查保障 API 请求失败。");
 }
 const payload = await response.json().catch(() => ({}));
 if (!response.ok) {
 const detail = payload?.detail;
 const message = typeof detail === "object" ? detail.message : detail;
 throw new MedicalMonitoringAssuranceApiError(
 message || `医学监查保障 API ${response.status}`,
 { status: response.status, detail: payload },
 );
 }
 return payload;
 };

 return {
 listTasks(projectId, { mode = "", signal } = {}) {
 const query = mode ? `?mode=${encodeURIComponent(mode)}` : "";
 return request(`/api/projects/${projectPath(projectId)}/monitoring/assurance/tasks${query}`, { signal });
 },
 getTask(projectId, taskId, { signal } = {}) {
 return request(taskPath(projectId, taskId), { signal });
 },
 getAudit(projectId, taskId, { signal } = {}) {
 return request(`${taskPath(projectId, taskId)}/audit`, { signal });
 },
 evaluateReadiness(projectId, taskId, payload, { signal } = {}) {
 return request(`${taskPath(projectId, taskId)}/readiness`, {
 method: "POST",
 signal,
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify(payload),
 });
 },
 recordFullRecomputeProof(projectId, taskId, payload, { signal } = {}) {
 return request(`${taskPath(projectId, taskId)}/full-recompute-proof`, {
 method: "POST",
 signal,
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify(serverOwnedTaskActionPayload(payload)),
 });
 },
 generateRollups(projectId, taskId, payload, { signal } = {}) {
 return request(`${taskPath(projectId, taskId)}/rollups`, {
 method: "POST",
 signal,
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify(serverOwnedTaskActionPayload(payload)),
 });
 },
 recordMedicalReview(projectId, taskId, payload, { signal } = {}) {
 return request(`${taskPath(projectId, taskId)}/medical-review`, {
 method: "POST",
 signal,
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify(serverOwnedTaskActionPayload(payload)),
 });
 },
 completeTask(projectId, taskId, payload, { signal } = {}) {
 return request(`${taskPath(projectId, taskId)}/complete`, {
 method: "POST",
 signal,
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify(serverOwnedTaskActionPayload(payload)),
 });
 },
 getProof(projectId, taskId, { signal } = {}) {
 return request(`${taskPath(projectId, taskId)}/full-recompute-proof`, { signal });
 },
 getRollups(projectId, taskId, { signal } = {}) {
 return request(`${taskPath(projectId, taskId)}/rollups`, { signal });
 },
 createTask(projectId, payload, { signal } = {}) {
 return request(`/api/projects/${projectPath(projectId)}/monitoring/assurance/tasks`, {
 method: "POST",
 signal,
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify(payload),
 });
 },
 };
}

const SEVERITY_RANK = Object.freeze({ critical: 0, high: 1, medium: 2, low: 3 });
const OPEN_STATUSES = new Set([
 "open",
 "action_required",
 "pending_review",
 "in_review",
 "new",
 "reviewed",
 "query_draft",
 "submitted_for_approval",
]);

function isRecord(value) {
 return value !== null && typeof value === "object" && !Array.isArray(value);
}

function text(value) {
 return typeof value === "string" && value.trim() ? value.trim() : "";
}

function issue(field, kind, message) {
 return { field, kind, message };
}

function optionalText(raw, field, issues) {
 if (raw === undefined || raw === null || raw === "") return null;
 const value = text(raw);
 if (!value) {
 issues.push(issue(field, "invalid", "字段不是非空文本。"));
 return null;
 }
 return value;
}

function requiredText(raw, field, issues) {
 const value = optionalText(raw, field, issues);
 if (!value) issues.push(issue(field, "missing", "整改项缺少显式风险实例 ID。"));
 return value;
}

function optionalBoolean(raw, field, issues) {
 if (raw === undefined || raw === null) {
 issues.push(issue(field, "missing", "关闭证据状态未提供。"));
 return null;
 }
 if (typeof raw !== "boolean") {
 issues.push(issue(field, "invalid", "关闭证据状态不是严格布尔值。"));
 return null;
 }
 return raw;
}

function rowPriority(row) {
 const openRank = OPEN_STATUSES.has(String(row.status || "").toLowerCase()) ? 0 : 1;
 const severityRank = SEVERITY_RANK[String(row.severity || "").toLowerCase()] ?? 9;
 const evidenceRank = row.closureEvidencePresent === false ? 0 : row.closureEvidencePresent === true ? 1 : 2;
 return [openRank, severityRank, evidenceRank, row.riskInstanceId || "", row.sourceIndex ?? 0];
}

function compareRows(left, right) {
 const leftKey = rowPriority(left);
 const rightKey = rowPriority(right);
 for (let index = 0; index < leftKey.length; index += 1) {
 if (leftKey[index] === rightKey[index]) continue;
 if (typeof leftKey[index] === "number") return leftKey[index] - rightKey[index];
 return String(leftKey[index]).localeCompare(String(rightKey[index]), "zh-CN", { numeric: true });
 }
 return 0;
}

export function normalizeMedicalMonitoringAssuranceRemediation(matrix) {
 if (matrix === null || matrix === undefined) {
 return { status: "empty", rows: [], totalCount: null, issues: [] };
 }
 if (!Array.isArray(matrix)) {
 return {
 status: "malformed",
 rows: [],
 totalCount: null,
 issues: [issue("remediation_matrix", "invalid", "整改矩阵不是数组。")],
 };
 }

 const issues = [];
 const rows = [];
 matrix.forEach((raw, index) => {
 if (!isRecord(raw)) {
 issues.push(issue(`remediation_matrix[${index}]`, "invalid", "整改项不是对象。"));
 return;
 }
 const path = `remediation_matrix[${index}]`;
 const riskInstanceId = requiredText(raw.risk_instance_id, `${path}.risk_instance_id`, issues);
 if (!riskInstanceId) return;
 rows.push({
 riskInstanceId,
 sourceIndex: index,
 riskKey: optionalText(raw.risk_key, `${path}.risk_key`, issues),
 subjectId: optionalText(raw.subject_id, `${path}.subject_id`, issues),
 siteId: optionalText(raw.site_id, `${path}.site_id`, issues),
 severity: optionalText(raw.severity, `${path}.severity`, issues),
 status: optionalText(raw.status, `${path}.status`, issues),
 closureEvidencePresent: optionalBoolean(raw.closure_evidence_present, `${path}.closure_evidence_present`, issues),
 });
 });

 const riskInstanceCounts = new Map();
 rows.forEach((row) => {
 riskInstanceCounts.set(row.riskInstanceId, (riskInstanceCounts.get(row.riskInstanceId) || 0) + 1);
 });
 const normalizedRows = rows.map((row) => {
 const identityState = riskInstanceCounts.get(row.riskInstanceId) > 1 ? "duplicate" : "ready";
 if (identityState === "duplicate") {
 issues.push(issue(`remediation_matrix[${row.sourceIndex}].risk_instance_id`, "invalid", "整改矩阵包含重复风险实例；保留整改项但暂不可单独聚焦。"));
 }
 return {
 ...row,
 identityState,
 identityIssue: identityState === "duplicate"
 ? "风险实例 ID 重复；保留整改项但暂不可单独聚焦。"
 : null,
 };
 });

 const sortedRows = [...normalizedRows].sort(compareRows);
 const openCount = sortedRows.filter((row) => OPEN_STATUSES.has(String(row.status || "").toLowerCase())).length;
 const missingClosureEvidenceCount = sortedRows.filter((row) => row.closureEvidencePresent !== true).length;
 return {
 status: issues.length > 0 ? "partial" : sortedRows.length > 0 ? "ready" : "empty",
 rows: sortedRows,
 totalCount: matrix.length,
 validCount: normalizedRows.length,
 invalidCount: matrix.length - normalizedRows.length,
 openCount,
 missingClosureEvidenceCount,
 issues: issues.map(({ field, kind, message }) => ({ field, kind, message })),
 };
}

export function assuranceRemediationDisplayKey(row, index = 0) {
 const identity = text(row?.riskInstanceId) || "missing";
 const sourceIndex = Number.isInteger(row?.sourceIndex) ? row.sourceIndex : index;
 return `assurance-remediation:${identity}:${sourceIndex}`;
}

export function assuranceRemediationSeverityLabel(value) {
 return { critical: "紧急", high: "高", medium: "中", low: "低" }[String(value || "").toLowerCase()] || value || "待核对";
}

export function assuranceRemediationStatusLabel(value) {
 return {
 open: "开放",
 action_required: "需行动",
 pending_review: "待医学复核",
 in_review: "复核中",
 new: "新识别",
 reviewed: "已医学复核",
 query_draft: "Query草稿",
 submitted_for_approval: "已提交审批",
 closed: "已关闭",
 resolved: "已解决",
 }[String(value || "").toLowerCase()] || value || "待核对";
}

import assert from "node:assert/strict";
import {
 assuranceRemediationDisplayKey,
 assuranceRemediationSeverityLabel,
 assuranceRemediationStatusLabel,
 normalizeMedicalMonitoringAssuranceRemediation,
} from "./medicalMonitoringAssuranceRemediation.mjs";

const matrix = [
 { risk_instance_id: "risk-closed", risk_key: "r-closed", subject_id: "S2", site_id: "02", severity: "low", status: "closed", closure_evidence_present: true },
 { risk_instance_id: "risk-high", risk_key: "r-high", subject_id: "S1", site_id: "01", severity: "high", status: "open", closure_evidence_present: false },
 { risk_instance_id: "risk-critical", risk_key: "r-critical", subject_id: "S3", site_id: "01", severity: "critical", status: "pending_review", closure_evidence_present: false },
];
const view = normalizeMedicalMonitoringAssuranceRemediation(matrix);
assert.equal(view.status, "ready");
assert.equal(view.totalCount, 3);
assert.equal(view.openCount, 2);
assert.equal(view.missingClosureEvidenceCount, 2);
assert.deepEqual(view.rows.map((row) => row.riskInstanceId), ["risk-critical", "risk-high", "risk-closed"]);
assert.equal(view.rows[0].subjectId, "S3");
assert.equal(view.rows[0].closureEvidencePresent, false);
assert.equal(view.rows[0].sourceIndex, 2);
assert.equal(view.rows[0].identityState, "ready");
assert.equal(assuranceRemediationDisplayKey(view.rows[0]), "assurance-remediation:risk-critical:2");
assert.equal(view.issues.length, 0);

assert.equal(normalizeMedicalMonitoringAssuranceRemediation(null).status, "empty");
assert.equal(normalizeMedicalMonitoringAssuranceRemediation("bad").status, "malformed");

const partial = normalizeMedicalMonitoringAssuranceRemediation([
 { risk_instance_id: "risk-partial", severity: "high", status: "open" },
 { risk_instance_id: "risk-partial" },
 "malformed",
]);
assert.equal(partial.status, "partial");
assert.equal(partial.validCount, 2);
assert.equal(partial.invalidCount, 1);
assert.equal(partial.rows[0].closureEvidencePresent, null);
assert.ok(partial.issues.some((item) => item.field.endsWith("closure_evidence_present")));
assert.ok(partial.issues.some((item) => item.field.includes("risk_instance_id")));

const duplicate = normalizeMedicalMonitoringAssuranceRemediation([
 { risk_instance_id: "risk-duplicate", subject_id: "S1", site_id: "01", status: "open", closure_evidence_present: false },
 { risk_instance_id: "risk-duplicate", subject_id: "S2", site_id: "02", status: "closed", closure_evidence_present: true },
]);
assert.equal(duplicate.status, "partial");
assert.equal(duplicate.rows.length, 2);
assert.equal(duplicate.rows[0].identityState, "duplicate");
assert.equal(duplicate.rows[1].identityState, "duplicate");
assert.notEqual(
 assuranceRemediationDisplayKey(duplicate.rows[0]),
 assuranceRemediationDisplayKey(duplicate.rows[1]),
);
assert.ok(duplicate.issues.some((item) => item.message.includes("重复风险实例")));

const invalidBoolean = normalizeMedicalMonitoringAssuranceRemediation([
 { risk_instance_id: "risk-boolean", closure_evidence_present: "false" },
]);
assert.equal(invalidBoolean.status, "partial");
assert.equal(invalidBoolean.rows[0].closureEvidencePresent, null);
assert.equal(assuranceRemediationSeverityLabel("critical"), "紧急");
assert.equal(assuranceRemediationStatusLabel("pending_review"), "待医学复核");

console.log("medicalMonitoringAssuranceRemediation: contract checks passed");

const LEVEL_KEYS = Object.freeze(["trial", "site", "subject"]);

function nonNegativeInteger(value) {
 if (value === null || value === undefined || value === "") return null;
 if (typeof value === "boolean") return null;
 if (typeof value === "string" && !value.trim()) return null;
 const number = Number(value);
 return Number.isInteger(number) && number >= 0 ? number : null;
}

function text(value, fallback = "") {
 const result = String(value ?? "").trim();
 return result || fallback;
}

function sortedUnique(values) {
 return [...new Set(values.map((value) => text(value)).filter(Boolean))].sort();
}

function idSetFromRows(rows) {
 return sortedUnique(
 rows.flatMap((row) => {
 if (Array.isArray(row?.riskInstanceIds)) return row.riskInstanceIds;
 return Array.isArray(row?.risk_instance_ids) ? row.risk_instance_ids : [];
 }),
 );
}

function sameValues(left, right) {
 return left.length === right.length && left.every((value, index) => value === right[index]);
}

function distributionEntries(distribution) {
 if (!distribution || typeof distribution !== "object" || Array.isArray(distribution)) return [];
 return Object.entries(distribution)
 .map(([label, value]) => ({ label: text(label, "未分类"), value: nonNegativeInteger(value) }))
 .filter((entry) => entry.value !== null)
 .sort((left, right) => right.value - left.value || left.label.localeCompare(right.label));
}

function normalizeSite(row) {
 const identity = text(row?.site_id);
 return {
 siteId: identity || "未标识中心",
 identityState: identity ? "ready" : "missing",
 identityIssue: identity ? "" : "中心缺少 site_id；仅可读，暂不可下钻",
 totalRiskCount: nonNegativeInteger(row?.total_risk_count),
 openRiskCount: nonNegativeInteger(row?.open_risk_count),
 openHighRiskCount: nonNegativeInteger(row?.open_high_risk_count),
 riskInstanceIds: sortedUnique(Array.isArray(row?.risk_instance_ids) ? row.risk_instance_ids : []),
 cluster: row?.cluster && typeof row.cluster === "object" ? row.cluster : null,
 };
}

function normalizeSubject(row) {
 const identity = text(row?.subject_id);
 return {
 subjectId: identity || "未标识受试者",
 identityState: identity ? "ready" : "missing",
 identityIssue: identity ? "" : "个例缺少 subject_id；仅可读，暂不可下钻",
 siteId: text(row?.site_id, "未标识中心"),
 totalRiskCount: nonNegativeInteger(row?.total_risk_count),
 openRiskCount: nonNegativeInteger(row?.open_risk_count),
 riskInstanceIds: sortedUnique(Array.isArray(row?.risk_instance_ids) ? row.risk_instance_ids : []),
 };
}

function normalizeRows(rows, normalize, identityField) {
 const normalized = (Array.isArray(rows) ? rows : [])
 .map((row, sourceIndex) => ({ ...normalize(row), displaySourceIndex: sourceIndex }));
 const identityCounts = new Map();
 normalized.forEach((row) => {
 if (row.identityState !== "ready") return;
 const identity = row[identityField];
 identityCounts.set(identity, (identityCounts.get(identity) || 0) + 1);
 });
 return normalized.map((row) => {
 if (row.identityState !== "ready" || (identityCounts.get(row[identityField]) || 0) <= 1) return row;
 return {
 ...row,
 identityState: "duplicate",
 identityIssue: `${identityField === "siteId" ? "中心" : "个例"}身份重复；仅可读，暂不可下钻`,
 };
 })
 .sort((left, right) => (
 (right.openHighRiskCount ?? -1) - (left.openHighRiskCount ?? -1)
 || (right.openRiskCount ?? -1) - (left.openRiskCount ?? -1)
 || (right.totalRiskCount ?? -1) - (left.totalRiskCount ?? -1)
 || left.siteId?.localeCompare(right.siteId || "")
 || left.subjectId?.localeCompare(right.subjectId || "")
 ));
}

/**
 * Turn the backend's reference-only pre-inspection rollup into a compact UI model.
 * It never invents risk facts or severity; every displayed count is copied from an
 * explicit rollup field and the conservation result is fail-closed on malformed IDs.
 */
export function projectAssuranceRollup(rollup = null) {
 const payload = rollup && typeof rollup === "object" && !Array.isArray(rollup) ? rollup : {};
 const trialPayload = payload.trial_rollup && typeof payload.trial_rollup === "object"
 ? payload.trial_rollup
 : {};
 const sites = normalizeRows(payload.site_rollup, normalizeSite, "siteId");
 const subjects = normalizeRows(payload.subject_rollup, normalizeSubject, "subjectId");
 const trialRiskIds = sortedUnique(
 Array.isArray(trialPayload.risk_instance_ids) ? trialPayload.risk_instance_ids : [],
 );
 const siteRiskIds = idSetFromRows(sites);
 const subjectRiskIds = idSetFromRows(subjects);
 const expectedTotal = nonNegativeInteger(trialPayload.total_risk_count);
 const conservation = {
 riskInstanceIdsMatch: trialRiskIds.length > 0 || expectedTotal === 0
 ? sameValues(trialRiskIds, siteRiskIds) && sameValues(trialRiskIds, subjectRiskIds)
 : false,
 trialCountMatches: expectedTotal !== null && expectedTotal === trialRiskIds.length,
 subjectCountMatches: subjects.every((row) => (
 row.totalRiskCount !== null && row.totalRiskCount === row.riskInstanceIds.length
 )),
 siteCountMatches: sites.every((row) => (
 row.totalRiskCount !== null && row.totalRiskCount === row.riskInstanceIds.length
 )),
 };
 conservation.ok = Object.values(conservation).every(Boolean);

 const distributions = payload.distributions && typeof payload.distributions === "object"
 ? payload.distributions
 : {};
 const trial = {
 totalRiskCount: expectedTotal,
 openRiskCount: nonNegativeInteger(trialPayload.open_risk_count),
 openHighRiskCount: nonNegativeInteger(trialPayload.open_high_risk_count),
 closedRiskCount: nonNegativeInteger(trialPayload.closed_risk_count),
 closedWithoutEvidenceCount: nonNegativeInteger(trialPayload.closed_risks_lacking_evidence_count),
 safetyPvRiskCount: nonNegativeInteger(trialPayload.safety_pv_risk_count),
 concomitantMedicationRiskCount: nonNegativeInteger(trialPayload.concomitant_medication_risk_count),
 studyTreatmentRiskCount: nonNegativeInteger(trialPayload.study_treatment_risk_count),
 };

 return {
 available: Boolean(rollup && typeof rollup === "object"),
 riskSnapshotId: text(payload.risk_snapshot_id),
 trial,
 sites,
 subjects,
 distributions: {
 severity: distributionEntries(distributions.by_severity),
 status: distributionEntries(distributions.by_status),
 disposition: distributionEntries(distributions.by_disposition),
 },
 evidenceCount: Array.isArray(payload.evidence_manifest) ? payload.evidence_manifest.length : 0,
 remediationCount: Array.isArray(payload.remediation_matrix) ? payload.remediation_matrix.length : 0,
 conservation,
 };
}

/**
 * UI-only key for an assurance rollup row. It keeps malformed/duplicate rows
 * visible without turning the source index into a scope or subject identity.
 */
export function assuranceRollupRowDisplayKey(row = {}, level = "row", index = 0) {
 const identity = level === "subject" ? text(row.subjectId) : text(row.siteId);
 const sourceIndex = Number.isInteger(row.displaySourceIndex) && row.displaySourceIndex >= 0
 ? row.displaySourceIndex
 : Number.isInteger(index) && index >= 0 ? index : 0;
 return `assurance:${level}:${identity || "missing"}:${sourceIndex}`;
}

export function assuranceRollupLevelKeys() {
 return [...LEVEL_KEYS];
}

export function assuranceRollupNumber(value, fallback = "—") {
 const number = nonNegativeInteger(value);
 return number === null ? fallback : String(number);
}

import assert from "node:assert/strict";
import {
 assuranceRollupLevelKeys,
 assuranceRollupNumber,
 assuranceRollupRowDisplayKey,
 projectAssuranceRollup,
} from "./medicalMonitoringAssuranceRollup.mjs";

const rollup = {
 risk_snapshot_id: "snapshot-1",
 trial_rollup: {
 total_risk_count: 3,
 open_risk_count: 2,
 open_high_risk_count: 1,
 closed_risk_count: 1,
 closed_risks_lacking_evidence_count: 0,
 safety_pv_risk_count: 1,
 concomitant_medication_risk_count: 1,
 study_treatment_risk_count: 0,
 risk_instance_ids: ["risk-1", "risk-2", "risk-3"],
 },
 site_rollup: [
 { site_id: "10", total_risk_count: 2, open_risk_count: 1, open_high_risk_count: 1, risk_instance_ids: ["risk-1", "risk-2"] },
 { site_id: "06", total_risk_count: 1, open_risk_count: 1, open_high_risk_count: 0, risk_instance_ids: ["risk-3"] },
 ],
 subject_rollup: [
 { subject_id: "10001", site_id: "10", total_risk_count: 1, open_risk_count: 1, risk_instance_ids: ["risk-1"] },
 { subject_id: "10002", site_id: "10", total_risk_count: 1, open_risk_count: 0, risk_instance_ids: ["risk-2"] },
 { subject_id: "06001", site_id: "06", total_risk_count: 1, open_risk_count: 1, risk_instance_ids: ["risk-3"] },
 ],
 distributions: {
 by_severity: { high: 1, medium: 2 },
 by_status: { open: 2, closed: 1 },
 by_disposition: { open: 2, closed: 1 },
 },
 evidence_manifest: [{ risk_instance_id: "risk-1" }],
 remediation_matrix: [{ risk_instance_id: "risk-1" }],
};

const view = projectAssuranceRollup(rollup);
assert.deepEqual(assuranceRollupLevelKeys(), ["trial", "site", "subject"]);
assert.equal(view.available, true);
assert.equal(view.riskSnapshotId, "snapshot-1");
assert.equal(view.trial.openHighRiskCount, 1);
assert.deepEqual(view.sites.map((row) => row.siteId), ["10", "06"]);
assert.deepEqual(view.subjects.map((row) => row.subjectId), ["06001", "10001", "10002"]);
assert.equal(view.distributions.severity[0].label, "medium");
assert.equal(view.evidenceCount, 1);
assert.equal(view.remediationCount, 1);
assert.equal(view.conservation.ok, true);
assert.equal(assuranceRollupNumber(0), "0");
assert.equal(assuranceRollupNumber("bad"), "—");
assert.equal(assuranceRollupNumber(false), "—");
assert.equal(assuranceRollupNumber(" "), "—");

const ambiguous = projectAssuranceRollup({
 ...rollup,
 site_rollup: [
 { site_id: "10", total_risk_count: 1, open_risk_count: 1, risk_instance_ids: ["risk-1"] },
 { site_id: "10", total_risk_count: 1, open_risk_count: 0, risk_instance_ids: ["risk-2"] },
 ],
 subject_rollup: [
 { site_id: "10", total_risk_count: 1, open_risk_count: 1, risk_instance_ids: ["risk-1"] },
 { total_risk_count: 0, open_risk_count: 0, risk_instance_ids: [] },
 ],
});
assert.equal(ambiguous.sites.every((row) => row.identityState === "duplicate"), true);
assert.equal(ambiguous.subjects.at(-1).identityState, "missing");
assert.notEqual(
 assuranceRollupRowDisplayKey(ambiguous.sites[0], "site", 0),
 assuranceRollupRowDisplayKey(ambiguous.sites[1], "site", 1),
);

const tampered = projectAssuranceRollup({
 ...rollup,
 site_rollup: [{ ...rollup.site_rollup[0], risk_instance_ids: ["risk-1"] }],
});
assert.equal(tampered.conservation.ok, false);
assert.equal(tampered.conservation.riskInstanceIdsMatch, false);

const empty = projectAssuranceRollup(null);
assert.equal(empty.available, false);
assert.equal(empty.conservation.ok, false);

console.log("medicalMonitoringAssuranceRollup: 16 passed");

const ASSURANCE_MODES = new Set(["pre_lock", "pre_inspection"]);
const ASSURANCE_STATUSES = new Set([
 "draft",
 "running",
 "blocked",
 "completed",
 "superseded",
]);
const ASSURANCE_EVIDENCE_PROVENANCE_STATUSES = new Set([
 "server_evidence_run_ledger",
 "signed_manifest_server_revalidated",
]);
const FROZEN_IDENTITY_FIELDS = [
 "batch_id",
 "batch_revision",
 "mapping_revision",
 "protocol_version_id",
 "rule_pack_revision",
 "dictionary_revision",
 "ctcae_revision",
 "model_revision",
 "risk_snapshot_id",
];
const AUDIT_ACTIONS = new Set([
 "read_monitoring",
 "read_source_evidence",
 "read_risk_audit",
 "read_runtime_audit",
 "intake_batch",
 "run_deterministic_rules",
 "review_ai_candidate",
 "change_risk_disposition",
 "draft_query",
 "create_assurance_task",
 "record_assurance_evidence",
 "review_assurance",
 "export_risk_evidence",
 "complete_assurance",
 "confirm_high_risk_close",
 "approve_rule_change",
 "provide_center_context",
 "validate_source_revision",
 "mark_safety_pv_review",
 "confirm_derived_data",
 "administer_runtime",
]);
const AUDIT_TARGET_TYPES = new Set([
 "project",
 "trial",
 "site",
 "subject",
 "risk",
 "batch",
 "source",
 "rule",
 "runtime",
]);
const AUDIT_ROLES = new Set([
 "medical_monitor",
 "medical_manager",
 "medical_director",
 "medical_writer",
 "clinical_operations",
 "data_management",
 "pv",
 "statistics_programming",
 "system_admin",
 "product_engineering",
]);
const SHA256_RE = /^[0-9a-f]{64}$/;

export class MedicalMonitoringAssuranceShapeError extends Error {
 constructor(path, message) {
 super(`${path} ${message}`);
 this.name = "MedicalMonitoringAssuranceShapeError";
 }
}

function fail(path, message) {
 throw new MedicalMonitoringAssuranceShapeError(path, message);
}

function record(value, path) {
 if (!value || typeof value !== "object" || Array.isArray(value)) {
 fail(path, "must be an object");
 }
 return value;
}

function array(value, path) {
 if (!Array.isArray(value)) fail(path, "must be an array");
 return value;
}

function requiredText(value, path) {
 if (typeof value !== "string" || !value.trim()) {
 fail(path, "must be a non-empty string");
 }
 return value.trim();
}

function positiveInteger(value, path) {
 if (typeof value !== "number" || !Number.isInteger(value) || value < 1) {
 fail(path, "must be a positive integer");
 }
 return value;
}

function nonNegativeInteger(value, path) {
 if (typeof value !== "number" || !Number.isInteger(value) || value < 0) {
 fail(path, "must be a non-negative integer");
 }
 return value;
}

function strictBoolean(value, path) {
 if (typeof value !== "boolean") fail(path, "must be a boolean");
 return value;
}

function sha256(value, path, { allowEmpty = false } = {}) {
 const text = requiredText(value, path).toLowerCase();
 if (allowEmpty && text === "") return "";
 if (!SHA256_RE.test(text)) fail(path, "must be a lowercase SHA-256 digest");
 return text;
}

function optionalSha256(value, path) {
 if (value === "") return "";
 return sha256(value, path);
}

function roleArray(value, path, { allowEmpty = false } = {}) {
 if (!Array.isArray(value) || (!allowEmpty && value.length === 0)) {
 fail(path, allowEmpty ? "must be an array" : "must be a non-empty array");
 }
 const roles = value.map((item, index) => requiredText(item, `${path}[${index}]`));
 if (new Set(roles).size !== roles.length) fail(path, "must contain unique values");
 const unsupported = roles.find((role) => !AUDIT_ROLES.has(role));
 if (unsupported) fail(path, `contains unsupported role ${unsupported}`);
 return roles;
}

function isoTimestamp(value, path) {
 const text = requiredText(value, path);
 const date = new Date(text);
 if (Number.isNaN(date.getTime())) fail(path, "must be an ISO-8601 timestamp");
 return text;
}

function auditPayloadIsSafe(value, path = "payload") {
 if (value === undefined) return;
 if (!value || typeof value !== "object" || Array.isArray(value)) fail(path, "must be an object");
 for (const [key, nested] of Object.entries(value)) {
 if (["access_token", "authorization", "password", "secret", "session_id", "token"].includes(key.toLowerCase())) {
 fail(`${path}.${key}`, "contains a sensitive field");
 }
 if (nested && typeof nested === "object") {
 if (Array.isArray(nested)) nested.forEach((item, index) => auditPayloadIsSafe(item, `${path}.${key}[${index}]`));
 else auditPayloadIsSafe(nested, `${path}.${key}`);
 }
 }
}

function normalizeAssuranceAuditEvent(raw, { projectId: expectedProjectId, taskId, path }) {
 const event = record(raw, path);
 projectId(event.project_id, expectedProjectId, `${path}.project_id`);
 requiredText(event.audit_id, `${path}.audit_id`);
 requiredText(event.principal_id, `${path}.principal_id`);
 const roleClaims = roleArray(event.role_claims, `${path}.role_claims`);
 const matchedRoles = roleArray(event.matched_roles, `${path}.matched_roles`, { allowEmpty: true });
 if (matchedRoles.some((role) => !roleClaims.includes(role))) fail(`${path}.matched_roles`, "must be a subset of role_claims");
 const action = requiredText(event.action, `${path}.action`);
 if (!AUDIT_ACTIONS.has(action)) fail(`${path}.action`, `has unsupported value ${action}`);
 const targetType = requiredText(event.target_type, `${path}.target_type`);
 if (!AUDIT_TARGET_TYPES.has(targetType)) fail(`${path}.target_type`, `has unsupported value ${targetType}`);
 requiredText(event.target_id, `${path}.target_id`);
 const sourceRevision = sha256(event.source_revision, `${path}.source_revision`);
 const authorizationDecision = sha256(event.authorization_decision_sha256, `${path}.authorization_decision_sha256`);
 strictBoolean(event.decision_allowed, `${path}.decision_allowed`);
 strictBoolean(event.write_permitted, `${path}.write_permitted`);
 strictBoolean(event.mutation_applied, `${path}.mutation_applied`);
 const versionBefore = nonNegativeInteger(event.aggregate_version_before, `${path}.aggregate_version_before`);
 const versionAfter = nonNegativeInteger(event.aggregate_version_after, `${path}.aggregate_version_after`);
 if (event.mutation_applied && versionAfter !== versionBefore + 1) fail(path, "mutation event must advance aggregate version by one");
 if (!event.mutation_applied && versionAfter !== versionBefore) fail(path, "non-mutating event cannot change aggregate version");
 const occurredAt = isoTimestamp(event.occurred_at, `${path}.occurred_at`);
 const prevEventHash = optionalSha256(event.prev_event_hash, `${path}.prev_event_hash`);
 const eventHash = sha256(event.event_hash, `${path}.event_hash`);
 if (taskId && event.payload !== undefined) {
 auditPayloadIsSafe(event.payload, `${path}.payload`);
 if (event.payload?.task_id !== undefined && String(event.payload.task_id) !== taskId) {
 fail(`${path}.payload.task_id`, "does not match the selected task");
 }
 } else {
 auditPayloadIsSafe(event.payload, `${path}.payload`);
 }
 return {
 schema_version: requiredText(event.schema_version, `${path}.schema_version`),
 audit_id: String(event.audit_id).trim(),
 project_id: String(expectedProjectId).trim(),
 principal_id: String(event.principal_id).trim(),
 role_claims: roleClaims,
 matched_roles: matchedRoles,
 action,
 target_type: targetType,
 target_id: String(event.target_id).trim(),
 source_revision: sourceRevision,
 authorization_decision_sha256: authorizationDecision,
 decision_allowed: event.decision_allowed,
 write_permitted: event.write_permitted,
 mutation_applied: event.mutation_applied,
 aggregate_version_before: versionBefore,
 aggregate_version_after: versionAfter,
 occurred_at: occurredAt,
 prev_event_hash: prevEventHash,
 event_hash: eventHash,
 };
}

function projectId(value, expected, path) {
 const actual = requiredText(value, path);
 const wanted = requiredText(expected, "project_id");
 if (actual !== wanted) fail(path, "does not match the active project");
 return actual;
}

function normalizeFrozenIdentity(value, path) {
 const identity = record(value, path);
 for (const field of FROZEN_IDENTITY_FIELDS) {
 requiredText(identity[field], `${path}.${field}`);
 }
 return identity;
}

export function normalizeAssuranceTask(raw, { projectId: expectedProjectId, path = "task" } = {}) {
 const task = record(raw, path);
 projectId(task.project_id, expectedProjectId, `${path}.project_id`);
 requiredText(task.task_id, `${path}.task_id`);
 const mode = requiredText(task.mode, `${path}.mode`);
 if (!ASSURANCE_MODES.has(mode)) fail(`${path}.mode`, `has unsupported value ${mode}`);
 const status = requiredText(task.status, `${path}.status`);
 if (!ASSURANCE_STATUSES.has(status)) fail(`${path}.status`, `has unsupported value ${status}`);
 positiveInteger(task.version, `${path}.version`);
 normalizeFrozenIdentity(task.frozen_identity, `${path}.frozen_identity`);
 requiredText(task.updated_at, `${path}.updated_at`);
 if (task.medical_review_recorded !== undefined) {
 strictBoolean(task.medical_review_recorded, `${path}.medical_review_recorded`);
 }
 return task;
}

function envelope(raw, expectedProjectId, path) {
 const payload = record(raw, path);
 projectId(payload.project_id, expectedProjectId, `${path}.project_id`);
 return payload;
}

export function normalizeAssuranceTaskList(
 raw,
 { projectId: expectedProjectId, mode = "", path = "assurance_task_list" } = {},
) {
 const payload = envelope(raw, expectedProjectId, path);
 const items = array(payload.items, `${path}.items`).map((item, index) => (
 normalizeAssuranceTask(item, {
 projectId: expectedProjectId,
 path: `${path}.items[${index}]`,
 })
 ));
 if (mode && items.some((item) => item.mode !== mode)) {
 fail(`${path}.items`, "contains a task from another assurance mode");
 }
 return { ...payload, project_id: String(expectedProjectId).trim(), items };
}

export function normalizeAssuranceTaskPayload(
 raw,
 { projectId: expectedProjectId, taskId = "", path = "assurance_task" } = {},
) {
 const payload = envelope(raw, expectedProjectId, path);
 const task = normalizeAssuranceTask(payload.task, {
 projectId: expectedProjectId,
 path: `${path}.task`,
 });
 if (taskId && task.task_id !== taskId) fail(`${path}.task.task_id`, "does not match the requested task");
 return { ...payload, project_id: String(expectedProjectId).trim(), task };
}

export function normalizeAssuranceReadinessPayload(
 raw,
 { projectId: expectedProjectId, taskId, expectedVersion = 0, path = "assurance_readiness" } = {},
) {
 const payload = normalizeEvidenceEnvelope(raw, {
 projectId: expectedProjectId,
 taskId,
 path,
 });
 const mode = requiredText(payload.mode, `${path}.mode`);
 if (!ASSURANCE_MODES.has(mode)) fail(`${path}.mode`, `has unsupported value ${mode}`);
 const status = requiredText(payload.status, `${path}.status`);
 if (!ASSURANCE_STATUSES.has(status)) fail(`${path}.status`, `has unsupported value ${status}`);
 const version = positiveInteger(payload.version, `${path}.version`);
 if (expectedVersion > 0 && version !== expectedVersion) fail(`${path}.version`, "does not match the selected task version");
 const gaps = array(payload.gaps, `${path}.gaps`).map((gap, index) => requiredText(gap, `${path}.gaps[${index}]`));
 if (new Set(gaps).size !== gaps.length) fail(`${path}.gaps`, "must contain unique values");
 return {
 ...payload,
 project_id: String(expectedProjectId).trim(),
 task_id: String(taskId).trim(),
 mode,
 status,
 version,
 ready: strictBoolean(payload.ready, `${path}.ready`),
 frozen_identity_ok: strictBoolean(payload.frozen_identity_ok, `${path}.frozen_identity_ok`),
 gaps,
 };
}

function normalizeEvidenceEnvelope(raw, { projectId: expectedProjectId, taskId, path }) {
 const payload = envelope(raw, expectedProjectId, path);
 const actualTaskId = requiredText(payload.task_id, `${path}.task_id`);
 if (actualTaskId !== taskId) fail(`${path}.task_id`, "does not match the selected task");
 return payload;
}

export function normalizeAssuranceProofPayload(
 raw,
 { projectId: expectedProjectId, taskId, path = "assurance_proof" } = {},
) {
 const payload = normalizeEvidenceEnvelope(raw, {
 projectId: expectedProjectId,
 taskId,
 path,
 });
 const proof = record(payload.proof, `${path}.proof`);
 projectId(proof.project_id, expectedProjectId, `${path}.proof.project_id`);
 if (requiredText(proof.task_id, `${path}.proof.task_id`) !== taskId) {
 fail(`${path}.proof.task_id`, "does not match the selected task");
 }
 requiredText(proof.proof_id, `${path}.proof.proof_id`);
 const provenanceStatus = requiredText(proof.provenance_status, `${path}.proof.provenance_status`);
 if (!ASSURANCE_EVIDENCE_PROVENANCE_STATUSES.has(provenanceStatus)) {
 fail(`${path}.proof.provenance_status`, "must be an accepted server evidence authority status");
 }
 for (const field of [
 "failures",
 "skips",
 "open_high_risk_count",
 "closed_risks_lacking_evidence_count",
 ]) {
 nonNegativeInteger(proof[field], `${path}.proof.${field}`);
 }
 for (const field of [
 "subject_reconciliation_ok",
 "site_reconciliation_ok",
 "trial_reconciliation_ok",
 ]) {
 strictBoolean(proof[field], `${path}.proof.${field}`);
 }
 return { ...payload, project_id: String(expectedProjectId).trim(), task_id: taskId, proof };
}

export function normalizeAssuranceRollupPayload(
 raw,
 { projectId: expectedProjectId, taskId, path = "assurance_rollup" } = {},
) {
 const payload = normalizeEvidenceEnvelope(raw, {
 projectId: expectedProjectId,
 taskId,
 path,
 });
 const rollup = record(payload.rollup, `${path}.rollup`);
 projectId(rollup.project_id, expectedProjectId, `${path}.rollup.project_id`);
 if (requiredText(rollup.task_id, `${path}.rollup.task_id`) !== taskId) {
 fail(`${path}.rollup.task_id`, "does not match the selected task");
 }
 requiredText(rollup.risk_snapshot_id, `${path}.rollup.risk_snapshot_id`);
 array(rollup.subject_rollup, `${path}.rollup.subject_rollup`);
 array(rollup.site_rollup, `${path}.rollup.site_rollup`);
 record(rollup.trial_rollup, `${path}.rollup.trial_rollup`);
 record(rollup.distributions, `${path}.rollup.distributions`);
 array(rollup.remediation_matrix, `${path}.rollup.remediation_matrix`);
 array(rollup.evidence_manifest, `${path}.rollup.evidence_manifest`);
 requiredText(rollup.content_sha256, `${path}.rollup.content_sha256`);
 return { ...payload, project_id: String(expectedProjectId).trim(), task_id: taskId, rollup };
}

export function normalizeAssuranceCreateResponse(
 raw,
 { projectId: expectedProjectId, mode = "", path = "assurance_create" } = {},
) {
 const payload = envelope(raw, expectedProjectId, path);
 if (payload.replayed !== undefined) strictBoolean(payload.replayed, `${path}.replayed`);
 const task = normalizeAssuranceTask(payload.task, {
 projectId: expectedProjectId,
 path: `${path}.task`,
 });
 if (mode && task.mode !== mode) fail(`${path}.task.mode`, "does not match the requested assurance mode");
 return { ...payload, project_id: String(expectedProjectId).trim(), task };
}

export function normalizeAssuranceAuditPayload(
 raw,
 { projectId: expectedProjectId, taskId, path = "assurance_audit" } = {},
) {
 const payload = normalizeEvidenceEnvelope(raw, {
 projectId: expectedProjectId,
 taskId,
 path,
 });
 const principalId = requiredText(payload.principal_id, `${path}.principal_id`);
 const items = array(payload.items, `${path}.items`).map((item, index) => (
 normalizeAssuranceAuditEvent(item, {
 projectId: expectedProjectId,
 taskId,
 path: `${path}.items[${index}]`,
 })
 ));
 const auditIds = new Set();
 const eventHashes = new Set();
 for (let index = 1; index < items.length; index += 1) {
 if (items[index].aggregate_version_before !== items[index - 1].aggregate_version_after) {
 fail(`${path}.items[${index}].aggregate_version_before`, "does not continue the returned task version chain");
 }
 }
 items.forEach((item, index) => {
 if (auditIds.has(item.audit_id)) fail(`${path}.items[${index}].audit_id`, "is duplicated");
 if (eventHashes.has(item.event_hash)) fail(`${path}.items[${index}].event_hash`, "is duplicated");
 auditIds.add(item.audit_id);
 eventHashes.add(item.event_hash);
 });
 return {
 ...payload,
 project_id: String(expectedProjectId).trim(),
 task_id: String(taskId).trim(),
 principal_id: principalId,
 items,
 };
}

import assert from "node:assert/strict";
import {
 MedicalMonitoringAssuranceShapeError,
