 ...classification,
 content_warnings: ["需医学经理确认"],
 },
});
assert.equal(classificationDetail.classification.content_warnings.length, 1);

assert.throws(
 () => normalizeBatchList({ project_id: "project-1", batches: "not-an-array" }),
 MedicalMonitoringBatchShapeError,
);
assert.throws(
