import {
 monitoringRiskCategoryLabel,
 riskDispositionStatusLabel,
 riskStatusLabel,
 severityLabel,
} from "./medicalMonitoringModels.mjs";

const severityRank = { critical: 0, high: 1, medium: 2, low: 3 };

export class MedicalRiskProjectionError extends Error {}

function required(value, field) {
 if (typeof value !== "string") {
 throw new MedicalRiskProjectionError(`${field} must be a string`);
 }
 const text = value.trim();
 if (!text) throw new MedicalRiskProjectionError(`${field} is required`);
 return text;
}

function optionalText(value, field) {
 if (value === undefined || value === null || value === "") return "";
 if (typeof value !== "string") {
 throw new MedicalRiskProjectionError(`${field} must be a string`);
 }
 return value.trim();
}

function orderedUnique(values = [], field = "value") {
 if (values === undefined || values === null) return [];
 if (!Array.isArray(values)) {
 throw new MedicalRiskProjectionError(`${field} must be a string array`);
 }
 if (values.some((value) => typeof value !== "string" || !value.trim())) {
 throw new MedicalRiskProjectionError(`${field} must contain non-empty strings`);
 }
 return [...new Set(values.map((value) => value.trim()))]
 .sort((left, right) => left.localeCompare(right, "zh-CN", { numeric: true }));
}

function optionalNonNegativeInteger(value, field) {
 if (value === undefined || value === null || value === "") return null;
 if (typeof value !== "number" || !Number.isInteger(value) || value < 0) {
 throw new MedicalRiskProjectionError(`${field} must be a non-negative integer`);
 }
 return value;
}

function scopeIdentity(row) {
 const scopeType = required(row.scope_type ?? row.scopeType, "scope_type");
 const scopeId = required(row.scope_id ?? row.scopeId, "scope_id");
 const siteId = optionalText(row.site_id ?? row.siteId, "site_id");
 const subjectId = optionalText(row.subject_id ?? row.subjectId, "subject_id");
 if (!["trial", "site", "subject"].includes(scopeType)) {
 throw new MedicalRiskProjectionError(`unsupported scope_type: ${scopeType}`);
 }
 const trialId = optionalText(row.trial_id ?? row.trialId, "trial_id");
 if (scopeType === "trial" && (scopeId !== trialId || siteId || subjectId)) {
 throw new MedicalRiskProjectionError("trial scope identity is inconsistent");
 }
 if (scopeType === "site" && (scopeId !== siteId || subjectId)) {
 throw new MedicalRiskProjectionError("site scope identity is inconsistent");
 }
 if (scopeType === "subject" && (!siteId || scopeId !== subjectId)) {
 throw new MedicalRiskProjectionError("subject scope identity is incomplete");
 }
 return { scopeType, scopeId, siteId, subjectId };
}

function linkedViews(row) {
 const hasSnakeCase = Object.prototype.hasOwnProperty.call(row, "linked_views");
 const hasCamelCase = Object.prototype.hasOwnProperty.call(row, "linkedViews");
 const suppliedLinks = hasSnakeCase ? row.linked_views : hasCamelCase ? row.linkedViews : undefined;
 const links = suppliedLinks === undefined || suppliedLinks === null ? {} : suppliedLinks;
 if (!links || typeof links !== "object" || Array.isArray(links)) {
 throw new MedicalRiskProjectionError("linked_views must be an object");
 }
 return Object.fromEntries([
 ["timelineEventIds", links.timeline_event_ids ?? links.timelineEventIds],
 ["profileFieldIds", links.profile_field_ids ?? links.profileFieldIds],
 ["aeEventIds", links.ae_event_ids ?? links.aeEventIds],
 ["labEventIds", links.lab_event_ids ?? links.labEventIds],
 ["vitalsEventIds", links.vitals_event_ids ?? links.vitalsEventIds],
 ["ecgEventIds", links.ecg_event_ids ?? links.ecgEventIds],
 ["pdEventIds", links.pd_event_ids ?? links.pdEventIds],
 ].map(([key, value]) => [key, orderedUnique(value, `linked_views.${key}`)]));
}

function normalizeCanonicalRisk(row) {
 const riskInstanceId = required(row.risk_instance_id ?? row.riskInstanceId, "risk_instance_id");
 const projectId = required(row.project_id ?? row.projectId, "project_id");
 const trialId = required(row.trial_id ?? row.trialId, "trial_id");
 const identity = scopeIdentity({ ...row, trial_id: trialId });
 const findingClass = required(row.finding_class ?? row.findingClass, "finding_class");
 const categoryValue = row.category ?? row.risk_category_label ?? row.riskCategoryLabel;
 const category = monitoringRiskCategoryLabel(optionalText(categoryValue, "category"));
 const severity = required(row.severity, "severity");
 const status = required(row.status, "status");
 const dispositionState = optionalText(row.disposition_state ?? row.dispositionState, "disposition_state") || "pending_review";
 const sourceRevision = required(row.source_revision ?? row.sourceRevision, "source_revision");
 const ruleId = required(row.rule_id ?? row.ruleId, "rule_id");
 const title = required(row.title, "title");
 const evidenceIds = orderedUnique(row.evidence_ids ?? row.evidenceIds, "evidence_ids");
 const locators = orderedUnique(row.evidence_locators ?? row.evidenceLocators ?? row.source_locators, "evidence_locators");
 if (row.unread !== undefined && typeof row.unread !== "boolean") {
 throw new MedicalRiskProjectionError("unread must be a boolean");
 }
 const needsActionValue = row.needs_action ?? row.needsAction;
 if (needsActionValue !== undefined && typeof needsActionValue !== "boolean") {
 throw new MedicalRiskProjectionError("needs_action must be a boolean");
 }
 const unreadProvided = row.unread !== undefined;
 const needsActionProvided = needsActionValue !== undefined;
 const unread = row.unread === true;
 const needsAction = needsActionValue === true;
 const aggregateVersion = optionalNonNegativeInteger(
 row.aggregate_version ?? row.aggregateVersion,
 "aggregate_version",
 );
 return {
 riskInstanceId,
 riskKey: required(row.risk_key ?? row.riskKey, "risk_key"),
 projectId,
 trialId,
 scopeType: identity.scopeType,
 scopeId: identity.scopeId,
 siteId: identity.siteId,
 subjectId: identity.subjectId,
 category,
 findingClass,
 severity,
 severityLabel: severityLabel(severity),
 detectionStatus: status,
 detectionStatusLabel: riskStatusLabel(status),
 dispositionState,
 dispositionLabel: riskDispositionStatusLabel(dispositionState),
 unread,
 needsAction,
 title,
 rationale: optionalText(row.rationale, "rationale"),
 recommendedAction: optionalText(row.recommended_action ?? row.recommendedAction, "recommended_action"),
 queryDraftText: optionalText(row.query_draft_text ?? row.queryDraftText, "query_draft_text"),
 workflowFieldPresence: { unread: unreadProvided, needsAction: needsActionProvided },
 evidence: {
 sourceRevision,
 ruleProfileRevision: optionalText(row.rule_profile_revision ?? row.ruleProfileRevision, "rule_profile_revision"),
 engineVersion: optionalText(row.engine_version ?? row.engineVersion, "engine_version"),
 ruleId,
 evidenceIds,
 locators,
 },
 linkedViews: linkedViews(row),
 aggregateVersion,
 updatedAt: optionalText(row.updated_at ?? row.updatedAt, "updated_at"),
 };
}

function canonicalIdentity(row) {
 return JSON.stringify({
 riskInstanceId: row.riskInstanceId,
 projectId: row.projectId,
 trialId: row.trialId,
 scopeType: row.scopeType,
 scopeId: row.scopeId,
 siteId: row.siteId,
 subjectId: row.subjectId,
 });
}

function sortRiskRows(rows) {
 return [...rows].sort((left, right) => (
 (severityRank[left.severity] ?? 9) - (severityRank[right.severity] ?? 9)
 || String(left.siteId).localeCompare(String(right.siteId), "zh-CN", { numeric: true })
 || String(left.subjectId).localeCompare(String(right.subjectId), "zh-CN", { numeric: true })
 || left.riskInstanceId.localeCompare(right.riskInstanceId, "zh-CN", { numeric: true })
 ));
}

function countBy(rows, field) {
 return Object.fromEntries(
 [...rows.reduce((counts, row) => {
 const value = String(row[field] || "");
 counts.set(value, (counts.get(value) || 0) + 1);
 return counts;
 }, new Map()).entries()]
 .sort(([left], [right]) => left.localeCompare(right, "zh-CN", { numeric: true })),
 );
}

function rollup(rows) {
 const sorted = sortRiskRows(rows);
 return {
 riskCount: sorted.length,
 riskInstanceIds: sorted.map((row) => row.riskInstanceId),
 unreadCount: sorted.filter((row) => row.unread).length,
 needsActionCount: sorted.filter((row) => row.needsAction).length,
 severityCounts: countBy(sorted, "severity"),
 findingClassCounts: countBy(sorted, "findingClass"),
 dispositionCounts: countBy(sorted, "dispositionState"),
 categoryCounts: countBy(sorted, "category"),
 scopeCounts: countBy(sorted, "scopeType"),
 evidenceCoverage: evidenceCoverage(sorted),
 linkedViewCoverage: linkedViewCoverage(sorted),
 };
}

/**
 * Summarize only explicit evidence fields already normalized on canonical rows.
 * A reference ID is not promoted to a locator: both counts stay visible so a
 * reviewer can distinguish “can open the source” from “has an evidence ID”.
 */
function evidenceCoverage(rows) {
 const riskCount = rows.length;
 const locatorRiskCount = rows.filter((row) => row.evidence.locators.length > 0).length;
 const evidenceIdRiskCount = rows.filter((row) => row.evidence.evidenceIds.length > 0).length;
 const missingRiskCount = rows.filter(
 (row) => row.evidence.locators.length === 0 && row.evidence.evidenceIds.length === 0,
 ).length;
 const locatorCount = rows.reduce((total, row) => total + row.evidence.locators.length, 0);
 const evidenceIdCount = rows.reduce((total, row) => total + row.evidence.evidenceIds.length, 0);
 const status = riskCount === 0
 ? "empty"
 : locatorRiskCount === riskCount
 ? "bound"
 : locatorRiskCount > 0 || evidenceIdRiskCount > 0
 ? "partial"
 : "missing";
 return {
 status,
 riskCount,
 locatorRiskCount,
 evidenceIdRiskCount,
 missingRiskCount,
 locatorCount,
 evidenceIdCount,
 };
}

/**
 * Keep drill-through availability separate from source evidence coverage. A
 * linked view helps navigation, but it is not itself proof of source binding.
 */
function linkedViewCoverage(rows) {
 const linkValues = (row) => Object.values(row.linkedViews).flat();
 return {
 riskCount: rows.length,
 linkedRiskCount: rows.filter((row) => linkValues(row).length > 0).length,
 linkedReferenceCount: rows.reduce((total, row) => total + linkValues(row).length, 0),
 };
}

function groupRows(rows, field) {
 const groups = new Map();
 rows.forEach((row) => {
 const key = row[field];
 if (!key) return;
 if (!groups.has(key)) groups.set(key, []);
 groups.get(key).push(row);
 });
 return [...groups.entries()]
 .sort(([left], [right]) => String(left).localeCompare(String(right), "zh-CN", { numeric: true }))
 .map(([id, groupedRows]) => ({ id, ...rollup(groupedRows), rows: sortRiskRows(groupedRows) }));
}

/**
 * Normalize canonical authority rows and derive deterministic drilldown projections.
 * This is a read-only view model; it never writes or infers clinical meaning.
 */
export function projectCanonicalMedicalRisks(rows = []) {
 const byRiskInstance = new Map();
 rows.forEach((raw) => {
 const row = normalizeCanonicalRisk(raw);
 const previous = byRiskInstance.get(row.riskInstanceId);
 if (previous && (
 canonicalIdentity(previous) !== canonicalIdentity(row)
 || JSON.stringify(previous) !== JSON.stringify(row)
 )) {
 throw new MedicalRiskProjectionError(`risk_instance_id identity conflict: ${row.riskInstanceId}`);
 }
 if (!previous) byRiskInstance.set(row.riskInstanceId, row);
 });
 const normalized = sortRiskRows([...byRiskInstance.values()]);
 if (normalized.some((row) => row.projectId !== normalized[0]?.projectId || row.trialId !== normalized[0]?.trialId)) {
 throw new MedicalRiskProjectionError("projection cannot mix project or trial identities");
 }
 const projectRows = normalized;
 const sites = groupRows(normalized.filter((row) => row.siteId), "siteId");
 const subjects = groupRows(normalized.filter((row) => row.subjectId), "subjectId");
 const project = {
 ...rollup(projectRows),
 projectId: normalized[0]?.projectId || "",
 trialId: normalized[0]?.trialId || "",
 sites,
 unassignedRiskInstanceIds: normalized.filter((row) => !row.siteId).map((row) => row.riskInstanceId),
 };
 const siteAssignedRiskCount = sites.reduce((total, site) => total + site.riskCount, 0);
 const unassignedRiskCount = project.unassignedRiskInstanceIds.length;
 const sitePartitionRiskCount = siteAssignedRiskCount + unassignedRiskCount;
 const subjectScopedRiskCount = normalized.filter((row) => row.scopeType === "subject").length;
 const subjectProjectionRiskCount = subjects.reduce((total, subject) => total + subject.riskCount, 0);
 const hasRows = normalized.length > 0;
 const limitations = [];
 if (!normalized.length) limitations.push("empty_risk_set");
 if (normalized.some((row) => !row.workflowFieldPresence.needsAction)) {
 limitations.push("needs_action_not_explicitly_provided");
 }
 return {
 projectionStatus: normalized.length ? "ready" : "empty",
 limitations,
 project,
 sites,
 subjects,
 rows: normalized,
 scopeConservation: {
 projectRiskCount: normalized.length,
 siteAssignedRiskCount,
 unassignedRiskCount,
 sitePartitionRiskCount,
 sitePartitionStatus: !hasRows
 ? "empty"
 : sitePartitionRiskCount === normalized.length ? "conserved" : "not_conserved",
 subjectScopedRiskCount,
 subjectProjectionRiskCount,
 subjectProjectionStatus: !hasRows
 ? "empty"
 : subjectProjectionRiskCount === subjectScopedRiskCount ? "conserved" : "not_conserved",
 },
 progressiveDisclosure: {
 defaultVisible: ["title", "severity", "detectionStatus", "dispositionState", "scopeType", "scopeId"],
 evidenceFields: ["sourceRevision", "ruleProfileRevision", "engineVersion", "ruleId", "evidenceIds", "locators"],
 linkedViewFields: ["timelineEventIds", "profileFieldIds", "aeEventIds", "labEventIds", "vitalsEventIds", "ecgEventIds", "pdEventIds"],
 },
 };
}

import assert from "node:assert/strict";
import {
 MedicalRiskProjectionError,
 projectCanonicalMedicalRisks,
} from "./medicalMonitoringRiskProjection.mjs";

let passed = 0;
function check(condition, message) {
 assert.ok(condition, message);
 passed += 1;
}

const base = {
 project_id: "proj_rux_03_002",
 trial_id: "RUX-03-002",
 risk_key: "risk-key-001",
 risk_instance_id: "riskinst-001",
 scope_type: "subject",
 scope_id: "S01001",
 site_id: "01",
 subject_id: "S01001",
 category: "laboratory_abnormality",
 finding_class: "risk",
 severity: "high",
 status: "action_required",
 disposition_state: "pending_review",
 unread: true,
 needs_action: true,
 source_revision: "source-001",
 rule_profile_revision: "rules-001",
 engine_version: "engine-001",
 rule_id: "LAB-001",
 title: "实验室异常需复核",
 rationale: "原始数据与规则阈值关联。",
 recommended_action: "医学复核。",
 evidence_ids: ["listing:LB:row:1"],
 evidence_locators: ["listing:LB:row:1"],
 linked_views: {
 timeline_event_ids: ["event-lb-1"],
 profile_field_ids: ["profile-lb-1"],
 lab_event_ids: ["event-lb-1"],
 },
};

const secondSubject = {
 ...base,
 risk_key: "risk-key-002",
 risk_instance_id: "riskinst-002",
 scope_id: "S01002",
 subject_id: "S01002",
 severity: "medium",
 status: "in_review",
 disposition_state: "reviewed",
 unread: false,
 needs_action: false,
 title: "访视窗口需复核",
 rule_id: "VISIT-001",
 evidence_ids: ["listing:SV:row:2"],
 evidence_locators: [],
 linked_views: { timeline_event_ids: ["event-sv-2"], pd_event_ids: ["pd-2"] },
};

const siteRisk = {
 ...base,
 risk_key: "risk-key-003",
 risk_instance_id: "riskinst-003",
 scope_type: "site",
 scope_id: "02",
 site_id: "02",
 subject_id: "",
 severity: "low",
 status: "new",
 disposition_state: "pending_review",
 unread: true,
 needs_action: false,
 title: "中心数据完整性待观察",
 rule_id: "DATA-001",
 evidence_ids: ["listing:DM:row:3"],
 evidence_locators: [],
 linked_views: { profile_field_ids: ["site-data-02"] },
};

const projection = projectCanonicalMedicalRisks([
 base,
 { ...base },
 secondSubject,
 siteRisk,
]);

check(projection.rows.length === 3, "exact duplicate risk instance is counted once");
check(projection.project.riskCount === 3, "project rollup counts distinct risk instances");
check(projection.project.unreadCount === 2, "unread remains a workflow field");
check(projection.project.needsActionCount === 1, "needsAction is not inferred from severity");
check(projection.project.severityCounts.high === 1 && projection.project.severityCounts.medium === 1, "severity counts are conserved");
check(projection.sites.map((site) => site.id).join(",") === "01,02", "sites sort deterministically");
check(projection.sites[0].riskCount === 2 && projection.sites[1].riskCount === 1, "site drilldown conserves counts");
check(projection.subjects.map((subject) => subject.id).join(",") === "S01001,S01002", "subject drilldown is explicit and sorted");
check(projection.project.evidenceCoverage.status === "partial", "project evidence coverage distinguishes locators from references");
check(projection.project.evidenceCoverage.locatorRiskCount === 1, "project locator coverage counts only explicit locators");
check(projection.project.evidenceCoverage.evidenceIdRiskCount === 3, "project evidence ID coverage counts explicit references");
check(projection.sites[0].evidenceCoverage.locatorRiskCount === 1, "site rollup carries evidence coverage");
check(projection.subjects[1].evidenceCoverage.missingRiskCount === 0, "subject rollup keeps evidence IDs visible without calling them locators");
check(projection.scopeConservation.sitePartitionStatus === "conserved", "site-assigned plus unassigned risks conserve the project total");
check(projection.scopeConservation.subjectProjectionStatus === "conserved", "subject projection conserves subject-scoped risks");
check(projection.rows[0].findingClass === "risk" && projection.rows[0].dispositionState === "pending_review", "finding and disposition stay separate");
check(projection.rows[0].linkedViews.labEventIds[0] === "event-lb-1", "lab linkage is explicit");
check(projection.rows[1].linkedViews.pdEventIds[0] === "pd-2", "PD linkage is explicit");
check(projection.projectionStatus === "ready" && projection.limitations.length === 0, "complete input is explicitly ready");
check(projection.progressiveDisclosure.defaultVisible.includes("severity"), "default view is concise");
check(projection.progressiveDisclosure.evidenceFields.includes("locators"), "technical evidence is progressive disclosure");

for (const [field, value] of [
 ["risk_instance_id", true],
 ["project_id", 123],
 ["subject_id", false],
 ["evidence_ids", "evidence-scalar"],
 ["linked_views", ["not-an-object"]],
 ["linked_views", false],
 ["aggregate_version", "4"],
]) {
 assert.throws(
 () => projectCanonicalMedicalRisks([{ ...base, [field]: value }]),
 MedicalRiskProjectionError,
 `malformed ${field} is rejected`,
 );
}
assert.throws(
 () => projectCanonicalMedicalRisks([{ ...base, evidence_ids: ["evidence-ok", 2] }]),
 /evidence_ids must contain non-empty strings/,
);
assert.throws(
 () => projectCanonicalMedicalRisks([{ ...base, linked_views: { timeline_event_ids: false } }]),
 /linked_views\.timelineEventIds must be a string array/,
);
assert.throws(
 () => projectCanonicalMedicalRisks([{
 ...base,
 linked_views: false,
 linkedViews: { timeline_event_ids: ["should-not-fallback"] },
 }]),
 /linked_views must be an object/,
);
assert.throws(
 () => projectCanonicalMedicalRisks([{ ...base, needs_action: "false" }]),
 /needs_action must be a boolean/,
);

const limited = projectCanonicalMedicalRisks([{ ...base, needs_action: undefined }]);
check(limited.limitations.includes("needs_action_not_explicitly_provided"), "missing workflow input is visible as a limitation");
check(projectCanonicalMedicalRisks().projectionStatus === "empty", "empty input cannot present as a successful risk state");
check(projectCanonicalMedicalRisks().scopeConservation.sitePartitionStatus === "empty", "empty projection is not reported as conserved data");

const missingEvidence = projectCanonicalMedicalRisks([{
 ...siteRisk,
 risk_instance_id: "riskinst-missing-evidence",
 evidence_ids: [],
 evidence_locators: [],
 title: "来源证据缺失仍需显示风险",
}]);
check(missingEvidence.project.evidenceCoverage.status === "missing", "missing source evidence remains an explicit missing state");
check(missingEvidence.project.evidenceCoverage.missingRiskCount === 1, "missing source evidence is counted without implying no risk");

assert.throws(
 () => projectCanonicalMedicalRisks([{ ...base, risk_instance_id: "" }]),
 MedicalRiskProjectionError,
);
assert.throws(
 () => projectCanonicalMedicalRisks([{ ...base }, { ...base, severity: "critical" }]),
 /identity conflict/,
);
assert.throws(
 () => projectCanonicalMedicalRisks([base, { ...secondSubject, project_id: "proj_other" }]),
 /project or trial identities/,
);
assert.throws(
 () => projectCanonicalMedicalRisks([{ ...base, subject_id: "", site_id: "" }]),
 /subject scope identity is incomplete/,
);

console.log(`medicalMonitoringRiskProjection: ${passed} passed`);

export const MEDICAL_MONITORING_SCOPES = Object.freeze(["trial", "site", "subject"]);
export const MEDICAL_MONITORING_VIEWS = Object.freeze([
 "checklist",
 "timeline",
 "profile",
 "ae-mh",
 "evidence",
]);

export const MEDICAL_MONITORING_EVIDENCE_TABS = Object.freeze([
 "disposition",
 "timeline",
 "profile",
 "ae_mh",
 "sources",
 "history",
]);

export const MEDICAL_MONITORING_CHECKLIST_SORT_FIELDS = Object.freeze([
 "subject_id",
 "site_id",
 "severity",
 "risk_category_code",
 "risk_item",
 "disposition_status",
 "updated_at",
]);

export const MEDICAL_MONITORING_ROUTE_KEYS = Object.freeze([
 "project_id",
 "scope",
 "site_id",
 "subject_id",
 "risk_key",
 "risk_instance_id",
 "view",
 "protocol_version_id",
 "batch_id",
 "evidence_tab",
 "filter_subject_id",
 "filter_site_id",
 "filter_severity",
 "filter_risk_category_code",
 "filter_risk_item",
 "filter_disposition_status",
 "filter_updated_at",
 "risk_sort_by",
 "risk_sort_direction",
 "risk_page",
 "risk_page_size",
 "risk_scroll_top",
 "risk_snapshot_id",
]);

export const MEDICAL_MONITORING_RISK_FOCUS_KEYS = Object.freeze([
 "risk_key",
 "risk_instance_id",
 "evidence_tab",
]);

const SCOPE_SET = new Set(MEDICAL_MONITORING_SCOPES);
const VIEW_SET = new Set(MEDICAL_MONITORING_VIEWS);
const EVIDENCE_TAB_SET = new Set(MEDICAL_MONITORING_EVIDENCE_TABS);
const CHECKLIST_SORT_SET = new Set(MEDICAL_MONITORING_CHECKLIST_SORT_FIELDS);
const SEVERITY_SET = new Set(["critical", "high", "medium", "low"]);
const SORT_DIRECTION_SET = new Set(["asc", "desc"]);

function routeParams(input) {
 if (input instanceof URLSearchParams) return new URLSearchParams(input);
 if (input instanceof URL) return new URLSearchParams(input.searchParams);
 if (input && typeof input === "object" && typeof input.search === "string") {
 return new URLSearchParams(input.search);
 }
 const raw = typeof input === "string" ? input.trim() : "";
 if (!raw) return new URLSearchParams();
 if (/^[a-z][a-z\d+.-]*:\/\//i.test(raw)) {
 return new URL(raw).searchParams;
 }
 return new URLSearchParams(raw.startsWith("?") ? raw.slice(1) : raw);
}

function cleanValue(value) {
 if (value === null || value === undefined) return "";
 return String(value).trim();
}

function projectIdFromCandidate(candidate) {
 if (typeof candidate === "string") return cleanValue(candidate);
 if (!candidate || typeof candidate !== "object") return "";
 return cleanValue(candidate.project_id);
}

/**
 * Resolve a risk deep link only against records already scoped to the current
 * project. An absent match is explicit so the UI can explain the boundary
 * instead of silently opening a different risk.
 */
export function resolveMedicalMonitoringRiskRoute(
 requestedRiskId,
 visibleRiskRows = [],
 fetchedRiskRows = [],
) {
 const requested = cleanValue(requestedRiskId);
 if (!requested) return Object.freeze({ status: "none", risk: null, requestedRiskId: "" });
 const candidates = [
 ...(Array.isArray(visibleRiskRows) ? visibleRiskRows : []),
 ...(Array.isArray(fetchedRiskRows) ? fetchedRiskRows : []),
 ];
 const risk = candidates.find((candidate) => (
 [candidate?.id, candidate?.risk_instance_id, candidate?.risk_key, candidate?.riskKey]
 .map(cleanValue)
 .includes(requested)
 )) || null;
 return Object.freeze({
 status: risk ? "matched" : "unavailable",
 risk,
 requestedRiskId: requested,
 });
}

/**
 * Resolve a monitoring deep-link project without ever substituting a
 * different project for an explicitly requested one. The result is pure so
 * App-level hydration can fail closed before any project-scoped read starts.
 */
export function resolveMedicalMonitoringProjectRoute(
 requestedProjectId,
 projects = [],
 currentProjectId = "",
 fallbackProjectId = "",
) {
 const requested = cleanValue(requestedProjectId);
 const available = [];
 const seen = new Set();
 (Array.isArray(projects) ? projects : []).forEach((candidate) => {
 const projectId = projectIdFromCandidate(candidate);
 if (projectId && !seen.has(projectId)) {
 seen.add(projectId);
 available.push(projectId);
 }
 });
 if (requested) {
 return Object.freeze({
 status: available.includes(requested) ? "matched" : "unavailable",
 projectId: available.includes(requested) ? requested : "",
 requestedProjectId: requested,
 });
 }
 const current = cleanValue(currentProjectId);
 if (current && available.includes(current)) {
 return Object.freeze({ status: "current", projectId: current, requestedProjectId: "" });
 }
 const fallback = cleanValue(fallbackProjectId);
 if (fallback && available.includes(fallback)) {
 return Object.freeze({ status: "fallback", projectId: fallback, requestedProjectId: "" });
 }
 return Object.freeze({
 status: available.length ? "default" : "empty",
 projectId: available[0] || "",
 requestedProjectId: "",
 });
}

function subjectIdFromCandidate(candidate) {
 if (typeof candidate === "string") return cleanValue(candidate);
 if (!candidate || typeof candidate !== "object") return "";
 return cleanValue(candidate.id ?? candidate.subject_id);
}

/**
 * Resolve a subject deep link against the current project's subject catalog.
 * An explicit non-member is unavailable rather than silently replaced by the
 * first subject in the catalog.
 */
export function resolveMedicalMonitoringSubjectRoute(
 requestedSubjectId,
 subjects = [],
 currentSubjectId = "",
 fallbackSubjectId = "",
) {
 const requested = cleanValue(requestedSubjectId);
 const available = [];
 const seen = new Set();
 (Array.isArray(subjects) ? subjects : []).forEach((candidate) => {
 const subjectId = subjectIdFromCandidate(candidate);
 if (subjectId && !seen.has(subjectId)) {
 seen.add(subjectId);
 available.push(subjectId);
 }
 });
 if (requested) {
 return Object.freeze({
 status: available.includes(requested) ? "matched" : "unavailable",
 subjectId: available.includes(requested) ? requested : "",
 requestedSubjectId: requested,
 });
 }
 const current = cleanValue(currentSubjectId);
 if (current && available.includes(current)) {
 return Object.freeze({ status: "current", subjectId: current, requestedSubjectId: "" });
 }
 const fallback = cleanValue(fallbackSubjectId);
 if (fallback && available.includes(fallback)) {
 return Object.freeze({ status: "fallback", subjectId: fallback, requestedSubjectId: "" });
 }
 return Object.freeze({
 status: available.length ? "default" : "empty",
 subjectId: available[0] || "",
 requestedSubjectId: "",
 });
}

function siteIdFromCandidate(candidate) {
 if (!candidate || typeof candidate !== "object") return "";
 return cleanValue(candidate.site_id ?? candidate.site ?? candidate.scope_id);
}

/**
 * Resolve a site deep link against the current project's subject catalog and
 * risk rollups. Empty candidate lists remain pending so an unready read is
 * not misreported as a missing center.
 */
export function resolveMedicalMonitoringSiteRoute(
 requestedSiteId,
 subjects = [],
 riskRollups = [],
) {
 const requested = cleanValue(requestedSiteId);
 if (!requested) return Object.freeze({ status: "none", siteId: "", requestedSiteId: "" });
 const candidates = [
 ...(Array.isArray(subjects) ? subjects : []),
 ...(Array.isArray(riskRollups) ? riskRollups : []),
 ].map(siteIdFromCandidate).filter(Boolean);
 const unique = [...new Set(candidates)];
 if (unique.includes(requested)) {
 return Object.freeze({ status: "matched", siteId: requested, requestedSiteId: requested });
 }
 return Object.freeze({
 status: unique.length ? "unavailable" : "pending",
 siteId: "",
 requestedSiteId: requested,
 });
}

function setWhenPresent(target, key, value) {
 const clean = cleanValue(value);
 if (clean) target[key] = clean;
}

export function normalizeMedicalMonitoringRouteState(input = {}) {
 const source = input && typeof input === "object" ? input : {};
 const normalized = {};

 setWhenPresent(normalized, "project_id", source.project_id);
 setWhenPresent(normalized, "site_id", source.site_id);
 setWhenPresent(normalized, "subject_id", source.subject_id);
 setWhenPresent(normalized, "risk_key", source.risk_key);
 setWhenPresent(normalized, "risk_instance_id", source.risk_instance_id);
 setWhenPresent(normalized, "protocol_version_id", source.protocol_version_id);
 setWhenPresent(normalized, "batch_id", source.batch_id);
 setWhenPresent(normalized, "filter_subject_id", source.filter_subject_id);
 setWhenPresent(normalized, "filter_site_id", source.filter_site_id);
 setWhenPresent(normalized, "filter_risk_category_code", source.filter_risk_category_code);
 setWhenPresent(normalized, "filter_risk_item", source.filter_risk_item);
 setWhenPresent(normalized, "filter_disposition_status", source.filter_disposition_status);
 setWhenPresent(normalized, "filter_updated_at", source.filter_updated_at);
 setWhenPresent(normalized, "risk_snapshot_id", source.risk_snapshot_id);

 const severity = cleanValue(source.filter_severity).toLowerCase();
 if (SEVERITY_SET.has(severity)) normalized.filter_severity = severity;

 const evidenceTab = cleanValue(source.evidence_tab).toLowerCase();
 if (EVIDENCE_TAB_SET.has(evidenceTab)) normalized.evidence_tab = evidenceTab;

 const sortBy = cleanValue(source.risk_sort_by).toLowerCase();
 if (CHECKLIST_SORT_SET.has(sortBy)) normalized.risk_sort_by = sortBy;
 const sortDirection = cleanValue(source.risk_sort_direction).toLowerCase();
 if (SORT_DIRECTION_SET.has(sortDirection)) {
 normalized.risk_sort_direction = sortDirection;
 }

 const page = Number.parseInt(cleanValue(source.risk_page), 10);
 if (Number.isInteger(page) && page > 1) normalized.risk_page = String(page);
 const pageSize = Number.parseInt(cleanValue(source.risk_page_size), 10);
 if (Number.isInteger(pageSize) && pageSize >= 1 && pageSize <= 200 && pageSize !== 50) {
 normalized.risk_page_size = String(pageSize);
 }
 const scrollTop = Number.parseInt(cleanValue(source.risk_scroll_top), 10);
 if (Number.isInteger(scrollTop) && scrollTop >= 1 && scrollTop <= 1_000_000) {
 normalized.risk_scroll_top = String(scrollTop);
 }

 const requestedScope = cleanValue(source.scope).toLowerCase();
 const requestedView = cleanValue(source.view).toLowerCase();
 const hasValidScope = SCOPE_SET.has(requestedScope);
 const hasValidView = VIEW_SET.has(requestedView);
 const hasFocus = Object.keys(normalized).length > 0 || hasValidScope || hasValidView;
 let scope = hasValidScope ? requestedScope : "";
 if (!scope && hasFocus) {
 scope = normalized.subject_id ? "subject" : normalized.site_id ? "site" : "trial";
 }

 if (scope === "trial") {
 delete normalized.site_id;
 delete normalized.subject_id;
 } else if (scope === "site") {
 delete normalized.subject_id;
 if (!normalized.site_id) scope = "trial";
 } else if (scope === "subject" && !normalized.subject_id) {
 scope = normalized.site_id ? "site" : "trial";
 }
 if (scope) normalized.scope = scope;

 let view = hasValidView ? requestedView : "";
 if (["timeline", "profile"].includes(view) && !normalized.subject_id) {
 view = "checklist";
 }
 if (
 view === "evidence"
 && !normalized.risk_key
 && !normalized.risk_instance_id
 ) {
 view = "checklist";
 }
 if (view) normalized.view = view;

 return normalized;
}

export function parseMedicalMonitoringRouteState(search = "") {
 const params = routeParams(search);
 const candidate = {};
 MEDICAL_MONITORING_ROUTE_KEYS.forEach((key) => {
 if (params.has(key)) candidate[key] = params.get(key);
 });
 return normalizeMedicalMonitoringRouteState(candidate);
}

function replaceMonitoringParams(params, state) {
 MEDICAL_MONITORING_ROUTE_KEYS.forEach((key) => params.delete(key));
 const normalized = normalizeMedicalMonitoringRouteState(state);
 MEDICAL_MONITORING_ROUTE_KEYS.forEach((key) => {
 if (normalized[key]) params.set(key, normalized[key]);
 });
 return params;
}

export function serializeMedicalMonitoringRouteState(state, baseSearch = "") {
 const params = replaceMonitoringParams(routeParams(baseSearch), state);
 const query = params.toString();
 return query ? `?${query}` : "";
}

export function mergeMedicalMonitoringRouteState(search, patch = {}) {
 const current = parseMedicalMonitoringRouteState(search);
 return serializeMedicalMonitoringRouteState(
 { ...current, ...(patch || {}) },
 search,
 );
}

export function clearMedicalMonitoringRiskFocusState(input = {}) {
 const next = { ...normalizeMedicalMonitoringRouteState(input) };
 MEDICAL_MONITORING_RISK_FOCUS_KEYS.forEach((key) => delete next[key]);
 return normalizeMedicalMonitoringRouteState(next);
}

export function clearMedicalMonitoringRouteState(search = "") {
 const params = routeParams(search);
 MEDICAL_MONITORING_ROUTE_KEYS.forEach((key) => params.delete(key));
 const query = params.toString();
 return query ? `?${query}` : "";
}

