const ROLE_LABELS = {
 recommended: "推荐方案",
 alternative: "备选方案",
 pending_decision: "需您选择/补全",
};

const CONFIDENCE_LABELS = {
 high: "高",
 medium: "中",
 low: "低",
 none: "无",
};

const RECEIPT_CATEGORY_LABELS = {
 applied: "已应用",
 overridden: "已按您的修改写入",
 derived: "联动派生",
 skipped: "已跳过",
 invalidated: "依赖需重新核验",
};

export function packageFieldLabel(fieldPath) {
 const path = String(fieldPath || "").trim();
 if (!path) return "相关字段";
 if (PACKAGE_FIELD_LABELS[path]) return PACKAGE_FIELD_LABELS[path];
 const last = path.split(".").pop() || path;
 if (/[A-Za-z]/.test(path)) {
 return `相关字段（${last.replaceAll("_", " ")}）`;
 }
 return path;
}

export function resolvePathLabel(fieldPath, pathLabels = {}) {
 const path = String(fieldPath || "").trim();
 if (!path) return "相关字段";
 const fromMap = pathLabels[path];
 if (fromMap && fromMap !== path) return fromMap;
 return packageFieldLabel(path);
}

export function isCompositePrefillGroup(group) {
 const candidates = group?.candidates || [];
 return candidates.some(
 (item) => item?.candidate_scope === "module" || item?.candidate_scope === "design_package",
 );
}

// Mirrors services/api/app/medical_writing_authoring_prefill_ai.py::
// _UNSUPPORTED_SUBSTANTIVE_GAP_PREFIX. The backend serializes candidate
// attributes with model defaults, so an absent adoption_mode/evidence_status
// is treated as its restrictive default (manual_only / insufficient) to stay
// fail-closed.
const UNSUPPORTED_SUBSTANTIVE_GAP_PREFIX = "声称内容未在引用原文中出现：";

const COMPOSITE_BLOCK_REASON_LABELS = {
 unavailable: "候选不可用。",
 pending_decision: "该候选含待确认项；请对每个字段填写确认值或勾选跳过。",
 manual_only: "该候选标注为需逐项确认（manual_only）；请对每个字段填写确认值或勾选跳过。",
 insufficient: "该候选证据不足（insufficient）；请对每个字段填写确认值或勾选跳过。",
 unsupported_gap: "该候选存在未被来源原文支持的实质声明；请对每个字段填写确认值或勾选跳过。",
};

/**
 * Stable machine code for why a candidate cannot be adopted without per-path
 * decisions, or "" when the candidate is safe. Mirrors the backend per-path
 * gate (``_composite_path_policy_restricted`` in
 * medical_writing_authoring_prefill.py): pending_decision role, manual_only
 * adoption mode, insufficient evidence status, or an unsupported-substantive
 * evidence gap all require an explicit override or explicit skip for every
 * contributed target path. ``batch_allowed`` + supported + gap-free
 * candidates are safe and remain zero-override adoptable.
 */
export function compositeCandidateBlockedCode(candidate) {
 if (!candidate) return "unavailable";
 if (candidate.recommendation_role === "pending_decision") return "pending_decision";
 if (String(candidate.preview || "").includes("待确认")) return "pending_decision";
 const adoptionMode = String(candidate.adoption_mode || "").trim() || "manual_only";
 if (adoptionMode === "manual_only") return "manual_only";
 const evidenceStatus = String(candidate.evidence_status || "").trim() || "insufficient";
 if (evidenceStatus === "insufficient") return "insufficient";
 if ((candidate.evidence_gaps || []).some(
 (gap) => String(gap).startsWith(UNSUPPORTED_SUBSTANTIVE_GAP_PREFIX),
 )) {
 return "unsupported_gap";
 }
 return "";
}

/**
 * Human-readable reason a composite candidate cannot be adopted without
 * per-path decisions, or "" when the candidate is safe.
 */
export function compositeCandidateBlockedReason(candidate) {
 const code = compositeCandidateBlockedCode(candidate);
 return COMPOSITE_BLOCK_REASON_LABELS[code] || "";
}

/**
 * Pending-like gating: a candidate is pending-like when it is restricted
 * (see ``compositeCandidateBlockedReason``). Pending-like candidates must
 * never fill the recommended slot, must not be auto-selected, and require an
 * explicit decision on every contributed target path before adoption.
 */
export function isPendingCompositeCandidate(candidate) {
 return Boolean(compositeCandidateBlockedReason(candidate));
}

function looksLikeEnglishPath(path, label) {
 if (label && label !== path) return false;
 return /[A-Za-z]/.test(String(path || ""));
}

export function moduleIncludeLines(candidate, pathLabels = {}) {
 const fromPreview = String(candidate?.preview || "")
 .split(/[；;\n]+/)
 .map((item) => item.trim())
 .filter(Boolean);
 if (fromPreview.length > 1) return fromPreview;
 const fromTargets = (candidate?.target_paths || []).map((path) => resolvePathLabel(path, pathLabels));
 if (fromTargets.length) return fromTargets;
 return fromPreview;
}

export function compactCandidatePreview(candidate, maxSegments = 4) {
 const segments = String(candidate?.preview || "")
 .split(/[；;\n]+/)
 .map((item) => item.trim())
 .filter(Boolean);
 if (!segments.length) return packageFieldLabel(candidate?.field_path);
 if (segments.length <= maxSegments) return segments.join("；");
 return `${segments.slice(0, maxSegments).join("；")}；其余设计已纳入整包建议`;
}

const STRUCTURED_VALUE_KEY_LABELS = Object.freeze({
 enabled: "启用状态",
 planned: "计划状态",
 features: "具体特征",
 labels: "标签",
 mode: "模式",
 model: "模式",
 type: "类型",
 blinded_roles: "盲态角色",
 purpose: "用途",
 src: "SRC",
 dmc: "DMC",
 parts: "研究Part",
 sequence: "序列",
 available_part_types: "可选Part类型",
});

const STRUCTURED_VALUE_ENUM_LABELS = Object.freeze({
 randomized: "随机",
 non_randomized: "非随机",
 open_label: "开放标签",
 single_blind: "单盲",
 double_blind: "双盲",
 triple_blind: "三盲",
 placebo: "安慰剂对照",
 active: "阳性/活性对照",
 none_or_dose_escalation: "无对照/剂量递增",
 planned: "计划",
 unplanned: "不计划",
 undecided: "待确认",
});

function structuredValueKeyLabel(key) {
 return STRUCTURED_VALUE_KEY_LABELS[key]
 || String(key || "").replaceAll("_", " ");
}

function humanizeStructuredValue(value) {
 if (value == null || value === "") return "待确认";
 if (typeof value === "boolean") return value ? "是" : "否";
 if (typeof value === "number") return String(value);
 if (typeof value === "string") {
 return STRUCTURED_VALUE_ENUM_LABELS[value] || value;
 }
 if (Array.isArray(value)) {
 if (!value.length) return "未设置";
 return value.map((item) => humanizeStructuredValue(item)).join("、");
 }
 if (typeof value === "object") {
 const entries = Object.entries(value).filter(([, item]) => item !== undefined);
 if (!entries.length) return "未设置";
 return entries
 .map(([key, item]) => `${structuredValueKeyLabel(key)}：${humanizeStructuredValue(item)}`)
 .join("；");
 }
 return String(value);
}

export function collectCompositePrefillGroups(prefillPackage) {
 return Object.values(prefillPackage?.field_candidates || {})
 .filter(isCompositePrefillGroup)
 .sort((left, right) => String(left.field_path).localeCompare(String(right.field_path)));
}

export function sortCompositeCandidates(group) {
 const candidates = [...(group?.candidates || [])];
 const recommendedId = group?.recommended_candidate_id;
 const recommendedById = candidates.find((item) => item.candidate_id === recommendedId);
 // Empty recommendation stays empty: the server deliberately leaves
 // recommended_candidate_id="" when no candidate is safe to recommend, and
 // a slot that points at a pending-like candidate is no recommendation
 // either. Never promote the first non-pending alternative into the slot.
 const recommended = recommendedById && !isPendingCompositeCandidate(recommendedById)
 ? recommendedById
 : null;
 candidates.sort((left, right) => {
 if (recommended) {
 if (left.candidate_id === recommended.candidate_id) return -1;
 if (right.candidate_id === recommended.candidate_id) return 1;
 }
 const leftPending = isPendingCompositeCandidate(left);
 const rightPending = isPendingCompositeCandidate(right);
 if (!leftPending && rightPending) return -1;
 if (leftPending && !rightPending) return 1;
 if (left.recommendation_role === "recommended" && right.recommendation_role !== "recommended") return -1;
 if (right.recommendation_role === "recommended" && left.recommendation_role !== "recommended") return 1;
 return String(left.candidate_id).localeCompare(String(right.candidate_id));
 });
 const alternatives = candidates
 .filter((item) => item.candidate_id !== recommended?.candidate_id)
 .slice(0, 4);
 const displayCandidates = recommended
 ? [recommended, ...alternatives].filter(Boolean)
 : candidates.slice(0, 5);
 return { recommended, alternatives, displayCandidates };
}

export function formatPathValue(value) {
 if (value == null) return "";
 if (typeof value === "string") return value;
 if (typeof value === "number" || typeof value === "boolean") return String(value);
 if (Array.isArray(value)) {
 if (!value.length) return "（空列表）";
 return value.map((item) => humanizeStructuredValue(item)).join("；");
 }
 return humanizeStructuredValue(value);
}

/**
 * Paths a pending-like (restricted) candidate needs an explicit decision on
 * before adoption. The backend per-path gate requires an override or
 * explicit skip for EVERY contributed target path of a restricted
 * candidate — AI-resolved values are never carried as implicit overrides.
 * Safe candidates return an empty list (zero-override adoption).
 */
export function compositeDecisionPaths(candidate) {
 if (!isPendingCompositeCandidate(candidate)) return [];
 return (candidate?.target_paths || []).filter(Boolean);
}

export function hasUsableSourceText(evidenceRefs = []) {
 return (evidenceRefs || []).some((item) => String(item?.source_text || "").trim());
}

/**
 * Adoption readiness mirrors the backend composite per-path gate: safe
 * candidates (batch_allowed + supported + gap-free) may submit without
 * per-path drafts; pending-like candidates (pending_decision / manual_only /
 * insufficient / unsupported-substantive-gap) require an explicit override
 * or explicit skip on EVERY contributed target path before the adopt action
 * may be enabled — the UI never shows an enabled action that is guaranteed
 * to be policy-rejected.
 */
export function compositeAdoptionReady(candidate, pathOverrides = {}, pathSkips = {}) {
 if (!candidate) return false;
 const targets = candidate.target_paths || [];
 if (!targets.length) return false;
 if (!isPendingCompositeCandidate(candidate)) return true;
 return compositeDecisionPaths(candidate).every((path) => {
 if (pathSkips[path]) return true;
 if (!(path in pathOverrides)) return false;
 const value = pathOverrides[path];
 if (value == null) return false;
 if (typeof value === "string") return value.trim().length > 0;
 if (Array.isArray(value)) return value.length > 0;
 return true;
 });
}

export function splitCompositeListValue(value) {
 const seen = new Set();
 return String(value || "")
 .split(/[\n；;]+/)
 .map((item) => item.trim())
 .filter((item) => {
 if (!item || seen.has(item)) return false;
 seen.add(item);
 return true;
 });
}

function stableManualInstrumentId(value) {
 let hash = 2166136261;
 for (const character of value) {
 hash ^= character.codePointAt(0);
 hash = Math.imul(hash, 16777619);
 }
 return `manual_instrument_${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function serializeAssessmentInstrumentItems(items) {
 return items.map((item) => {
 if (item.startsWith("{") && item.endsWith("}")) {
 try {
 const parsed = JSON.parse(item);
 if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) return parsed;
 } catch {
 // Keep malformed JSON-like input as the user's instrument name.
 }
 }
 return {
 instrument_id: stableManualInstrumentId(item),
 canonical_name_zh: item,
 instrument_kind: "other",
 confirmation_status: "candidate",
 };
 });
}

export function serializeCompositePathOverride(candidate, path, value) {
 if (typeof value !== "string") return value;
 const trimmed = value.trim();
 if (!trimmed) return "";
 const candidateValue = candidate?.structured_value?.[path];
 if (!Array.isArray(candidateValue)) return trimmed;

 const items = splitCompositeListValue(value);
 const hasStructuredItems = candidateValue.some(
 (item) => item && typeof item === "object" && !Array.isArray(item),
 );
 if (hasStructuredItems || path === "picos.assessment_instruments") {
 return serializeAssessmentInstrumentItems(items);
 }
 return items;
}

/** Build request path_overrides: only non-skipped entries with real values. */
export function buildCompositePathOverrides(candidate, pathOverrides = {}, pathSkips = {}) {
 const result = {};
 for (const path of candidate?.target_paths || []) {
 if (pathSkips[path]) {
 delete result[path];
 continue;
 }
 if (!(path in pathOverrides)) continue;
 const value = pathOverrides[path];
 if (value == null) continue;
 if (typeof value === "string") {
 const serialized = serializeCompositePathOverride(candidate, path, value);
 if (serialized === "" || (Array.isArray(serialized) && !serialized.length)) continue;
 result[path] = serialized;
 continue;
 }
 result[path] = value;
 }
 return result;
}

export function collectExplicitCompositeSkips(candidate, pathSkips = {}) {
 return (candidate?.target_paths || []).filter((path) => Boolean(pathSkips[path]));
}

export function receiptSummaryMessage(receipt) {
 if (!receipt) return "";
 if (receipt.replayed) return "已应用（幂等回放）";
 if (receipt.package_marked_stale) return "建议包已标记为需更新，请重新生成后再采用。";
 const applied = receipt.applied_paths?.length || 0;
 const overridden = receipt.overridden_paths?.length || 0;
 const skipped = receipt.skipped_paths?.length || 0;
 return `组合采用完成：应用${applied}项，修改${overridden}项，跳过${skipped}项。`;
}

function EvidenceBlock({ evidenceRefs = [] }) {
 const withText = (evidenceRefs || []).filter((item) => String(item?.source_text || "").trim());
 const withoutText = (evidenceRefs || []).filter((item) => !String(item?.source_text || "").trim());
 if (!withText.length && !withoutText.length) {
 return null;
 }
 return (
 <div className="authoring-package-evidence" data-evidence-status={withText.length ? "has-source-text" : "insufficient"}>
 {withText.map((item, index) => (
 <blockquote key={`${item.source_id || "src"}-${index}`} className="authoring-package-source-text">
 <span>竞品实践 / 来源原文</span>
 <p>{item.source_text}</p>
 </blockquote>
 ))}
 {!withText.length && (
 <div className="authoring-package-evidence insufficient">
 <span>证据不足</span>
 <p>暂无可用的竞品原文；仅有定位信息时不视为已展示证据。</p>
 </div>
 )}
 {(withoutText.length > 0 || withText.some((item) => item.locator || item.source_id)) && (
 <details className="authoring-package-trace-details">
 <summary>溯源详情（定位/哈希，默认折叠）</summary>
 <ul>
 {(evidenceRefs || []).map((item, index) => (
 <li key={`trace-${item.source_id || index}`}>
 <strong>{item.source_kind || "来源"}</strong>
 <small>{item.locator || item.source_id || "无定位"}</small>
 </li>
 ))}
 </ul>
 </details>
 )}
 </div>
 );
}

function PathDecisionRow({
 path,
 label,
 candidateValue,
 overrideValue,
 skipped,
 allowSkip = false,
 disabled,
 onOverrideChange,
 onSkipToggle,
}) {
 const displayValue = formatPathValue(candidateValue);
 const primaryLabel = label && label !== path ? label : packageFieldLabel(path);
 const listValued = Array.isArray(candidateValue);
 const overridePlaceholder = listValued
 ? path === "picos.assessment_instruments"
 ? "每行或用分号分隔一个量表/评估工具"
 : "每行或用分号分隔一项；空项和重复项会被忽略"
 : "填写后采用您的表述；留空且不跳过则待补全";
 return (
 <div className={`authoring-package-path-row ${skipped ? "skipped" : ""}`} data-target-path={path}>
 <div className="authoring-package-path-head">
 <strong title={path}>{primaryLabel}</strong>
 </div>
 <div className="authoring-package-path-candidate">
 <span>建议值</span>
 <p>{displayValue || "（空）"}</p>
 </div>
 <label className="authoring-package-path-override">
 <span>您的确认/修改</span>
 <textarea
 rows={2}
 value={typeof overrideValue === "string" ? overrideValue : overrideValue == null ? "" : formatPathValue(overrideValue)}
 onChange={(event) => onOverrideChange(path, event.target.value)}
 disabled={disabled || skipped}
 placeholder={overridePlaceholder}
 aria-label={`${primaryLabel}确认或修改`}
 />
 </label>
 {allowSkip && (
 <label className="authoring-package-path-skip">
 <input
 type="checkbox"
 checked={Boolean(skipped)}
 onChange={() => onSkipToggle(path)}
 disabled={disabled}
 />
 <span>本次跳过该字段</span>
 </label>
 )}
 </div>
 );
}

function CompositeReceiptPanel({ receipt }) {
 if (!receipt) return null;
 const skippedItems = (receipt.skipped_paths || []).map((item) => (
 typeof item === "string" ? { path: item, reason: "" } : item
 ));
 const categories = [
 { key: "applied", paths: receipt.applied_paths || [], className: "applied" },
 { key: "overridden", paths: receipt.overridden_paths || [], className: "overridden" },
 { key: "derived", paths: receipt.derived_paths || [], className: "derived" },
 {
 key: "skipped",
 paths: skippedItems.map((item) => item.path),
 className: "skipped",
 details: skippedItems,
 },
 { key: "invalidated", paths: receipt.invalidated_dependents || [], className: "invalidated" },
 ].filter((item) => item.paths.length > 0 || (item.key === "skipped" && item.details?.length));

 return (
 <section
 className={`authoring-package-receipt ${receipt.replayed ? "replayed" : ""} ${receipt.package_marked_stale ? "stale" : ""}`}
 data-testid="composite-adopt-receipt"
 data-replayed={receipt.replayed ? "true" : "false"}
 data-package-stale={receipt.package_marked_stale ? "true" : "false"}
 aria-live="polite"
 >
 <header>
 <CheckCircle2 size={15} />
 <div>
 <strong>{receiptSummaryMessage(receipt)}</strong>
 <small>
 {packageFieldLabel(receipt.package_field_path) || "组合候选"}
 {receipt.candidate_id ? ` · ${receipt.candidate_id}` : ""}
 {receipt.journey_revision_after ? ` · 修订 ${receipt.journey_revision_before}→${receipt.journey_revision_after}` : ""}
 </small>
 </div>
 </header>
 {receipt.replayed && <p className="authoring-package-receipt-flag replayed" data-receipt-flag="replayed">已应用（幂等回放）</p>}
 {receipt.package_marked_stale && <p className="authoring-package-receipt-flag stale" data-receipt-flag="stale">建议包已过期或标记为需更新，请重新生成后再继续采用。</p>}
 {categories.length > 0 && (
 <details className="authoring-package-receipt-categories">
 <summary>写入明细（默认折叠）</summary>
 <div className="authoring-package-receipt-categories-body">
 {categories.map((category) => (
 <div key={category.key} className={`authoring-package-receipt-category ${category.className}`} data-receipt-category={category.key}>
 <strong>{RECEIPT_CATEGORY_LABELS[category.key]}</strong>
 <ul>
 {category.key === "skipped"
 ? (category.details || []).map((item) => (
 <li key={item.path}>
 <span>{resolvePathLabel(item.path)}</span>
 {item.reason ? <small>{item.reason}</small> : null}
 </li>
 ))
 : category.paths.map((path) => <li key={path}>{resolvePathLabel(path)}</li>)}
 </ul>
 </div>
 ))}
 </div>
 </details>
 )}
 </section>
 );
}

function CandidateCard({
 candidate,
 isRecommended,
 selected,
 pathLabels,
 pathOverrides,
 pathSkips,
 readOnly,
 busy,
 onSelect,
 onOverrideChange,
 onSkipToggle,
}) {
 const role = candidate.recommendation_role || (isRecommended ? "recommended" : "alternative");
 const pending = isPendingCompositeCandidate(candidate);
 const sourceOk = hasUsableSourceText(candidate.evidence_refs);
 const targets = candidate.target_paths || [];
 const pendingPaths = compositeDecisionPaths(candidate);
 const labeledTargets = targets.map((path) => ({
 path,
 label: resolvePathLabel(path, pathLabels),
 }));
 const englishTargetPaths = targets.filter((path) => looksLikeEnglishPath(path, pathLabels[path] || path));
 const hasClinicalTradeoffs = candidate.clinical_tradeoffs?.length > 0;
 const hasReviewDetails = candidate.evidence_gaps?.length > 0
 || candidate.limitations?.length > 0;
 const hasRunMeta = Boolean(
 candidate.candidate_id
 || candidate.ai_run_id
 || candidate.evidence_catalog_id
 || candidate.evidence_catalog_sha256
 || englishTargetPaths.length
 || candidate.adoption_mode,
 );
 const compactSummary = candidate.rationale
 || (sourceOk ? "已关联可核验来源原文。" : "当前证据不足，选择后可查看详情。");

 return (
 <article
 className={`authoring-package-candidate ${isRecommended ? "recommended" : ""} ${selected ? "selected" : ""} ${pending ? "pending" : ""} ${candidate.state === "user_confirmed" ? "confirmed" : ""}`}
 data-candidate-id={candidate.candidate_id}
 data-recommendation-role={role}
 data-candidate-scope={candidate.candidate_scope}
 data-candidate-detail={selected ? "expanded" : "compact"}
 >
 <button
 type="button"
 className="authoring-package-candidate-select"
 onClick={() => onSelect(candidate.candidate_id)}
 disabled={readOnly || Boolean(busy)}
 aria-pressed={selected}
 aria-expanded={selected}
 title={readOnly ? "只读模式不可切换方案" : busy ? "正在处理中，请稍候" : "选择该组合方案"}
 >
 <div className="authoring-package-candidate-select-copy">
 <span className="authoring-package-candidate-role">
 {candidate.state === "user_confirmed" ? <CheckCircle2 size={13} /> : isRecommended ? <Sparkles size={13} /> : null}
 {candidate.state === "user_confirmed" ? "已采用" : ROLE_LABELS[role] || "方案"}
 </span>
 <strong>{compactCandidatePreview(candidate)}</strong>
 {!selected && <small>{compactSummary}</small>}
 </div>
 <small className="authoring-package-candidate-confidence">
 {CONFIDENCE_LABELS[candidate.confidence] || "未知"}置信
 </small>
 </button>
 {selected && <div className="authoring-package-candidate-body">
 {candidate.rationale && (
 <div className="authoring-package-why-recommend">
 <strong>为何推荐</strong>
 <p className="authoring-package-rationale">{candidate.rationale}</p>
 </div>
 )}
 {hasClinicalTradeoffs && (
 <div className="authoring-package-tradeoffs" data-tradeoffs-priority="primary">
 <strong>临床差异 / 权衡</strong>
 <ul>{candidate.clinical_tradeoffs.map((item) => <li key={item}>{item}</li>)}</ul>
 </div>
 )}
 {selected && pending && (
 <div className="authoring-package-path-decisions" data-testid="pending-path-decisions">
 <header>
 <ShieldAlert size={14} />
 <span>{compositeCandidateBlockedReason(candidate) || "该方案需逐项确认后采用。"}</span>
 </header>
 {pendingPaths.map((path) => (
 <PathDecisionRow
 key={path}
 path={path}
 label={resolvePathLabel(path, pathLabels)}
 candidateValue={candidate.structured_value?.[path]}
 overrideValue={pathOverrides[path]}
 skipped={Boolean(pathSkips[path])}
 allowSkip
 disabled={readOnly || Boolean(busy)}
 onOverrideChange={onOverrideChange}
 onSkipToggle={onSkipToggle}
 />
 ))}
 {!pendingPaths.length && <p>当前没有需要确认的字段。</p>}
 </div>
 )}
 {selected && !pending && targets.length > 0 && (
 <details className="authoring-package-optional-overrides">
 <summary>按字段微调后再采用</summary>
 {targets.map((path) => (
 <PathDecisionRow
 key={path}
 path={path}
 label={resolvePathLabel(path, pathLabels)}
 candidateValue={candidate.structured_value?.[path]}
 overrideValue={pathOverrides[path]}
 skipped={false}
 disabled={readOnly || Boolean(busy)}
 onOverrideChange={onOverrideChange}
 onSkipToggle={onSkipToggle}
 />
 ))}
 </details>
 )}
 <details className="authoring-package-basis-details">
 <summary>展开依据与全部字段</summary>
 <div className="authoring-package-basis-body">
 <EvidenceBlock evidenceRefs={candidate.evidence_refs} />
 {!sourceOk && <p className="authoring-package-insufficient-flag">当前没有可直接展示的来源原文。</p>}
 {hasReviewDetails && (
 <div className="authoring-package-review-grid">
 {candidate.evidence_gaps?.length > 0 && (
 <div className="authoring-package-gaps">
 <strong>证据缺口</strong>
 <ul>{candidate.evidence_gaps.map((item) => <li key={item}>{item}</li>)}</ul>
 </div>
 )}
 {candidate.limitations?.length > 0 && (
 <div className="authoring-package-limitations">
 <strong>局限</strong>
 <ul>{candidate.limitations.map((item) => <li key={item}>{item}</li>)}</ul>
 </div>
 )}
 </div>
 )}
 {labeledTargets.length > 0 && (
 <div className="authoring-package-targets">
 <strong>受影响字段</strong>
 <ul>{labeledTargets.map((item) => <li key={item.path} title={item.path}>{item.label}</li>)}</ul>
 </div>
 )}
 {hasRunMeta && (
 <details className="authoring-package-run-meta">
 <summary>运行元数据</summary>
 <dl>
 {candidate.candidate_id && <div><dt>候选标识</dt><dd>{candidate.candidate_id}</dd></div>}
 {candidate.ai_run_id && <div><dt>AI运行</dt><dd>{candidate.ai_run_id}</dd></div>}
 {candidate.evidence_catalog_id && <div><dt>证据目录</dt><dd>{candidate.evidence_catalog_id}</dd></div>}
 {candidate.evidence_catalog_sha256 && <div><dt>目录哈希</dt><dd>{candidate.evidence_catalog_sha256}</dd></div>}
 {candidate.adoption_mode && <div><dt>采用模式</dt><dd>{candidate.adoption_mode === "batch_allowed" ? "允许组合采用" : "需逐项确认"}</dd></div>}
 {englishTargetPaths.length > 0 && <div><dt>内部路径</dt><dd><ul>{englishTargetPaths.map((path) => <li key={path}>{path}</li>)}</ul></dd></div>}
 </dl>
 </details>
 )}
 </div>
 </details>
 </div>}
 </article>
 );
}

/**
 * Recommendation-first composite candidate package panel.
 * Pure presentation: no network calls. Parent owns journey/package and adopt.
 */
export function AuthoringCandidatePackagePanel({
 groups = [],
 packageRevision = 0,
 pathLabels = {},
 busy = "",
 readOnly = false,
 receipt = null,
 onAdoptComposite,
}) {
 const compositeGroups = useMemo(
 () => (groups || []).filter(isCompositePrefillGroup),
 [groups],
 );
 const [activeFieldPath, setActiveFieldPath] = useState("");
 const [selectedByField, setSelectedByField] = useState({});
 const [overridesByField, setOverridesByField] = useState({});
 const [skipsByField, setSkipsByField] = useState({});

 useEffect(() => {
 if (!compositeGroups.length) {
 setActiveFieldPath("");
 return;
 }
 if (!compositeGroups.some((group) => group.field_path === activeFieldPath)) {
 setActiveFieldPath(
 compositeGroups.find((group) => group.field_path === "package.design")?.field_path
 || compositeGroups[0].field_path,
 );
 }
 }, [compositeGroups, activeFieldPath]);

 useEffect(() => {
 setSelectedByField({});
 setOverridesByField({});
 setSkipsByField({});
 }, [packageRevision]);

 if (!compositeGroups.length) {
 return (
 <section className="authoring-package-panel empty" data-testid="authoring-candidate-package-panel" aria-label="研究设计组合推荐">
 <header>
 <Sparkles size={15} />
 <div>
 <strong>组合推荐包</strong>
 <small>当前尚无组合推荐方案。完成公开检索与语料准备后会在此出现。</small>
 </div>
 </header>
 </section>
 );
 }

 const activeGroup = compositeGroups.find((group) => group.field_path === activeFieldPath) || compositeGroups[0];
 const { recommended, alternatives, displayCandidates } = sortCompositeCandidates(activeGroup);
 // Empty recommendation stays no recommendation: never auto-select the
 // first display candidate when the server left the slot empty or the
 // slot points at a pending-like candidate.
 const selectedId = selectedByField[activeGroup.field_path] || recommended?.candidate_id || "";
 const selectedCandidate = displayCandidates.find((item) => item.candidate_id === selectedId) || null;
 const fieldOverrides = overridesByField[activeGroup.field_path] || {};
 const fieldSkips = skipsByField[activeGroup.field_path] || {};
 const pending = isPendingCompositeCandidate(selectedCandidate);
 const pendingPaths = compositeDecisionPaths(selectedCandidate);
 const ready = compositeAdoptionReady(selectedCandidate, fieldOverrides, fieldSkips);
 const confirmed = selectedCandidate?.state === "user_confirmed";
 const adoptBusy = busy === "prefill-composite-adopt" || busy === `prefill-composite-adopt-${activeGroup.field_path}`;
 const adoptDisabled = readOnly || Boolean(busy) || !selectedCandidate || !ready || confirmed
 || !["module", "design_package"].includes(selectedCandidate?.candidate_scope);

 const setSelected = (candidateId) => {
 setSelectedByField((current) => ({ ...current, [activeGroup.field_path]: candidateId }));
 };
 const setOverride = (path, value) => {
 setOverridesByField((current) => ({
 ...current,
 [activeGroup.field_path]: {
 ...(current[activeGroup.field_path] || {}),
 [path]: value,
 },
 }));
 if (value && String(value).trim()) {
 setSkipsByField((current) => {
 const nextField = { ...(current[activeGroup.field_path] || {}) };
 delete nextField[path];
 return { ...current, [activeGroup.field_path]: nextField };
 });
 }
 };
 const toggleSkip = (path) => {
 setSkipsByField((current) => {
 const nextField = { ...(current[activeGroup.field_path] || {}) };
 if (nextField[path]) delete nextField[path];
 else nextField[path] = true;
 return { ...current, [activeGroup.field_path]: nextField };
 });
 };
 const handleAdopt = () => {
 if (adoptDisabled || typeof onAdoptComposite !== "function") return;
 const pathOverrides = buildCompositePathOverrides(selectedCandidate, fieldOverrides, fieldSkips);
 const skippedPaths = collectExplicitCompositeSkips(selectedCandidate, fieldSkips);
 onAdoptComposite(activeGroup.field_path, selectedCandidate, pathOverrides, skippedPaths);
 };

 return (
 <section className="authoring-package-panel" data-testid="authoring-candidate-package-panel" aria-label="研究设计组合推荐">
 <header>
 <Sparkles size={15} />
 <div>
 <strong>AI推荐研究方案</strong>
 <small>先审阅整套设计与关键差异；采用后仍可在高级微调中逐项修改。</small>
 </div>
 </header>
 <nav className="authoring-package-tabs" aria-label="组合推荐模块">
 {compositeGroups.map((group) => {
 const rec = sortCompositeCandidates(group).recommended;
 const isConfirmed = group.candidates?.some((item) => item.state === "user_confirmed");
 return (
 <button
 key={group.field_path}
 type="button"
 className={group.field_path === activeGroup.field_path ? "active" : ""}
 data-package-field={group.field_path}
 aria-pressed={group.field_path === activeGroup.field_path}
 onClick={() => setActiveFieldPath(group.field_path)}
 >
 <span>{packageFieldLabel(group.field_path)}</span>
 <small>
 {isConfirmed ? "有采用记录" : ROLE_LABELS[rec?.recommendation_role] || "待审阅"}
 </small>
 </button>
 );
 })}
 </nav>
 <div className="authoring-package-workspace" data-package-field={activeGroup.field_path}>
 <div className="authoring-package-candidates">
 {selectedCandidate && (
 <CandidateCard
 key={selectedCandidate.candidate_id}
 candidate={selectedCandidate}
 isRecommended={selectedCandidate.candidate_id === recommended?.candidate_id}
 selected
 pathLabels={pathLabels}
 pathOverrides={fieldOverrides}
 pathSkips={fieldSkips}
 readOnly={readOnly}
 busy={busy}
 onSelect={setSelected}
 onOverrideChange={setOverride}
 onSkipToggle={toggleSkip}
 />
 )}
 {!selectedCandidate && (
 <div className="authoring-package-empty-slot" data-testid="composite-empty-slot">
 <p>该分组当前没有推荐方案；请从下方候选中选择，或先完成待决字段后采用。</p>
 </div>
 )}
 {!selectedCandidate && displayCandidates.length > 0 && (
 <div className="authoring-package-candidate-list" data-testid="composite-no-recommendation-list">
 {displayCandidates.map((candidate) => (
 <CandidateCard
 key={candidate.candidate_id}
 candidate={candidate}
 isRecommended={false}
 selected={false}
 pathLabels={pathLabels}
 pathOverrides={fieldOverrides}
 pathSkips={fieldSkips}
 readOnly={readOnly}
 busy={busy}
 onSelect={setSelected}
 onOverrideChange={setOverride}
 onSkipToggle={toggleSkip}
 />
 ))}
 </div>
 )}
 {selectedCandidate && displayCandidates.length > 1 && (
 <details className="authoring-package-alternatives">
 <summary>查看其他方案与关键差异</summary>
 <div>
 {displayCandidates
 .filter((candidate) => candidate.candidate_id !== selectedCandidate?.candidate_id)
 .map((candidate) => (
 <CandidateCard
 key={candidate.candidate_id}
 candidate={candidate}
 isRecommended={candidate.candidate_id === recommended?.candidate_id}
 selected={false}
 pathLabels={pathLabels}
 pathOverrides={fieldOverrides}
 pathSkips={fieldSkips}
 readOnly={readOnly}
 busy={busy}
 onSelect={setSelected}
 onOverrideChange={setOverride}
 onSkipToggle={toggleSkip}
 />
 ))}
 </div>
 </details>
 )}
 {selectedCandidate && alternatives.length === 0 && <p className="authoring-package-no-alternatives">当前没有实质备选方案。</p>}
 </div>
 <aside className="authoring-package-actions" aria-label="组合采用">
 <div className="authoring-package-action-summary">
 <strong>{packageFieldLabel(activeGroup.field_path)}</strong>
 <p>
 {!selectedCandidate
 ? "该分组当前没有推荐方案；请从候选中选择，或先处理待决字段。"
 : pending
 ? pendingPaths.length
 ? `该方案需逐项确认：请对 ${pendingPaths.length} 个字段填写确认值或勾选跳过。`
 : "该方案需逐项确认后采用。"
 : "可直接采用；仅在确有项目差异时再展开修改。"}
 </p>
 {pending && !ready && selectedCandidate && (
 <p className="authoring-package-pending-hint" data-testid="pending-gating-hint">
 完成上方字段确认后即可整包采用。
 </p>
 )}
 </div>
 {!readOnly && (
 <button
 type="button"
 className="primary-button authoring-package-adopt-button"
 data-action="adopt-composite"
 data-testid="adopt-composite-button"
 data-package-field={activeGroup.field_path}
 data-candidate-id={selectedCandidate?.candidate_id || ""}
 onClick={handleAdopt}
 disabled={adoptDisabled}
 title={
 confirmed ? "该组合方案已采用"
 : readOnly ? "只读模式不可采用"
 : busy ? "正在处理中，请稍候"
 : !selectedCandidate ? "该分组没有推荐方案；请先从候选中选择"
 : pending && !ready ? (compositeCandidateBlockedReason(selectedCandidate) || "请先对每个字段确认或跳过")
 : "一次请求采用组合候选，并自动填入下方字段"
 }
 >
 {adoptBusy ? "写入中" : confirmed ? "已采用推荐方案" : selectedCandidate?.candidate_id === recommended?.candidate_id ? "一键采用推荐方案" : "采用所选方案"}
 </button>
 )}
 {pending && pendingPaths.length > 0 && (
 <p className="authoring-package-pending-badge" data-recommendation-role="pending_decision">
 <ChevronDown size={13} /> {pendingPaths.length}项待决定
 </p>
 )}
 </aside>
 </div>
 <CompositeReceiptPanel receipt={receipt} />
 </section>
 );
}

export default AuthoringCandidatePackagePanel;

import { describe, expect, it } from "vitest";

import {
 buildCompositePathOverrides,
 collectExplicitCompositeSkips,
 compactCandidatePreview,
 compositeAdoptionReady,
 compositeCandidateBlockedCode,
 compositeCandidateBlockedReason,
 compositeDecisionPaths,
 formatPathValue,
 isPendingCompositeCandidate,
 serializeCompositePathOverride,
 sortCompositeCandidates,
 splitCompositeListValue,
} from "./AuthoringCandidatePackagePanel";

const pendingPackage = {
 candidate_id: "candidate-pending",
 candidate_scope: "design_package",
 recommendation_role: "pending_decision",
 adoption_mode: "manual_only",
 evidence_status: "insufficient",
 target_paths: [
 "design.randomization",
 "design.blinding",
 "design.interim_analysis",
 ],
 structured_value: {
 "design.randomization": "随机",
 "design.blinding": "双盲",
 "design.interim_analysis": "待确认",
 },
};

const safeCandidate = {
 candidate_id: "candidate-safe",
 candidate_scope: "design_package",
 recommendation_role: "recommended",
 adoption_mode: "batch_allowed",
 evidence_status: "supported",
 target_paths: ["design.randomization", "design.blinding"],
 structured_value: {
 "design.randomization": "随机",
 "design.blinding": "双盲",
 },
};

describe("AI-first composite package approval", () => {
 it("renders structured defaults as human-readable Chinese instead of raw JSON", () => {
 expect(formatPathValue({ enabled: false, features: [] })).toBe("启用状态：否；具体特征：未设置");
 expect(formatPathValue({ mode: "", blinded_roles: [] })).toBe("模式：待确认；盲态角色：未设置");
 expect(formatPathValue({ planned: false })).toBe("计划状态：否");
 expect(formatPathValue({ src: false, dmc: false })).toBe("SRC：否；DMC：否");
 });

 it("treats every contributed path of a pending-like candidate as a decision path", () => {
 // The backend per-path gate requires an override or explicit skip for
 // EVERY target path of a restricted candidate — AI-resolved values are
 // never carried as implicit overrides.
 expect(isPendingCompositeCandidate(pendingPackage)).toBe(true);
 expect(compositeCandidateBlockedCode(pendingPackage)).toBe("pending_decision");
 expect(compositeDecisionPaths(pendingPackage)).toEqual(pendingPackage.target_paths);
 });

 it("does not mistake neutral nested scaffold defaults for AI decisions", () => {
 const scaffold = {
 candidate_id: "candidate-structure-only",
 candidate_scope: "module",
 recommendation_role: "pending_decision",
 target_paths: [
 "design.adaptive_design",
 "design.phase1_parts",
 "design.src_dmc",
 ],
 structured_value: {
 "design.adaptive_design": { enabled: false, features: [] },
 "design.phase1_parts": {
 parts: [],
 sequence: "",
 available_part_types: ["SAD", "MAD"],
 },
 "design.src_dmc": { src: false, dmc: false },
 },
 };

 expect(compositeDecisionPaths(scaffold)).toEqual(scaffold.target_paths);
 expect(compositeAdoptionReady(scaffold)).toBe(false);
 });

 it("keeps the backend composite contract complete: restricted candidates need a decision on every path", () => {
 expect(compositeAdoptionReady(pendingPackage)).toBe(false);
 // One decided path of three is not enough.
 expect(
 compositeAdoptionReady(
 pendingPackage,
 { "design.interim_analysis": "不设置期中分析" },
 {},
 ),
 ).toBe(false);
 // Every path explicitly decided (override or skip) enables adoption.
 expect(
 compositeAdoptionReady(
 pendingPackage,
 {
 "design.interim_analysis": "不设置期中分析",
 "design.randomization": "随机",
 "design.blinding": "双盲",
 },
 {},
 ),
 ).toBe(true);
 expect(
 buildCompositePathOverrides(
 pendingPackage,
 {
 "design.interim_analysis": "不设置期中分析",
 "design.randomization": "随机",
 "design.blinding": "双盲",
 },
 {},
 ),
 ).toEqual({
 "design.randomization": "随机",
 "design.blinding": "双盲",
 "design.interim_analysis": "不设置期中分析",
 });
 // Un-decided paths are never carried as implicit overrides.
 expect(
 buildCompositePathOverrides(
 pendingPackage,
 { "design.interim_analysis": "不设置期中分析" },
 {},
 ),
 ).toEqual({ "design.interim_analysis": "不设置期中分析" });
 });

 it("classifies unsafe alternatives and keeps them out of zero-override adoption", () => {
 const manualOnly = {
 ...safeCandidate,
 candidate_id: "candidate-manual",
 adoption_mode: "manual_only",
 };
 const insufficient = {
 ...safeCandidate,
 candidate_id: "candidate-insufficient",
 evidence_status: "insufficient",
 };
 const gapCarrier = {
 ...safeCandidate,
 candidate_id: "candidate-gap",
 evidence_gaps: ["声称内容未在引用原文中出现：双盲优于单盲"],
 };
 expect(compositeCandidateBlockedCode(manualOnly)).toBe("manual_only");
 expect(compositeCandidateBlockedCode(insufficient)).toBe("insufficient");
 expect(compositeCandidateBlockedCode(gapCarrier)).toBe("unsupported_gap");
 for (const unsafe of [manualOnly, insufficient, gapCarrier]) {
 expect(isPendingCompositeCandidate(unsafe)).toBe(true);
 expect(compositeCandidateBlockedReason(unsafe)).not.toBe("");
 // Zero-override adoption of an unsafe alternative is never enabled.
 expect(compositeAdoptionReady(unsafe, {}, {})).toBe(false);
 // Explicit decision on every path re-enables the audited override path.
 expect(
 compositeAdoptionReady(
 unsafe,
 { "design.randomization": "随机", "design.blinding": "双盲" },
 {},
 ),
 ).toBe(true);
 }
 });

 it("keeps genuinely safe alternatives zero-override selectable", () => {
 expect(compositeCandidateBlockedCode(safeCandidate)).toBe("");
 expect(isPendingCompositeCandidate(safeCandidate)).toBe(false);
 expect(compositeDecisionPaths(safeCandidate)).toEqual([]);
 expect(compositeAdoptionReady(safeCandidate, {}, {})).toBe(true);
 expect(compositeAdoptionReady(safeCandidate)).toBe(true);
 });

 it("leaves an empty recommendation slot empty instead of promoting an alternative", () => {
 const emptySlot = {
 field_path: "package.design",
 recommended_candidate_id: "",
 candidates: [
 { ...pendingPackage, candidate_id: "candidate-gap", evidence_gaps: ["声称内容未在引用原文中出现：X"] },
 { ...safeCandidate, candidate_id: "candidate-safe-alt" },
 ],
 };
 const sorted = sortCompositeCandidates(emptySlot);
 expect(sorted.recommended).toBeNull();
 // The safe alternative stays visible and selectable, but is not
 // auto-promoted into the recommendation slot.
 expect(sorted.displayCandidates.map((item) => item.candidate_id)).toContain("candidate-safe-alt");
 });

 it("does not promote a pending-like slot occupant into the recommended card", () => {
 const pendingSlot = {
 field_path: "package.design",
 recommended_candidate_id: pendingPackage.candidate_id,
 candidates: [
 pendingPackage,
 { ...safeCandidate, candidate_id: "candidate-safe-alt" },
 ],
 };
 const sorted = sortCompositeCandidates(pendingSlot);
 expect(sorted.recommended).toBeNull();
 expect(sorted.displayCandidates.map((item) => item.candidate_id)).toContain("candidate-safe-alt");
 });

 it("serializes list-valued paths from candidate metadata while preserving scalar text", () => {
 const listPaths = [
 "picos.inclusion_modules",
 "picos.exclusion_modules",
 "picos.washout_rules",
 "picos.allowed_concomitant_rules",
 "picos.required_background_rules",
 "picos.prohibited_concomitant_rules",
 "picos.assessment_timing_restrictions",
 "picos.primary_objectives",
 "picos.secondary_objectives",
 "picos.exploratory_objectives",
 "picos.key_secondary_endpoints",
 "picos.other_secondary_endpoints",
 "picos.exploratory_endpoints",
 "picos.safety_endpoints",
 "picos.aesi_definitions",
 "picos.study_epochs",
 ];
 const candidate = {
 candidate_id: "candidate-lists",
 candidate_scope: "module",
 recommendation_role: "pending_decision",
 target_paths: [
 "picos.intervention_summary",
 ...listPaths,
 ],
 structured_value: {
 "picos.intervention_summary": "",
 ...Object.fromEntries(listPaths.map((path) => [path, []])),
 },
 };

 expect(splitCompositeListValue("规则 A\n规则 B；规则 A; ")).toEqual([
 "规则 A",
 "规则 B",
 ]);
 const overrides = buildCompositePathOverrides(candidate, {
 "picos.intervention_summary": " 保留用户原始表述 ",
 ...Object.fromEntries(listPaths.map((path) => [path, "规则 A\n规则 B；规则 A"])),
 });
 expect(overrides["picos.intervention_summary"]).toBe("保留用户原始表述");
 listPaths.forEach((path) => {
 expect(overrides[path]).toEqual(["规则 A", "规则 B"]);
 });
 });

 it("serializes assessment-instrument text into backend-valid structured list items", () => {
 const candidate = {
 candidate_id: "candidate-instruments",
 candidate_scope: "module",
 recommendation_role: "pending_decision",
 target_paths: ["picos.assessment_instruments"],
 structured_value: {
 "picos.assessment_instruments": [],
 },
 };

 const serialized = serializeCompositePathOverride(
 candidate,
 "picos.assessment_instruments",
 "SNOT-22\nLund-Kennedy",
 );
 expect(serialized).toEqual([
 {
 instrument_id: expect.stringMatching(/^manual_instrument_[0-9a-f]{8}$/),
 canonical_name_zh: "SNOT-22",
 instrument_kind: "other",
 confirmation_status: "candidate",
 },
 {
 instrument_id: expect.stringMatching(/^manual_instrument_[0-9a-f]{8}$/),
 canonical_name_zh: "Lund-Kennedy",
 instrument_kind: "other",
 confirmation_status: "candidate",
 },
 ]);
 expect(serialized[0].instrument_id).not.toBe(serialized[1].instrument_id);
 });

 it("allows every decision path to be explicitly skipped but not left undecided", () => {
 const entirelyUnresolved = {
 candidate_id: "candidate-all-unresolved",
 candidate_scope: "module",
 recommendation_role: "pending_decision",
 target_paths: ["picos.primary_objectives", "picos.secondary_objectives"],
 structured_value: {
 "picos.primary_objectives": [],
 "picos.secondary_objectives": [],
 },
 };
 const allSkipped = {
 "picos.primary_objectives": true,
 "picos.secondary_objectives": true,
 };
 expect(compositeAdoptionReady(entirelyUnresolved, {}, allSkipped)).toBe(true);
 expect(buildCompositePathOverrides(entirelyUnresolved, {}, allSkipped)).toEqual({});
 expect(collectExplicitCompositeSkips(entirelyUnresolved, allSkipped)).toEqual([
 "picos.primary_objectives",
 "picos.secondary_objectives",
 ]);
 expect(compositeAdoptionReady(entirelyUnresolved, {}, {})).toBe(false);
 });

 it("keeps the default summary compact even when a package contains many fields", () => {
 expect(compactCandidatePreview({
 preview: "随机；双盲；安慰剂对照；平行分组；多中心；不设置期中分析",
 })).toBe("随机；双盲；安慰剂对照；平行分组；其余设计已纳入整包建议");
 });
});

import { useEffect, useRef, useState } from "react";
import { X } from "lucide-react";
import { WritingReferencePanel } from "../writing-reference/WritingReferencePanel";

/**
 * Early authoring competitor-processing drawer.
 * Reuses WritingReferencePanel state machine; keeps the panel mounted when closed
 * so triage selection, scroll position, and in-flight jobs survive hide/show.
 */
export function AuthoringCompetitorDrawer({
 open = false,
 onClose = () => {},
 projectId,
 snapshotId = "",
 lockedIndication = "",
 lockedPhase = "",
 journey = null,
 onJourneyChange = () => {},
 onTriagePipelineChange = () => {},
 selectedBriefIds = [],
 onSelectedBriefIdsChange = () => {},
 requestedView = "",
 requestedArtifactId = "",
 focusRequestKey = "",
 keepPanelMounted = true,
 onExecuteSearch = null,
 searchBusy = false,
}) {
 useEffect(() => {
 if (!open) return undefined;
 const onKeyDown = (event) => {
 if (event.key === "Escape") {
 event.preventDefault();
 onClose();
 }
 };
 globalThis.addEventListener?.("keydown", onKeyDown);
 return () => globalThis.removeEventListener?.("keydown", onKeyDown);
 }, [open, onClose]);

 const prevOpenRef = useRef(open);
 const [refreshSignal, setRefreshSignal] = useState(0);
 useEffect(() => {
 if (open && !prevOpenRef.current) {
 setRefreshSignal((signal) => signal + 1);
 }
 prevOpenRef.current = open;
 }, [open]);

 const shouldRenderPanel = Boolean(projectId && (keepPanelMounted || open) && snapshotId);

 return (
 <div
 className={`authoring-competitor-drawer-host ${open ? "is-open" : "is-closed"}`}
 data-open={open ? "true" : "false"}
 aria-hidden={!open}
 >
 <button
 type="button"
 className="authoring-competitor-drawer-backdrop"
 tabIndex={open ? 0 : -1}
 aria-label="关闭竞品处理抽屉"
 onClick={onClose}
 />
 <aside
 className="authoring-competitor-drawer panel"
 role="dialog"
 aria-modal={open ? "true" : "false"}
 aria-label="竞品方案处理"
 data-testid="authoring-competitor-drawer"
 >
 <header className="authoring-competitor-drawer-header">
 <div>
 <span>建稿前语料处理</span>
 <strong>竞品方案处理</strong>
 <small>
 {snapshotId
 ? "分诊、原文、译文与医学审核可在此完成；关闭抽屉不会清空研究框架或PICOS草稿。"
 : "完成竞品检索后可在此处理候选研究；当前尚无已保存的公开检索快照。"}
 </small>
 </div>
 <button
 type="button"
 className="icon-button authoring-competitor-drawer-close"
 onClick={onClose}
 title="关闭竞品处理抽屉"
 aria-label="关闭竞品处理抽屉"
 data-action="close-competitor-drawer"
 >
 <X size={16} />
 </button>
 </header>
 <div className="authoring-competitor-drawer-body">
 {shouldRenderPanel ? (
 <WritingReferencePanel
 projectId={projectId}
 variant="authoring"
 embedded
 compact
 snapshotId={snapshotId}
 lockedIndication={lockedIndication}
 lockedPhase={lockedPhase}
 journey={journey}
 onJourneyChange={onJourneyChange}
 onTriagePipelineChange={onTriagePipelineChange}
 selectedBriefIds={selectedBriefIds}
 onSelectedBriefIdsChange={onSelectedBriefIdsChange}
 requestedView={requestedView}
 requestedArtifactId={requestedArtifactId}
 focusRequestKey={focusRequestKey}
 refreshSignal={refreshSignal}
 />
 ) : (
 <div className="authoring-competitor-drawer-empty" role="status">
 <strong>竞品处理尚未就绪</strong>
 <p>
 {snapshotId
 ? "本次公开检索结果已关联，但面板暂不可用；请关闭后重开抽屉。"
 : "尚无已保存的公开检索快照。请先在语料门执行一次 ClinicalTrials.gov 公开检索；检索完成后本抽屉会自动加载候选分诊与原文处理。"}
 </p>
 {!snapshotId && typeof onExecuteSearch === "function" && (
 <button
 type="button"
 className="primary-button"
 data-action="execute-search-from-competitor-drawer"
 onClick={onExecuteSearch}
 disabled={Boolean(searchBusy)}
 title={searchBusy ? "正在执行公开检索，请稍候" : "执行公开检索并保存本次检索快照（推荐默认动作）"}
 >
 {searchBusy ? "检索中…" : "执行公开检索（推荐）"}
 </button>
 )}
 </div>
 )}
 </div>
 </aside>
 </div>
 );
}

export default AuthoringCompetitorDrawer;

import { Mark, mergeAttributes } from "@tiptap/core";

export const CrossReferenceMark = Mark.create({
 name: "crossReference",
 inclusive: false,
 addAttributes() {
 return {
 targetKind: {
 default: null,
 parseHTML: (element) => element.getAttribute("data-cross-reference-kind"),
 renderHTML: (attributes) => attributes.targetKind
 ? { "data-cross-reference-kind": attributes.targetKind }
 : {},
 },
 targetId: {
 default: null,
 parseHTML: (element) => element.getAttribute("data-cross-reference-id"),
 renderHTML: (attributes) => attributes.targetId
 ? { "data-cross-reference-id": attributes.targetId }
 : {},
 },
 };
 },
 parseHTML() {
 return [{ tag: "span[data-cross-reference-kind][data-cross-reference-id]" }];
 },
 renderHTML({ HTMLAttributes }) {
 return ["span", mergeAttributes(HTMLAttributes, { class: "protocol-cross-reference" }), 0];
 },
});

export function insertCrossReference(editor, target) {
 const targetKind = String(target?.kind || "").trim();
 const targetId = String(target?.object_id || "").trim();
 const number = Number(target?.number);
 if (
 !editor
 || !["table", "figure"].includes(targetKind)
 || !targetId
 || !Number.isInteger(number)
 || number < 1
 ) return false;
 const label = targetKind === "table" ? "表" : "图";
 return editor.chain()
 .focus()
 .setTextSelection(editor.state.selection.to)
 .insertContent({
 type: "text",
 text: `${label} ${number}`,
 marks: [{
 type: "crossReference",
 attrs: { targetKind, targetId },
 }],
 })
 .unsetMark("crossReference")
 .run();
}

import { useEffect, useMemo, useState } from "react";
import { ChevronLeft, ChevronRight, X } from "lucide-react";

/**
 * Sort assessment-instrument appendix pages deterministically by page_number.
 * Does not copy or transform image_base64 payloads.
 */
export function orderInstrumentAppendixPages(pages = []) {
 return [...(pages || [])]
 .filter((block) => block && block.block_type === "appendix_image")
 .sort((left, right) => {
 const leftPage = Number(left.page_number) || 0;
 const rightPage = Number(right.page_number) || 0;
 if (leftPage !== rightPage) return leftPage - rightPage;
 return String(left.block_id || "").localeCompare(String(right.block_id || ""));
 });
}

export function imageDataUrl(block) {
 if (!block?.image_base64) return "";
 const mediaType = block.media_type || "image/png";
 return `data:${mediaType};base64,${block.image_base64}`;
}

/**
 * Real per-page assessment-instrument appendix preview.
 * Thumbnails use lazy loading; the enlarged overlay mounts only the current page image.
 * Page index state never stores base64 copies.
 */
export function InstrumentAppendixPreview({
 pages = [],
 declaredPageCount = null,
 instrumentLabel = "量表附件",
 emptyMessage = "",
}) {
 const orderedPages = useMemo(() => orderInstrumentAppendixPages(pages), [pages]);
 const actualCount = orderedPages.length;
 const declared = Number(declaredPageCount) || Number(orderedPages[0]?.page_count) || actualCount;
 const hasMismatch = actualCount > 0 && declared > 0 && declared !== actualCount;
 const [reviewIndex, setReviewIndex] = useState(null);

 useEffect(() => {
 setReviewIndex(null);
 }, [pages]);

 useEffect(() => {
 if (reviewIndex === null) return undefined;
 const onKeyDown = (event) => {
 if (event.key === "Escape") {
 event.preventDefault();
 setReviewIndex(null);
 return;
 }
 if (event.key === "ArrowLeft") {
 event.preventDefault();
 setReviewIndex((current) => (current === null ? null : Math.max(0, current - 1)));
 return;
 }
 if (event.key === "ArrowRight") {
 event.preventDefault();
 setReviewIndex((current) => (
 current === null ? null : Math.min(actualCount - 1, current + 1)
 ));
 }
 };
 globalThis.addEventListener?.("keydown", onKeyDown);
 return () => globalThis.removeEventListener?.("keydown", onKeyDown);
 }, [reviewIndex, actualCount]);

 if (!actualCount) {
 if (!emptyMessage) return null;
 return (
 <div className="instrument-appendix-preview is-empty" data-testid="instrument-appendix-preview" data-page-count="0">
 <p>{emptyMessage}</p>
 </div>
 );
 }

 const openIndex = reviewIndex === null ? -1 : Math.min(Math.max(reviewIndex, 0), actualCount - 1);
 const currentPage = openIndex >= 0 ? orderedPages[openIndex] : null;
 const currentSrc = currentPage ? imageDataUrl(currentPage) : "";

 return (
 <section
 className="instrument-appendix-preview"
 data-testid="instrument-appendix-preview"
 data-page-count={String(actualCount)}
 aria-label={`${instrumentLabel}逐页预览`}
 >
 <header className="instrument-appendix-preview-head">
 <strong>原始页面预览</strong>
 <span>{actualCount} 页可审阅</span>
 </header>
 {hasMismatch && (
 <p className="instrument-appendix-consistency-notice" role="status" data-testid="appendix-page-count-mismatch">
 附件声明 {declared} 页，当前工作副本实际可读 {actualCount} 页；按实际页序审阅，不阻断核对。
 </p>
 )}
 <div className="instrument-appendix-thumbnail-grid" role="list">
 {orderedPages.map((block, index) => {
 const pageNumber = Number(block.page_number) || index + 1;
 const src = imageDataUrl(block);
 return (
 <button
 key={block.block_id || `page-${pageNumber}-${index}`}
 type="button"
 className="instrument-appendix-thumbnail"
 role="listitem"
 data-page-number={String(pageNumber)}
 data-testid={`appendix-thumbnail-${pageNumber}`}
 onClick={() => setReviewIndex(index)}
 title={`查看第 ${pageNumber} 页`}
 aria-label={`查看${instrumentLabel}第 ${pageNumber} 页，共 ${actualCount} 页`}
 >
 {src ? (
 <img
 src={src}
 alt={`${instrumentLabel}第 ${pageNumber} 页缩略图`}
 loading="lazy"
 decoding="async"
 />
 ) : (
 <span className="instrument-appendix-thumbnail-missing">第 {pageNumber} 页图像不可用</span>
 )}
 <em>{pageNumber}/{actualCount}</em>
 </button>
 );
 })}
 </div>

 {currentPage && openIndex >= 0 && (
 <div
 className="instrument-appendix-review-overlay"
 role="dialog"
 aria-modal="true"
 aria-label={`${instrumentLabel}第 ${currentPage.page_number || openIndex + 1} 页放大审阅`}
 data-testid="instrument-appendix-review-overlay"
 data-review-index={String(openIndex)}
 >
 <div className="instrument-appendix-review-backdrop" onClick={() => setReviewIndex(null)} />
 <div className="instrument-appendix-review-panel">
 <header>
 <div>
 <span>放大审阅</span>
 <strong>
 第 {Number(currentPage.page_number) || openIndex + 1} 页 / 共 {actualCount} 页
 </strong>
 </div>
 <button
 type="button"
 className="icon-button"
 onClick={() => setReviewIndex(null)}
 title="关闭放大审阅"
 aria-label="关闭放大审阅"
 data-action="close-appendix-review"
 >
 <X size={16} />
 </button>
 </header>
 <div className="instrument-appendix-review-stage">
 {/* Only the current full-page image is mounted; base64 is read from the source block. */}
 {currentSrc ? (
 <img
 key={currentPage.block_id || `review-${openIndex}`}
 src={currentSrc}
 alt={`${instrumentLabel}第 ${currentPage.page_number || openIndex + 1} 页`}
 data-testid="instrument-appendix-review-image"
 data-page-number={String(currentPage.page_number || openIndex + 1)}
 />
 ) : (
 <p>当前页图像不可用。</p>
 )}
 </div>
 <footer className="instrument-appendix-review-controls">
 <button
 type="button"
 onClick={() => setReviewIndex((current) => Math.max(0, (current ?? 0) - 1))}
 disabled={openIndex <= 0}
 data-action="appendix-prev"
 aria-label="上一页"
 >
 <ChevronLeft size={15} /> 上一页
 </button>
 <label className="instrument-appendix-page-selector">
 <span>页码</span>
 <select
 value={String(openIndex)}
 onChange={(event) => setReviewIndex(Number(event.target.value))}
 aria-label="选择页码"
 data-testid="appendix-page-selector"
 >
 {orderedPages.map((block, index) => (
 <option key={block.block_id || index} value={String(index)}>
 第 {Number(block.page_number) || index + 1} 页
 </option>
 ))}
 </select>
 </label>
 <span className="instrument-appendix-page-indicator" data-testid="appendix-page-indicator">
 {openIndex + 1} / {actualCount}
 </span>
 <button
 type="button"
 onClick={() => setReviewIndex((current) => Math.min(actualCount - 1, (current ?? 0) + 1))}
 disabled={openIndex >= actualCount - 1}
 data-action="appendix-next"
 aria-label="下一页"
 >
 下一页 <ChevronRight size={15} />
 </button>
 </footer>
 </div>
 </div>
 )}
 </section>
 );
}

export default InstrumentAppendixPreview;

import { useEffect, useState } from "react";
import { ChevronDown, ChevronRight, Plus, Trash2 } from "lucide-react";

const SCHEMA_VERSION = "medical_writing_intervention_rules_v1";

const PRODUCT_ROLE_OPTIONS = [
 ["investigational_product", "试验药"],
 ["active_comparator", "阳性对照"],
 ["placebo", "安慰剂"],
 ["other", "其他"],
];
const ADJUSTMENT_POLICY_OPTIONS = [
 ["unspecified", "未指定"],
 ["no_planned_adjustment", "无计划性剂量调整"],
 ["protocol_defined", "方案规定的调整"],
];
const ACTION_KIND_OPTIONS = [
 ["planned_on_off", "计划性停药/重启"],
 ["temporary_interruption", "暂时中断"],
 ["resume", "恢复用药"],
 ["permanent_discontinuation", "永久停药"],
 ["discontinuation_taper", "减量至停药"],
 ["post_discontinuation_follow_up", "停药后随访"],
 ["other", "其他"],
];
const RULE_CLASS_OPTIONS = [
 ["background", "背景治疗"],
 ["allowed_cm", "允许的合并用药"],
 ["prohibited_cm", "禁止的合并用药"],
 ["rescue", "补救治疗"],
 ["other_non_investigational", "其他非试验用药"],
];
const NON_IP_RULE_CLASS_OPTIONS = RULE_CLASS_OPTIONS.filter(([value]) => ["background", "rescue", "other_non_investigational"].includes(value));
const CM_RULE_CLASS_OPTIONS = RULE_CLASS_OPTIONS.filter(([value]) => ["allowed_cm", "prohibited_cm"].includes(value));
const POLICY_OPTIONS = [
 ["allowed", "允许"],
 ["allowed_if_stable", "允许（病情稳定时）"],
 ["allowed_with_approval", "允许（需批准）"],
 ["allowed_with_timing", "允许（限时）"],
 ["prohibited", "禁止"],
 ["rescue_policy", "补救策略"],
];
const LINK_ACTION_OPTIONS = [
 ["hold", "暂停IP"],
 ["stop", "停止IP"],
 ["no_auto_ip_action", "不自动改变IP"],
 ["resume", "恢复IP"],
];

const PANELS = [
 ["regimen", "试验药物与给药"],
 ["ip_actions", "试验用药品调整与处置"],
 ["non_ip", "非试验用药与补救"],
 ["cm", "合并用药"],
];

const uid = (prefix) => `${prefix}_${typeof globalThis.crypto?.randomUUID === "function" ? globalThis.crypto.randomUUID() : Math.random().toString(36).slice(2, 10)}`;

function emptyRules() {
 return {
 schema_version: SCHEMA_VERSION,
 authority: "legacy",
 ip_regimens: [],
 ip_adjustment_policy: "unspecified",
 no_planned_adjustment_statement: "",
 ip_action_rules: [],
 non_ip_treatment_rules: [],
 cross_object_links: [],
 };
}

function ensureRules(value) {
 if (!value || typeof value !== "object") return emptyRules();
 return {
 schema_version: SCHEMA_VERSION,
 authority: value.authority === "structured" ? "structured" : "legacy",
 ip_regimens: Array.isArray(value.ip_regimens) ? value.ip_regimens : [],
 ip_adjustment_policy: ADJUSTMENT_POLICY_OPTIONS.some(([k]) => k === value.ip_adjustment_policy) ? value.ip_adjustment_policy : "unspecified",
 no_planned_adjustment_statement: String(value.no_planned_adjustment_statement || ""),
 ip_action_rules: Array.isArray(value.ip_action_rules) ? value.ip_action_rules : [],
 non_ip_treatment_rules: Array.isArray(value.non_ip_treatment_rules) ? value.non_ip_treatment_rules : [],
 cross_object_links: Array.isArray(value.cross_object_links) ? value.cross_object_links : [],
 };
}

function newRowRegimen() {
 return { regimen_id: uid("reg"), product_name: "", product_role: "investigational_product", dose_and_frequency: "", route: "", treatment_period: "", adherence_notes: "", source_location: "" };
}
function newRowIpAction() {
 return { rule_id: uid("ipr"), action_kind: "temporary_interruption", trigger: "", severity_or_threshold: "", confirmation_required: "", exceptions: [], study_product_action: "", retest_recovery: "", approvers: [], wait_period: "", permanent_discontinuation_condition: "", taper_steps: [], linked_non_ip_rule_ids: [], source_location: "", notes: "" };
}
function newRowNonIp() {
 return { rule_id: uid("nir"), rule_class: "background", policy: "allowed", agent_or_category: "", collection_window: "", timing_restrictions: [], washout_or_window: "", cm_dose_rule: "", phase_applicability: "", exceptions: [], source_location: "", notes: "" };
}
function newRowLink() {
 return { link_id: uid("lnk"), source_rule_id: "", source_kind: "rescue", target_kind: "ip", target_rule_id: "", action: "no_auto_ip_action", resume_condition: "", notes: "", source_location: "" };
}

export function InterventionRulesEditor({ value, onChange, panel = "", onPanelChange }) {
 const [collapsed, setCollapsed] = useState(false);
 const rules = ensureRules(value);
 const activePanel = PANELS.some(([key]) => key === panel) ? panel : "regimen";

 useEffect(() => {
 if (panel && !PANELS.some(([key]) => key === panel)) onPanelChange?.("regimen");
 }, [panel, onPanelChange]);

 const update = (patch) => {
 const next = { ...rules, ...patch };
 const hasStructuredContent = next.ip_regimens.length
 || next.ip_action_rules.length
 || next.non_ip_treatment_rules.length
 || next.cross_object_links.length
 || next.ip_adjustment_policy !== "unspecified"
 || next.no_planned_adjustment_statement.trim();
 if (hasStructuredContent && next.authority !== "structured") next.authority = "structured";
 onChange(next);
 };

 const listOps = (field, factory) => ({
 add: () => update({ [field]: [...rules[field], factory()] }),
 addWith: (override) => update({ [field]: [...rules[field], { ...factory(), ...override }] }),
 removeItem: (index) => update({ [field]: rules[field].filter((_, i) => i !== index) }),
 setItem: (index, patch) => update({ [field]: rules[field].map((item, i) => (i === index ? { ...item, ...patch } : item)) }),
 });

 const toggleCollapsed = () => setCollapsed((v) => !v);
 const setPanel = (key) => onPanelChange?.(key);

 const ipActionIds = rules.ip_action_rules.map((r) => r.rule_id);
 const nonIpIds = rules.non_ip_treatment_rules.map((r) => r.rule_id);

 return (
 <section className="intervention-rules-editor">
 <header className="intervention-rules-head" onClick={toggleCollapsed} role="button" tabIndex={0} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); toggleCollapsed(); } }}>
 <span className="intervention-rules-toggle">{collapsed ? <ChevronRight size={14} /> : <ChevronDown size={14} />}</span>
 <div>
 <strong>结构化干预规则编辑器</strong>
 <small>试验药物与给药、剂量调整、非试验用药/补救、合并用药分栏维护；IP与CM边界不混用。</small>
 </div>
 <span className={`intervention-rules-authority ${rules.authority}`}>{rules.authority === "structured" ? "结构化" : "兼容模式"}</span>
 </header>
 {!collapsed && (
 <>
 <div className="intervention-rules-segments" role="tablist">
 {PANELS.map(([key, label]) => (
 <button key={key} type="button" role="tab" aria-selected={activePanel === key} className={activePanel === key ? "active" : ""} onClick={() => setPanel(key)}>{label}</button>
 ))}
 </div>
 <div className="intervention-rules-body">
 {activePanel === "regimen" && <RegimenPanel rules={rules} ops={listOps("ip_regimens", newRowRegimen)} />}
 {activePanel === "ip_actions" && <IpActionsPanel rules={rules} update={update} ops={listOps("ip_action_rules", newRowIpAction)} nonIpIds={nonIpIds} />}
 {activePanel === "non_ip" && <NonIpPanel rules={rules} ops={listOps("non_ip_treatment_rules", newRowNonIp)} linkOps={listOps("cross_object_links", newRowLink)} ipActionIds={ipActionIds} />}
 {activePanel === "cm" && <CmPanel rules={rules} ops={listOps("non_ip_treatment_rules", newRowNonIp)} linkOps={listOps("cross_object_links", newRowLink)} ipActionIds={ipActionIds} />}
 </div>
 </>
 )}
 </section>
 );
}

function DenseRow({ index, onDelete, deleteLabel, children }) {
 return (
 <div className="intervention-rules-row">
 <span className="intervention-rules-row-index">{String(index + 1).padStart(2, "0")}</span>
 <div className="intervention-rules-row-fields">{children}</div>
 <button type="button" className="icon-button intervention-rules-row-delete" onClick={onDelete} title={deleteLabel}><Trash2 size={14} /></button>
 </div>
 );
}

function MiniInput({ label, value, onChange, placeholder, span }) {
 return (
 <label className={`intervention-rules-mini ${span ? `span-${span}` : ""}`}>
 <span>{label}</span>
 <input value={value || ""} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} />
 </label>
 );
}
function MiniSelect({ label, value, onChange, options, disabled = false }) {
 return (
 <label className="intervention-rules-mini">
 <span>{label}</span>
 <select value={value || ""} onChange={(e) => onChange(e.target.value)} disabled={disabled}>
 {options.map(([val, lbl]) => <option key={val} value={val}>{lbl}</option>)}
 </select>
 </label>
 );
}
function MiniArea({ label, value, onChange, placeholder, rows }) {
 return (
 <label className="intervention-rules-mini span-full">
 <span>{label}</span>
 <textarea rows={rows || 2} value={value || ""} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} />
 </label>
 );
}

function MiniListInput({ label, value, onChange, span = 2 }) {
 return <MiniInput label={label} value={(value || []).join("；")} onChange={(text) => onChange(text.split(/[;；\n]+/).map((item) => item.trim()).filter(Boolean))} span={span} />;
}

function PanelAddButton({ label, onClick }) {
 return <button type="button" className="intervention-rules-add" onClick={onClick}><Plus size={14} /> {label}</button>;
}

function EmptyHint({ text }) {
 return <p className="intervention-rules-empty">{text}</p>;
}

function RegimenPanel({ rules, ops }) {
 return (
 <div className="intervention-rules-panel">
 <p className="intervention-rules-panel-hint">试验药物常规给药方案（IP）。CM剂量调整不在此处。</p>
 {rules.ip_regimens.length === 0 && <EmptyHint text="尚未登记试验药物给药方案。" />}
 {rules.ip_regimens.map((row, i) => (
 <DenseRow key={row.regimen_id} index={i} onDelete={() => ops.removeItem(i)} deleteLabel="删除给药方案">
 <MiniInput label="产品名称" value={row.product_name} onChange={(v) => ops.setItem(i, { product_name: v })} />
 <MiniSelect label="产品角色" value={row.product_role} onChange={(v) => ops.setItem(i, { product_role: v })} options={PRODUCT_ROLE_OPTIONS} />
 <MiniInput label="用法用量" value={row.dose_and_frequency} onChange={(v) => ops.setItem(i, { dose_and_frequency: v })} span={2} />
 <MiniInput label="给药途径" value={row.route} onChange={(v) => ops.setItem(i, { route: v })} />
 <MiniInput label="治疗时期" value={row.treatment_period} onChange={(v) => ops.setItem(i, { treatment_period: v })} />
 <MiniInput label="依从性说明" value={row.adherence_notes} onChange={(v) => ops.setItem(i, { adherence_notes: v })} span={2} />
 <MiniInput label="来源定位" value={row.source_location} onChange={(v) => ops.setItem(i, { source_location: v })} span={2} />
 </DenseRow>
 ))}
 <PanelAddButton label="新增给药方案" onClick={ops.add} />
 </div>
 );
}

function IpActionsPanel({ rules, update, ops, nonIpIds }) {
 const policy = rules.ip_adjustment_policy;
 return (
 <div className="intervention-rules-panel">
 <div className="intervention-rules-policy-bar">
 <label className="intervention-rules-mini">
 <span>剂量调整策略</span>
 <select value={policy} onChange={(e) => update({ ip_adjustment_policy: e.target.value })}>
 {ADJUSTMENT_POLICY_OPTIONS.map(([val, lbl]) => <option key={val} value={val}>{lbl}</option>)}
 </select>
 </label>
 {policy === "no_planned_adjustment" && (
 <label className="intervention-rules-mini span-full">
 <span>无计划性调整说明（必填）</span>
 <input value={rules.no_planned_adjustment_statement || ""} onChange={(e) => update({ no_planned_adjustment_statement: e.target.value })} placeholder="说明本研究无计划性常规剂量调整，可包含安全中断/永久停药/减量/随访规则" />
 </label>
 )}
 </div>
 {rules.ip_action_rules.length === 0 && <EmptyHint text="尚未登记试验药物剂量调整规则。" />}
 {rules.ip_action_rules.map((row, i) => (
 <DenseRow key={row.rule_id} index={i} onDelete={() => ops.removeItem(i)} deleteLabel="删除IP调整规则">
 <MiniSelect label="调整类型" value={row.action_kind} onChange={(v) => ops.setItem(i, { action_kind: v })} options={ACTION_KIND_OPTIONS} />
 <MiniInput label="触发条件" value={row.trigger} onChange={(v) => ops.setItem(i, { trigger: v })} span={3} />
 <MiniInput label="严重程度/阈值" value={row.severity_or_threshold} onChange={(v) => ops.setItem(i, { severity_or_threshold: v })} span={2} />
 <MiniInput label="确认要求" value={row.confirmation_required} onChange={(v) => ops.setItem(i, { confirmation_required: v })} span={2} />
 <MiniArea label="试验药物处置" value={row.study_product_action} onChange={(v) => ops.setItem(i, { study_product_action: v })} />
 <MiniArea label="复测/恢复条件" value={row.retest_recovery} onChange={(v) => ops.setItem(i, { retest_recovery: v })} />
 <MiniInput label="等待期" value={row.wait_period} onChange={(v) => ops.setItem(i, { wait_period: v })} span={2} />
 <MiniListInput label="例外条件" value={row.exceptions} onChange={(v) => ops.setItem(i, { exceptions: v })} />
 {row.action_kind === "permanent_discontinuation" && (
 <MiniArea label="永久停药条件" value={row.permanent_discontinuation_condition} onChange={(v) => ops.setItem(i, { permanent_discontinuation_condition: v })} />
 )}
 {row.action_kind === "discontinuation_taper" && <MiniListInput label="递减步骤" value={row.taper_steps} onChange={(v) => ops.setItem(i, { taper_steps: v })} span={4} />}
 <MiniInput label="审批人" value={(row.approvers || []).join("、")} onChange={(v) => ops.setItem(i, { approvers: v.split(/[、,;，；\n]+/).map((s) => s.trim()).filter(Boolean) })} span={2} />
 <MiniInput label="来源定位" value={row.source_location} onChange={(v) => ops.setItem(i, { source_location: v })} span={2} />
 <MiniArea label="备注" value={row.notes} onChange={(v) => ops.setItem(i, { notes: v })} />
 </DenseRow>
 ))}
 <PanelAddButton label="新增IP剂量调整规则" onClick={ops.add} />
 {nonIpIds.length > 0 && rules.ip_action_rules.length > 0 && (
 <p className="intervention-rules-panel-hint">非试验治疗或 CM 对试验用药品的影响，请在对应规则面板建立显式关联。</p>
 )}
 </div>
 );
}

function NonIpPanel({ rules, ops, linkOps, ipActionIds }) {
 const filtered = rules.non_ip_treatment_rules.map((row, originalIndex) => ({ row, originalIndex })).filter(({ row }) => ["background", "rescue", "other_non_investigational"].includes(row.rule_class));
 const sourceRuleIds = filtered.map(({ row }) => row.rule_id);
 return (
 <div className="intervention-rules-panel">
 <p className="intervention-rules-panel-hint">背景治疗、补救治疗及其他非试验用药。合并用药（允许/禁止）请在"合并用药"面板维护。</p>
 {filtered.length === 0 && <EmptyHint text="尚未登记非试验用药/补救治疗规则。" />}
 {filtered.map(({ row, originalIndex }, displayIndex) => (
 <DenseRow key={row.rule_id} index={displayIndex} onDelete={() => ops.removeItem(originalIndex)} deleteLabel="删除非IP规则">
 <MiniSelect label="规则类别" value={row.rule_class} onChange={(v) => ops.setItem(originalIndex, { rule_class: v, policy: v === "rescue" ? "rescue_policy" : row.policy === "rescue_policy" ? "allowed" : row.policy })} options={NON_IP_RULE_CLASS_OPTIONS} />
 <MiniSelect label="策略" value={row.policy} onChange={(v) => ops.setItem(originalIndex, { policy: v })} options={POLICY_OPTIONS} />
 <MiniInput label="药物/类别" value={row.agent_or_category} onChange={(v) => ops.setItem(originalIndex, { agent_or_category: v })} span={2} />
 <MiniInput label="采集窗口" value={row.collection_window} onChange={(v) => ops.setItem(originalIndex, { collection_window: v })} />
 <MiniListInput label="时间限制" value={row.timing_restrictions} onChange={(v) => ops.setItem(originalIndex, { timing_restrictions: v })} />
 <MiniInput label="洗脱/时间窗" value={row.washout_or_window} onChange={(v) => ops.setItem(originalIndex, { washout_or_window: v })} span={2} />
 <MiniInput label="阶段适用性" value={row.phase_applicability} onChange={(v) => ops.setItem(originalIndex, { phase_applicability: v })} span={2} />
 <MiniInput label="CM剂量规则" value={row.cm_dose_rule} onChange={(v) => ops.setItem(originalIndex, { cm_dose_rule: v })} span={2} />
 <MiniListInput label="例外条件" value={row.exceptions} onChange={(v) => ops.setItem(originalIndex, { exceptions: v })} />
 <MiniInput label="来源定位" value={row.source_location} onChange={(v) => ops.setItem(originalIndex, { source_location: v })} span={2} />
 <MiniArea label="备注" value={row.notes} onChange={(v) => ops.setItem(originalIndex, { notes: v })} />
 </DenseRow>
 ))}
 <PanelAddButton label="新增非IP规则" onClick={ops.add} />
 <CrossObjectLinks rules={rules} linkOps={linkOps} ipActionIds={ipActionIds} sourceRuleIds={sourceRuleIds} defaultSourceKind="rescue" />
 </div>
 );
}

function CmPanel({ rules, ops, linkOps, ipActionIds }) {
 const cmRows = rules.non_ip_treatment_rules.map((row, originalIndex) => ({ row, originalIndex })).filter(({ row }) => ["allowed_cm", "prohibited_cm"].includes(row.rule_class));
 const sourceRuleIds = cmRows.map(({ row }) => row.rule_id);
 return (
 <div className="intervention-rules-panel">
 <p className="intervention-rules-panel-hint">合并用药允许/禁止规则。CM剂量变更不会生成IP剂量调整规则。</p>
 {cmRows.length === 0 && <EmptyHint text="尚未登记合并用药规则。新增非IP规则后选择允许的合并用药或禁止的合并用药类别即可。" />}
 {cmRows.map(({ row, originalIndex }, displayIndex) => (
 <DenseRow key={row.rule_id} index={displayIndex} onDelete={() => ops.removeItem(originalIndex)} deleteLabel="删除CM规则">
 <MiniSelect label="规则类别" value={row.rule_class} onChange={(v) => ops.setItem(originalIndex, { rule_class: v, policy: v === "prohibited_cm" ? "prohibited" : row.policy === "prohibited" ? "allowed" : row.policy })} options={CM_RULE_CLASS_OPTIONS} />
 <MiniSelect label="策略" value={row.policy} onChange={(v) => ops.setItem(originalIndex, { policy: v })} options={POLICY_OPTIONS} />
 <MiniInput label="药物/类别" value={row.agent_or_category} onChange={(v) => ops.setItem(originalIndex, { agent_or_category: v })} span={2} />
 <MiniInput label="CM剂量规则" value={row.cm_dose_rule} onChange={(v) => ops.setItem(originalIndex, { cm_dose_rule: v })} span={2} />
 <MiniInput label="采集窗口" value={row.collection_window} onChange={(v) => ops.setItem(originalIndex, { collection_window: v })} />
 <MiniListInput label="时间限制" value={row.timing_restrictions} onChange={(v) => ops.setItem(originalIndex, { timing_restrictions: v })} />
 <MiniInput label="洗脱/时间窗" value={row.washout_or_window} onChange={(v) => ops.setItem(originalIndex, { washout_or_window: v })} span={2} />
 <MiniInput label="阶段适用性" value={row.phase_applicability} onChange={(v) => ops.setItem(originalIndex, { phase_applicability: v })} span={2} />
 <MiniListInput label="例外条件" value={row.exceptions} onChange={(v) => ops.setItem(originalIndex, { exceptions: v })} />
 <MiniInput label="来源定位" value={row.source_location} onChange={(v) => ops.setItem(originalIndex, { source_location: v })} span={2} />
 <MiniArea label="备注" value={row.notes} onChange={(v) => ops.setItem(originalIndex, { notes: v })} />
 </DenseRow>
 ))}
 <PanelAddButton label="新增CM规则" onClick={() => ops.addWith({ rule_class: "allowed_cm" })} />
 <CrossObjectLinks rules={rules} linkOps={linkOps} ipActionIds={ipActionIds} sourceRuleIds={sourceRuleIds} defaultSourceKind="cm" />
 </div>
 );
}

function CrossObjectLinks({ rules, linkOps, ipActionIds, sourceRuleIds, defaultSourceKind }) {
 const links = rules.cross_object_links.map((link, originalIndex) => ({ link, originalIndex })).filter(({ link }) => sourceRuleIds.includes(link.source_rule_id));
 if (!sourceRuleIds.length || !ipActionIds.length) return null;
 const nonIpById = new Map(rules.non_ip_treatment_rules.map((rule) => [rule.rule_id, rule]));
 const ipActionById = new Map(rules.ip_action_rules.map((rule) => [rule.rule_id, rule]));
 const sourceKind = (ruleId) => {
 const ruleClass = nonIpById.get(ruleId)?.rule_class;
 if (ruleClass === "rescue") return "rescue";
 if (ruleClass === "background") return "background";
 if (["allowed_cm", "prohibited_cm"].includes(ruleClass)) return "cm";
 return "other_non_ip";
 };
 const sourceOptions = sourceRuleIds.map((id) => {
 const rule = nonIpById.get(id);
 return [id, `${rule?.agent_or_category || "未命名规则"} (${id})`];
 });
 const targetOptions = ipActionIds.map((id) => {
 const rule = ipActionById.get(id);
 const actionLabel = ACTION_KIND_OPTIONS.find(([value]) => value === rule?.action_kind)?.[1] || "试验用药品处置";
 return [id, `${actionLabel}${rule?.trigger ? ` · ${rule.trigger}` : ""} (${id})`];
 });
 return (
 <div className="intervention-rules-links">
 <header><strong>跨对象关联</strong><span>明确非试验治疗或 CM 是否触发试验用药品暂停、停止或恢复；不会把两类规则合并。</span></header>
 {links.map(({ link, originalIndex }, displayIndex) => (
 <DenseRow key={link.link_id} index={displayIndex} onDelete={() => linkOps.removeItem(originalIndex)} deleteLabel="删除关联">
 <MiniSelect label="来源规则" value={link.source_rule_id} onChange={(v) => linkOps.setItem(originalIndex, { source_rule_id: v, source_kind: sourceKind(v) })} options={sourceOptions} />
 <MiniSelect label="来源类型" value={sourceKind(link.source_rule_id)} onChange={() => {}} options={[["rescue", "补救治疗"], ["cm", "合并用药"], ["background", "背景治疗"], ["other_non_ip", "其他非试验治疗"]]} disabled />
 <MiniSelect label="目标试验用药品规则" value={link.target_rule_id} onChange={(v) => linkOps.setItem(originalIndex, { target_rule_id: v })} options={[["", "—无—"], ...targetOptions]} />
 <MiniSelect label="动作" value={link.action} onChange={(v) => linkOps.setItem(originalIndex, { action: v })} options={LINK_ACTION_OPTIONS} />
 <MiniInput label="恢复条件" value={link.resume_condition} onChange={(v) => linkOps.setItem(originalIndex, { resume_condition: v })} span={2} />
 <MiniInput label="来源定位" value={link.source_location} onChange={(v) => linkOps.setItem(originalIndex, { source_location: v })} span={2} />
 <MiniArea label="补充说明" value={link.notes} onChange={(v) => linkOps.setItem(originalIndex, { notes: v })} />
 </DenseRow>
 ))}
 <PanelAddButton label="新增跨对象关联" onClick={() => linkOps.addWith({ source_rule_id: sourceRuleIds[0], source_kind: sourceKind(sourceRuleIds[0]) || defaultSourceKind, target_rule_id: ipActionIds[0] })} />
 </div>
 );
}

import { useEffect, useMemo, useRef, useState } from "react";
import {
 CheckCircle2,
 FileCheck2,
 FileText,
 RefreshCw,
 ShieldAlert,
 X,
} from "lucide-react";

const ACTOR = "medical_manager";

const LEGACY_BOOTSTRAP_CONFIRMED_PATHS = Object.freeze([
 "framing.protocol_id",
 "framing.version",
 "framing.document_title",
 "framing.indication",
 "framing.study_phase",
 "framing.investigational_product",
 "framing.target_mechanism",
 "framing.design_pattern",
 "framing.population_intent",
 "picos.population_summary",
 "picos.intervention_summary",
 "picos.comparator_summary",
 "picos.primary_endpoint",
]);

function apiErrorText(error) {
 return String(error?.detail || error?.message || error || "请求失败");
}

async function readJsonOrThrow(response) {
 const payload = await response.json().catch(() => ({}));
 if (!response.ok) {
 const error = new Error(payload?.detail || `请求失败（${response.status}）`);
 error.status = response.status;
 error.detail = payload?.detail || "";
 throw error;
 }
 return payload;
}

function roleLabel(role) {
 return role === "synopsis" ? "方案摘要" : "完整研究方案";
}

function extractionStageLabel(jobStatus) {
 return {
 queued: "等待独立AI处理",
 parsing: "正在解析文件内容",
 ai_synthesis: "正在提取研究设计",
 validating: "正在合并并核对结果",
 }[jobStatus] || "正在处理原始文件";
}

function clone(value) {
 return value == null ? value : JSON.parse(JSON.stringify(value));
}

function warningList(candidate) {
 return Array.from(new Set(
 (candidate?.source?.validation_warnings || []).filter(Boolean),
 ));
}

function storageKey(projectId) {
 return `mw-legacy-bootstrap:${projectId}`;
}

function readStoredImportKey(projectId) {
 try {
 return globalThis.sessionStorage?.getItem(storageKey(projectId)) || "";
 } catch {
 return "";
 }
}

function writeStoredImportKey(projectId, value) {
 try {
 globalThis.sessionStorage?.setItem(storageKey(projectId), value);
 } catch {
 // The server-side idempotency key still protects the active request.
 }
}

function clearStoredImportKey(projectId) {
 try {
 globalThis.sessionStorage?.removeItem(storageKey(projectId));
 } catch {
 // A blocked session store must not make the import workflow unusable.
 }
}

function TextField({
 fieldPath,
 label,
 value,
 onChange,
 wide = false,
 multiline = false,
}) {
 const confirmedPath = LEGACY_BOOTSTRAP_CONFIRMED_PATHS.includes(fieldPath)
 ? fieldPath
 : undefined;
 return (
 <label className={wide ? "span-2" : ""} data-confirmed-path={confirmedPath}>
 <span>{label}</span>
 {multiline
 ? <textarea rows={3} value={value || ""} onChange={(event) => onChange(event.target.value)} />
 : <input value={value || ""} onChange={(event) => onChange(event.target.value)} />}
 </label>
 );
}

export function LegacyAuthoringBootstrapPanel({
 projectId,
 expectedIndication = "",
 onConfirmed,
 onOpenBinding,
}) {
 const [status, setStatus] = useState(null);
 const [open, setOpen] = useState(false);
 const [busy, setBusy] = useState("");
 const [message, setMessage] = useState("");
 const [importKey, setImportKey] = useState("");
 const [framing, setFraming] = useState(null);
 const [picos, setPicos] = useState(null);
 const [synopsisText, setSynopsisText] = useState("");
 const [confirmedRole, setConfirmedRole] = useState("protocol");
 const [roleOverrideReason, setRoleOverrideReason] = useState("");
 const [acknowledgedWarnings, setAcknowledgedWarnings] = useState([]);
 const [validationOverrideReason, setValidationOverrideReason] = useState("");
 const requestRef = useRef(0);

 const detectedRole = status?.detected_source_role || status?.source_role || "protocol";
 const warnings = useMemo(() => warningList(status?.candidate), [status?.candidate]);
 const roleOverridden = Boolean(confirmedRole && confirmedRole !== detectedRole);
 const allWarningsAcknowledged = warnings.every((warning) => acknowledgedWarnings.includes(warning));
 const missingCoreFields = useMemo(() => {
 if (!framing || !picos) return [];
 const fields = [
 ["方案号", framing.protocol_id],
 ["版本", framing.version],
 ["方案标题", framing.document_title],
 ["适应症", framing.indication],
 ["研究分期", framing.study_phase],
 ["试验药物", framing.investigational_product],
 ["总体设计", framing.design_pattern],
 ["目标研究人群", framing.population_intent],
 ["研究人群", picos.population_summary],
 ["干预措施", picos.intervention_summary],
 ["主要终点及评价时间", picos.primary_endpoint],
 ["方案摘要文本", synopsisText],
 ];
 return fields.filter(([, value]) => !String(value || "").trim()).map(([label]) => label);
 }, [framing, picos, synopsisText]);
 const confirmationReady = Boolean(
 status?.state === "review_pending"
 && status?.candidate?.source?.source_id
 && framing
 && picos
 && synopsisText.trim()
 && missingCoreFields.length === 0
 && allWarningsAcknowledged
 && (!warnings.length || validationOverrideReason.trim().length >= 10)
 && (!roleOverridden || roleOverrideReason.trim().length >= 10)
 );

 const loadStatus = async (key = importKey, { quiet = false } = {}) => {
 const requestId = requestRef.current + 1;
 requestRef.current = requestId;
 if (!quiet) setBusy("loading");
 try {
 const query = key ? `?import_idempotency_key=${encodeURIComponent(key)}` : "";
 const payload = await fetch(
 `/api/projects/${projectId}/medical-writing/legacy-authoring-bootstrap${query}`,
 ).then(readJsonOrThrow);
 if (requestId !== requestRef.current) return null;
 setStatus(payload);
 setConfirmedRole(
 payload.confirmed_source_role
 || payload.author_confirmed_source_role
 || payload.source_role
 || "protocol",
 );
 if (payload.import_idempotency_key) {
 setImportKey(payload.import_idempotency_key);
 writeStoredImportKey(projectId, payload.import_idempotency_key);
 }
 if (payload.candidate) {
 setFraming(clone(payload.candidate.proposed_framing));
 setPicos(clone(payload.candidate.proposed_picos));
 setSynopsisText(payload.candidate.proposed_synopsis_text || "");
 }
 if (["bound", "not_eligible"].includes(payload.state)) {
 clearStoredImportKey(projectId);
 }
 setMessage(payload.message || "");
 return payload;
 } catch (error) {
 if (requestId !== requestRef.current) return null;
 setMessage(apiErrorText(error));
 return null;
 } finally {
 if (requestId === requestRef.current && !quiet) setBusy("");
 }
 };

 useEffect(() => {
 const stored = readStoredImportKey(projectId);
 setImportKey(stored);
 loadStatus(stored);
 return () => {
 requestRef.current += 1;
 };
 // The bootstrap source is scoped by project and immutable source hash.
 // eslint-disable-next-line react-hooks/exhaustive-deps
 }, [projectId]);

 useEffect(() => {
 if (!["extracting"].includes(status?.state) || !importKey) return undefined;
 let cancelled = false;
 let timer;
 const poll = async () => {
 await loadStatus(importKey, { quiet: true });
 if (!cancelled) timer = globalThis.setTimeout(poll, 3000);
 };
 timer = globalThis.setTimeout(poll, 3000);
 return () => {
 cancelled = true;
 globalThis.clearTimeout(timer);
 };
 // eslint-disable-next-line react-hooks/exhaustive-deps
 }, [status?.state, importKey]);

 useEffect(() => {
 if (!open) return undefined;
 const handleKeyDown = (event) => {
 if (event.key === "Escape") setOpen(false);
 };
 globalThis.addEventListener?.("keydown", handleKeyDown);
 return () => globalThis.removeEventListener?.("keydown", handleKeyDown);
 }, [open]);

 useEffect(() => {
 setAcknowledgedWarnings([]);
 setValidationOverrideReason("");
 }, [
 status?.candidate?.source?.content_sha256,
 status?.candidate?.source?.extraction_revision,
 ]);

 const startExtraction = async () => {
 if (!status?.document_id || !status?.source_sha256) return;
 const retrySuffix = status.state === "failed" ? `-${Date.now()}` : "";
 const key = `legacy-extract-${projectId}-${status.source_sha256.slice(0, 16)}${retrySuffix}`.slice(0, 200);
 setBusy("prepare");
 setMessage("");
 try {
 const payload = await fetch(
 `/api/projects/${projectId}/medical-writing/legacy-authoring-bootstrap/prepare`,
 {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 expected_document_id: status.document_id,
 expected_source_sha256: status.source_sha256,
 expected_indication: expectedIndication || "",
 actor: ACTOR,
 idempotency_key: key,
 }),
 },
 ).then(readJsonOrThrow);
 setImportKey(payload.import_idempotency_key || key);
 writeStoredImportKey(projectId, payload.import_idempotency_key || key);
 setStatus(payload);
 setMessage("正在从原始文件提取研究框架、PICOS和方案摘要。");
 } catch (error) {
 setMessage(apiErrorText(error));
 } finally {
 setBusy("");
 }
 };

 const updateFraming = (field, value) => {
 setFraming((current) => ({ ...current, [field]: value }));
 };

 const updatePicos = (field, value) => {
 setPicos((current) => ({ ...current, [field]: value }));
 };

 const toggleWarning = (warning) => {
 setAcknowledgedWarnings((current) => (
 current.includes(warning)
 ? current.filter((item) => item !== warning)
 : [...current, warning]
 ));
 };

 const confirmCandidate = async () => {
 if (!confirmationReady) return;
 setBusy("confirm");
 setMessage("");
 try {
 const payload = await fetch(
 `/api/projects/${projectId}/medical-writing/legacy-authoring-bootstrap/confirm`,
 {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 expected_document_id: status.document_id,
 expected_source_sha256: status.source_sha256,
 import_idempotency_key: importKey,
 source_id: status.candidate.source.source_id,
 framing,
 picos,
 synopsis_text: synopsisText,
 confirmed_source_role: confirmedRole,
 source_role_override_reason: roleOverridden ? roleOverrideReason.trim() : "",
 acknowledged_validation_warnings: acknowledgedWarnings,
 validation_override_reason: warnings.length ? validationOverrideReason.trim() : "",
 actor: ACTOR,
 idempotency_key: `legacy-confirm-${projectId}-${status.source_sha256.slice(0, 16)}`.slice(0, 200),
 }),
 },
 ).then(readJsonOrThrow);
 setStatus(payload);
 clearStoredImportKey(projectId);
 setMessage("研究设计基线已建立；原始文件保持只读，下一步核对影响并重绑定。");
 await onConfirmed?.(payload);
 } catch (error) {
 setMessage(apiErrorText(error));
 } finally {
 setBusy("");
 }
 };

 if (!status || ["bound", "not_eligible"].includes(status.state)) return null;

 return (
 <>
 <section className={`legacy-bootstrap-bar ${status.state === "failed" ? "is-error" : ""}`}>
 <div>
 {status.state === "confirmed_ready_for_binding"
 ? <CheckCircle2 size={17} />
 : status.state === "failed"
 ? <ShieldAlert size={17} />
 : <FileText size={17} />}
 <span>
 <strong>
 {status.state === "confirmed_ready_for_binding"
 ? "已从原始方案建立研究设计基线"
 : status.state === "extracting"
 ? "正在解析原始方案"
 : status.state === "review_pending"
 ? "研究设计候选待作者核对"
 : status.state === "failed"
 ? "原始方案解析未完成"
 : "原始方案尚未建立研究设计基线"}
 </strong>
 <small>
 {status.source_filename || "原始方案"}
 {` · 系统识别为${roleLabel(detectedRole)}`}
 </small>
 </span>
 </div>
 {status.state === "confirmed_ready_for_binding"
 ? <button type="button" onClick={onOpenBinding}><FileCheck2 size={14} /> 核对影响并重绑定</button>
 : <button type="button" onClick={() => setOpen(true)}>
 {status.state === "review_pending" ? "核对提取结果" : status.state === "extracting" ? "查看进度" : "建立研究设计基线"}
 </button>}
 </section>

 {open && (
 <div className="legacy-bootstrap-layer" role="presentation" onMouseDown={(event) => {
 if (event.target === event.currentTarget) setOpen(false);
 }}>
 <aside className="legacy-bootstrap-drawer" role="dialog" aria-modal="true" aria-label="原始方案研究设计基线">
 <header>
 <div>
 <span>原始方案导入</span>
 <strong>建立可追溯的研究设计基线</strong>
 </div>
 <button type="button" onClick={() => setOpen(false)} title="关闭"><X size={18} /></button>
 </header>

 <div className="legacy-bootstrap-source">
 <FileText size={18} />
 <span>
 <strong title={status.source_filename}>{status.source_filename}</strong>
 <small>原始文件只读 · {status.source_sha256?.slice(0, 12)}…</small>
 </span>
 <em>{roleLabel(detectedRole)}</em>
 </div>

 {status.state === "eligible" || status.state === "failed" ? (
 <section className="legacy-bootstrap-start">
 <p>独立AI将提取研究框架、PICOS和方案摘要；完成后直接核对并修订候选。</p>
 {message && <small className={status.state === "failed" ? "danger" : ""}>{message}</small>}
 <button type="button" className="primary-button" onClick={startExtraction} disabled={Boolean(busy)}>
 <RefreshCw size={15} /> {busy === "prepare" ? "正在启动" : status.state === "failed" ? "重新解析" : "AI提取研究设计"}
 </button>
 </section>
 ) : status.state === "extracting" ? (
 <section className="legacy-bootstrap-progress" aria-live="polite">
 <RefreshCw size={20} className="spin" />
 <strong>{extractionStageLabel(status.job_status)}</strong>
 <span>可关闭面板继续其他工作，完成后将自动显示可编辑候选。</span>
 <ol aria-label="提取进度">
 <li className="is-complete"><CheckCircle2 size={14} /> 文件解析</li>
 <li className={status.job_status === "validating" ? "is-complete" : "is-active"}>
 {status.job_status === "validating"
 ? <CheckCircle2 size={14} />
 : <RefreshCw size={14} className="spin" />}
 研究设计提取
 </li>
 <li className={status.job_status === "validating" ? "is-active" : ""}>
 <FileCheck2 size={14} /> 合并核对
 </li>
 </ol>
 </section>
 ) : status.state === "review_pending" && framing && picos ? (
 <div className="legacy-bootstrap-review">
 <section className="legacy-bootstrap-role">
 <div>
 <strong>文件角色</strong>
 <small>系统识别只作为建议；您的选择即为本项目确认。</small>
 </div>
 <select value={confirmedRole} onChange={(event) => setConfirmedRole(event.target.value)}>
 <option value="protocol">完整研究方案</option>
 <option value="synopsis">方案摘要</option>
 </select>
 {roleOverridden && (
 <label>
 <span>调整理由</span>
 <textarea rows={2} value={roleOverrideReason} onChange={(event) => setRoleOverrideReason(event.target.value)} placeholder="说明为何原文件应按所选角色使用；不少于10个字符。" />
 </label>
 )}
 </section>

 <section>
 <header><strong>研究基本信息</strong><small>AI已预填；仅修订不准确处。</small></header>
 <div className="legacy-bootstrap-grid">
 <TextField fieldPath="framing.protocol_id" label="方案号" value={framing.protocol_id} onChange={(value) => updateFraming("protocol_id", value)} />
 <TextField fieldPath="framing.version" label="版本" value={framing.version} onChange={(value) => updateFraming("version", value)} />
 <TextField fieldPath="framing.document_title" wide label="方案标题" value={framing.document_title} onChange={(value) => updateFraming("document_title", value)} />
 <TextField fieldPath="framing.indication" label="适应症" value={framing.indication} onChange={(value) => updateFraming("indication", value)} />
 <TextField fieldPath="framing.study_phase" label="研究分期" value={framing.study_phase} onChange={(value) => updateFraming("study_phase", value)} />
 <TextField fieldPath="framing.investigational_product" label="试验药物" value={framing.investigational_product} onChange={(value) => updateFraming("investigational_product", value)} />
 <TextField fieldPath="framing.target_mechanism" label="靶点/作用机制" value={framing.target_mechanism} onChange={(value) => updateFraming("target_mechanism", value)} />
 <TextField fieldPath="framing.design_pattern" wide multiline label="总体设计" value={framing.design_pattern} onChange={(value) => updateFraming("design_pattern", value)} />
 <TextField fieldPath="framing.population_intent" wide multiline label="目标研究人群" value={framing.population_intent} onChange={(value) => updateFraming("population_intent", value)} />
 </div>
 </section>

 <section>
 <header><strong>PICOS核心设计</strong><small>保留提取的完整结构化对象。</small></header>
 <div className="legacy-bootstrap-grid">
 <TextField fieldPath="picos.population_summary" wide multiline label="研究人群" value={picos.population_summary} onChange={(value) => updatePicos("population_summary", value)} />
 <TextField fieldPath="picos.intervention_summary" wide multiline label="干预措施" value={picos.intervention_summary} onChange={(value) => updatePicos("intervention_summary", value)} />
 <TextField fieldPath="picos.comparator_summary" wide multiline label="对照" value={picos.comparator_summary} onChange={(value) => updatePicos("comparator_summary", value)} />
 <TextField fieldPath="picos.primary_endpoint" wide multiline label="主要终点及评价时间" value={picos.primary_endpoint} onChange={(value) => updatePicos("primary_endpoint", value)} />
 <TextField wide multiline label="方案摘要文本" value={synopsisText} onChange={setSynopsisText} />
 </div>
 </section>

 {status.candidate.conflict_notes?.length > 0 && (
 <section className="legacy-bootstrap-conflicts">
 <header><strong>提取冲突</strong><small>请直接在上方候选中修正；不会作为自动确认事实。</small></header>
 <ul>{status.candidate.conflict_notes.map((item) => <li key={item}>{item}</li>)}</ul>
 </section>
 )}

 {warnings.length > 0 && (
 <section className="legacy-bootstrap-warnings">
 <header><strong>内容校验提示</strong><small>逐项确认后仍可沿用，原提示会持续保留。</small></header>
 {warnings.map((warning) => (
 <label key={warning}>
 <input type="checkbox" checked={acknowledgedWarnings.includes(warning)} onChange={() => toggleWarning(warning)} />
 <span>{warning}</span>
 </label>
 ))}
 <label>
 <span>沿用理由</span>
 <textarea rows={2} value={validationOverrideReason} onChange={(event) => setValidationOverrideReason(event.target.value)} placeholder="说明为何该文件仍可用于当前项目；不少于10个字符。" />
 </label>
 </section>
 )}
 {missingCoreFields.length > 0 && (
 <section className="legacy-bootstrap-missing" role="status">
 <strong>还需补全 {missingCoreFields.length} 项</strong>
 <span>{missingCoreFields.join("、")}</span>
 </section>
 )}
 </div>
 ) : null}

 <footer>
 <span className={message && /失败|错误|变化|冲突/.test(message) ? "danger" : ""}>
 {["review_pending", "confirmed_ready_for_binding"].includes(status.state) ? message : ""}
 </span>
 <div>
 <button type="button" onClick={() => setOpen(false)}>稍后处理</button>
 {status.state === "review_pending" && (
 <button type="button" className="primary-button" onClick={confirmCandidate} disabled={!confirmationReady || Boolean(busy)}>
 <FileCheck2 size={15} /> {busy === "confirm" ? "正在建立" : "确认并建立研究设计"}
 </button>
 )}
 </div>
 </footer>
 </aside>
 </div>
 )}
 </>
 );
}

.phase1-parts-editor {
 min-width: 0;
 display: grid;
 gap: 10px;
 border-top: 1px solid var(--line);
 padding-top: 12px;
}

.phase1-parts-editor > header {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 16px;
}

.phase1-parts-editor > header > div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.phase1-parts-editor > header strong {
 font-size: 13px;
}

.phase1-parts-editor > header span,
.phase1-parts-editor > header small {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.phase1-parts-editor > header button {
