 color: var(--muted);
 font-size: 11px;
 cursor: pointer;
}

.phase1-part-selector label:nth-child(4n) {
 border-right: 0;
}

.phase1-part-selector label:nth-last-child(-n + 4) {
 border-bottom: 0;
}

.phase1-part-selector label.selected {
 box-shadow: inset 3px 0 0 var(--brand);
 background: #fff7f2;
 color: var(--text);
 font-weight: 600;
}

.phase1-part-selector input {
 width: auto;
 min-width: 14px;
 margin: 0;
}

.phase1-part-sequence {
 max-width: none;
}

.phase1-part-list {
 min-width: 0;
 display: grid;
 border: 1px solid var(--line);
 border-radius: 4px;
 overflow: hidden;
 background: #fff;
}

.phase1-part-item + .phase1-part-item {
 border-top: 1px solid var(--line);
}

.phase1-part-item > summary {
 min-width: 0;
 min-height: 48px;
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 align-items: center;
 gap: 12px;
 padding: 8px 12px;
 background: #f8f9fa;
 cursor: pointer;
}

.phase1-part-item > summary::marker {
 color: var(--muted);
}

.phase1-part-item > summary > span {
 min-width: 0;
 display: flex;
 align-items: baseline;
 gap: 8px;
}

.phase1-part-item > summary small {
 overflow: hidden;
 color: var(--muted);
 font-size: 10px;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.phase1-part-item > summary > em {
 border-radius: 3px;
 padding: 3px 7px;
 background: #fff1df;
 color: #986019;
 font-size: 10px;
 font-style: normal;
}

.phase1-part-item > summary > em.ready {
 background: #e8f5ec;
 color: #2d7144;
}

.phase1-part-item[open] > summary {
 border-bottom: 1px solid var(--line);
 background: #fff;
}

.phase1-part-fields {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 10px 12px;
 padding: 12px;
}

.phase1-part-fields .phase1-part-label,
.phase1-part-fields .phase1-part-wide {
