 />}
 {stage !== "corpus" && <details className="authoring-advanced-refinement" open={advancedRefinementOpen} onToggle={(event) => setAdvancedRefinementOpen(event.currentTarget.open)}>
 <summary><span><strong>高级微调</strong><small>仅在需要逐字段改写、补充精确规则或处理“其他”设计时展开</small></span><em>{groups.find((item) => item.key === group)?.label || "选择字段组"}</em></summary>
 <div className="authoring-group-tabs" role="tablist">{groups.map((item) => <button key={item.key} type="button" role="tab" aria-selected={group === item.key} className={group === item.key ? "active" : ""} onClick={() => setGroup(item.key)} disabled={interactionLocked}>{item.label}</button>)}</div>
 <div className="authoring-advanced-refinement-body">
 {stage === "framing" && <FramingFields projectId={projectId} framing={framing} group={group} update={updateFraming} factConversation={factConversation} setFactConversation={setFactConversation} onSubmitFactIntake={submitFactIntakeTurn} onApplyFactProposal={applyFactIntakeProposal} onAttachIb={attachInvestigatorBrochure} onMarkIbUnavailable={persistIbPacket} onAnalyzeIb={analyzeInvestigatorBrochure} busy={busy} interactionLocked={interactionLocked} />}
 {stage === "picos" && <PicosFields projectId={projectId} framing={framing} picos={picos} group={group} updateFraming={updateFraming} update={updatePicos} updateApplicability={updatePicosApplicability} interventionPanel={interventionPanel} setInterventionPanel={setInterventionPanel} hasPrefillRecommendations={Boolean(journey.prefill_package)} existingDocument={existingDocument} readOnly={readOnly} appendixReady={Boolean(journey.picos_complete && !picosDirty && !picosPendingDraft)} onSaveDesignDraft={saveCurrentDrafts} framingDirty={framingDirty} busy={busy} />}
 </div>
 </details>}
 {stage === "corpus" && <CorpusGate projectId={projectId} journey={journey} setJourney={setJourney} selectedBriefIds={selectedCorpusBriefIds} setSelectedBriefIds={setSelectedCorpusBriefIds} searchMessage={searchMessage} busy={busy} onSearch={() => runPublicSearch(journey)} acknowledged={acknowledged} setAcknowledged={setAcknowledged} overrideReason={overrideReason} setOverrideReason={setOverrideReason} allAcknowledged={allAcknowledged} onOverride={overrideCorpusGate} onCreateDocument={createDocument} onReviewAssemblyPlan={() => { setStage("picos"); setGroup("intervention"); }} readOnly={readOnly} existingDocument={existingDocument} />}
 </fieldset></main>
 {impact && <section className="authoring-impact-panel" aria-live="polite"><div><ShieldAlert size={18} /><span><strong>该变更会使下游内容失效</strong><small>确认后系统保留旧版本，并把以下对象标记为需要重新核验。</small></span></div><ul>{impact.preview.affected_dependents.map((item) => <li key={item}>{DEPENDENT_LABELS[item] || item}</li>)}</ul><div className="authoring-impact-actions"><button type="button" onClick={() => setImpact(null)}>返回修改</button><button className="primary-button" type="button" onClick={confirmImpact} disabled={busy === "confirm-impact"}>确认变更并重新核验</button></div></section>}
 {(message || hasUncommittedChanges) && <p className={`authoring-journey-message ${message.includes("失败") ? "danger" : ""}`} role="status"><span>{message || (hasUnsavedChanges ? "当前有尚未保存的修改。" : "草稿已保存，尚未提交当前阶段。")}</span>{researchRecovery?.projectId === projectId && <button type="button" onClick={retryAutomaticResearch} disabled={Boolean(busy)}><RefreshCw size={13} /> 重试</button>}</p>}
 {stage !== "corpus" && !impact && !readOnly && <footer className="authoring-journey-footer"><span>{authoringWriteBlockedMessage || (unresolvedPhase1PartCount > 0 ? `还有 ${unresolvedPhase1PartCount} 个I期Part缺少研究人群或队列/剂量方案；可先保存草稿，但投影与阶段完成继续阻断。` : stage === "framing" ? "研究药物、适应症和研究分期足以启动竞品检索；产品技术类型或给药途径未知时可先保留待确认，由IB/语料证据提出建议。" : framingPendingDraft ? "研究设计已写入第一步草稿；请返回第一步完成变更后再提交PICOS。" : "先采用或微调调研建议；精确剂量、阈值和终点仍需项目证据支持。")}</span><div>{stage === "picos" && <button type="button" onClick={() => { setStage("framing"); setGroup(isPhaseOneStudy(framing.study_phase) ? "design" : "identity"); setPrefillSection("identity"); setAdvancedRefinementOpen(true); }} disabled={authoringWriteBlocked}><ArrowLeft size={14} /> 返回第一步</button>}<button type="button" onClick={saveCurrentDrafts} disabled={authoringWriteBlocked || Boolean(busy) || (journey && !(stage === "framing" ? framingDirty : framingDirty || picosDirty))} title={authoringWriteBlocked ? authoringWriteBlockedMessage : busy ? "正在处理中，请稍候" : (journey && !(stage === "framing" ? framingDirty : framingDirty || picosDirty)) ? "当前没有需要保存的修改" : "保存当前草稿"}><Save size={14} /> {String(busy).startsWith("draft-") ? "保存中" : "保存草稿"}</button><button className="primary-button" type="button" onClick={() => saveStage(stage)} disabled={authoringWriteBlocked || Boolean(busy) || (stage === "framing" ? !framingReady : !picosReady || framingDirty || framingPendingDraft || !typedPhase1PartsReady)} title={authoringWriteBlockedMessage ? authoringWriteBlockedMessage : busy ? "正在处理中，请稍候" : stage === "framing" ? (!framingReady ? "请先补齐第一步必填项；未知产品技术类型不会阻断此步骤" : "提交并完成第一步") : framingDirty || framingPendingDraft ? "请先保存并完成第一步变更后再提交PICOS" : !typedPhase1PartsReady ? "请先补齐I期Part必填项" : !picosReady ? "请先补齐第二步必填项后再完成" : "提交并完成第二步"}>{busy === `save-${stage}` ? "提交中" : stage === "framing" ? "完成第一步" : "完成第二步"}<ArrowRight size={14} /></button></div></footer>}
 <AuthoringCompetitorDrawer
 open={competitorDrawerOpen}
 onClose={closeCompetitorDrawer}
 projectId={projectId}
 snapshotId={competitorSnapshotId}
 lockedIndication={journey.search_plan?.registry_filter?.condition_term || journey.framing?.clinicaltrials_condition_term || journey.framing?.indication || ""}
 lockedPhase={journey.framing?.study_phase || ""}
 journey={journey}
 onJourneyChange={setJourney}
 onTriagePipelineChange={handleTriagePipelineChange}
 selectedBriefIds={selectedCorpusBriefIds}
 onSelectedBriefIdsChange={setSelectedCorpusBriefIds}
 requestedView={referencePanelRequest?.view || ""}
 requestedArtifactId={referencePanelRequest?.artifactId || ""}
 focusRequestKey={referencePanelRequest?.requestKey || ""}
 keepPanelMounted
 onExecuteSearch={() => runPublicSearch(journey)}
 searchBusy={busy === "search"}
 />

 </div>
 );
}

function ResearchPipelineBanner({
 status,
 busy,
 onCancel,
 onContinueAfterTriage,
 onOpenFileIssues,
 onOpenCorpusAdmission,
 onResume,
 onRetryTriage,
 onStartRound2,
}) {
 const pipeline = status?.pipeline;
 if (!pipeline || !pipeline.stage) return null;
 const stage = pipeline.stage;
 const triageProgress = status?.triage_progress || {};
 const percent = Number.isFinite(Number(pipeline.percent))
 ? Number(pipeline.percent)
 : stage === "triaging" && Number.isFinite(triageProgress.percent)
 ? triageProgress.percent
 : 0;
 const childCompleted = Number.isFinite(Number(pipeline.child_completed))
 ? Number(pipeline.child_completed)
 : stage === "triaging" ? Number(triageProgress.completed_chunks || 0) : 0;
 const childTotal = Number.isFinite(Number(pipeline.child_total))
 ? Number(pipeline.child_total)
 : stage === "triaging" ? Number(triageProgress.total_chunks || 0) : 0;
 const childPercent = Number.isFinite(Number(pipeline.child_percent))
 ? Number(pipeline.child_percent)
 : stage === "triaging" ? Number(triageProgress.percent || 0) : 0;
 const childSubstepPercent = Number.isFinite(
 Number(pipeline.child_context?.current_substep_percent),
 )
 ? Math.max(0, Math.min(100, Number(pipeline.child_context.current_substep_percent)))
 : null;
 const childLabel = pipeline.child_label
 || (stage === "triaging" ? triageProgress.label : "")
 || "";
 const stageLabel = PIPELINE_STAGE_LABELS[stage] || stage;
 const isFailed = stage === "failed";
 const isCancelled = stage === "cancelled";
 const isCorpusReady = stage === "corpus_ready";
 const isRound2Ready = stage === "round2_ready";
 const isTerminal = PIPELINE_TERMINAL_STAGES.has(stage);
 const isWaitingForUser = PIPELINE_STABLE_WAITING_STAGES.has(stage);
 const isSourceIssueWaiting = isWaitingForUser
 && stage !== "awaiting_corpus_admission"
 && stage !== "awaiting_triage_confirm"
 && stage !== "awaiting_preparation_admission";
 const isPreparationStageWaiting = stage === "awaiting_preparation_admission";
 const emptyBasketFallback = stage === "awaiting_corpus_admission"
 && [
 "no_retainable_candidates_after_confirm",
 "no_retainable_candidates",
 "no_public_protocol_results",
 ].includes(
 String(pipeline.error_summary || ""),
 );
 const downstreamRetryable = isFailed && Boolean(status?.pipeline_retryable);
 const failedTaskMessage = String(pipeline.error_summary || "").includes(
 "CorpusAnalysisAiError",
 )
 ? "独立AI返回的语料分析结构未符合系统合同；已完成的原文、OCR和翻译仍保留，可直接重试后续语料分析。"
 : String(pipeline.error_summary || "").includes(
 "AI provider response is not valid JSON",
 )
 ? "独立AI接口未返回可解析的结构化结果；已完成的原文、OCR和翻译仍保留，可直接重试后续语料分析。"
 : "研究流水线未完成；可按页面提示重试。";
 const taskMessage = isFailed
 ? failedTaskMessage
 : isCancelled
 ? "研究流水线已取消，已保留已完成步骤。"
 : isCorpusReady
 ? "研究语料已准备完毕，可进入研究设计推荐。"
 : isRound2Ready
 ? "第二轮竞品分析已完成。"
 : isWaitingForUser
 ? (stage === "awaiting_triage_confirm"
 ? "竞品分诊已完成，等待确认后继续。"
 : stage === "awaiting_preparation_admission"
 ? "本阶段公开Protocol已完成；下一批原文需明确准入后继续，已完成项不会重复下载或OCR。"
 : stage === "awaiting_corpus_admission"
 ? emptyBasketFallback
 ? "公开检索没有可保留Protocol；可使用已审核共享语料或手动上传，并在语料准入处记录项目特异理由后继续。"
 : "第一轮竞品语料分析已完成；可继续研究设计，完整医学准入与PICOS对齐将在后续补齐。"
 : stage === "awaiting_corpus_analysis"
 ? "独立AI未返回可解析的最终语料分析JSON；已完成的下载、OCR和翻译仍保留，可直接重试后续语料分析。"
 : stage === "awaiting_translation_scope"
 ? "翻译范围仍需处理；已完成的原文和解析结果仍保留，可继续翻译与分析。"
 : "当前步骤需要处理后才能继续。")
 : childLabel || stageLabel;
 const blockers = Array.isArray(pipeline.document_admission_blockers)
 ? pipeline.document_admission_blockers
 : [];
 const exclusions = Array.isArray(pipeline.document_admission_exclusions)
 ? pipeline.document_admission_exclusions
 : [];
 const triageRetryable = Boolean(status?.triage_retryable);
 const unlocked = Boolean(status?.design_recommendations_unlocked);
 const busyReason = busy
 ? (busy === "pipeline-cancel"
 ? "正在取消研究流水线，请稍候"
 : busy === "pipeline-continue"
 ? "正在确认分诊并继续，请稍候"
 : busy === "pipeline-resume"
 ? "正在复核已处理文件并继续，请稍候"
 : busy === "pipeline-retry-triage"
 ? "正在继续未完成的竞品分诊，请稍候"
 : "当前有其他操作进行中，请稍候")
 : "";
 const cancelDisabled = Boolean(busy) || isTerminal;
 const continueDisabled = Boolean(busy);
 return (
 <section
 className={`research-pipeline-banner ${isFailed ? "danger" : isTerminal ? "success" : isWaitingForUser ? "waiting" : "active"}`}
 role="status"
 data-testid="research-pipeline-banner"
 >
 <div className="research-pipeline-banner-head">
 <span className="research-pipeline-banner-stage">
 {!isTerminal && !isWaitingForUser && <RefreshCw size={13} className="research-pipeline-banner-spin" />}
 {isWaitingForUser && <ShieldAlert size={13} />}
 研究流水线 · {stageLabel}
 </span>
 <span className="research-pipeline-banner-percent">
 {percent}%
 </span>
 </div>
 <div
 className="research-pipeline-banner-track"
 role="progressbar"
 aria-label="研究流水线进度"
 aria-valuemin="0"
 aria-valuemax="100"
 aria-valuenow={percent}
 ><div style={{ width: `${Math.max(0, Math.min(100, percent))}%` }} /></div>
 {childLabel && (
 <p className="research-pipeline-banner-substep" data-testid="research-pipeline-current-substep">
 <strong>{childLabel}</strong>
 {childTotal > 0 && (
 <small>
 {childCompleted}/{childTotal} · {childPercent}%
 {childSubstepPercent !== null && ` · 子步骤 ${childSubstepPercent}%`}
 </small>
 )}
 </p>
 )}
 {isCorpusReady && (
 <p className="research-pipeline-banner-ready" role="status">
 <strong>语料已准备完毕，可进入研究设计推荐</strong>
 </p>
 )}
 {isRound2Ready && (
 <p className="research-pipeline-banner-ready" role="status">
 <strong>第二轮竞品分析已完成，可对照已确认设计复核差异</strong>
 </p>
 )}
 {emptyBasketFallback && (
 <p className="research-pipeline-banner-fallback" role="alert">
 <strong>未发现可下载的公开方案</strong>
 <span>系统没有启动下载、OCR或翻译；请打开语料准入查看可用来源和缺口。当前没有候选研究时，不会伪造上传或公开来源。</span>
 </p>
 )}
 <p>
 {taskMessage}
 {!unlocked && !isFailed && !isCancelled && !isCorpusReady ? " 语料就绪前不会开放证据化设计推荐。" : ""}
 {unlocked && !isCorpusReady ? " 证据化设计推荐已开放。" : ""}
 </p>
 {isWaitingForUser && blockers.length > 0 && (
 <div className="research-pipeline-blockers" role="alert">
 {blockers.map((blocker) => (
 <article key={blocker.artifact_id || blocker.filename}>
 <header>
 <strong>{blocker.filename || blocker.nct_id || "待处理文档"}</strong>
 <span>{[blocker.nct_id, blocker.document_type].filter(Boolean).join(" · ")}</span>
 </header>
 {(blocker.checks || []).map((check) => (
 <div key={check.check_code || check.label}>
 <b>{check.label || "内容核验"}</b>
 <span>{check.observed_value || "原文中未识别到可核对信息"}</span>
 {check.expected_value && <small>当前项目预期：{check.expected_value}</small>}
 </div>
 ))}
 {!(blocker.checks || []).length && <p>{blocker.detail || blocker.required_action}</p>}
 </article>
 ))}
 </div>
 )}
 {exclusions.length > 0 && (
 <details className="research-pipeline-exclusions">
 <summary>
 已自动排除 {exclusions.length} 份不适合作为本轮章节语料的原文，不影响其余资料继续
 </summary>
 <ul>
 {exclusions.map((item) => (
 <li key={item.artifact_id || item.filename}>
 <strong>{item.nct_id || item.filename || "例外文件"}</strong>
 <span>{item.detail || item.reason_code || "未通过本轮语料准入"}</span>
 {Array.isArray(item.checks) && item.checks.length > 0 && (
 <dl>
 {item.checks.map((check) => (
 <div key={check.check_code || check.label}>
 <dt>{check.label || "内容核验"}</dt>
 <dd>
 <span>识别：{check.observed_value || "未识别到可核对信息"}</span>
 {check.expected_value && <small>预期：{check.expected_value}</small>}
 </dd>
 </div>
 ))}
 </dl>
 )}
 </li>
 ))}
 </ul>
 </details>
 )}
 <div className="research-pipeline-banner-actions">
 {emptyBasketFallback && onOpenCorpusAdmission && (
 <button
 type="button"
 className="primary-button"
 onClick={onOpenCorpusAdmission}
 disabled={Boolean(busy)}
 title={busy ? busyReason : "打开语料准入，查看共享语料、项目资料和例外放行条件"}
 >
 <FileText size={13} /> 查看语料准入
 </button>
 )}
 {downstreamRetryable && (
 <button
 type="button"
 className="primary-button"
 onClick={onResume}
 disabled={Boolean(busy)}
 title={busy ? busyReason : "复用既有原文、解析和OCR结果，仅重试翻译与后续语料分析"}
 >
 <RefreshCw size={13} /> {busy === "pipeline-resume" ? "重试中" : "从已完成原文继续"}
 </button>
 )}
 {isFailed && triageRetryable && (
 <button
 type="button"
 className="primary-button"
 onClick={onRetryTriage}
 disabled={Boolean(busy)}
 title={busy ? busyReason : "保留已完成分块，仅继续处理未完成的竞品分诊"}
 >
 <RefreshCw size={13} /> {busy === "pipeline-retry-triage" ? "继续中" : "继续未完成分诊"}
 </button>
 )}
 {isCorpusReady && (
 <button
 type="button"
 className="primary-button"
 onClick={onStartRound2}
 disabled={Boolean(busy)}
 title={busy ? busyReason : "以当前已确认研究设计启动第二轮精细化竞品分析"}
 >
 <RefreshCw size={13} /> {busy === "pipeline-round2" ? "分析中" : "启动第二轮精细化分析"}
 </button>
 )}
 {stage === "awaiting_triage_confirm" && (
 <button
 type="button"
 className="primary-button"
 onClick={onContinueAfterTriage}
 disabled={continueDisabled}
 title={continueDisabled ? busyReason : "确认分诊结果后继续研究流水线"}
 >
 <CheckCircle2 size={13} /> {busy === "pipeline-continue" ? "处理中" : "确认分诊后继续"}
 </button>
 )}
 {isSourceIssueWaiting && (
 <>
 <button
 type="button"
 onClick={onOpenFileIssues}
 disabled={Boolean(busy)}
 title={busy ? busyReason : "打开现有竞品方案处理面板，核对文件内容、结构与翻译范围"}
 >
 <FileText size={13} /> 处理文件问题
 </button>
 <button
 type="button"
 className="primary-button"
 onClick={onResume}
 disabled={continueDisabled}
 title={continueDisabled ? busyReason : "仅复核既有原文准备批次，并从当前等待节点继续"}
 >
 <CheckCircle2 size={13} /> {busy === "pipeline-resume" ? "复核中" : "已处理，继续流水线"}
 </button>
 </>
 )}
 {isPreparationStageWaiting && (
 <button
 type="button"
 className="primary-button"
 onClick={onResume}
 disabled={continueDisabled}
 title={continueDisabled ? busyReason : "准入并处理下一批延后公开Protocol；已完成项不会重跑"}
 >
 <CheckCircle2 size={13} /> {busy === "pipeline-resume" ? "准入中" : "准入下一批原文"}
 </button>
 )}
 {!isTerminal && (
 <button
 type="button"
 onClick={onCancel}
 disabled={cancelDisabled}
 title={cancelDisabled ? (isTerminal ? "流水线已结束，无需取消" : busyReason) : "取消当前研究流水线（已完成步骤会保留审计）"}
 >
 <XCircle size={13} /> {busy === "pipeline-cancel" ? "取消中" : "取消研究流水线"}
 </button>
 )}
 {isCancelled && (
 <span className="research-pipeline-banner-clear-stage" title="流水线已取消，阶段已清空为终态">
 阶段已清除：已取消研究流水线
 </span>
 )}
 </div>
 </section>
 );
}

function EntryModeChooser({ busy, onSelect }) {
 return <section className="authoring-entry-mode"><header><div><strong>选择开始方式</strong><span>两种方式最终汇入同一研究定义、两阶段医学确认和完整方案编辑器。</span></div></header><div className="authoring-entry-mode-options"><button type="button" onClick={() => onSelect("synopsis_import")} disabled={Boolean(busy)}><FileText size={19} /><span><strong>导入已有方案/方案摘要</strong><small>上传PDF或DOCX，核对提取的研究框架、PICOS和量表候选后继续补全。</small></span><ArrowRight size={16} /></button><button type="button" onClick={() => onSelect("guided_greenfield")} disabled={Boolean(busy)}><PenLine size={19} /><span><strong>从零开始</strong><small>通过两阶段反问确定方案摘要和研究框架，再进入完整方案撰写。</small></span><ArrowRight size={16} /></button></div>{busy && <p><RefreshCw size={14} /> 正在建立写作任务...</p>}</section>;
}

function InstrumentCandidateEvidence({ item, evidenceSpans }) {
 const evidenceById = new Map((evidenceSpans || []).map((evidence) => [evidence.span_id, evidence]));
 const evidence = (item.evidence_span_ids || []).map((spanId) => evidenceById.get(spanId)).filter(Boolean);
 const renderEvidence = (entry) => <div key={entry.span_id}><span>原文</span><blockquote>{entry.source_text}</blockquote><small title={entry.locator}>{entry.locator}</small></div>;
 if (!evidence.length) return <div className="synopsis-instrument-evidence missing"><span>原文</span><p>未找到该候选的直接原文，暂不可确认。</p></div>;
 return <div className="synopsis-instrument-evidence">{renderEvidence(evidence[0])}{evidence.length > 1 && <details><summary>查看其余 {evidence.length - 1} 条直接原文</summary>{evidence.slice(1).map(renderEvidence)}</details>}</div>;
}

function SynopsisImportPanel({ journey, file, uploadKey, replacementPending, framing, picos, synopsisText, acknowledged, overrideReason, busy, interactionLocked, onFile, onUpload, onFraming, onPicos, onSynopsisText, onAcknowledged, onOverrideReason }) {
 const imported = journey.synopsis_import || {};
 const source = imported.source;
 const validationWarnings = source?.validation_warnings || [];
 const toggleWarning = (warning) => onAcknowledged(acknowledged.includes(warning) ? acknowledged.filter((item) => item !== warning) : [...acknowledged, warning]);
 return <section className="synopsis-import-stage"><header><div><strong>导入已有方案/方案摘要</strong><span>先校验文件基本信息、内容角色和项目适应症，再审核AI提取候选。</span></div><span className={`synopsis-import-status ${source && !replacementPending ? "review" : "pending"}`}>{replacementPending ? (source ? "替换待解析" : "文件待解析") : source ? "AI建议·待确认" : "待导入"}</span></header><fieldset className="authoring-journey-fieldset" disabled={interactionLocked}><div className="synopsis-upload-bar"><label className="synopsis-file-picker"><input type="file" accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" onChange={(event) => onFile(event.target.files?.[0] || null)} /><Upload size={16} /><span><strong>{file?.name || (source ? "选择新的PDF或DOCX以替换当前文件" : "选择PDF或DOCX方案/方案摘要")}</strong><small>{file ? `${formatFileSize(file.size)} · 重试将沿用同一导入请求` : "文件需可正常读取；内容校验结果由医学经理确认。"}</small></span></label><button type="button" onClick={onUpload} disabled={!file || !uploadKey || Boolean(busy)}><Upload size={14} /> {busy === "synopsis-upload" ? "解析中" : source ? "替换并重新解析" : "导入并解析"}</button></div>{source && <><section className="synopsis-source-review"><header><strong>文件与内容校验</strong><small>原始判断会持续保留；确认沿用不会把“需确认/不一致”改写为“一致”。</small></header><dl><div><dt>文件</dt><dd title={source.original_filename}>{source.original_filename}</dd></div><div><dt>格式 / 大小</dt><dd>{source.media_type === "application/pdf" ? "PDF" : "DOCX"} · {formatFileSize(source.actual_size)}</dd></div><div><dt>文件角色</dt><dd><span className={`synopsis-validation ${source.source_role_status}`}>{validationStatus(source.source_role_status)}</span> 临床试验方案/方案摘要</dd></div><div><dt>适应症</dt><dd><span className={`synopsis-validation ${source.indication_status}`}>{validationStatus(source.indication_status)}</span> 当前项目</dd></div><div><dt>解析器</dt><dd>{source.parser_name}</dd></div><div><dt>提取版本</dt><dd title={source.extraction_revision}>{source.extraction_revision}</dd></div></dl></section><div className="synopsis-findings-grid"><section><header><strong>待补充字段</strong><span>{imported.missing_fields?.length || 0}项</span></header>{imported.missing_fields?.length ? <ul>{imported.missing_fields.map((item) => <li key={item} title={item}>{synopsisFieldLabel(item)}</li>)}</ul> : <p>未发现结构性缺失。</p>}</section><section><header><strong>提取冲突</strong><span>{imported.conflict_notes?.length || 0}项</span></header>{imported.conflict_notes?.length ? <ul>{imported.conflict_notes.map((item) => <li key={item}>{item}</li>)}</ul> : <p>未发现相互冲突的表述。</p>}</section></div>{picos.assessment_instruments?.length > 0 && <section className="synopsis-instrument-candidates"><header><div><strong>量表与评估工具候选</strong><span>仅为原文提取候选；进入PICOS后仍需逐项核对用途、访视、中文版本与使用许可。</span></div><small>{picos.assessment_instruments.length}项待确认</small></header><div>{picos.assessment_instruments.map((item) => <article key={item.instrument_id}><span>{item.acronym || "工具"}</span><div className="synopsis-instrument-summary"><strong>{item.canonical_name_zh}</strong><small>{[item.study_purpose, item.visit_labels?.join("、")].filter(Boolean).join(" · ") || "用途与访视待补充"}</small></div><em>候选·待确认</em><InstrumentCandidateEvidence item={item} evidenceSpans={imported.evidence_spans} /></article>)}</div></section>}{validationWarnings.length > 0 && <section className="synopsis-validation-review"><header><div><ShieldAlert size={17} /><span><strong>逐项确认内容提示</strong><small>以下提示必须逐项确认，并记录不少于10个字符的沿用理由。</small></span></div><span>{acknowledged.length}/{validationWarnings.length}</span></header><div>{validationWarnings.map((warning, index) => <label key={`${index}-${warning}`}><input type="checkbox" checked={acknowledged.includes(warning)} onChange={() => toggleWarning(warning)} /><span><strong>{warning}</strong><small>{acknowledged.includes(warning) ? "医学经理已确认沿用" : "尚未确认"}</small></span></label>)}</div><label className="synopsis-override-reason"><span>确认沿用理由</span><textarea rows={2} value={overrideReason} onChange={(event) => onOverrideReason(event.target.value)} placeholder="说明为何该文件仍属于当前项目并可继续使用；不少于10个字符。" /></label></section>}<section className="synopsis-extraction-review"><header><div><strong>提取结果摘要</strong><span>可直接修订候选；确认后会写入统一研究定义草稿，并继续两阶段补全。</span></div><small>AI提取 · 待用户确认</small></header><div className="authoring-field-grid four"><Field label="方案号"><input value={framing.protocol_id || ""} onChange={(event) => onFraming("protocol_id", event.target.value)} /></Field><Field label="版本"><input value={framing.version || ""} onChange={(event) => onFraming("version", event.target.value)} /></Field><Field label="研究分期"><StudyPhaseInput value={framing.study_phase} onChange={(value) => onFraming("study_phase", value)} listId="medical-writing-synopsis-phase-options" /></Field><Field label="适应症"><input value={framing.indication || ""} onChange={(event) => onFraming("indication", event.target.value)} /></Field><Field className="span-2" label="方案标题"><input value={framing.document_title || ""} onChange={(event) => onFraming("document_title", event.target.value)} /></Field><Field label="试验药物"><input value={framing.investigational_product || ""} onChange={(event) => onFraming("investigational_product", event.target.value)} /></Field><Field label="靶点/作用机制"><input value={framing.target_mechanism || ""} onChange={(event) => onFraming("target_mechanism", event.target.value)} /></Field><Field className="span-2" label="总体设计意图"><textarea rows={3} value={framing.design_pattern || ""} onChange={(event) => onFraming("design_pattern", event.target.value)} /></Field><Field className="span-2" label="目标研究人群"><textarea rows={3} value={framing.population_intent || picos.population_summary || ""} onChange={(event) => { onFraming("population_intent", event.target.value); onPicos("population_summary", event.target.value); }} /></Field><Field className="span-2" label="干预措施"><textarea rows={3} value={picos.intervention_summary || ""} onChange={(event) => onPicos("intervention_summary", event.target.value)} /></Field><Field className="span-2" label="对照"><textarea rows={3} value={picos.comparator_summary || ""} onChange={(event) => onPicos("comparator_summary", event.target.value)} /></Field><Field className="span-4" label="主要终点及评价时间"><textarea rows={3} value={picos.primary_endpoint || ""} onChange={(event) => onPicos("primary_endpoint", event.target.value)} /></Field><Field className="span-4" label="研究摘要文本"><textarea rows={8} value={synopsisText} onChange={(event) => onSynopsisText(event.target.value)} /></Field></div></section></>}</fieldset></section>;
}

function PrefillRecommendations({
 journey,
 prefillPackage,
 searchPlan,
 busy,
 readOnly,
 activeSection,
 onSectionChange,
 onAdopt,
 onAdoptComposite,
 onDefer,
 onRefine,
 onRegenerate,
 deferredFields,
 compositeReceipt,
 onOpenCompetitorDrawer,
}) {
 const searchCount = searchPlan?.returned_count || 0;
 const documentCount = searchPlan?.public_document_count || 0;
 if (!prefillPackage) {
 return <section className="authoring-prefill-panel preparing" aria-live="polite">
 <header><div><Sparkles size={16} /><span><strong>{busy === "prefill-generate" ? "正在准备研究设计建议" : "研究设计建议尚未准备完成"}</strong><small>系统只使用已确认的试验药物、适应症和分期启动准备，不会要求重复填写。</small></span></div>{busy === "prefill-generate" ? <RefreshCw className="spin" size={16} /> : !readOnly && <button type="button" onClick={onRegenerate} disabled={Boolean(busy)}><RefreshCw size={14} /> 重新准备</button>}</header>
 <div className="authoring-prefill-preparation" aria-label="建议准备进程">
 <span className="done"><CheckCircle2 size={13} /> 项目最小信息已确认</span>
 <span className={busy === "prefill-generate" ? "running" : "pending"}><RefreshCw size={13} /> 汇总公开研究与项目资料</span>
 <span className="pending"><Sparkles size={13} /> 生成研究框架与PICOS建议</span>
 </div>
 </section>;
 }
 const compositeGroups = collectCompositePrefillGroups(prefillPackage);
 const groups = prefillFieldsForSection(prefillPackage, activeSection);
 const statusLabel = ({ ready: "建议已就绪", partial: "部分建议已就绪", stale: "建议需更新", failed: "建议生成失败" })[prefillPackage.status] || "建议准备中";
 const pathLabels = {
 ...SYNOPSIS_FIELD_LABELS,
 ...FACT_FIELD_LABELS,
 ...DESIGN_PREFILL_FIELD_LABELS,
 };
 return <section className={`authoring-prefill-panel ${prefillPackage.status}`} aria-label="研究设计推荐包">
 <header>
 <div><Sparkles size={16} /><span><strong>{statusLabel}</strong><small>{searchCount || documentCount ? `已结合 ${searchCount} 项公开研究${documentCount ? `及 ${documentCount} 份Protocol` : ""}` : "AI正在结合项目事实与公开研究形成整套建议"}</small></span></div>
 {!readOnly && <div className="authoring-prefill-header-actions">
 {searchPlan?.latest_snapshot_id && typeof onOpenCompetitorDrawer === "function" && (
 <button type="button" data-action="open-competitor-drawer-from-prefill" onClick={onOpenCompetitorDrawer} disabled={Boolean(busy)} title="打开竞品处理抽屉">
 <Search size={14} /> 打开竞品处理
 </button>
 )}
 <button type="button" onClick={onRegenerate} disabled={Boolean(busy)} title="按最新项目事实和调研结果重新生成建议"><RefreshCw size={14} /> 更新建议</button>
 </div>}
 </header>
 <AuthoringCandidatePackagePanel
 groups={compositeGroups}
 packageRevision={prefillPackage.package_revision}
 pathLabels={pathLabels}
 busy={busy}
 readOnly={readOnly}
 receipt={compositeReceipt}
 onAdoptComposite={onAdoptComposite}
 />
 <details className="authoring-prefill-field-details">
 <summary>
 <span><strong>展开单字段修改与依据</strong><small>仅在整包建议需要局部调整时使用</small></span>
 </summary>
 <div className="authoring-prefill-workspace">
 <div className="authoring-prefill-main">
 <nav className="authoring-prefill-section-tabs" aria-label="AI推荐分组">
 {PREFILL_OVERVIEW_SECTIONS.map((section) => {
 const sectionGroups = prefillFieldsForSection(prefillPackage, section.key);
 return <button key={section.key} type="button" className={activeSection === section.key ? "active" : ""} aria-pressed={activeSection === section.key} onClick={() => onSectionChange(section.key)}><span>{section.label}</span><small>{sectionGroups.length}项</small></button>;
 })}
 </nav>
 {activeSection === "design" && (
 <p className="authoring-prefill-design-helper" role="note">
 总体设计须给出明确采用/不采用（如不启用适应性设计、不设置SRC或DMC、不计划期中分析）；禁止以「待确认」作为推荐或默认选项。
 </p>
 )}
 {groups.length > 0 ? <div className="authoring-prefill-fields">{groups.map((candidateGroup) => <PrefillFieldCard key={candidateGroup.field_path} group={candidateGroup} projectConfirmedCandidate={confirmedProjectCandidate(journey, candidateGroup)} busy={busy} readOnly={readOnly} onAdopt={onAdopt} onDefer={onDefer} onRefine={onRefine} deferred={deferredFields.includes(candidateGroup.field_path)} />)}</div> : <div className="authoring-prefill-empty"><ShieldAlert size={15} /><span>该分组尚无证据充分的预填建议。系统不会为精确剂量、频率或终点虚构内容；完成Protocol解析后可更新。</span></div>}
 </div>
 <aside className="authoring-prefill-impact" aria-label="整包建议说明">
 <strong>修改原则</strong>
 <p>优先采用整包方案。仅在项目事实与推荐不一致时修改单字段；精确剂量、终点与AESI仍受现有证据门约束。</p>
 </aside>
 </div>
 {prefillPackage.partial_source_failures?.length > 0 && <details className="authoring-prefill-limitations"><summary>来源限制</summary><ul>{prefillPackage.partial_source_failures.map((item) => <li key={item}>{item}</li>)}</ul></details>}
 </details>
 </section>;
}

function PrefillFieldCard({ group, projectConfirmedCandidate, busy, readOnly, onAdopt, onDefer, onRefine, deferred }) {
 const recommended = recommendedPrefillCandidate(group);
 const confirmed = group.candidates.find((item) => item.state === "user_confirmed") || projectConfirmedCandidate;
 const [editingCandidateId, setEditingCandidateId] = useState("");
 const [editedValue, setEditedValue] = useState("");
 const candidates = [...group.candidates].sort((left, right) => {
 const leftPending = isPendingCompositeCandidate(left);
 const rightPending = isPendingCompositeCandidate(right);
 if (!leftPending && rightPending) return -1;
 if (leftPending && !rightPending) return 1;
 if (left.candidate_id === group.recommended_candidate_id) return -1;
 if (right.candidate_id === group.recommended_candidate_id) return 1;
 return 0;
 });
 const startEdit = (candidate) => {
 setEditingCandidateId(candidate.candidate_id);
 setEditedValue(typeof candidate.structured_value === "string" ? candidate.structured_value : candidate.preview || "");
 };
 const currentCandidate = confirmed || recommended;
 const currentDisplay = prefillCandidateDisplay(group.field_path, currentCandidate);
 const rawCurrentDisplay = currentCandidate?.preview || (typeof currentCandidate?.structured_value === "string" ? currentCandidate.structured_value : "");
 const evidenceCount = currentCandidate?.evidence_refs?.length || 0;
 const editingCandidate = candidates.find((candidate) => candidate.candidate_id === editingCandidateId);
 const editingCandidatePending = isPendingCompositeCandidate(editingCandidate);
 const needsExplicitDecision = DESIGN_EXPLICIT_DECISION_FIELDS.has(group.field_path);
 const refineDisabled = Boolean(busy);
 const bothCandidate = candidates.find((c) => {
 const v = c.structured_value || {};
 return v.src === true && v.dmc === true;
 }) || candidates.find((c) => String(c.preview || "").includes("同时设"));
 const noneCandidate = candidates.find((c) => {
 const v = c.structured_value || {};
 return v.src === false && v.dmc === false;
 }) || candidates.find((c) => String(c.preview || "").includes("不设"));
 return <article className={`authoring-prefill-field ${confirmed ? "confirmed" : ""} ${deferred ? "deferred" : ""}`} data-prefill-field={group.field_path}>
 <div className="authoring-prefill-field-head">
 <span><strong>{prefillFieldLabel(group.field_path)}</strong><small>{confirmed ? "已成为当前项目事实" : deferred ? "本次暂缓，不写入项目事实" : `AI推荐 · ${evidenceCount}条主要依据`}</small></span>
 <em>{confirmed ? "已采用" : deferred ? "暂未确定" : "AI建议"}</em>
 </div>
 {needsExplicitDecision && (
 <p className="authoring-prefill-explicit-helper">
 请选择明确采用或不采用选项（如不启用适应性设计 / 同时设置SRC与DMC / 不设置SRC或DMC / 不计划期中分析）；勿采用含「待确认」的表述。
 </p>
 )}
 {group.field_path === "design.src_dmc" && !readOnly && !confirmed && (
 <div className="authoring-prefill-src-dmc-bulk" role="group" aria-label="SRC/DMC快捷选择">
 <button
 type="button"
 className="primary-button"
 disabled={Boolean(busy) || Boolean(bothCandidate && isPendingCompositeCandidate(bothCandidate))}
 title={bothCandidate && isPendingCompositeCandidate(bothCandidate) ? prefillCandidateBlockedReason(bothCandidate) : "同时设置SRC与DMC"}
 onClick={() => { if (bothCandidate) onAdopt(group.field_path, bothCandidate); }}
 >
 SRC/DMC 全选
 </button>
 <button
 type="button"
 disabled={Boolean(busy) || Boolean(noneCandidate && isPendingCompositeCandidate(noneCandidate))}
 title={noneCandidate && isPendingCompositeCandidate(noneCandidate) ? prefillCandidateBlockedReason(noneCandidate) : "不设置SRC或DMC"}
 onClick={() => { if (noneCandidate) onAdopt(group.field_path, noneCandidate); }}
 >
 SRC/DMC 全不选
 </button>
 </div>
 )}
 <div className="authoring-prefill-current">
 <strong title={rawCurrentDisplay && rawCurrentDisplay !== currentDisplay ? rawCurrentDisplay : undefined}>{currentDisplay || (candidates.length ? "当前无推荐方案；请从下方候选中选择或使用组合推荐" : needsExplicitDecision ? "请从下方候选中明确选择" : "候选内容待生成")}</strong>
 {currentCandidate?.rationale && <p>{currentCandidate.rationale}</p>}
 </div>
 {!readOnly && <div className="authoring-prefill-primary-actions">
 {!confirmed && recommended && <button type="button" className="primary-button" data-prefill-action="adopt-recommended" onClick={() => onAdopt(group.field_path, recommended)} disabled={Boolean(busy) || isPendingCompositeCandidate(recommended)} title={isPendingCompositeCandidate(recommended) ? prefillCandidateBlockedReason(recommended) : "采用当前推荐方案"}>{busy === `prefill-adopt-${group.field_path}` ? "写入中" : "采用推荐"}</button>}
 {!confirmed && STRING_PREFILL_FIELDS.has(group.field_path) && recommended && <button type="button" onClick={() => startEdit(recommended)} disabled={Boolean(busy) || isPendingCompositeCandidate(recommended)} title={isPendingCompositeCandidate(recommended) ? prefillCandidateBlockedReason(recommended) : "修改后采用，写入您的表述"}>修改后采用</button>}
 {!confirmed && <button type="button" className={deferred ? "selected" : ""} onClick={() => onDefer(group.field_path)} disabled={Boolean(busy)} title="仅暂缓本次处理，不写入项目事实；下次读取仍会保留该建议">{deferred ? "继续处理" : "暂不确定"}</button>}
 <button type="button" onClick={() => onRefine(group.field_path)} disabled={refineDisabled} title={refineDisabled ? "正在处理中，请稍候" : "打开高级微调面板；已有内容会保留，空字段可从推荐预填"}>{STRING_PREFILL_FIELDS.has(group.field_path) ? "其他表述" : "其他/高级微调"}</button>
 </div>}
 {editingCandidateId === recommended?.candidate_id && <div className="authoring-prefill-edit"><textarea rows={3} value={editedValue} onChange={(event) => setEditedValue(event.target.value)} aria-label={`${prefillFieldLabel(group.field_path)}修改稿`} /><div><button type="button" onClick={() => setEditingCandidateId("")}>取消</button><button className="primary-button" type="button" onClick={() => onAdopt(group.field_path, recommended, editedValue.trim())} disabled={!editedValue.trim() || Boolean(busy) || editingCandidatePending} title={editingCandidatePending ? prefillCandidateBlockedReason(editingCandidate) : "采用修改后的候选"}>采用修改稿</button></div></div>}
 <details className="authoring-prefill-candidate-drawer" open={needsExplicitDecision && !confirmed}>
 <summary>查看{candidates.length}个候选、依据与局限</summary>
 <div className="authoring-prefill-candidates">
 {candidates.map((candidate) => {
 const isRecommended = candidate.candidate_id === recommended?.candidate_id;
 const isConfirmed = candidate.state === "user_confirmed" || candidate.candidate_id === confirmed?.candidate_id;
 const isBusy = busy === `prefill-adopt-${group.field_path}`;
 const display = prefillCandidateDisplay(group.field_path, candidate);
 const rawDisplay = candidate.preview || (typeof candidate.structured_value === "string" ? candidate.structured_value : "");
 const pendingCandidate = isPendingCompositeCandidate(candidate);
 return <section key={candidate.candidate_id} className={`${isRecommended ? "recommended" : ""} ${isConfirmed ? "selected" : ""} ${pendingCandidate ? "pending" : ""}`}>
 <div className="authoring-prefill-candidate-copy">
 <div><span>{isConfirmed ? <CheckCircle2 size={13} /> : isRecommended ? <Sparkles size={13} /> : null}{isConfirmed ? "已采用" : pendingCandidate ? "待决定（非推荐）" : isRecommended ? "推荐" : "备选"}</span><small>{({ high: "高", medium: "中", low: "低", none: "无" })[candidate.confidence] || "未知"}置信</small></div>
 <strong title={rawDisplay && rawDisplay !== display ? rawDisplay : undefined}>{display}</strong>
 {candidate.rationale && <p>{candidate.rationale}</p>}
 </div>
 {!readOnly && !isConfirmed && <div className="authoring-prefill-candidate-actions">
 <button type="button" className={isRecommended ? "primary-button" : ""} onClick={() => onAdopt(group.field_path, candidate)} disabled={Boolean(busy) || pendingCandidate} title={pendingCandidate ? prefillCandidateBlockedReason(candidate) : "采用该候选"}>{isBusy ? "写入中" : "采用"}</button>
 {STRING_PREFILL_FIELDS.has(group.field_path) && <button type="button" onClick={() => startEdit(candidate)} disabled={Boolean(busy) || pendingCandidate} title={pendingCandidate ? prefillCandidateBlockedReason(candidate) : "修改后采用，写入您的表述"}>修改后采用</button>}
 </div>}
 {editingCandidateId === candidate.candidate_id && <div className="authoring-prefill-edit"><textarea rows={3} value={editedValue} onChange={(event) => setEditedValue(event.target.value)} /><div><button type="button" onClick={() => setEditingCandidateId("")}>取消</button><button className="primary-button" type="button" onClick={() => onAdopt(group.field_path, candidate, editedValue.trim())} disabled={!editedValue.trim() || Boolean(busy) || editingCandidatePending} title={editingCandidatePending ? prefillCandidateBlockedReason(editingCandidate) : "采用修改后的候选"}>采用修改稿</button></div></div>}
 {(candidate.evidence_refs?.length > 0 || candidate.limitations?.length > 0) && <details className="authoring-prefill-evidence"><summary>依据与局限</summary>{candidate.evidence_refs?.map((evidence, index) => <div key={`${evidence.source_id}-${index}`}><strong>{evidence.source_text || evidence.source_id}</strong><small title={evidence.locator}>{evidence.source_kind} · {evidence.locator || evidence.source_id}</small></div>)}{candidate.limitations?.length > 0 && <ul>{candidate.limitations.map((item) => <li key={item}>{item}</li>)}</ul>}</details>}
 </section>;
 })}
 </div>
 </details>
 </article>;
}

function InvestigatorBrochureIntake({
 projectId,
 packet,
 busy,
 interactionLocked,
 onAttach,
 onMarkUnavailable,
 onAnalyze,
}) {
 const [file, setFile] = useState(null);
 const [registration, setRegistration] = useState(null);
 const [uploading, setUploading] = useState(false);
 const [acknowledged, setAcknowledged] = useState([]);
 const [overrideReason, setOverrideReason] = useState("");
 const [localMessage, setLocalMessage] = useState("");
 useEffect(() => {
 setFile(null);
 setRegistration(null);
 setAcknowledged([]);
 setOverrideReason("");
 setLocalMessage("");
 }, [projectId]);
 const currentSourceId = packet.ib_source_ids?.[0] || "";
 const upload = async () => {
 if (!file || uploading || interactionLocked) return;
 setUploading(true);
 setLocalMessage("正在解析研究者手册并核对文件角色与适应症...");
 try {
 const form = new FormData();
 form.append("file", file, file.name);
 const response = await fetch(
 `/api/projects/${projectId}/medical-writing/sources/investigator-brochure`,
 { method: "POST", body: form },
 ).then(readJson);
 const validation = response?.entry?.metadata?.content_validation || {};
 setRegistration(response);
 setAcknowledged([]);
 setOverrideReason("");
 if (!(validation.warnings || []).length) {
 await onAttach(response, "");
 setLocalMessage("文件角色与项目内容已核对，研究者手册已进入项目事实来源。");
 } else {
 setLocalMessage("文件已读取；请核对下方内容提示后决定是否沿用。");
 }
 } catch (error) {
 setLocalMessage(`研究者手册导入失败：${error.message}`);
 } finally {
 setUploading(false);
 }
 };
 const validation = registration?.entry?.metadata?.content_validation || {};
 const warnings = validation.warnings || [];
 const allAcknowledged = warnings.length > 0
 && warnings.every((item) => acknowledged.includes(item.code));
 const confirm = async () => {
 if (!allAcknowledged || overrideReason.trim().length < 10) return;
 await onAttach(registration, overrideReason);
 setLocalMessage("已按医学经理确认沿用该研究者手册；原提示仍保留在来源记录中。");
 };
 return <section className="authoring-ib-intake">
 <div className="authoring-ib-actions">
 <label className="authoring-ib-file-picker">
 <input type="file" accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" onChange={(event) => {
 setFile(event.target.files?.[0] || null);
 setRegistration(null);
 setAcknowledged([]);
 setOverrideReason("");
 setLocalMessage("");
 }} disabled={interactionLocked || uploading} />
 <Upload size={14} />
 <span>{file?.name || (currentSourceId ? "替换研究者手册" : "上传研究者手册")}</span>
 </label>
 {file && <button type="button" onClick={upload} disabled={interactionLocked || uploading}>{uploading ? <RefreshCw size={14} /> : <FileText size={14} />}{uploading ? "解析中" : "导入并解析"}</button>}
 {!currentSourceId && <button type="button" onClick={onMarkUnavailable} disabled={interactionLocked || uploading}>暂不提供IB</button>}
 {currentSourceId && <button type="button" className="primary-button" onClick={onAnalyze} disabled={interactionLocked || busy === "fact-turn"}><Sparkles size={14} /> {busy === "fact-turn" ? "提取中" : "提取关键事实"}</button>}
 </div>
 {warnings.length > 0 && currentSourceId !== registration?.entry?.entry_id && <div className="authoring-ib-validation">
 <header><ShieldAlert size={15} /><span><strong>内容提示</strong><small>仅核对是否误传文件或项目资料，不执行额外安全检查。</small></span></header>
 {warnings.map((warning) => <label key={warning.code}>
 <input type="checkbox" checked={acknowledged.includes(warning.code)} onChange={() => setAcknowledged((current) => current.includes(warning.code) ? current.filter((item) => item !== warning.code) : [...current, warning.code])} />
 <span><strong>{warning.label}</strong><small>{warning.message}</small></span>
 </label>)}
 <textarea rows={2} value={overrideReason} onChange={(event) => setOverrideReason(event.target.value)} placeholder="说明确认该文件可用于当前项目的理由，不少于10个字符" />
 <button type="button" className="primary-button" onClick={confirm} disabled={!allAcknowledged || overrideReason.trim().length < 10 || interactionLocked}><CheckCircle2 size={14} /> 确认沿用</button>
 </div>}
 {currentSourceId && <div className="authoring-ib-current"><CheckCircle2 size={14} /><span><strong>已接入项目事实来源</strong><small title={currentSourceId}>{currentSourceId}</small></span></div>}
 {localMessage && <p>{localMessage}</p>}
 </section>;
}

function FramingFields({ projectId, framing, group, update, factConversation, setFactConversation, onSubmitFactIntake, onApplyFactProposal, onAttachIb, onMarkIbUnavailable, onAnalyzeIb, busy, interactionLocked }) {
 if (group === "identity") {
 const factPacket = framing.minimum_product_fact_packet || {};
 const ibStatus = factPacket.ib_status || "not_provided";
 const ibTone = IB_STATUS_TONE[ibStatus] || "optional";
 const ibLabel = IB_STATUS_LABELS[ibStatus] || IB_STATUS_LABELS.not_provided;
 const packetStatusLabel = FACT_PACKET_STATUS_LABELS[factPacket.status] || FACT_PACKET_STATUS_LABELS.not_started;
 const highImpactGaps = factPacket.unresolved_high_impact_fields || [];
 const productProfile = framing.product_profile || {};
 const updateProductProfile = (patch) => update("product_profile", { ...productProfile, ...patch });
 const toggleAdministrationRoute = (route) => {
 const current = productProfile.administration_routes || [];
 updateProductProfile({
 administration_routes: current.includes(route)
 ? current.filter((item) => item !== route)
 : [...current, route],
 });
 };
 const updateDosageForm = (value) => updateProductProfile({ dosage_forms: value ? [value] : [] });
 return <section className="authoring-field-section"><header><strong>项目与产品</strong><span>研究药物、适应症和研究分期是启动竞品检索的最小三项；其他内容可由系统预填后再确认</span></header><div className="authoring-ib-banner"><div className={`authoring-ib-status ${ibTone}`}><FileText size={16} /><div><strong>可选：研究者手册（IB）</strong><span>{ibLabel}</span></div></div><div className="authoring-ib-fact-packet"><span>最小产品事实包</span><strong>{packetStatusLabel}</strong>{highImpactGaps.length > 0 && <small>高影响缺口 {highImpactGaps.length} 项：{highImpactGaps.slice(0, 3).map(factGapLabel).join("、")}{highImpactGaps.length > 3 ? " 等" : ""}</small>}</div></div><InvestigatorBrochureIntake projectId={projectId} packet={factPacket} busy={busy} interactionLocked={interactionLocked} onAttach={onAttachIb} onMarkUnavailable={() => onMarkIbUnavailable({ ibStatus: "not_available" })} onAnalyze={onAnalyzeIb} /><div className="authoring-field-grid four"><Field label="方案号"><input value={framing.protocol_id} onChange={(event) => update("protocol_id", event.target.value)} /></Field><Field label="版本"><input value={framing.version} onChange={(event) => update("version", event.target.value)} /></Field><Field label="研究分期" required><StudyPhaseInput value={framing.study_phase} onChange={(value) => update("study_phase", value)} listId="medical-writing-study-phase-options" /></Field><Field label="开发区域"><input value={lineText(framing.development_regions)} onChange={(event) => update("development_regions", lines(event.target.value))} /></Field><Field className="span-4" label="方案标题"><input value={framing.document_title} onChange={(event) => update("document_title", event.target.value)} /></Field><Field className="span-2" label="适应症" required><input value={framing.indication} onChange={(event) => update("indication", event.target.value)} /></Field><Field className="span-2" label="试验药物" required><input value={framing.investigational_product} onChange={(event) => update("investigational_product", event.target.value)} /></Field><Field className="span-2" label="药物技术类型" required><select value={productProfile.technology_type || "unknown"} onChange={(event) => updateProductProfile({ technology_type: event.target.value })} aria-label="药物技术类型" aria-required="true">{PRODUCT_TECHNOLOGY_OPTIONS.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></Field><Field className="span-2" label="暴露范围"><select value={productProfile.exposure_scope || "unknown"} onChange={(event) => updateProductProfile({ exposure_scope: event.target.value })} aria-label="暴露范围">{PRODUCT_EXPOSURE_SCOPE_OPTIONS.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></Field><Field className="span-2" label="剂型"><select value={(productProfile.dosage_forms || [])[0] || ""} onChange={(event) => updateDosageForm(event.target.value)} aria-label="剂型">{PRODUCT_DOSAGE_FORM_OPTIONS.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></Field><Field className="span-2" label="给药途径"><div className="authoring-choice-grid" role="group" aria-label="给药途径">{PRODUCT_ADMINISTRATION_ROUTES.map((route) => <label key={route} className={(productProfile.administration_routes || []).includes(route) ? "selected" : ""}><input type="checkbox" checked={(productProfile.administration_routes || []).includes(route)} onChange={() => toggleAdministrationRoute(route)} /><span>{route}</span></label>)}</div></Field><Field className="span-4" label="ClinicalTrials.gov疾病检索词（系统建议，可修改）"><input value={framing.clinicaltrials_condition_term || ""} onChange={(event) => update("clinicaltrials_condition_term", event.target.value)} placeholder="可留空；系统先按适应症形成检索计划，并可在调研后建议规范英文词" /><small>该字段用于优化注册库检索，不是启动检索的硬门；留空时使用适应症。</small></Field></div><ConversationalFactIntake factConversation={factConversation} setFactConversation={setFactConversation} onSubmit={onSubmitFactIntake} onApplyProposal={onApplyFactProposal} busy={busy} interactionLocked={interactionLocked} /></section>;
 }
 if (group === "purpose") return <section className="authoring-field-section"><header><strong>内在研究目的</strong><span>不是正文中的“研究目的”，用于决定设计路径和证据检索范围</span></header><div className="authoring-choice-grid">{PURPOSE_OPTIONS.map((item) => <label key={item} className={framing.intrinsic_objectives.includes(item) ? "selected" : ""}><input type="checkbox" checked={framing.intrinsic_objectives.includes(item)} onChange={() => update("intrinsic_objectives", framing.intrinsic_objectives.includes(item) ? framing.intrinsic_objectives.filter((value) => value !== item) : [...framing.intrinsic_objectives, item])} /><span>{item}</span></label>)}</div><Field label="其他研究目的（自然语言，每行一项）"><textarea rows={3} value={lineText(framing.intrinsic_objectives.filter((item) => !PURPOSE_OPTIONS.includes(item)))} onChange={(event) => update("intrinsic_objectives", [...framing.intrinsic_objectives.filter((item) => PURPOSE_OPTIONS.includes(item)), ...lines(event.target.value)])} placeholder="可填写组合研究目的或列表中没有的其他目的" /></Field><Field label="关键科学与开发不确定性（每行一项）"><textarea rows={4} value={lineText(framing.key_uncertainties)} onChange={(event) => update("key_uncertainties", lines(event.target.value))} /></Field></section>;
 if (group === "competition") return <section className="authoring-field-section"><header><strong>靶点与竞品范围</strong><span>第一步完成后据此形成宽检索和人工分诊篮子；未知时可留空，由IB或后续证据补充</span></header><div className="authoring-field-grid two"><Field label="靶点/作用机制"><textarea rows={4} value={framing.target_mechanism} onChange={(event) => update("target_mechanism", event.target.value)} /></Field><Field label="竞品靶点与机制范围"><textarea rows={4} value={framing.competitor_target_scope} onChange={(event) => update("competitor_target_scope", event.target.value)} placeholder="可扩展到同靶点、同机制或同治疗线竞品" /></Field><Field label="已准备的Protocol文件名称或资料编号（每行一项）" className="span-2"><textarea rows={4} value={lineText(framing.manual_source_ids)} onChange={(event) => update("manual_source_ids", lines(event.target.value))} placeholder="此处登记资料；原文将在语料准备步骤导入并校验文件角色" /></Field></div></section>;
 return <DesignIntentFields framing={framing} update={update} />;
}

function parsePopulationIntentStructure(text) {
 const source = String(text || "");
 const extract = (label, options) => {
 const match = source.match(new RegExp(`${label}：([^；;]+)`));
 if (!match) return [];
 return options.filter((item) => match[1].includes(item));
 };
 let freeText = source;
 for (const label of ["年龄段", "疾病状态", "经治情况"]) {
 freeText = freeText.replace(new RegExp(`${label}：[^；;]*[；;]?`, "g"), "");
 }
 return {
 ageBands: extract("年龄段", POPULATION_AGE_BAND_OPTIONS),
 diseaseStates: extract("疾病状态", POPULATION_DISEASE_STATE_OPTIONS),
 treatmentStatuses: extract("经治情况", POPULATION_TREATMENT_STATUS_OPTIONS),
 freeText: freeText.replace(/^[；;\s]+|[；;\s]+$/g, "").trim(),
 };
}

function composePopulationIntent({ ageBands, diseaseStates, treatmentStatuses, freeText }) {
 const parts = [];
 if (ageBands.length) parts.push(`年龄段：${ageBands.join("、")}`);
 if (diseaseStates.length) parts.push(`疾病状态：${diseaseStates.join("、")}`);
 if (treatmentStatuses.length) parts.push(`经治情况：${treatmentStatuses.join("、")}`);
 if (String(freeText || "").trim()) parts.push(String(freeText).trim());
 return parts.join("；");
}

function DesignIntentFields({ framing, update }) {
 const parsed = parsePopulationIntentStructure(framing.population_intent);
 const [ageBands, setAgeBands] = useState(parsed.ageBands);
 const [diseaseStates, setDiseaseStates] = useState(parsed.diseaseStates);
 const [treatmentStatuses, setTreatmentStatuses] = useState(parsed.treatmentStatuses);
 const [freeText, setFreeText] = useState(parsed.freeText);
 const lastComposedRef = useRef(framing.population_intent || "");

 useEffect(() => {
 if ((framing.population_intent || "") === lastComposedRef.current) return;
 const next = parsePopulationIntentStructure(framing.population_intent);
 setAgeBands(next.ageBands);
 setDiseaseStates(next.diseaseStates);
 setTreatmentStatuses(next.treatmentStatuses);
 setFreeText(next.freeText);
 lastComposedRef.current = framing.population_intent || "";
 }, [framing.population_intent]);

 const writePopulationIntent = (nextAge, nextDisease, nextTreatment, nextFree) => {
 const composed = composePopulationIntent({
 ageBands: nextAge,
 diseaseStates: nextDisease,
 treatmentStatuses: nextTreatment,
 freeText: nextFree,
 });
 lastComposedRef.current = composed;
 update("population_intent", composed);
 };

 const toggleMulti = (current, value, setter, writer) => {
 const next = current.includes(value)
 ? current.filter((item) => item !== value)
 : [...current, value];
 setter(next);
 writer(next);
 };

 return (
 <section className="authoring-field-section">
 <header>
 <strong>总体设计意图</strong>
 <span>回答“准备做什么研究”，暂不要求写成方案正文；总体设计须明确采用/不采用，禁止待确认</span>
 </header>
 <div className="authoring-field-grid two">
 <Field label="总体设计模式" required>
 <textarea
 rows={5}
 value={framing.design_pattern}
 onChange={(event) => update("design_pattern", event.target.value)}
 placeholder="如随机、双盲、安慰剂对照、平行组、多中心"
 />
 </Field>
 <Field label="目标研究人群意图" required>
 <div className="authoring-population-structure" data-testid="population-structure-fields">
 <div className="authoring-choice-grid" role="group" aria-label="年龄段">
 <span className="authoring-population-structure-label">年龄段</span>
 {POPULATION_AGE_BAND_OPTIONS.map((item) => (
 <label key={item} className={ageBands.includes(item) ? "selected" : ""}>
 <input
 type="checkbox"
 checked={ageBands.includes(item)}
 onChange={() => toggleMulti(ageBands, item, setAgeBands, (next) => writePopulationIntent(next, diseaseStates, treatmentStatuses, freeText))}
 />
 <span>{item}</span>
 </label>
 ))}
 </div>
 <div className="authoring-choice-grid" role="group" aria-label="疾病状态">
 <span className="authoring-population-structure-label">疾病状态</span>
 {POPULATION_DISEASE_STATE_OPTIONS.map((item) => (
 <label key={item} className={diseaseStates.includes(item) ? "selected" : ""}>
 <input
 type="checkbox"
 checked={diseaseStates.includes(item)}
 onChange={() => toggleMulti(diseaseStates, item, setDiseaseStates, (next) => writePopulationIntent(ageBands, next, treatmentStatuses, freeText))}
 />
 <span>{item}</span>
 </label>
 ))}
 </div>
 <div className="authoring-choice-grid" role="group" aria-label="经治情况">
 <span className="authoring-population-structure-label">经治情况</span>
 {POPULATION_TREATMENT_STATUS_OPTIONS.map((item) => (
 <label key={item} className={treatmentStatuses.includes(item) ? "selected" : ""}>
 <input
 type="checkbox"
 checked={treatmentStatuses.includes(item)}
 onChange={() => toggleMulti(treatmentStatuses, item, setTreatmentStatuses, (next) => writePopulationIntent(ageBands, diseaseStates, next, freeText))}
 />
 <span>{item}</span>
 </label>
 ))}
 </div>
 <textarea
 rows={3}
 value={freeText}
 onChange={(event) => {
 const next = event.target.value;
 setFreeText(next);
 writePopulationIntent(ageBands, diseaseStates, treatmentStatuses, next);
 }}
 placeholder="补充疾病定义、治疗线、既往治疗与严重程度等自然语言意图"
 aria-label="目标研究人群补充说明"
 />
 <small>上述选项会自动写入「目标研究人群意图」摘要；可继续补充自然语言细节。</small>
 </div>
 </Field>
 </div>
 <Phase1PartsEditor framing={framing} update={update} />
 </section>
 );
}

function Phase1PartsEditor({ framing, update, onSave = null, dirty = false, busy = "" }) {
 const parts = phase1PartsFromFraming(framing);
 const selectedCodesKey = parts.map((part) => part.part_code).join("|");
 const [expandedCodes, setExpandedCodes] = useState([]);
 useEffect(() => {
 const currentCodes = parts.map((part) => part.part_code).filter(Boolean);
 setExpandedCodes((current) => {
 const retained = current.filter((code) => currentCodes.includes(code));
 if (retained.length || !currentCodes.length) return retained;
 const firstUnresolved = parts.find(
 (part) => !String(part.population || "").trim() || !String(part.cohort_dose || "").trim(),
 );
 return [firstUnresolved?.part_code || currentCodes[0]];
 });
 // Part codes are the stable accordion identity; field edits must not reset expansion.
 }, [selectedCodesKey]);

 if (!isPhaseOneStudy(framing?.study_phase)) return null;

 const structuredDesign = framing.structured_design || {};
 const writeDesign = (patch) => update("structured_design", { ...structuredDesign, ...patch });
 const availableOptions = [
 ...PHASE1_PART_OPTIONS,
 ...parts
 .filter((part) => !PHASE1_PART_OPTIONS.some((option) => option.code === part.part_code))
 .map((part) => ({ code: part.part_code, label: part.part_label || part.part_code })),
 ];
 const togglePart = (option, selected) => {
 const nextParts = selected
 ? [...parts, {
 part_code: option.code,
 part_label: option.label,
 population: "",
 cohort_dose: "",
 pk_pd: "",
 safety: "",
 stopping_rules: "",
 soa_summary: "",
 transition_dependencies: "",
 unresolved: true,
 }]
 : parts.filter((part) => part.part_code !== option.code);
 writeDesign({ phase1_parts: nextParts });
 setExpandedCodes((current) => selected
 ? [...new Set([...current, option.code])]
 : current.filter((code) => code !== option.code));
 };
 const updatePart = (partCode, field, value) => {
 writeDesign({
 phase1_parts: parts.map((part) => (
 part.part_code === partCode ? { ...part, [field]: value } : part
 )),
 });
 };

 return <section className="phase1-parts-editor" aria-label="I期复合研究Part编辑器">
 <header>
 <div>
 <strong>I期复合研究 Parts</strong>
 <span>已采用或已保存的内容直接载入；可分次补充。研究人群与队列/剂量方案缺失时，确定性投影继续阻断。</span>
 </div>
 {onSave && <button type="button" onClick={onSave} disabled={!dirty || Boolean(busy)}><Save size={14} /> {String(busy).startsWith("draft-") ? "保存中" : "保存研究设计草稿"}</button>}
 </header>
 <div className="phase1-part-selector" aria-label="选择I期研究Part">
 {availableOptions.filter((option) => option.code).map((option) => {
 const selected = parts.some((part) => part.part_code === option.code);
 return <label key={option.code} className={selected ? "selected" : ""}>
 <input type="checkbox" checked={selected} onChange={(event) => togglePart(option, event.target.checked)} />
 <span>{option.label}</span>
 </label>;
 })}
 </div>
 {parts.length > 1 && <Field className="phase1-part-sequence" label="Part总体序列/并行关系"><textarea rows={2} value={structuredDesign.phase1_sequence || ""} onChange={(event) => writeDesign({ phase1_sequence: event.target.value })} placeholder="说明各Part的先后、并行、数据审阅或转段关系" /></Field>}
 {parts.length ? <div className="phase1-part-list">
 {parts.map((part) => {
 const resolved = Boolean(String(part.population || "").trim() && String(part.cohort_dose || "").trim());
 const populatedCount = PHASE1_PART_DETAIL_FIELDS.filter((field) => String(part[field.key] || "").trim()).length;
 return <details key={part.part_code} className="phase1-part-item" open={expandedCodes.includes(part.part_code)} onToggle={(event) => setExpandedCodes((current) => event.currentTarget.open ? [...new Set([...current, part.part_code])] : current.filter((code) => code !== part.part_code))}>
 <summary>
 <span><strong>{part.part_code}</strong><small>{part.part_label || "名称待补"} · {populatedCount}/{PHASE1_PART_DETAIL_FIELDS.length}项已有内容</small></span>
 <em className={resolved ? "ready" : ""}>{resolved ? "投影必填已齐" : "缺投影必填"}</em>
 </summary>
 <div className="phase1-part-fields">
 <Field className="phase1-part-label" label="Part显示名称"><input value={part.part_label || ""} onChange={(event) => updatePart(part.part_code, "part_label", event.target.value)} /></Field>
 {PHASE1_PART_DETAIL_FIELDS.map((field) => <Field key={field.key} className={field.key === "transition_dependencies" ? "phase1-part-wide" : ""} label={field.label} required={field.required}><textarea rows={field.rows} value={part[field.key] || ""} onChange={(event) => updatePart(part.part_code, field.key, event.target.value)} placeholder={field.placeholder} /></Field>)}
 </div>
 </details>;
 })}
 </div> : <p className="phase1-part-empty">尚未选择Part。可先保留为空，后续根据研究目的和证据逐项选择。</p>}
 </section>;
}

const STRUCTURED_DESIGN_MODE_OPTIONS = Object.freeze({
 randomization_mode: [
 ["undecided", "待确认"],
 ["randomized", "随机"],
 ["non_randomized", "非随机"],
 ["other", "其他（需说明）"],
 ],
 blinding_mode: [
 ["undecided", "待确认"],
 ["open_label", "开放标签"],
 ["single_blind", "单盲"],
 ["double_blind", "双盲"],
 ["triple_blind", "三盲"],
 ["other", "其他（需说明）"],
 ],
 comparator_type: [
 ["undecided", "待确认"],
 ["placebo", "安慰剂对照"],
 ["active", "阳性/活性对照"],
 ["none_or_dose_escalation", "无对照/剂量递增"],
 ["other", "其他（需说明）"],
 ],
});

const STRUCTURED_DESIGN_PLANNED_FIELDS = Object.freeze([
 ["adaptive_design", "适应性设计"],
 ["crossover", "交叉设计"],
 ["open_label_extension", "开放标签延伸"],
 ["treatment_switch", "治疗转换"],
 ["sample_size_reestimation", "样本量重估"],
 ["interim_analysis", "期中分析"],
]);

function plannedValue(value) {
 if (value === true) return "true";
 if (value === false) return "false";
 return "";
}

function StructuredDesignFactEditor({ framing, picos, update }) {
 const design = framing.structured_design || {};
 const updateDesign = (patch) => update("structured_design", { ...design, ...patch });
 const updatePlanned = (key, value) => updateDesign({
 [key]: { ...(design[key] || {}), planned: value === "" ? null : value === "true" },
 });
 const text = `${framing.design_pattern || ""} ${picos?.comparator_summary || ""}`;
 const currentTextSuggestion = {
 randomization_mode: /随机/.test(text) ? "randomized" : "undecided",
 blinding_mode: /三盲/.test(text) ? "triple_blind" : /双盲/.test(text) ? "double_blind" : /单盲/.test(text) ? "single_blind" : /开放标签/.test(text) ? "open_label" : "undecided",
 comparator_type: /安慰剂/.test(text) ? "placebo" : /活性对照|阳性对照/.test(text) ? "active" : /剂量递增|无对照/.test(text) ? "none_or_dose_escalation" : "undecided",
 assignment_model: /平行/.test(text) ? "平行组" : /交叉/.test(text) ? "交叉设计" : "",
 center_model: /多中心/.test(text) ? "多中心" : /单中心/.test(text) ? "单中心" : "",
 };
 const applyTextSuggestion = () => updateDesign({
 ...currentTextSuggestion,
 adaptive_design: { ...(design.adaptive_design || {}), planned: false },
 crossover: { ...(design.crossover || {}), planned: currentTextSuggestion.assignment_model === "交叉设计" },
 open_label_extension: { ...(design.open_label_extension || {}), planned: false },
 treatment_switch: { ...(design.treatment_switch || {}), planned: false },
 sample_size_reestimation: { ...(design.sample_size_reestimation || {}), planned: false },
 interim_analysis: { ...(design.interim_analysis || {}), planned: false },
 src_planned: false,
 dmc_planned: false,
 });
 return <section className="authoring-structured-design-facts" data-testid="structured-design-fact-editor">
 <header><div><strong>结构化研究设计确认</strong><span>AI/当前方案文字已给出建议；确认后才会投影到方案摘要、流程图和正文。未确认的维度继续阻断，不会被系统猜测。</span></div><button type="button" className="secondary-button" data-action="apply-structured-design-suggestion" onClick={applyTextSuggestion}>采用当前方案文字建议</button></header>
 <div className="authoring-field-grid three">
 {[["randomization_mode", "随机化"], ["blinding_mode", "盲法"], ["comparator_type", "对照类型"]].map(([key, label]) => <Field key={key} label={label} required><select aria-label={label} value={design[key] || "undecided"} onChange={(event) => updateDesign({ [key]: event.target.value })}>{STRUCTURED_DESIGN_MODE_OPTIONS[key].map(([value, option]) => <option key={value} value={value}>{option}</option>)}</select></Field>)}
 <Field label="分组/分配方式" required><select aria-label="分组/分配方式" value={design.assignment_model || ""} onChange={(event) => updateDesign({ assignment_model: event.target.value })}><option value="">待确认</option><option value="平行组">平行组</option><option value="交叉设计">交叉设计</option><option value="序贯设计">序贯设计</option><option value="其他">其他（需说明）</option></select></Field>
 <Field label="中心模式" required><select aria-label="中心模式" value={design.center_model || ""} onChange={(event) => updateDesign({ center_model: event.target.value })}><option value="">待确认</option><option value="多中心">多中心</option><option value="单中心">单中心</option><option value="有限中心">有限中心</option><option value="其他">其他（需说明）</option></select></Field>
 <Field label="随机化/盲法补充说明"><input aria-label="随机化盲法补充说明" value={design.randomization_details || ""} onChange={(event) => updateDesign({ randomization_details: event.target.value })} placeholder="可保留分层因素、盲态角色等具体说明" /></Field>
 </div>
 <div className="authoring-structured-planned-grid" aria-label="复杂设计计划状态">
 {STRUCTURED_DESIGN_PLANNED_FIELDS.map(([key, label]) => <label key={key}><span>{label}</span><select aria-label={`${label}计划状态`} value={plannedValue(design[key]?.planned)} onChange={(event) => updatePlanned(key, event.target.value)}><option value="">待确认</option><option value="false">不计划</option><option value="true">计划</option></select></label>)}
 <label><span>SRC</span><select aria-label="SRC计划状态" value={design.src_planned == null ? "" : String(Boolean(design.src_planned))} onChange={(event) => updateDesign({ src_planned: event.target.value === "" ? null : event.target.value === "true" })}><option value="">待确认</option><option value="false">不计划</option><option value="true">计划</option></select></label>
 <label><span>DMC</span><select aria-label="DMC计划状态" value={design.dmc_planned == null ? "" : String(Boolean(design.dmc_planned))} onChange={(event) => updateDesign({ dmc_planned: event.target.value === "" ? null : event.target.value === "true" })}><option value="">待确认</option><option value="false">不计划</option><option value="true">计划</option></select></label>
 </div>
 </section>;
}

function PicosFields({ projectId, framing, picos, group, updateFraming, update, updateApplicability, interventionPanel, setInterventionPanel, hasPrefillRecommendations = false, existingDocument = false, readOnly = false, appendixReady = false, onSaveDesignDraft = null, framingDirty = false, busy = "" }) {
 if (group === "applicability") return <section className="authoring-field-section"><header><strong>研究设计适用性</strong><span>优先采用上方调研建议；随机化、盲法、对照、分组和期中分析等维度分别确认，系统再组合成研究设计。</span></header>{picos.design_archetype && <div className="authoring-current-design"><CheckCircle2 size={15} /><span>当前兼容设计类型：<strong>{DESIGN_ARCHETYPES.find((item) => item.value === picos.design_archetype)?.label || picos.design_archetype}</strong></span></div>}<details className="authoring-manual-design-options" open={!hasPrefillRecommendations}><summary>{hasPrefillRecommendations ? "手动选择兼容设计类型" : "选择兼容设计类型"}</summary><div className="authoring-design-archetypes">{DESIGN_ARCHETYPES.map((item) => <label key={item.value} className={picos.design_archetype === item.value ? "selected" : ""}><input type="radio" name="picos-design-archetype" value={item.value} checked={picos.design_archetype === item.value} onChange={() => update("design_archetype", item.value)} /><span><strong>{item.label}</strong><small>{item.detail}</small></span></label>)}</div></details>{picos.design_archetype && <div className="authoring-applicability-list"><div className="authoring-applicability-head"><strong>条件字段</strong><span>标记为“不适用”时，必须填写理由并由医学经理确认。</span></div>{CONDITIONAL_PICOS_FIELDS.map((item) => { const decision = picos.field_applicability?.[item.key] || { status: "applicable", reason: "", confirmed_by_medical_manager: false }; const lockedRequired = picos.design_archetype === "randomized_confirmatory" || (picos.design_archetype === "randomized_exploratory" && item.key === "comparator_summary"); const notApplicable = decision.status === "not_applicable"; return <div className="authoring-applicability-row" key={item.key}><div><strong>{item.label}</strong><small>{lockedRequired ? "当前随机设计中必须填写" : "可根据已确认的研究设计判断是否适用"}</small></div><select aria-label={`${item.label}适用性`} value={lockedRequired ? "applicable" : decision.status} onChange={(event) => updateApplicability(item.key, { status: event.target.value })} disabled={lockedRequired}><option value="applicable">适用，需填写</option><option value="not_applicable">不适用</option></select>{notApplicable && !lockedRequired && <><textarea aria-label={`${item.label}不适用理由`} rows={2} value={decision.reason || ""} onChange={(event) => updateApplicability(item.key, { reason: event.target.value })} placeholder="说明本研究为何无需该设计项；不少于10个字符" /><label className="authoring-applicability-confirm"><input type="checkbox" checked={Boolean(decision.confirmed_by_medical_manager)} onChange={(event) => updateApplicability(item.key, { confirmed_by_medical_manager: event.target.checked })} /><span>医学经理确认该项不适用</span></label></>}</div>; })}</div>}<StructuredDesignFactEditor framing={framing} picos={picos} update={updateFraming} /><Phase1PartsEditor framing={framing} update={updateFraming} onSave={onSaveDesignDraft} dirty={framingDirty} busy={busy} /></section>;
 if (group === "population") return <section className="authoring-field-section"><header><strong>研究人群</strong><span>模块化确定人群、入排、洗脱与重筛边界</span></header><div className="authoring-field-grid two"><Field label="目标人群概述" required className="span-2"><textarea rows={3} value={picos.population_summary} onChange={(event) => update("population_summary", event.target.value)} /></Field><StructuredListField label="入选标准" prefix="IN" required value={picos.inclusion_modules} onChange={(value) => update("inclusion_modules", value)} /><StructuredListField label="排除标准" prefix="EX" required value={picos.exclusion_modules} onChange={(value) => update("exclusion_modules", value)} /><StructuredListField className="span-2" label="药物/治疗洗脱规则" prefix="WO" value={picos.washout_rules} onChange={(value) => update("washout_rules", value)} /></div></section>;
 if (group === "intervention") return <section className="authoring-field-section"><header><strong>干预措施</strong><span>试验药物、非试验用药和普通CM保持清晰边界</span></header><div className="authoring-field-grid two"><Field label="试验药物干预概述" required><textarea rows={4} value={picos.intervention_summary} onChange={(event) => update("intervention_summary", event.target.value)} /></Field><Field label="试验药物常规用法用量" required><textarea rows={4} value={picos.intervention_dose_regimen} onChange={(event) => update("intervention_dose_regimen", event.target.value)} /></Field><StructuredListField label="必须使用/背景治疗" prefix="BG" value={picos.required_background_rules} onChange={(value) => update("required_background_rules", value)} /><StructuredListField label="允许使用的合并用药/治疗" prefix="CM-A" value={picos.allowed_concomitant_rules} onChange={(value) => update("allowed_concomitant_rules", value)} /><StructuredListField label="限制/禁止使用的合并用药/治疗" prefix="CM-P" value={picos.prohibited_concomitant_rules} onChange={(value) => update("prohibited_concomitant_rules", value)} /><StructuredListField label="访视/评价前用药与治疗限制" prefix="TIME" value={picos.assessment_timing_restrictions} onChange={(value) => update("assessment_timing_restrictions", value)} /></div><InterventionRulesEditor value={picos.intervention_rules || null} onChange={(value) => update("intervention_rules", value)} panel={interventionPanel} onPanelChange={setInterventionPanel} /></section>;
 if (group === "comparator") { const notApplicable = picos.field_applicability?.comparator_summary?.status === "not_applicable" && !["randomized_confirmatory", "randomized_exploratory"].includes(picos.design_archetype); return <section className="authoring-field-section"><header><strong>对照</strong><span>{notApplicable ? "已在设计适用性中标记为不适用；理由仍保留在正式研究事实中" : "明确安慰剂、阳性对照或随机组间比较及其用法用量"}</span></header>{notApplicable ? <ApplicabilitySummary label="对照/组间比较设计" decision={picos.field_applicability.comparator_summary} onEdit={() => {}} /> : <Field label="对照/组间比较设计" required><textarea rows={7} value={picos.comparator_summary} onChange={(event) => update("comparator_summary", event.target.value)} /></Field>}</section>; }
 if (group === "outcomes") return <section className="authoring-field-section"><header><strong>结局指标</strong><span>终点定义必须包含评价变量、时间点和必要的应答规则</span></header><div className="authoring-field-grid two"><Field label="主要终点及评价时间" required className="span-2"><textarea rows={3} value={picos.primary_endpoint} onChange={(event) => update("primary_endpoint", event.target.value)} /></Field><ListField label="关键次要终点" value={picos.key_secondary_endpoints} onChange={(value) => update("key_secondary_endpoints", value)} /><ListField label="其他次要终点" value={picos.other_secondary_endpoints} onChange={(value) => update("other_secondary_endpoints", value)} /><ListField label="探索性终点" value={picos.exploratory_endpoints} onChange={(value) => update("exploratory_endpoints", value)} /><ListField label="安全性终点" required value={picos.safety_endpoints} onChange={(value) => update("safety_endpoints", value)} /><ListField label="AESI定义" value={picos.aesi_definitions} onChange={(value) => update("aesi_definitions", value)} /></div><AssessmentInstrumentEditor projectId={projectId} value={picos.assessment_instruments || []} onChange={(value) => update("assessment_instruments", value)} existingDocument={existingDocument} readOnly={readOnly} appendixReady={appendixReady} /></section>;
 const estimandNotApplicable = picos.field_applicability?.estimand_strategy?.status === "not_applicable" && picos.design_archetype !== "randomized_confirmatory";
 return <section className="authoring-field-section"><header><strong>研究执行与统计</strong><span>补齐生成流程表、估计目标和统计章节所需结构事实</span></header><div className="authoring-field-grid two"><ListField label="研究时期/阶段" required value={picos.study_epochs} onChange={(value) => update("study_epochs", value)} /><Field label="访视策略" required><textarea rows={4} value={picos.visit_strategy} onChange={(event) => update("visit_strategy", event.target.value)} placeholder="概述筛选、基线、治疗、关键评价和随访访视；具体活动可在SoA表格设计器中完善" /></Field>{estimandNotApplicable ? <ApplicabilitySummary label="估计目标策略" decision={picos.field_applicability.estimand_strategy} /> : <Field label="估计目标策略" required><textarea rows={4} value={picos.estimand_strategy} onChange={(event) => update("estimand_strategy", event.target.value)} /></Field>}<Field label="样本量策略" required><textarea rows={4} value={picos.sample_size_strategy} onChange={(event) => update("sample_size_strategy", event.target.value)} /></Field><Field label="统计分析策略" required className="span-2"><textarea rows={4} value={picos.statistical_strategy} onChange={(event) => update("statistical_strategy", event.target.value)} /></Field></div></section>;
}

const INSTRUMENT_KIND_OPTIONS = [
 ["clinician_reported", "研究者/临床医生评估"],
 ["patient_reported", "患者报告结局（PRO）"],
 ["observer_reported", "观察者报告结局"],
 ["performance_outcome", "操作/表现结局"],
 ["diagnostic_criterion", "诊断/入排判定工具"],
 ["safety_grading", "安全性分级标准"],
 ["other", "其他评估工具"],
];
const TRANSLATION_STATUS_OPTIONS = [
 ["unknown", "中文版本待核实"], ["not_needed", "无需翻译"], ["official_available", "已有官方中文版本"],
 ["validated_available", "已有验证中文版本"], ["permission_required", "翻译/使用需许可"],
 ["translation_candidate", "中文候选待医学审阅"], ["medical_reviewed", "医学已审阅"], ["unavailable", "未找到可用中文版本"],
];
const RIGHTS_STATUS_OPTIONS = [
 ["unknown", "权利状态待核实"], ["permission_required", "使用前需许可"], ["license_pending", "许可申请中"],
 ["licensed", "当前项目已获许可"], ["public_domain", "公共领域"], ["permission_not_required", "已确认无需许可"],
];
const ENDPOINT_BINDINGS = [
 ["picos.primary_endpoint", "主要终点"], ["picos.key_secondary_endpoints", "关键次要终点"],
 ["picos.other_secondary_endpoints", "其他次要终点"], ["picos.exploratory_endpoints", "探索性终点"],
 ["picos.safety_endpoints", "安全性终点"], ["picos.inclusion_modules", "入选标准"], ["picos.exclusion_modules", "排除标准"],
];

function newInstrument() {
 const identity = typeof globalThis.crypto?.randomUUID === "function" ? globalThis.crypto.randomUUID() : `${Math.random().toString(16).slice(2)}-${Math.random().toString(16).slice(2)}`;
 return {
 instrument_id: `mwinstrument_${identity}`, canonical_name_zh: "待命名评估工具", canonical_name_en: "", acronym: "", version_label: "",
 instrument_kind: "other", administration_mode: "", respondent: "", recall_period: "", scoring_range: "", scoring_direction: "", scoring_summary: "", study_purpose: "",
 endpoint_paths: [], visit_labels: [], soa_activity_ids: [], appendix_locator: "", protocol_modified: false, source_synopsis_only: false, evidence_span_ids: [], source_bindings: [],
 rights: { status: "unknown", full_text_policy: "metadata_only", owner: "", license_reference: "", evidence_url: "", checked_at: null, confirmed_by: "", confirmed_at: null },
 translation: { source_language: "", target_language: "简体中文", status: "unknown", version_label: "", source_url: "", artifact_id: "", reviewed_by: "", reviewed_at: null },
 confirmation_status: "candidate", confirmed_by: "", confirmed_at: null, notes: "",
 };
}

function AssessmentInstrumentEditor({ projectId, value, onChange, existingDocument = false, readOnly = false, appendixReady = false }) {
 const [selectedId, setSelectedId] = useState(value[0]?.instrument_id || "");
 const [appendixFile, setAppendixFile] = useState(null);
 const [appendixTarget, setAppendixTarget] = useState(null);
 const [appendixResult, setAppendixResult] = useState(null);
 const [appendixPages, setAppendixPages] = useState([]);
 const [appendixBusy, setAppendixBusy] = useState(false);
 const [appendixMessage, setAppendixMessage] = useState("");
 useEffect(() => {
 if (!value.length) {
 if (selectedId) setSelectedId("");
 return;
 }
 if (!value.some((item) => item.instrument_id === selectedId)) {
 setSelectedId(value[0].instrument_id);
 }
 }, [selectedId, value]);
 useEffect(() => {
 const controller = new AbortController();
 setAppendixFile(null);
 setAppendixTarget(null);
 setAppendixResult(null);
 setAppendixPages([]);
 setAppendixMessage("");
 if (!projectId || !existingDocument || !selectedId) return () => controller.abort();
 (async () => {
 try {
 const document = await fetch(
 `/api/projects/${projectId}/medical-writing/document-session`,
 { signal: controller.signal },
 ).then(readJson);
 const sections = document.sections || [];
 const section = (
 sections.find((item) => item.node_kind === "assessment_instrument_appendix")
 || sections.find((item) => /instrument/i.test(item.template_node_id || ""))
 || sections.find((item) => /量表|评价工具/.test(item.heading || ""))
 || sections.find((item) => (item.interaction_types || []).includes("assessment_instrument_builder"))
 || sections.find((item) => item.section_number === "14.2" && /量表|评价工具/.test(item.heading || ""))
 );
 if (!section) {
 setAppendixMessage("当前方案未启用“研究量表和评价工具”章节。");
 return;
 }
 const workingCopy = await fetch(
 `/api/projects/${projectId}/medical-writing/working-copies/${section.section_id}`,
 { signal: controller.signal },
 ).then(readJson);
 if (controller.signal.aborted) return;
 const pages = (workingCopy.content_blocks || []).filter((block) => (
 block.block_type === "appendix_image"
 && block.attachment_kind === "assessment_instrument_page"
 && block.instrument_id === selectedId
 ));
 setAppendixTarget({ section, workingCopy });
 // Keep block references only; preview reads image_base64 from these objects.
 setAppendixPages(pages);
 if (pages.length) {
 const first = pages[0];
 setAppendixResult({
 source_filename: first.source_filename,
 page_count: first.page_count || pages.length,
 render_dpi: first.render_dpi,
 projection_action: "existing",
 updated_at: workingCopy.updated_at,
 });
 }
 } catch (error) {
 if (error.name !== "AbortError" && !controller.signal.aborted) {
 setAppendixMessage(error.status === 404 ? "方案正文尚未生成，生成后可上传原始量表。" : `量表附件状态读取失败：${error.message}`);
 }
 }
 })();
 return () => controller.abort();
 }, [existingDocument, projectId, selectedId]);
 const selected = value.find((item) => item.instrument_id === selectedId) || null;
 const updateItem = (patch) => onChange(value.map((item) => item.instrument_id === selectedId ? { ...item, ...patch } : item));
 const updateNested = (field, patch) => updateItem({ [field]: { ...(selected?.[field] || {}), ...patch } });
 const add = () => { const next = newInstrument(); onChange([...value, next]); setSelectedId(next.instrument_id); };
 const remove = () => {
 const next = value.filter((item) => item.instrument_id !== selectedId);
 onChange(next);
 setSelectedId(next[0]?.instrument_id || "");
 };
 const toggleEndpoint = (path) => updateItem({ endpoint_paths: selected.endpoint_paths.includes(path) ? selected.endpoint_paths.filter((item) => item !== path) : [...selected.endpoint_paths, path] });
 const uploadAppendix = async () => {
 if (!appendixFile || !appendixTarget || !selected || appendixBusy) return;
 setAppendixBusy(true);
 setAppendixMessage("正在上传并按 220 DPI 转换原始页面...");
 try {
 const form = new FormData();
 form.append("file", appendixFile);
 form.append("instrument_id", selected.instrument_id);
 form.append("expected_working_copy_revision", String(appendixTarget.workingCopy.revision));
 form.append("actor", "medical_manager");
 form.append("dpi", "220");
 form.append(
 "idempotency_key",
 await stableInstrumentAppendixUploadKey(
 projectId,
 appendixTarget.section.section_id,
 selected.instrument_id,
 appendixTarget.workingCopy.revision,
 appendixFile,
 ),
 );
 const payload = await fetch(
 `/api/projects/${projectId}/medical-writing/working-copies/${appendixTarget.section.section_id}/assessment-instrument-appendix`,
 { method: "POST", body: form },
 ).then(readJson);
 setAppendixTarget((current) => ({ ...current, workingCopy: payload.working_copy }));
 setAppendixResult(payload);
 const refreshedPages = (payload.working_copy?.content_blocks || []).filter((block) => (
 block.block_type === "appendix_image"
 && block.attachment_kind === "assessment_instrument_page"
 && block.instrument_id === selected.instrument_id
 ));
 setAppendixPages(refreshedPages);
 const sectionLabel = [payload.target_section_number, payload.target_section_heading].filter(Boolean).join(" ");
 setAppendixMessage(payload.projection_action === "replaced" ? `已替换“${sectionLabel}”中的原始量表页面。` : `已写入“${sectionLabel}”。`);
 setAppendixFile(null);
 } catch (error) {
 setAppendixMessage(
 error.status === 409
 ? "目标章节已被更新，请重新选择文件后再试。"
 : error.status === 422
 ? `暂不能写入：${error.message}`
 : `量表附件上传失败：${error.message}`,
 );
 } finally {
 setAppendixBusy(false);
 }
 };
 return <section className="authoring-instrument-registry">
 <header><div><strong>量表与评估工具</strong><span>统一维护版本、项目用法、评价时点、中文版本及全文使用边界；未知状态不会被系统自动视为已获许可。</span></div><button type="button" onClick={add}><Plus size={14} /> 新增工具</button></header>
 {!value.length ? <div className="authoring-instrument-empty"><p>尚未登记量表或评分工具。可根据主要/次要终点添加；竞品方案提取的候选也将在此处待用户确认。</p><button type="button" onClick={add}><Plus size={14} /> 登记第一个工具</button></div> : <div className="authoring-instrument-layout">
 <div className="authoring-instrument-list" role="listbox" aria-label="量表与评估工具列表">{value.map((item) => <button type="button" role="option" aria-selected={item.instrument_id === selectedId} className={item.instrument_id === selectedId ? "selected" : ""} key={item.instrument_id} onClick={() => setSelectedId(item.instrument_id)}><span><strong>{item.acronym || item.canonical_name_zh}</strong><small>{item.acronym ? item.canonical_name_zh : item.canonical_name_en || "英文名称待补充"}</small></span><em className={`instrument-state ${item.confirmation_status}`}>{item.confirmation_status === "confirmed" ? "已确认" : item.confirmation_status === "needs_review" ? "需复核" : "候选"}</em></button>)}</div>
 {selected && <div className="authoring-instrument-editor">
 <div className="authoring-instrument-editor-head"><div><strong>{selected.acronym || selected.canonical_name_zh}</strong><span>{selected.version_label || "版本待确认"}</span></div><button type="button" className="danger-quiet" onClick={remove} title="删除当前工具"><Trash2 size={14} /> 删除</button></div>
 <div className="authoring-field-grid four"><Field label="中文规范名称" required><input value={selected.canonical_name_zh} onChange={(event) => updateItem({ canonical_name_zh: event.target.value })} /></Field><Field label="英文规范名称"><input value={selected.canonical_name_en} onChange={(event) => updateItem({ canonical_name_en: event.target.value })} /></Field><Field label="缩写"><input value={selected.acronym} onChange={(event) => updateItem({ acronym: event.target.value })} /></Field><Field label="版本/变体"><input value={selected.version_label} onChange={(event) => updateItem({ version_label: event.target.value })} placeholder="如 8a、v4、0-4分制" /></Field><Field label="工具类型"><select value={selected.instrument_kind} onChange={(event) => updateItem({ instrument_kind: event.target.value })}>{INSTRUMENT_KIND_OPTIONS.map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></Field><Field label="填写/评估者"><input value={selected.respondent} onChange={(event) => updateItem({ respondent: event.target.value })} placeholder="参与者、研究者、照护者" /></Field><Field label="回忆期"><input value={selected.recall_period} onChange={(event) => updateItem({ recall_period: event.target.value })} placeholder="如过去24小时、过去7天" /></Field><Field label="实施方式"><input value={selected.administration_mode} onChange={(event) => updateItem({ administration_mode: event.target.value })} placeholder="纸质、ePRO、访视现场" /></Field><Field label="评分范围"><input value={selected.scoring_range} onChange={(event) => updateItem({ scoring_range: event.target.value })} placeholder="如 0-52" /></Field><Field className="span-2" label="评分方向"><input value={selected.scoring_direction} onChange={(event) => updateItem({ scoring_direction: event.target.value })} placeholder="分值越高表示……" /></Field><Field label="附录/来源定位"><input value={selected.appendix_locator} onChange={(event) => updateItem({ appendix_locator: event.target.value })} placeholder="如 附录1、表6" /></Field><Field className="span-2" label="本研究用途"><textarea rows={3} value={selected.study_purpose} onChange={(event) => updateItem({ study_purpose: event.target.value })} /></Field><Field className="span-2" label="评分与应答规则摘要"><textarea rows={3} value={selected.scoring_summary} onChange={(event) => updateItem({ scoring_summary: event.target.value })} /></Field></div>
 <fieldset className="authoring-instrument-bindings"><legend>关联研究事实</legend><div>{ENDPOINT_BINDINGS.map(([path, label]) => <label key={path}><input type="checkbox" checked={selected.endpoint_paths.includes(path)} onChange={() => toggleEndpoint(path)} /><span>{label}</span></label>)}</div><Field label="评价访视/时点（每行一项）"><textarea rows={3} value={lineText(selected.visit_labels)} onChange={(event) => updateItem({ visit_labels: lines(event.target.value) })} placeholder="基线（D1）&#10;第12周（D85±7天）" /></Field></fieldset>
 <div className="authoring-instrument-governance"><section><header><strong>中文版本</strong><span>{selected.translation.status === "medical_reviewed" ? "医学已审阅" : "待按来源确认"}</span></header><label><span>状态</span><select value={selected.translation.status} onChange={(event) => updateNested("translation", { status: event.target.value, reviewed_by: event.target.value === "medical_reviewed" ? "medical_manager" : "", reviewed_at: event.target.value === "medical_reviewed" ? new Date().toISOString() : null })}>{TRANSLATION_STATUS_OPTIONS.map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label><label><span>版本/语言</span><input value={selected.translation.version_label} onChange={(event) => updateNested("translation", { version_label: event.target.value })} /></label><label><span>权威来源</span><input type="url" value={selected.translation.source_url} onChange={(event) => updateNested("translation", { source_url: event.target.value })} placeholder="量表所有者或验证研究链接" /></label></section><section><header><strong>权利与全文边界</strong><span>{selected.rights.full_text_policy === "metadata_only" ? "仅保存元数据" : "按已确认范围使用"}</span></header><label><span>状态</span><select value={selected.rights.status} onChange={(event) => updateNested("rights", { status: event.target.value })}>{RIGHTS_STATUS_OPTIONS.map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label><label><span>权利人/管理方</span><input value={selected.rights.owner} onChange={(event) => updateNested("rights", { owner: event.target.value })} /></label><label><span>许可编号或证据链接</span><input value={selected.rights.license_reference || selected.rights.evidence_url} onChange={(event) => updateNested("rights", { license_reference: event.target.value, evidence_url: /^https?:/i.test(event.target.value) ? event.target.value : selected.rights.evidence_url })} /></label></section></div>
 <section className="authoring-instrument-appendix">
 <header><div><strong>原始量表附件</strong><span>PDF原页将按 220 DPI 写入方案中的量表工具章节，保持题项、选框和版权标识的可读性。</span></div><em className={appendixResult || appendixPages.length ? "ready" : ""}>{appendixResult || appendixPages.length ? "已写入方案" : "尚未写入"}</em></header>
 {(appendixResult || appendixPages.length > 0) && <div className="authoring-instrument-appendix-result"><FileText size={16} /><span><strong title={appendixResult?.source_filename || selected.canonical_name_zh}>{appendixResult?.source_filename || selected.canonical_name_zh}</strong><small>{appendixPages.length || appendixResult?.page_count || 0} 页 · {appendixResult?.render_dpi || 220} DPI{appendixResult?.projection_action === "replaced" ? " · 已替换" : ""}</small></span></div>}
 {appendixPages.length > 0 ? (
 <InstrumentAppendixPreview
 pages={appendixPages}
 declaredPageCount={appendixResult?.page_count || appendixPages[0]?.page_count || appendixPages.length}
 instrumentLabel={selected.acronym || selected.canonical_name_zh || "量表附件"}
 />
 ) : existingDocument && selected.confirmation_status === "confirmed" && appendixReady ? (
 <InstrumentAppendixPreview pages={[]} emptyMessage="当前工作副本尚无该量表的原始页面；上传 PDF 后可在此逐页审阅。" />
 ) : null}
 {!existingDocument ? <p>完成PICOS并生成方案正文后，可在此上传原始量表PDF。</p> : selected.confirmation_status !== "confirmed" ? <p>先确认该量表在本项目中的用法，再上传原始量表PDF。</p> : !appendixReady ? <p>当前量表信息尚未保存。完成第二步后即可写入方案中的量表工具章节。</p> : !readOnly && <div className="authoring-instrument-appendix-actions"><label><input type="file" accept=".pdf,application/pdf" onChange={(event) => { setAppendixFile(event.target.files?.[0] || null); setAppendixMessage(""); }} /><Upload size={15} /><span><strong>{appendixFile?.name || (appendixResult || appendixPages.length ? "选择新PDF以替换" : "选择原始量表PDF")}</strong><small>{appendixFile ? formatFileSize(appendixFile.size) : "最多50 MB；支持1–100页"}</small></span></label><button type="button" onClick={uploadAppendix} disabled={!appendixFile || !appendixTarget || appendixBusy}>{appendixBusy ? <RefreshCw size={14} /> : <Upload size={14} />}{appendixBusy ? "处理中" : appendixResult || appendixPages.length ? "替换附件" : "写入方案"}</button></div>}
 {readOnly && appendixPages.length > 0 && <p className="success">只读模式可审阅原始页面，不可上传或删除附件。</p>}
 {appendixMessage && <p className={/失败|暂不能|未启用|尚未生成|更新/.test(appendixMessage) ? "warning" : "success"}>{appendixMessage}</p>}
 </section>
 <div className="authoring-instrument-confirm"><label><input type="checkbox" checked={selected.protocol_modified} onChange={(event) => updateItem({ protocol_modified: event.target.checked })} /><span>本方案对原量表回忆期、填写频率、措辞或版式有修改，需单独核实</span></label><label><input type="checkbox" checked={selected.source_synopsis_only} onChange={(event) => updateItem({ source_synopsis_only: event.target.checked })} /><span>当前仅有方案摘要信息，完整版本/题项待后续方案核对</span></label><button type="button" className={selected.confirmation_status === "confirmed" ? "confirmed" : ""} onClick={() => updateItem({ confirmation_status: selected.confirmation_status === "confirmed" ? "needs_review" : "confirmed", confirmed_by: selected.confirmation_status === "confirmed" ? "" : "medical_manager", confirmed_at: selected.confirmation_status === "confirmed" ? null : new Date().toISOString() })}>{selected.confirmation_status === "confirmed" ? <CheckCircle2 size={14} /> : <ShieldAlert size={14} />}{selected.confirmation_status === "confirmed" ? "医学经理已确认本项目用法" : "确认本项目用法"}</button></div>
 </div>}
 </div>}
 </section>;
}

const ASSEMBLY_PLAN_BLOCKER_LABELS = Object.freeze({
 "intervention.active_comparator_regimen": "活动对照的具体方案",
 "intervention.background_treatment": "背景治疗规则",
 "intervention.investigational_product_dose_actions": "试验药物剂量调整规则",
 "intervention.investigational_product_regimen": "试验药物给药方案",
 "intervention.permitted_concomitant_treatment": "允许的合并治疗",
 "intervention.placebo_regimen": "安慰剂给药方案",
 "intervention.prohibited_concomitant_treatment": "禁止的合并治疗",
 "intervention.rescue_treatment": "救援治疗规则",
});

function CorpusGate({ projectId, journey, setJourney, selectedBriefIds, setSelectedBriefIds, searchMessage, busy, onSearch, acknowledged, setAcknowledged, overrideReason, setOverrideReason, allAcknowledged, onOverride, onCreateDocument, onReviewAssemblyPlan, readOnly = false, existingDocument = false }) {
 const [assemblyPlanState, setAssemblyPlanState] = useState({ status: "loading", payload: null, error: "" });
 const assemblyPlanRefreshAttemptRef = useRef("");
 const gate = journey?.corpus_gate; const searchPlan = journey?.search_plan; const missing = gate?.missing_requirements || []; const allowed = Boolean(gate?.access_permitted);
 const ready = gate?.readiness_status === "ready";
 const gateStatusClass = ready ? "allowed" : allowed ? "exception" : "blocked";
 const assemblyPayload = assemblyPlanState.payload || {};
 const assemblyPlan = assemblyPayload.plan || null;
 const assemblyPlanReady = Boolean(
 assemblyPayload.available
 && assemblyPayload.source_current
 && assemblyPayload.confirmation_current
 && assemblyPayload.deterministic_projection_allowed,
 );
 const studyDefinitionBound = Boolean(
 journey?.study_definition?.definition_id
 && journey?.study_definition?.revision
 && journey?.study_definition?.state_sha256,
 );
 const assemblyPlanBlockers = (assemblyPlan?.modules || []).flatMap((module) => (module.unresolved_questions || []).map((question) => ({
 code: question.code || module.module_id,
 label: ASSEMBLY_PLAN_BLOCKER_LABELS[module.module_id] || ASSEMBLY_PLAN_BLOCKER_LABELS[question.code] || question.prompt || module.module_id,
 })));
 const gateStatusText = ready && assemblyPlanReady
 ? "语料与方案结构均已核对"
 : ready
 ? "语料已就绪 · 仍需核对方案结构"
 : allowed
 ? "例外放行 · 语料未就绪"
 : "当前阻断写作";

 useEffect(() => {
 const definition = journey?.study_definition;
 if (!definition?.definition_id || !definition.revision || !definition.state_sha256) {
 setAssemblyPlanState({ status: "missing-definition", payload: null, error: "研究定义尚未完成版本绑定" });
 return undefined;
 }
 const controller = new AbortController();
 let cancelled = false;
 const definitionKey = `${definition.definition_id}:${definition.revision}:${definition.state_sha256}`;
 const readPlan = async () => {
 try {
 const payload = await fetch(`/api/projects/${projectId}/medical-writing/protocol-assembly-plan`, { signal: controller.signal }).then(readJson);
 if (cancelled) return;
 if (payload.available && payload.source_current) {
 setAssemblyPlanState({ status: "ready", payload, error: "" });
 return;
 }
 const planRevision = payload.plan?.revision || 0;
 const refreshKey = `${projectId}:${definitionKey}:${planRevision}`;
 if (readOnly || assemblyPlanRefreshAttemptRef.current === refreshKey) {
 setAssemblyPlanState({ status: payload.available ? "stale" : "missing", payload, error: payload.stale_reason || "方案组装计划尚未生成" });
 return;
 }
 assemblyPlanRefreshAttemptRef.current = refreshKey;
 setAssemblyPlanState({ status: "refreshing", payload, error: "正在自动核对方案结构完整性" });
 await fetch(`/api/projects/${projectId}/medical-writing/protocol-assembly-plan/refresh`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 signal: controller.signal,
 body: JSON.stringify({
 expected_plan_revision: planRevision,
 expected_source_definition_id: definition.definition_id,
 expected_source_definition_revision: definition.revision,
 expected_source_definition_sha256: definition.state_sha256,
 actor: "medical_manager",
 idempotency_key: `authoring-assembly-plan-refresh-${projectId}-${definitionKey}`.slice(0, 200),
 }),
 }).then(readJson);
 const refreshed = await fetch(`/api/projects/${projectId}/medical-writing/protocol-assembly-plan`, { signal: controller.signal }).then(readJson);
 if (!cancelled) setAssemblyPlanState({ status: refreshed.available ? "ready" : "missing", payload: refreshed, error: refreshed.stale_reason || "" });
 } catch (error) {
 if (cancelled || error.name === "AbortError") return;
 if (error.status === 404) {
 setAssemblyPlanState({ status: "missing", payload: { available: false }, error: "方案组装计划尚未生成" });
 } else {
 setAssemblyPlanState({ status: "error", payload: null, error: "暂时无法核对方案结构，请稍后重试" });
 }
 }
 };
 readPlan();
 return () => { cancelled = true; controller.abort(); };
 }, [projectId, journey?.revision, journey?.study_definition?.definition_id, journey?.study_definition?.revision, journey?.study_definition?.state_sha256, readOnly]);

 // A documented corpus exception is an explicit, auditable writing route;
 // it must not be rendered as permanently disabled merely because the full
 // evidence gate is not ready. The backend still requires a complete,
 // version-bound StudyDefinition, so keep that binding as the only local
 // prerequisite for this exception path. The normal ready path retains the
 // stricter assembly-plan check.
 const writeEntryReady = allowed
 && (ready ? assemblyPlanReady : studyDefinitionBound);
 const assemblyPlanMessage = assemblyPlanState.status === "loading" || assemblyPlanState.status === "refreshing"
 ? "系统正在自动核对方案结构完整性，您无需填写技术表单。"
 : assemblyPlanReady
 ? "方案结构已完成版本绑定，可建立版本化方案工作稿。"
 : assemblyPlanBlockers.length
 ? `还需确认：${assemblyPlanBlockers.slice(0, 3).map((item) => item.label).join("、")}${assemblyPlanBlockers.length > 3 ? `等${assemblyPlanBlockers.length}项` : ""}。`
 : assemblyPlanState.error || "方案结构尚未完成核对，暂不能建立工作稿。";
 const persistedSearchMessage = searchPlan?.latest_snapshot_id ? `最近一次公开检索已记录：${searchPlan.returned_count}项公开研究，${searchPlan.public_document_count}份公开Protocol；结果编号 ${searchPlan.latest_snapshot_id}。` : "";
 const searchContractIncomplete = Boolean(searchPlan && !searchPlan.registry_filter);
 const registryFilter = searchPlan?.registry_filter || {};
 const triageCriteria = searchPlan?.triage_criteria || [];
 const registryFilterRows = [
 ["疾病/适应症", registryFilter.condition_term],
 ["研究分期", (registryFilter.phases || []).join("、")],
 ["研究类型", registryFilter.study_type],
 ["干预名称", (registryFilter.intervention_terms || []).join("、") || "不限"],
 ["研究地区", (registryFilter.regions || []).join("、") || "不限"],
 ];
 return (
 <section className="authoring-corpus-stage">
 <header><div><strong>语料准备与写作准入</strong><span>公开竞品原文、监管中文语料和项目设计事实共同决定章节可写性</span></div><span className={`authoring-gate-status ${gateStatusClass}`}>{gateStatusText}</span></header>
 <div className="authoring-search-plan">
 <div><Search size={17} /><span><strong>ClinicalTrials.gov竞品检索计划</strong><small>先按注册库条件宽检索，再由医学经理按项目设计线索分诊相关研究。</small></span></div>
 <button
 type="button"
 onClick={onSearch}
 disabled={readOnly || busy === "search" || searchContractIncomplete}
 title={
 searchContractIncomplete
 ? "检索条件不完整，请刷新页面后重试"
 : searchPlan?.latest_snapshot_id && (searchPlan?.returned_count || 0) > 0
 ? "已有检索结果；再次点击将按当前条件重新检索并覆盖上一批结果"
 : searchPlan?.latest_snapshot_id && (searchPlan?.returned_count || 0) === 0
 ? "上次检索未找到公开研究；可修正适应症英文检索词后重新检索"
 : "向 ClinicalTrials.gov 发起公开竞品检索"
 }
 >
 <RefreshCw size={14} />
 {" "}
 {busy === "search"
 ? "检索中…"
 : searchPlan?.latest_snapshot_id
 ? ((searchPlan?.returned_count || 0) > 0 ? "重新检索竞品" : "未找到结果，重新检索")
 : "执行公开竞品检索"}
 </button>
 <div className="authoring-search-contract">
 <section aria-label="实际注册库过滤条件">
 <strong>实际发送到注册库的条件</strong>
 <dl>{registryFilterRows.map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value || "待确认"}</dd></div>)}</dl>
 </section>
 <section aria-label="检索后医学分诊条件">
 <strong>检索后医学分诊线索</strong>
 {triageCriteria.length ? <ul>{triageCriteria.map((item) => <li key={item.criterion_id}><b>{item.label}</b><span>{item.value}</span></li>)}</ul> : <p>尚未形成靶点、研究目的或设计分诊线索。</p>}
 </section>
 </div>
 {searchContractIncomplete && <p className="authoring-search-contract-error" role="alert">检索合同版本过旧，请刷新页面后重试；系统不会按前端推测条件发起注册库检索。</p>}
 {(searchMessage || persistedSearchMessage) && <p>{searchMessage || persistedSearchMessage}</p>}
 </div>
 {searchPlan?.latest_snapshot_id && <WritingReferencePanel projectId={projectId} variant="authoring" snapshotId={searchPlan.latest_snapshot_id} lockedIndication={searchPlan.registry_filter?.condition_term || journey.framing?.clinicaltrials_condition_term || journey.framing?.indication || ""} lockedPhase={journey.framing?.study_phase || ""} journey={journey} onJourneyChange={setJourney} selectedBriefIds={selectedBriefIds} onSelectedBriefIdsChange={setSelectedBriefIds} />}
 <div className="authoring-gate-checklist"><strong>{missing.length ? "尚未满足的准入条件" : "准入条件已满足"}</strong>{(gate?.requirements?.length ? gate.requirements : missing.map((label) => ({ label, satisfied: false, detail: "" }))).map((item) => <label key={item.label} className={item.satisfied ? "satisfied" : ""}><input type="checkbox" checked={item.satisfied || acknowledged.includes(item.label)} onChange={() => { if (item.satisfied) return; setAcknowledged((current) => current.includes(item.label) ? current.filter((value) => value !== item.label) : [...current, item.label]); }} disabled={readOnly || allowed || item.satisfied} /><span><b>{item.label}</b>{item.detail && <small>{item.detail}</small>}</span></label>)}</div>
 {readOnly ? <div className="authoring-writing-entry"><div>{ready && assemblyPlanReady ? <CheckCircle2 size={18} /> : <ShieldAlert size={18} />}<span><strong>{ready && assemblyPlanReady ? "当前文档基于已核对语料与方案结构建立" : allowed ? "当前文档基于已记录的准入状态建立" : "当前语料门未满足"}</strong><small>此处仅回看文档创建所依据的设计、方案结构与语料状态；调整需进入受控变更流程。</small></span></div></div> : existingDocument ? <div className="authoring-writing-entry"><div>{ready && assemblyPlanReady ? <CheckCircle2 size={18} /> : <ShieldAlert size={18} />}<span><strong>当前写作文档已建立</strong><small>研究设计变更提交后，返回编辑器完成受影响章节的重绑定、重新核对与审阅。</small></span></div></div> : !allowed ? <details className="authoring-override"><summary>在保留全部缺口的情况下例外进入写作</summary><p className="quiet-text">仅在项目确需先行建稿时使用。逐项确认上方全部缺口，并填写项目特异的例外理由；系统不会自动代替您确认。</p><label className="synopsis-override-reason"><span>例外理由</span><textarea rows={2} value={overrideReason} onChange={(event) => setOverrideReason(event.target.value)} placeholder="说明当前为何需要例外进入写作，以及后续如何补齐语料；不少于10个字符。" /></label><button className="primary-button" type="button" onClick={onOverride} disabled={busy === "override" || !allAcknowledged || overrideReason.trim().length < 10} title={!allAcknowledged ? "请先逐项确认全部缺口" : overrideReason.trim().length < 10 ? "请填写不少于10个字符的项目特异理由" : "记录例外并进入写作"}><ShieldAlert size={14} /> {busy === "override" ? "记录中" : "确认例外并放行"}</button></details> : <div className="authoring-writing-entry"><div>{writeEntryReady ? <CheckCircle2 size={18} /> : <ShieldAlert size={18} />}<span><strong>{writeEntryReady ? (ready ? "语料与方案结构均已就绪" : "已记录例外，可建立版本化方案工作稿") : ready ? "语料已就绪，仍需完成方案结构核对" : "例外已记录，但研究定义尚未完成版本绑定"}</strong><small>{writeEntryReady ? (ready ? "可以建立版本化方案工作稿。" : "已明确缺少公开语料；正式稿仍须以当前版本化研究定义为唯一事实来源。") : ready ? assemblyPlanMessage : "先完成两阶段研究定义的版本绑定；语料缺口和例外理由会持续保留并纳入审计链。"}</small></span></div>{ready && !assemblyPlanReady && onReviewAssemblyPlan && <button className="secondary-button" type="button" onClick={onReviewAssemblyPlan} disabled={assemblyPlanState.status === "loading" || assemblyPlanState.status === "refreshing"}><PenLine size={14} /> 查看待确认项</button>}<button className="primary-button" type="button" onClick={onCreateDocument} disabled={!writeEntryReady || busy === "create-document"} title={!writeEntryReady ? (ready ? assemblyPlanMessage : "请先完成两阶段研究定义版本绑定") : ready ? "建立版本化方案工作稿" : "在已记录例外的审计状态下建立版本化方案工作稿"}><FileText size={15} /> {busy === "create-document" ? "建立中" : writeEntryReady ? "进入写作平台" : ready ? "完成核对后进入写作" : "完成研究定义后进入写作"}</button></div>}
 </section>
 );
}

function Field({ label, required = false, className = "", children }) {
 const control = isValidElement(children)
 ? cloneElement(children, { "aria-required": required || undefined })
 : children;
 return <label className={`authoring-field ${className}`}><span>{label}{required && <b>*</b>}</span>{control}</label>;
}
function ListField({ label, required = false, value, onChange }) { return <Field label={`${label}（每行一项）`} required={required}><textarea rows={5} value={lineText(value)} onChange={(event) => onChange(lines(event.target.value))} /></Field>; }
function StructuredListField({ label, prefix, required = false, className = "", value = [], onChange }) {
 const rows = Array.isArray(value) ? value : [];
 const updateRow = (index, text) => onChange(rows.map((item, itemIndex) => itemIndex === index ? text : item));
 const deleteRow = (index) => onChange(rows.filter((_item, itemIndex) => itemIndex !== index));
 const addRow = () => onChange([...rows, ""]);
 return (
 <fieldset className={`authoring-structured-list ${className}`}>
 <legend>{label}{required && <b>*</b>}</legend>
 <div className="authoring-structured-list-rows">
 {rows.map((item, index) => (
 <div className="authoring-structured-list-row" key={`${prefix}-${index}`}>
 <span>{prefix}-{String(index + 1).padStart(2, "0")}</span>
 <textarea
 rows={2}
 aria-label={`${label} ${index + 1}`}
 value={item}
 onChange={(event) => updateRow(index, event.target.value)}
 placeholder={`填写${label}的具体条件、阈值、时间窗或例外`}
 />
 <button type="button" className="icon-button" onClick={() => deleteRow(index)} title={`删除 ${prefix}-${String(index + 1).padStart(2, "0")}`}>
 <Trash2 size={14} />
 </button>
 </div>
 ))}
 {!rows.length && <p>尚未建立规则。新增后将按 {prefix}-01 起连续编号，保存时写回统一PICOS事实。</p>}
 </div>
 <button type="button" className="authoring-structured-list-add" onClick={addRow}><Plus size={14} /> 新增{label}</button>
 </fieldset>
 );
}
function ApplicabilitySummary({ label, decision }) { return <div className="authoring-applicability-summary"><span><strong>{label}</strong><small>不适用</small></span><p>{decision?.reason || "尚未填写理由"}</p><span>{decision?.confirmed_by_medical_manager ? <CheckCircle2 size={14} /> : <ShieldAlert size={14} />}{decision?.confirmed_by_medical_manager ? "医学经理已确认" : "尚待医学经理确认"}</span></div>; }

function FactProposalCard({ proposal, decision, onAdopt, onEdit, onReject, busy }) {
 const [editing, setEditing] = useState(false);
 const [editedValue, setEditedValue] = useState(proposal.value || "");
 const evidenceKind = proposal.fact_kind || proposal.evidence_status || "unknown";
 const evidenceLabel = EVIDENCE_STATUS_LABELS[evidenceKind] || EVIDENCE_STATUS_LABELS.unknown;
 const confidenceLabel = CONFIDENCE_LABELS[proposal.confidence] || CONFIDENCE_LABELS.unknown;
 const effectiveDecision = decision || (proposal.decision !== "pending" ? proposal.decision : "");
 const decided = Boolean(effectiveDecision);
 const tone = proposal.field_path?.startsWith("high_impact_missing.")
 ? "gap"
 : evidenceKind === "conflict"
 ? "conflict"
 : evidenceKind === "unknown"
 ? "unknown"
 : evidenceKind === "ai_inferred"
 ? "inference"
 : "fact";
 return (
 <article className={`authoring-fact-proposal ${tone} ${decided ? "decided" : ""}`}>
 <div className="authoring-fact-proposal-head">
 <span className="authoring-fact-proposal-field" title={proposal.field_path}>{proposal.field_label || factFieldLabel(proposal.field_path)}</span>
 <span className={`authoring-fact-proposal-evidence ${evidenceKind}`}>{evidenceLabel} · 置信{confidenceLabel}</span>
 </div>
 {editing ? (
 <div className="authoring-fact-proposal-edit">
 <textarea rows={2} value={editedValue} onChange={(event) => setEditedValue(event.target.value)} placeholder="修订后的事实值；确认采用后写入版本化研究事实" />
 <div className="authoring-fact-proposal-edit-actions">
 <button type="button" onClick={() => { onEdit(editedValue); setEditing(false); }} disabled={busy}>采用修订</button>
 <button type="button" onClick={() => { setEditing(false); setEditedValue(proposal.value || ""); }}>取消</button>
 </div>
 </div>
 ) : (
 <p className="authoring-fact-proposal-value">{proposal.value || "尚无具体值；需项目资料或用户确认"}</p>
 )}
 {(proposal.rationale || proposal.source_summary) && <small className="authoring-fact-proposal-source">{proposal.rationale || proposal.source_summary}</small>}
 {proposal.conflict_note && <small className="authoring-fact-proposal-conflict">冲突：{proposal.conflict_note}</small>}
 {!editing && (
 <div className="authoring-fact-proposal-actions">
 <button type="button" className={effectiveDecision === "adopted" ? "decided" : ""} onClick={onAdopt} disabled={busy || decided} title="采用该事实并写入研究框架">{effectiveDecision === "adopted" ? <><CheckCircle2 size={13} /> 已采用</> : "采用"}</button>
 <button type="button" className={effectiveDecision === "edited" ? "decided" : ""} onClick={() => setEditing(true)} disabled={busy || decided} title="修订后采用">{effectiveDecision === "edited" ? <><PenLine size={13} /> 已修订</> : "修订"}</button>
 <button type="button" className={effectiveDecision === "rejected" ? "decided" : ""} onClick={onReject} disabled={busy || decided} title="拒绝该建议">{effectiveDecision === "rejected" ? <><XCircle size={13} /> 已拒绝</> : "拒绝"}</button>
 </div>
 )}
 </article>
 );
}

function ConversationalFactIntake({ factConversation, setFactConversation, onSubmit, onApplyProposal, busy, interactionLocked }) {
 const turns = factConversation.turns || [];
 const pendingInput = factConversation.pendingInput || "";
 const pendingTurnId = factConversation.pendingTurnId || "";
 const disabled = interactionLocked || busy === "fact-turn";
 const setInput = (value) => setFactConversation((current) => ({ ...current, pendingInput: value }));
 const submit = () => { if (pendingInput.trim()) onSubmit(); };
 const hasProposals = turns.some((turn) => turn.ai_response?.proposals?.length);
 return (
 <section className="authoring-conversation" aria-label="对话式事实采集">
 <header>
 <div>
 <Sparkles size={16} />
 <div>
 <strong>补充产品事实（自然语言）</strong>
 <span>可粘贴大段文字、药学资料摘要或临床前结论；独立AI拆解为可确认事实、推断、未知项、冲突和高影响缺口，每轮最多追问3个影响下游设计的问题。</span>
 </div>
 </div>
 <small>IB可选·缺少不阻断调研</small>
 </header>
 <div className="authoring-conversation-input">
 <textarea
 rows={4}
 value={pendingInput}
 onChange={(event) => setInput(event.target.value)}
 placeholder="例如：CMS-D1是抗IL-23p19单抗，静脉输注，首次人体，已有食蟹猴4周毒理，NOAEL 30mg/kg，暂无人体PK数据，关注输注反应和免疫原性。"
 disabled={disabled}
 aria-label="自然语言事实输入"
 />
 <button type="button" className="primary-button" onClick={submit} disabled={disabled || !pendingInput.trim()}>
 <Sparkles size={14} /> {busy === "fact-turn" ? "解析中" : "提交并拆解"}
 </button>
 </div>
 {turns.length === 0 ? (
 <p className="authoring-conversation-empty">尚未发起事实采集。无IB不阻断竞品调研；当前目标产品事实仅采用用户输入或已绑定来源，竞品信息不会自动写成本品事实。此处补充的自然语言会合并进入版本化事实。</p>
 ) : (
 <div className="authoring-conversation-turns">
 {turns.map((turn, turnIndex) => {
 const proposals = turn.ai_response?.proposals || [];
 const questions = turn.ai_response?.questions || [];
 const gaps = turn.ai_response?.high_impact_gaps || [];
 return (
 <div key={turn.turn_id || turnIndex} className="authoring-conversation-turn">
 <div className="authoring-conversation-user">
 <small>用户输入 · 第{turnIndex + 1}轮</small>
 <p>{turn.user_message}</p>
 </div>
 <div className="authoring-conversation-ai">
 <small>AI拆解 · 待用户确认</small>
 {turn.ai_response?.response_text && <p className="authoring-conversation-response">{turn.ai_response.response_text}</p>}
 {proposals.length > 0 && (
 <div className="authoring-fact-proposals">
 {proposals.map((proposal) => (
 <FactProposalCard
 key={proposal.proposal_id}
 proposal={proposal}
 decision={turn.decisions?.[proposal.proposal_id]}
 onAdopt={() => onApplyProposal(turn.turn_id || pendingTurnId, proposal.proposal_id, "adopted")}
 onEdit={(value) => onApplyProposal(turn.turn_id || pendingTurnId, proposal.proposal_id, "edited", value)}
 onReject={() => onApplyProposal(turn.turn_id || pendingTurnId, proposal.proposal_id, "rejected")}
 busy={busy === `fact-apply-${proposal.proposal_id}`}
 />
 ))}
 </div>
 )}
 {gaps.length > 0 && (
 <div className="authoring-conversation-gaps">
 <strong>高影响缺口</strong>
 <ul>{gaps.map((gap, gapIndex) => { const fieldPath = typeof gap === "string" ? gap : gap.field_path; return <li key={gapIndex} title={fieldPath}>{typeof gap === "string" ? factGapLabel(gap) : gap.field_label || factGapLabel(fieldPath)}</li>; })}</ul>
 </div>
 )}
 {questions.length > 0 && (
 <div className="authoring-conversation-questions">
 <strong>本轮问题（按下游影响排序）</strong>
 <ol>{questions.map((question, questionIndex) => <li key={questionIndex}>{typeof question === "string" ? question : question.text}</li>)}</ol>
 </div>
 )}
 {proposals.length === 0 && gaps.length === 0 && questions.length === 0 && (
 <p className="authoring-conversation-no-findings">本次未识别到新的可确认事实或必须追问项；可在下方继续补充。</p>
 )}
 </div>
 </div>
 );
 })}
 </div>
 )}
 {hasProposals && <p className="authoring-conversation-hint">采用或修订后立即写入本项目确认事实，不再进入第二次批准。</p>}
 </section>
 );
}

import { useEffect, useMemo, useRef, useState } from "react";
import {
 AlertTriangle,
 BookPlus,
 CheckCircle2,
 ExternalLink,
 RefreshCw,
 Search,
} from "lucide-react";


function requestKey(prefix) {
 const suffix = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random()}`;
 return `${prefix}-${suffix}`;
}


async function readJson(response) {
 const payload = await response.json().catch(() => ({}));
 if (response.ok) return payload;
 const error = new Error(typeof payload.detail === "string" ? payload.detail : `HTTP ${response.status}`);
 error.status = response.status;
 throw error;
}


function validationLabel(status) {
 return {
 confirmed: ["信息完整", "success"],
 needs_review: ["信息待补", "warning"],
 overridden: ["医学确认", "info"],
 }[status] || ["待确认", "warning"];
}


function referenceAuthorYear(reference) {
 const author = reference.authors?.[0] || "作者待补";
 return `${author}${reference.authors?.length > 1 ? " 等" : ""} · ${reference.year || "年份待补"}`;
}


export function MedicalWritingLiteraturePanel({ projectId, onInsertReference = () => {} }) {
 const activeProjectRef = useRef(projectId);
 const [library, setLibrary] = useState(null);
 const [sourceInput, setSourceInput] = useState("");
 const [query, setQuery] = useState("");
 const [busy, setBusy] = useState("");
 const [message, setMessage] = useState("");
 const [manualMetadata, setManualMetadata] = useState({
 title: "",
 authors: "",
 journal: "",
 year: "",
 url: "",
 });
 const [overrideReason, setOverrideReason] = useState("");

 const refresh = async ({ preserveMessage = false } = {}) => {
 const requestedProject = projectId;
 setBusy((current) => current || "refresh");
 if (!preserveMessage) setMessage("");
 try {
 const payload = await fetch(`/api/projects/${projectId}/medical-writing/literature`).then(readJson);
 if (activeProjectRef.current !== requestedProject) return;
 setLibrary(payload);
 } catch (error) {
 if (activeProjectRef.current === requestedProject) setMessage(`文献库读取失败：${error.message}`);
 } finally {
 if (activeProjectRef.current === requestedProject) setBusy("");
 }
 };

 useEffect(() => {
 activeProjectRef.current = projectId;
 setLibrary(null);
 setSourceInput("");
 setQuery("");
 setMessage("");
 setManualMetadata({ title: "", authors: "", journal: "", year: "", url: "" });
 setOverrideReason("");
 refresh();
 }, [projectId]);

 const references = library?.references || [];
 const visibleReferences = useMemo(() => {
 const needle = query.trim().toLowerCase();
 if (!needle) return references;
 return references.filter((reference) => [
 reference.title,
 reference.journal,
 reference.year,
 reference.doi,
 reference.pmid,
 ...(reference.authors || []),
 ].some((value) => String(value || "").toLowerCase().includes(needle)));
 }, [references, query]);

 const importReference = async ({ override = false } = {}) => {
 if (!sourceInput.trim()) return;
 const requestedProject = projectId;
 setBusy(override ? "override" : "import");
 setMessage("");
 try {
 const payload = await fetch(`/api/projects/${projectId}/medical-writing/literature/imports`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 source_input: sourceInput.trim(),
 manual_metadata: override ? {
 ...manualMetadata,
 authors: manualMetadata.authors.split(/[，,;；]/).map((item) => item.trim()).filter(Boolean),
 } : null,
 override_validation: override,
 override_reason: override ? overrideReason.trim() : "",
 actor: "medical_manager",
 idempotency_key: requestKey(override ? "literature-override" : "literature-import"),
 }),
 }).then(readJson);
 if (activeProjectRef.current !== requestedProject) return;
 setMessage(payload.created
 ? "文献已加入当前项目文献库。"
 : `已与现有文献合并（按${payload.matched_on.toUpperCase()}识别）。`);
 setSourceInput("");
 setManualMetadata({ title: "", authors: "", journal: "", year: "", url: "" });
 setOverrideReason("");
 await refresh({ preserveMessage: true });
 } catch (error) {
 if (activeProjectRef.current === requestedProject) setMessage(`文献导入失败：${error.message}`);
 } finally {
 if (activeProjectRef.current === requestedProject) setBusy("");
 }
 };

 const canOverride = sourceInput.trim()
 && manualMetadata.title.trim()
 && overrideReason.trim().length >= 10;

 return (
 <section className="medical-literature-panel" aria-label="项目文献库">
 <header>
 <div>
 <span>项目文献库</span>
 <strong>{references.length} 条可追溯文献</strong>
 </div>
 <button className="icon-button" onClick={() => refresh()} disabled={Boolean(busy)} title="刷新项目文献库">
 <RefreshCw size={16} />
 </button>
 </header>

 <div className="medical-literature-import">
 <label>
 DOI、PMID 或文献官网链接
 <div>
 <input value={sourceInput} onChange={(event) => setSourceInput(event.target.value)} placeholder="例如 10.1016/... 或 PMID: 33957195" />
 <button className="primary-button" onClick={() => importReference()} disabled={Boolean(busy) || !sourceInput.trim()}>
 <BookPlus size={15} /> {busy === "import" ? "读取中" : "导入"}
 </button>
 </div>
 </label>
 <label>
 当前项目引文格式
 <select value="gbt_7714_2015_numeric" disabled title="当前生产导出固定使用 GB/T 7714-2015 顺序编码制">
 <option value="gbt_7714_2015_numeric">GB/T 7714-2015 顺序编码制</option>
 </select>
 </label>
 <details>
 <summary>官网链接无法自动识别时，手动确认基本信息</summary>
 <div className="medical-literature-manual-grid">
 <label>题名<input value={manualMetadata.title} onChange={(event) => setManualMetadata((current) => ({ ...current, title: event.target.value }))} /></label>
 <label>作者<input value={manualMetadata.authors} onChange={(event) => setManualMetadata((current) => ({ ...current, authors: event.target.value }))} placeholder="多位作者用逗号分隔" /></label>
 <label>期刊<input value={manualMetadata.journal} onChange={(event) => setManualMetadata((current) => ({ ...current, journal: event.target.value }))} /></label>
 <label>年份<input value={manualMetadata.year} onChange={(event) => setManualMetadata((current) => ({ ...current, year: event.target.value }))} /></label>
 <label className="span-2">文献官网链接<input value={manualMetadata.url} onChange={(event) => setManualMetadata((current) => ({ ...current, url: event.target.value }))} /></label>
 <label className="span-2">医学确认理由<textarea value={overrideReason} onChange={(event) => setOverrideReason(event.target.value)} placeholder="说明已核对的原始页面及确认依据，至少10个字" /></label>
 </div>
 <button onClick={() => importReference({ override: true })} disabled={Boolean(busy) || !canOverride}>确认信息并导入</button>
 </details>
 </div>

 {message && <p className={`medical-literature-message ${message.includes("失败") ? "danger" : ""}`}>{message}</p>}

 <label className="medical-literature-search">
 <Search size={15} />
 <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="按题名、作者、期刊、DOI 或 PMID 搜索" />
 </label>

 <div className="medical-literature-list">
 {visibleReferences.map((reference) => {
 const [label, tone] = validationLabel(reference.validation_status);
 const citable = reference.validation_status !== "needs_review";
 return (
 <article key={reference.reference_id}>
 <header>
 <span className={`tag ${tone}`}>{label}</span>
 <span>{referenceAuthorYear(reference)}</span>
 </header>
 <strong>{reference.title}</strong>
 <p>{[reference.journal, reference.volume, reference.issue, reference.pages].filter(Boolean).join(" · ")}</p>
 <footer>
 <span>{reference.doi ? `DOI ${reference.doi}` : reference.pmid ? `PMID ${reference.pmid}` : "官网元数据"}</span>
 <div>
 {reference.url && <a href={reference.url} target="_blank" rel="noreferrer" title="打开文献来源"><ExternalLink size={14} /></a>}
 <button
 onClick={() => {
 const insertionMessage = onInsertReference(reference);
 if (insertionMessage) setMessage(insertionMessage);
 }}
 disabled={!citable}
 title={citable ? "在当前光标处插入引文" : "请先补全或医学确认缺失元数据"}
 >
 {citable ? <CheckCircle2 size={14} /> : <AlertTriangle size={14} />} 插入引文
 </button>
 </div>
 </footer>
 {reference.validation_warnings?.length > 0 && <small>{reference.validation_warnings.join("；")}</small>}
 </article>
 );
 })}
 {!visibleReferences.length && <div className="empty-state">当前项目尚无匹配文献。</div>}
 </div>
 </section>
 );
}

import { CheckCircle2, RefreshCw, ShieldAlert, X } from "lucide-react";

const PAGE_COUNT_BASIS_LABELS = Object.freeze({
 style_profile_estimate: "快速估算",
 microsoft_word_receipt: "Word已核验",
});

const PREVIEW_STATUS_LABELS = Object.freeze({
 fast_preview: "快速分页预览",
 word_verified: "Microsoft Word/PDF核验",
 stale: "核验已过期",
});

export function previewPageCountBasisLabel(basis) {
 return PAGE_COUNT_BASIS_LABELS[basis] || "待确认来源";
}

export function previewStatusLabel(status) {
 return PREVIEW_STATUS_LABELS[status] || "版式状态待确认";
}

export function previewPageSummary(page) {
 const sections = Array.isArray(page?.section_ids) ? page.section_ids.length : 0;
 const blocks = Array.isArray(page?.block_ids) ? page.block_ids.length : 0;
 return `${sections}个章节 · ${blocks}个内容块`;
}

function previewTone(preview) {
 if (preview?.page_count_basis === "microsoft_word_receipt") return "verified";
 if (preview?.preview_status === "stale") return "stale";
 return "estimated";
}

export function MedicalWritingPreviewPanel({
 preview,
 busy = false,
 message = "",
 onRefresh,
 onClose,
}) {
 if (!preview) return null;
 const tone = previewTone(preview);
 const pages = Array.isArray(preview.pages) ? preview.pages : [];
 const visiblePages = pages.slice(0, 8);
 const hiddenPageCount = Math.max(0, pages.length - visiblePages.length);
 const isVerified = preview.page_count_basis === "microsoft_word_receipt";
 const statusDescription = isVerified
 ? "当前页数来自同一方案快照的 Microsoft Word/PDF 核验，可作为最终版式依据。"
 : "当前页数是同一方案快照的快速估算，不等同于 Word 最终页数；封面、目录、表格跨页和版式节可能造成差异。";

 return (
 <section className={`medical-writing-preview-panel ${tone}`} aria-label="方案版式预览状态">
 <div className="medical-writing-preview-panel-header">
 <div>
 <span className="medical-writing-preview-eyebrow">版式状态</span>
 <strong>{previewStatusLabel(preview.preview_status)}</strong>
 </div>
 <div className="medical-writing-preview-panel-actions">
 <button type="button" onClick={onRefresh} disabled={busy} title="重新读取当前方案快照的版式状态">
 <RefreshCw size={13} /> {busy ? "读取中" : "刷新"}
 </button>
 <button type="button" className="medical-writing-preview-close" onClick={onClose} title="关闭版式状态面板" aria-label="关闭版式状态面板">
 <X size={14} />
 </button>
 </div>
 </div>
 <div className="medical-writing-preview-summary">
 <div className="medical-writing-preview-page-count">
 {isVerified ? <CheckCircle2 size={17} /> : <ShieldAlert size={17} />}
 <span><strong>{preview.page_count}页</strong><small>{previewPageCountBasisLabel(preview.page_count_basis)}</small></span>
 </div>
 <p>{statusDescription}</p>
 </div>
 {preview.warning && <p className="medical-writing-preview-warning">{preview.warning}</p>}
 {message && <p className="medical-writing-preview-message" role="alert">{message}</p>}
 <div className="medical-writing-preview-meta">
 <span>快照 <code>{String(preview.snapshot_sha256 || "").slice(0, 12) || "待生成"}…</code></span>
 <span>{preview.style_profile_id || "StyleProfile待确认"}</span>
 </div>
 {visiblePages.length > 0 && (
 <ol className="medical-writing-preview-pages" aria-label="方案页状态">
 {visiblePages.map((page) => (
 <li key={page.page_number}>
 <span>第{page.page_number}页</span>
 <small>{previewPageSummary(page)}</small>
 </li>
 ))}
 </ol>
 )}
 {hiddenPageCount > 0 && <p className="medical-writing-preview-more">其余 {hiddenPageCount} 页已折叠；需要最终页数请以 Word 核验为准。</p>}
 </section>
 );
}


import { describe, expect, it } from "vitest";

import {
 previewPageCountBasisLabel,
 previewPageSummary,
 previewStatusLabel,
} from "./MedicalWritingPreviewPanel";

describe("medical writing preview truth boundary", () => {
 it("keeps the estimate and Word receipt labels distinct", () => {
 expect(previewPageCountBasisLabel("style_profile_estimate")).toBe("快速估算");
 expect(previewPageCountBasisLabel("microsoft_word_receipt")).toBe("Word已核验");
 expect(previewStatusLabel("fast_preview")).toBe("快速分页预览");
 expect(previewStatusLabel("word_verified")).toBe("Microsoft Word/PDF核验");
 });

 it("summarizes page evidence without assuming every page has locators", () => {
 expect(previewPageSummary({ section_ids: ["s1", "s2"], block_ids: ["b1"] })).toBe("2个章节 · 1个内容块");
 expect(previewPageSummary({})).toBe("0个章节 · 0个内容块");
 });
});


import { useEffect, useMemo, useRef, useState } from "react";
import {
 AlertTriangle,
 CheckCircle2,
 FileText,
 LoaderCircle,
 RotateCcw,
 Upload,
 XCircle,
} from "lucide-react";

const PHASES = ["I期", "I/II期", "II期", "II/III期", "III期"];
const TERMINAL_JOB_STATES = new Set(["review_ready", "failed", "cancelled"]);
const POLL_INTERVAL_MS = 4000;
const POLL_REQUEST_TIMEOUT_MS = 15000;
const COMMAND_REQUEST_TIMEOUT_MS = 30000;
const UPLOAD_REQUEST_TIMEOUT_MS = 120000;
const MAX_CONSECUTIVE_POLL_FAILURES = 3;

export class SynopsisRequestTimeoutError extends Error {
 constructor(message = "请求超时") {
 super(message);
 this.name = "SynopsisRequestTimeoutError";
 }
}

async function readJson(response) {
 const payload = await response.json().catch(() => ({}));
 if (!response.ok) {
 const detail = payload?.detail;
 throw new Error(
 typeof detail === "string"
 ? detail
 : detail
 ? JSON.stringify(detail)
 : `请求失败（${response.status}）`,
 );
 }
 return payload;
}

function isAbortError(error) {
 return error?.name === "AbortError";
}

export async function requestJsonWithTimeout(
 url,
 options = {},
 {
 timeoutMs = COMMAND_REQUEST_TIMEOUT_MS,
 signal,
 fetchImpl = fetch,
 } = {},
) {
 const controller = new AbortController();
 let timedOut = false;
 const abortFromCaller = () => controller.abort();
 if (signal?.aborted) controller.abort();
 else signal?.addEventListener("abort", abortFromCaller, { once: true });
 const timeoutId = setTimeout(() => {
 timedOut = true;
 controller.abort();
 }, timeoutMs);
 try {
 const response = await fetchImpl(url, { ...options, signal: controller.signal });
 return await readJson(response);
 } catch (error) {
 if (timedOut) {
 throw new SynopsisRequestTimeoutError(`请求在 ${Math.ceil(timeoutMs / 1000)} 秒内未响应`);
 }
 throw error;
 } finally {
 clearTimeout(timeoutId);
 signal?.removeEventListener("abort", abortFromCaller);
 }
}

export function synopsisJobState(job) {
 if (TERMINAL_JOB_STATES.has(job?.status)) return job.status;
 if (TERMINAL_JOB_STATES.has(job?.phase)) return job.phase;
 if (job?.status === "recoverable" || job?.phase === "recoverable") return "recoverable";
 return job?.status || job?.phase || "pending";
}

export function synopsisJobMessage(job) {
 const state = synopsisJobState(job);
 if (job?.error_message) return job.error_message;
 if (state === "failed") return "方案摘要解析失败。已完成的解析进度仍会保留，您可以继续处理。";
 if (state === "recoverable") return "方案摘要解析已暂停，已完成的进度仍会保留。";
 if (state === "cancelled") return "本次解析已取消。您可以重新选择文件。";
 return "";
}

function waitForNextPoll(delayMs, signal) {
 return new Promise((resolve, reject) => {
 if (signal?.aborted) {
 reject(new DOMException("Aborted", "AbortError"));
 return;
 }
 const abort = () => {
 clearTimeout(timeoutId);
 reject(new DOMException("Aborted", "AbortError"));
 };
 const timeoutId = setTimeout(() => {
 signal?.removeEventListener("abort", abort);
 resolve();
 }, delayMs);
 signal?.addEventListener("abort", abort, { once: true });
 });
}

export async function pollSynopsisJob(
 started,
 {
 request,
 signal,
 onJob = () => {},
 wait = waitForNextPoll,
 pollIntervalMs = POLL_INTERVAL_MS,
 maxConsecutiveFailures = MAX_CONSECUTIVE_POLL_FAILURES,
 },
) {
 if (["review_ready", "failed", "recoverable", "cancelled"].includes(synopsisJobState(started))) {
 onJob(started);
 return started;
 }
 let consecutiveFailures = 0;
 while (!signal?.aborted) {
 try {
 const current = await request(
 `/api/medical-writing/project-intake/synopsis/${started.intake_id}/jobs/${encodeURIComponent(started.idempotency_key)}`,
 { signal },
 );
 consecutiveFailures = 0;
 onJob(current);
 if (["review_ready", "failed", "recoverable", "cancelled"].includes(synopsisJobState(current))) {
 return current;
 }
 } catch (error) {
 if (isAbortError(error)) throw error;
 consecutiveFailures += 1;
 if (consecutiveFailures >= maxConsecutiveFailures) {
 throw new Error(
 "状态查询连续超时或失败。后台任务仍会保留；您可以重新查询、取消任务或关闭窗口后稍后重试。",
 { cause: error },
 );
 }
 }
 await wait(pollIntervalMs, signal);
 }
 throw new DOMException("Aborted", "AbortError");
}

export async function cancelSynopsisJob(intake, { abortPolling, request, signal }) {
 abortPolling();
 return request(
 `/api/medical-writing/project-intake/synopsis/${intake.intake_id}/jobs/${encodeURIComponent(intake.idempotency_key)}/cancel`,
 { method: "POST", signal },
 );
}

async function fileRequestKey(file) {
 const digest = await crypto.subtle.digest("SHA-256", await file.arrayBuffer());
 const hex = [...new Uint8Array(digest)]
 .map((value) => value.toString(16).padStart(2, "0"))
 .join("");
 return `file-first-synopsis-${hex}`.slice(0, 200);
}

function formatSize(value) {
 if (!Number.isFinite(value)) return "";
 if (value < 1024 * 1024) return `${Math.max(1, Math.round(value / 1024))} KB`;
 return `${(value / 1024 / 1024).toFixed(1)} MB`;
}

function phaseLabel(job) {
 return ({
 uploaded: "文件已接收",
 parsing: "正在解析文档",
 chunking: "正在识别章节",
 ai_synthesis: "AI正在提取研究框架与PICOS",
 validating: "正在核对来源与结构",
 review_ready: "提取完成，待您确认",
 recoverable: "任务可恢复",
 failed: "解析失败",
 cancelled: "已取消",
 })[job?.phase || job?.status] || "准备导入";
}

export function MedicalWritingSynopsisProjectIntake({ disabled = false, onCreated }) {
 const mountedRef = useRef(true);
 const pollGenerationRef = useRef(0);
 const pollControllerRef = useRef(null);
 const commandControllerRef = useRef(null);
 const [file, setFile] = useState(null);
 const [busy, setBusy] = useState("");
 const [message, setMessage] = useState("");
 const [intake, setIntake] = useState(null);
 const [job, setJob] = useState(null);
 const [imported, setImported] = useState(null);
 const [framing, setFraming] = useState(null);
 const [picos, setPicos] = useState(null);
 const [synopsisText, setSynopsisText] = useState("");
 const [acknowledged, setAcknowledged] = useState([]);
 const [overrideReason, setOverrideReason] = useState("");

 useEffect(() => () => {
 mountedRef.current = false;
 pollControllerRef.current?.abort();
 commandControllerRef.current?.abort();
 }, []);

 const warnings = imported?.source?.validation_warnings || [];
 const canConfirm = useMemo(() => Boolean(
 imported?.source?.source_id
 && framing?.investigational_product?.trim()
 && framing?.indication?.trim()
 && framing?.study_phase?.trim()
 && synopsisText.trim()
 && acknowledged.length === warnings.length
 && (!warnings.length || overrideReason.trim().length >= 10)
 ), [acknowledged.length, framing, imported, overrideReason, synopsisText, warnings.length]);

 const reset = () => {
 pollGenerationRef.current += 1;
 pollControllerRef.current?.abort();
 commandControllerRef.current?.abort();
 setFile(null);
 setBusy("");
 setMessage("");
 setIntake(null);
 setJob(null);
 setImported(null);
 setFraming(null);
 setPicos(null);
 setSynopsisText("");
 setAcknowledged([]);
 setOverrideReason("");
 };

 const request = (url, options = {}, timeoutMs = COMMAND_REQUEST_TIMEOUT_MS) => {
 const { signal, ...fetchOptions } = options;
 return requestJsonWithTimeout(url, fetchOptions, { timeoutMs, signal });
 };

 const settleJob = async (current, started, generation, signal) => {
 if (!mountedRef.current || pollGenerationRef.current !== generation) return;
 setJob(current);
 const state = synopsisJobState(current);
 if (state === "review_ready") {
 const result = await request(
 `/api/medical-writing/project-intake/synopsis/${started.intake_id}/jobs/${encodeURIComponent(started.idempotency_key)}/result`,
 { signal },
 );
 if (!mountedRef.current || pollGenerationRef.current !== generation) return;
 setImported(result);
 setFraming(result.proposed_framing);
 setPicos(result.proposed_picos);
 setSynopsisText(result.proposed_synopsis_text || "");
 setMessage("");
 } else {
 setMessage(synopsisJobMessage(current));
 }
 setBusy("");
 };

 const pollJob = async (started, generation) => {
 pollControllerRef.current?.abort();
 const controller = new AbortController();
 pollControllerRef.current = controller;
 const current = await pollSynopsisJob(started, {
 signal: controller.signal,
 request: (url, options) => request(url, options, POLL_REQUEST_TIMEOUT_MS),
 onJob: (nextJob) => {
 if (mountedRef.current && pollGenerationRef.current === generation) setJob(nextJob);
 },
 });
 await settleJob(current, started, generation, controller.signal);
 };

 const start = async () => {
 if (!file || busy) return;
 setBusy("upload");
 setMessage("");
 setImported(null);
 commandControllerRef.current?.abort();
 const controller = new AbortController();
 commandControllerRef.current = controller;
 try {
 const requestKey = await fileRequestKey(file);
 const body = new FormData();
 body.append("file", file);
 body.append("actor", "medical_manager");
 body.append("idempotency_key", requestKey);
 const started = await request(
 "/api/medical-writing/project-intake/synopsis",
 { method: "POST", body, signal: controller.signal },
 UPLOAD_REQUEST_TIMEOUT_MS,
 );
 if (!mountedRef.current) return;
 setIntake(started);
 setJob(started);
 setBusy("processing");
 const generation = pollGenerationRef.current + 1;
 pollGenerationRef.current = generation;
 await pollJob(started, generation);
 } catch (error) {
 if (!mountedRef.current || isAbortError(error)) return;
 setBusy("");
 setMessage(error.message);
 } finally {
 if (commandControllerRef.current === controller) commandControllerRef.current = null;
 }
 };

 const cancel = async () => {
 if (!intake?.intake_id || !intake?.idempotency_key) return;
 const generation = pollGenerationRef.current + 1;
 pollGenerationRef.current = generation;
 setBusy("cancel");
 setMessage("");
 commandControllerRef.current?.abort();
 const controller = new AbortController();
 commandControllerRef.current = controller;
 try {
 const cancelled = await cancelSynopsisJob(intake, {
 abortPolling: () => pollControllerRef.current?.abort(),
 signal: controller.signal,
 request: (url, options) => request(url, options, COMMAND_REQUEST_TIMEOUT_MS),
 });
 if (!mountedRef.current) return;
 setJob(cancelled);
 setMessage(synopsisJobMessage(cancelled));
 } catch (error) {
 if (!mountedRef.current || isAbortError(error)) return;
 setMessage(error.message);
 } finally {
 if (mountedRef.current) setBusy("");
 if (commandControllerRef.current === controller) commandControllerRef.current = null;
 }
 };

 const resume = async () => {
 if (!intake?.intake_id || !intake?.idempotency_key || busy) return;
 pollControllerRef.current?.abort();
 setBusy("processing");
 setMessage("");
 commandControllerRef.current?.abort();
 const controller = new AbortController();
 commandControllerRef.current = controller;
 try {
 const body = new FormData();
 body.append("actor", "medical_manager");
 const resumed = await request(
 `/api/medical-writing/project-intake/synopsis/${intake.intake_id}/jobs/${encodeURIComponent(intake.idempotency_key)}/resume`,
 { method: "POST", body, signal: controller.signal },
 );
 if (!mountedRef.current) return;
 setJob(resumed);
 const generation = pollGenerationRef.current + 1;
 pollGenerationRef.current = generation;
 await pollJob(intake, generation);
 } catch (error) {
 if (!mountedRef.current || isAbortError(error)) return;
 setBusy("");
 setMessage(error.message);
 } finally {
 if (commandControllerRef.current === controller) commandControllerRef.current = null;
 }
 };

 const retryPoll = async () => {
 if (!intake?.intake_id || !intake?.idempotency_key || busy) return;
 setBusy("processing");
 setMessage("");
 const generation = pollGenerationRef.current + 1;
 pollGenerationRef.current = generation;
 try {
 await pollJob(intake, generation);
 } catch (error) {
 if (!mountedRef.current || isAbortError(error)) return;
 setBusy("");
 setMessage(error.message);
 }
 };

 const confirm = async () => {
 if (!canConfirm || busy || !intake) return;
 setBusy("confirm");
 setMessage("");
 commandControllerRef.current?.abort();
 const controller = new AbortController();
 commandControllerRef.current = controller;
 try {
 const payload = await request(
 "/api/medical-writing/project-intake/synopsis/confirm",
 {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 signal: controller.signal,
 body: JSON.stringify({
 intake_id: intake.intake_id,
 import_idempotency_key: intake.idempotency_key,
 source_id: imported.source.source_id,
 framing,
 picos,
 synopsis_text: synopsisText,
 acknowledged_validation_warnings: acknowledged,
 validation_override_reason: overrideReason,
 actor: "medical_manager",
 idempotency_key: `confirm-${intake.intake_id}-${imported.source.content_sha256}`.slice(0, 200),
 }),
 },
 );
 onCreated?.(payload);
 } catch (error) {
 if (!mountedRef.current || isAbortError(error)) return;
 setBusy("");
 setMessage(error.message);
 } finally {
 if (commandControllerRef.current === controller) commandControllerRef.current = null;
 }
 };

 const setFramingField = (field, value) => {
 setFraming((current) => ({ ...current, [field]: value }));
 };
 const setPicosField = (field, value) => {
 setPicos((current) => ({ ...current, [field]: value }));
 };

 if (!imported) {
 const progress = job?.progress;
 const current = progress?.chunk_index || job?.chunk_index || 0;
 const total = progress?.chunk_total || job?.chunk_total || 0;
 const elapsedMinutes = Math.max(0, Math.floor(Number(job?.elapsed_seconds || 0) / 60));
 return (
 <section className="file-first-synopsis-intake">
 <div className="file-first-dropzone">
 <input
 type="file"
 accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document"
 disabled={disabled || Boolean(busy)}
 onChange={(event) => {
 setFile(event.target.files?.[0] || null);
 setMessage("");
 }}
 />
 <FileText size={26} />
 <div>
 <strong>{file?.name || "选择方案摘要或完整方案"}</strong>
 <span>{file ? `${formatSize(file.size)} · PDF / DOCX` : "系统先提取，您确认后才创建正式项目"}</span>
 </div>
 {file && !busy && (
 <button type="button" onClick={start}>
 <Upload size={15} /> 导入并提取
 </button>
 )}
 </div>
 {busy && (
 <div className="file-first-progress" aria-live="polite">
 <LoaderCircle size={18} className="spin" />
 <div>
 <strong>{phaseLabel(job)}</strong>
 <span>
 {total ? `正在处理 ${Math.min(current + 1, total)} / ${total} 个内容块` : "正在准备文档内容"}
 {elapsedMinutes ? ` · 已运行 ${elapsedMinutes} 分钟` : ""}
 </span>
 </div>
 {intake && (
 <button type="button" onClick={cancel} disabled={busy === "cancel"}>
 {busy === "cancel" ? "正在取消" : "取消"}
 </button>
 )}
 </div>
 )}
 {message && (
 <div className="file-first-error" role="alert">
 <AlertTriangle size={17} /><span>{message}</span>
 {intake && ["failed", "recoverable"].includes(synopsisJobState(job)) && (
 <button type="button" onClick={resume}><RotateCcw size={14} /> 继续处理</button>
 )}
 {intake && !["failed", "recoverable", "cancelled"].includes(synopsisJobState(job)) && (
 <>
 <button type="button" onClick={retryPoll}><RotateCcw size={14} /> 重新查询</button>
 <button type="button" onClick={cancel}>取消任务</button>
 </>
 )}
 {(!intake || ["failed", "recoverable", "cancelled"].includes(synopsisJobState(job))) && (
 <button type="button" onClick={reset}><RotateCcw size={14} /> 重新选择</button>
 )}
 </div>
 )}
 </section>
 );
 }

 return (
 <section className="file-first-synopsis-review">
 <header>
 <div>
 <span>AI 已提取 · 一次确认</span>
 <strong>{imported.source.original_filename}</strong>
 </div>
 <button type="button" onClick={reset} disabled={Boolean(busy)} title="更换文件">
 <XCircle size={16} /> 更换文件
 </button>
 </header>

 <div className="file-first-core-fields">
 <label>
 <span>试验药物</span>
 <input value={framing?.investigational_product || ""} onChange={(event) => setFramingField("investigational_product", event.target.value)} />
 </label>
 <label>
 <span>适应症</span>
 <input value={framing?.indication || ""} onChange={(event) => setFramingField("indication", event.target.value)} />
 </label>
 <label>
 <span>研究分期</span>
 <select value={framing?.study_phase || ""} onChange={(event) => setFramingField("study_phase", event.target.value)}>
 <option value="">请选择</option>
 {PHASES.map((phase) => <option key={phase}>{phase}</option>)}
 </select>
 </label>
 <label>
 <span>方案号</span>
 <input value={framing?.protocol_id || ""} onChange={(event) => setFramingField("protocol_id", event.target.value)} />
 </label>
 <label className="span-2">
 <span>建议方案标题</span>
 <input value={framing?.document_title || ""} onChange={(event) => setFramingField("document_title", event.target.value)} />
 </label>
 <label>
 <span>版本</span>
 <input value={framing?.version || ""} onChange={(event) => setFramingField("version", event.target.value)} />
 </label>
 </div>

 <div className="file-first-design-summary">
 <label>
 <span>研究设计</span>
 <textarea rows={2} value={framing?.design_pattern || ""} onChange={(event) => setFramingField("design_pattern", event.target.value)} />
 </label>
 <label>
 <span>研究人群</span>
 <textarea rows={2} value={picos?.population_summary || framing?.population_intent || ""} onChange={(event) => {
 setPicosField("population_summary", event.target.value);
 setFramingField("population_intent", event.target.value);
 }} />
 </label>
 <label>
 <span>干预措施</span>
 <textarea rows={2} value={picos?.intervention_summary || ""} onChange={(event) => setPicosField("intervention_summary", event.target.value)} />
 </label>
 <label>
 <span>对照</span>
 <textarea rows={2} value={picos?.comparator_summary || ""} onChange={(event) => setPicosField("comparator_summary", event.target.value)} />
 </label>
 <label>
 <span>主要终点</span>
 <textarea rows={2} value={picos?.primary_endpoint || ""} onChange={(event) => setPicosField("primary_endpoint", event.target.value)} />
 </label>
 </div>

 {(imported.missing_fields?.length > 0 || imported.conflict_notes?.length > 0) && (
 <div className="file-first-findings">
 <div><strong>后续仅需补充</strong><span>{imported.missing_fields?.map((item) => item.split(".").at(-1)).join("、") || "无"}</span></div>
 <div><strong>需留意的原文差异</strong><span>{imported.conflict_notes?.join("；") || "无"}</span></div>
 </div>
 )}

 {warnings.length > 0 && (
 <div className="file-first-warnings">
 <strong>文件内容提示</strong>
 {warnings.map((warning) => (
 <label key={warning}>
 <input
 type="checkbox"
 checked={acknowledged.includes(warning)}
 onChange={() => setAcknowledged((current) => current.includes(warning)
 ? current.filter((item) => item !== warning)
 : [...current, warning])}
 />
 <span>{warning}</span>
 </label>
 ))}
 <textarea rows={2} value={overrideReason} onChange={(event) => setOverrideReason(event.target.value)} placeholder="确认该文件可用于当前项目的理由（不少于10个字符）" />
 </div>
 )}

 <footer>
 <span><CheckCircle2 size={15} />确认后，已提取内容直接成为当前项目事实；不会再次要求医学批准。</span>
 <button type="button" className="primary-button" disabled={!canConfirm || Boolean(busy)} onClick={confirm}>
 {busy === "confirm" ? <LoaderCircle size={15} className="spin" /> : <CheckCircle2 size={15} />}
 {busy === "confirm" ? "正在创建" : "确认并进入写作"}
 </button>
 </footer>
 {message && <p className="file-first-inline-error"><AlertTriangle size={15} />{message}</p>}
 </section>
 );
}

import { afterEach, describe, expect, it, vi } from "vitest";

import {
 SynopsisRequestTimeoutError,
 cancelSynopsisJob,
 pollSynopsisJob,
 requestJsonWithTimeout,
 synopsisJobMessage,
 synopsisJobState,
} from "./MedicalWritingSynopsisProjectIntake";

const startedJob = {
 intake_id: "mwintake_test",
 idempotency_key: "file-first-synopsis-test",
 status: "chunking",
 phase: "chunking",
};

afterEach(() => {
 vi.useRealTimers();
});

describe("synopsis intake recovery", () => {
 it("aborts a hung poll request and stops after a bounded failure budget", async () => {
 vi.useFakeTimers();
 const hungFetch = vi.fn((_url, { signal }) => new Promise((_resolve, reject) => {
 signal.addEventListener("abort", () => {
 reject(new DOMException("Aborted", "AbortError"));
 }, { once: true });
 }));
 const timedRequest = requestJsonWithTimeout("/hung", {}, {
 timeoutMs: 25,
 fetchImpl: hungFetch,
 });
 const timedAssertion = expect(timedRequest).rejects.toBeInstanceOf(SynopsisRequestTimeoutError);
 await vi.advanceTimersByTimeAsync(25);
 await timedAssertion;

 const request = vi.fn().mockRejectedValue(new SynopsisRequestTimeoutError());
 await expect(pollSynopsisJob(startedJob, {
 request,
 wait: () => Promise.resolve(),
 maxConsecutiveFailures: 3,
 })).rejects.toThrow("后台任务仍会保留");
 expect(request).toHaveBeenCalledTimes(3);
 });

 it("surfaces a backend failed terminal state and preserves its error", async () => {
 const failed = {
 status: "failed",
 phase: "failed",
 error_message: "产品 AI 结构化调用超时",
 };
 const onJob = vi.fn();
 const terminal = await pollSynopsisJob(startedJob, {
 request: vi.fn().mockResolvedValue(failed),
 onJob,
 });

 expect(synopsisJobState(terminal)).toBe("failed");
 expect(synopsisJobMessage(terminal)).toBe("产品 AI 结构化调用超时");
 expect(onJob).toHaveBeenCalledWith(failed);
 });

 it("aborts polling before issuing an independent cancel command", async () => {
 const order = [];
 const cancelled = { status: "cancelled", cancellation_state: "cancelled" };
 const result = await cancelSynopsisJob(startedJob, {
 abortPolling: () => order.push("abort-poll"),
 request: vi.fn().mockImplementation(async (_url, options) => {
 order.push(`cancel-${options.method}`);
 return cancelled;
 }),
 });

 expect(order).toEqual(["abort-poll", "cancel-POST"]);
 expect(result).toEqual(cancelled);
 expect(synopsisJobMessage(result)).toContain("已取消");
 });

 it("treats a same-hash reused failed job as resumable without polling", async () => {
 const replay = {
 ...startedJob,
 status: "reused",
 phase: "failed",
 };
 const request = vi.fn();
 const terminal = await pollSynopsisJob(replay, { request });

 expect(request).not.toHaveBeenCalled();
 expect(synopsisJobState(terminal)).toBe("failed");
 expect(synopsisJobMessage(terminal)).toContain("继续处理");
 });
});

import { useEffect, useMemo, useState } from "react";
import { CheckCircle2, CircleDashed, Clock3, EyeOff, SlidersHorizontal } from "lucide-react";

const STATUS_OPTIONS = [
 { value: "applicable|retain_full", label: "纳入方案", status: "applicable", renderAction: "retain_full" },
 { value: "not_applicable|omit", label: "不适用，隐藏章节", status: "not_applicable", renderAction: "omit" },
 { value: "not_applicable|retain_not_applicable", label: "不适用，保留“不适用”", status: "not_applicable", renderAction: "retain_not_applicable" },
 { value: "unknown|omit", label: "待确定，暂不呈现", status: "unknown", renderAction: "omit" },
 { value: "deferred|omit", label: "延后决定，暂不呈现", status: "deferred", renderAction: "omit" },
];

const STATUS_META = {
 applicable: { label: "已纳入", tone: "included", icon: CheckCircle2 },
 not_applicable: { label: "不适用", tone: "excluded", icon: EyeOff },
 unknown: { label: "待确定", tone: "unknown", icon: CircleDashed },
 deferred: { label: "延后", tone: "deferred", icon: Clock3 },
};

const ARTIFACT_LABELS = {
 synopsis: "方案摘要",
 body: "正文",
 statistics: "统计分析",
 schedule: "研究流程表",
 evidence: "证据候选",
 ai_candidates: "AI候选",
};

const defaultRationale = (status) => ({
 applicable: "医学经理确认本研究包含该设计模块。",
 not_applicable: "医学经理确认本研究不包含该设计模块。",
 unknown: "当前信息不足，待补充研究设计事实后再确定。",
 deferred: "该设计决定延后至后续方案讨论时确定。",
}[status]);

export function ProtocolModuleResolutionPanel({
 resolutions = [],
 templateNodes = [],
 busyId = "",
 baselineReady = false,
 message = "",
 lastResult = null,
 onApply,
}) {
 const [statusFilter, setStatusFilter] = useState("all");
 const [selectedId, setSelectedId] = useState("");
 const [draft, setDraft] = useState(null);
 const nodeBySemantic = useMemo(
 () => new Map(templateNodes.map((node) => [node.semantic_node_id, node])),
 [templateNodes],
 );
 const conditionalResolutions = useMemo(
 () => resolutions
 .filter((item) => {
 const node = nodeBySemantic.get(item.semantic_node_id);
 return node && node.applicability_mode !== "required";
 })
 .map((item) => ({ ...item, node: nodeBySemantic.get(item.semantic_node_id) }))
 .sort((left, right) => (
 (left.node?.section_number || "").localeCompare(
 right.node?.section_number || "",
 "zh-CN",
 { numeric: true },
 )
 )),
 [resolutions, nodeBySemantic],
 );
 const visible = statusFilter === "all"
 ? conditionalResolutions
 : conditionalResolutions.filter((item) => item.status === statusFilter);
 const selected = conditionalResolutions.find((item) => item.semantic_node_id === selectedId)
 || visible[0]
 || conditionalResolutions[0]
 || null;

 useEffect(() => {
 if (!selected) {
 setSelectedId("");
 setDraft(null);
 return;
 }
 if (selected.semantic_node_id !== selectedId) setSelectedId(selected.semantic_node_id);
 setDraft({
 status: selected.status,
 renderAction: selected.render_action,
 rationale: selected.rationale,
 sourceRefs: selected.source_fact_ids?.length
 ? selected.source_fact_ids
 : [`medical_manager:module:${selected.semantic_node_id}`],
 });
 }, [
 selected?.semantic_node_id,
 selected?.status,
 selected?.render_action,
 selected?.rationale,
 JSON.stringify(selected?.source_fact_ids || []),
 ]);

 const counts = conditionalResolutions.reduce(
 (result, item) => ({ ...result, [item.status]: (result[item.status] || 0) + 1 }),
 {},
 );
 const selectedOption = draft ? `${draft.status}|${draft.renderAction}` : "";
 const canApply = Boolean(
 selected
 && draft
 && baselineReady
 && draft.rationale.trim().length >= 5
 && busyId !== selected.semantic_node_id
 && (
 draft.status !== selected.status
 || draft.renderAction !== selected.render_action
 || draft.rationale.trim() !== selected.rationale
 ),
 );

 return (
 <section className="protocol-module-resolution-panel" aria-label="动态章节设计">
 <header>
 <div>
 <span><SlidersHorizontal size={14} /> 动态章节</span>
 <strong>按研究设计决定方案内容</strong>
 <small>选择即按医学经理决策应用；不再增加同角色的二次批准。</small>
 </div>
 <label>
 <span>显示</span>
 <select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)}>
 <option value="all">全部 {conditionalResolutions.length}</option>
 <option value="applicable">已纳入 {counts.applicable || 0}</option>
 <option value="not_applicable">不适用 {counts.not_applicable || 0}</option>
 <option value="unknown">待确定 {counts.unknown || 0}</option>
 <option value="deferred">延后 {counts.deferred || 0}</option>
 </select>
 </label>
 </header>
 <div className="protocol-module-resolution-workspace">
 <div className="protocol-module-resolution-list" role="list">
 {visible.map((item) => {
 const meta = STATUS_META[item.status] || STATUS_META.unknown;
 const Icon = meta.icon;
 return (
 <button
 type="button"
 role="listitem"
 key={item.semantic_node_id}
 className={selected?.semantic_node_id === item.semantic_node_id ? "active" : ""}
 onClick={() => setSelectedId(item.semantic_node_id)}
 >
 <span className={`module-status ${meta.tone}`}><Icon size={13} /> {meta.label}</span>
 <strong>{item.node?.title_zh || item.semantic_node_id}</strong>
 <small>{item.node?.section_number || "动态"} · {item.rationale}</small>
 </button>
 );
 })}
 {!visible.length && <p>当前筛选条件下没有章节。</p>}
 </div>
 {selected && draft ? (
 <div className="protocol-module-resolution-editor">
 <div className="module-resolution-title">
 <span>{selected.node?.section_number || "动态章节"}</span>
 <strong>{selected.node?.title_zh || selected.semantic_node_id}</strong>
 </div>
 <label>
 <span>本研究如何处理</span>
 <select
 value={selectedOption}
 onChange={(event) => {
 const option = STATUS_OPTIONS.find((item) => item.value === event.target.value);
 if (!option) return;
 setDraft((current) => ({
 ...current,
 status: option.status,
 renderAction: option.renderAction,
 rationale: defaultRationale(option.status),
 }));
 }}
 >
 {STATUS_OPTIONS.map((option) => (
 <option key={option.value} value={option.value}>{option.label}</option>
 ))}
 </select>
 </label>
 <label>
 <span>医学设计依据</span>
 <textarea
 rows={3}
 value={draft.rationale}
 onChange={(event) => setDraft((current) => ({ ...current, rationale: event.target.value }))}
 placeholder="简要说明为什么本研究纳入、不适用或延后该模块。"
 />
 </label>
 <div className="module-resolution-impact">
 <span>同步更新</span>
 <div>
 {(selected.affected_artifacts || []).map((item) => (
 <b key={item}>{ARTIFACT_LABELS[item] || item}</b>
 ))}
 </div>
 </div>
 <button
 type="button"
 className="primary-button"
 disabled={!canApply}
 data-baseline-ready={baselineReady ? "true" : "false"}
 onClick={() => onApply?.(selected, draft)}
 >
 {!baselineReady
 ? "正在同步方案基线"
 : busyId === selected.semantic_node_id
 ? "正在应用"
 : "应用到方案"}
 </button>
 </div>
 ) : <div className="protocol-module-resolution-empty">尚无可配置的动态章节。</div>}
 </div>
 {message && <p className="protocol-module-resolution-message">{message}</p>}
 {lastResult && (
 <p className="protocol-module-resolution-result">
 已同步 {lastResult.affected_artifacts?.map((item) => ARTIFACT_LABELS[item] || item).join("、") || "正文"}
 ；新增 {lastResult.added_section_ids?.length || 0} 节，移除 {lastResult.removed_section_ids?.length || 0} 节，
 保留历史 {lastResult.quarantined_section_ids?.length || 0} 节。
 </p>
 )}
 </section>
 );
}

import { useEffect, useMemo, useState } from "react";
import {
 AlertTriangle,
 ArrowDown,
 ArrowLeft,
 ArrowRight,
 ArrowUp,
 Check,
 Columns3,
 LayoutPanelTop,
 LockKeyhole,
 Merge,
 PanelRightClose,
 PanelRightOpen,
 PencilLine,
 Plus,
 Rows3,
 Sparkles,
 Split,
 StickyNote,
 Table2,
 Trash2,
 X,
} from "lucide-react";
import { TableCellRichEditor } from "./TableCellRichEditor";
import "./structured-table-designer.css";

const SOA_DOMAIN = "schedule_of_activities";
const CELL_ROLES = [
 { value: "body", label: "正文" },
 { value: "header", label: "表头" },
 { value: "section", label: "分区" },
];
const NOTE_TYPES = [
 { value: "item_set", label: "项目集合" },
 { value: "timing_rule", label: "时间规则" },
 { value: "condition", label: "适用条件" },
 { value: "specimen_preparation", label: "样本/准备" },
 { value: "definition", label: "定义" },
 { value: "exception", label: "例外" },
 { value: "operational", label: "执行说明" },
];
const PLAN_STATES = [
 { value: "planned", label: "X", cellText: "X" },
 { value: "conditional", label: "条件", cellText: "条件" },
 { value: "continuous", label: "持续", cellText: "持续" },
 { value: "not_applicable", label: "N/A", cellText: "N/A" },
];

let fallbackIdSequence = 0;

function cloneValue(value) {
 if (typeof globalThis.structuredClone === "function") return globalThis.structuredClone(value);
 return JSON.parse(JSON.stringify(value));
}

function localId(kind) {
 fallbackIdSequence += 1;
 const uuid = globalThis.crypto?.randomUUID?.()
 || `${Date.now().toString(36)}_${fallbackIdSequence.toString(36)}`;
 return `local_${kind}_${uuid}`;
}

function positiveInteger(value, fallback = 1) {
 const parsed = Number(value);
 return Number.isInteger(parsed) && parsed > 0 ? parsed : fallback;
}

function gridIndex(value, fallback = 0) {
 const parsed = Number(value);
 return Number.isInteger(parsed) && parsed >= 0 ? parsed : fallback;
}

function blockTitle(block) {
 return block?.structured_table?.title
 || block?.title
 || block?.title_hint
 || "未命名表格";
}

function tableDomain(block) {
 return block?.structured_table?.domain || block?.domain || "generic";
}

function inferredSoaHeaderRows(model) {
 const headerLabel = /^(?:研究阶段|试验阶段|访视周|访视天|研究日|访视窗口|访视日期|study period|visit week|study day|visit window)/i;
 let count = 0;
 for (const row of model.rows) {
 const firstVisibleCell = row.cells.find((cell) => !cell.hidden);
 if (!headerLabel.test(String(firstVisibleCell?.text || "").trim())) break;
 count += 1;
 }
 return count;
}

function columnCount(block) {
 let maximum = block?.structured_table?.columns?.length || 0;
 (block?.rows || []).forEach((row) => {
 let cursor = 0;
 (row || []).forEach((cell) => {
 const start = gridIndex(cell?.grid_column_index, cursor);
 const span = positiveInteger(cell?.column_span);
 maximum = Math.max(maximum, start + span);
 cursor = start + span;
 });
 });
 return Math.max(maximum, 1);
}

function structuredColumnMetadata(block, index, tableId) {
 const structured = block?.structured_table || {};
 const explicit = structured.columns?.[index] || {};
 const sourceCell = (block?.rows || [])
 .flatMap((row) => row || [])
 .find((cell) => (
 gridIndex(cell?.grid_column_index) === index
 && (cell?.structure_column_id || cell?.column_id)
 ));
 return {
 ...explicit,
 column_id: explicit.column_id
 || structured.column_ids?.[index]
 || sourceCell?.structure_column_id
 || sourceCell?.column_id
 || `${tableId}_column_${index}`,
 order: index,
 label: explicit.label || structured.column_labels?.[index] || `第 ${index + 1} 列`,
 style_role: explicit.style_role || structured.column_style_roles?.[index] || "body",
 width_twips: explicit.width_twips ?? structured.column_width_twips?.[index] ?? null,
 source_locator: explicit.source_locator || structured.column_source_locators?.[index] || "",
 semantic_role: explicit.semantic_role
 || structured.column_semantic_roles?.[index]
 || sourceCell?.structure_column_semantic_role
 || "",
 };
}

function structuredRowMetadata(block, row, rowIndex, tableId) {
 const structured = block?.structured_table || {};
 const explicit = structured.rows?.[rowIndex] || {};
 const sourceCell = (row || []).find((cell) => cell?.structure_row_id || cell?.row_id);
 return {
 ...explicit,
 row_id: explicit.row_id
 || structured.row_ids?.[rowIndex]
 || sourceCell?.structure_row_id
 || sourceCell?.row_id
 || `${tableId}_row_${rowIndex}`,
 order: rowIndex,
 label: explicit.label || structured.row_labels?.[rowIndex] || "",
 style_role: explicit.style_role || structured.row_style_roles?.[rowIndex] || sourceCell?.style_role || "body",
 };
}

function viewModel(block) {
 const tableId = block?.table_id || block?.structured_table?.table_id || "table";
 const count = columnCount(block);
 const columns = Array.from(
 { length: count },
 (_, index) => structuredColumnMetadata(block, index, tableId),
 );
 const rows = (block?.rows || []).map((row, rowIndex) => {
 const metadata = structuredRowMetadata(block, row, rowIndex, tableId);
 let cursor = 0;
 const cells = (row || []).map((cell, cellIndex) => {
 const start = gridIndex(cell?.grid_column_index, cursor);
 cursor = start + positiveInteger(cell?.column_span);
 return {
 ...cell,
 cell_id: cell?.cell_id || `${tableId}_cell_${rowIndex}_${cellIndex}`,
 grid_column_index: start,
 column_span: positiveInteger(cell?.column_span),
 row_span: positiveInteger(cell?.row_span),
 style_role: cell?.style_role || metadata.style_role || "body",
 };
 });
 return {
 ...metadata,
 row_id: metadata.row_id || cells[0]?.row_id || `${tableId}_row_${rowIndex}`,
 order: rowIndex,
 style_role: metadata.style_role || cells[0]?.style_role || "body",
 cells,
 };
 });
 return { tableId, columns, rows };
}

function synchronizeStructuredTable(block) {
 const structured = block.structured_table || {};
 const model = viewModel(block);
 const previousRows = structured.rows || [];
 const previousCells = new Map(
 previousRows.flatMap((row) => row?.cells || []).map((cell) => [cell.cell_id, cell]),
 );
 block.table_id = block.table_id || structured.table_id || localId("table");
 block.structured_table = {
 ...structured,
 schema_version: structured.schema_version || "structured_table_v1",
 table_id: block.table_id,
 block_id: structured.block_id || block.block_id || localId("block"),
 domain: structured.domain || block.domain || "generic",
 title: structured.title || block.title || block.title_hint || "未命名表格",
 source_locator: structured.source_locator || block.source_locator || "",
 version: Number.isInteger(structured.version) ? structured.version : 0,
 columns: model.columns.map((column, index) => ({
 ...(structured.columns?.[index] || {}),
 ...column,
 order: index,
 })),
 rows: model.rows.map((row, rowIndex) => ({
 ...(previousRows.find((item) => item.row_id === row.row_id) || previousRows[rowIndex] || {}),
 row_id: row.row_id,
 order: rowIndex,
 label: row.label || "",
 style_role: row.style_role || "body",
 source_locator: row.source_locator || "",
 cells: row.cells.map((cell) => ({
 ...(previousCells.get(cell.cell_id) || {}),
 ...cell,
 row_id: row.row_id,
 column_id: model.columns[cell.grid_column_index]?.column_id
 || model.columns[0].column_id,
 structure_row_id: row.row_id,
 structure_column_id: model.columns[cell.grid_column_index]?.column_id
 || model.columns[0].column_id,
 structure_row_order: rowIndex,
 structure_column_order: cell.grid_column_index,
 text: String(cell.text || ""),
 })),
 })),
 notes: Array.isArray(structured.notes) ? structured.notes : [],
 word_layout: {
 orientation: "landscape",
 ...(structured.word_layout || {}),
 },
 };
 block.structured_table.column_ids = block.structured_table.columns.map((column) => column.column_id);
 block.structured_table.column_labels = block.structured_table.columns.map((column) => column.label || "");
 block.structured_table.column_style_roles = block.structured_table.columns.map((column) => column.style_role || "body");
 block.structured_table.column_width_twips = block.structured_table.columns.map((column) => column.width_twips ?? null);
 block.structured_table.column_source_locators = block.structured_table.columns.map((column) => column.source_locator || "");
 block.structured_table.column_semantic_roles = block.structured_table.columns.map((column) => column.semantic_role || "");
 block.structured_table.row_ids = block.structured_table.rows.map((row) => row.row_id);
 block.structured_table.row_labels = block.structured_table.rows.map((row) => row.label || "");
 block.structured_table.row_style_roles = block.structured_table.rows.map((row) => row.style_role || "body");
 block.rows = block.structured_table.rows.map((row, rowIndex) => row.cells.map((cell) => ({
 ...cell,
 row_index: rowIndex,
 structure_column_semantic_role: block.structured_table.columns[cell.grid_column_index]?.semantic_role || "",
 })));
 return block;
}

function materializeBlock(block) {
 const next = cloneValue(block || { block_type: "table", rows: [] });
 next.rows = Array.isArray(next.rows) ? next.rows : [];
 const tableId = next.table_id || next.structured_table?.table_id || "table";
 const count = columnCount(next);
 const structured = next.structured_table || {};
 const columns = Array.from(
 { length: count },
 (_, index) => structuredColumnMetadata(next, index, tableId),
 );
 const rows = next.rows.map((row, rowIndex) => {
 const oldMeta = structuredRowMetadata(next, row, rowIndex, tableId);
 const rowId = oldMeta.row_id;
 let cursor = 0;
 return (row || []).map((cell, cellIndex) => {
 const start = gridIndex(cell?.grid_column_index, cursor);
 cursor = start + positiveInteger(cell?.column_span);
 return {
 ...cell,
 cell_id: cell?.cell_id || `${tableId}_cell_${rowIndex}_${cellIndex}`,
 row_id: rowId,
 column_id: columns[start]?.column_id || columns[0].column_id,
 structure_row_id: rowId,
 structure_column_id: columns[start]?.column_id || columns[0].column_id,
 structure_row_order: rowIndex,
 structure_column_order: start,
 row_index: rowIndex,
 grid_column_index: start,
 column_span: positiveInteger(cell?.column_span),
 row_span: positiveInteger(cell?.row_span),
 hidden: Boolean(cell?.hidden),
 style_role: cell?.style_role || oldMeta.style_role || "body",
 };
 });
 });
 next.structured_table = { ...structured, columns };
 next.rows = rows;
 return synchronizeStructuredTable(next);
}

function validateStructure(block) {
 const model = viewModel(block);
 const columnIds = model.columns.map((column) => column.column_id);
 const rowIds = model.rows.map((row) => row.row_id);
 const cellIds = model.rows.flatMap((row) => row.cells.map((cell) => cell.cell_id));
 const noteIds = (block?.structured_table?.notes || []).map((note) => note.note_id);
 if (new Set(columnIds).size !== columnIds.length) return "列 ID 冲突，已阻止本次操作。";
 if (new Set(rowIds).size !== rowIds.length) return "行 ID 冲突，已阻止本次操作。";
 if (new Set(cellIds).size !== cellIds.length) return "单元格 ID 冲突，已阻止本次操作。";
 if (new Set(noteIds).size !== noteIds.length) return "附注 ID 冲突，已阻止本次操作。";
 const validTargets = new Set([
 block?.table_id,
 block?.block_id,
 block?.structured_table?.block_id,
 ...columnIds,
 ...rowIds,
 ...cellIds,
 ].filter(Boolean));
 const soaMetadata = block?.structured_table?.soa || block?.structured_table?.schedule_of_activities || {};
 ["epochs", "visits", "activities", "cells"].forEach((collection) => {
 (soaMetadata[collection] || []).forEach((item) => {
 ["epoch_id", "visit_id", "activity_id", "cell_id"].forEach((key) => {
 if (item?.[key]) validTargets.add(item[key]);
 });
 });
 });
 for (const note of block?.structured_table?.notes || []) {
 if (!(note.target_ids || []).length || note.target_ids.some((targetId) => !validTargets.has(targetId))) {
 return "附注存在空目标或失效目标，已阻止本次操作。";
 }
 }
 const occupied = new Set();
 for (let rowIndex = 0; rowIndex < model.rows.length; rowIndex += 1) {
 for (const cell of model.rows[rowIndex].cells) {
 if (cell.hidden) continue;
 const rowSpan = positiveInteger(cell.row_span);
 const columnSpan = positiveInteger(cell.column_span);
 if (cell.grid_column_index + columnSpan > model.columns.length) {
 return "单元格跨列超出表格边界，已阻止本次操作。";
 }
 if (rowIndex + rowSpan > model.rows.length) {
 return "单元格跨行超出表格边界，已阻止本次操作。";
 }
 for (let r = rowIndex; r < rowIndex + rowSpan; r += 1) {
 for (let c = cell.grid_column_index; c < cell.grid_column_index + columnSpan; c += 1) {
 const key = `${r}:${c}`;
 if (occupied.has(key)) return "合并区域发生重叠，已阻止本次操作。";
 occupied.add(key);
 }
 }
 }
 }
 return "";
}

function cellLocation(model, cellId) {
 for (let rowIndex = 0; rowIndex < model.rows.length; rowIndex += 1) {
 const row = model.rows[rowIndex];
 const cell = row.cells.find((item) => item.cell_id === cellId);
 if (cell) {
 const columnIndex = cell.grid_column_index;
 return {
 rowIndex,
 columnIndex,
 row,
 column: model.columns[columnIndex],
 cell,
 };
 }
 }
 return null;
}

function selectedRectangle(model, anchorId, selectedId) {
 const anchor = cellLocation(model, anchorId);
 const selected = cellLocation(model, selectedId);
 if (!anchor || !selected) return null;
 return {
 top: Math.min(anchor.rowIndex, selected.rowIndex),
 bottom: Math.max(anchor.rowIndex, selected.rowIndex),
 left: Math.min(anchor.columnIndex, selected.columnIndex),
 right: Math.max(anchor.columnIndex, selected.columnIndex),
 };
}

function compactSourceBoundary(block) {
 const locator = block?.source_locator || block?.structured_table?.source_locator;
 if (!locator) return "当前工作副本表格；未提供来源定位";
 return `来源边界：${locator}`;
}

function IconButton({ label, icon: Icon, onClick, disabled = false, active = false }) {
 return (
 <button
 type="button"
 className={active ? "std-icon-button active" : "std-icon-button"}
 aria-label={label}
 title={label}
 disabled={disabled}
 onClick={onClick}
 >
 <Icon size={15} aria-hidden="true" />
 </button>
 );
}

export function StructuredTableDesigner({
 tableBlock,
 readOnly = false,
 onChange,
 onClose,
 onSelectedCellChange,
 cellRevisionThreads = [],
 documentIndex = null,
 domainProfiles = [],
 suggestedDomain = "",
}) {
 const [draftBlock, setDraftBlock] = useState(() => cloneValue(tableBlock || {}));
 const [selectedCellId, setSelectedCellId] = useState("");
 const [selectionAnchorId, setSelectionAnchorId] = useState("");
 const [cellEditorFocusRequest, setCellEditorFocusRequest] = useState(0);
 const [inspectorOpen, setInspectorOpen] = useState(true);
 const [inspectorTab, setInspectorTab] = useState("properties");
 const [error, setError] = useState("");

 useEffect(() => {
 setDraftBlock(cloneValue(tableBlock || {}));
 }, [tableBlock]);

 const model = useMemo(() => viewModel(draftBlock), [draftBlock]);
 const domain = tableDomain(draftBlock);
 const objectRole = draftBlock?.structured_table?.role || "unclassified";
 const isLayoutObject = objectRole === "layout";
 const isSynopsisObject = objectRole === "protocol_synopsis";
 const isDedicatedDocumentObject = isLayoutObject || isSynopsisObject;
 const objectRoleLabel = isLayoutObject
 ? "方案首页排版对象"
 : isSynopsisObject
 ? "方案摘要结构化对象"
 : "";
 const isSoa = domain === SOA_DOMAIN;
 const activeDomainProfile = isDedicatedDocumentObject
 ? null
 : domainProfiles.find((profile) => profile.domain === domain) || null;
 const selected = cellLocation(model, selectedCellId);
 const rectangle = selectedRectangle(model, selectionAnchorId, selectedCellId);
 const headerRowCount = Math.max(
 Number(draftBlock?.header_row_count || draftBlock?.structured_table?.header_row_count || 0),
 isSoa ? inferredSoaHeaderRows(model) : 0,
 model.rows.reduce((count, row, rowIndex) => (
 rowIndex === count
 && (row.style_role === "header" || row.cells.some((cell) => cell.style_role === "header"))
 ? count + 1
 : count
 ), 0),
 );
 const notes = draftBlock?.structured_table?.notes || [];
 const sourceCaption = draftBlock?.structured_table?.source_caption || null;
 const sourceCaptionText = String(
 draftBlock?.table_caption?.text || sourceCaption?.text || "",
 ).trim();
 const wordOrientation = draftBlock?.structured_table?.word_layout?.orientation || "landscape";
 const domainProfileState = draftBlock?.structured_table?.word_layout?.domain_profile || {};
 const domainMappingLabel = {
 template_roles_attached: "模板角色已附加，待医学确认",
 pending_user_confirmation: "待人工确认",
 confirmed_by_user: "已确认",
 }[domainProfileState.mapping_status] || "待建立映射";
 const mappedSemanticRoles = new Set(model.columns.map((column) => column.semantic_role).filter(Boolean));
 const missingRequiredRoles = (activeDomainProfile?.column_roles || [])
 .filter((role) => role.required && !mappedSemanticRoles.has(role.role_id));
 const selectedDomainRole = activeDomainProfile?.column_roles?.find(
 (role) => role.role_id === selected?.column?.semantic_role,
 ) || null;
 const domainRecordAxis = domainProfileState.record_axis || "semantic_only";
 const incompleteDomainRows = domainRecordAxis === "rows" && activeDomainProfile
 ? model.rows.slice(headerRowCount).filter((row) => {
 const visibleCells = row.cells.filter((cell) => !cell.hidden);
 if (!visibleCells.some((cell) => String(cell.text || "").trim())) return false;
 return (activeDomainProfile.column_roles || []).some((role) => {
 if (!role.required) return false;
 const roleColumns = model.columns
 .filter((column) => column.semantic_role === role.role_id)
 .map((column) => column.column_id);
 return !roleColumns.length || !visibleCells.some((cell) => (
 roleColumns.includes(cell.column_id) && String(cell.text || "").trim()
 ));
 });
 })
 : [];

 useEffect(() => {
 if (selectedCellId && !cellLocation(model, selectedCellId)) {
 setSelectedCellId("");
 setSelectionAnchorId("");
 }
 }, [model, selectedCellId]);

 useEffect(() => {
 if (!selected) {
 onSelectedCellChange?.(null);
 return;
 }
 onSelectedCellChange?.({
 rowId: selected.row.row_id,
 rowLabel: selected.row.label || "",
 columnId: selected.column.column_id,
 columnLabel: selected.column.label || "",
 semanticRole: selected.column.semantic_role || "",
 cellId: selected.cell.cell_id,
 text: String(selected.cell.text || ""),
 rowIndex: selected.rowIndex,
 columnIndex: selected.columnIndex,
 });
 }, [selectedCellId, draftBlock]);

 const emitMutation = (mutator) => {
 if (readOnly) return;
 const next = materializeBlock(draftBlock);
 const result = mutator(next) || {};
 if (typeof result === "string") {
 setError(result);
 return;
 }
 synchronizeStructuredTable(next);
 const structureError = validateStructure(next);
 if (structureError) {
 setError(structureError);
 return;
 }
 setError("");
 setDraftBlock(next);
 if (result.selectId) {
 setSelectedCellId(result.selectId);
 setSelectionAnchorId(result.selectId);
 }
 onChange?.(next);
 };

 const selectCell = (cellId, extend = false, focusEditor = false) => {
 setSelectedCellId(cellId);
 if (!extend || !selectionAnchorId) setSelectionAnchorId(cellId);
 if (focusEditor && !extend && !readOnly) {
 setCellEditorFocusRequest((value) => value + 1);
 }
 };

 const navigateEditableCell = (direction) => {
 const visibleCells = model.rows.flatMap((row) => row.cells.filter((cell) => !cell.hidden));
 if (!visibleCells.length) return;
 const currentIndex = visibleCells.findIndex((cell) => cell.cell_id === selectedCellId);
 const nextIndex = Math.max(0, Math.min(
 visibleCells.length - 1,
 (currentIndex < 0 ? 0 : currentIndex) + direction,
 ));
 selectCell(visibleCells[nextIndex].cell_id, false, true);
 };

 const updateCell = (cellId, updater) => emitMutation((next) => {
 for (const row of next.rows) {
 const index = row.findIndex((cell) => cell.cell_id === cellId);
 if (index >= 0) {
 row[index] = { ...row[index], ...updater(row[index]) };
 return { selectId: cellId };
 }
 }
 return "未找到目标单元格，已阻止本次操作。";
 });

 const updateDomain = (nextDomain) => emitMutation((next) => {
 const profile = domainProfiles.find((item) => item.domain === nextDomain);
 next.structured_table.domain = nextDomain;
 next.domain = nextDomain;
 next.structured_table.columns = next.structured_table.columns.map((column) => ({
 ...column,
 semantic_role: "",
 }));
 next.rows.forEach((row) => row.forEach((cell) => {
 cell.structure_column_semantic_role = "";
 }));
 if (!profile) {
 next.structured_table.word_layout = {
 ...(next.structured_table.word_layout || {}),
 };
 delete next.structured_table.word_layout.domain_profile;
 return { selectId: selectedCellId };
 }
 next.structured_table.word_layout = {
 ...(next.structured_table.word_layout || {}),
 domain_profile: {
 profile_id: profile.profile_id,
 profile_version: profile.version,
 mapping_status: "pending_user_confirmation",
 confirmed_by_user: false,
 record_axis: "semantic_only",
 source: "working_copy_user_mapping",
 },
 };
 return { selectId: selectedCellId };
 });

 const mapDomainProfile = () => emitMutation((next) => {
 if (!activeDomainProfile) return "请先选择支持领域设计的表格类型。";
 const usedRoles = new Set();
 next.structured_table.columns = next.structured_table.columns.map((column) => {
 if (column.semantic_role) {
 usedRoles.add(column.semantic_role);
 return column;
 }
 const normalizedLabel = String(column.label || "").replace(/[\s/、（）()]/g, "");
 if (!normalizedLabel) return column;
 const match = activeDomainProfile.column_roles.find((role) => {
 const normalizedRole = String(role.label || "").replace(/[\s/、（）()]/g, "");
 return !usedRoles.has(role.role_id)
 && (normalizedLabel.includes(normalizedRole) || normalizedRole.includes(normalizedLabel));
 });
 if (!match) return column;
 usedRoles.add(match.role_id);
 return { ...column, semantic_role: match.role_id };
 });
 next.structured_table.word_layout = {
 ...(next.structured_table.word_layout || {}),
 domain_profile: {
 ...(next.structured_table.word_layout?.domain_profile || {}),
 profile_id: activeDomainProfile.profile_id,
 profile_version: activeDomainProfile.version,
 mapping_status: "pending_user_confirmation",
 confirmed_by_user: false,
 },
 };
 return { selectId: selectedCellId };
 });

 const updateColumnSemanticRole = (semanticRole) => emitMutation((next) => {
 const current = viewModel(next);
 const location = cellLocation(current, selectedCellId);
 if (!location) return "请先选择要映射的列。";
 next.structured_table.columns[location.columnIndex] = {
 ...next.structured_table.columns[location.columnIndex],
 semantic_role: semanticRole,
 };
 next.rows.forEach((row) => row.forEach((cell) => {
 if (cell.grid_column_index === location.columnIndex) {
 cell.structure_column_semantic_role = semanticRole;
 }
 }));
 next.structured_table.word_layout = {
 ...(next.structured_table.word_layout || {}),
 domain_profile: {
 ...(next.structured_table.word_layout?.domain_profile || {}),
 profile_id: activeDomainProfile?.profile_id || domain,
 profile_version: activeDomainProfile?.version || "",
 mapping_status: "pending_user_confirmation",
 confirmed_by_user: false,
 },
 };
 return { selectId: selectedCellId };
 });

 const confirmDomainMapping = () => {
 if (missingRequiredRoles.length) {
 setError(`仍有必需字段未映射：${missingRequiredRoles.map((role) => role.label).join("、")}`);
 return;
 }
 emitMutation((next) => {
 next.structured_table.word_layout = {
 ...(next.structured_table.word_layout || {}),
 domain_profile: {
 ...(next.structured_table.word_layout?.domain_profile || {}),
 profile_id: activeDomainProfile.profile_id,
 profile_version: activeDomainProfile.version,
 mapping_status: "confirmed_by_user",
 confirmed_by_user: true,
 },
 };
 return { selectId: selectedCellId };
 });
 };

 const updateProjectEvidenceConfirmation = (confirmed) => emitMutation((next) => {
 next.structured_table.word_layout = {
 ...(next.structured_table.word_layout || {}),
 domain_profile: {
 ...(next.structured_table.word_layout?.domain_profile || {}),
 project_evidence_confirmed_by_user: confirmed,
 },
 };
 return { selectId: selectedCellId };
 });

 const updateDomainRecordAxis = (recordAxis) => emitMutation((next) => {
 next.structured_table.word_layout = {
 ...(next.structured_table.word_layout || {}),
 domain_profile: {
 ...(next.structured_table.word_layout?.domain_profile || {}),
 record_axis: recordAxis,
 mapping_status: "pending_user_confirmation",
 confirmed_by_user: false,
 },
 };
 return { selectId: selectedCellId };
 });

 const addRow = () => emitMutation((next) => {
 const current = viewModel(next);
 const location = cellLocation(current, selectedCellId);
 const insertionIndex = location ? location.rowIndex + 1 : current.rows.length;
 const crossing = current.rows.some((row, rowIndex) => row.cells.some((cell) => (
 !cell.hidden && rowIndex < insertionIndex && rowIndex + cell.row_span > insertionIndex
 )));
 if (crossing) return "新增位置穿过纵向合并区域，请先拆分相关单元格。";
 const rowId = localId("row");
 const cells = current.columns.map((column, columnIndex) => ({
 cell_id: localId("cell"),
 row_id: rowId,
 column_id: column.column_id,
 row_index: insertionIndex,
 grid_column_index: columnIndex,
 column_span: 1,
 row_span: 1,
 hidden: false,
 text: "",
 style_role: "body",
 source_locator: "",
 provenance_lineage: [],
 note_refs: [],
 }));
 next.rows.splice(insertionIndex, 0, cells);
 next.structured_table.rows.splice(insertionIndex, 0, {
 row_id: rowId,
 order: insertionIndex,
 label: "",
 style_role: "body",
 source_locator: "",
 cells,
 });
 return { selectId: cells[0].cell_id };
 });

 const deleteRow = () => emitMutation((next) => {
 const current = viewModel(next);
 const location = cellLocation(current, selectedCellId);
 if (!location) return "请先选择要删除的行。";
 if (current.rows.length <= 1) return "表格至少保留一行。";
 const rowTouchesMerge = current.rows.some((row, rowIndex) => row.cells.some((cell) => (
 cell.hidden && rowIndex === location.rowIndex
 ) || (!cell.hidden && rowIndex <= location.rowIndex && rowIndex + cell.row_span > location.rowIndex && cell.row_span > 1)));
 if (rowTouchesMerge) return "目标行处于纵向合并区域，请先拆分相关单元格。";
 next.rows.splice(location.rowIndex, 1);
 next.structured_table.rows.splice(location.rowIndex, 1);
 const fallback = next.rows[Math.min(location.rowIndex, next.rows.length - 1)]?.find((cell) => !cell.hidden);
 return { selectId: fallback?.cell_id || "" };
 });

 const moveRow = (direction) => emitMutation((next) => {
 const current = viewModel(next);
 const location = cellLocation(current, selectedCellId);
 if (!location) return "请先选择要移动的行。";
 if (current.rows.some((row) => row.cells.some((cell) => cell.hidden || cell.row_span > 1))) {
 return "存在纵向合并单元格时不能移动行，请先拆分相关区域。";
 }
 const target = location.rowIndex + direction;
 if (target < 0 || target >= next.rows.length) return "目标行已位于边界。";
 [next.rows[location.rowIndex], next.rows[target]] = [next.rows[target], next.rows[location.rowIndex]];
 [next.structured_table.rows[location.rowIndex], next.structured_table.rows[target]] = [
 next.structured_table.rows[target],
 next.structured_table.rows[location.rowIndex],
 ];
 return { selectId: selectedCellId };
 });

 const addColumn = () => emitMutation((next) => {
 const current = viewModel(next);
 const location = cellLocation(current, selectedCellId);
 const insertionIndex = location ? location.columnIndex + 1 : current.columns.length;
 const crossing = current.rows.some((row) => row.cells.some((cell) => (
 !cell.hidden && cell.grid_column_index < insertionIndex
 && cell.grid_column_index + cell.column_span > insertionIndex
 )));
 if (crossing) return "新增位置穿过横向合并区域，请先拆分相关单元格。";
 const column = {
 column_id: localId("column"),
 order: insertionIndex,
 label: `第 ${insertionIndex + 1} 列`,
 style_role: "body",
 source_locator: "",
 semantic_role: "",
 };
 next.structured_table.columns.splice(insertionIndex, 0, column);
 let firstCellId = "";
 next.rows.forEach((row, rowIndex) => {
 row.forEach((cell) => {
 if (cell.grid_column_index >= insertionIndex) cell.grid_column_index += 1;
 });
 const rowId = next.structured_table.rows[rowIndex].row_id;
 const cell = {
 cell_id: localId("cell"),
 row_id: rowId,
 column_id: column.column_id,
 row_index: rowIndex,
 grid_column_index: insertionIndex,
 column_span: 1,
 row_span: 1,
 hidden: false,
 text: "",
 style_role: "body",
 source_locator: "",
 provenance_lineage: [],
 note_refs: [],
 };
 row.push(cell);
 row.sort((left, right) => left.grid_column_index - right.grid_column_index);
 if (!firstCellId) firstCellId = cell.cell_id;
 });
 return { selectId: firstCellId };
 });

 const deleteColumn = () => emitMutation((next) => {
 const current = viewModel(next);
 const location = cellLocation(current, selectedCellId);
 if (!location) return "请先选择要删除的列。";
 if (current.columns.length <= 1) return "表格至少保留一列。";
 const intersectsMerge = current.rows.some((row) => row.cells.some((cell) => (
 !cell.hidden
 && cell.grid_column_index <= location.columnIndex
 && cell.grid_column_index + cell.column_span > location.columnIndex
 && cell.column_span > 1
 )));
 if (intersectsMerge) return "目标列处于横向合并区域，请先拆分相关单元格。";
 next.rows.forEach((row) => {
 const index = row.findIndex((cell) => cell.grid_column_index === location.columnIndex);
 if (index >= 0) row.splice(index, 1);
 row.forEach((cell) => {
 if (cell.grid_column_index > location.columnIndex) cell.grid_column_index -= 1;
 });
 });
 next.structured_table.columns.splice(location.columnIndex, 1);
 const fallback = next.rows[location.rowIndex]?.find((cell) => !cell.hidden);
 return { selectId: fallback?.cell_id || "" };
 });

 const moveColumn = (direction) => emitMutation((next) => {
 const current = viewModel(next);
 const location = cellLocation(current, selectedCellId);
 if (!location) return "请先选择要移动的列。";
 if (current.rows.some((row) => row.cells.some((cell) => cell.column_span > 1))) {
 return "存在横向合并单元格时不能移动列，请先拆分相关区域。";
 }
 const target = location.columnIndex + direction;
 if (target < 0 || target >= current.columns.length) return "目标列已位于边界。";
 next.rows.forEach((row) => {
 row.forEach((cell) => {
 if (cell.grid_column_index === location.columnIndex) cell.grid_column_index = target;
 else if (cell.grid_column_index === target) cell.grid_column_index = location.columnIndex;
 });
 row.sort((left, right) => left.grid_column_index - right.grid_column_index);
 });
 [next.structured_table.columns[location.columnIndex], next.structured_table.columns[target]] = [
 next.structured_table.columns[target],
 next.structured_table.columns[location.columnIndex],
 ];
 return { selectId: selectedCellId };
 });

 const mergeCells = () => emitMutation((next) => {
 const current = viewModel(next);
 const range = selectedRectangle(current, selectionAnchorId, selectedCellId);
 if (!range || (range.top === range.bottom && range.left === range.right)) {
 return "按住 Shift 选择一个规则矩形后再合并。";
 }
 const targets = [];
 for (let rowIndex = range.top; rowIndex <= range.bottom; rowIndex += 1) {
 for (let columnIndex = range.left; columnIndex <= range.right; columnIndex += 1) {
 const cell = current.rows[rowIndex].cells.find((item) => (
 !item.hidden && item.grid_column_index === columnIndex
 ));
 if (!cell || cell.row_span !== 1 || cell.column_span !== 1) {
 return "所选区域不是未合并的规则矩形，已阻止合并。";
 }
 targets.push({ rowIndex, columnIndex, cell });
 }
 }
 if (targets.filter(({ cell }) => String(cell.text || "").trim()).length > 1) {
 return "所选区域含多个非空单元格，请先保留一个主单元格内容后再合并。";
 }
 const parent = targets[0].cell;
 next.rows[range.top] = next.rows[range.top].map((cell) => (
 cell.cell_id === parent.cell_id
 ? { ...cell, row_span: range.bottom - range.top + 1, column_span: range.right - range.left + 1 }
 : cell
 ));
 targets.slice(1).forEach(({ rowIndex, cell }) => {
 next.rows[rowIndex] = next.rows[rowIndex].map((item) => (
 item.cell_id === cell.cell_id
 ? {
 ...item,
 hidden: true,
 merge_parent_cell_id: parent.cell_id,
 merge_parent_row_index: range.top,
 merge_parent_grid_column_index: range.left,
 }
 : item
 ));
 });
 return { selectId: parent.cell_id };
 });

 const splitCell = () => emitMutation((next) => {
 const current = viewModel(next);
 const location = cellLocation(current, selectedCellId);
 if (!location || (location.cell.row_span === 1 && location.cell.column_span === 1)) {
 return "当前单元格没有可拆分的合并区域。";
 }
 const parent = location.cell;
 for (let rowIndex = location.rowIndex; rowIndex < location.rowIndex + parent.row_span; rowIndex += 1) {
 for (let columnIndex = location.columnIndex; columnIndex < location.columnIndex + parent.column_span; columnIndex += 1) {
 const row = next.rows[rowIndex];
 const existingIndex = row.findIndex((cell) => cell.grid_column_index === columnIndex);
 if (rowIndex === location.rowIndex && columnIndex === location.columnIndex) {
 row[existingIndex] = { ...row[existingIndex], row_span: 1, column_span: 1 };
 } else if (existingIndex >= 0) {
 row[existingIndex] = {
 ...row[existingIndex],
 hidden: false,
 merge_parent_cell_id: null,
 merge_parent_row_index: null,
 merge_parent_grid_column_index: null,
 row_span: 1,
 column_span: 1,
 };
 } else {
 row.push({
 cell_id: localId("cell"),
 row_id: next.structured_table.rows[rowIndex].row_id,
 column_id: next.structured_table.columns[columnIndex].column_id,
 row_index: rowIndex,
 grid_column_index: columnIndex,
 column_span: 1,
 row_span: 1,
 hidden: false,
 text: "",
 style_role: "body",
 source_locator: "",
 provenance_lineage: [],
 note_refs: [],
 });
 row.sort((left, right) => left.grid_column_index - right.grid_column_index);
 }
 }
 }
 return { selectId: parent.cell_id };
 });

 const setRowRole = (role) => emitMutation((next) => {
 const current = viewModel(next);
 const location = cellLocation(current, selectedCellId);
 if (!location) return "请先选择目标行。";
 next.rows[location.rowIndex] = next.rows[location.rowIndex].map((cell) => ({ ...cell, style_role: role }));
 next.structured_table.rows[location.rowIndex] = {
 ...next.structured_table.rows[location.rowIndex],
 style_role: role,
 };
 return { selectId: selectedCellId };
 });

 const addNote = () => emitMutation((next) => {
 const noteId = localId("note");
 const targetId = selectedCellId || next.table_id;
 next.structured_table.notes.push({
 note_id: noteId,
 marker: String(next.structured_table.notes.length + 1),
 note_type: "operational",
 text: "",
 target_ids: [targetId],
 module_ref: "",
 project_override: false,
 source_refs: [],
 source_kind: "working_copy_user_note",
 review_status: "confirmed",
 association_reason: "由医学用户在当前工作副本中新增。",
 });
 if (selectedCellId) {
 next.rows = next.rows.map((row) => row.map((cell) => (
 cell.cell_id === selectedCellId
 ? { ...cell, note_refs: [...new Set([...(cell.note_refs || []), noteId])] }
 : cell
 )));
 }
 setInspectorTab("notes");
 return { selectId: selectedCellId };
 });

 const updateNote = (noteId, patch) => emitMutation((next) => {
 next.structured_table.notes = next.structured_table.notes.map((note) => (
 note.note_id === noteId ? { ...note, ...patch } : note
 ));
 return { selectId: selectedCellId };
 });

 const deleteNote = (noteId) => emitMutation((next) => {
 next.structured_table.notes = next.structured_table.notes.filter((note) => note.note_id !== noteId);
 next.rows = next.rows.map((row) => row.map((cell) => ({
 ...cell,
 note_refs: (cell.note_refs || []).filter((ref) => ref !== noteId),
 })));
 return { selectId: selectedCellId };
 });

 const updateTableTitle = (title) => emitMutation((next) => {
 next.title = title;
 next.structured_table.title = title;
 return { selectId: selectedCellId };
 });

 const confirmCaptionAssociation = () => emitMutation((next) => {
 if (!next.structured_table.source_caption) return "当前表格没有待确认的来源表题。";
 next.structured_table.source_caption = {
 ...next.structured_table.source_caption,
 review_status: "confirmed",
 };
 if (next.table_caption) {
 next.table_caption = { ...next.table_caption, review_status: "confirmed" };
 }
 return { selectId: selectedCellId };
 });

 const confirmNoteAssociation = (noteId) => emitMutation((next) => {
 let found = false;
 next.structured_table.notes = next.structured_table.notes.map((note) => {
 if (note.note_id !== noteId) return note;
 found = true;
 return { ...note, review_status: "confirmed" };
 });
 next.structured_table.source_note_metadata = (
 next.structured_table.source_note_metadata || []
 ).map((metadata) => (
 metadata.note_id === noteId
 ? { ...metadata, review_status: "confirmed" }
 : metadata
 ));
 return found ? { selectId: selectedCellId } : "未找到待确认附注。";
 });

 const mapSoaMetadata = () => emitMutation((next) => {
 next.structured_table.soa = {
 ...(next.structured_table.soa || {}),
 mapping_status: "pending_user_confirmation",
 mapping_method: "mapped_from_current_table",
 confirmed_by_user: false,
 };
 return { selectId: selectedCellId };
 });

 const adoptSuggestedSoaDomain = () => emitMutation((next) => {
 next.structured_table.domain = SOA_DOMAIN;
 next.domain = SOA_DOMAIN;
 next.structured_table.soa = {
 ...(next.structured_table.soa || {}),
 mapping_status: "pending_user_confirmation",
 mapping_method: "mapped_from_current_table",
 confirmed_by_user: false,
 };
 return { selectId: selectedCellId };
 });

 const updateSoaCell = (patch) => {
 if (!selectedCellId) {
 setError("请先选择要设置研究流程属性的单元格。");
 return;
 }
 updateCell(selectedCellId, (cell) => ({
 soa: {
 ...(cell.soa || {}),
 mapping_status: cell.soa?.mapping_status || "pending_user_confirmation",
 ...patch,
 },
 }));
 };

 const updatePlanState = (state) => {
 const definition = PLAN_STATES.find((item) => item.value === state);
 if (!definition || !selectedCellId) return;
 updateCell(selectedCellId, (cell) => ({
 text: definition.cellText,
 rich_text: null,
 soa: {
 ...(cell.soa || {}),
 plan_state: state,
 mapping_status: cell.soa?.mapping_status || "pending_user_confirmation",
 },
 }));
 };

 const updateWordLayout = (orientation) => emitMutation((next) => {
 next.structured_table.word_layout = {
 ...(next.structured_table.word_layout || {}),
 orientation,
 };
 return { selectId: selectedCellId };
 });

 const moveSelection = (rowDelta, columnDelta) => {
 if (!selected) return;
 const targetRow = model.rows[selected.rowIndex + rowDelta];
 if (!targetRow) return;
 const targetColumn = Math.max(0, Math.min(
 model.columns.length - 1,
 selected.columnIndex + columnDelta,
 ));
 const target = targetRow.cells.find((cell) => (
 !cell.hidden
 && cell.grid_column_index <= targetColumn
 && cell.grid_column_index + cell.column_span > targetColumn
 ));
 if (target) selectCell(target.cell_id);
 };

 const handleKeyDown = (event) => {
 if (event.key === "Escape") {
 if (error) setError("");
 else onClose?.();
 return;
 }
 if (!event.altKey) return;
 const moves = {
 ArrowUp: [-1, 0],
 ArrowDown: [1, 0],
 ArrowLeft: [0, -1],
 ArrowRight: [0, 1],
 };
 const move = moves[event.key];
 if (move) {
 event.preventDefault();
 moveSelection(...move);
 }
 };

 return (
 <section
 className={`structured-table-designer ${inspectorOpen ? "inspector-open" : "inspector-closed"} ${isDedicatedDocumentObject ? `document-object ${objectRole}` : ""}`}
 aria-label="医学写作结构化表格设计器"
 onKeyDown={handleKeyDown}
 >
 <header className="std-titlebar">
 <div className="std-title-identity">
 <Table2 size={18} aria-hidden="true" />
 <div>
 <strong title={blockTitle(draftBlock)}>{blockTitle(draftBlock)}</strong>
 <span title={compactSourceBoundary(draftBlock)}>{compactSourceBoundary(draftBlock)}</span>
 </div>
 </div>
 <div className="std-title-status">
 <span className={readOnly ? "std-status read-only" : "std-status editable"}>
 {readOnly ? <LockKeyhole size={13} aria-hidden="true" /> : <PencilLine size={13} aria-hidden="true" />}
 {readOnly ? "原始来源只读" : "工作副本可编辑"}
 </span>
 <span className="std-domain-label">{objectRoleLabel || (isSoa ? "研究流程表" : (activeDomainProfile?.label || "通用结构化表格"))}</span>
 <IconButton label={inspectorOpen ? "收起属性检查器" : "展开属性检查器"} icon={inspectorOpen ? PanelRightClose : PanelRightOpen} onClick={() => setInspectorOpen((value) => !value)} />
 <IconButton label="关闭表格设计器" icon={X} onClick={() => onClose?.()} />
 </div>
 </header>

 <div className="std-toolbar" role="toolbar" aria-label="表格结构工具">
 {isDedicatedDocumentObject && (
 <div className="std-document-object-boundary">
 <strong>{objectRoleLabel}</strong>
 <span>{isLayoutObject ? "用于首页、签字页或联系信息排版，不进入正文表目录。" : "对应 M11 1.1；按实际 Word 表格编辑，不参与正文表格编号。"}</span>
 </div>
 )}
 <div className="std-tool-group">
 <span><Rows3 size={14} aria-hidden="true" />行</span>
 <IconButton label="新增下一行" icon={Plus} disabled={readOnly} onClick={addRow} />
 <IconButton label="删除当前行" icon={Trash2} disabled={readOnly || !selected} onClick={deleteRow} />
 <IconButton label="当前行上移" icon={ArrowUp} disabled={readOnly || !selected} onClick={() => moveRow(-1)} />
 <IconButton label="当前行下移" icon={ArrowDown} disabled={readOnly || !selected} onClick={() => moveRow(1)} />
 </div>
 <div className="std-tool-group">
 <span><Columns3 size={14} aria-hidden="true" />列</span>
 <IconButton label="新增右侧列" icon={Plus} disabled={readOnly} onClick={addColumn} />
 <IconButton label="删除当前列" icon={Trash2} disabled={readOnly || !selected} onClick={deleteColumn} />
 <IconButton label="当前列左移" icon={ArrowLeft} disabled={readOnly || !selected} onClick={() => moveColumn(-1)} />
 <IconButton label="当前列右移" icon={ArrowRight} disabled={readOnly || !selected} onClick={() => moveColumn(1)} />
 </div>
 <div className="std-tool-group">
 <span><LayoutPanelTop size={14} aria-hidden="true" />结构</span>
 <IconButton label="合并所选规则矩形" icon={Merge} disabled={readOnly || !selected} onClick={mergeCells} />
 <IconButton label="拆分当前合并单元格" icon={Split} disabled={readOnly || !selected} onClick={splitCell} />
 {CELL_ROLES.map((role) => (
 <button
 key={role.value}
 type="button"
 className="std-text-button"
 disabled={readOnly || !selected}
 aria-label={`设为${role.label}行`}
 onClick={() => setRowRole(role.value)}
 >
 {role.label}
 </button>
 ))}
 </div>
 <div className="std-tool-hint">Shift+点击选择矩形；Alt+方向键移动焦点</div>
 </div>

 <TableCellRichEditor
 key={selected?.cell?.cell_id || "no-selected-cell"}
 cell={selected ? {
 ...selected.cell,
 rowIndex: selected.rowIndex,
 columnIndex: selected.columnIndex,
 } : null}
 readOnly={readOnly}
 documentIndex={documentIndex}
 focusRequest={cellEditorFocusRequest}
 onNavigateCell={navigateEditableCell}
 onChange={(patch) => {
 if (!selected?.cell?.cell_id) return;
 updateCell(selected.cell.cell_id, () => patch);
 }}
 />

 <div className="std-feedback-row">
 {error && (
 <div className="std-error" role="alert">
 <AlertTriangle size={15} aria-hidden="true" />
 <span>{error}</span>
 <button type="button" aria-label="关闭错误提示" onClick={() => setError("")}><X size={14} /></button>
 </div>
 )}
 </div>

 <div className="std-workspace">
 <main className="std-grid-region" aria-label="结构化表格网格">
 <div className="std-grid-meta">
 <span>{model.rows.length} 行 × {model.columns.length} 列</span>
 <span>{headerRowCount} 行冻结表头</span>
 <span>{notes.length} 条附注</span>
 {rectangle && (rectangle.top !== rectangle.bottom || rectangle.left !== rectangle.right) && (
 <span className="selection-summary">已选 {rectangle.bottom - rectangle.top + 1} × {rectangle.right - rectangle.left + 1}</span>
 )}
 </div>
 <div className="std-grid-scroll" tabIndex={0} aria-label="可水平和垂直滚动的表格画布">
 <table className="std-grid-table">
 <tbody>
 {model.rows.map((row, rowIndex) => {
 const headerIndex = row.style_role === "header" || rowIndex < headerRowCount
 ? Math.min(rowIndex, headerRowCount - 1)
 : -1;
 return (
 <tr key={row.row_id} data-row-id={row.row_id} data-style-role={row.style_role}>
 {row.cells.filter((cell) => !cell.hidden).map((cell) => {
 const inSelection = rectangle
 && rowIndex >= rectangle.top
 && rowIndex <= rectangle.bottom
 && cell.grid_column_index >= rectangle.left
 && cell.grid_column_index <= rectangle.right;
 const isSelected = cell.cell_id === selectedCellId;
 const cellRevision = cellRevisionThreads.find((thread) => (
 thread?.table_cell_anchor?.cell_id === cell.cell_id
 && thread?.table_cell_anchor?.table_id === (draftBlock?.table_id || draftBlock?.structured_table?.table_id)
 && thread.status !== "rejected"
 ));
 const CellTag = headerIndex >= 0
 || cell.style_role === "header"
 || row.style_role === "header"
 ? "th"
 : "td";
 return (
 <CellTag
 key={cell.cell_id}
 rowSpan={cell.row_span}
 colSpan={cell.column_span}
 data-cell-id={cell.cell_id}
 data-style-role={cell.style_role}
 className={`${cell.grid_column_index === 0 ? "sticky-first-column" : ""} ${headerIndex >= 0 ? "sticky-header" : ""} ${isSelected ? "selected" : ""} ${inSelection ? "in-selection" : ""}`}
 style={{ "--std-header-index": Math.max(headerIndex, 0) }}
 onClick={(event) => selectCell(cell.cell_id, event.shiftKey, !event.shiftKey)}
 >
 <button
 type="button"
 className="std-readonly-cell std-cell-select-button"
 aria-label={`${readOnly ? "选择" : "编辑"}第 ${rowIndex + 1} 行第 ${cell.grid_column_index + 1} 列：${String(cell.text || "空白")}`}
 title={String(cell.text || "")}
 onClick={(event) => {
 event.stopPropagation();
 selectCell(cell.cell_id, event.shiftKey, !event.shiftKey);
 }}
 >
 {String(cell.text || "")}
 </button>
 {(cell.note_refs || []).length > 0 && (
 <span className="std-cell-note-marker" title="该单元格含结构化附注">
 {(cell.note_refs || []).length}
 </span>
 )}
 {cellRevision && (
 <span
 className="std-cell-ai-marker"
 title={cellRevision.status === "medically_approved" ? "该单元格有医学已批准的AI修订" : "该单元格有待医学处置的AI修订"}
 aria-label="该单元格有AI修订线程"
 >
 <Sparkles size={10} />
 </span>
 )}
 </CellTag>
 );
 })}
 </tr>
 );
 })}
 </tbody>
 </table>
 </div>
 </main>

 {inspectorOpen && (
 <aside className="std-inspector" aria-label="表格属性检查器">
 <div className={`std-inspector-tabs ${activeDomainProfile ? "has-domain" : ""}`} role="tablist" aria-label="属性检查器视图">
 <button type="button" role="tab" aria-selected={inspectorTab === "properties"} className={inspectorTab === "properties" ? "active" : ""} onClick={() => setInspectorTab("properties")}>属性</button>
 {activeDomainProfile && <button type="button" role="tab" aria-selected={inspectorTab === "domain"} className={inspectorTab === "domain" ? "active" : ""} onClick={() => setInspectorTab("domain")}>领域</button>}
 <button type="button" role="tab" aria-selected={inspectorTab === "notes"} className={inspectorTab === "notes" ? "active" : ""} onClick={() => setInspectorTab("notes")}>附注 {notes.length}</button>
 <button type="button" role="tab" aria-selected={inspectorTab === "layout"} className={inspectorTab === "layout" ? "active" : ""} onClick={() => setInspectorTab("layout")}>Word</button>
 </div>

 {inspectorTab === "properties" && (
 <div className="std-inspector-body">
 <section className="std-property-section">
 <div className="std-section-heading">
 <h3>{isLayoutObject ? "排版对象信息" : isSynopsisObject ? "方案摘要表信息" : "表格信息"}</h3>
 {sourceCaption && (
 sourceCaption.review_status === "confirmed"
 ? <span className="std-confirmed"><Check size={12} />表题已确认</span>
 : <span className="std-pending">表题待确认</span>
 )}
 </div>
 <label className="std-field">
 <span>{isLayoutObject ? "对象名称" : isSynopsisObject ? "摘要名称" : "表题"}</span>
 <input
 value={blockTitle(draftBlock) === "未命名表格" ? "" : blockTitle(draftBlock)}
 disabled={readOnly}
 aria-label="表格标题"
 placeholder="输入表题"
 onChange={(event) => updateTableTitle(event.target.value)}
 />
 </label>
 {!isDedicatedDocumentObject && !isSoa && suggestedDomain === SOA_DOMAIN && (
 <div className="std-mapping-boundary">
 当前表格来自研究流程表章节，尚未建立研究流程语义。可在工作副本中建立待确认映射；系统不会自动确认或改写原始来源表。
 <button type="button" disabled={readOnly} onClick={adoptSuggestedSoaDomain}>建立待确认映射</button>
 </div>
 )}
 {!isDedicatedDocumentObject && !isSoa && (
 <label className="std-field">
 <span>表格类型</span>
 <select
 value={domain}
 disabled={readOnly}
 aria-label="结构化表格类型"
 onChange={(event) => updateDomain(event.target.value)}
 >
 <option value="generic">通用结构化表格</option>
 {domainProfiles.map((profile) => (
 <option key={profile.profile_id} value={profile.domain}>{profile.label}</option>
 ))}
 </select>
 </label>
 )}
 {sourceCaption && (
 <div className="std-association-detail">
 {sourceCaptionText && (
 <p><strong>来源表题：</strong>{sourceCaptionText}</p>
 )}
 {sourceCaption.association_reason && <p>{sourceCaption.association_reason}</p>}
 {sourceCaption.source_locator && (
 <small title={sourceCaption.source_locator}>来源：{sourceCaption.source_locator}</small>
 )}
 {sourceCaption.review_status !== "confirmed" && (
 <button
 type="button"
 className="std-confirm-button"
 disabled={readOnly}
 onClick={confirmCaptionAssociation}
 ><Check size={14} />确认表题关联</button>
 )}
 </div>
 )}
 </section>
 <section className="std-property-section">
 <h3>当前单元格</h3>
 {selected ? (
 <>
 <dl className="std-identity-list">
 <div><dt>稳定 ID</dt><dd title={selected.cell.cell_id}>{selected.cell.cell_id}</dd></div>
 <div><dt>位置</dt><dd>第 {selected.rowIndex + 1} 行 / 第 {selected.columnIndex + 1} 列</dd></div>
 <div><dt>跨度</dt><dd>{selected.cell.row_span} 行 × {selected.cell.column_span} 列</dd></div>
 </dl>
 <label className="std-field">
 <span>样式角色</span>
 <select
 value={selected.cell.style_role || "body"}
 disabled={readOnly}
 aria-label="当前单元格样式角色"
 onChange={(event) => updateCell(selected.cell.cell_id, () => ({ style_role: event.target.value }))}
 >
 {CELL_ROLES.map((role) => <option key={role.value} value={role.value}>{role.label}</option>)}
 </select>
 </label>
 </>
 ) : <p className="std-empty">选择单元格后查看和修改属性。</p>}
 </section>

 {isSoa && (
 <section className="std-property-section soa-properties">
 <div className="std-section-heading">
 <h3>研究流程属性</h3>
 {draftBlock?.structured_table?.soa?.confirmed_by_user
 ? <span className="std-confirmed"><Check size={12} />已确认</span>
 : <span className="std-pending">待人工确认</span>}
 </div>
 {!draftBlock?.structured_table?.soa && (
 <div className="std-mapping-boundary">
 当前仅有原始表格结构。可建立待确认映射，再由医学用户逐项确认；系统不会标记为 AI 已完成。
 <button type="button" disabled={readOnly} onClick={mapSoaMetadata}>建立待确认映射</button>
 </div>
 )}
 <label className="std-field">
 <span>单元格类型</span>
 <select
 value={selected?.cell?.soa?.kind || "activity_plan"}
 disabled={readOnly || !selected}
 aria-label="研究流程单元格类型"
 onChange={(event) => updateSoaCell({ kind: event.target.value })}
 >
 <option value="epoch">阶段</option>
 <option value="visit">访视</option>
 <option value="timing">研究日/周与时间窗</option>
 <option value="activity">活动</option>
 <option value="activity_plan">计划状态</option>
 </select>
 </label>
 <div className="std-field-row">
 <label className="std-field"><span>研究日</span><input type="number" value={selected?.cell?.soa?.nominal_day ?? ""} disabled={readOnly || !selected} aria-label="名义研究日" onChange={(event) => updateSoaCell({ nominal_day: event.target.value === "" ? null : Number(event.target.value) })} /></label>
 <label className="std-field"><span>研究周</span><input type="number" step="0.5" value={selected?.cell?.soa?.nominal_week ?? ""} disabled={readOnly || !selected} aria-label="名义研究周" onChange={(event) => updateSoaCell({ nominal_week: event.target.value === "" ? null : Number(event.target.value) })} /></label>
 </div>
 <div className="std-field-row">
 <label className="std-field"><span>窗前（天）</span><input type="number" min="0" value={selected?.cell?.soa?.window_before_days ?? ""} disabled={readOnly || !selected} aria-label="访视窗提前天数" onChange={(event) => updateSoaCell({ window_before_days: event.target.value === "" ? null : Number(event.target.value) })} /></label>
 <label className="std-field"><span>窗后（天）</span><input type="number" min="0" value={selected?.cell?.soa?.window_after_days ?? ""} disabled={readOnly || !selected} aria-label="访视窗延后天数" onChange={(event) => updateSoaCell({ window_after_days: event.target.value === "" ? null : Number(event.target.value) })} /></label>
 </div>
 <label className="std-field"><span>活动分组</span><input value={selected?.cell?.soa?.activity_group || ""} disabled={readOnly || !selected} aria-label="研究活动分组" onChange={(event) => updateSoaCell({ activity_group: event.target.value })} placeholder="例如：安全性评估" /></label>
 <fieldset className="std-plan-states" disabled={readOnly || !selected}>
 <legend>计划状态</legend>
 {PLAN_STATES.map((state) => (
 <button
 type="button"
 key={state.value}
 className={selected?.cell?.soa?.plan_state === state.value ? "active" : ""}
 aria-label={`设为${state.label}`}
 onClick={() => updatePlanState(state.value)}
 >{state.label}</button>
 ))}
 </fieldset>
 <button
 type="button"
 className="std-confirm-button"
 disabled={readOnly || !draftBlock?.structured_table?.soa}
 onClick={() => emitMutation((next) => {
 next.structured_table.soa = {
 ...(next.structured_table.soa || {}),
 mapping_status: "confirmed_by_user",
 confirmed_by_user: true,
 };
 return { selectId: selectedCellId };
 })}
 ><Check size={14} />确认当前映射</button>
 </section>
 )}
 </div>
 )}

 {inspectorTab === "domain" && activeDomainProfile && (
 <div className="std-inspector-body">
 <section className="std-property-section std-domain-profile-properties">
 <div className="std-section-heading">
 <h3>领域属性</h3>
 {domainProfileState.confirmed_by_user
 ? <span className="std-confirmed"><Check size={12} />已确认</span>
 : <span className="std-pending">{domainMappingLabel}</span>}
 </div>
 <p className="std-domain-purpose">{activeDomainProfile.purpose}</p>
 {activeDomainProfile.warning_text && (
 <div className="std-domain-warning"><AlertTriangle size={14} />{activeDomainProfile.warning_text}</div>
 )}
 {activeDomainProfile.designer_status === "guarded" && (
 <label className="std-domain-confirmation">
 <input
 type="checkbox"
 checked={Boolean(domainProfileState.project_evidence_confirmed_by_user)}
 disabled={readOnly}
 onChange={(event) => updateProjectEvidenceConfirmation(event.target.checked)}
 />
 <span>已根据当前项目方案核对阈值、试验用药处置、复测和恢复条件</span>
 </label>
 )}
 <div className="std-mapping-boundary">
 领域映射只描述当前表格各列的业务含义，不会把其他项目的医学内容带入本项目。
 <button type="button" disabled={readOnly} onClick={mapDomainProfile}>建立待确认映射</button>
 </div>
 <label className="std-field">
 <span>记录方向</span>
 <select
 value={domainRecordAxis}
 disabled={readOnly}
 aria-label="领域表格记录方向"
 onChange={(event) => updateDomainRecordAxis(event.target.value)}
 >
 <option value="semantic_only">仅映射字段，不按行校验</option>
 <option value="rows">每行一条记录</option>
 </select>
 </label>
 <label className="std-field">
 <span>当前列语义角色</span>
 <select
 value={selected?.column?.semantic_role || ""}
 disabled={readOnly || !selected}
 aria-label="当前列语义角色"
 onChange={(event) => updateColumnSemanticRole(event.target.value)}
 >
 <option value="">未映射</option>
 {activeDomainProfile.column_roles.map((role) => (
 <option key={role.role_id} value={role.role_id}>
 {role.label}{role.required ? "（必需）" : ""}
 </option>
 ))}
 </select>
 </label>
 {selectedDomainRole && (
 <div className="std-role-detail">
 <strong>{selectedDomainRole.label}</strong>
 <p>{selectedDomainRole.description}</p>
 </div>
 )}
 {selectedDomainRole?.options?.length > 0 && selected && (
 <label className="std-field">
 <span>当前单元格快速录入</span>
 <input
 list={`std-options-${activeDomainProfile.profile_id}-${selectedDomainRole.role_id}`}
 value={String(selected.cell.text || "")}
 disabled={readOnly}
 aria-label="领域字段快速录入"
 onChange={(event) => updateCell(selected.cell.cell_id, () => ({ text: event.target.value }))}
 />
 <datalist id={`std-options-${activeDomainProfile.profile_id}-${selectedDomainRole.role_id}`}>
 {selectedDomainRole.options.map((option) => <option key={option} value={option} />)}
 </datalist>
 <small>可从建议项选择，也允许自定义输入；当前医学经理确认后写入工作副本。</small>
 </label>
 )}
 {selectedDomainRole?.control === "date" && selected && (
 <label className="std-field">
 <span>当前单元格日期</span>
 <input
 type="date"
 value={String(selected.cell.text || "")}
 disabled={readOnly}
 aria-label="领域日期字段快速录入"
 onChange={(event) => updateCell(selected.cell.cell_id, () => ({ text: event.target.value }))}
 />
 <small>日期写入当前可见表格单元格，并随同一工作副本和 Word 导出链保存。</small>
 </label>
 )}
 <div className="std-domain-role-list" aria-label="领域字段映射概览">
 {activeDomainProfile.column_roles.map((role) => (
 <div key={role.role_id} className={mappedSemanticRoles.has(role.role_id) ? "mapped" : "unmapped"}>
 <span>{role.label}{role.required ? " *" : ""}</span>
 <strong>{mappedSemanticRoles.has(role.role_id) ? "已映射" : "未映射"}</strong>
 </div>
 ))}
 </div>
 {domainRecordAxis === "rows" && (
 <p className={incompleteDomainRows.length ? "std-domain-row-check warning" : "std-domain-row-check"}>
 {incompleteDomainRows.length
 ? `${incompleteDomainRows.length} 行仍缺少必需内容；可保存草稿，但不能确认并冻结。`
 : "当前已填写记录未发现必需字段缺失。"}
 </p>
 )}
 <button
 type="button"
 className="std-confirm-button"
 disabled={readOnly}
 onClick={confirmDomainMapping}
 ><Check size={14} />确认当前领域映射</button>
 </section>
 </div>
 )}

 {inspectorTab === "notes" && (
 <div className="std-inspector-body">
 <div className="std-section-heading">
 <h3>结构化附注</h3>
 <button type="button" className="std-add-note" disabled={readOnly} onClick={addNote}><Plus size={14} />新增</button>
 </div>
 <p className="std-note-boundary">附注绑定稳定对象 ID；单元格坐标仅用于当前显示。</p>
 <div className="std-note-list">
 {notes.map((note) => (
 <article key={note.note_id} className="std-note-item">
 <div className="std-note-head">
 <span><StickyNote size={13} />附注 {note.marker || "-"}</span>
 <span className={note.review_status === "confirmed" ? "std-confirmed" : "std-pending"}>
 {note.review_status === "confirmed" ? <><Check size={12} />已确认</> : "待确认"}
 </span>
 <IconButton label="删除附注" icon={Trash2} disabled={readOnly} onClick={() => deleteNote(note.note_id)} />
 </div>
 <label className="std-field"><span>类型</span><select value={note.note_type || "operational"} disabled={readOnly} aria-label={`附注 ${note.marker || note.note_id} 类型`} onChange={(event) => updateNote(note.note_id, { note_type: event.target.value })}>{NOTE_TYPES.map((type) => <option key={type.value} value={type.value}>{type.label}</option>)}</select></label>
 <label className="std-field"><span>内容</span><textarea value={note.text || ""} disabled={readOnly} rows={4} aria-label={`附注 ${note.marker || note.note_id} 内容`} onChange={(event) => updateNote(note.note_id, { text: event.target.value })} /></label>
 <div className="std-note-provenance">
 {note.association_reason && <p>{note.association_reason}</p>}
 <small title={(note.target_ids || []).join("；")}>绑定：{(note.target_ids || []).join("；") || "未绑定"}</small>
 {(note.source_refs || []).length > 0 && (
 <small title={note.source_refs.join("；")}>来源：{note.source_refs.join("；")}</small>
 )}
 </div>
 {note.review_status !== "confirmed" && (
 <button
 type="button"
 className="std-confirm-button"
 disabled={readOnly}
 onClick={() => confirmNoteAssociation(note.note_id)}
 ><Check size={14} />确认附注关联</button>
 )}
 </article>
 ))}
 {!notes.length && <p className="std-empty">暂无结构化附注。</p>}
 </div>
 </div>
 )}

 {inspectorTab === "layout" && (
 <div className="std-inspector-body">
 <section className="std-property-section">
 <h3>Word 页面方向</h3>
 <div className="std-orientation-control" role="group" aria-label="Word 页面方向">
 <button type="button" className={wordOrientation === "landscape" ? "active" : ""} disabled={readOnly} onClick={() => updateWordLayout("landscape")}>横向</button>
 <button type="button" className={wordOrientation === "portrait" ? "active" : ""} disabled={readOnly} onClick={() => updateWordLayout("portrait")}>纵向</button>
 </div>
 <label className="std-field"><span>长表拆页</span><select value={draftBlock?.structured_table?.word_layout?.split_strategy || "repeat_header"} disabled={readOnly} aria-label="Word 长表拆页策略" onChange={(event) => emitMutation((next) => {
 next.structured_table.word_layout = { ...(next.structured_table.word_layout || {}), split_strategy: event.target.value };
 return { selectId: selectedCellId };
 })}><option value="repeat_header">自动拆页并重复表头</option><option value="horizontal_panels">按列分面拆页</option></select></label>
 <label className="std-field"><span>分面重复首列数</span><input type="number" min="0" max={model.columns.length} value={draftBlock?.structured_table?.word_layout?.frozen_column_count ?? 1} disabled={readOnly} aria-label="Word 分面重复首列数量" onChange={(event) => emitMutation((next) => {
 next.structured_table.word_layout = { ...(next.structured_table.word_layout || {}), frozen_column_count: Number(event.target.value) };
 return { selectId: selectedCellId };
 })} /></label>
 </section>
 </div>
 )}
 </aside>
 )}
 </div>
 </section>
 );
}

export default StructuredTableDesigner;

import { useEffect, useMemo, useRef, useState } from "react";
import {
 AlertTriangle,
 ArrowDown,
 ArrowLeft,
 ArrowRight,
 ArrowUp,
 CheckCircle2,
 CheckCheck,
 GitCompare,
 Maximize2,
 Minimize2,
 Plus,
 RefreshCw,
 RotateCcw,
 Save,
 SendToBack,
 Trash2,
 Undo2,
 Redo2,
 ZoomIn,
 ZoomOut,
} from "lucide-react";

const NODE_KINDS = [
 ["entry", "起点"],
 ["screening", "筛选"],
 ["run_in", "导入期"],
 ["randomization", "随机"],
 ["allocation", "分配"],
 ["arm", "研究臂"],
 ["dose_cohort", "剂量队列"],
 ["treatment", "治疗/给药"],
 ["treatment_switch", "治疗转组"],
 ["extension_period", "开放标签延展期"],
 ["decision_gate", "决策门"],
 ["follow_up", "随访"],
 ["end", "结束"],
 ["other", "其他"],
];

const EDGE_KINDS = [
 ["participant_flow", "受试者流转"],
 ["activation_dependency", "队列启用条件"],
 ["randomization", "随机分配"],
 ["conditional", "条件分支"],
 ["treatment_switch", "转为其他治疗"],
 ["treatment_continuation", "继续原治疗"],
 ["discontinuation", "中止/退出"],
 ["follow_up", "进入随访"],
];

function apiErrorText(error) {
 if (typeof error?.detail === "string") return error.detail;
 if (Array.isArray(error?.detail)) return error.detail.map((item) => item.msg).join("；");
 return error?.message || "请求失败";
}

async function readJson(response) {
 const payload = await response.json().catch(() => ({}));
 if (!response.ok) throw payload;
 return payload;
}

function svgDataUrl(svg) {
 return svg ? `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}` : "";
}

function clamp(value, minimum, maximum) {
 return Math.min(maximum, Math.max(minimum, value));
}

export function StudySchemaEditor({ projectId, sectionId, readOnly = false }) {
 const [snapshot, setSnapshot] = useState(null);
 const [workingCopy, setWorkingCopy] = useState(null);
 const [draft, setDraft] = useState(null);
 const [preview, setPreview] = useState(null);
 const [busy, setBusy] = useState("");
 const [message, setMessage] = useState("");
 const [activePanel, setActivePanel] = useState("nodes");
 const [selectedNodeId, setSelectedNodeId] = useState("");
 const [selectedEdgeId, setSelectedEdgeId] = useState("");
 const [changeReason, setChangeReason] = useState("");
 const [fullscreen, setFullscreen] = useState(false);
 const [zoom, setZoom] = useState(1);
 const [historyState, setHistoryState] = useState({ undo: 0, redo: 0 });
 const undoStack = useRef([]);
 const redoStack = useRef([]);
 const previewRequestSequence = useRef(0);

 const base = `/api/projects/${projectId}/medical-writing/authoring-journey/study-schema`;
 const currentSvg = preview?.svg || snapshot?.svg || "";
 const svgPresentation = useMemo(() => {
 const width = Number(currentSvg.match(/<svg\b[^>]*\bwidth="([0-9.]+)"/)?.[1] || 0);
 const height = Number(currentSvg.match(/<svg\b[^>]*\bheight="([0-9.]+)"/)?.[1] || 0);
 const nodeCount = (currentSvg.match(/data-node-id="/g) || []).length;
 return {
 width,
 height,
 nodeCount,
 wordOrientation: width >= 1600 || nodeCount >= 12 ? "横向A4" : "纵向A4",
 };
 }, [currentSvg]);
 const issues = preview?.issues || snapshot?.issues || [];
 const blockers = issues.filter((item) => item.severity === "blocker");
 const selectedNode = draft?.nodes?.find((item) => item.node_id === selectedNodeId) || null;
 const selectedEdge = draft?.edges?.find((item) => item.edge_id === selectedEdgeId) || null;
 const committed = Boolean(snapshot?.study_schema);
 const draftMatchesCommitted = draft?.state_sha256 === snapshot?.study_schema?.state_sha256;
 const committedSchemaStale = snapshot?.study_schema?.status === "stale";
 const projectedFigure = workingCopy?.content_blocks?.find((block) => block.figure_kind === "study_schema") || null;
 const figureCurrent = Boolean(
 projectedFigure
 && projectedFigure.schema_state_sha256 === snapshot?.study_schema?.state_sha256
 && projectedFigure.layout_revision === snapshot?.presentation?.layout_revision
 );

 const load = () => {
 setBusy("load");
 setMessage("");
 Promise.all([
 fetch(base).then(readJson),
 sectionId
 ? fetch(`/api/projects/${projectId}/medical-writing/working-copies/${sectionId}`).then(readJson)
 : Promise.resolve(null),
 ])
 .then(([payload, currentWorkingCopy]) => {
 setSnapshot(payload);
 setWorkingCopy(currentWorkingCopy);
 setDraft(payload.study_schema || null);
 setPreview(null);
 setSelectedNodeId(payload.study_schema?.nodes?.[0]?.node_id || "");
 setSelectedEdgeId(payload.study_schema?.edges?.[0]?.edge_id || "");
 undoStack.current = [];
 redoStack.current = [];
 setHistoryState({ undo: 0, redo: 0 });
 })
 .catch((error) => setMessage(`研究流程图读取失败：${apiErrorText(error)}`))
 .finally(() => setBusy(""));
 };

 useEffect(() => {
 load();
 }, [projectId, sectionId]);

 const invalidatePreview = () => {
 previewRequestSequence.current += 1;
 setPreview(null);
 };
 const syncHistoryState = () => setHistoryState({
 undo: undoStack.current.length,
 redo: redoStack.current.length,
 });
 const updateDraft = (updater) => {
 if (!draft) return;
 undoStack.current = [...undoStack.current.slice(-29), draft];
 redoStack.current = [];
 setDraft(updater(draft));
 syncHistoryState();
 invalidatePreview();
 setMessage("");
 };

 const undo = () => {
 if (!undoStack.current.length || !draft) return;
 const previous = undoStack.current[undoStack.current.length - 1];
 undoStack.current = undoStack.current.slice(0, -1);
 redoStack.current = [...redoStack.current.slice(-29), draft];
 setDraft(previous);
 setPreview(null);
 setMessage("已撤销上一步编辑。");
 syncHistoryState();
 };

 const redo = () => {
 if (!redoStack.current.length || !draft) return;
 const next = redoStack.current[redoStack.current.length - 1];
 redoStack.current = redoStack.current.slice(0, -1);
 undoStack.current = [...undoStack.current.slice(-29), draft];
 setDraft(next);
 setPreview(null);
 setMessage("已重做上一步编辑。");
 syncHistoryState();
 };

 const createProposal = () => {
 setBusy("proposal");
 setMessage("");
 fetch(`${base}/proposal`)
 .then(readJson)
 .then((payload) => {
 setDraft(payload);
 setPreview(null);
 setSelectedNodeId(payload.nodes?.[0]?.node_id || "");
 setActivePanel("nodes");
 undoStack.current = [];
 redoStack.current = [];
 setHistoryState({ undo: 0, redo: 0 });
 setMessage("已根据当前研究框架与PICOS生成候选图；可先整体核对，再一键确认全部候选。");
 })
 .catch((error) => setMessage(`候选图生成失败：${apiErrorText(error)}`))
 .finally(() => setBusy(""));
 };

 const updatePart = (partId, patch) => updateDraft((current) => ({
 ...current,
 parts: current.parts.map((part) => part.part_id === partId ? { ...part, ...patch } : part),
 }));

 const updateNode = (nodeId, patch, invalidateFact = true) => updateDraft((current) => ({
 ...current,
 nodes: current.nodes.map((node) => node.node_id === nodeId
 ? {
 ...node,
 ...patch,
 ...(invalidateFact && node.fact_status === "confirmed" ? { fact_status: "manual_candidate" } : {}),
 }
 : node),
 }));

 const updateEdge = (edgeId, patch, invalidateFact = true) => updateDraft((current) => ({
 ...current,
 edges: current.edges.map((edge) => edge.edge_id === edgeId
 ? {
 ...edge,
 ...patch,
 ...(invalidateFact && edge.fact_status === "confirmed" ? { fact_status: "manual_candidate" } : {}),
 }
 : edge),
 }));

 const addPart = () => updateDraft((current) => {
 const index = current.parts.length + 1;
 return {
 ...current,
 parts: [...current.parts, {
 part_id: `part_${Date.now()}`,
 order: current.parts.length,
 label: `研究部分 ${index}`,
 flow_direction: "left_to_right",
 source_bindings: [],
 }],
 };
 });

 const addNode = () => updateDraft((current) => {
 const nodeId = `node_${Date.now()}`;
 const partId = current.parts[0]?.part_id;
 const maxOrder = Math.max(-1, ...current.nodes.filter((node) => node.part_id === partId).map((node) => node.order));
 setSelectedNodeId(nodeId);
 setActivePanel("nodes");
 return {
 ...current,
 nodes: [...current.nodes, {
 node_id: nodeId,
 part_id: partId,
 order: maxOrder + 1,
 lane_order: 0,
 node_kind: "other",
 label: "新节点",
 detail_lines: [],
 fact_status: "manual_candidate",
 source_bindings: [],
 }],
 };
 });

 const deleteNode = (nodeId) => updateDraft((current) => {
 const nodes = current.nodes.filter((node) => node.node_id !== nodeId);
 setSelectedNodeId(nodes[0]?.node_id || "");
 return {
 ...current,
 nodes,
 edges: current.edges.filter((edge) => edge.from_node_id !== nodeId && edge.to_node_id !== nodeId),
 };
 });

 const addEdge = () => updateDraft((current) => {
 if (current.nodes.length < 2) return current;
 const edgeId = `edge_${Date.now()}`;
 setSelectedEdgeId(edgeId);
 setActivePanel("edges");
 return {
 ...current,
 edges: [...current.edges, {
 edge_id: edgeId,
 from_node_id: current.nodes[0].node_id,
 to_node_id: current.nodes[1].node_id,
 edge_kind: "participant_flow",
 label: "",
 fact_status: "manual_candidate",
 source_bindings: [],
 }],
 };
 });

 const deleteEdge = (edgeId) => updateDraft((current) => {
 const edges = current.edges.filter((edge) => edge.edge_id !== edgeId);
 setSelectedEdgeId(edges[0]?.edge_id || "");
 return { ...current, edges };
 });

 const confirmAllCandidates = () => updateDraft((current) => ({
 ...current,
 nodes: current.nodes.map((node) => (
 ["manual_candidate", "extracted_candidate"].includes(node.fact_status)
 ? { ...node, fact_status: "confirmed" }
 : node
 )),
 edges: current.edges.map((edge) => (
 ["manual_candidate", "extracted_candidate"].includes(edge.fact_status)
 ? { ...edge, fact_status: "confirmed" }
 : edge
 )),
 }));

 const requestPreview = ({ silent = false } = {}) => {
 if (!draft || !snapshot) return;
 const requestSequence = previewRequestSequence.current + 1;
 previewRequestSequence.current = requestSequence;
 if (!silent) {
 setBusy("preview");
 setMessage("");
 }
 fetch(`${base}/impact-preview`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 expected_journey_revision: snapshot.journey_revision,
 study_schema: draft,
 }),
 })
 .then(readJson)
 .then((payload) => {
 if (requestSequence !== previewRequestSequence.current) return;
 setPreview(payload);
 if (!silent) {
 setMessage(payload.issues?.length
 ? `预览完成：${payload.issues.filter((item) => item.severity === "blocker").length} 项阻断、${payload.issues.filter((item) => item.severity === "warning").length} 项提示。`
 : "预览完成，当前图无结构性问题。 ");
 }
 })
 .catch((error) => {
 if (requestSequence === previewRequestSequence.current) {
 setMessage(`影响预览失败：${apiErrorText(error)}`);
 }
 })
 .finally(() => {
 if (!silent && requestSequence === previewRequestSequence.current) {
 setBusy("");
 }
 });
 };

 useEffect(() => {
 if (!draft || !snapshot || readOnly) return undefined;
 if (committedSchemaStale && draftMatchesCommitted) return undefined;
 const timer = window.setTimeout(() => requestPreview({ silent: true }), 450);
 return () => window.clearTimeout(timer);
 }, [
 draft,
 snapshot?.journey_revision,
 readOnly,
 committedSchemaStale,
 draftMatchesCommitted,
 ]);

 const commit = () => {
 if (!draft || !snapshot || !preview || changeReason.trim().length < 10) return;
 setBusy("commit");
 setMessage("");
 fetch(`${base}/commit`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 expected_journey_revision: snapshot.journey_revision,
 study_schema: draft,
 impact_preview_id: preview.preview_id,
 reason: changeReason.trim(),
 actor: "medical_manager",
 idempotency_key: `study-schema-${projectId}-${Date.now()}`,
 }),
 })
 .then(readJson)
 .then((payload) => {
 setSnapshot(payload);
 setDraft(payload.study_schema);
 setPreview(null);
 setChangeReason("");
 setMessage(payload.formal_render_allowed
 ? "研究流程图已提交并形成可插入方案的正式矢量版本。"
 : "研究流程图已保存为草稿；仍有事实阻断项，暂不能插入正式方案。 ");
 })
 .catch((error) => setMessage(`研究流程图提交失败：${apiErrorText(error)}`))
 .finally(() => setBusy(""));
 };

 const saveLayout = (nextOverrides) => {
 if (!snapshot?.study_schema || !snapshot?.presentation) return;
 setBusy("layout");
 fetch(`${base}/layout`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 expected_journey_revision: snapshot.journey_revision,
 expected_schema_revision: snapshot.study_schema.revision,
 expected_layout_revision: snapshot.presentation.layout_revision,
 node_overrides: nextOverrides,
 actor: "medical_manager",
 idempotency_key: `study-schema-layout-${projectId}-${Date.now()}`,
 }),
 })
 .then(readJson)
 .then((payload) => {
 setSnapshot(payload);
 setMessage("位置微调已写入独立布局版本，未改变研究事实。 ");
 })
 .catch((error) => setMessage(`布局保存失败：${apiErrorText(error)}`))
 .finally(() => setBusy(""));
 };

 const nudgeSelectedNode = (dx, dy) => {
 if (!selectedNode || !draftMatchesCommitted) return;
 const current = snapshot.presentation?.node_overrides?.find((item) => item.node_id === selectedNode.node_id) || { node_id: selectedNode.node_id, dx: 0, dy: 0 };
 const next = {
 ...current,
 dx: clamp(current.dx + dx, -48, 48),
 dy: clamp(current.dy + dy, -32, 32),
 };
 const overrides = [
 ...(snapshot.presentation?.node_overrides || []).filter((item) => item.node_id !== selectedNode.node_id),
 next,
 ];
 saveLayout(overrides);
 };

 const projectFigure = () => {
 if (!sectionId || !snapshot?.study_schema || !snapshot?.presentation || !workingCopy) return;
 setBusy("project");
 setMessage("");
 fetch(`/api/projects/${projectId}/medical-writing/working-copies/${sectionId}/study-schema-figure`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 expected_journey_revision: snapshot.journey_revision,
 expected_schema_revision: snapshot.study_schema.revision,
 expected_layout_revision: snapshot.presentation.layout_revision,
 expected_working_copy_revision: workingCopy.revision,
 actor: "medical_manager",
 reason: projectedFigure
 ? "医学经理确认以当前研究事实和布局更新方案研究流程图。"
 : "医学经理确认将当前研究流程图插入方案第1.2节。",
 idempotency_key: `study-schema-figure-${projectId}-${Date.now()}`,
 }),
 })
 .then(readJson)
 .then((payload) => {
 setWorkingCopy(payload.working_copy);
 setMessage(payload.projection_action === "inserted"
 ? "研究流程图已插入方案第1.2节，并进入工作副本版本。"
 : "方案中的研究流程图已更新为当前事实和布局版本。 ");
 })
 .catch((error) => setMessage(`插入方案失败：${apiErrorText(error)}`))
 .finally(() => setBusy(""));
 };

 const issueTargets = useMemo(() => new Map(issues.map((item) => [item.target_id, item])), [issues]);

 return (
 <section className={`study-schema-editor ${fullscreen ? "is-fullscreen" : ""}`} data-testid="study-schema-editor">
 <header className="study-schema-toolbar">
 <div>
 <span>研究流程图</span>
 <strong>{draft?.title || "研究设计概况"}</strong>
 {snapshot?.study_schema && <small>图版本 {snapshot.study_schema.revision} · 布局版本 {snapshot.presentation?.layout_revision || 0}</small>}
 {currentSvg && <small className="study-schema-output-hint">Word：{svgPresentation.wordOrientation}</small>}
 </div>
 <div className="study-schema-toolbar-actions">
 <button type="button" onClick={load} disabled={Boolean(busy)} title="重新读取服务器版本"><RefreshCw size={15} />刷新</button>
 <button type="button" onClick={undo} disabled={Boolean(busy) || readOnly || !historyState.undo} title="撤销上一步编辑"><Undo2 size={15} />撤销</button>
 <button type="button" onClick={redo} disabled={Boolean(busy) || readOnly || !historyState.redo} title="重做上一步编辑"><Redo2 size={15} />重做</button>
 {committedSchemaStale && <button type="button" className="primary-button" onClick={createProposal} disabled={Boolean(busy) || readOnly} title="研究事实已变化；按当前已确认研究框架和PICOS重新生成候选图"><RefreshCw size={15} />按当前设计重新生成</button>}
 <button
 type="button"
 onClick={confirmAllCandidates}
 disabled={Boolean(busy) || readOnly || !draft || !draft.nodes.some((node) => ["manual_candidate", "extracted_candidate"].includes(node.fact_status)) && !draft.edges.some((edge) => ["manual_candidate", "extracted_candidate"].includes(edge.fact_status))}
 title="医学经理整体核对当前候选后，一次确认全部节点和关系"
 ><CheckCheck size={15} />确认全部候选</button>
 {committed && <button type="button" onClick={() => saveLayout([])} disabled={Boolean(busy) || !draftMatchesCommitted} title="清除位置微调并恢复确定性自动布局"><RotateCcw size={15} />自动排布</button>}
 <div className="study-schema-zoom" aria-label="流程图缩放">
 <button type="button" onClick={() => setZoom((value) => clamp(value - 0.15, 0.55, 1.6))} disabled={zoom <= 0.55} title="缩小流程图"><ZoomOut size={15} /></button>
 <span>{Math.round(zoom * 100)}%</span>
 <button type="button" onClick={() => setZoom((value) => clamp(value + 0.15, 0.55, 1.6))} disabled={zoom >= 1.6} title="放大流程图"><ZoomIn size={15} /></button>
 </div>
 <button type="button" onClick={() => requestPreview()} disabled={Boolean(busy) || !draft || readOnly || committedSchemaStale && draftMatchesCommitted} title={committedSchemaStale && draftMatchesCommitted ? "研究事实已变化，请先按当前设计重新生成候选图" : "立即校验事实状态并刷新当前预览"}><GitCompare size={15} />立即预览</button>
 {committed && <button
 type="button"
 className={figureCurrent ? "" : "primary-button"}
 onClick={projectFigure}
 disabled={Boolean(busy) || readOnly || !sectionId || !workingCopy || !snapshot?.formal_render_allowed || !draftMatchesCommitted || figureCurrent}
 title={figureCurrent ? "方案中的流程图已是当前版本" : "把当前已确认流程图插入或更新到方案第1.2节"}
 ><SendToBack size={15} />{busy === "project" ? "写入中" : projectedFigure ? figureCurrent ? "已同步方案" : "更新方案" : "插入方案"}</button>}
 <button type="button" className="icon-button" onClick={() => setFullscreen((value) => !value)} title={fullscreen ? "退出最大化" : "最大化流程图编辑器"}>{fullscreen ? <Minimize2 size={17} /> : <Maximize2 size={17} />}</button>
 </div>
 </header>

 {!draft ? (
 <div className="study-schema-empty">
 <strong>尚未建立研究流程图</strong>
 <p>系统将从已确认研究框架和PICOS生成候选节点；所有节点与关系均需医学确认。</p>
 <button type="button" className="primary-button" onClick={createProposal} disabled={Boolean(busy) || readOnly}><Plus size={16} />生成候选图</button>
 </div>
 ) : (
 <div className="study-schema-workspace">
 <aside className="study-schema-structure">
 <div className="study-schema-tabs" role="tablist">
 {[["parts", "研究部分"], ["nodes", "节点"], ["edges", "关系"]].map(([id, label]) => (
 <button key={id} type="button" className={activePanel === id ? "active" : ""} onClick={() => setActivePanel(id)}>{label}</button>
 ))}
 </div>

 {activePanel === "parts" && <div className="study-schema-list">
 {draft.parts.map((part) => <article key={part.part_id} className="study-schema-form-row">
 <label><span>标题</span><input value={part.label} disabled={readOnly} onChange={(event) => updatePart(part.part_id, { label: event.target.value })} /></label>
 <div className="study-schema-inline-fields">
 <label><span>顺序</span><input type="number" min="0" value={part.order} disabled={readOnly} onChange={(event) => updatePart(part.part_id, { order: Number(event.target.value) })} /></label>
 <label><span>方向</span><select value={part.flow_direction} disabled={readOnly} onChange={(event) => updatePart(part.part_id, { flow_direction: event.target.value })}><option value="left_to_right">从左到右</option><option value="top_to_bottom">从上到下</option><option value="bottom_to_top">从下到上</option></select></label>
 </div>
 </article>)}
 {!readOnly && <button type="button" className="study-schema-add" onClick={addPart}><Plus size={14} />新增研究部分</button>}
 </div>}

 {activePanel === "nodes" && <div className="study-schema-list">
 {draft.nodes.map((node) => <button type="button" key={node.node_id} className={`study-schema-list-item ${selectedNodeId === node.node_id ? "active" : ""}`} onClick={() => setSelectedNodeId(node.node_id)}>
 <span>{NODE_KINDS.find(([id]) => id === node.node_kind)?.[1] || node.node_kind}</span>
 <strong>{node.label}</strong>
 {node.fact_status === "confirmed" ? <CheckCircle2 size={15} /> : <AlertTriangle size={15} />}
 </button>)}
 {!readOnly && <button type="button" className="study-schema-add" onClick={addNode}><Plus size={14} />新增节点</button>}
 </div>}

 {activePanel === "edges" && <div className="study-schema-list">
 {draft.edges.map((edge) => <button type="button" key={edge.edge_id} className={`study-schema-list-item ${selectedEdgeId === edge.edge_id ? "active" : ""}`} onClick={() => setSelectedEdgeId(edge.edge_id)}>
 <span>{EDGE_KINDS.find(([id]) => id === edge.edge_kind)?.[1] || edge.edge_kind}</span>
 <strong>{draft.nodes.find((node) => node.node_id === edge.from_node_id)?.label} → {draft.nodes.find((node) => node.node_id === edge.to_node_id)?.label}</strong>
 {edge.fact_status === "confirmed" ? <CheckCircle2 size={15} /> : <AlertTriangle size={15} />}
 </button>)}
 {!readOnly && <button type="button" className="study-schema-add" onClick={addEdge} disabled={draft.nodes.length < 2}><Plus size={14} />新增关系</button>}
 </div>}
 </aside>

 <main className="study-schema-canvas-column">
 <div className="study-schema-canvas">
 {currentSvg ? <img src={svgDataUrl(currentSvg)} alt="研究流程图预览" style={{ width: `${zoom * 100}%` }} /> : <div className="study-schema-canvas-placeholder">候选图将在编辑停顿后自动生成。</div>}
 </div>
 <div className="study-schema-legend"><span><i className="candidate" />候选事实</span><span><i className="confirmed" />已确认事实</span><span>虚线关系：队列启用条件/条件分支</span></div>
 </main>

 <aside className="study-schema-inspector">
 {activePanel === "nodes" && selectedNode ? <>
 <header><span>节点属性</span><strong>{selectedNode.label}</strong></header>
 <label><span>节点名称</span><input value={selectedNode.label} disabled={readOnly} onChange={(event) => updateNode(selectedNode.node_id, { label: event.target.value })} /></label>
 <label><span>节点类型</span><select value={selectedNode.node_kind} disabled={readOnly} onChange={(event) => updateNode(selectedNode.node_id, { node_kind: event.target.value })}>{NODE_KINDS.map(([id, label]) => <option value={id} key={id}>{label}</option>)}</select></label>
 <label><span>所属部分</span><select value={selectedNode.part_id} disabled={readOnly} onChange={(event) => updateNode(selectedNode.node_id, { part_id: event.target.value })}>{draft.parts.map((part) => <option value={part.part_id} key={part.part_id}>{part.label}</option>)}</select></label>
 <div className="study-schema-inline-fields"><label><span>流程层级</span><input type="number" min="0" value={selectedNode.order} disabled={readOnly} onChange={(event) => updateNode(selectedNode.node_id, { order: Number(event.target.value) })} /></label><label><span>同层分支</span><input type="number" min="0" max="20" value={selectedNode.lane_order || 0} disabled={readOnly} onChange={(event) => updateNode(selectedNode.node_id, { lane_order: Number(event.target.value) })} /></label></div>
 <label><span>补充说明（每行一条）</span><textarea rows="4" value={(selectedNode.detail_lines || []).join("\n")} disabled={readOnly} onChange={(event) => updateNode(selectedNode.node_id, { detail_lines: event.target.value.split("\n").map((line) => line.trim()).filter(Boolean) })} /></label>
 <div className="study-schema-fact-state"><span>事实状态</span><strong>{selectedNode.fact_status === "confirmed" ? "医学已确认" : "待医学确认"}</strong>{!readOnly && <button type="button" onClick={() => updateNode(selectedNode.node_id, { fact_status: selectedNode.fact_status === "confirmed" ? "manual_candidate" : "confirmed" }, false)}>{selectedNode.fact_status === "confirmed" ? "撤回确认" : "确认该节点"}</button>}</div>
 <div className="study-schema-nudge"><span>位置微调</span><div><button type="button" title="向上微调" disabled={!draftMatchesCommitted || Boolean(busy)} onClick={() => nudgeSelectedNode(0, -8)}><ArrowUp size={15} /></button><button type="button" title="向左微调" disabled={!draftMatchesCommitted || Boolean(busy)} onClick={() => nudgeSelectedNode(-8, 0)}><ArrowLeft size={15} /></button><button type="button" title="向右微调" disabled={!draftMatchesCommitted || Boolean(busy)} onClick={() => nudgeSelectedNode(8, 0)}><ArrowRight size={15} /></button><button type="button" title="向下微调" disabled={!draftMatchesCommitted || Boolean(busy)} onClick={() => nudgeSelectedNode(0, 8)}><ArrowDown size={15} /></button></div><small>单次 8 px，横向最多 ±48 px，纵向最多 ±32 px；不改变研究事实。</small></div>
 {!readOnly && <button type="button" className="danger-button" onClick={() => deleteNode(selectedNode.node_id)} disabled={draft.nodes.length <= 1}><Trash2 size={14} />删除节点</button>}
 </> : activePanel === "edges" && selectedEdge ? <>
 <header><span>关系属性</span><strong>{EDGE_KINDS.find(([id]) => id === selectedEdge.edge_kind)?.[1]}</strong></header>
 <label><span>起点</span><select value={selectedEdge.from_node_id} disabled={readOnly} onChange={(event) => updateEdge(selectedEdge.edge_id, { from_node_id: event.target.value })}>{draft.nodes.map((node) => <option value={node.node_id} key={node.node_id}>{node.label}</option>)}</select></label>
 <label><span>终点</span><select value={selectedEdge.to_node_id} disabled={readOnly} onChange={(event) => updateEdge(selectedEdge.edge_id, { to_node_id: event.target.value })}>{draft.nodes.map((node) => <option value={node.node_id} key={node.node_id}>{node.label}</option>)}</select></label>
 <label><span>关系类型</span><select value={selectedEdge.edge_kind} disabled={readOnly} onChange={(event) => updateEdge(selectedEdge.edge_id, { edge_kind: event.target.value })}>{EDGE_KINDS.map(([id, label]) => <option value={id} key={id}>{label}</option>)}</select></label>
 <label><span>关系标签</span><input value={selectedEdge.label || ""} disabled={readOnly} onChange={(event) => updateEdge(selectedEdge.edge_id, { label: event.target.value })} placeholder={selectedEdge.edge_kind === "conditional" ? "条件分支必须填写" : "可选"} /></label>
 <div className="study-schema-fact-state"><span>事实状态</span><strong>{selectedEdge.fact_status === "confirmed" ? "医学已确认" : "待医学确认"}</strong>{!readOnly && <button type="button" onClick={() => updateEdge(selectedEdge.edge_id, { fact_status: selectedEdge.fact_status === "confirmed" ? "manual_candidate" : "confirmed" }, false)}>{selectedEdge.fact_status === "confirmed" ? "撤回确认" : "确认该关系"}</button>}</div>
 {!readOnly && <button type="button" className="danger-button" onClick={() => deleteEdge(selectedEdge.edge_id)}><Trash2 size={14} />删除关系</button>}
 </> : <div className="study-schema-inspector-empty">选择一个节点或关系进行编辑。</div>}
 </aside>
 </div>
 )}

 {draft && <footer className="study-schema-footer">
 <div className="study-schema-issues">
 <strong>{blockers.length ? `${blockers.length} 项阻断正式插入` : preview ? "当前无阻断项" : "请先执行影响预览"}</strong>
 {issues.slice(0, 3).map((issue) => <span key={issue.issue_id} className={issue.severity}>{issue.message}</span>)}
 {issues.length > 3 && <small>另有 {issues.length - 3} 项，请在对应节点或关系中核对。</small>}
 </div>
 {!readOnly && <div className="study-schema-commit">
 <label><span>变更理由</span><input value={changeReason} onChange={(event) => setChangeReason(event.target.value)} placeholder="至少10个字，说明本次医学确认或调整依据" /></label>
 <button type="button" className="primary-button" onClick={commit} disabled={Boolean(busy) || !preview || changeReason.trim().length < 10}><Save size={15} />{busy === "commit" ? "提交中" : "提交当前版本"}</button>
 </div>}
 </footer>}
 {message && <p className={`study-schema-message ${/失败|冲突|错误/.test(message) ? "danger" : ""}`}>{message}</p>}
 </section>
 );
}

import { useEffect, useRef, useState } from "react";
import { EditorContent, useEditor } from "@tiptap/react";
import { Extension } from "@tiptap/core";
import StarterKit from "@tiptap/starter-kit";
import TextAlign from "@tiptap/extension-text-align";
import Highlight from "@tiptap/extension-highlight";
import Subscript from "@tiptap/extension-subscript";
import Superscript from "@tiptap/extension-superscript";
import { Color, FontFamily, FontSize, TextStyle } from "@tiptap/extension-text-style";
import {
 AlignCenter,
 AlignJustify,
 AlignLeft,
 AlignRight,
 Bold,
 Eraser,
 Highlighter,
 IndentDecrease,
 IndentIncrease,
 Italic,
 List,
 ListOrdered,
 Link2,
 Palette,
 Redo2,
 Subscript as SubscriptIcon,
 Superscript as SuperscriptIcon,
 Underline as UnderlineIcon,
 Undo2,
} from "lucide-react";
import { WordEditingShortcuts } from "./WordEditingShortcuts";
import {
 CrossReferenceMark,
 insertCrossReference,
} from "./CrossReferenceMark";

const PARAGRAPH_DEFAULTS = {
 stylePreset: null,
 lineHeight: null,
 spacingBeforePt: null,
 spacingAfterPt: null,
 leftIndentChars: null,
 rightIndentChars: null,
 firstLineIndentChars: null,
};

function numericDataAttribute(element, name) {
 const value = element.getAttribute(name);
 if (value === null || value === "") return null;
 const numeric = Number(value);
 return Number.isFinite(numeric) ? numeric : null;
}

const CellParagraphFormatting = Extension.create({
 name: "cellParagraphFormatting",
 addGlobalAttributes() {
 return [{
 types: ["paragraph", "heading"],
 attributes: {
 stylePreset: {
 default: null,
 parseHTML: (element) => element.getAttribute("data-style-preset"),
 renderHTML: (attributes) => attributes.stylePreset
 ? { "data-style-preset": attributes.stylePreset }
 : {},
 },
 lineHeight: {
 default: null,
 parseHTML: (element) => numericDataAttribute(element, "data-line-height"),
 renderHTML: (attributes) => attributes.lineHeight == null
 ? {}
 : { "data-line-height": attributes.lineHeight, style: `line-height: ${attributes.lineHeight}` },
 },
 spacingBeforePt: {
 default: null,
 parseHTML: (element) => numericDataAttribute(element, "data-spacing-before-pt"),
 renderHTML: (attributes) => attributes.spacingBeforePt == null
 ? {}
 : { "data-spacing-before-pt": attributes.spacingBeforePt, style: `margin-top: ${attributes.spacingBeforePt}pt` },
 },
 spacingAfterPt: {
 default: null,
 parseHTML: (element) => numericDataAttribute(element, "data-spacing-after-pt"),
 renderHTML: (attributes) => attributes.spacingAfterPt == null
 ? {}
 : { "data-spacing-after-pt": attributes.spacingAfterPt, style: `margin-bottom: ${attributes.spacingAfterPt}pt` },
 },
 leftIndentChars: {
 default: null,
 parseHTML: (element) => numericDataAttribute(element, "data-left-indent-chars"),
 renderHTML: (attributes) => attributes.leftIndentChars == null
 ? {}
 : { "data-left-indent-chars": attributes.leftIndentChars, style: `margin-left: ${attributes.leftIndentChars}em` },
 },
 rightIndentChars: {
 default: null,
 parseHTML: (element) => numericDataAttribute(element, "data-right-indent-chars"),
 renderHTML: (attributes) => attributes.rightIndentChars == null
 ? {}
 : { "data-right-indent-chars": attributes.rightIndentChars, style: `margin-right: ${attributes.rightIndentChars}em` },
 },
 firstLineIndentChars: {
 default: null,
 parseHTML: (element) => numericDataAttribute(element, "data-first-line-indent-chars"),
 renderHTML: (attributes) => attributes.firstLineIndentChars == null
 ? {}
 : { "data-first-line-indent-chars": attributes.firstLineIndentChars, style: `text-indent: ${attributes.firstLineIndentChars}em` },
 },
 },
 }];
 },
});

const STYLE_PRESETS = [
 { id: "heading_1", label: "一级标题", node: "heading", level: 1, font: "黑体", size: "16pt", attrs: { lineHeight: 1, spacingBeforePt: 18, spacingAfterPt: 8, leftIndentChars: 0, rightIndentChars: 0, firstLineIndentChars: 0 } },
 { id: "heading_2", label: "二级标题", node: "heading", level: 2, font: "黑体", size: "14pt", attrs: { lineHeight: 1, spacingBeforePt: 14, spacingAfterPt: 6, leftIndentChars: 0, rightIndentChars: 0, firstLineIndentChars: 0 } },
 { id: "heading_3", label: "三级标题", node: "heading", level: 3, font: "黑体", size: "12pt", attrs: { lineHeight: 1, spacingBeforePt: 10, spacingAfterPt: 4, leftIndentChars: 0, rightIndentChars: 0, firstLineIndentChars: 0 } },
 { id: "heading_4", label: "四级标题", node: "heading", level: 4, font: "黑体", size: "10.5pt", attrs: { lineHeight: 1, spacingBeforePt: 8, spacingAfterPt: 3, leftIndentChars: 0, rightIndentChars: 0, firstLineIndentChars: 0 } },
 { id: "body", label: "正文", node: "paragraph", font: "宋体", size: "10.5pt", attrs: { lineHeight: 1.5, spacingBeforePt: 0, spacingAfterPt: 4, leftIndentChars: 0, rightIndentChars: 0, firstLineIndentChars: 0 } },
 { id: "note", label: "附注", node: "paragraph", font: "宋体", size: "9pt", attrs: { lineHeight: 1, spacingBeforePt: 2, spacingAfterPt: 2, leftIndentChars: 0, rightIndentChars: 0, firstLineIndentChars: 0 } },
];
const FONT_OPTIONS = ["宋体", "黑体", "仿宋", "楷体", "Arial", "Times New Roman"];
const FONT_SIZE_OPTIONS = ["8pt", "9pt", "10.5pt", "12pt", "14pt", "16pt", "18pt", "22pt"];
const HIGHLIGHT_OPTIONS = [
 { value: "", label: "无标黄" },
 { value: "#FFFF00", label: "黄色" },
 { value: "#00FF00", label: "绿色" },
 { value: "#00FFFF", label: "青色" },
 { value: "#FF00FF", label: "粉色" },
];

function blockType(editor) {
 return editor?.isActive("heading") ? "heading" : "paragraph";
}

function blockAttributes(editor) {
 return editor?.getAttributes(blockType(editor)) || {};
}

function updateBlock(editor, attrs) {
 return editor?.chain().focus().updateAttributes(blockType(editor), attrs).run();
}

function cellDocument(value, plainText) {
 if (value?.type === "doc" && Array.isArray(value.content)) return value;
 if (value?.type) return { type: "doc", content: [value] };
 return {
 type: "doc",
 content: [{
 type: "paragraph",
 content: plainText ? [{ type: "text", text: String(plainText) }] : undefined,
 }],
 };
}

export function TableCellRichEditor({
 cell,
 readOnly = false,
 documentIndex = null,
 focusRequest = 0,
 onChange,
 onNavigateCell,
}) {
 const [paragraphSettingsOpen, setParagraphSettingsOpen] = useState(false);
 const onChangeRef = useRef(onChange);
 const readOnlyRef = useRef(readOnly);
 const onNavigateCellRef = useRef(onNavigateCell);
 const documentBaselineRef = useRef("");
 const editorReadyRef = useRef(false);
 onChangeRef.current = onChange;
 readOnlyRef.current = readOnly;
 onNavigateCellRef.current = onNavigateCell;
 const editor = useEditor({
 extensions: [
 StarterKit,
 TextStyle,
 FontFamily,
 FontSize,
 Color,
 Subscript,
 Superscript,
 CrossReferenceMark,
 Highlight.configure({ multicolor: true }),
 TextAlign.configure({ types: ["heading", "paragraph"] }),
 CellParagraphFormatting,
 WordEditingShortcuts,
 ],
 editable: !readOnly,
 content: cellDocument(cell?.rich_text, cell?.text),
 onCreate: ({ editor: current }) => {
 documentBaselineRef.current = JSON.stringify(current.getJSON());
 editorReadyRef.current = true;
 },
 onUpdate: ({ editor: current }) => {
 if (readOnlyRef.current || !cell?.cell_id) return;
 if (!editorReadyRef.current) return;
 const nextDocument = current.getJSON();
 const serialized = JSON.stringify(nextDocument);
 if (serialized === documentBaselineRef.current) return;
 documentBaselineRef.current = serialized;
 onChangeRef.current?.({
 text: current.getText({ blockSeparator: "\n" }),
 rich_text: nextDocument,
 });
 },
 editorProps: {
 handleKeyDown: (_view, event) => {
 if (event.key !== "Tab" || readOnlyRef.current) return false;
 event.preventDefault();
 onNavigateCellRef.current?.(event.shiftKey ? -1 : 1);
 return true;
 },
 },
 }, [cell?.cell_id]);

 useEffect(() => {
 editor?.setEditable(!readOnly);
 }, [editor, readOnly]);

 useEffect(() => {
 if (!editor || !cell?.cell_id) return;
 const incoming = cellDocument(cell.rich_text, cell.text);
 if (JSON.stringify(editor.getJSON()) !== JSON.stringify(incoming)) {
 editor.commands.setContent(incoming, { emitUpdate: false });
 }
 documentBaselineRef.current = JSON.stringify(editor.getJSON());
 }, [editor, cell?.cell_id, cell?.rich_text, cell?.text]);

 useEffect(() => {
 if (!editor || readOnly || !focusRequest) return;
 const frame = globalThis.requestAnimationFrame?.(() => editor.commands.focus("end"));
 return () => globalThis.cancelAnimationFrame?.(frame);
 }, [editor, focusRequest, readOnly]);

 if (!cell?.cell_id || !editor) {
 return <div className="std-cell-rich-empty">选择单元格后可编辑文字与段落格式</div>;
 }

 const attrs = blockAttributes(editor);
 const styleId = attrs.stylePreset
 || (editor.isActive("heading") ? `heading_${Math.min(Number(editor.getAttributes("heading")?.level || 1), 4)}` : "body");
 const preset = STYLE_PRESETS.find((item) => item.id === styleId) || STYLE_PRESETS[4];
 const textStyle = editor.getAttributes("textStyle") || {};
 const highlight = editor.getAttributes("highlight")?.color || "";
 const disabled = readOnly || !editor;
 const crossReferenceTargets = [
 ...(documentIndex?.tables || []),
 ...(documentIndex?.figures || []),
 ];
 const setNumber = (key, raw) => {
 const value = Number(raw);
 if (Number.isFinite(value)) updateBlock(editor, { [key]: value });
 };
 const applyStyle = (presetId) => {
 const next = STYLE_PRESETS.find((item) => item.id === presetId);
 if (!next) return;
 const chain = editor.chain().focus();
 if (next.node === "heading") chain.setHeading({ level: next.level });
 else chain.setParagraph();
 chain.updateAttributes(next.node, { stylePreset: next.id, ...next.attrs }).run();
 };
 const adjustIndent = (delta) => {
 const current = Number(blockAttributes(editor).leftIndentChars || 0);
 updateBlock(editor, { leftIndentChars: Math.min(20, Math.max(0, current + delta)) });
 };

 return (
 <section className="std-cell-rich-panel" aria-label="当前单元格文字与段落编辑">
 <div className="std-cell-rich-identity">
 <strong>当前单元格</strong>
 <span>{cell.rowIndex + 1} 行 / {cell.columnIndex + 1} 列</span>
 </div>
 <div className="rich-toolbar std-rich-toolbar" aria-label="单元格格式工具栏">
 <div className="rich-toolbar-row rich-toolbar-text-row">
 <label className="rich-toolbar-select rich-style-select"><span>样式</span><select aria-label="单元格段落样式" value={styleId} disabled={disabled} onChange={(event) => applyStyle(event.target.value)}>{STYLE_PRESETS.map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select></label>
 <label className="rich-toolbar-select rich-font-select"><span>字体</span><select aria-label="单元格字体" value={textStyle.fontFamily || preset.font} disabled={disabled} onChange={(event) => editor.chain().focus().setFontFamily(event.target.value).run()}>{FONT_OPTIONS.map((font) => <option key={font} value={font}>{font}</option>)}</select></label>
 <label className="rich-toolbar-select rich-size-select"><span>字号</span><select aria-label="单元格字号" value={textStyle.fontSize || preset.size} disabled={disabled} onChange={(event) => editor.chain().focus().setFontSize(event.target.value).run()}>{FONT_SIZE_OPTIONS.map((size) => <option key={size} value={size}>{size.replace("pt", "")}</option>)}</select></label>
 <span className="rich-toolbar-separator" aria-hidden="true" />
 {[
 ["加粗", Bold, editor.isActive("bold"), () => editor.chain().focus().toggleBold().run()],
 ["斜体", Italic, editor.isActive("italic"), () => editor.chain().focus().toggleItalic().run()],
 ["下划线", UnderlineIcon, editor.isActive("underline"), () => editor.chain().focus().toggleUnderline().run()],
 ["上标", SuperscriptIcon, editor.isActive("superscript"), () => editor.chain().focus().toggleSuperscript().run()],
 ["下标", SubscriptIcon, editor.isActive("subscript"), () => editor.chain().focus().toggleSubscript().run()],
 ].map(([label, Icon, active, run]) => <button type="button" key={label} className={active ? "active" : ""} disabled={disabled} onClick={run} title={label} aria-label={`单元格${label}`}><Icon size={15} /></button>)}
 <span className="rich-toolbar-separator" aria-hidden="true" />
 <label className="rich-color-control" title="文字颜色"><Palette size={15} /><span className="rich-color-swatch" style={{ backgroundColor: textStyle.color || "#222222" }} /><input type="color" aria-label="单元格文字颜色" value={/^#[0-9a-f]{6}$/i.test(textStyle.color || "") ? textStyle.color : "#222222"} disabled={disabled} onChange={(event) => editor.chain().focus().setColor(event.target.value.toUpperCase()).run()} /></label>
 <label className="rich-highlight-control" title="文字标黄"><Highlighter size={15} /><span className="rich-color-swatch" style={{ backgroundColor: highlight || "#ffff00" }} /><select aria-label="单元格文字标黄" value={highlight} disabled={disabled} onChange={(event) => event.target.value ? editor.chain().focus().setHighlight({ color: event.target.value }).run() : editor.chain().focus().unsetHighlight().run()}>{HIGHLIGHT_OPTIONS.map((item) => <option key={item.value || "none"} value={item.value}>{item.label}</option>)}</select></label>
 <button type="button" disabled={disabled} title="清除直接格式" aria-label="清除单元格直接格式" onClick={() => editor.chain().focus().unsetAllMarks().updateAttributes(blockType(editor), { ...PARAGRAPH_DEFAULTS, stylePreset: attrs.stylePreset || null }).run()}><Eraser size={15} /></button>
 </div>
 <div className="rich-toolbar-row rich-toolbar-paragraph-row">
 {[
 ["项目符号", List, editor.isActive("bulletList"), () => editor.chain().focus().toggleBulletList().run()],
 ["编号", ListOrdered, editor.isActive("orderedList"), () => editor.chain().focus().toggleOrderedList().run()],
 ["左对齐", AlignLeft, editor.isActive({ textAlign: "left" }), () => editor.chain().focus().setTextAlign("left").run()],
 ["居中", AlignCenter, editor.isActive({ textAlign: "center" }), () => editor.chain().focus().setTextAlign("center").run()],
 ["右对齐", AlignRight, editor.isActive({ textAlign: "right" }), () => editor.chain().focus().setTextAlign("right").run()],
 ["两端对齐", AlignJustify, editor.isActive({ textAlign: "justify" }), () => editor.chain().focus().setTextAlign("justify").run()],
 ["减少左缩进", IndentDecrease, false, () => adjustIndent(-1)],
 ["增加左缩进", IndentIncrease, false, () => adjustIndent(1)],
 ].map(([label, Icon, active, run]) => <button type="button" key={label} className={active ? "active" : ""} disabled={disabled} onClick={run} title={label} aria-label={`单元格${label}`}><Icon size={15} /></button>)}
 <span className="rich-toolbar-separator" aria-hidden="true" />
 <label className="rich-toolbar-select rich-line-height-select"><span>行距</span><select aria-label="单元格行距" value={attrs.lineHeight ?? preset.attrs.lineHeight} disabled={disabled} onChange={(event) => setNumber("lineHeight", event.target.value)}>{[1, 1.15, 1.25, 1.5, 2].map((value) => <option key={value} value={value}>{value}</option>)}</select></label>
 <div className="rich-paragraph-settings">
 <button type="button" className={paragraphSettingsOpen ? "active" : ""} disabled={disabled} aria-expanded={paragraphSettingsOpen} onClick={() => setParagraphSettingsOpen((value) => !value)}>段落</button>
 {paragraphSettingsOpen && <div className="rich-paragraph-popover" role="dialog" aria-label="单元格段落设置">{[
 ["首行缩进（字符）", "firstLineIndentChars", attrs.firstLineIndentChars ?? preset.attrs.firstLineIndentChars, -10, 20, 0.5],
 ["左缩进（字符）", "leftIndentChars", attrs.leftIndentChars ?? 0, 0, 20, 0.5],
 ["右缩进（字符）", "rightIndentChars", attrs.rightIndentChars ?? 0, 0, 20, 0.5],
 ["段前（磅）", "spacingBeforePt", attrs.spacingBeforePt ?? preset.attrs.spacingBeforePt, 0, 72, 1],
 ["段后（磅）", "spacingAfterPt", attrs.spacingAfterPt ?? preset.attrs.spacingAfterPt, 0, 72, 1],
 ].map(([label, key, value, min, max, step]) => <label key={key}><span>{label}</span><input type="number" min={min} max={max} step={step} value={value} onChange={(event) => setNumber(key, event.target.value)} /></label>)}</div>}
 </div>
 <span className="rich-toolbar-separator" aria-hidden="true" />
 <button type="button" disabled={disabled || !editor.can().undo()} title="撤销" aria-label="撤销单元格编辑" onClick={() => editor.chain().focus().undo().run()}><Undo2 size={15} /></button>
 <button type="button" disabled={disabled || !editor.can().redo()} title="重做" aria-label="重做单元格编辑" onClick={() => editor.chain().focus().redo().run()}><Redo2 size={15} /></button>
 <span className="rich-toolbar-separator" aria-hidden="true" />
 <label className="rich-cross-reference-picker" title="在当前单元格插入表或图的交叉引用">
 <Link2 size={15} aria-hidden="true" />
 <select
 aria-label="单元格插入交叉引用"
 value=""
 disabled={disabled || !crossReferenceTargets.length}
 onChange={(event) => {
 const [targetKind, targetId] = event.target.value.split(":", 2);
 const target = crossReferenceTargets.find((item) => (
 item.kind === targetKind && item.object_id === targetId
 ));
 if (target) insertCrossReference(editor, target);
 event.target.value = "";
 }}
 >
 <option value="">交叉引用</option>
 {(documentIndex?.tables || []).length > 0 && (
 <optgroup label="表">
 {documentIndex.tables.map((item) => (
 <option key={`table:${item.object_id}`} value={`table:${item.object_id}`}>
 {item.display_label}
 </option>
 ))}
 </optgroup>
 )}
 {(documentIndex?.figures || []).length > 0 && (
 <optgroup label="图">
 {documentIndex.figures.map((item) => (
 <option key={`figure:${item.object_id}`} value={`figure:${item.object_id}`}>
 {item.display_label}
 </option>
 ))}
 </optgroup>
 )}
 </select>
 </label>
 </div>
 </div>
 <EditorContent editor={editor} className="std-cell-rich-editor" />
 </section>
 );
}

import { Extension } from "@tiptap/core";
import { redo, undo } from "@tiptap/pm/history";
import { Plugin, PluginKey } from "@tiptap/pm/state";

const wordEditingShortcutsPluginKey = new PluginKey("wordEditingShortcuts");

export const WordEditingShortcuts = Extension.create({
 name: "wordEditingShortcuts",
 priority: 1000,
 addKeyboardShortcuts() {
 return {
 "Mod-b": () => this.editor.commands.toggleBold(),
 "Mod-i": () => this.editor.commands.toggleItalic(),
 "Mod-u": () => this.editor.commands.toggleUnderline(),
 "Mod-z": () => this.editor.commands.undo(),
 "Mod-Shift-z": () => this.editor.commands.redo(),
 "Mod-y": () => this.editor.commands.redo(),
 };
 },
 addProseMirrorPlugins() {
 return [new Plugin({
 key: wordEditingShortcutsPluginKey,
 props: {
 handleKeyDown(view, event) {
 if (!(event.metaKey || event.ctrlKey) || event.altKey) return false;
 const key = String(event.key || "").toLowerCase();
 const command = key === "z"
 ? (event.shiftKey ? redo : undo)
 : key === "y" && !event.shiftKey
 ? redo
 : null;
 if (!command || !command(view.state, view.dispatch)) return false;
 event.preventDefault();
 return true;
 },
 },
 })];
 },
});

export default WordEditingShortcuts;

/**
 * Durable job state machine + production controller helpers.
 * Imported by useDurableMwJob.js, App.jsx, writing-reference panels, and Node tests.
 *
 * Domain reconciliation is explicit: transport /result HTTP 200 is never enough
 * to clear a locator. Callers must acknowledge exact business artifacts.
 */

export const TERMINAL_STATUSES = new Set(["completed", "failed", "cancelled"]);
export const LOCATOR_VERSION = "mw_job_locator_v2";
export const GEN_CTX_VERSION = "mw_gen_ctx_v2";

export function isCompletedSuccess(status) {
 return status === "completed";
}

export function isTerminal(status) {
 return TERMINAL_STATUSES.has(status);
}

export function isValidLocator(locator) {
 if (!locator || typeof locator !== "object") return false;
 if (!locator.job_id || typeof locator.job_id !== "string") return false;
 if (!locator.project_id || typeof locator.project_id !== "string") return false;
 return true;
}

export function isV2Locator(locator) {
 return Boolean(locator && locator.version === LOCATOR_VERSION);
}

/**
 * Build a versioned locator before polling starts.
 */
export function buildLocator({
 projectId,
 jobId,
 operation,
 sectionId,
 jobType,
 runId,
 batchId,
 snapshotId,
 suggestionIds,
 threadId,
}) {
 return {
 version: LOCATOR_VERSION,
 project_id: projectId,
 job_id: jobId,
 operation: operation || "",
 section_id: sectionId || "",
 job_type: jobType || "",
 run_id: runId || "",
 batch_id: batchId || "",
 snapshot_id: snapshotId || "",
 thread_id: threadId || "",
 suggestion_ids: Array.isArray(suggestionIds) ? suggestionIds : [],
 persisted_at: Date.now(),
 };
}

/**
 * Only clear after terminal status AND successful domain reconciliation.
 * Transport-level /result success alone is never enough.
 * Cancelled without domain recon must retain the locator.
 */
export function shouldClearLocator(status, domainReconciled) {
 return isTerminal(status) && domainReconciled === true;
}

export function shouldBlockStart(currentJobStatus) {
 if (!currentJobStatus) return false;
 return !isTerminal(currentJobStatus);
}

/**
 * Block start for a specific operation key in a dual-job map.
 */
export function shouldBlockStartForOperation(jobsByOperation, operation) {
 const row = jobsByOperation && jobsByOperation[operation];
 return shouldBlockStart(row?.status);
}

export function extractArtifactThreadId(resultBody) {
 if (!resultBody || typeof resultBody !== "object") return null;
 const artifact = resultBody.artifact;
 if (artifact && artifact.thread_id) return String(artifact.thread_id);
 if (resultBody.thread_id) return String(resultBody.thread_id);
 return null;
}

export function extractArtifactSuggestionIds(resultBody) {
 if (!resultBody || typeof resultBody !== "object") return [];
 const artifact = resultBody.artifact || {};
 const ids = artifact.suggestion_ids || resultBody.suggestion_ids || [];
 return Array.isArray(ids) ? ids.map(String).filter(Boolean) : [];
}

export function extractArtifactPostThreadHash(resultBody) {
 if (!resultBody || typeof resultBody !== "object") return "";
 const artifact = resultBody.artifact || {};
 return String(artifact.post_thread_hash || resultBody.post_thread_hash || "");
}

export function extractArtifactGenerationContextVersion(resultBody) {
 if (!resultBody || typeof resultBody !== "object") return "";
 const artifact = resultBody.artifact || {};
 return String(
 artifact.generation_context_version
 || resultBody.generation_context_version
 || "",
 );
}

export function extractArtifactRunId(resultBody) {
 if (!resultBody || typeof resultBody !== "object") return "";
 const artifact = resultBody.artifact || {};
 return String(artifact.run_id || resultBody.run_id || "");
}

export function extractArtifactBatchId(resultBody) {
 if (!resultBody || typeof resultBody !== "object") return "";
 const artifact = resultBody.artifact || {};
 return String(artifact.batch_id || resultBody.batch_id || "");
}

export function extractArtifactSnapshotId(resultBody) {
 if (!resultBody || typeof resultBody !== "object") return "";
 const artifact = resultBody.artifact || {};
 return String(artifact.snapshot_id || resultBody.snapshot_id || "");
}

/**
 * Transport poll outcome from status + whether /result was fetched.
 * domainReconciled defaults false until domain ack.
 */
export function classifyPollOutcome(status, domainReconciled) {
 if (isCompletedSuccess(status) && domainReconciled) return "success";
 if ((status === "failed" || status === "cancelled") && domainReconciled) {
 return "terminal_failure";
 }
 if (isTerminal(status) && !domainReconciled) return "reconcile_failed";
 return "retain";
}

/**
 * Decide cleanup after transport + domain reconciliation.
 * Never treats cancelled-without-domain as clearable.
 */
export function decideLocatorCleanup({ status, domainReconciled }) {
 const shouldClear = shouldClearLocator(status, domainReconciled === true);
 const outcome = classifyPollOutcome(status, domainReconciled === true);
 return { shouldClear, outcome };
}

export function buildTerminalPayload(status, resultBody, errorSummary) {
 return {
 status,
 result: resultBody,
 error: errorSummary || "",
 };
}

export function isStaleCompletion(locator, currentProjectId, currentSectionId) {
 if (!locator) return false;
 if (locator.project_id !== currentProjectId) return true;
 if (currentSectionId && locator.section_id && locator.section_id !== currentSectionId) {
 return true;
 }
 return false;
}

/**
 * Screen generation token: suppress mutations after project/section switch.
 */
export function createScreenGeneration(projectId, sectionId = "") {
 return {
 projectId: projectId || "",
 sectionId: sectionId || "",
 seq: Date.now(),
 };
}

export function isScreenGenerationCurrent(token, currentProjectId, currentSectionId = "") {
 if (!token) return false;
 if (token.projectId !== currentProjectId) return false;
 if (token.sectionId && currentSectionId && token.sectionId !== currentSectionId) {
 return false;
 }
 return true;
}

/**
 * After durable retry, prefer any replacement job_id from the response body.
 * Preserves full locator context via mergeRetryLocator.
 */
export function resolveRetryJobId(previousJobId, retryBody) {
 if (retryBody && typeof retryBody === "object") {
 const next = retryBody.job_id || retryBody.durable_job_id;
 if (next) return String(next);
 }
 return previousJobId;
}

export function mergeRetryLocator(previousLocator, nextJobId, projectId) {
 const base = previousLocator && typeof previousLocator === "object" ? previousLocator : {};
 return buildLocator({
 projectId: projectId || base.project_id || "",
 jobId: nextJobId,
 operation: base.operation || "",
 sectionId: base.section_id || "",
 jobType: base.job_type || "",
 runId: base.run_id || "",
 batchId: base.batch_id || "",
 snapshotId: base.snapshot_id || "",
 suggestionIds: base.suggestion_ids || [],
 threadId: base.thread_id || "",
 });
}

/**
 * Exact revision/rewrite artifact validation for v2 locators/results.
 * Missing exact lineage is reconciliation failure — no fallback guessing.
 * Legacy (non-v2) locators may use optional thread fallback only when explicitly allowed.
 */
export function validateRevisionArtifactExact(resultBody, locator = null, opts = {}) {
 const requireSuggestions = opts.requireSuggestions !== false;
 const allowLegacyFallback = opts.allowLegacyFallback === true;
 const isV2 = isV2Locator(locator)
 || extractArtifactGenerationContextVersion(resultBody) === GEN_CTX_VERSION
 || (locator && locator.version === LOCATOR_VERSION);

 const threadId = extractArtifactThreadId(resultBody);
 const suggestionIds = extractArtifactSuggestionIds(resultBody);
 const postHash = extractArtifactPostThreadHash(resultBody);

 if (isV2 || !allowLegacyFallback) {
 if (!threadId) {
 return { ok: false, reason: "missing_exact_thread_id", threadId: null, suggestionIds: [], postHash: "" };
 }
 if (requireSuggestions && suggestionIds.length === 0) {
 return { ok: false, reason: "missing_exact_suggestion_ids", threadId, suggestionIds: [], postHash };
 }
 return { ok: true, reason: "", threadId, suggestionIds, postHash };
 }

 // Legacy-only path (unreachable for v2 locators).
 const legacyThread = threadId || (locator && locator.thread_id) || null;
 if (!legacyThread) {
 return { ok: false, reason: "legacy_missing_thread", threadId: null, suggestionIds: [], postHash: "" };
 }
 return { ok: true, reason: "legacy", threadId: String(legacyThread), suggestionIds, postHash };
}

/**
 * Domain reconcile revision thread against exact artifact IDs.
 * domainThread must be the exact loaded business object (or null).
 */
export function acknowledgeRevisionDomain({
 status,
 resultBody,
 locator,
 domainThread,
 currentProjectId,
 currentSectionId,
 screenGeneration,
}) {
 if (screenGeneration && !isScreenGenerationCurrent(screenGeneration, currentProjectId, currentSectionId)) {
 return {
 domainReconciled: false,
 outcome: "stale_screen",
 shouldClear: false,
 reason: "stale_screen",
 threadId: null,
 suggestionIds: [],
 };
 }
 if (locator && isStaleCompletion(locator, currentProjectId, currentSectionId)) {
 return {
 domainReconciled: false,
 outcome: "stale_screen",
 shouldClear: false,
 reason: "stale_locator_context",
 threadId: null,
 suggestionIds: [],
 };
 }

 if (!isTerminal(status)) {
 return {
 domainReconciled: false,
 outcome: "retain",
 shouldClear: false,
 reason: "non_terminal",
 threadId: null,
 suggestionIds: [],
 };
 }

 if (status === "failed" || status === "cancelled") {
 // Terminal failure: domain recon requires transport result body present
 // (caller only passes resultBody when /result succeeded). No exact
 // suggestion required for failed/cancelled, but no clear without body.
 const domainReconciled = resultBody != null && typeof resultBody === "object";
 const { shouldClear, outcome } = decideLocatorCleanup({ status, domainReconciled });
 return {
 domainReconciled,
 outcome,
 shouldClear,
 reason: domainReconciled ? "terminal_failure_acked" : "terminal_without_result",
 threadId: null,
 suggestionIds: [],
 };
 }

 // completed
 const exact = validateRevisionArtifactExact(resultBody, locator, { requireSuggestions: true });
 if (!exact.ok) {
 return {
 domainReconciled: false,
 outcome: "reconcile_failed",
 shouldClear: false,
 reason: exact.reason,
 threadId: null,
 suggestionIds: [],
 };
 }
 if (!domainThread || domainThread.thread_id !== exact.threadId) {
 return {
 domainReconciled: false,
 outcome: "reconcile_failed",
 shouldClear: false,
 reason: "thread_not_found_or_mismatch",
 threadId: exact.threadId,
 suggestionIds: exact.suggestionIds,
 };
 }
 const present = new Set((domainThread.suggestions || []).map((s) => String(s.suggestion_id)));
 if (exact.suggestionIds.some((id) => !present.has(id))) {
 return {
 domainReconciled: false,
 outcome: "reconcile_failed",
 shouldClear: false,
 reason: "suggestion_ids_not_on_thread",
 threadId: exact.threadId,
 suggestionIds: exact.suggestionIds,
 };
 }
 return {
 domainReconciled: true,
 outcome: "success",
 shouldClear: shouldClearLocator(status, true),
 reason: "exact_artifact_ok",
 threadId: exact.threadId,
 suggestionIds: exact.suggestionIds,
 };
}

export function acknowledgeTriageDomain({
 status,
 resultBody,
 locator,
 expectedRunId,
 expectedSnapshotId,
}) {
 if (!isTerminal(status)) {
 return { domainReconciled: false, outcome: "retain", shouldClear: false, reason: "non_terminal" };
 }
 if (status === "failed" || status === "cancelled") {
 const domainReconciled = resultBody != null && typeof resultBody === "object";
 const { shouldClear, outcome } = decideLocatorCleanup({ status, domainReconciled });
 return { domainReconciled, outcome, shouldClear, reason: domainReconciled ? "terminal_failure_acked" : "terminal_without_result" };
 }
 if (!resultBody) {
 return { domainReconciled: false, outcome: "reconcile_failed", shouldClear: false, reason: "missing_result" };
 }
 const runId = extractArtifactRunId(resultBody);
 const snapshotId = extractArtifactSnapshotId(resultBody);
 const expectRun = expectedRunId || locator?.run_id || "";
 const expectSnap = expectedSnapshotId || locator?.snapshot_id || "";
 if (expectRun && runId && expectRun !== runId) {
 return { domainReconciled: false, outcome: "reconcile_failed", shouldClear: false, reason: "run_id_mismatch" };
 }
 if (expectSnap && snapshotId && expectSnap !== snapshotId) {
 return { domainReconciled: false, outcome: "reconcile_failed", shouldClear: false, reason: "snapshot_id_mismatch" };
 }
 // completed: require at least run or snapshot identity when expected
 if (expectRun && !runId) {
 return { domainReconciled: false, outcome: "reconcile_failed", shouldClear: false, reason: "missing_run_id" };
 }
 return {
 domainReconciled: true,
 outcome: "success",
 shouldClear: shouldClearLocator(status, true),
 reason: "triage_exact_ok",
 runId,
 snapshotId,
 };
}

export function acknowledgeTranslationDomain({
 status,
 resultBody,
 locator,
 expectedBatchId,
 expectedSnapshotId,
}) {
 if (!isTerminal(status)) {
 return { domainReconciled: false, outcome: "retain", shouldClear: false, reason: "non_terminal" };
 }
 if (status === "failed" || status === "cancelled") {
 const domainReconciled = resultBody != null && typeof resultBody === "object";
 const { shouldClear, outcome } = decideLocatorCleanup({ status, domainReconciled });
 return { domainReconciled, outcome, shouldClear, reason: domainReconciled ? "terminal_failure_acked" : "terminal_without_result" };
 }
 if (!resultBody) {
 return { domainReconciled: false, outcome: "reconcile_failed", shouldClear: false, reason: "missing_result" };
 }
 const batchId = extractArtifactBatchId(resultBody);
 const snapshotId = extractArtifactSnapshotId(resultBody);
 const expectBatch = expectedBatchId || locator?.batch_id || "";
 const expectSnap = expectedSnapshotId || locator?.snapshot_id || "";
 if (expectBatch && batchId && expectBatch !== batchId) {
 return { domainReconciled: false, outcome: "reconcile_failed", shouldClear: false, reason: "batch_id_mismatch" };
 }
 if (expectSnap && snapshotId && expectSnap !== snapshotId) {
 return { domainReconciled: false, outcome: "reconcile_failed", shouldClear: false, reason: "snapshot_id_mismatch" };
 }
 if (expectBatch && !batchId) {
 return { domainReconciled: false, outcome: "reconcile_failed", shouldClear: false, reason: "missing_batch_id" };
 }
 return {
 domainReconciled: true,
 outcome: "success",
 shouldClear: shouldClearLocator(status, true),
 reason: "translation_exact_ok",
 batchId,
 snapshotId,
 };
}

/**
 * Dual-operation job map helpers (initial + rewrite independent).
 */
export function emptyRevisionJobMap() {
 return { initial: null, rewrite: null };
}

export function setOperationJob(map, operation, jobState) {
 const next = { ...(map || emptyRevisionJobMap()) };
 next[operation] = jobState;
 return next;
}

export function clearOperationJob(map, operation) {
 return setOperationJob(map, operation, null);
}

export function pickFocusedRevisionJob(map) {
 const m = map || emptyRevisionJobMap();
 if (m.rewrite && shouldBlockStart(m.rewrite.status)) return m.rewrite;
 if (m.initial && shouldBlockStart(m.initial.status)) return m.initial;
 if (m.rewrite) return m.rewrite;
 if (m.initial) return m.initial;
 return null;
}

/**
 * Production controller adapter used by Node tests and production callers.
 * Pure decision surface — no React, no fetch.
 */
export const durableJobController = {
 LOCATOR_VERSION,
 GEN_CTX_VERSION,
 buildLocator,
 shouldClearLocator,
 shouldBlockStart,
 shouldBlockStartForOperation,
 classifyPollOutcome,
 decideLocatorCleanup,
 isStaleCompletion,
 createScreenGeneration,
 isScreenGenerationCurrent,
 resolveRetryJobId,
 mergeRetryLocator,
 validateRevisionArtifactExact,
 acknowledgeRevisionDomain,
 acknowledgeTriageDomain,
 acknowledgeTranslationDomain,
 emptyRevisionJobMap,
 setOperationJob,
 clearOperationJob,
 pickFocusedRevisionJob,
 extractArtifactThreadId,
 extractArtifactSuggestionIds,
 extractArtifactPostThreadHash,
 extractArtifactRunId,
 extractArtifactBatchId,
 extractArtifactSnapshotId,
};

export default durableJobController;

/**
 * Production-imported durable job controller behavior tests.
 * Run: node frontend/src/features/medical-writing/durableJobState.test.mjs
 */
import assert from "node:assert/strict";
import {
 TERMINAL_STATUSES,
 LOCATOR_VERSION,
 GEN_CTX_VERSION,
 isCompletedSuccess,
 isTerminal,
 isValidLocator,
 buildLocator,
 shouldClearLocator,
 shouldBlockStart,
 shouldBlockStartForOperation,
 classifyPollOutcome,
 decideLocatorCleanup,
 isStaleCompletion,
 createScreenGeneration,
 isScreenGenerationCurrent,
 resolveRetryJobId,
 mergeRetryLocator,
 validateRevisionArtifactExact,
 acknowledgeRevisionDomain,
 acknowledgeTriageDomain,
 acknowledgeTranslationDomain,
 emptyRevisionJobMap,
 setOperationJob,
 clearOperationJob,
 pickFocusedRevisionJob,
 durableJobController,
} from "./durableJobState.mjs";

let passed = 0;
function check(cond, msg) {
 assert.ok(cond, msg);
 passed += 1;
}

// --- basic helpers ---
check(isCompletedSuccess("completed"), "completed success");
check(!isCompletedSuccess("failed"), "failed not success");
check(isTerminal("cancelled"), "cancelled terminal");
check(TERMINAL_STATUSES.has("failed"), "failed in set");

const locator = buildLocator({
 projectId: "p1",
 jobId: "j1",
 operation: "initial",
 sectionId: "sec1",
 jobType: "section_ai_candidate",
});
check(locator.version === LOCATOR_VERSION, "locator version v2");
check(isValidLocator(locator), "valid locator");

// 1. Cancel without domain recon must NOT clear
check(shouldClearLocator("cancelled", false) === false, "cancel without domain retains");
check(shouldClearLocator("cancelled", true) === true, "cancel with domain clears");
check(
 decideLocatorCleanup({ status: "cancelled", domainReconciled: false }).shouldClear === false,
 "decideLocatorCleanup cancel no domain",
);
check(
 classifyPollOutcome("cancelled", false) === "reconcile_failed",
 "cancelled without domain is reconcile_failed",
);

// 2. Stale screen generation
const gen = createScreenGeneration("p1", "sec1");
check(isScreenGenerationCurrent(gen, "p1", "sec1"), "generation current");
check(!isScreenGenerationCurrent(gen, "p2", "sec1"), "project switch stale");
check(!isScreenGenerationCurrent(gen, "p1", "secB"), "section switch stale");
check(isStaleCompletion(locator, "p2", "sec1"), "stale project locator");
check(isStaleCompletion(locator, "p1", "secOther"), "stale section locator");

// 3. v2 exact artifact — no fallback guessing
const v2Result = {
 artifact: {
 thread_id: "th1",
 suggestion_ids: ["s1", "s2"],
 post_thread_hash: "a".repeat(64),
 generation_context_version: GEN_CTX_VERSION,
 },
};
const exactOk = validateRevisionArtifactExact(v2Result, locator);
check(exactOk.ok === true, "v2 exact ok");
check(exactOk.threadId === "th1", "exact thread");

const missingThread = validateRevisionArtifactExact({ artifact: { suggestion_ids: ["s1"] } }, locator);
check(missingThread.ok === false, "v2 missing thread fails");
check(missingThread.reason === "missing_exact_thread_id", "missing thread reason");

const missingSug = validateRevisionArtifactExact({ artifact: { thread_id: "th1" } }, locator);
check(missingSug.ok === false, "v2 missing suggestions fails");

// Legacy fallback only when allowLegacyFallback and non-v2 locator
const legacyLoc = { job_id: "j", project_id: "p", thread_id: "legacy_th" };
const legacy = validateRevisionArtifactExact({}, legacyLoc, { allowLegacyFallback: true });
check(legacy.ok === true && legacy.threadId === "legacy_th", "legacy fallback only when allowed");
const noLegacy = validateRevisionArtifactExact({}, locator, { allowLegacyFallback: true });
check(noLegacy.ok === false, "v2 locator never uses legacy fallback");

// 4. Dual-job map independence
let map = emptyRevisionJobMap();
map = setOperationJob(map, "initial", { job_id: "ji", status: "running", operation: "initial" });
map = setOperationJob(map, "rewrite", { job_id: "jr", status: "queued", operation: "rewrite" });
check(map.initial.job_id === "ji" && map.rewrite.job_id === "jr", "dual ops independent");
check(shouldBlockStartForOperation(map, "initial") === true, "block initial while running");
check(shouldBlockStartForOperation(map, "rewrite") === true, "block rewrite while queued");
const focused = pickFocusedRevisionJob(map);
check(focused.job_id === "jr" || focused.job_id === "ji", "focused picks busy op");
map = clearOperationJob(map, "initial");
check(map.initial === null && map.rewrite.job_id === "jr", "clear one op only");

// 5. Domain recon required for cleanup
const domainOk = acknowledgeRevisionDomain({
 status: "completed",
 resultBody: v2Result,
 locator,
 domainThread: {
 thread_id: "th1",
 suggestions: [{ suggestion_id: "s1" }, { suggestion_id: "s2" }],
 },
 currentProjectId: "p1",
 currentSectionId: "sec1",
 screenGeneration: gen,
});
check(domainOk.domainReconciled === true && domainOk.shouldClear === true, "domain success clears");

const domainNoThread = acknowledgeRevisionDomain({
 status: "completed",
 resultBody: v2Result,
 locator,
 domainThread: null,
 currentProjectId: "p1",
 currentSectionId: "sec1",
 screenGeneration: gen,
});
check(domainNoThread.shouldClear === false, "missing domain thread retains");
check(domainNoThread.outcome === "reconcile_failed", "missing thread reconcile_failed");

const cancelNoResult = acknowledgeRevisionDomain({
 status: "cancelled",
 resultBody: null,
 locator,
 domainThread: null,
 currentProjectId: "p1",
 currentSectionId: "sec1",
 screenGeneration: gen,
});
check(cancelNoResult.shouldClear === false, "cancel without result retains");
check(cancelNoResult.domainReconciled === false, "cancel without result not domain-acked");

const cancelWithResult = acknowledgeRevisionDomain({
 status: "cancelled",
 resultBody: { status: "cancelled" },
 locator,
 domainThread: null,
 currentProjectId: "p1",
 currentSectionId: "sec1",
 screenGeneration: gen,
});
check(cancelWithResult.shouldClear === true, "cancel with result can clear");

// Stale screen suppresses mutation/cleanup
const staleAck = acknowledgeRevisionDomain({
 status: "completed",
 resultBody: v2Result,
 locator,
 domainThread: { thread_id: "th1", suggestions: [{ suggestion_id: "s1" }, { suggestion_id: "s2" }] },
 currentProjectId: "p1",
 currentSectionId: "sec1",
 screenGeneration: createScreenGeneration("p1", "secOLD"),
});
check(staleAck.outcome === "stale_screen" && staleAck.shouldClear === false, "stale screen no clear");

// 6. Retry replacement id + context preserve
const nextId = resolveRetryJobId("old", { job_id: "new_job" });
check(nextId === "new_job", "retry job id");
const nextDurable = resolveRetryJobId("old", { durable_job_id: "d2" });
check(nextDurable === "d2", "retry durable id");
const merged = mergeRetryLocator(locator, "j2", "p1");
check(merged.job_id === "j2", "merged job id");
check(merged.operation === "initial", "merged preserves operation");
check(merged.section_id === "sec1", "merged preserves section");
check(merged.version === LOCATOR_VERSION, "merged remains v2");

// 7. Duplicate prevention
check(shouldBlockStart("running") === true, "block running");
check(shouldBlockStart("queued") === true, "block queued");
check(shouldBlockStart("completed") === false, "allow after completed");
check(shouldBlockStart(null) === false, "allow empty");

// 8. Triage exact run/snapshot
const triageOk = acknowledgeTriageDomain({
 status: "completed",
 resultBody: { artifact: { run_id: "r1", snapshot_id: "snap1" } },
 locator: buildLocator({ projectId: "p1", jobId: "j", runId: "r1", snapshotId: "snap1" }),
 expectedRunId: "r1",
 expectedSnapshotId: "snap1",
});
check(triageOk.shouldClear === true, "triage exact clears");
const triageMismatch = acknowledgeTriageDomain({
 status: "completed",
 resultBody: { artifact: { run_id: "r2" } },
 locator: { run_id: "r1" },
 expectedRunId: "r1",
});
check(triageMismatch.shouldClear === false, "triage run mismatch retains");

// 9. Translation exact batch + cancel without domain
const txOk = acknowledgeTranslationDomain({
 status: "completed",
 resultBody: { artifact: { batch_id: "b1", snapshot_id: "s1" } },
 locator: buildLocator({ projectId: "p1", jobId: "j", batchId: "b1", snapshotId: "s1" }),
 expectedBatchId: "b1",
 expectedSnapshotId: "s1",
});
check(txOk.shouldClear === true, "translation exact clears");
const txCancel = acknowledgeTranslationDomain({
 status: "cancelled",
 resultBody: null,
 locator: { batch_id: "b1" },
});
check(txCancel.shouldClear === false, "translation cancel without result retains");

// 10. Controller export surface
check(typeof durableJobController.acknowledgeRevisionDomain === "function", "controller export");
check(durableJobController.LOCATOR_VERSION === LOCATOR_VERSION, "controller version");

// Transport alone never enough for success cleanup path
check(classifyPollOutcome("completed", false) === "reconcile_failed", "completed without domain not success");
check(shouldClearLocator("completed", false) === false, "completed without domain no clear");

console.log(`${passed} passed, 0 failed`);

function editorNodeSourceBlockId(node) {
 return String(node?.attrs?.sourceBlockId || "").trim();
}

export function groupEditorNodesBySourceBlockId(
 contentBlocks,
 editorNodes,
 { isEffectivelyEmptyNode = () => false } = {},
) {
 const blocks = Array.isArray(contentBlocks) ? contentBlocks : [];
 const nodes = Array.isArray(editorNodes) ? editorNodes : [];
 const canonicalIds = blocks.map((block) => String(block?.block_id || "").trim());
 if (canonicalIds.some((blockId) => !blockId)) {
 return { error: "来源内容存在缺失的 block_id，不能安全映射编辑内容。", groups: [] };
 }
 if (new Set(canonicalIds).size !== canonicalIds.length) {
 return { error: "来源内容存在重复的 block_id，不能安全映射编辑内容。", groups: [] };
 }

 const blockById = new Map(blocks.map((block) => [String(block.block_id), block]));
 const groupsById = new Map(canonicalIds.map((blockId) => [
 blockId,
 {
 blockId,
 node: null,
 leadingNodes: [],
 trailingNodes: [],
 },
 ]));
 const boundIds = [];
 let activeSourceId = "";
 let pendingHeadingBody = null;

 for (let index = 0; index < nodes.length; index += 1) {
 const node = nodes[index];
 const sourceBlockId = editorNodeSourceBlockId(node);
 if (sourceBlockId) {
 if (!blockById.has(sourceBlockId)) {
 return {
 error: `编辑器包含未知来源块 ${sourceBlockId}，系统已阻止保存。`,
 groups: [],
 };
 }
 const group = groupsById.get(sourceBlockId);
 const sourceBlock = blockById.get(sourceBlockId);
 if (pendingHeadingBody) {
 if (sourceBlock?.block_type !== "paragraph") {
 return {
 error: `标题后的新增正文无法绑定到相邻正文来源块 ${sourceBlockId}，系统已阻止保存。`,
 groups: [],
 };
 }
 group.leadingNodes.push(...pendingHeadingBody.nodes);
 pendingHeadingBody = null;
 }
 if (group.node) {
 return {
 error: `编辑器重复出现来源块 ${sourceBlockId}，系统已阻止保存。`,
 groups: [],
 };
 }
 const expectedId = canonicalIds[boundIds.length];
 if (sourceBlockId !== expectedId) {
 return {
 error: `来源块顺序发生变化：期望 ${expectedId || "文档结束"}，实际为 ${sourceBlockId}。`,
 groups: [],
 };
 }
 if (sourceBlock?.block_type === "heading" && node.type === "sourceBlock") {
 const content = Array.isArray(node.content) ? node.content : [];
 const [headingNode, ...overflowNodes] = content;
 if (headingNode?.type !== "heading") {
 return {
 error: `标题来源块 ${sourceBlockId} 已失去标题语义，系统已阻止保存。`,
 groups: [],
 };
 }
 const meaningfulOverflow = overflowNodes.filter((candidate) => (
 !isEffectivelyEmptyNode(candidate)
 ));
 if (meaningfulOverflow.some((candidate) => candidate?.type !== "paragraph")) {
 return {
 error: `标题来源块 ${sourceBlockId} 包含无法安全绑定的新增标题或结构节点，系统已阻止保存。`,
 groups: [],
 };
 }
 group.node = { ...node, content: [headingNode] };
 if (meaningfulOverflow.length) {
 pendingHeadingBody = {
 sourceBlockId,
 nodes: meaningfulOverflow,
 };
 }
 } else {
 group.node = node;
 }
 boundIds.push(sourceBlockId);
 activeSourceId = sourceBlockId;
 continue;
 }

 const isTrailingEmpty = index === nodes.length - 1 && isEffectivelyEmptyNode(node);
 if (isTrailingEmpty) continue;
 if (!["paragraph", "heading"].includes(String(node?.type || ""))) {
 return {
 error: `编辑器包含无法绑定来源的 ${node?.type || "unknown"} 节点，系统已阻止保存。`,
 groups: [],
 };
 }
 if (!activeSourceId) {
 return {
 error: "文档开头出现无法定位来源的新增段落，系统已阻止保存。",
 groups: [],
 };
 }
 const activeBlock = blockById.get(activeSourceId);
 if (pendingHeadingBody || activeBlock?.block_type === "heading") {
 if (node?.type !== "paragraph") {
 return {
 error: `标题后的新增内容包含无法安全绑定的 ${node?.type || "unknown"} 节点，系统已阻止保存。`,
 groups: [],
 };
 }
 if (!pendingHeadingBody) {
 pendingHeadingBody = {
 sourceBlockId: activeSourceId,
 nodes: [],
 };
 }
 pendingHeadingBody.nodes.push(node);
 continue;
 }
 if (["table", "figure"].includes(activeBlock?.block_type)) {
 return {
 error: `新增段落紧邻${activeBlock.block_type === "table" ? "表格" : "图片"}来源块 ${activeSourceId}，无法确定正文来源。`,
 groups: [],
 };
 }
 groupsById.get(activeSourceId).trailingNodes.push(node);
 }

 if (pendingHeadingBody) {
 return {
 error: `标题后的新增正文没有相邻正文来源块可供绑定（标题来源块 ${pendingHeadingBody.sourceBlockId}），系统已阻止保存。`,
 groups: [],
 };
 }
 const missingIds = canonicalIds.filter((blockId) => !groupsById.get(blockId).node);
 if (missingIds.length) {
 return {
 error: `编辑器缺少来源块 ${missingIds.slice(0, 3).join("、")}${missingIds.length > 3 ? "等" : ""}，系统已阻止保存。`,
 groups: [],
 };
 }
 return {
 error: "",
 groups: canonicalIds.map((blockId) => groupsById.get(blockId)),
 boundSourceBlockIds: boundIds,
 };
}

/**
 * Protocol v3 workbench API client contract (frozen plan Task 1.9).
 *
 * Non-visual transport contract only: builds route-safe v3 URLs under
 * `/api/projects/{project_id}/protocol-workflow`, injectable fetch, JSON
 * headers, business-shaped methods matching the implemented endpoints and a
 * typed Chinese-native error. It never converts an HTTP/network/invalid-JSON
 * failure into an empty success, never exposes audit payloads (machine codes,
 * object ids, attempts, owners, recovery actions, audit detail/context), and
 * carries no local absolute paths. Non-ok error `detail` is normalized to
 * exactly the four approved public fields (`message`, `responsible_area`,
 * `can_retry`, `next_step`) when they exist; every other top-level or nested
 * server key is discarded. User-facing messages contain no English/program
 * labels and no API/backend/log wording. There is no exception-card method:
 * clients never invent a catalog failure.
 */

export class ProtocolWorkspaceApiError extends Error {
 constructor(message, { status = 0, detail = null } = {}) {
 super(message);
 this.name = "ProtocolWorkspaceApiError";
 this.status = status;
 this.detail = detail;
 }
}

function projectPath(projectId) {
 return encodeURIComponent(String(projectId || ""));
}

function workflowPath(projectId, workflowRunId) {
 return `/api/projects/${projectPath(projectId)}/protocol-workflow/workflow-runs/${encodeURIComponent(String(workflowRunId))}`;
}

export function createProtocolWorkspaceApi({ fetchImpl = globalThis.fetch } = {}) {
 if (typeof fetchImpl !== "function") {
 throw new ProtocolWorkspaceApiError("当前环境不支持方案工作台请求。");
 }

 const request = async (path, options = {}) => {
 let response;
 try {
 response = await fetchImpl(path, {
 ...options,
 headers: { Accept: "application/json", ...(options.headers || {}) },
 });
 } catch (error) {
 if (error && error.name === "AbortError") throw error;
 // Network/transport failures never leak the underlying (possibly
 // English/program) message into user-facing copy.
 throw new ProtocolWorkspaceApiError("方案工作台请求失败。", {
 status: 0,
 detail: null,
 });
 }
 let payload = null;
 try {
 payload = await response.json();
 } catch {
 throw new ProtocolWorkspaceApiError(
 "方案工作台返回内容无法解析，本次请求未能完成。",
 { status: response.status, detail: null },
 );
 }
 if (!response.ok) {
 const rawDetail = payload && typeof payload === "object" ? payload.detail : null;
 // Normalize defensively: keep ONLY the four approved public fields
 // (message / responsible_area / can_retry / next_step) and discard any
 // top-level or nested audit-shaped key (machine codes, object ids,
 // attempts, owners, recovery actions, audit detail/context).
 let detail = null;
 if (rawDetail && typeof rawDetail === "object") {
 const normalized = {};
 if (typeof rawDetail.message === "string") normalized.message = rawDetail.message;
 if (typeof rawDetail.responsible_area === "string") normalized.responsible_area = rawDetail.responsible_area;
 if (typeof rawDetail.can_retry === "boolean") normalized.can_retry = rawDetail.can_retry;
 if (typeof rawDetail.next_step === "string") normalized.next_step = rawDetail.next_step;
 if (Object.keys(normalized).length > 0) detail = normalized;
 }
 const message =
 detail && typeof detail.message === "string"
 ? detail.message
 : "方案工作台未能完成本次操作。";
 throw new ProtocolWorkspaceApiError(message, {
 status: response.status,
 detail,
 });
 }
 return payload;
 };

 const post = (path, body, signal) =>
 request(path, {
 method: "POST",
 signal,
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify(body),
 });

 const get = (path, signal) => request(path, { method: "GET", signal });

 return {
 createStudyDefinition(projectId, payload, { signal } = {}) {
 return post(
 `/api/projects/${projectPath(projectId)}/protocol-workflow/study-definitions`,
 payload,
 signal,
 );
 },
 applyStudyDecision(projectId, studyDefinitionId, payload, { signal } = {}) {
 return post(
 `/api/projects/${projectPath(projectId)}/protocol-workflow/study-definitions/${encodeURIComponent(String(studyDefinitionId))}/decisions`,
 payload,
 signal,
 );
 },
 getStudyDefinition(projectId, studyDefinitionId, { signal } = {}) {
 return get(
 `/api/projects/${projectPath(projectId)}/protocol-workflow/study-definitions/${encodeURIComponent(String(studyDefinitionId))}`,
 signal,
 );
 },
 getStudyDefinitionEvents(projectId, studyDefinitionId, { signal } = {}) {
 return get(
 `/api/projects/${projectPath(projectId)}/protocol-workflow/study-definitions/${encodeURIComponent(String(studyDefinitionId))}/events`,
 signal,
 );
 },
 getDecisionGraph(projectId, studyDefinitionId, { signal } = {}) {
 return get(
 `/api/projects/${projectPath(projectId)}/protocol-workflow/study-definitions/${encodeURIComponent(String(studyDefinitionId))}/decision-graph`,
 signal,
 );
 },
 getWorkflowRun(projectId, workflowRunId, { signal } = {}) {
 return get(`${workflowPath(projectId, workflowRunId)}`, signal);
 },
 getWorkflowRunProgress(projectId, workflowRunId, studyDefinitionId, { signal } = {}) {
 return get(
 `${workflowPath(projectId, workflowRunId)}/progress?study_definition_id=${encodeURIComponent(String(studyDefinitionId))}`,
 signal,
 );
 },
 getWorkflowRunGates(projectId, workflowRunId, studyDefinitionId, { signal } = {}) {
 return get(
 `${workflowPath(projectId, workflowRunId)}/gates?study_definition_id=${encodeURIComponent(String(studyDefinitionId))}`,
 signal,
 );
 },
 getWorkflowRunDecisionRequests(projectId, workflowRunId, studyDefinitionId, { signal } = {}) {
 return get(
 `${workflowPath(projectId, workflowRunId)}/decision-requests?study_definition_id=${encodeURIComponent(String(studyDefinitionId))}`,
 signal,
 );
 },
 pinRunManifest(projectId, workflowRunId, payload, { signal } = {}) {
 return post(`${workflowPath(projectId, workflowRunId)}/manifest`, payload, signal);
 },
 decomposeWorkPackages(projectId, workflowRunId, payload, { signal } = {}) {
 return post(`${workflowPath(projectId, workflowRunId)}/decomposition`, payload, signal);
 },
 };
}

.structured-table-designer {
 --std-orange: var(--orange, #e87524);
 --std-orange-dark: var(--orange-dark, #bd5513);
 --std-text: var(--text, #1f2933);
 --std-muted: var(--muted, #697586);
 --std-line: var(--line, #d9dee5);
 --std-soft-line: var(--soft-line, #e8ebef);
 --std-canvas: #f4f6f8;
 --std-panel: #ffffff;
 position: fixed;
 inset: 0;
 z-index: 1200;
 display: grid;
 grid-template-rows: 54px auto auto auto minmax(0, 1fr);
 min-width: 1120px;
 min-height: 680px;
 background: var(--std-canvas);
 color: var(--std-text);
 font-family: inherit;
 letter-spacing: 0;
}

.std-titlebar {
 min-width: 0;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 16px;
 padding: 0 14px;
 border-bottom: 1px solid var(--std-line);
 background: var(--std-panel);
}

.std-title-identity,
.std-title-status,
.std-title-identity > div,
.std-tool-group,
.std-tool-group > span,
.std-status,
.std-section-heading,
.std-confirmed,
.std-note-head,
.std-note-head > span,
.std-add-note,
.std-confirm-button {
 display: flex;
 align-items: center;
}

.std-title-identity {
 min-width: 0;
 gap: 9px;
}

.std-title-identity > svg {
 flex: 0 0 auto;
 color: var(--std-orange-dark);
}

.std-title-identity > div {
 min-width: 0;
 align-items: flex-start;
 flex-direction: column;
 gap: 2px;
}

.std-title-identity strong,
.std-title-identity span {
 max-width: min(720px, 48vw);
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.std-title-identity strong {
 font-size: 14px;
}

.std-title-identity span {
 color: var(--std-muted);
 font-size: 11px;
}

.std-title-status {
 flex: 0 0 auto;
 gap: 7px;
}

.std-status,
.std-domain-label {
 min-height: 26px;
 border: 1px solid var(--std-line);
 border-radius: 4px;
 padding: 0 8px;
 font-size: 11px;
 white-space: nowrap;
}

.std-status {
 gap: 5px;
}

.std-status.editable {
 border-color: #f3bf96;
 background: #fff8f3;
 color: var(--std-orange-dark);
}

.std-status.read-only {
 background: #f7f8fa;
 color: var(--std-muted);
}

.std-domain-label {
 display: inline-flex;
 align-items: center;
 background: #fbfcfd;
}

.std-toolbar {
 min-height: 46px;
 display: flex;
 align-items: center;
 gap: 8px;
 padding: 6px 14px;
 border-bottom: 1px solid var(--std-line);
 background: #fbfcfd;
 overflow-x: auto;
}

.std-tool-group {
 flex: 0 0 auto;
 gap: 4px;
 padding-right: 8px;
 border-right: 1px solid var(--std-line);
}

.std-tool-group > span {
 gap: 4px;
 margin-right: 2px;
 color: var(--std-muted);
 font-size: 11px;
 font-weight: 700;
}

.std-icon-button,
.std-text-button,
.std-add-note,
.std-confirm-button,
.std-inspector-tabs button,
.std-orientation-control button,
.std-plan-states button,
.std-mapping-boundary button {
 border: 1px solid var(--std-line);
 border-radius: 4px;
 background: #fff;
 color: var(--std-text);
 font: inherit;
 cursor: pointer;
}

.std-icon-button {
 width: 30px;
 height: 30px;
 display: inline-grid;
 place-items: center;
 padding: 0;
}

.std-icon-button:hover:not(:disabled),
.std-text-button:hover:not(:disabled),
.std-add-note:hover:not(:disabled),
.std-confirm-button:hover:not(:disabled),
.std-mapping-boundary button:hover:not(:disabled) {
 border-color: var(--std-orange);
 color: var(--std-orange-dark);
 background: #fff8f3;
}

.std-icon-button.active,
.std-text-button.active {
 border-color: var(--std-orange);
 background: #fff8f3;
 color: var(--std-orange-dark);
}

.std-icon-button:disabled,
.std-text-button:disabled,
.std-add-note:disabled,
.std-confirm-button:disabled,
.std-plan-states:disabled button,
.std-orientation-control button:disabled,
.std-mapping-boundary button:disabled {
 cursor: not-allowed;
 opacity: 0.42;
}

.std-text-button {
 min-width: 38px;
 height: 30px;
 padding: 0 8px;
 font-size: 11px;
}

.std-tool-hint {
 margin-left: auto;
 color: var(--std-muted);
 font-size: 11px;
 white-space: nowrap;
}

.std-cell-rich-panel {
 min-width: 0;
 display: grid;
 grid-template-columns: 124px minmax(620px, 1fr) minmax(260px, 380px);
 align-items: stretch;
 gap: 8px;
 padding: 7px 14px;
 border-bottom: 1px solid var(--std-line);
 background: #fff;
}

.std-cell-rich-empty {
 min-height: 34px;
 display: flex;
 align-items: center;
 padding: 0 14px;
 border-bottom: 1px solid var(--std-line);
 background: #fff;
 color: var(--std-muted);
 font-size: 11px;
}

.std-cell-rich-identity {
 min-width: 0;
 display: flex;
 flex-direction: column;
 justify-content: center;
 gap: 3px;
 border-right: 1px solid var(--std-line);
}

.std-cell-rich-identity strong {
 font-size: 12px;
}

