 durableJobController,
} from "./durableJobState.mjs";

import { useMemo, useRef, useState } from "react";
import { CheckCircle2, ChevronDown, ChevronUp } from "lucide-react";

function requestKey() {
 const suffix = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random()}`;
 return `ocr-consistency-confirm-${suffix}`;
}

async function readJson(response) {
 const payload = await response.json().catch(() => ({}));
 if (response.ok) return payload;
 throw new Error(typeof payload.detail === "string" ? payload.detail : `HTTP ${response.status}`);
}

export function MixedOcrReviewPanel({
 projectId,
 reviews = [],
 artifacts = [],
 onSettled = () => {},
}) {
 const keyRef = useRef("");
 const [expanded, setExpanded] = useState(false);
 const [busy, setBusy] = useState(false);
 const [message, setMessage] = useState("");
 const artifactsById = useMemo(
 () => new Map(artifacts.map((item) => [item.artifact_id, item])),
 [artifacts],
 );
 const pending = useMemo(
 () => reviews.filter((item) => (
 item.effective_status === "pending_medical_confirmation"
 && item.recheck_verdict === "review_required"
 )),
 [reviews],
 );

 if (!pending.length) return null;

 const confirmAll = async () => {
 setBusy(true);
 setMessage("");
 if (!keyRef.current) keyRef.current = requestKey();
 try {
 const response = await fetch(
 `/api/projects/${projectId}/medical-writing/references/ocr-consistency-reviews/batch-disposition`,
 {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 decision: "confirmed",
 comment: "已核对当前批次中 AI 定位的 OCR 衔接差异，同意按原始页面与已保存提取结果继续进入翻译和语料库流程。",
 actor: "medical_manager",
 idempotency_key: keyRef.current,
 }),
 },
 );
 const payload = await readJson(response);
 const failed = (payload.outcomes || []).filter((item) => (
 item.outcome === "failed" || item.outcome === "stale"
 ));
 if (failed.length) {
 setMessage(`${failed.length} 项状态已变化，请刷新后重试。`);
 } else {
 keyRef.current = "";
 setMessage("已批量确认，相关方案可继续进入翻译与语料库流程。");
 onSettled(payload);
 }
 } catch (error) {
 setMessage(`批量确认未完成：${error.message}`);
 } finally {
 setBusy(false);
 }
 };

 return (
 <section className="mixed-ocr-review-panel" data-testid="mixed-ocr-review-panel">
 <div className="mixed-ocr-review-summary">
 <div>
 <strong>{pending.length} 份方案的 OCR 衔接需确认</strong>
 <span>AI 已聚焦到具体页面；确认后可一次性继续后续流程。</span>
 </div>
 <button
 type="button"
 className="secondary-button"
 onClick={() => setExpanded((current) => !current)}
 aria-expanded={expanded}
 >
 {expanded ? <ChevronUp size={15} /> : <ChevronDown size={15} />}
 {expanded ? "收起" : "查看差异"}
 </button>
 <button
 type="button"
 className="primary-button"
 onClick={confirmAll}
 disabled={busy}
 >
 <CheckCircle2 size={15} />
 {busy ? "确认中…" : "批量确认并继续"}
 </button>
 </div>
 {expanded && (
 <div className="mixed-ocr-review-details">
 {pending.map((item) => {
 const artifact = artifactsById.get(item.artifact_id);
 return (
 <article key={`${item.artifact_id}-${item.recheck_id}`}>
 <div>
 <strong>{artifact?.nct_id || "已导入方案"}</strong>
 <span>{artifact?.filename || item.artifact_id}</span>
 </div>
 <p>{item.recheck_notes || "AI 建议对当前 OCR 衔接结果进行快速核对。"}</p>
 </article>
 );
 })}
 </div>
 )}
 {message && <p className="mixed-ocr-review-message">{message}</p>}
 </section>
 );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { AlertTriangle, CheckCircle2, Play, RefreshCw, RotateCcw } from "lucide-react";
import { WritingReferenceProgressJourney } from "./WritingReferenceProgressJourney";

const ACTIVE_BATCH_STATUSES = new Set(["accepted", "running"]);
const TERMINAL_BATCH_STATUSES = new Set([
 "completed",
 "completed_with_review_required",
 "completed_with_manual_upload_required",
 "partial_failure",
 "failed",
]);
const REFERENCE_DOCUMENT_TYPES = new Set(["protocol", "protocol_sap"]);
const FAILURE_STATUSES = new Set(["failed"]);
const REVIEW_STATUSES = new Set(["review_required", "needs_review", "mismatch"]);
const errorDetailLabels = {
 no_public_protocol_or_sap: "本次公开检索结果中未发现公开 Protocol，请手动导入已取得的研究方案原文。",
 no_public_protocol: "本次公开检索结果中未发现公开 Protocol，请手动导入已取得的研究方案原文。",
 source_artifact_invalidated: "当前来源版本已失效，请重新下载或手动导入当前版本。",
 service_restart_interrupted: "服务重启中断了本次处理，可仅重试该失败项。",
 standalone_sap_out_of_scope: "独立 SAP 不属于本批次 Protocol 语料范围。",
 public_document_content_invalid: "公开文件内容无法通过基本校验，请转入逐文件处理。",
 document_has_no_extractable_text: "文件未提取到可用文字，请核对原文件或改用可解析版本。",
 public_document_redirect_not_allowed: "公开下载地址已跳转至非授权来源，请人工核对来源。",
 registered_artifact_unavailable: "已登记的文件当前不可读取，请重新下载或手动导入。",
 validation_status_unsupported: "内容校验状态异常，请转入逐文件处理。",
};

const batchStatusLabels = {
 not_started: "待开始",
 accepted: "已受理",
 running: "批量准备中",
 completed: "批量准备完成",
 completed_with_review_required: "准备完成，待人工内容确认",
 completed_with_manual_upload_required: "准备完成，待手动导入",
 partial_failure: "部分失败",
 failed: "批次失败",
 awaiting_stage_admission: "等待下一阶段准入",
};

const stageLabels = {
 download: {
 pending: "待下载",
 running: "下载中",
 downloading: "下载中",
 succeeded: "已下载",
 review_required: "待人工处理",
 not_applicable: "不适用",
 failed: "下载失败",
 failed_retryable: "下载失败（可重试）",
 failed_terminal: "下载失败（终止）",
 },
 parse: {
 pending: "待解析",
 running: "解析中",
 extracting: "解析提取中",
 ocr_running: "OCR识别中",
 toc_planning: "目录识别中",
 succeeded: "已解析",
 review_required: "待人工处理",
 not_applicable: "不适用",
 failed: "解析失败",
 failed_retryable: "解析失败（可重试）",
 failed_terminal: "解析失败（终止）",
 },
 validation: {
 pending: "待校验",
 running: "校验中",
 translating_hy_mt2: "Hy-MT2翻译中",
 integration_qc: "衔接核对中",
 confirmed: "内容匹配",
 succeeded: "内容匹配",
 review_required: "待人工确认",
 needs_review: "待人工确认",
 mismatch: "内容不一致",
 user_overridden: "已确认沿用",
 not_applicable: "不适用",
 failed: "校验失败",
 failed_retryable: "校验失败（可重试）",
 failed_terminal: "校验失败（终止）",
 },
};

const newStageLabels = {
 extracting: "解析提取中",
 ocr_running: "OCR识别中",
 toc_planning: "目录识别中",
 translating_hy_mt2: "Hy-MT2翻译中",
 integration_qc: "衔接核对中",
 candidate_ready: "候选已就绪",
 fidelity_blocked: "忠实度阻断",
 failed_retryable: "失败（可重试）",
 failed_terminal: "失败（终止）",
};

const preparationProgressPhaseLabels = {
 pending: "等待开始处理",
 downloading: "正在下载公开 Protocol",
 native_extracting: "正在提取原生文本",
 ocr_rendering: "正在渲染 OCR 页面",
 ocr_completing: "正在完成 OCR 页面识别",
 extraction_persisting: "正在持久化结构提取结果",
 content_validating: "正在校验文件内容",
 completed: "文件准备完成",
 failed: "文件准备失败",
};

function stageLabel(stage, status) {
 const stageMap = stageLabels[stage];
 if (stageMap && stageMap[status]) return stageMap[status];
 if (newStageLabels[status]) return newStageLabels[status];
 return status;
}

function requestKey(prefix) {
 const suffix = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random()}`;
 return `${prefix}-${suffix}`;
}

async function readJson(response, { allowNotFound = false } = {}) {
 const payload = await response.json().catch(() => ({}));
 if (response.ok) return payload;
 if (allowNotFound && response.status === 404) return null;
 const error = new Error(typeof payload.detail === "string" ? payload.detail : `HTTP ${response.status}`);
 error.status = response.status;
 throw error;
}

function normalizedStatus(value, fallback = "pending") {
 return String(value || fallback).trim().toLowerCase();
}

function itemProgress(item) {
 const progress = item?.progress || {};
 return {
 phase: normalizedStatus(progress.phase, "pending"),
 current_substep: progress.current_substep || "",
 completed: Number(progress.completed || 0),
 total: Number(progress.total || 0),
 percent: Math.max(0, Math.min(100, Number(progress.percent || 0))),
 unit: progress.unit || "",
 context: progress.context || {},
 };
}

function progressSubstep(progress) {
 return progress.current_substep
 || preparationProgressPhaseLabels[progress.phase]
 || "等待真实处理边界";
}

function progressCountLabel(progress) {
 if (!progress.total) return "";
 if (progress.unit === "page" && String(progress.phase || "").startsWith("ocr_")) {
 return `已完成 ${progress.completed}/${progress.total} 个需识别页面`;
 }
 return `${progress.completed}/${progress.total}${progress.unit === "page" ? " 页" : ""}`;
}

function stageStatus(item, stage) {
 const stageState = stage === "download"
 ? item.ingest
 : stage === "parse"
 ? item.extraction
 : item.validation;
 return normalizedStatus(stageState?.status);
}

function rawBatchItems(batch) {
 return Array.isArray(batch?.items) ? batch.items : [];
}

function normalizeBatchItem(item, candidateById) {
 const nctId = item.nct_id || "";
 const documentId = item.document_id || item.item_id;
 const downloadStatus = stageStatus(item, "download");
 const parseStatus = stageStatus(item, "parse");
 const validationStageStatus = stageStatus(item, "validation");
 const validationStatus = normalizedStatus(item.validation_status, "") || validationStageStatus;
 const itemStatus = normalizedStatus(item.status);
 return {
 ...item,
 nct_id: nctId,
 document_id: documentId,
 artifact_id: item.artifact_id || "",
 study_title: item.study_title || candidateById.get(nctId)?.brief_title || candidateById.get(nctId)?.official_title || "",
 document_label: item.filename || (item.item_kind === "study_manual_upload_required" ? "未发现公开 Protocol" : "公开文件待确认"),
 document_type: item.document_type || (item.item_kind === "study_manual_upload_required" ? "待补充" : "Protocol"),
 document_date: item.document_date || "",
 download_status: downloadStatus,
 parse_status: parseStatus,
 validation_status: validationStatus,
 item_status: itemStatus,
 error_detail: itemStatus === "excluded"
 ? ""
 : errorDetailLabels[item.error_code] || item.error_detail || "",
 progress: item.progress || {},
 };
}

function preparationProgressStatus(item) {
 const statuses = [
 normalizedStatus(item.download_status, ""),
 normalizedStatus(item.parse_status, ""),
 normalizedStatus(item.validation_status, ""),
 normalizedStatus(item.item_status, ""),
 ];
 if (statuses.includes("excluded")) return "excluded";
 const terminalFailure = statuses.find((status) => ["failed_terminal", "manual_upload_required"].includes(status));
 if (terminalFailure) return "failed_terminal";
 const retryableFailure = statuses.find((status) => ["failed", "failed_retryable"].includes(status));
 if (retryableFailure) return "failed_retryable";
 if (statuses.some((status) => ["mismatch", "review_required", "needs_review"].includes(status))) {
 return "fidelity_blocked";
 }
 if (["confirmed", "succeeded", "user_overridden"].includes(normalizedStatus(item.validation_status, ""))) {
 return "prepared";
 }
 if (["prepared", "completed"].includes(normalizedStatus(item.item_status, ""))) return "prepared";
 if (["running", "validating"].includes(normalizedStatus(item.validation_status, ""))) return "validating";
 const parseStatus = normalizedStatus(item.parse_status, "");
 if (["extracting", "ocr_running", "toc_planning"].includes(parseStatus)) return parseStatus;
 if (parseStatus === "running") return "parsing";
 const downloadStatus = normalizedStatus(item.download_status, "");
 if (["running", "downloading", "accepted"].includes(downloadStatus)) return "downloading";
 return "waiting";
}

function buildPreviewItems(candidates, artifacts, validations, artifactSpanCounts) {
 const artifactByDocument = new Map(
 artifacts.filter((item) => item.source_status !== "user_uploaded")
 .map((item) => [item.source_document_id, item]),
 );
 const validationByArtifact = new Map(validations.map((item) => [item.artifact_id, item]));
 return candidates.flatMap((candidate) => {
 const documents = (candidate.public_documents || []).filter((document) => (
 REFERENCE_DOCUMENT_TYPES.has(String(document.document_type || "").toLowerCase())
 ));
 if (!documents.length) {
 return [{
 nct_id: candidate.nct_id,
 document_id: `missing-${candidate.nct_id}`,
 artifact_id: "",
 item_kind: "study_manual_upload_required",
 study_title: candidate.brief_title || candidate.official_title || "",
 document_label: "未发现公开 Protocol",
 document_type: "待补充",
 document_date: "",
 download_status: "not_applicable",
 parse_status: "not_applicable",
 validation_status: "not_applicable",
 item_status: "manual_upload_required",
 error_detail: "可在逐文件问题处理中手动导入已取得的原始文件。",
 }];
 }
 return documents.map((document) => {
 const artifact = artifactByDocument.get(document.document_id);
 const validation = artifact ? validationByArtifact.get(artifact.artifact_id) : null;
 const parsed = artifact && Number(artifactSpanCounts?.[artifact.artifact_id] || 0) > 0;
 const sourceInvalid = artifact && !artifact.source_current;
 return {
 nct_id: candidate.nct_id,
 document_id: document.document_id,
 artifact_id: artifact?.artifact_id || "",
 study_title: candidate.brief_title || candidate.official_title || "",
 document_label: document.label || document.filename || "公开文件",
 document_type: document.document_type || "Protocol",
 document_date: document.document_date || "",
 download_status: sourceInvalid ? "failed" : artifact ? "succeeded" : "pending",
 parse_status: sourceInvalid ? "pending" : parsed ? "succeeded" : "pending",
 validation_status: sourceInvalid ? "pending" : validation?.status || "pending",
 item_status: sourceInvalid
 ? "failed"
 : validation?.status === "confirmed" || validation?.status === "user_overridden"
 ? "prepared"
 : REVIEW_STATUSES.has(validation?.status)
 ? "review_required"
 : "pending",
 error_detail: sourceInvalid ? "来源版本已失效，不能在批次中自动重用。" : "",
 };
 });
 });
}

function stageTone(status) {
 if (status === "failed" || status === "mismatch") return "danger";
 if (["succeeded", "confirmed", "user_overridden"].includes(status)) return "success";
 if (status === "running") return "info";
 return "warning";
}

function itemNeedsAttention(item) {
 return item.item_status === "failed"
 || item.item_status === "review_required"
 || item.item_status === "manual_upload_required"
 || item.download_status === "failed"
 || item.parse_status === "failed"
 || item.validation_status === "failed"
 || REVIEW_STATUSES.has(item.validation_status)
 || REVIEW_STATUSES.has(item.item_status);
}

function nextStepLabel(item) {
 if (item.item_status === "excluded") return "无需处理";
 if (item.item_status === "manual_upload_required") return "手动导入 Protocol";
 if (item.item_status === "review_required") return "人工确认文件内容";
 if (item.item_status === "failed") return "重试失败项或逐文件处理";
 if (item.item_status === "prepared") return "待结构审核";
 if (item.item_status === "running") return "批次处理中";
 return "等待批次执行";
}

export function ReferencePreparationBatchPanel({
 projectId,
 snapshotId,
 candidates = [],
 artifacts = [],
 documentValidations = [],
 artifactSpanCounts = {},
 onOpenIssue = () => {},
 onBatchSettled = () => {},
}) {
 const generationRef = useRef(0);
 const createKeyRef = useRef("");
 const retryKeyRef = useRef({ batchId: "", key: "" });
 const advanceKeyRef = useRef({ batchId: "", key: "" });
 const settledMarkerRef = useRef("");
 const [batch, setBatch] = useState(null);
 const [loading, setLoading] = useState(false);
 const [action, setAction] = useState("");
 const [message, setMessage] = useState("");
 const [pollSuspended, setPollSuspended] = useState(false);

 const candidateById = useMemo(
 () => new Map(candidates.map((candidate) => [candidate.nct_id, candidate])),
 [candidates],
 );
 const previewItems = useMemo(
 () => buildPreviewItems(candidates, artifacts, documentValidations, artifactSpanCounts),
 [candidates, artifacts, documentValidations, artifactSpanCounts],
 );

 const loadLatest = useCallback(async ({ silent = false } = {}) => {
 if (!snapshotId) return;
 const generation = ++generationRef.current;
 if (!silent) setLoading(true);
 try {
 const response = await fetch(`/api/projects/${projectId}/medical-writing/references/preparation-batches/latest?snapshot_id=${encodeURIComponent(snapshotId)}`);
 const payload = await readJson(response, { allowNotFound: true });
 if (generation !== generationRef.current) return;
 setBatch(payload);
 setMessage("");
 setPollSuspended(false);
 } catch (error) {
 if (generation === generationRef.current) setMessage(`批次状态读取失败：${error.message}`);
 } finally {
 if (!silent && generation === generationRef.current) setLoading(false);
 }
 }, [projectId, snapshotId]);

 const loadBatch = useCallback(async (batchId, { polling = false } = {}) => {
 if (!batchId) return;
 const generation = ++generationRef.current;
 if (!polling) setLoading(true);
 try {
 const response = await fetch(`/api/projects/${projectId}/medical-writing/references/preparation-batches/${encodeURIComponent(batchId)}`);
 const payload = await readJson(response);
 if (generation !== generationRef.current) return;
 setBatch(payload);
 setMessage("");
 setPollSuspended(false);
 } catch (error) {
 if (generation !== generationRef.current) return;
 setMessage(`${polling ? "批次轮询" : "批次刷新"}失败：${error.message}`);
 if (polling) setPollSuspended(true);
 } finally {
 if (!polling && generation === generationRef.current) setLoading(false);
 }
 }, [projectId]);

 useEffect(() => {
 generationRef.current += 1;
 setBatch(null);
 setMessage("");
 setPollSuspended(false);
 createKeyRef.current = "";
 retryKeyRef.current = { batchId: "", key: "" };
 advanceKeyRef.current = { batchId: "", key: "" };
 settledMarkerRef.current = "";
 loadLatest();
 return () => { generationRef.current += 1; };
 }, [loadLatest]);

 const batchStatus = normalizedStatus(batch?.status, "not_started");
 const batchId = batch?.batch_id || "";
 const batchRevision = batch?.updated_at || batchStatus;

 useEffect(() => {
 if (!batchId || !ACTIVE_BATCH_STATUSES.has(batchStatus) || pollSuspended) return undefined;
 const timer = globalThis.setTimeout(() => loadBatch(batchId, { polling: true }), 2000);
 return () => globalThis.clearTimeout(timer);
 }, [batchId, batchStatus, batchRevision, loadBatch, pollSuspended]);

 useEffect(() => {
 if (!batchId || !TERMINAL_BATCH_STATUSES.has(batchStatus)) return;
 const marker = `${batchId}:${batchRevision}`;
 if (settledMarkerRef.current === marker) return;
 settledMarkerRef.current = marker;
 onBatchSettled(batch);
 }, [batch, batchId, batchRevision, batchStatus, onBatchSettled]);

 const batchItems = useMemo(
 () => rawBatchItems(batch).map((item) => normalizeBatchItem(item, candidateById)),
 [batch, candidateById],
 );
 const rows = batchItems.length ? batchItems : previewItems;
 const currentProgressItem = batchItems.find((item) => item.item_status === "running")
 || batchItems.find((item) => item.item_status === "pending")
 || batchItems.find((item) => item.item_status === "failed");
 const projectedProgress = batch?.progress || (currentProgressItem ? itemProgress(currentProgressItem) : null);
 const progress = {
 ...itemProgress(currentProgressItem),
 ...projectedProgress,
 completed: Number(projectedProgress?.completed ?? itemProgress(currentProgressItem).completed ?? 0),
 total: Number(projectedProgress?.total ?? itemProgress(currentProgressItem).total ?? 0),
 percent: Math.max(0, Math.min(100, Number(projectedProgress?.percent ?? itemProgress(currentProgressItem).percent ?? 0))),
 };
 const currentNctId = progress.context?.nct_id || batch?.current_nct_id || currentProgressItem?.nct_id || "";
 const currentDocumentLabel = progress.context?.document_label || batch?.current_document_label
 || currentProgressItem?.document_label
 || "";
 const studyCount = new Set(rows.map((item) => item.nct_id).filter(Boolean)).size;
 const fileCount = rows.filter((item) => item.item_kind !== "study_manual_upload_required").length;
 const failedCount = rows.filter((item) => (
 FAILURE_STATUSES.has(item.item_status)
 || FAILURE_STATUSES.has(item.download_status)
 || FAILURE_STATUSES.has(item.parse_status)
 || FAILURE_STATUSES.has(item.validation_status)
 )).length;
 const reviewCount = rows.filter((item) => REVIEW_STATUSES.has(item.validation_status) || REVIEW_STATUSES.has(item.item_status)).length;
 const manualUploadCount = rows.filter((item) => item.item_status === "manual_upload_required").length;
 const finishedCount = Number(batch?.prepared_count || 0)
 + Number(batch?.review_required_count || 0)
 + Number(batch?.manual_upload_required_count || 0)
 + Number(batch?.failed_count || 0)
 + Number(batch?.excluded_count || 0);
 const active = ACTIVE_BATCH_STATUSES.has(batchStatus);

 const startBatch = async () => {
 setAction("start");
 setMessage("");
 if (!createKeyRef.current) createKeyRef.current = requestKey("reference-preparation-batch");
 try {
 const response = await fetch(`/api/projects/${projectId}/medical-writing/references/preparation-batches`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 snapshot_id: snapshotId,
 actor: "medical_manager",
 idempotency_key: createKeyRef.current,
 }),
 });
 const payload = await readJson(response);
 setBatch(payload);
 setPollSuspended(false);
 setMessage("批量准备已启动；刷新页面后仍可恢复当前进度。");
 createKeyRef.current = "";
 } catch (error) {
 setMessage(`批量准备未启动：${error.message}`);
 } finally {
 setAction("");
 }
 };

 const retryFailed = async () => {
 if (!batchId) return;
 setAction("retry");
 setMessage("");
 if (retryKeyRef.current.batchId !== batchId || !retryKeyRef.current.key) {
 retryKeyRef.current = { batchId, key: requestKey("reference-preparation-retry") };
 }
 try {
 const response = await fetch(`/api/projects/${projectId}/medical-writing/references/preparation-batches/${encodeURIComponent(batchId)}/retry`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({ actor: "medical_manager", idempotency_key: retryKeyRef.current.key }),
 });
 const payload = await readJson(response);
 setBatch(payload);
 setPollSuspended(false);
 setMessage("已仅重新提交失败项；成功项和待人工确认项不会重复处理。");
 retryKeyRef.current = { batchId: "", key: "" };
 } catch (error) {
 setMessage(`失败项重试未启动：${error.message}`);
 } finally {
 setAction("");
 }
 };

 const advanceStage = async () => {
 if (!batchId || batchStatus !== "awaiting_stage_admission") return;
 setAction("advance");
 setMessage("");
 if (advanceKeyRef.current.batchId !== batchId || !advanceKeyRef.current.key) {
 advanceKeyRef.current = { batchId, key: requestKey("reference-preparation-stage") };
 }
 try {
 const response = await fetch(`/api/projects/${projectId}/medical-writing/references/preparation-batches/${encodeURIComponent(batchId)}/advance-stage`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 actor: "medical_manager",
 idempotency_key: advanceKeyRef.current.key,
 }),
 });
 const payload = await readJson(response);
 setBatch(payload);
 setPollSuspended(false);
 setMessage("已准入下一阶段原文；成功项不会重复下载或 OCR。批次将继续处理。");
 advanceKeyRef.current = { batchId: "", key: "" };
 } catch (error) {
 setMessage(`下一阶段准入未启动：${error.message}`);
 } finally {
 setAction("");
 }
 };

 const refreshBatch = () => {
 setPollSuspended(false);
 return batchId ? loadBatch(batchId) : loadLatest();
 };

 return (
 <section
 className="writing-reference-preparation-batch"
 data-testid="reference-preparation-batch"
 data-batch-status={batchStatus}
 data-batch-id={batchId || undefined}
 >
 <header className="writing-reference-batch-head">
 <div>
 <span>已锁定竞品篮子</span>
 <strong>本批次 Protocol 准备</strong>
 <small>本批次只执行公开文件下载、结构解析和内容校验；结构确认、监管中文审核与语料准入在后续审核工作区完成。</small>
 </div>
 <span className={`writing-reference-batch-status ${batchStatus}`}>{batchStatusLabels[batchStatus] || batchStatus}</span>
 </header>

 <div className="writing-reference-batch-summary" data-testid="reference-batch-summary" role="status" aria-live="polite">
 <span><b>{studyCount}</b>项研究</span>
 <span><b>{fileCount}</b>份公开文件</span>
 <span className={failedCount ? "danger" : ""}><b>{failedCount}</b>项失败</span>
 <span className={reviewCount ? "warning" : ""}><b>{reviewCount}</b>项待人工确认</span>
 <span className={manualUploadCount ? "warning" : ""}><b>{manualUploadCount}</b>项待手动导入</span>
 </div>

 {batchItems.length > 0 && (
 <>
 <WritingReferenceProgressJourney
 items={batchItems.map((item) => ({ status: preparationProgressStatus(item) }))}
 compact={true}
 />
 <div
 className="writing-reference-preparation-progress"
 data-testid="reference-preparation-progress"
 data-progress-phase={progress.phase}
 data-progress-percent={progress.percent}
 role="status"
 aria-live="polite"
 aria-busy={active}
 >
 <div className="writing-reference-preparation-progress-main">
 <strong>{progressSubstep(progress)}</strong>
 {currentNctId && currentDocumentLabel && (
 <span>{currentNctId} / {currentDocumentLabel}</span>
 )}
 </div>
 <div className="writing-reference-preparation-progress-meta">
 {progress.total > 0 && <span>{progressCountLabel(progress)}</span>}
 <b>{progress.percent}%</b>
 </div>
 <progress max="100" value={progress.percent} aria-label="公开 Protocol 准备进度" />
 </div>
 </>
 )}

 <div className="writing-reference-batch-actions">
 {!batchId && (
 <button className="primary-button" type="button" data-action="start-batch" onClick={startBatch} disabled={!snapshotId || !candidates.length || Boolean(action) || loading}>
 <Play size={14} /> {action === "start" ? "启动中" : "开始批量准备"}
 </button>
 )}
 <button type="button" data-action="refresh-batch" onClick={refreshBatch} disabled={Boolean(action) || loading}>
 <RefreshCw size={14} className={loading ? "spin" : ""} /> 刷新
 </button>
 {batchId && (
 <button type="button" data-action="retry-failed" onClick={retryFailed} disabled={!failedCount || active || Boolean(action) || loading}>
 <RotateCcw size={14} /> {action === "retry" ? "重试中" : "仅重试失败项"}
 </button>
 )}
 {batchId && batchStatus === "awaiting_stage_admission" && Number(batch?.deferred_item_count || 0) > 0 && (
 <button className="primary-button" type="button" data-action="advance-stage" onClick={advanceStage} disabled={Boolean(action) || loading} title="仅准入下一阶段延后原文；已完成项不会重复处理">
 <Play size={14} /> {action === "advance" ? "准入中" : `准入下一阶段（${batch.deferred_item_count}）`}
 </button>
 )}
 {active && <span>批次处理中，完成 {finishedCount}/{Number(batch?.item_count || rows.length)}</span>}
 </div>

 {message && <p className={`writing-reference-batch-message ${message.includes("失败") || message.includes("未启动") ? "danger" : ""}`} role="alert">{message}</p>}

 <div className="writing-reference-batch-table-wrap" data-testid="reference-batch-scope">
 <table className="writing-reference-batch-table">
 <thead><tr><th>研究</th><th>公开文件</th><th>下载</th><th>结构解析</th><th>内容校验</th><th>下一步</th></tr></thead>
 <tbody>
 {rows.map((item) => {
 const needsAttention = itemNeedsAttention(item);
 const validationIssue = item.item_status === "review_required" && Boolean(item.artifact_id);
 return (
 <tr
 key={`${item.nct_id}:${item.document_id}`}
 data-testid="reference-preparation-row"
 data-nct-id={item.nct_id}
 data-document-id={item.document_id}
 data-item-status={item.item_status}
 data-download-status={item.download_status}
 data-parse-status={item.parse_status}
 data-validation-status={item.validation_status}
 className={needsAttention ? "requires-attention" : ""}
 >
 <td><strong>{item.nct_id || "研究待确认"}</strong><small>{item.study_title || "标题待核验"}</small></td>
 <td><strong>{item.document_label}</strong><small>{item.document_type}{item.document_date ? ` · ${item.document_date}` : ""}</small>{item.progress?.current_substep && item.item_status === "running" && <small data-testid="reference-preparation-item-progress">{item.progress.current_substep}{item.progress.total ? ` · ${progressCountLabel(item.progress)}` : ""}</small>}{item.error_detail && <em><AlertTriangle size={12} />{item.error_detail}</em>}</td>
 <td><span className={`writing-reference-stage ${stageTone(item.download_status)}`} data-stage="download" data-status={item.download_status}>{stageLabel('download', item.download_status)}</span></td>
 <td><span className={`writing-reference-stage ${stageTone(item.parse_status)}`} data-stage="parse" data-status={item.parse_status}>{stageLabel('parse', item.parse_status)}</span></td>
 <td><span className={`writing-reference-stage ${stageTone(item.validation_status)}`} data-stage="validation" data-status={item.validation_status}>{stageLabel('validation', item.validation_status)}</span></td>
 <td>
 <div className="writing-reference-next-step-cell">
 <span className="writing-reference-next-step">{!needsAttention && <CheckCircle2 size={13} />}{nextStepLabel(item)}</span>
 {needsAttention && <button type="button" data-action="open-issue" onClick={() => onOpenIssue({ ...item, issue_kind: validationIssue ? "content_validation" : "single_document" })}>处理问题</button>}
 </div>
 </td>
 </tr>
 );
 })}
 </tbody>
 </table>
 {!rows.length && <div className="writing-reference-batch-empty">锁定篮子中没有可准备的公开 Protocol。</div>}
 </div>
 </section>
 );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { ArrowUpDown, CheckCheck, Eye, Languages, Play, RefreshCw, RotateCcw } from "lucide-react";
import { WritingReferenceProgressJourney } from "./WritingReferenceProgressJourney";
import {
 pollDurableMwJob,
 buildLocator,
 extractArtifactBatchId,
 resolveRetryJobId,
 mergeRetryLocator,
 acknowledgeTranslationDomain,
} from "../medical-writing/useDurableMwJob";
import {
 deriveDocumentTranslationProgress,
 formatDocumentTranslationProgressSummary,
} from "./progressJourneyLogic.mjs";

const ACTIVE_BATCH_STATUSES = new Set(["accepted", "running"]);
const TERMINAL_BATCH_STATUSES = new Set([
 "completed",
 "completed_with_blocked",
 "partial_failure",
 "failed",
]);
const FAILED_ITEM_STATUSES = new Set(["failed_retryable", "failed_terminal"]);
const EXCLUSION_EXAMPLE_LIMIT = 4;
// The server's translation contract currently exposes only these six M11
// anchors. Other mapped anchors remain visible for transparency, but are
// disabled instead of being submitted as an invalid batch scope.
const SUPPORTED_TRANSLATION_ANCHORS = new Set([
 "eligibility",
 "objectives_endpoints",
 "safety",
 "schedule",
 "statistics",
 "synopsis",
]);

const batchStatusLabels = {
 not_started: "尚未生成",
 accepted: "已受理",
 running: "生成中",
 completed: "已完成",
 completed_with_blocked: "完成，有忠实度阻断",
 partial_failure: "部分失败",
 failed: "批次失败",
};

const generationLabels = {
 pending: ["待生成", "warning"],
 running: ["生成中", "info"],
 excluded: ["规划后排除", "neutral"],
 candidate_ready: ["候选已就绪", "success"],
 fidelity_blocked: ["忠实度阻断", "danger"],
 failed_retryable: ["失败，可重试", "danger"],
 failed_terminal: ["终止失败", "danger"],
};

const fidelityLabels = {
 not_checked: ["待机器检查", "warning"],
 passed: ["机器检查通过", "success"],
 blocked: ["忠实度阻断", "danger"],
};

const reviewLabels = {
 not_confirmed: ["待作者确认", "warning"],
 confirmed: ["作者已确认", "success"],
 returned: ["已退回", "warning"],
 rejected: ["已拒绝", "danger"],
};

const admissionLabels = {
 not_admitted: ["未准入", "neutral"],
 admitted: ["已准入", "success"],
 invalidated: ["准入已失效", "danger"],
};

const exclusionReasonLabels = {
 no_current_artifact: "没有当前有效的已登记文件",
 validation_missing: "文件内容核验尚未建立",
 validation_not_confirmed: "文件内容核验尚未确认",
 validation_document_hash_mismatch: "文件版本与核验记录不一致",
 validation_state_stale: "文件核验状态已过期",
 validation_extraction_stale: "文件内容核验未绑定当前结构解析版本",
 latest_extraction_missing: "没有当前结构解析版本",
 latest_extraction_has_no_spans: "当前解析版本没有片段",
 structure_review_missing: "结构医学审核尚未建立",
 structure_review_not_approved: "结构医学审核尚未通过",
 source_text_hash_mismatch: "片段原文版本不一致",
 semantic_fragment_incomplete: "原文为跨块或跨页的不完整语义片段",
 unmapped: "未映射到 M11 结构",
 standalone_sap_not_corpus_input: "独立SAP不进入竞品方案语料库",
 combined_protocol_boundary_unresolved: "合并文件未能可靠定位Protocol与SAP边界",
 sap_section_excluded_from_protocol_corpus: "合并文件中的SAP章节已排除",
 anchor_filtered: "不在本次所选 M11 结构范围",
};

function requestKey(prefix) {
 const suffix = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random()}`;
 return `${prefix}-${suffix}`;
}

async function readJson(response, { allowNotFound = false } = {}) {
 if (allowNotFound && response.status === 404) return null;
 const payload = await response.json().catch(() => ({}));
 if (response.ok) return payload;
 const detail = typeof payload.detail === "string"
 ? payload.detail
 : payload.detail?.message || payload.message || `HTTP ${response.status}`;
 const error = new Error(detail);
 error.status = response.status;
 throw error;
}

function normalizedStatus(value, fallback) {
 return String(value || fallback || "").trim().toLowerCase();
}

function safeCount(value, fallback = 0) {
 const count = Number(value);
 return Number.isFinite(count) && count >= 0 ? count : fallback;
}

function selectedScopeMatchesPreview(preview, selectedAnchors) {
 if (!preview) return false;
 const returned = [...(preview.anchor_filter || [])].sort();
 const selected = [...selectedAnchors].sort();
 return returned.length === selected.length
 && returned.every((anchor, index) => anchor === selected[index]);
}

function optionsFromPreview(preview) {
 return (preview?.anchor_summaries || [])
 .map((summary) => ({
 value: String(summary.ich_m11_anchor || "").trim(),
 eligibleNew: safeCount(summary.eligible_new),
 existingCandidate: safeCount(summary.existing_candidate),
 fidelityBlocked: safeCount(summary.fidelity_blocked),
 }))
 .map((option) => ({
 ...option,
 count: option.eligibleNew + option.existingCandidate + option.fidelityBlocked,
 }))
 .filter((option) => option.value && option.value.toLowerCase() !== "unmapped" && option.count > 0)
 .sort((left, right) => left.value.localeCompare(right.value, "zh-CN"));
}

function supportedAnchors(anchors) {
 return [...new Set((anchors || []).filter((anchor) => SUPPORTED_TRANSLATION_ANCHORS.has(anchor)))];
}

function normalizeItem(item, index) {
 const generationStatus = normalizedStatus(item.generation_status, "pending");
 const hasPipelineLineage = Boolean(
 item.pipeline_fingerprint
 || item.hy_mt2_model
 || item.flash_plan_model
 || item.flash_qc_model
 || (item.pipeline_stage && item.pipeline_stage !== "extracting"),
 );
 const fidelityStatus = generationStatus === "fidelity_blocked"
 ? "blocked"
 : normalizedStatus(item.fidelity_status, "not_checked");
 return {
 rowKey: item.item_id || `${item.artifact_id || "item"}:${item.span_id || index}`,
 nctId: item.nct_id || "",
 artifactId: item.artifact_id || "",
 spanId: item.span_id || "",
 filename: item.filename || "",
 documentType: item.document_type || "",
 documentLabel: item.document_label || item.filename || "",
 documentTotal: Number(item.document_total) || 0,
 documentIndex: Number(item.document_index) || 0,
 chapterId: item.chapter_id || "",
 chapterTitle: item.chapter_title || "",
 chapterTotal: Number(item.chapter_total) || 0,
 chapterIndex: Number(item.chapter_index) || 0,
 chunkCount: Number(item.chunk_count) || 0,
 chunkCompleted: Number(item.chunk_completed) || 0,
 chunkRunning: Number(item.chunk_running) || 0,
 chunkFailed: Number(item.chunk_failed) || 0,
 chunkReused: Number(item.chunk_reused) || 0,
 blockerKind: item.blocker_kind || "",
 blockerMessage: item.blocker_message || "",
 anchor: item.ich_m11_anchor || "",
 sourceLocator: item.source_locator || "来源定位待返回",
 origin: item.origin || "new",
 generationStatus,
 translationId: item.translation_id || "",
 translationRevision: Number(item.translation_revision) || 0,
 pipelineStage: hasPipelineLineage ? normalizedStatus(item.pipeline_stage, "") : "",
 pipelineStageDetail: String(item.pipeline_stage_detail || ""),
 fidelityStatus,
 authorConfirmationStatus: normalizedStatus(
 item.author_confirmation_status,
 item.medical_review_status === "approved"
 ? "confirmed"
 : item.medical_review_status || "not_confirmed",
 ),
 admissionStatus: normalizedStatus(item.admission_status, "not_admitted"),
 fidelityFailureCodes: Array.isArray(item.fidelity_failure_codes) ? item.fidelity_failure_codes : [],
 };
}

function statusTag(status, dictionary, fallback = "状态待确认") {
 const [label, tone] = dictionary[status] || [fallback, "neutral"];
 return <span className={`tag ${tone}`}>{label}</span>;
}

function nextStep(row) {
 if (row.generationStatus === "pending") return "等待候选生成";
 if (row.generationStatus === "running") return row.pipelineStageDetail || "候选生成中";
 if (row.generationStatus === "excluded") return "不在所选章节范围，无需生成";
 if (row.generationStatus === "fidelity_blocked") return "核对原文与忠实度问题";
 if (row.generationStatus === "failed_retryable") return "可仅重试失败项";
 if (row.generationStatus === "failed_terminal") return "转逐片段问题处理";
 if (row.generationStatus !== "candidate_ready") return "等待状态确认";
 if (row.authorConfirmationStatus === "returned") return "按作者意见修订";
 if (row.authorConfirmationStatus === "rejected") return "作者已拒绝";
 if (row.authorConfirmationStatus !== "confirmed") return "逐片段核对并确认";
 if (row.admissionStatus === "admitted") return "已完成当前准入链";
 if (row.admissionStatus === "invalidated") return "复核失效准入记录";
 return "核对确认状态";
}

function batchReviewEligibleRow(row) {
 return row.generationStatus === "candidate_ready"
 && row.fidelityStatus === "passed"
 && row.authorConfirmationStatus === "not_confirmed"
 && row.admissionStatus !== "invalidated"
 && Boolean(row.translationId)
 && row.translationRevision >= 1;
}

function sortValue(row, key) {
 if (key === "study") return `${row.nctId} ${row.filename} ${row.documentType}`;
 if (key === "anchor") return `${row.anchor} ${row.sourceLocator}`;
 if (key === "generation") return row.generationStatus;
 if (key === "fidelity") return row.fidelityStatus;
 if (key === "review") return row.authorConfirmationStatus;
 if (key === "admission") return row.admissionStatus;
 return nextStep(row);
}

function SortHeader({ label, column, sort, onSort }) {
 const active = sort.key === column;
 return (
 <button
 type="button"
 className={active ? "active" : ""}
 onClick={() => onSort(column)}
 aria-label={`按${label}${active && sort.direction === "asc" ? "降序" : "升序"}排列`}
 >
 {label}<ArrowUpDown size={12} />
 </button>
 );
}

export function ReferenceTranslationBatchPanel({
 projectId,
 snapshotId,
 glossaryVersion = "cms_regulatory_zh_v1",
 onOpenSpan = () => {},
 onBatchSettled = () => {},
}) {
 const previewGenerationRef = useRef(0);
 const batchGenerationRef = useRef(0);
 const batchRequestInFlightRef = useRef(false);
 const createKeyRef = useRef("");
 const retryKeyRef = useRef({ batchId: "", key: "" });
 const batchReviewKeyRef = useRef({ batchId: "", key: "" });
 const selectionKeyRef = useRef("");
 const settledMarkerRef = useRef("");
 const [preview, setPreview] = useState(null);
 const [batch, setBatch] = useState(null);
 const [availableAnchors, setAvailableAnchors] = useState([]);
 const [selectedAnchors, setSelectedAnchors] = useState([]);
 const [statusFilter, setStatusFilter] = useState("all");
 const [tableAnchorFilter, setTableAnchorFilter] = useState("all");
 const [sort, setSort] = useState({ key: "study", direction: "asc" });
 const [previewLoading, setPreviewLoading] = useState(false);
 const [batchLoading, setBatchLoading] = useState(false);
 const [action, setAction] = useState("");
 const [previewError, setPreviewError] = useState("");
 const [batchError, setBatchError] = useState("");
 const [notice, setNotice] = useState("");
 const [pollSuspended, setPollSuspended] = useState(false);
 const [durableJobId, setDurableJobId] = useState("");

 const scopeKey = `${projectId}:${snapshotId}:${glossaryVersion}`;
 const selectedAnchorKey = useMemo(
 () => [...selectedAnchors].sort().join("|"),
 [selectedAnchors],
 );

 const loadPreview = useCallback(async (anchors, { silent = false } = {}) => {
 if (!snapshotId) return;
 const generation = ++previewGenerationRef.current;
 if (!silent) setPreviewLoading(true);
 const params = new URLSearchParams({ snapshot_id: snapshotId, glossary_version: glossaryVersion });
 anchors.forEach((anchor) => params.append("anchor_filter", anchor));
 try {
 const response = await fetch(`/api/projects/${projectId}/medical-writing/references/translation-batches/preview?${params.toString()}`);
 const payload = await readJson(response);
 if (generation !== previewGenerationRef.current) return;
 const returnedAnchors = optionsFromPreview(payload);
 setPreview(payload);
 setAvailableAnchors((current) => {
 const merged = new Map(current.map((item) => [item.value, item]));
 returnedAnchors.forEach((item) => merged.set(item.value, item));
 return [...merged.values()].sort((left, right) => left.value.localeCompare(right.value, "zh-CN"));
 });
 if (selectionKeyRef.current !== scopeKey) {
 selectionKeyRef.current = scopeKey;
 setSelectedAnchors(supportedAnchors(returnedAnchors.map((item) => item.value)));
 }
 setPreviewError("");
 } catch (error) {
 if (generation === previewGenerationRef.current) setPreviewError(`候选范围预览失败：${error.message}`);
 } finally {
 if (!silent && generation === previewGenerationRef.current) setPreviewLoading(false);
 }
 }, [glossaryVersion, projectId, scopeKey, snapshotId]);

 const loadBatch = useCallback(async (batchId, { polling = false } = {}) => {
 if (!batchId || batchRequestInFlightRef.current) return;
 batchRequestInFlightRef.current = true;
 const generation = ++batchGenerationRef.current;
 if (!polling) setBatchLoading(true);
 try {
 const response = await fetch(`/api/projects/${projectId}/medical-writing/references/translation-batches/${encodeURIComponent(batchId)}`);
 const payload = await readJson(response);
 if (generation !== batchGenerationRef.current) return;
 setBatch(payload);
 setBatchError("");
 setPollSuspended(false);
 } catch (error) {
 if (generation !== batchGenerationRef.current) return;
 setBatchError(`${polling ? "批次状态轮询" : "批次刷新"}失败：${error.message}`);
 if (polling) setPollSuspended(true);
 } finally {
 batchRequestInFlightRef.current = false;
 if (!polling && generation === batchGenerationRef.current) setBatchLoading(false);
 }
 }, [projectId]);

 const loadLatest = useCallback(async () => {
 if (!snapshotId || batchRequestInFlightRef.current) return;
 batchRequestInFlightRef.current = true;
 const generation = ++batchGenerationRef.current;
 setBatchLoading(true);
 try {
 const response = await fetch(`/api/projects/${projectId}/medical-writing/references/translation-batches/latest?snapshot_id=${encodeURIComponent(snapshotId)}`);
 const payload = await readJson(response, { allowNotFound: true });
 if (generation !== batchGenerationRef.current) return;
 setBatch(payload);
 if (payload?.anchor_filter?.length) {
 selectionKeyRef.current = scopeKey;
 setSelectedAnchors(supportedAnchors(payload.anchor_filter));
 }
 setBatchError("");
 setPollSuspended(false);
 } catch (error) {
 if (generation === batchGenerationRef.current) setBatchError(`当前批次读取失败：${error.message}`);
 } finally {
 batchRequestInFlightRef.current = false;
 if (generation === batchGenerationRef.current) setBatchLoading(false);
 }
 }, [projectId, scopeKey, snapshotId]);

 useEffect(() => {
 previewGenerationRef.current += 1;
 batchGenerationRef.current += 1;
 batchRequestInFlightRef.current = false;
 createKeyRef.current = "";
 retryKeyRef.current = { batchId: "", key: "" };
 batchReviewKeyRef.current = { batchId: "", key: "" };
 selectionKeyRef.current = "";
 settledMarkerRef.current = "";
 setPreview(null);
 setBatch(null);
 setAvailableAnchors([]);
 setSelectedAnchors([]);
 setStatusFilter("all");
 setTableAnchorFilter("all");
 setPreviewError("");
 setBatchError("");
 setNotice("");
 setPollSuspended(false);
 loadLatest();
 // Resume durable translation job after reload.
 try {
 const stored = JSON.parse(localStorage.getItem(`mw_translation_job_${projectId}`) || "null");
 if (stored?.job_id) {
 setDurableJobId(stored.job_id);
 pollDurableMwJob(projectId, stored.job_id, { intervalMs: 2500, maxLoops: 240 })
 .then(({ status, result, transportResultOk }) => {
 const ack = acknowledgeTranslationDomain({
 status,
 resultBody: transportResultOk ? result : null,
 locator: stored,
 expectedBatchId: stored.batch_id || "",
 expectedSnapshotId: stored.snapshot_id || "",
 });
 if (ack.outcome === "success") {
 const targetBatch = ack.batchId || stored.batch_id || "";
 if (targetBatch) loadBatch(targetBatch, { polling: false });
 } else if (ack.outcome === "reconcile_failed") {
 setBatchError("翻译作业已结束，但批次/快照核对失败。定位器已保留。");
 }
 if (ack.shouldClear) {
 try { localStorage.removeItem(`mw_translation_job_${projectId}`); } catch { /* ignore */ }
 setDurableJobId("");
 }
 });
 }
 } catch { /* ignore */ }
 return () => {
 previewGenerationRef.current += 1;
 batchGenerationRef.current += 1;
 batchRequestInFlightRef.current = false;
 };
 }, [loadLatest, scopeKey]);

 useEffect(() => {
 if (!snapshotId) return undefined;
 const timer = globalThis.setTimeout(() => loadPreview(selectedAnchors), selectedAnchors.length ? 80 : 0);
 return () => globalThis.clearTimeout(timer);
 }, [loadPreview, selectedAnchorKey, snapshotId]);

 useEffect(() => {
 createKeyRef.current = "";
 }, [selectedAnchorKey]);

 const batchStatus = normalizedStatus(batch?.status, "not_started");
 const batchId = batch?.batch_id || "";
 const batchRevision = batch?.updated_at || batchStatus;
 const active = ACTIVE_BATCH_STATUSES.has(batchStatus);

 useEffect(() => {
 if (!batchId || !active || pollSuspended) return undefined;
 const timer = globalThis.setInterval(() => loadBatch(batchId, { polling: true }), 2500);
 return () => globalThis.clearInterval(timer);
 }, [active, batchId, loadBatch, pollSuspended]);

 useEffect(() => {
 if (!batchId || !TERMINAL_BATCH_STATUSES.has(batchStatus)) return;
 const marker = `${batchId}:${batchRevision}`;
 if (settledMarkerRef.current === marker) return;
 settledMarkerRef.current = marker;
 onBatchSettled(batch);
 }, [batch, batchId, batchRevision, batchStatus, onBatchSettled]);

 const previewMatchesSelection = selectedScopeMatchesPreview(preview, selectedAnchors);
 const previewEligibleCount = previewMatchesSelection ? safeCount(preview?.eligible_count) : 0;
 const batchMatchesSelection = Boolean(batch)
 && batch.snapshot_id === snapshotId
 && batch.glossary_version === glossaryVersion
 && selectedScopeMatchesPreview(batch, selectedAnchors);
 const visibleBatch = batchMatchesSelection ? batch : null;
 const visibleBatchStatus = normalizedStatus(visibleBatch?.status, "not_started");
 const rows = useMemo(
 () => (visibleBatch?.items || []).map(normalizeItem),
 [visibleBatch?.items],
 );
 const documentProgress = useMemo(
 () => deriveDocumentTranslationProgress(visibleBatch?.items || []),
 [visibleBatch?.items],
 );
 const documentProgressSummary = useMemo(
 () => formatDocumentTranslationProgressSummary(documentProgress),
 [documentProgress],
 );
 const counts = visibleBatch?.counts || {};
 const candidateReadyCount = visibleBatch
 ? safeCount(counts.candidate_ready_count, rows.filter((row) => row.generationStatus === "candidate_ready").length)
 : previewMatchesSelection ? safeCount(preview?.existing_candidate_count) : 0;
 const fidelityBlockedCount = visibleBatch
 ? safeCount(counts.fidelity_blocked_count, rows.filter((row) => row.generationStatus === "fidelity_blocked").length)
 : previewMatchesSelection ? safeCount(preview?.fidelity_blocked_count) : 0;
 const failedCount = safeCount(counts.failed_count, rows.filter((row) => FAILED_ITEM_STATUSES.has(row.generationStatus)).length);
 const pendingReviewCount = safeCount(counts.pending_author_confirmation_count, rows.filter((row) => row.generationStatus === "candidate_ready" && ["not_confirmed", "returned"].includes(row.authorConfirmationStatus)).length);
 const approvedCount = safeCount(counts.author_confirmed_count, rows.filter((row) => row.authorConfirmationStatus === "confirmed").length);
 const admittedCount = safeCount(counts.admitted_count, rows.filter((row) => row.admissionStatus === "admitted").length);
 const batchReusedCount = safeCount(counts.reused_count, rows.filter((row) => row.origin === "existing").length);
 const expectedNewCount = previewMatchesSelection ? safeCount(preview?.eligible_new_count) : 0;
 const reuseCount = previewMatchesSelection ? safeCount(preview?.existing_candidate_count) : 0;

 const exclusionGroups = useMemo(() => {
 const reasonCounts = new Map();
 for (const countsByReason of [
 preview?.document_exclusion_reason_counts || {},
 preview?.span_exclusion_reason_counts || {},
 ]) {
 Object.entries(countsByReason).forEach(([reason, count]) => {
 reasonCounts.set(reason, safeCount(reasonCounts.get(reason)) + safeCount(count));
 });
 }
 const examples = new Map();
 (preview?.exclusions || []).forEach((item) => {
 const reason = item.reason_code || "other";
 const current = examples.get(reason) || [];
 if ((item.nct_id || item.artifact_id) && current.length < EXCLUSION_EXAMPLE_LIMIT) current.push(item);
 examples.set(reason, current);
 });
 return [...reasonCounts.entries()]
 .map(([reason, count]) => ({
 reason,
 label: exclusionReasonLabels[reason] || "其他不符合批量条件的原因",
 count,
 examples: examples.get(reason) || [],
 }))
 .sort((left, right) => right.count - left.count || left.label.localeCompare(right.label, "zh-CN"));
 }, [preview]);
 const previewExcludedCount = exclusionGroups.reduce((sum, group) => sum + group.count, 0);
 const excludedCount = visibleBatch
 ? safeCount(counts.excluded_count, previewExcludedCount)
 : previewExcludedCount;

 const visibleRows = useMemo(() => {
 const filtered = rows.filter((row) => {
 if (tableAnchorFilter !== "all" && row.anchor !== tableAnchorFilter) return false;
 if (statusFilter === "pending" && row.generationStatus !== "pending") return false;
 if (statusFilter === "running" && row.generationStatus !== "running") return false;
 if (statusFilter === "excluded" && row.generationStatus !== "excluded") return false;
 if (statusFilter === "candidate_ready" && row.generationStatus !== "candidate_ready") return false;
 if (statusFilter === "fidelity_blocked" && row.generationStatus !== "fidelity_blocked") return false;
 if (statusFilter === "failed_retryable" && row.generationStatus !== "failed_retryable") return false;
 if (statusFilter === "failed_terminal" && row.generationStatus !== "failed_terminal") return false;
 if (statusFilter === "pending_author_confirmation" && !(row.generationStatus === "candidate_ready" && ["not_confirmed", "returned"].includes(row.authorConfirmationStatus))) return false;
 if (statusFilter === "author_confirmed" && row.authorConfirmationStatus !== "confirmed") return false;
 if (statusFilter === "admitted" && row.admissionStatus !== "admitted") return false;
 return true;
 });
 const direction = sort.direction === "asc" ? 1 : -1;
 return [...filtered].sort((left, right) => sortValue(left, sort.key).localeCompare(sortValue(right, sort.key), "zh-CN") * direction);
 }, [rows, sort, statusFilter, tableAnchorFilter]);

 const batchReviewEligibleRows = useMemo(
 () => visibleRows.filter(batchReviewEligibleRow),
 [visibleRows],
 );

 const toggleAnchor = (anchor, checked) => {
 if (!SUPPORTED_TRANSLATION_ANCHORS.has(anchor)) return;
 createKeyRef.current = "";
 setNotice("");
 setSelectedAnchors((current) => {
 if (!checked && current.length === 1 && current[0] === anchor) return current;
 return checked
 ? [...new Set([...current, anchor])]
 : current.filter((item) => item !== anchor);
 });
 };

 const updateSort = (key) => {
 setSort((current) => ({
 key,
 direction: current.key === key && current.direction === "asc" ? "desc" : "asc",
 }));
 };

 const startBatch = async () => {
 if (!selectedAnchors.length || !previewMatchesSelection || previewEligibleCount === 0) return;
 setAction("start");
 setBatchError("");
 setNotice("");
 if (!createKeyRef.current) createKeyRef.current = requestKey("reference-translation-batch");
 try {
 const response = await fetch(`/api/projects/${projectId}/medical-writing/references/translation-batches`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 snapshot_id: snapshotId,
 glossary_version: glossaryVersion,
 anchor_filter: selectedAnchors,
 actor: "medical_manager",
 idempotency_key: createKeyRef.current,
 }),
 });
 const payload = await readJson(response);
 setBatch(payload);
 if (payload.durable_job_id) {
 setDurableJobId(payload.durable_job_id);
 const locator = buildLocator({
 projectId,
 jobId: payload.durable_job_id,
 operation: "reference_translation",
 jobType: "reference_translation",
 batchId: payload.batch_id || "",
 snapshotId,
 });
 try { localStorage.setItem(`mw_translation_job_${projectId}`, JSON.stringify(locator)); } catch { /* ignore */ }
 // Poll the durable job in background for cancel/retry lifecycle.
 pollDurableMwJob(projectId, payload.durable_job_id, { intervalMs: 2500, maxLoops: 240 })
 .then(({ status, result, transportResultOk }) => {
 const ack = acknowledgeTranslationDomain({
 status,
 resultBody: transportResultOk ? result : null,
 locator,
 expectedBatchId: payload.batch_id || "",
 expectedSnapshotId: snapshotId,
 });
 if (ack.outcome === "success") {
 const targetBatch = ack.batchId || payload.batch_id || batchId;
 if (targetBatch) loadBatch(targetBatch, { polling: false });
 }
 if (ack.shouldClear) {
 try { localStorage.removeItem(`mw_translation_job_${projectId}`); } catch { /* ignore */ }
 setDurableJobId("");
 }
 });
 }
 setPollSuspended(false);
 setNotice("候选生成批次已受理；页面刷新后仍可恢复当前批次状态。");
 createKeyRef.current = "";
 } catch (error) {
 setBatchError(`候选生成未启动：${error.message}`);
 } finally {
 setAction("");
 }
 };

 const retryFailed = async () => {
 if (!batchId) return;
 setAction("retry");
 setBatchError("");
 setNotice("");
 if (retryKeyRef.current.batchId !== batchId || !retryKeyRef.current.key) {
 retryKeyRef.current = { batchId, key: requestKey("reference-translation-retry") };
 }
 try {
 const response = await fetch(`/api/projects/${projectId}/medical-writing/references/translation-batches/${encodeURIComponent(batchId)}/retry`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({ actor: "medical_manager", idempotency_key: retryKeyRef.current.key }),
 });
 const payload = await readJson(response);
 setBatch(payload);
 const nextDurableId = resolveRetryJobId(durableJobId, payload)
 || payload.durable_job_id
 || durableJobId;
 if (nextDurableId) {
 setDurableJobId(nextDurableId);
 let previousLocator = null;
 try {
 previousLocator = JSON.parse(localStorage.getItem(`mw_translation_job_${projectId}`) || "null");
 } catch { /* ignore */ }
 const locator = mergeRetryLocator(
 previousLocator || {
 operation: "reference_translation",
 job_type: "reference_translation",
 batch_id: payload.batch_id || batchId,
 snapshot_id: snapshotId,
 },
 nextDurableId,
 projectId,
 );
 // Preserve batch/snapshot operation context across replacement job ids.
 locator.batch_id = payload.batch_id || batchId || locator.batch_id || "";
 locator.snapshot_id = snapshotId || locator.snapshot_id || "";
 try { localStorage.setItem(`mw_translation_job_${projectId}`, JSON.stringify(locator)); } catch { /* ignore */ }
 pollDurableMwJob(projectId, nextDurableId, { intervalMs: 2500, maxLoops: 240 })
 .then(({ status, result, transportResultOk }) => {
 const ack = acknowledgeTranslationDomain({
 status,
 resultBody: transportResultOk ? result : null,
 locator,
 expectedBatchId: locator.batch_id || batchId,
 expectedSnapshotId: snapshotId,
 });
 if (ack.outcome === "success") {
 const targetBatch = ack.batchId || payload.batch_id || batchId;
 if (targetBatch) loadBatch(targetBatch, { polling: false });
 }
 if (ack.shouldClear) {
 try { localStorage.removeItem(`mw_translation_job_${projectId}`); } catch { /* ignore */ }
 setDurableJobId("");
 }
 });
 }
 setPollSuspended(false);
 setNotice("已仅重新提交可重试失败项；成功项、忠实度阻断项和终止失败项不会重复生成。");
 retryKeyRef.current = { batchId: "", key: "" };
 } catch (error) {
 setBatchError(`失败项重试未启动：${error.message}`);
 } finally {
 setAction("");
 }
 };

 const batchConfirmEligible = async () => {
 if (!batchId || !batchReviewEligibleRows.length) return;
 setAction("batch-confirm");
 setBatchError("");
 setNotice("");
 if (batchReviewKeyRef.current.batchId !== batchId || !batchReviewKeyRef.current.key) {
 batchReviewKeyRef.current = { batchId, key: requestKey("reference-translation-batch-review") };
 }
 try {
 const response = await fetch(`/api/projects/${projectId}/medical-writing/references/translation-batches/${encodeURIComponent(batchId)}/medical-review`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 targets: batchReviewEligibleRows.map((row) => ({
 translation_id: row.translationId,
 translation_revision: row.translationRevision,
 })),
 actor: "medical_manager",
 idempotency_key: batchReviewKeyRef.current.key,
 }),
 });
 const payload = await readJson(response);
 const approvedCount = safeCount(payload.approved_count);
 const skippedCount = safeCount(payload.skipped_count);
 const staleCount = safeCount(payload.stale_count);
 const failedCount = safeCount(payload.failed_count);
 setNotice(`一键确认完成：已确认 ${approvedCount} 项${skippedCount ? `，跳过 ${skippedCount} 项（忠实度阻断、已退回、已拒绝或已确认项仍需逐项核对）` : ""}${staleCount ? `，${staleCount} 项版本已变化，请刷新后逐项核对` : ""}${failedCount ? `，${failedCount} 项确认失败` : ""}。`);
 batchReviewKeyRef.current = { batchId: "", key: "" };
 await loadBatch(batchId);
 // Medical-review creates/updates approved evidence briefs in the parent
 // workspace, but does not necessarily change the batch revision marker.
 // Refresh the parent explicitly so the adjacent "已准入证据" tab cannot
 // remain at a stale zero-count after a successful one-click confirmation.
 await onBatchSettled();
 } catch (error) {
 setBatchError(`一键确认未完成：${error.message}`);
 } finally {
 setAction("");
 }
 };

 const cancelTranslationJob = async () => {
 if (!durableJobId) return;
 try {
 await fetch(`/api/projects/${projectId}/medical-writing/jobs/${durableJobId}/cancel`, { method: "POST" });
 // Do NOT clear locator or jobId here. The background poll will detect
 // the cancelled status and reconcile before cleanup.
 } catch { /* best-effort */ }
 };

 const refreshAll = async () => {
 setAction("refresh");
 setNotice("");
 setPollSuspended(false);
 await Promise.all([
 loadPreview(selectedAnchors),
 batchId ? loadBatch(batchId) : loadLatest(),
 ]);
 setAction("");
 };

 return (
 <section className="writing-reference-translation-batch" data-testid="reference-translation-batch" data-batch-status={batchStatus} data-batch-id={batchId || undefined}>
 <header className="writing-reference-translation-batch-head">
 <div>
 <span><Languages size={14} />监管中文候选批次</span>
 <strong>按 M11 结构范围生成</strong>
 <small>机器忠实度检查只验证候选与原文的一致性；通过后由医学作者一键确认合格候选或逐片段核对，确认即直接准入。</small>
 </div>
 <code title="当前监管术语契约">{glossaryVersion}</code>
 </header>

 <div className="writing-reference-translation-summary" role="status" aria-live="polite" data-testid="translation-batch-counts">
 <span><small>当前范围批次</small><b className={visibleBatchStatus}>{batchStatusLabels[visibleBatchStatus] || "状态待确认"}</b></span>
 <span><small>符合条件</small><b>{previewEligibleCount}</b></span>
 <span><small>已生成候选</small><b>{candidateReadyCount}</b></span>
 <span className={fidelityBlockedCount ? "danger" : ""}><small>忠实度阻断</small><b>{fidelityBlockedCount}</b></span>
 <span className={failedCount ? "danger" : ""}><small>失败</small><b>{failedCount}</b></span>
 <span className={pendingReviewCount ? "warning" : ""}><small>待作者确认</small><b>{pendingReviewCount}</b></span>
 <span><small>作者已确认</small><b>{approvedCount}</b></span>
 <span><small>已准入</small><b>{admittedCount}</b></span>
 </div>

 {rows.length > 0 && (
 <>
 <WritingReferenceProgressJourney
 items={rows.map((row) => ({
 status: ["excluded", "candidate_ready", "fidelity_blocked", "failed_retryable", "failed_terminal"].includes(row.generationStatus)
 ? row.generationStatus
 : row.pipelineStage || row.generationStatus,
 pipeline_stage: row.pipelineStage,
 pipeline_stage_detail: row.pipelineStageDetail,
 artifact_id: row.artifactId,
 span_id: row.spanId,
 document_total: row.documentTotal,
 document_index: row.documentIndex,
 document_label: row.documentLabel,
 chapter_id: row.chapterId,
 chapter_title: row.chapterTitle,
 chapter_total: row.chapterTotal,
 chapter_index: row.chapterIndex,
 chunk_count: row.chunkCount,
 chunk_completed: row.chunkCompleted,
 chunk_running: row.chunkRunning,
 chunk_failed: row.chunkFailed,
 chunk_reused: row.chunkReused,
 }))}
 compact={true}
 />
 {documentProgressSummary ? (
 <p
 className="writing-reference-translation-document-progress"
 role="status"
 aria-live="polite"
 data-testid="translation-document-chapter-chunk-progress"
 >
 {documentProgressSummary}
 </p>
 ) : null}
 </>
 )}

 <div className="writing-reference-translation-scope">
 <fieldset>
 <legend>M11 结构范围（已选 {selectedAnchors.length}/{availableAnchors.filter((anchor) => SUPPORTED_TRANSLATION_ANCHORS.has(anchor.value)).length}）</legend>
 <div className="writing-reference-translation-anchor-options" data-testid="translation-anchor-filter">
 {availableAnchors.map((anchor) => (
 <label key={anchor.value}>
 <input type="checkbox" checked={selectedAnchors.includes(anchor.value)} disabled={!SUPPORTED_TRANSLATION_ANCHORS.has(anchor.value)} onChange={(event) => toggleAnchor(anchor.value, event.target.checked)} />
 <span>{anchor.value}（{anchor.count}）{SUPPORTED_TRANSLATION_ANCHORS.has(anchor.value) ? "" : " · 当前批量翻译合同暂不支持"}</span>
 </label>
 ))}
 {!availableAnchors.length && <span>当前预览没有返回可选择的已映射 M11 结构。</span>}
 </div>
 </fieldset>
 <div className="writing-reference-translation-preview" data-testid="translation-batch-preview-counts">
 <span><b>{expectedNewCount}</b>预计新生成</span>
 <span title={visibleBatch ? `当前批次实际复用 ${batchReusedCount}` : undefined}><b>{reuseCount}</b>复用当前契约候选</span>
 <span><b>{excludedCount}</b>排除</span>
 </div>
 <div className="writing-reference-translation-actions">
 <button className="primary-button" type="button" data-action="start-translation-batch" onClick={startBatch} disabled={!snapshotId || !previewMatchesSelection || previewEligibleCount === 0 || !selectedAnchors.length || active || Boolean(action) || previewLoading || batchLoading} title={!selectedAnchors.length ? "至少选择一个有资格的 M11 结构" : "按当前结构范围生成监管中文候选"}>
 <Play size={14} />{action === "start" ? "提交中" : "生成候选"}
 </button>
 <button type="button" data-action="refresh-translation-batch" onClick={refreshAll} disabled={Boolean(action) || previewLoading || batchLoading}>
 <RefreshCw size={14} className={previewLoading || batchLoading ? "spin" : ""} />刷新
 </button>
 <button type="button" data-action="retry-translation-failed" onClick={retryFailed} disabled={!batchMatchesSelection || !batchId || !failedCount || active || Boolean(action) || batchLoading}>
 <RotateCcw size={14} />{action === "retry" ? "重试中" : "仅重试失败项"}
 </button>
 <button type="button" data-action="batch-confirm-eligible-translations" onClick={batchConfirmEligible} disabled={!batchMatchesSelection || !batchId || !batchReviewEligibleRows.length || active || Boolean(action) || batchLoading} title="一键确认当前筛选中机器忠实度通过且尚未确认的候选；忠实度阻断、已退回、已拒绝或版本已变化项仍需逐项核对">
 <CheckCheck size={14} />{action === "batch-confirm" ? "确认中" : `一键确认合格候选（${batchReviewEligibleRows.length}）`}
 </button>
 {durableJobId && active && (
 <button type="button" data-action="cancel-translation-job" onClick={cancelTranslationJob}>取消生成</button>
 )}
 </div>
 </div>

 {batch && !batchMatchesSelection && previewMatchesSelection && (
 <p className="writing-reference-translation-message" role="status">
 当前选择与最近批次的冻结范围不同；本页先显示本次范围预览，生成后建立新的可恢复批次。
 </p>
 )}

 {previewError && <p className="writing-reference-translation-message danger" role="alert">{previewError}</p>}
 {batchError && <p className="writing-reference-translation-message danger" role="alert">{batchError}</p>}
 {notice && <p className="writing-reference-translation-message" role="status">{notice}</p>}

 {previewMatchesSelection && previewEligibleCount === 0 ? (
 <div className="writing-reference-translation-empty" data-testid="translation-batch-zero-eligible">
 <strong>当前范围没有可批量生成的合格片段</strong>
 <span>零 eligible 是合法结果，通常表示当前研究没有可用公开Protocol，或文件内容核验与结构医学审核双门禁尚未完成。可到“文档与解析”手动导入已取得的Protocol，或先完成阶段一处理。</span>
 </div>
 ) : (
 <>
 <div className="writing-reference-translation-table-tools">
 <label>状态筛选
 <select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)}>
 <option value="all">全部状态</option>
 <option value="pending">待生成</option>
 <option value="running">生成中</option>
 <option value="excluded">规划后排除</option>
 <option value="candidate_ready">候选已就绪</option>
 <option value="fidelity_blocked">忠实度阻断</option>
 <option value="failed_retryable">失败，可重试</option>
 <option value="failed_terminal">终止失败</option>
 <option value="pending_author_confirmation">待作者确认</option>
 <option value="author_confirmed">作者已确认</option>
 <option value="admitted">已准入</option>
 </select>
 </label>
 <label>Anchor 筛选
 <select value={tableAnchorFilter} onChange={(event) => setTableAnchorFilter(event.target.value)}>
 <option value="all">全部 M11 结构</option>
 {availableAnchors.map((anchor) => <option value={anchor.value} key={anchor.value}>{anchor.value}</option>)}
 </select>
 </label>
 <span>{visibleRows.length}/{rows.length} 条</span>
 </div>

 <div className="writing-reference-translation-table-wrap" data-testid="translation-batch-table">
 <table className="writing-reference-translation-table">
 <thead><tr>
 <th><SortHeader label="研究 / 文件" column="study" sort={sort} onSort={updateSort} /></th>
 <th><SortHeader label="M11 结构与来源定位" column="anchor" sort={sort} onSort={updateSort} /></th>
 <th><SortHeader label="生成状态" column="generation" sort={sort} onSort={updateSort} /></th>
 <th><SortHeader label="忠实度" column="fidelity" sort={sort} onSort={updateSort} /></th>
 <th><SortHeader label="作者确认" column="review" sort={sort} onSort={updateSort} /></th>
 <th><SortHeader label="准入" column="admission" sort={sort} onSort={updateSort} /></th>
 <th><SortHeader label="下一步" column="next" sort={sort} onSort={updateSort} /></th>
 </tr></thead>
 <tbody>
 {visibleRows.map((row) => (
 <tr key={row.rowKey} data-anchor={row.anchor} data-generation-status={row.generationStatus} data-review-status={row.authorConfirmationStatus} data-admission-status={row.admissionStatus}>
 <td><strong>{row.nctId || "研究待确认"}</strong><small>{row.filename || "文件名待后端补充"}{row.documentType ? ` · ${row.documentType}` : ""}</small></td>
 <td><strong>{row.anchor || "结构待确认"}</strong><small>{row.sourceLocator}</small></td>
 <td>
 {statusTag(row.generationStatus, generationLabels)}
 {row.generationStatus === "running" && row.pipelineStageDetail && (
 <small>{row.pipelineStageDetail}</small>
 )}
 </td>
 <td>{statusTag(row.fidelityStatus, fidelityLabels)}{row.fidelityFailureCodes.length > 0 && <small>{row.fidelityFailureCodes.join("、")}</small>}</td>
 <td>{statusTag(row.authorConfirmationStatus, reviewLabels, "待作者确认")}</td>
 <td>{statusTag(row.admissionStatus, admissionLabels, "未准入")}</td>
 <td>
 <span>{nextStep(row)}</span>
 <button type="button" data-action="open-translation-span" onClick={() => onOpenSpan({ artifact_id: row.artifactId, span_id: row.spanId, ich_m11_anchor: row.anchor })} disabled={row.generationStatus === "excluded" || !row.artifactId || !row.spanId} title={row.generationStatus === "excluded" ? "该章节不在本次所选范围，无需核对译文" : "在下方单片段区对照原文并确认译文"}><Eye size={13} />核对译文</button>
 </td>
 </tr>
 ))}
 </tbody>
 </table>
 {!visibleRows.length && <div className="writing-reference-translation-table-empty">{batch ? "当前筛选条件下没有片段。" : "生成批次后将在此显示具体片段。"}</div>}
 </div>
 </>
 )}

 <details className="writing-reference-translation-exclusions">
 <summary>排除项（{excludedCount}）</summary>
 {exclusionGroups.map((group) => (
 <div key={group.reason}>
 <strong>{group.label}<span>{group.count} 项</span></strong>
 {group.examples.map((item, index) => (
 <p key={`${group.reason}:${item.artifact_id || "document"}:${index}`}>
 <b>{item.nct_id || "研究待确认"}</b>
 <span>{item.artifact_id || "未登记文件"}{item.ich_m11_anchor ? ` · ${item.ich_m11_anchor}` : ""}</span>
 </p>
 ))}
 {group.count > group.examples.length && <p><b>其余项目</b><span>另有 {group.count - group.examples.length} 项未展开</span></p>}
 </div>
 ))}
 {!exclusionGroups.length && <p>当前预览没有排除项。</p>}
 </details>
 </section>
 );
}

import { useEffect, useMemo, useState } from "react";
import { CheckCircle2, ExternalLink, Filter, RefreshCw, Search, ShieldAlert } from "lucide-react";


const reviewLabels = {
 not_reviewed: ["待共享适用性确认", "warning"],
 approved: ["已确认可复用", "success"],
 returned: ["已退回", "warning"],
 rejected: ["已拒绝", "danger"],
};

const admissionLabels = {
 not_admitted: ["未准入", "neutral"],
 admitted: ["已纳入共享语料", "success"],
 invalidated: ["准入已失效", "danger"],
};

const modalityLabels = {
 monoclonal_antibody: "抗体类",
 bispecific_fusion_protein: "双特异性融合蛋白",
 engineered_biologic: "工程化生物制品",
 small_molecule: "小分子",
};

function requestKey(prefix) {
 const suffix = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random()}`;
 return `${prefix}-${suffix}`;
}

async function readJson(response) {
 const payload = await response.json().catch(() => ({}));
 if (response.ok) return payload;
 const detail = typeof payload.detail === "string" ? payload.detail : `HTTP ${response.status}`;
 throw new Error(detail);
}

function StatusTag({ value, labels }) {
 const [label, tone] = labels[value] || [value || "待确认", "neutral"];
 return <span className={`tag ${tone}`}>{label}</span>;
}

export function SharedPhase1CorpusPanel() {
 const [catalog, setCatalog] = useState(null);
 const [selectedId, setSelectedId] = useState("");
 const [query, setQuery] = useState("");
 const [status, setStatus] = useState("all");
 const [modality, setModality] = useState("all");
 const [comment, setComment] = useState("");
 const [busy, setBusy] = useState("");
 const [message, setMessage] = useState("");

 const load = async ({ preserveMessage = false } = {}) => {
 if (!preserveMessage) setMessage("");
 const params = new URLSearchParams({ query, status, modality });
 try {
 const payload = await fetch(`/api/medical-writing/shared-corpus/phase1?${params}`).then(readJson);
 setCatalog(payload);
 setSelectedId((current) => payload.items?.some((item) => item.segment_id === current)
 ? current
 : payload.items?.[0]?.segment_id || "");
 } catch (error) {
 setMessage(`共享语料读取失败：${error.message}`);
 }
 };

 useEffect(() => {
 const timer = globalThis.setTimeout(() => load(), 180);
 return () => globalThis.clearTimeout(timer);
 }, [query, status, modality]);

 const selected = useMemo(
 () => catalog?.items?.find((item) => item.segment_id === selectedId) || catalog?.items?.[0],
 [catalog, selectedId],
 );

 useEffect(() => setComment(""), [selected?.segment_id, selected?.medical_review_revision]);

 const run = async (key, action, successMessage) => {
 setBusy(key);
 setMessage("");
 try {
 const updated = await action();
 setSelectedId(updated.segment_id);
 await load({ preserveMessage: true });
 setMessage(successMessage);
 setComment("");
 } catch (error) {
 setMessage(`操作未完成：${error.message}`);
 } finally {
 setBusy("");
 }
 };

 const review = (decision) => run(
 `review-${decision}`,
 () => fetch(`/api/medical-writing/shared-corpus/phase1/${selected.segment_id}/medical-review`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 decision,
 comment: comment.trim(),
 actor: "medical_manager",
 expected_revision: selected.medical_review_revision,
 idempotency_key: requestKey("shared-phase1-review"),
 }),
 }).then(readJson),
 decision === "approved"
 ? "已确认该译文适合跨项目复用；仍需显式选择纳入共享语料。"
 : decision === "returned"
 ? "复用核对意见已记录；既有准入已立即失效。"
 : "该候选已拒绝，不会进入共享语料检索。",
 );

 const admit = () => run(
 "admit",
 () => fetch(`/api/medical-writing/shared-corpus/phase1/${selected.segment_id}/admissions`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 medical_review_id: selected.medical_review_id,
 expected_review_revision: selected.medical_review_revision,
 actor: "medical_manager",
 idempotency_key: requestKey("shared-phase1-admission"),
 }),
 }).then(readJson),
 "当前作者确认版本已纳入I期共享语料；仅在I期且写作对象匹配时提供参考。",
 );

 return (
 <section className="shared-phase1-corpus" aria-label="I期共享语料适用性核对">
 <header className="shared-phase1-corpus-header">
 <div>
 <span>I期竞品方案语料</span>
 <strong>原文与监管中文共享适用性核对</strong>
 <small>只将作者已确认适合复用且显式准入的片段用于I期方案结构和措辞参考；药物、剂量、阈值、访视和终点仍以当前项目事实为准。</small>
 </div>
 <button type="button" className="icon-button" onClick={() => load()} title="刷新共享语料状态"><RefreshCw size={15} /></button>
 </header>
 <div className="shared-phase1-corpus-metrics">
 <span><b>{catalog?.item_count || 0}</b> 候选</span>
 <span><b>{catalog?.pending_review_count || 0}</b> 待适用性确认</span>
 <span><b>{catalog?.approved_count || 0}</b> 已确认可复用</span>
 <span><b>{catalog?.admitted_count || 0}</b> 已准入</span>
 </div>
 <div className="shared-phase1-corpus-filters">
 <label><Search size={14} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="检索NCT号、申办方、药物或正文" /></label>
 <label><Filter size={14} /><select value={status} onChange={(event) => setStatus(event.target.value)}><option value="all">全部状态</option><option value="not_reviewed">待共享适用性确认</option><option value="approved">已确认可复用</option><option value="returned">已退回</option><option value="rejected">已拒绝</option><option value="admitted">已准入</option><option value="invalidated">准入已失效</option></select></label>
 <select value={modality} onChange={(event) => setModality(event.target.value)} aria-label="按药物类型筛选"><option value="all">全部药物类型</option>{Object.entries(modalityLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select>
 </div>
 {message && <p className={`shared-phase1-corpus-message ${message.includes("失败") || message.includes("未完成") ? "danger" : ""}`}>{message}</p>}
 <div className="shared-phase1-corpus-workspace">
 <nav aria-label="I期共享语料候选">
 {(catalog?.items || []).map((item) => (
 <button type="button" key={item.segment_id} className={item.segment_id === selected?.segment_id ? "active" : ""} onClick={() => setSelectedId(item.segment_id)}>
 <span><b>{item.nct_id}</b><StatusTag value={item.medical_review_status} labels={reviewLabels} /></span>
 <strong>{item.compound}</strong>
 <small>{item.sponsor} · {modalityLabels[item.modality] || item.modality}</small>
 <small>{item.conditions.join("、")}</small>
 </button>
 ))}
 {!catalog?.items?.length && <p>当前筛选条件下没有候选。</p>}
 </nav>
 {selected ? <article className="shared-phase1-corpus-detail">
 <header>
 <div><span>{selected.nct_id} · {selected.phases.join("/")}</span><strong>{selected.compound}</strong><small>{selected.corpus_function} · {selected.ich_m11_anchor}</small></div>
 <div><StatusTag value={selected.medical_review_status} labels={reviewLabels} /><StatusTag value={selected.admission_status} labels={admissionLabels} /></div>
 </header>
 <p className="shared-phase1-applicability"><ShieldAlert size={15} /><span><b>适用边界</b>{selected.applicability}</span></p>
 <div className="shared-phase1-text-compare">
 <section><header><strong>Protocol原文</strong><a href={selected.source_url} target="_blank" rel="noreferrer" title="打开ClinicalTrials.gov官方文件"><ExternalLink size={14} />官方文件</a></header><p lang="en">{selected.source_text}</p></section>
 <section><header><strong>监管中文候选</strong><span>{selected.model_name} · {selected.prompt_version}</span></header><p>{selected.translated_text}</p></section>
 </div>
 <details className="shared-phase1-lineage"><summary>来源与版本</summary><dl><div><dt>原文定位</dt><dd>{selected.source_locator}</dd></div><div><dt>方案版本</dt><dd>{selected.protocol_version || selected.document_date || "见官方文件"}</dd></div><div><dt>词典</dt><dd>{selected.glossary_version}</dd></div><div><dt>AI运行</dt><dd>{selected.ai_run_id}</dd></div></dl></details>
 {selected.medical_review_comment && <p className="shared-phase1-review-comment"><b>当前复用核对意见</b>{selected.medical_review_comment}</p>}
 <div className="shared-phase1-review-actions">
 {selected.medical_review_status === "approved" && selected.admission_status !== "admitted" ? (
 <button type="button" className="primary-button" onClick={admit} disabled={Boolean(busy)}><CheckCircle2 size={14} />{busy === "admit" ? "准入中" : "纳入I期共享语料"}</button>
 ) : <>
 <label><span>{selected.admission_status === "admitted" ? "撤回理由" : "共享适用性核对意见"}</span><textarea rows={3} value={comment} onChange={(event) => setComment(event.target.value)} placeholder={selected.admission_status === "admitted" ? "说明新发现的医学、翻译或适用性问题；确认后准入立即失效。" : "对照原文确认医学含义、数字、单位、时序、否定关系和跨项目适用边界。"} /></label>
 <div>
 {selected.admission_status === "admitted" ? <button type="button" onClick={() => review("returned")} disabled={comment.trim().length < 2 || Boolean(busy)}>撤回并退回修订</button> : <>
 <button type="button" className="primary-button" onClick={() => review("approved")} disabled={comment.trim().length < 2 || Boolean(busy)}>确认可复用</button>
 <button type="button" onClick={() => review("returned")} disabled={comment.trim().length < 2 || Boolean(busy)}>退回修改</button>
 <button type="button" onClick={() => review("rejected")} disabled={comment.trim().length < 2 || Boolean(busy)}>拒绝</button>
 </>}
 </div>
 </>}
 </div>
 </article> : <div className="shared-phase1-corpus-empty">选择候选后对照原文和监管中文。</div>}
 </div>
 </section>
 );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
 AlertTriangle,
 CheckCircle2,
 ChevronLeft,
 ChevronRight,
 Download,
 ExternalLink,
 FileSearch,
 FileText,
 RefreshCw,
 Search,
 Upload,
} from "lucide-react";
import { ReferencePreparationBatchPanel } from "./ReferencePreparationBatchPanel";
import { MixedOcrReviewPanel } from "./MixedOcrReviewPanel";
import { ReferenceTranslationBatchPanel } from "./ReferenceTranslationBatchPanel";
import { SharedPhase1CorpusPanel } from "./SharedPhase1CorpusPanel";
import {
 pollDurableMwJob,
 buildLocator,
 shouldClearLocator,
 shouldBlockStart,
 acknowledgeTriageDomain,
} from "../medical-writing/useDurableMwJob";
import {
 deriveTriagePresentation,
 mergeTriageSelections,
} from "./triagePresentationState.mjs";
import { alignedArtifactId } from "./referenceIdentity.mjs";

const viewDefinitions = [
 { id: "candidates", label: "候选研究" },
 { id: "documents", label: "文档与解析" },
 { id: "translations", label: "结构与译文确认" },
 { id: "approved", label: "已准入证据" },
 { id: "shared_phase1", label: "I期共享语料" },
];

function isPhase1(value) {
 const normalized = String(value || "").trim().toUpperCase().replace(/\s+/g, "").replaceAll("Ⅰ", "I");
 return ["1", "I", "1期", "I期", "PHASE1", "PHASEI", "1A", "1B", "IA", "IB", "I/II期", "I期/II期"].includes(normalized)
 || normalized.startsWith("PHASE1/")
 || normalized.startsWith("I期/")
 || normalized.startsWith("I/II");
}

const relevanceLabels = {
 pending_medical_relevance: ["待AI分类", "warning"],
 direct_competitor: ["直接竞品", "info"],
 indirect_reference: ["间接参照", "info"],
 excluded: ["已排除", "neutral"],
};

const triageClassificationLabels = {
 direct_competitor: "直接竞品",
 indirect_reference: "间接参照",
 excluded: "排除",
};

const triageDimensionLabels = {
 indication: "适应症",
 phase: "研究分期",
 population: "研究人群",
 intervention: "干预措施",
 comparator: "对照",
 endpoint: "研究终点",
 mechanism: "作用机制",
 route: "给药途径",
 design: "研究设计",
 document: "公开文档",
};

const translationStatusLabels = {
 pending_author_confirmation: ["待作者确认", "warning"],
 author_confirmed_admitted: ["作者已确认并准入", "success"],
 pending_medical_approval: ["历史状态：待迁移", "warning"],
 fidelity_blocked: ["忠实度校验未通过", "danger"],
 invalidated_source: ["来源已失效", "danger"],
 invalidated_extraction: ["结构解析已更新", "danger"],
 invalidated_review: ["作者确认已撤回", "danger"],
};

const reviewLabels = {
 approved: ["作者已确认", "success"],
 returned: ["已退回", "warning"],
 rejected: ["已拒绝", "danger"],
};

const historicalReviewLabels = {
 approved: ["历史审核已批准", "neutral"],
 returned: ["历史退回记录", "neutral"],
 rejected: ["历史拒绝记录", "neutral"],
};

const validationLabels = {
 confirmed: ["内容匹配", "success"],
 needs_review: ["需确认", "warning"],
 mismatch: ["发现不一致", "danger"],
 user_overridden: ["已确认沿用", "info"],
};

const extractionReviewLabels = {
 approved: ["结构已确认", "success"],
 returned: ["结构待修正", "warning"],
};

function ReferenceTag({ value, dictionary, fallback = "待处理" }) {
 const [label, tone] = dictionary[value] || [fallback, "neutral"];
 return <span className={`tag ${tone}`}>{label}</span>;
}

function requestKey(prefix) {
 const suffix = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random()}`;
 return `${prefix}-${suffix}`;
}

async function readJson(response) {
 const payload = await response.json().catch(() => ({}));
 if (response.ok) return payload;
 const error = new Error(typeof payload.detail === "string" ? payload.detail : `HTTP ${response.status}`);
 error.status = response.status;
 throw error;
}

function currentDecision(workspace, nctId) {
 return (workspace?.decisions || [])
 .filter((item) => item.nct_id === nctId)
 .sort((left, right) => right.revision - left.revision)[0];
}

function currentReview(workspace, translation) {
 return (workspace?.medical_reviews || [])
 .filter((item) => item.translation_id === translation?.translation_id && item.translation_revision === translation?.revision)
 .sort((left, right) => right.revision - left.revision)[0];
}

function triageCandidateResults(runResponse) {
 return (runResponse?.run?.chunks || [])
 .filter((chunk) => chunk.status === "succeeded")
 .flatMap((chunk) => chunk.results || []);
}

function spanOptionLabel(span) {
 const source = String(span?.source_text || span?.section_heading || span?.ich_m11_anchor || "")
 .replace(/\s+/g, " ")
 .trim();
 const summary = source.length > 110 ? `${source.slice(0, 107)}...` : source;
 const pages = span?.source_fragments?.length > 1
 ? span.source_fragments.map((item) => `p${item.physical_page}`).join("+")
 : `p${span?.physical_page || "?"}`;
 return `${pages} · ${summary || "未识别到正文"}`;
}

export function WritingReferencePanel({
 projectId,
 selectedBriefIds = [],
 onSelectedBriefIdsChange = () => {},
 onUseEvidence = () => {},
 variant = "editor",
 snapshotId = "",
 lockedIndication = "",
 lockedPhase = "",
 journey = null,
 onJourneyChange = () => {},
 onTriagePipelineChange = () => {},
 embedded = false,
 compact = false,
 requestedView = "",
 requestedArtifactId = "",
 focusRequestKey = "",
 refreshSignal = 0,
}) {
 const authoringMode = variant === "authoring";
 const presentationClass = [
 "writing-reference-panel",
 authoringMode ? "authoring-mode" : "",
 embedded ? "is-embedded" : "",
 compact ? "is-compact" : "",
 ].filter(Boolean).join(" ");
 const activeProjectRef = useRef(projectId);
 const activeSnapshotRef = useRef(snapshotId);
 const refreshGenerationRef = useRef(0);
 const manualFileInputRef = useRef(null);
 const manualUploadKeyRef = useRef("");
 const aiTriageCreateKeyRef = useRef("");
 const legacyIssueToolsRef = useRef(null);
 const translationReviewRef = useRef(null);
 const [workspace, setWorkspace] = useState(null);
 const [activeView, setActiveView] = useState(authoringMode ? "candidates" : "approved");
 const [loading, setLoading] = useState(false);
 const [busyAction, setBusyAction] = useState("");
 const [message, setMessage] = useState("");
 const [indication, setIndication] = useState(lockedIndication);
 const [phase, setPhase] = useState(lockedPhase || "PHASE2");
 const phase1SharedAvailable = authoringMode && isPhase1(
 lockedPhase || journey?.framing?.study_phase || phase,
 );
 const [selectedNctId, setSelectedNctId] = useState("");
 const [selectedArtifactId, setSelectedArtifactId] = useState("");
 const [selectedSpanId, setSelectedSpanId] = useState("");
 const [reason, setReason] = useState("");
 const [reviewComment, setReviewComment] = useState("");
 const [showReviewWithdrawal, setShowReviewWithdrawal] = useState(false);
 const [structureReviewComment, setStructureReviewComment] = useState("");
 const [structureIssues, setStructureIssues] = useState("");
 const [validationOverrideReason, setValidationOverrideReason] = useState("");
 const [acknowledgedValidationCodes, setAcknowledgedValidationCodes] = useState([]);
 const [spans, setSpans] = useState([]);
 const [spanMeta, setSpanMeta] = useState({ extractionRevision: "", anchorCounts: {}, total: 0, filteredTotal: 0 });
 const [spanAnchorFilter, setSpanAnchorFilter] = useState("all");
 const [spanOffset, setSpanOffset] = useState(0);
 const [candidateQuery, setCandidateQuery] = useState("");
 const [candidateStatus, setCandidateStatus] = useState("retained");
 const [candidatePage, setCandidatePage] = useState(1);
 const [triageReason, setTriageReason] = useState("");
 const [noSuitableCompetitorReason, setNoSuitableCompetitorReason] = useState("");
 const [aiTriageJobId, setAiTriageJobId] = useState("");
 const [aiTriageStatus, setAiTriageStatus] = useState("");
 const [aiTriageError, setAiTriageError] = useState("");
 const [aiTriageRun, setAiTriageRun] = useState(null);
 const [aiTriagePipeline, setAiTriagePipeline] = useState(null);
 const [aiTriageSelections, setAiTriageSelections] = useState({});
 const [aiTriageDetailsOpen, setAiTriageDetailsOpen] = useState(false);
 const [aiTriageRecovering, setAiTriageRecovering] = useState(false);
 const aiTriageSelectionRunRef = useRef("");
 const [alignmentStatus, setAlignmentStatus] = useState("no_conflicts");
 const [alignmentConflictCount, setAlignmentConflictCount] = useState(0);
 const [alignmentSummary, setAlignmentSummary] = useState("");
 const [manualFile, setManualFile] = useState(null);
 const [manualDocumentType, setManualDocumentType] = useState("protocol");
 const [manualDocumentDate, setManualDocumentDate] = useState("");
 const [legacyIssueOpen, setLegacyIssueOpen] = useState(false);

 const refreshWorkspace = async ({ preserveMessage = false } = {}) => {
 const requestedProjectId = projectId;
 const generation = ++refreshGenerationRef.current;
 setLoading(true);
 if (!preserveMessage) setMessage("");
 try {
 const query = authoringMode && snapshotId ? `?snapshot_id=${encodeURIComponent(snapshotId)}` : "";
 const payload = await fetch(`/api/projects/${projectId}/medical-writing/references/workspace${query}`).then(readJson);
 if (generation !== refreshGenerationRef.current || activeProjectRef.current !== requestedProjectId) return;
 if (authoringMode && snapshotId && payload.snapshot?.snapshot_id !== snapshotId) {
 throw new Error("语料工作区返回了非当前建项快照，请刷新后重试");
 }
 setWorkspace(payload);
 if (payload.snapshot?.request) {
 setIndication(payload.snapshot.request.indication || "");
 setPhase(payload.snapshot.request.phases?.[0] || "PHASE2");
 }
 const candidateIds = (payload.snapshot?.candidates || []).map((item) => item.nct_id);
 setSelectedNctId((current) => candidateIds.includes(current) ? current : candidateIds[0] || "");
 const artifactIds = (payload.artifacts || []).map((item) => item.artifact_id);
 setSelectedArtifactId((current) => artifactIds.includes(current) ? current : artifactIds[0] || "");
 } catch (error) {
 if (generation === refreshGenerationRef.current && activeProjectRef.current === requestedProjectId) {
 setMessage(`竞品方案参照读取失败：${error.message}`);
 }
 } finally {
 if (generation === refreshGenerationRef.current && activeProjectRef.current === requestedProjectId) setLoading(false);
 }
 };

 // Batch medical-review/admission changes the evidence rows in the parent
 // workspace but may leave the journey revision unchanged. Reconcile the
 // corpus gate explicitly before handing the journey back to the authoring
 // surface; otherwise a successful batch confirmation remains displayed as
 // an old, missing-gate state until an unrelated reference action occurs.
 const refreshAuthoringAfterBatchSettled = async () => {
 await refreshWorkspace({ preserveMessage: true });
 if (!authoringMode || !projectId) return;
 const recalculated = await fetch(
 `/api/projects/${projectId}/medical-writing/authoring-journey/corpus-gate/recalculate`,
 { method: "POST" },
 ).then(readJson);
 const authoritative = await fetch(
 `/api/projects/${projectId}/medical-writing/authoring-journey?allow_missing=true`,
 ).then(readJson);
 onJourneyChange(authoritative.available === false ? recalculated : authoritative);
 };

 const adoptTriageRun = (payload) => {
 const run = payload?.run;
 if (!run || !activeSnapshotRef.current || run.snapshot_id !== activeSnapshotRef.current) {
 throw new Error("AI分诊结果不属于当前建项快照，已阻止载入");
 }
 setAiTriageRun(payload);
 // A terminal durable-job state is more specific than the business run
 // when a parent pipeline times out before the run can persist its own end state.
 setAiTriageStatus((current) => (
 ["failed", "cancelled"].includes(current) ? current : run.status || current
 ));
 setAiTriageError("");
 const isNewRun = aiTriageSelectionRunRef.current !== run.run_id;
 const latestResults = triageCandidateResults(payload);
 setAiTriageSelections((current) => mergeTriageSelections(
 current,
 latestResults,
 { reset: isNewRun },
 ));
 if (isNewRun) {
 setAiTriageDetailsOpen(false);
 aiTriageSelectionRunRef.current = run.run_id;
 }
 return payload;
 };

 const recoverLatestTriageRun = async ({ silentNotFound = true, background = false } = {}) => {
 if (!authoringMode || !projectId || !snapshotId) return null;
 const requestedProjectId = projectId;
 const requestedSnapshotId = snapshotId;
 if (!background) setAiTriageRecovering(true);
 try {
 const pipelineRequest = fetch(
 `/api/projects/${projectId}/medical-writing/research-pipeline/status`,
 ).catch(() => null);
 const response = await fetch(
 `/api/projects/${projectId}/medical-writing/authoring-journey/competitor-triage/latest?snapshot_id=${encodeURIComponent(snapshotId)}`,
 );
 const pipelineResponse = await pipelineRequest;
 if (pipelineResponse?.ok) {
 const pipelinePayload = await pipelineResponse.json().catch(() => ({}));
 if (
 activeProjectRef.current === requestedProjectId
 && activeSnapshotRef.current === requestedSnapshotId
 ) {
 setAiTriagePipeline(pipelinePayload?.pipeline || null);
 // Propagate the latest parent research-pipeline payload to the outer
 // authoring page so its compact toolbar and banner converge to the
 // same terminal state the drawer already observes.
 onTriagePipelineChange(pipelinePayload?.pipeline || null);
 }
 } else if (
 pipelineResponse?.status === 404
 && activeProjectRef.current === requestedProjectId
 && activeSnapshotRef.current === requestedSnapshotId
 ) {
 setAiTriagePipeline(null);
 onTriagePipelineChange(null);
 }
 if (response.status === 404 && silentNotFound) return null;
 const payload = await readJson(response);
 if (
 activeProjectRef.current !== requestedProjectId
 || activeSnapshotRef.current !== requestedSnapshotId
 ) return null;
 return adoptTriageRun(payload);
 } catch (error) {
 setAiTriageError(`AI分诊结果恢复失败：${error.message}`);
 return null;
 } finally {
 if (
 activeProjectRef.current === requestedProjectId
 && activeSnapshotRef.current === requestedSnapshotId
 && !background) setAiTriageRecovering(false);
 }
 };

 useEffect(() => {
 activeProjectRef.current = projectId;
 activeSnapshotRef.current = snapshotId;
 refreshGenerationRef.current += 1;
 setWorkspace(null);
 setSelectedNctId("");
 setSelectedArtifactId("");
 setSelectedSpanId("");
 setSpans([]);
 setSpanMeta({ extractionRevision: "", anchorCounts: {}, total: 0, filteredTotal: 0 });
 setSpanAnchorFilter("all");
 setSpanOffset(0);
 setValidationOverrideReason("");
 setAcknowledgedValidationCodes([]);
 setStructureReviewComment("");
 setStructureIssues("");
 setCandidateQuery("");
 setCandidateStatus("retained");
 setCandidatePage(1);
 setAiTriageJobId("");
 setAiTriageStatus("");
 setAiTriageError("");
 setAiTriageRun(null);
 setAiTriagePipeline(null);
 setAiTriageSelections({});
 setAiTriageRecovering(false);
 aiTriageSelectionRunRef.current = "";
 setManualFile(null);
 setManualDocumentType("protocol");
 setManualDocumentDate("");
 setLegacyIssueOpen(false);
 manualUploadKeyRef.current = "";
 if (manualFileInputRef.current) manualFileInputRef.current.value = "";
 refreshWorkspace();
 }, [projectId, snapshotId]);

 useEffect(() => {
 setIndication(lockedIndication);
 setPhase(lockedPhase || "PHASE2");
 }, [lockedIndication, lockedPhase]);

 useEffect(() => {
 if (refreshSignal > 0) {
 refreshWorkspace();
 recoverLatestTriageRun({ silentNotFound: true, background: true });
 }
 // refreshSignal is an external open-transition trigger; both views use current props.
 // eslint-disable-next-line react-hooks/exhaustive-deps
 }, [refreshSignal]);

 useEffect(() => {
 if (!focusRequestKey) return;
 if (viewDefinitions.some((view) => view.id === requestedView)) {
 setActiveView(requestedView);
 }
 if (requestedArtifactId) {
 setSelectedArtifactId(requestedArtifactId);
 }
 globalThis.requestAnimationFrame?.(() => {
 translationReviewRef.current?.scrollIntoView?.({ block: "start", behavior: "smooth" });
 });
 }, [focusRequestKey, requestedArtifactId, requestedView]);

 useEffect(() => {
 if (!selectedArtifactId) {
 setSpans([]);
 setSpanMeta({ extractionRevision: "", anchorCounts: {}, total: 0, filteredTotal: 0 });
 setSelectedSpanId("");
 return;
 }
 const controller = new AbortController();
 const anchorQuery = spanAnchorFilter === "all"
 ? ""
 : `&ich_m11_anchor=${encodeURIComponent(spanAnchorFilter)}`;
 fetch(`/api/projects/${projectId}/medical-writing/references/documents/${selectedArtifactId}/spans?limit=500&offset=${spanOffset}${anchorQuery}`, { signal: controller.signal })
 .then(readJson)
 .then((payload) => {
 setSpans(payload.items || []);
 setSpanMeta({
 extractionRevision: payload.extraction_revision || "",
 anchorCounts: payload.anchor_counts || {},
 total: Object.values(payload.anchor_counts || {}).reduce((sum, value) => sum + Number(value || 0), 0),
 filteredTotal: payload.total || 0,
 });
 setSelectedSpanId((current) => (payload.items || []).some((item) => item.span_id === current) ? current : payload.items?.[0]?.span_id || "");
 })
 .catch((error) => {
 if (error.name !== "AbortError") setMessage(`结构化片段读取失败：${error.message}`);
 });
 return () => controller.abort();
 }, [
 projectId,
 selectedArtifactId,
 spanAnchorFilter,
 spanOffset,
 workspace?.document_validations?.find((item) => item.artifact_id === selectedArtifactId)?.revision,
 workspace?.artifact_span_counts?.[selectedArtifactId],
 ]);

 useEffect(() => {
 setSpanAnchorFilter("all");
 setSpanOffset(0);
 }, [selectedArtifactId]);

 const snapshot = workspace?.snapshot;
 const candidates = snapshot?.candidates || [];
 const aiTriageResults = useMemo(
 () => triageCandidateResults(aiTriageRun),
 [aiTriageRun],
 );
 const aiTriagePresentation = useMemo(() => deriveTriagePresentation({
 run: aiTriageRun?.run,
 jobStatus: aiTriageStatus,
 hasActiveJob: Boolean(aiTriageJobId) && ["starting", "queued", "running", "resuming"].includes(aiTriageStatus),
 pipeline: aiTriagePipeline,
 snapshotId,
 candidateCount: candidates.length,
 }), [aiTriageJobId, aiTriagePipeline, aiTriageRun, aiTriageStatus, candidates.length, snapshotId]);
 const aiTriageCoverageComplete = Boolean(candidates.length)
 && aiTriageResults.length === candidates.length
 && candidates.every((candidate) => aiTriageSelections[candidate.nct_id]);
 const aiTriageRetainedCount = candidates.filter((candidate) => (
 ["direct_competitor", "indirect_reference"].includes(
 aiTriageSelections[candidate.nct_id],
 )
 )).length;
 const aiTriageAllExcluded = aiTriageCoverageComplete && aiTriageRetainedCount === 0;
 const noSuitableCompetitorReasonValid = !aiTriageAllExcluded
 || noSuitableCompetitorReason.trim().length >= 10;
 const candidateDisplayStatus = useCallback((candidate) => (
 aiTriageRun?.run?.status === "review_ready"
 ? aiTriageSelections[candidate.nct_id] || candidate.relevance_status
 : currentDecision(workspace, candidate.nct_id)?.relevance_status || candidate.relevance_status
 ), [aiTriageRun?.run?.status, aiTriageSelections, workspace]);
 const candidatePageSize = 50;
 const filteredCandidates = useMemo(() => {
 const query = candidateQuery.trim().toLowerCase();
 return candidates.filter((candidate) => {
 const status = candidateDisplayStatus(candidate);
 if (
 candidateStatus === "retained"
 ? !["direct_competitor", "indirect_reference"].includes(status)
 : candidateStatus !== "all" && status !== candidateStatus
 ) return false;
 if (!query) return true;
 return [candidate.nct_id, candidate.brief_title, candidate.official_title, candidate.lead_sponsor]
 .some((value) => String(value || "").toLowerCase().includes(query));
 });
 }, [
 candidateDisplayStatus,
 candidates,
 candidateQuery,
 candidateStatus,
 ]);
 const candidatePageCount = Math.max(1, Math.ceil(filteredCandidates.length / candidatePageSize));
 const visibleCandidates = filteredCandidates.slice(
 (candidatePage - 1) * candidatePageSize,
 candidatePage * candidatePageSize,
 );
 const selectedCandidate = filteredCandidates.find(
 (item) => item.nct_id === selectedNctId,
 ) || filteredCandidates[0] || candidates.find(
 (item) => item.nct_id === selectedNctId,
 ) || candidates[0];
 const selectedCandidateDecision = currentDecision(workspace, selectedCandidate?.nct_id);
 const triageFinalized = authoringMode
 && journey?.corpus_triage?.status === "finalized"
 && journey?.corpus_triage?.snapshot_id === snapshotId;
 const triageReviewLocked = triageFinalized || (
 authoringMode && aiTriageRun?.run?.status === "confirmed"
 );
 const retainedCandidateIds = journey?.corpus_triage?.retained_candidate_ids || [];
 const retainedCandidateIdSet = useMemo(
 () => new Set(retainedCandidateIds),
 [retainedCandidateIds],
 );
 const documentCandidates = triageFinalized
 ? candidates.filter((item) => retainedCandidateIdSet.has(item.nct_id))
 : candidates;
 const selectedDocumentCandidate = documentCandidates.find((item) => item.nct_id === selectedNctId)
 || documentCandidates[0];
 const selectedDocumentCandidateDecision = currentDecision(workspace, selectedDocumentCandidate?.nct_id);
 const selectedCandidateCanIngest = ["direct_competitor", "indirect_reference"].includes(
 selectedDocumentCandidateDecision?.relevance_status,
 );
 const selectedArtifact = (workspace?.artifacts || []).find((item) => item.artifact_id === selectedArtifactId);
 const selectedValidation = (workspace?.document_validations || []).find((item) => item.artifact_id === selectedArtifactId);
 const validationWarnings = (selectedValidation?.checks || []).filter((check) => ["warning", "mismatch"].includes(check.outcome));
 const selectedSpan = spans.find((item) => item.span_id === selectedSpanId) || spans[0];
 const selectedExtractionRevision = spanMeta.extractionRevision || selectedSpan?.extraction_revision || "";
 const selectedExtractionAnchors = Object.keys(spanMeta.anchorCounts)
 .filter((item) => item && item !== "unmapped")
 .sort();
 const selectedExtractionReview = (workspace?.extraction_reviews || [])
 .filter((item) => item.artifact_id === selectedArtifactId && item.extraction_revision === selectedExtractionRevision)
 .sort((left, right) => right.revision - left.revision)[0];
 const selectedTranslation = (workspace?.translations || []).find((item) => item.span_id === selectedSpan?.span_id);
 const selectedReview = currentReview(workspace, selectedTranslation);
 const selectedBrief = (workspace?.evidence_brief_history || []).find(
 (item) => item.translation_id === selectedTranslation?.translation_id
 && item.translation_revision === selectedTranslation?.revision
 && item.status === "approved_current",
 );
 const selectedTranslationInvalidated = Boolean(
 selectedTranslation?.status?.startsWith("invalidated_"),
 );
 const selectedReviewIsCurrentConfirmation = Boolean(
 selectedReview?.decision === "approved"
 && selectedReview?.decision_type === "author_confirmation"
 && selectedReview?.admission_status === "admitted"
 && selectedTranslation?.status === "author_confirmed_admitted"
 && selectedBrief,
 );
 const legacyApprovedAwaitingAuthorConfirmation = Boolean(
 selectedReview?.decision === "approved"
 && !selectedBrief
 && !selectedTranslationInvalidated
 && (
 selectedReview?.decision_type !== "author_confirmation"
 || selectedReview?.admission_status !== "admitted"
 ),
 );
 const currentBriefs = workspace?.approved_evidence_briefs || [];
 const currentBriefIdSet = new Set(currentBriefs.map((item) => item.brief_id));
 const displayedBriefHistory = [...(workspace?.evidence_brief_history || [])].sort((left, right) => {
 const currentDelta = Number(currentBriefIdSet.has(right.brief_id)) - Number(currentBriefIdSet.has(left.brief_id));
 if (currentDelta) return currentDelta;
 return String(right.recorded_at || right.created_at || "").localeCompare(
 String(left.recorded_at || left.created_at || ""),
 );
 });
 const alignmentSubmitDisabledReason = !journey?.picos_sha256
 ? "当前PICOS尚未形成可核对版本"
 : alignmentSummary.trim().length < 10
 ? "请填写至少10个字的核对与处置说明"
 : alignmentStatus === "resolved" && Number(alignmentConflictCount) < 1
 ? "请填写已处置冲突数"
 : busyAction
 ? "前一项操作尚未完成"
 : "";
 const artifactBySourceDocument = useMemo(
 () => new Map((workspace?.artifacts || []).map((item) => [item.source_document_id, item])),
 [workspace?.artifacts],
 );
 const selectedManualArtifacts = (workspace?.artifacts || []).filter(
 (item) => item.nct_id === selectedDocumentCandidate?.nct_id && item.source_status === "user_uploaded",
 );
 const selectCandidateForReview = (nctId) => {
 setSelectedNctId(nctId);
 setSelectedArtifactId((currentArtifactId) => alignedArtifactId(
 workspace?.artifacts,
 currentArtifactId,
 nctId,
 ));
 };

 useEffect(() => {
 setValidationOverrideReason("");
 setAcknowledgedValidationCodes([]);
 setStructureReviewComment("");
 setStructureIssues("");
 }, [selectedArtifactId, selectedValidation?.revision, selectedExtractionReview?.revision]);

 useEffect(() => {
 setShowReviewWithdrawal(false);
 setReviewComment("");
 }, [selectedSpan?.span_id, selectedTranslation?.revision]);

 useEffect(() => {
 setCandidatePage((current) => Math.min(current, candidatePageCount));
 }, [candidatePageCount]);

 useEffect(() => {
 if (activeView !== "documents" || !documentCandidates.length) return;
 if (!documentCandidates.some((item) => item.nct_id === selectedNctId)) {
 setSelectedNctId(documentCandidates[0].nct_id);
 }
 }, [activeView, documentCandidates, selectedNctId]);

 const runAction = async (key, action, successMessage) => {
 setBusyAction(key);
 setMessage("");
 try {
 await action();
 await refreshWorkspace({ preserveMessage: true });
 if (authoringMode) {
 const recalculated = await fetch(`/api/projects/${projectId}/medical-writing/authoring-journey/corpus-gate/recalculate`, {
 method: "POST",
 }).then(readJson);
 // The recalculation endpoint returns the persisted journey model, while
 // the read endpoint adds derived hashes (notably picos_sha256) that the
 // PICOS alignment contract needs. Keep the parent state on that
 // authoritative read shape after every reference action; otherwise a
 // successful refresh silently makes the visible alignment button look
 // as if PICOS had never been completed.
 const authoritative = await fetch(
 `/api/projects/${projectId}/medical-writing/authoring-journey?allow_missing=true`,
 ).then(readJson);
 onJourneyChange(authoritative.available === false ? recalculated : authoritative);
 }
 setMessage(successMessage);
 } catch (error) {
 setMessage(`操作未完成：${error.message}`);
 } finally {
 setBusyAction("");
 }
 };

 const submitSearch = () => runAction(
 "search",
 () => fetch(`/api/projects/${projectId}/medical-writing/references/search-snapshots`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 search: { indication: indication.trim(), phases: phase ? [phase] : [], study_type: "INTERVENTIONAL", page_size: 100 },
 actor: "medical_manager",
 idempotency_key: requestKey("reference-search"),
 }),
 }).then(readJson),
 "公开研究检索已完成；候选研究仍需医学分类。",
 );

 const relatedDecisionIds = (workspace?.decisions || [])
 .filter((item) => ["direct_competitor", "indirect_reference"].includes(item.relevance_status))
 .map((item) => item.nct_id);

 const finalizeTriage = () => runAction(
 "finalize-triage",
 async () => {
 const updated = await fetch(`/api/projects/${projectId}/medical-writing/authoring-journey/corpus-triage/finalize`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 expected_revision: journey.revision,
 snapshot_id: snapshotId,
 retained_candidate_ids: relatedDecisionIds,
 reason: triageReason.trim(),
 actor: "medical_manager",
 idempotency_key: requestKey("reference-triage-finalize"),
 }),
 }).then(readJson);
 onJourneyChange(updated);
 },
 `已锁定${relatedDecisionIds.length}项直接竞品/间接参照进入深度语料处理。`,
 );

 const startAiTriage = async () => {
 if (
 (shouldBlockStart(aiTriageStatus) && aiTriageRun?.run?.status !== "stale")
 || busyAction
 ) return; // dedupe
 setAiTriageError("");
 setAiTriageStatus("starting");
 const storageKey = `mw_triage_job_${projectId}`;
 if (!aiTriageCreateKeyRef.current) {
 aiTriageCreateKeyRef.current = requestKey("competitor-triage");
 }
 try {
 const resp = await fetch(
 `/api/projects/${projectId}/medical-writing/authoring-journey/competitor-triage`,
 {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 snapshot_id: snapshotId,
 expected_journey_revision: journey?.revision || 0,
 actor: "medical_manager",
 idempotency_key: aiTriageCreateKeyRef.current,
 }),
 },
 );
 const body = await readJson(resp);
 if (!resp.ok) {
 aiTriageCreateKeyRef.current = "";
 setAiTriageError(`AI分诊启动失败：${typeof body.detail === "string" ? body.detail : JSON.stringify(body.detail || body)}`);
 setAiTriageStatus("");
 return;
 }
 const jobId = body.job_id;
 const runId = body.run_id || "";
 if (!jobId) {
 setAiTriageError("AI分诊启动失败：后端未返回作业标识。");
 setAiTriageStatus("");
 return;
 }
 setAiTriageJobId(jobId);
 setAiTriageStatus("queued");
 const locator = buildLocator({
 projectId,
 jobId,
 operation: "competitor_triage",
 jobType: "competitor_triage",
 runId,
 snapshotId,
 });
 try { localStorage.setItem(storageKey, JSON.stringify(locator)); } catch { /* ignore */ }
 const { status, result, error, transportResultOk } = await pollDurableMwJob(projectId, jobId, {
 intervalMs: 2000, maxLoops: 150,
 onUpdate: (st) => setAiTriageStatus(st.status),
 });
 setAiTriageStatus(status);
 const ack = acknowledgeTriageDomain({
 status,
 resultBody: transportResultOk ? result : null,
 locator,
 expectedRunId: runId,
 expectedSnapshotId: snapshotId,
 });
 if (ack.outcome === "success") {
 setMessage("AI分诊已完成。请整体浏览AI建议，必要时展开修改，再一次确认并锁定。");
 await recoverLatestTriageRun({ silentNotFound: false });
 } else if (ack.outcome === "terminal_failure") {
 setAiTriageError(status === "cancelled"
 ? "AI分诊已取消。"
 : `AI分诊失败：${error || "请检查生产AI配置后重试。"}`);
 await recoverLatestTriageRun();
 } else {
 setAiTriageError(
 ack.outcome === "reconcile_failed"
 ? "AI分诊已结束，但结果核对失败。定位器已保留，请重试核对。"
 : "AI分诊仍在后台进行，请稍后查看或刷新页面恢复。",
 );
 }
 if (ack.shouldClear) {
 try { localStorage.removeItem(storageKey); } catch { /* ignore */ }
 setAiTriageJobId("");
 aiTriageCreateKeyRef.current = "";
 }
 } catch (err) {
 setAiTriageError(`AI分诊请求异常：${err.message || err}`);
 setAiTriageStatus("");
 }
 };

 const cancelAiTriage = async () => {
 if (!aiTriageJobId) return;
 try {
 await fetch(`/api/projects/${projectId}/medical-writing/jobs/${aiTriageJobId}/cancel`, { method: "POST" });
 // Do not clear locator without domain recon (no cancelled override).
 const { status, result, transportResultOk } = await pollDurableMwJob(projectId, aiTriageJobId, {
 intervalMs: 1000, maxLoops: 30, onUpdate: (st) => setAiTriageStatus(st.status),
 });
 setAiTriageStatus(status);
 let locator = null;
 try { locator = JSON.parse(localStorage.getItem(`mw_triage_job_${projectId}`) || "null"); } catch { /* ignore */ }
 const ack = acknowledgeTriageDomain({
 status,
 resultBody: transportResultOk ? result : null,
 locator,
 });
 setAiTriageError(
 ack.domainReconciled
 ? "AI分诊已取消。"
 : "取消请求已发送，结果核对未完成。定位器已保留，请重试核对。",
 );
 if (ack.shouldClear) {
 try { localStorage.removeItem(`mw_triage_job_${projectId}`); } catch { /* ignore */ }
 setAiTriageJobId("");
 }
 } catch { /* best-effort */ }
 };

 const retryAiTriageRun = async () => {
 const run = aiTriageRun?.run;
 if (!run) {
 setAiTriageError("未找到当前分诊运行，无法安全重试；请刷新当前候选结果后再启动分诊。");
 return;
 }
 if (run.status === "stale") {
 setAiTriageRun(null);
 setAiTriageSelections({});
 aiTriageSelectionRunRef.current = "";
 await startAiTriage();
 return;
 }
 if (busyAction) return;
 setBusyAction("retry-ai-triage");
 setAiTriageError("");
 setAiTriageStatus("starting");
 const storageKey = `mw_triage_job_${projectId}`;
 try {
 const incompleteChunkIds = (run.chunks || [])
 .filter((chunk) => chunk.status !== "succeeded")
 .map((chunk) => chunk.chunk_id);
 const retryKey = requestKey("competitor-triage-retry");
 const recoverParentPipeline = aiTriagePipeline?.stage === "failed"
 && aiTriagePipeline?.triage_run_id === run.run_id
 && (!aiTriagePipeline?.snapshot_id || aiTriagePipeline.snapshot_id === snapshotId);
 const body = await fetch(
 recoverParentPipeline
 ? `/api/projects/${projectId}/medical-writing/research-pipeline/retry-triage`
 : `/api/projects/${projectId}/medical-writing/authoring-journey/competitor-triage/${run.run_id}/retry`,
 {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify(recoverParentPipeline ? {
 actor: "medical_manager",
 idempotency_key: retryKey,
 expected_pipeline_id: aiTriagePipeline.pipeline_id,
 expected_triage_run_id: run.run_id,
 } : {
 actor: "medical_manager",
 idempotency_key: retryKey,
 chunk_ids: incompleteChunkIds,
 }),
 },
 ).then(readJson);
 const retryJobId = body.triage_job_id || body.job_id;
 if (!retryJobId) throw new Error("后端未返回重试作业标识");
 if (body.pipeline) setAiTriagePipeline(body.pipeline);
 const locator = buildLocator({
 projectId,
 jobId: retryJobId,
 operation: "competitor_triage",
 jobType: "competitor_triage",
 runId: body.run_id || run.run_id,
 snapshotId,
 });
 try { localStorage.setItem(storageKey, JSON.stringify(locator)); } catch { /* ignore */ }
 setAiTriageJobId(retryJobId);
 setAiTriageStatus("queued");
 await recoverLatestTriageRun({ silentNotFound: false, background: true });
 const polled = await pollDurableMwJob(projectId, retryJobId, {
 intervalMs: 2000,
 maxLoops: 150,
 onUpdate: (state) => setAiTriageStatus(state.status),
 });
 const ack = acknowledgeTriageDomain({
 status: polled.status,
 resultBody: polled.transportResultOk ? polled.result : null,
 locator,
 expectedRunId: locator.run_id,
 expectedSnapshotId: snapshotId,
 });
 if (ack.outcome === "success") {
 setMessage("AI分诊重试已完成，请整体浏览后一次确认并锁定。");
 } else if (ack.outcome === "terminal_failure") {
 setAiTriageError(`AI分诊重试失败：${polled.error || "请查看失败分块后再次重试。"}`);
 } else {
 setAiTriageError("AI分诊重试已结束，但结果尚未完成核对，请刷新状态。");
 }
 await recoverLatestTriageRun({ silentNotFound: false });
 if (ack.shouldClear) {
 try { localStorage.removeItem(storageKey); } catch { /* ignore */ }
 setAiTriageJobId("");
 }
 } catch (error) {
 setAiTriageStatus(run.status);
 setAiTriageError(`AI分诊重试未完成：${error.message}`);
 } finally {
 setBusyAction("");
 }
 };

 const confirmAiTriageRun = async () => {
 const run = aiTriageRun?.run;
 if (!run || run.status !== "review_ready" || !aiTriageCoverageComplete) return;
 const allCandidateIds = candidates.map((candidate) => candidate.nct_id);
 const retainedNctIds = allCandidateIds.filter((nctId) => (
 ["direct_competitor", "indirect_reference"].includes(aiTriageSelections[nctId])
 ));
 const excludedNctIds = allCandidateIds.filter((nctId) => aiTriageSelections[nctId] === "excluded");
 if (retainedNctIds.length + excludedNctIds.length !== allCandidateIds.length) {
 setAiTriageError("仍有候选研究未完成分类，无法确认。");
 return;
 }
 if (!retainedNctIds.length && noSuitableCompetitorReason.trim().length < 10) {
 setAiTriageError("全部候选均排除时，请填写至少10个字的无合适竞品理由。");
 return;
 }
 const finalClassifications = Object.fromEntries(
 allCandidateIds.map((nctId) => [nctId, aiTriageSelections[nctId]]),
 );
 setBusyAction("confirm-ai-triage");
 setAiTriageError("");
 try {
 const confirmation = await fetch(
 `/api/projects/${projectId}/medical-writing/authoring-journey/competitor-triage/${run.run_id}/confirm`,
 {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 expected_run_revision: run.canonical_input_hash,
 retained_nct_ids: retainedNctIds,
 excluded_nct_ids: excludedNctIds,
 final_classifications: finalClassifications,
 no_suitable_competitor_reason: retainedNctIds.length
 ? ""
 : noSuitableCompetitorReason.trim(),
 actor: "medical_manager",
 reason: triageReason.trim() || "医学经理已整体核对AI分诊结果并确认锁定当前竞品篮子。",
 idempotency_key: requestKey("competitor-triage-confirm"),
 expected_journey_revision: journey?.revision || 0,
 }),
 },
 ).then(readJson);
 await refreshWorkspace({ preserveMessage: true });
 const latestJourney = await fetch(
 `/api/projects/${projectId}/medical-writing/authoring-journey`,
 ).then(readJson);
 onJourneyChange(latestJourney);
 await recoverLatestTriageRun({ silentNotFound: false });
 const pipeline = confirmation?.pipeline || null;
 const pipelineStage = String(pipeline?.stage || "").trim();
 const pipelineAdvanced = confirmation?.pipeline_advanced === true;
 if (!retainedNctIds.length) {
 setMessage("已确认本次公开检索结果中无合适竞品；可继续手工上传方案或使用通用语料库。");
 } else if (pipelineAdvanced) {
 setMessage(`已按本次审核结果确认并锁定全部${allCandidateIds.length}项候选研究。研究流水线已开始继续处理原文。`);
 } else if (pipelineStage) {
 setMessage(
 `已按本次审核结果确认并锁定全部${allCandidateIds.length}项候选研究；研究流水线当前为“${pipelineStage}”，尚未确认进入原文处理。请刷新状态后再继续。`,
 );
 } else {
 const pipelineError = String(confirmation?.pipeline_error || "").trim();
 setMessage(
 pipelineError
 ? `已确认并锁定全部${allCandidateIds.length}项候选研究，但原文处理未启动：${pipelineError}。系统未将其显示为已开始，请先处理该问题后重试。`
 : `已确认并锁定全部${allCandidateIds.length}项候选研究，但研究流水线尚未建立；系统未开始下载原文。请刷新检索状态后重试。`,
 );
 }
 } catch (error) {
 setAiTriageError(`确认并锁定未完成：${error.message}`);
 } finally {
 setBusyAction("");
 }
 };

 const retryAiTriageProjection = async () => {
 const run = aiTriageRun?.run;
 if (!run || run.status !== "projection_pending") return;
 setBusyAction("retry-ai-triage-projection");
 setAiTriageError("");
 try {
 await fetch(
 `/api/projects/${projectId}/medical-writing/authoring-journey/competitor-triage/${run.run_id}/projection-retry`,
 {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 actor: "medical_manager",
 idempotency_key: requestKey("competitor-triage-projection-retry"),
 }),
 },
 ).then(readJson);
 await refreshWorkspace({ preserveMessage: true });
 const latestJourney = await fetch(
 `/api/projects/${projectId}/medical-writing/authoring-journey`,
 ).then(readJson);
 onJourneyChange(latestJourney);
 await recoverLatestTriageRun({ silentNotFound: false });
 setMessage("已恢复确认结果与写作旅程的同步，无需再次审核。");
 } catch (error) {
 setAiTriageError(`确认结果同步仍未完成：${error.message}`);
 } finally {
 setBusyAction("");
 }
 };

 // Resume a durable job when its locator exists; otherwise recover the
 // latest run strictly within the current project snapshot.
 useEffect(() => {
 if (!authoringMode || !projectId || !snapshotId) return undefined;
 let cancelled = false;
 try {
 const storageKey = `mw_triage_job_${projectId}`;
 const stored = JSON.parse(localStorage.getItem(storageKey) || "null");
 if (stored?.job_id && stored.snapshot_id === snapshotId && !aiTriageJobId) {
 setAiTriageJobId(stored.job_id);
 setAiTriageStatus("resuming");
 pollDurableMwJob(projectId, stored.job_id, {
 intervalMs: 2000, maxLoops: 150, onUpdate: (st) => setAiTriageStatus(st.status),
 }).then(async ({ status, result, transportResultOk, error }) => {
 if (cancelled) return;
 setAiTriageStatus(status);
 const ack = acknowledgeTriageDomain({
 status,
 resultBody: transportResultOk ? result : null,
 locator: stored,
 expectedRunId: stored.run_id || "",
 expectedSnapshotId: stored.snapshot_id || "",
 });
 if (ack.outcome === "success") {
 setMessage("AI分诊已完成。请整体浏览AI建议，必要时展开修改，再一次确认并锁定。");
 } else if (ack.outcome === "terminal_failure") {
 setAiTriageError(status === "cancelled" ? "AI分诊已取消。" : `AI分诊失败：${error || ""}`);
 } else if (ack.outcome === "reconcile_failed") {
 setAiTriageError("AI分诊已结束，但结果核对失败。定位器已保留。");
 }
 await recoverLatestTriageRun();
 if (ack.shouldClear) {
 try { localStorage.removeItem(storageKey); } catch { /* ignore */ }
 setAiTriageJobId("");
 }
 });
 } else {
 if (stored?.job_id && stored.snapshot_id !== snapshotId) {
 try { localStorage.removeItem(storageKey); } catch { /* ignore */ }
 }
 recoverLatestTriageRun();
 }
 } catch { /* ignore */ }
 return () => { cancelled = true; };
 // eslint-disable-next-line react-hooks/exhaustive-deps
 }, [projectId, snapshotId]);

 // The durable job poll owns its own lifecycle. This lightweight business-state
 // refresh keeps an already-restored drawer current and lets a parent-pipeline
 // terminal state surface without manufacturing a local timeout.
 useEffect(() => {
 const runStatus = aiTriageRun?.run?.status || "";
 const pipelineStage = aiTriagePipeline?.stage || "";
 const shouldPoll = authoringMode
 && projectId
 && snapshotId
 && aiTriagePresentation.kind !== "failed"
 && aiTriagePresentation.kind !== "stale"
 && (
 ["starting", "queued", "running", "resuming"].includes(aiTriageStatus)
 || ["queued", "running"].includes(runStatus)
 || ["queued", "triaging"].includes(pipelineStage)
 );
 if (!shouldPoll) return undefined;

 let cancelled = false;
 let timer = null;
 const refresh = async () => {
 await recoverLatestTriageRun({ silentNotFound: true, background: true });
 if (!cancelled) timer = globalThis.setTimeout(refresh, 5000);
 };
 refresh();
 return () => {
 cancelled = true;
 if (timer) globalThis.clearTimeout(timer);
 };
 // recoverLatestTriageRun is render-local; status values are the intended trigger surface.
 // eslint-disable-next-line react-hooks/exhaustive-deps
 }, [authoringMode, projectId, snapshotId, aiTriagePresentation.kind, aiTriageStatus, aiTriageRun?.run?.status, aiTriagePipeline?.stage]);

 const recordPicosAlignment = () => runAction(
 "record-picos-alignment",
 async () => {
 const currentBriefIds = (workspace?.approved_evidence_briefs || []).map((item) => item.brief_id);
 const updated = await fetch(`/api/projects/${projectId}/medical-writing/authoring-journey/picos-corpus-alignment`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({
 expected_revision: journey.revision,
 source_picos_sha256: journey.picos_sha256,
 status: alignmentStatus,
 conflict_count: alignmentStatus === "no_conflicts" ? 0 : Number(alignmentConflictCount || 0),
 disposition_summary: alignmentSummary.trim(),
 evidence_brief_ids: selectedBriefIds.length ? selectedBriefIds : currentBriefIds,
 actor: "medical_manager",
 idempotency_key: requestKey("reference-picos-alignment"),
 }),
 }).then(readJson);
 onJourneyChange(updated);
 },
 "PICOS与当前准入语料的核对结论已记录。",
 );

