 <code>{selectedSpan.source_locator}</code>
 </details>
 ) : (
 <code>{selectedSpan.source_locator}</code>
 )}
 {selectedSpan.source_fragments?.length > 1 && (
 <details className="writing-reference-cross-page-source">
 <summary>
 跨页原始片段 · {selectedSpan.source_fragments.map((item) => `p${item.physical_page}`).join(" + ")}
 </summary>
 <div>
 {selectedSpan.source_fragments.map((item) => (
 <section key={item.source_locator}>
 <code>p{item.physical_page}:b{item.block_index}</code>
 <p>{item.source_text}</p>
 </section>
 ))}
 {selectedSpan.skipped_interstitials?.length > 0 && (
 <small>
 已跳过{selectedSpan.skipped_interstitials.map((item) => (
 item.reason_code === "repeated_margin_header" ? "重复页眉" : "重复页脚"
 )).join("、")}；定位信息保留在来源记录中。
 </small>
 )}
 </div>
 </details>
 )}
 </div>
 {selectedTranslation ? (
 <>
 <div className="writing-reference-translation"><span>监管中文候选 · v{selectedTranslation.revision}</span><ReferenceTag value={selectedReviewIsCurrentConfirmation ? selectedReview.decision : selectedTranslation.status} dictionary={selectedReviewIsCurrentConfirmation ? reviewLabels : translationStatusLabels} /><p>{selectedTranslation.translated_text}</p>{selectedTranslation.fidelity_failure_codes?.length > 0 && <small>{selectedTranslation.fidelity_failure_codes.join("、")}</small>}</div>
 {selectedReview && <div className="writing-reference-review-state"><ReferenceTag value={selectedReview.decision} dictionary={selectedReviewIsCurrentConfirmation ? reviewLabels : historicalReviewLabels} /><span>{selectedReview.comment}{!selectedReviewIsCurrentConfirmation && "（仅保留为历史记录，不构成当前作者确认）"}</span></div>}
 {selectedTranslationInvalidated && <div className="writing-reference-review-state"><ReferenceTag value={selectedTranslation.status} dictionary={translationStatusLabels} /><span>请基于当前来源和结构解析重新生成译文后再确认。</span></div>}
 {!selectedTranslationInvalidated && selectedReview?.decision === "returned" && <button className="primary-button" onClick={reviseTranslation} disabled={Boolean(busyAction)}>按审核意见重新生成</button>}
 {selectedReviewIsCurrentConfirmation && !showReviewWithdrawal && <button onClick={() => setShowReviewWithdrawal(true)} disabled={Boolean(busyAction)}>发现问题，撤回译文</button>}
 {selectedReviewIsCurrentConfirmation && showReviewWithdrawal && <>
 <label>撤回理由<textarea value={reviewComment} onChange={(event) => setReviewComment(event.target.value)} placeholder="说明复核发现的具体问题；撤回后旧准入证据立即失效。" /></label>
 <div className="button-row">
 <button onClick={() => reviewTranslation("returned")} disabled={!reviewComment.trim() || Boolean(busyAction)}>确认撤回</button>
 <button onClick={() => { setShowReviewWithdrawal(false); setReviewComment(""); }} disabled={Boolean(busyAction)}>取消</button>
 </div>
 </>}
 {legacyApprovedAwaitingAuthorConfirmation && <>
 <label>当前作者确认意见<textarea value={reviewComment} onChange={(event) => setReviewComment(event.target.value)} placeholder="历史记录未完成当前准入；请对照当前原文、来源版本和译文后确认。" /></label>
 <div className="button-row">
 <button className="primary-button" onClick={() => reviewTranslation("approved")} disabled={!reviewComment.trim() || selectedTranslation.fidelity_status !== "passed" || Boolean(busyAction)}>确认当前译文并准入</button>
 <button onClick={() => reviewTranslation("returned")} disabled={!reviewComment.trim() || Boolean(busyAction)}>退回修改</button>
 <button onClick={() => reviewTranslation("rejected")} disabled={!reviewComment.trim() || Boolean(busyAction)}>拒绝</button>
 </div>
 </>}
 {!selectedReview && !selectedTranslationInvalidated && <>
 <label>作者核对意见<textarea value={reviewComment} onChange={(event) => setReviewComment(event.target.value)} placeholder="对照原文记录医学含义、数字、时间窗及否定关系的核对结论。" /></label>
 <div className="button-row">
 <button className="primary-button" onClick={() => reviewTranslation("approved")} disabled={!reviewComment.trim() || selectedTranslation.fidelity_status !== "passed" || Boolean(busyAction)}>确认译文并准入</button>
 <button onClick={() => reviewTranslation("returned")} disabled={!reviewComment.trim() || Boolean(busyAction)}>退回修改</button>
 <button onClick={() => reviewTranslation("rejected")} disabled={!reviewComment.trim() || Boolean(busyAction)}>拒绝</button>
 </div>
 </>}
 {selectedBrief && <div className="writing-reference-admitted"><CheckCircle2 size={15} />已纳入写作参考库：{selectedBrief.status === "approved_current" ? "来源当前有效" : "来源已失效"}</div>}
 </>
 ) : (
 <button className="primary-button" onClick={createTranslation} disabled={selectedExtractionReview?.decision !== "approved" || Boolean(busyAction)}>生成监管中文候选</button>
 )}
 </div>
 ) : <div className="writing-reference-empty">当前文档尚无可审核的结构化片段。</div>}
 </div>
 )}

 {activeView === "approved" && (
 <div className="writing-reference-view approved-reference-view">
 <div className="writing-reference-selection-head">
 <strong>{authoringMode ? "已准入证据" : "本次AI证据包"}</strong>
 <span>{authoringMode ? `${currentBriefs.length} 条 · 已选 ${selectedBriefIds.length} 条` : `${selectedBriefIds.length} 条`}</span>
 </div>
 <div className="writing-reference-list">
 {displayedBriefHistory.map((brief) => {
 const current = brief.status === "approved_current" && currentBriefs.some((item) => item.brief_id === brief.brief_id);
 return (
 <label className={`writing-reference-brief ${current ? "" : "invalid"}`} key={brief.brief_id}>
 <input type="checkbox" checked={selectedBriefIds.includes(brief.brief_id)} disabled={!current} onChange={() => toggleBrief(brief.brief_id)} />
 <span><strong>{brief.nct_id} · {brief.ich_m11_anchor}</strong><ReferenceTag value={current ? "approved" : "invalidated_source"} dictionary={{ approved: ["作者已确认并准入", "success"], invalidated_source: ["来源已失效", "danger"] }} /><small>{brief.approved_zh_text}</small><code>{brief.source_locator}</code></span>
 </label>
 );
 })}
 {!displayedBriefHistory.length && <div className="writing-reference-empty">尚无作者已确认、已准入且可追溯的竞品方案证据。</div>}
 </div>
 {authoringMode ? <div className="writing-reference-alignment">
 <div><strong>PICOS与语料核对</strong><span>结论绑定当前PICOS哈希和当前有效证据；上游变更后必须重新核对。</span></div>
 <label>核对结论<select value={alignmentStatus} onChange={(event) => setAlignmentStatus(event.target.value)}><option value="no_conflicts">未发现冲突</option><option value="resolved">发现冲突且已处置</option></select></label>
 {alignmentStatus === "resolved" && <label>已处置冲突数<input type="number" min="1" value={alignmentConflictCount} onChange={(event) => setAlignmentConflictCount(event.target.value)} /></label>}
 <label>核对与处置说明<textarea value={alignmentSummary} onChange={(event) => setAlignmentSummary(event.target.value)} placeholder="逐项说明研究人群、干预、对照、终点和时间点与语料的一致性或处置结果。" /></label>
 <button className="primary-button" title={alignmentSubmitDisabledReason} onClick={recordPicosAlignment} disabled={Boolean(alignmentSubmitDisabledReason)}>{busyAction === "record-picos-alignment" ? "记录中" : "记录PICOS核对结论"}</button>
 </div> : <button className="primary-button" onClick={onUseEvidence} disabled={!selectedBriefIds.length}>返回AI修订并使用所选证据</button>}
 </div>
 )}
 </div>
 );
}

import { CheckCircle2, Circle, AlertTriangle, Loader2 } from "lucide-react";
import {
 STAGE_SEQUENCE,
 normalizeStage,
 getStageLabel,
 getActiveStages,
 getNextAction,
 isBusyStage,
 deriveDocumentTranslationProgress,
} from "./progressJourneyLogic.mjs";

export function getStageIcon(stage, isActive) {
 if (stage === "candidate_ready" || stage === "prepared") {
 return <CheckCircle2 size={14} className="success" />;
 }
 if (stage === "failed_retryable" || stage === "failed_terminal" || stage === "fidelity_blocked") {
 return <AlertTriangle size={14} className="danger" />;
 }
 if (isActive) return <Loader2 size={14} className="spin info" />;
 return <Circle size={14} className="muted" />;
}

export function WritingReferenceProgressJourney({ items = [], compact = false }) {
 const stageCounts = getActiveStages(items);
 const totalItems = items.length;
 const readyCount = stageCounts.get("candidate_ready") || 0;
 const preparedCount = stageCounts.get("prepared") || 0;
 const excludedCount = stageCounts.get("excluded") || 0;
 const failedCount = (stageCounts.get("failed_retryable") || 0)
 + (stageCounts.get("failed_terminal") || 0)
 + (stageCounts.get("fidelity_blocked") || 0);
 const activeStages = STAGE_SEQUENCE.filter((stage) => stageCounts.has(stage) && isBusyStage(stage));
 const isBusy = items.some((item) => isBusyStage(item.status || item.generation_status));
 const waitingCount = stageCounts.get("waiting") || 0;
 const unknownCount = stageCounts.get("unknown") || 0;
 const compactProgress = deriveDocumentTranslationProgress(items);

 if (compact) {
 return (
 <div className="writing-reference-progress-compact" role="status" aria-live="polite" aria-busy={isBusy}>
 <div className="writing-reference-progress-content">
 <span className="progress-summary">
 <span className={isBusy ? "info" : "muted"} data-testid="writing-reference-compact-current-progress">
 {compactProgress.activeStageDetail}
 {" · "}
 {compactProgress.progressCompleted}/{compactProgress.progressTotal}
 {" · "}
 {compactProgress.progressPercent}%
 </span>
 {readyCount > 0 && <span className="success">{readyCount} 项已就绪</span>}
 {preparedCount > 0 && <span className="success">{preparedCount} 项资料已准备</span>}
 {excludedCount > 0 && <span className="muted">{excludedCount} 项规划后排除</span>}
 {failedCount > 0 && <span className="danger">{failedCount} 项失败</span>}
 {waitingCount > 0 && <span className="muted">{waitingCount} 项等待开始</span>}
 {unknownCount > 0 && <span className="warning">{unknownCount} 项状态待同步</span>}
 {activeStages.length === 0 && readyCount === 0 && preparedCount === 0 && excludedCount === 0 && failedCount === 0 && waitingCount === 0 && unknownCount === 0 && (
 <span className="muted">等待启动</span>
 )}
 </span>
 <div
 className="writing-reference-progress-track"
 role="progressbar"
 aria-label="资料处理进度"
 aria-valuemin="0"
 aria-valuemax="100"
 aria-valuenow={compactProgress.progressPercent}
 data-testid="writing-reference-compact-progressbar"
 >
 <span style={{ width: `${compactProgress.progressPercent}%` }} />
 </div>
 </div>
 </div>
 );
 }

 return (
 <div className="writing-reference-progress-journey" role="status" aria-live="polite" aria-busy={isBusy}>
 <div className="progress-header">
 <strong>处理进度</strong>
 <span className="progress-stats">
 共 {totalItems} 项 ·
 {readyCount > 0 && <span className="success"> {readyCount} 项已就绪</span>}
 {preparedCount > 0 && <span className="success"> {preparedCount} 项资料已准备</span>}
 {excludedCount > 0 && <span className="muted"> {excludedCount} 项规划后排除</span>}
 {failedCount > 0 && <span className="danger"> {failedCount} 项失败</span>}
 </span>
 </div>
 <div
 className="writing-reference-progress-track"
 role="progressbar"
 aria-label="资料处理进度"
 aria-valuemin="0"
 aria-valuemax="100"
 aria-valuenow={compactProgress.progressPercent}
 data-testid="writing-reference-full-progressbar"
 >
 <span style={{ width: `${compactProgress.progressPercent}%` }} />
 </div>
 <div className="progress-stages">
 {STAGE_SEQUENCE.map((stage) => {
 const count = stageCounts.get(stage) || 0;
 const isActive = count > 0 && isBusyStage(stage);
 const isComplete = count > 0 && (stage === "candidate_ready" || stage === "prepared");
 return (
 <div key={stage} className={`progress-stage ${isActive ? "active" : ""} ${isComplete ? "complete" : ""}`}>
 {getStageIcon(stage, isActive)}
 <span className="stage-label">{getStageLabel(stage)}</span>
 {count > 0 && <span className="stage-count">{count}</span>}
 </div>
 );
 })}
 </div>
 </div>
 );
}

/**
 * Pure logic functions for medical writing reference progress journey.
 * These functions can be tested directly without React/JSX.
 */

// Stage progression for medical writing reference workflow
export const STAGE_SEQUENCE = [
 "searching",
 "screening",
 "downloading",
 "parsing",
 "extracting",
 "ocr_running",
 "validating",
 "prepared",
 "toc_planning",
 "translating_hy_mt2",
 "integration_qc",
 "medical_review",
 "corpus_admission",
 "chapter_mapping",
 "candidate_ready",
];

// Backward-compatible status mapping
export function normalizeStage(rawStatus) {
 const status = String(rawStatus || "").trim().toLowerCase();

 // Legacy status mapping
 const legacyMap = {
 pending: "waiting",
 accepted: "downloading",
 running: "parsing",
 download: "downloading",
 parse: "parsing",
 extract: "extracting",
 extracting: "extracting",
 validation: "validating",
 validate: "validating",
 validating: "validating",
 succeeded: "candidate_ready",
 completed: "candidate_ready",
 failed: "failed_retryable",
 failed_retryable: "failed_retryable",
 failed_terminal: "failed_terminal",
 excluded: "excluded",
 review_required: "medical_review",
 needs_review: "medical_review",
 mismatch: "fidelity_blocked",
 manual_upload_required: "failed_terminal",
 prepared: "prepared",
 candidate_ready: "candidate_ready",
 fidelity_blocked: "fidelity_blocked",
 ocr_running: "ocr_running",
 toc_planning: "toc_planning",
 translating: "translating_hy_mt2",
 translating_hy_mt2: "translating_hy_mt2",
 integration_qc: "integration_qc",
 medical_review: "medical_review",
 approved: "corpus_admission",
 corpus_admission: "corpus_admission",
 admitted: "chapter_mapping",
 chapter_mapping: "chapter_mapping",
 not_applicable: "skipped",
 };

 if (!status) return "waiting";
 return legacyMap[status] || "unknown";
}

export function getStageLabel(stage) {
 const labels = {
 searching: "检索中",
 screening: "筛选中",
 downloading: "下载中",
 parsing: "解析中",
 extracting: "文本提取中",
 ocr_running: "OCR识别中",
 validating: "内容校验中",
 prepared: "资料已准备",
 toc_planning: "目录识别中",
 translating_hy_mt2: "Hy-MT2翻译中",
 integration_qc: "衔接核对中",
 medical_review: "作者确认中",
 corpus_admission: "确认后准入中",
 chapter_mapping: "章节映射中",
 candidate_ready: "候选已就绪",
 failed_retryable: "失败（可重试）",
 failed_terminal: "失败（终止）",
 fidelity_blocked: "忠实度阻断",
 excluded: "规划后排除",
 skipped: "不适用",
 waiting: "等待开始",
 unknown: "状态待同步",
 };
 return labels[stage] || "处理中";
}

const TERMINAL_ITEM_STAGES = new Set([
 "prepared",
 "candidate_ready",
 "failed_retryable",
 "failed_terminal",
 "fidelity_blocked",
 "excluded",
 "skipped",
]);

function itemValue(item, snakeName, camelName) {
 return item?.[snakeName] ?? item?.[camelName];
}

function progressNumber(item, snakeName, camelName) {
 const value = Number(itemValue(item, snakeName, camelName));
 return Number.isFinite(value) && value >= 0 ? value : 0;
}

function getItemStage(item) {
 const generationStage = normalizeStage(
 item?.status || item?.generation_status || item?.generationStatus,
 );
 if (TERMINAL_ITEM_STAGES.has(generationStage)) return generationStage;

 const rawPipelineStage = itemValue(item, "pipeline_stage", "pipelineStage");
 const pipelineStage = normalizeStage(rawPipelineStage);
 if (rawPipelineStage && pipelineStage !== "waiting" && pipelineStage !== "unknown") {
 return pipelineStage;
 }
 return generationStage;
}

function derivePipelineItemPercent(item) {
 const stage = getItemStage(item);
 if (TERMINAL_ITEM_STAGES.has(stage)) return 100;
 if (stage === "toc_planning") return 8;
 if (stage === "translating_hy_mt2") {
 const chunkTotal = progressNumber(item, "chunk_count", "chunkCount");
 const chunkCompleted = Math.min(
 chunkTotal,
 progressNumber(item, "chunk_completed", "chunkCompleted"),
 );
 return chunkTotal
 ? Math.round(10 + ((chunkCompleted / chunkTotal) * 70))
 : 10;
 }
 if (stage === "integration_qc") return 88;
 if (stage === "medical_review") return 94;
 if (stage === "corpus_admission") return 97;
 if (stage === "chapter_mapping") return 99;
 if (stage === "extracting") return 3;
 if (stage === "ocr_running") return 5;
 if (stage === "validating") return 7;
 return 0;
}

export function getActiveStages(items) {
 const stageCounts = new Map();
 items.forEach((item) => {
 const stage = getItemStage(item);
 stageCounts.set(stage, (stageCounts.get(stage) || 0) + 1);
 });
 return stageCounts;
}

export function getNextAction(item) {
 const stage = normalizeStage(item.status || item.generation_status);
 const actions = {
 searching: "等待检索启动",
 screening: "等待筛选完成",
 downloading: "等待下载完成",
 parsing: "等待解析完成",
 extracting: "等待文本提取完成",
 ocr_running: "等待OCR识别完成",
 validating: "等待内容校验完成",
 prepared: "可进入翻译与语料审核",
 toc_planning: "等待目录识别完成",
 translating_hy_mt2: "等待翻译完成",
 integration_qc: "等待衔接核对完成",
 medical_review: "等待作者确认",
 corpus_admission: "等待确认后准入",
 chapter_mapping: "等待章节映射",
 candidate_ready: "可进入下一步",
 failed_retryable: "可重试失败项",
 failed_terminal: "需人工处理",
 fidelity_blocked: "需核对原文",
 excluded: "不在所选章节范围，无需生成",
 skipped: "不适用",
 waiting: "等待启动",
 unknown: "刷新状态或查看任务详情",
 };
 return actions[stage] || "处理中";
}

const BUSY_STAGES = new Set([
 "searching",
 "screening",
 "downloading",
 "parsing",
 "extracting",
 "ocr_running",
 "validating",
 "toc_planning",
 "translating_hy_mt2",
 "integration_qc",
 "medical_review",
 "corpus_admission",
 "chapter_mapping",
]);

export function isBusyStage(stage) {
 return BUSY_STAGES.has(normalizeStage(stage));
}

/**
 * Derive medical-user-facing document/chapter/chunk progress from batch items.
 * Does not expose hashes, model names, internal IDs, or raw logs.
 */
export function deriveDocumentTranslationProgress(items = []) {
 const list = Array.isArray(items) ? items : [];
 const byDocument = new Map();
 const byChapter = new Map();
 let blockerKind = "";
 let blockerMessage = "";

 const itemDocumentKey = (item, index) => String(
 itemValue(item, "artifact_id", "artifactId")
 || itemValue(item, "document_label", "documentLabel")
 || item?.filename
 || `document:${index}`,
 );
 const itemChapterKey = (item, index) => {
 const chapterId = itemValue(item, "chapter_id", "chapterId");
 const chapterIndex = progressNumber(item, "chapter_index", "chapterIndex");
 const chapterTitle = itemValue(item, "chapter_title", "chapterTitle");
 const chapterIdentity = chapterId || (chapterIndex || chapterTitle
 ? `${chapterIndex}:${chapterTitle || ""}`
 : `item:${index}`);
 return `${itemDocumentKey(item, index)}:${chapterIdentity}`;
 };

 list.forEach((item, index) => {
 const documentKey = itemDocumentKey(item, index);
 const label = itemValue(item, "document_label", "documentLabel")
 || item.filename
 || itemValue(item, "artifact_id", "artifactId")
 || "文档";
 const existingDocument = byDocument.get(documentKey);
 const document = {
 key: documentKey,
 label,
 index: progressNumber(item, "document_index", "documentIndex"),
 total: progressNumber(item, "document_total", "documentTotal"),
 };
 if (!existingDocument) {
 byDocument.set(documentKey, document);
 } else {
 byDocument.set(documentKey, {
 ...existingDocument,
 label: existingDocument.label || document.label,
 index: Math.max(existingDocument.index, document.index),
 total: Math.max(existingDocument.total, document.total),
 });
 }

 const chapterKey = itemChapterKey(item, index);
 const chapterProgress = {
 chunkTotal: progressNumber(item, "chunk_count", "chunkCount"),
 chunkCompleted: progressNumber(item, "chunk_completed", "chunkCompleted"),
 chunkRunning: progressNumber(item, "chunk_running", "chunkRunning"),
 chunkFailed: progressNumber(item, "chunk_failed", "chunkFailed"),
 chunkReused: progressNumber(item, "chunk_reused", "chunkReused"),
 };
 const existingChapter = byChapter.get(chapterKey);
 if (!existingChapter) {
 byChapter.set(chapterKey, chapterProgress);
 } else {
 byChapter.set(chapterKey, {
 chunkTotal: Math.max(existingChapter.chunkTotal, chapterProgress.chunkTotal),
 chunkCompleted: Math.max(existingChapter.chunkCompleted, chapterProgress.chunkCompleted),
 chunkRunning: Math.max(existingChapter.chunkRunning, chapterProgress.chunkRunning),
 chunkFailed: Math.max(existingChapter.chunkFailed, chapterProgress.chunkFailed),
 chunkReused: Math.max(existingChapter.chunkReused, chapterProgress.chunkReused),
 });
 }

 const stage = getItemStage(item);
 if (!blockerKind && item.blocker_kind) {
 blockerKind = String(item.blocker_kind);
 blockerMessage = String(item.blocker_message || "");
 } else if (!blockerKind && (stage === "failed_retryable" || stage === "failed_terminal" || stage === "fidelity_blocked")) {
 blockerKind = stage === "failed_retryable" ? "retryable" : "terminal";
 blockerMessage = getNextAction({ generation_status: stage });
 }
 });

 const busyItemIndex = list.findIndex((item) => isBusyStage(getItemStage(item)));
 const currentItemIndex = busyItemIndex >= 0
 ? busyItemIndex
 : list.reduce((selectedIndex, item, index) => {
 if (selectedIndex < 0) return index;
 const selectedDocumentIndex = progressNumber(
 list[selectedIndex],
 "document_index",
 "documentIndex",
 );
 const candidateDocumentIndex = progressNumber(item, "document_index", "documentIndex");
 return candidateDocumentIndex >= selectedDocumentIndex ? index : selectedIndex;
 }, -1);
 const currentItem = currentItemIndex >= 0 ? list[currentItemIndex] : null;
 const activeStage = currentItem ? getItemStage(currentItem) : "waiting";
 const activeStageDetail = String(
 itemValue(currentItem, "pipeline_stage_detail", "pipelineStageDetail")
 || getStageLabel(activeStage),
 );

 const documents = Array.from(byDocument.values()).sort(
 (a, b) => (a.index || 0) - (b.index || 0),
 );
 const currentDocumentKey = currentItem
 ? itemDocumentKey(currentItem, currentItemIndex)
 : "";
 const currentDocument = byDocument.get(currentDocumentKey) || null;
 const documentTotal = Math.max(
 documents.length,
 ...documents.map((document) => document.total || 0),
 );
 const chapterProgress = Array.from(byChapter.values()).reduce(
 (total, chapter) => ({
 chunkTotal: total.chunkTotal + chapter.chunkTotal,
 chunkCompleted: total.chunkCompleted + chapter.chunkCompleted,
 chunkRunning: total.chunkRunning + chapter.chunkRunning,
 chunkFailed: total.chunkFailed + chapter.chunkFailed,
 chunkReused: total.chunkReused + chapter.chunkReused,
 }),
 {
 chunkTotal: 0,
 chunkCompleted: 0,
 chunkRunning: 0,
 chunkFailed: 0,
 chunkReused: 0,
 },
 );
 const currentChunkTotal = progressNumber(currentItem, "chunk_count", "chunkCount");
 const currentChunkCompleted = Math.min(
 currentChunkTotal,
 progressNumber(currentItem, "chunk_completed", "chunkCompleted"),
 );
 const currentPipelineStage = currentItem
 ? itemValue(currentItem, "pipeline_stage", "pipelineStage")
 : "";
 let progressCompleted = currentChunkCompleted;
 let progressTotal = currentChunkTotal;
 if (!progressTotal && currentDocument?.total) {
 progressTotal = currentDocument.total;
 progressCompleted = Math.max(0, (currentDocument.index || 1) - 1);
 }
 if (!progressTotal && list.length) {
 progressTotal = list.length;
 progressCompleted = list.filter((item) => TERMINAL_ITEM_STAGES.has(getItemStage(item))).length;
 }
 const progressPercent = currentPipelineStage
 ? derivePipelineItemPercent(currentItem)
 : (
 progressTotal
 ? Math.round((Math.min(progressCompleted, progressTotal) / progressTotal) * 100)
 : 0
 );

 return {
 documentTotal,
 documentIndex: currentDocument?.index || (documents.length ? 1 : 0),
 documentLabel: currentDocument?.label || "",
 chapterTotal: progressNumber(currentItem, "chapter_total", "chapterTotal"),
 chapterIndex: progressNumber(currentItem, "chapter_index", "chapterIndex"),
 chapterTitle: itemValue(currentItem, "chapter_title", "chapterTitle") || "",
 ...chapterProgress,
 currentChunkTotal,
 currentChunkCompleted,
 currentChunkRunning: progressNumber(currentItem, "chunk_running", "chunkRunning"),
 currentChunkFailed: progressNumber(currentItem, "chunk_failed", "chunkFailed"),
 currentChunkReused: progressNumber(currentItem, "chunk_reused", "chunkReused"),
 activeStage,
 activeStageDetail,
 progressCompleted,
 progressTotal,
 progressPercent,
 blockerKind,
 blockerMessage,
 };
}

export function formatDocumentTranslationProgressSummary(progress) {
 if (!progress) return "";
 const parts = [];
 if (progress.documentTotal) {
 parts.push(
 `文档 ${progress.documentIndex || 0}/${progress.documentTotal}`
 + (progress.documentLabel ? `（${progress.documentLabel}）` : ""),
 );
 }
 if (progress.chapterTotal) {
 parts.push(
 `章节 ${progress.chapterIndex || 0}/${progress.chapterTotal}`
 + (progress.chapterTitle ? `（${progress.chapterTitle}）` : ""),
 );
 }
 if (progress.chunkTotal) {
 parts.push(
 `分块 完成${progress.chunkCompleted || 0}/运行${progress.chunkRunning || 0}/失败${progress.chunkFailed || 0}/复用${progress.chunkReused || 0}/共${progress.chunkTotal}`,
 );
 }
 if (progress.blockerKind) {
 const kindLabel = progress.blockerKind === "retryable" ? "可重试" : "需处理";
 parts.push(`阻断（${kindLabel}）${progress.blockerMessage ? `：${progress.blockerMessage}` : ""}`);
 }
 return parts.join(" · ");
}

