export const runtimeExpectation = Object.freeze(__WORKBENCH_RUNTIME_EXPECTATION__);

export function assessRuntimeReadiness(payload, { httpOk = true, httpStatus = 200 } = {}) {
 const reasons = [];
 if (!httpOk) {
 reasons.push(
 httpStatus > 0
 ? `运行环境检查未通过（HTTP ${httpStatus}），当前后端未提供兼容性合同`
 : "无法连接运行环境检查接口",
 );
 } else if (!payload || typeof payload !== "object") {
 reasons.push("未收到可识别的运行时准备信息");
 } else {
 if (payload.runtime_contract_schema !== runtimeExpectation.runtimeContractSchema) {
 reasons.push("运行时合同结构与当前前端不一致");
 }
 if (payload.api_contract_version !== runtimeExpectation.apiContractVersion) {
 reasons.push("前后端 API 合同版本不一致");
 }
 if (payload.backend_build_id !== runtimeExpectation.expectedBackendBuildId) {
 reasons.push("后端构建与当前前端构建不一致");
 }
 if (payload.ready !== true) {
 reasons.push("后端尚未满足医学写作必需能力");
 }
 if (Array.isArray(payload.missing_capabilities) && payload.missing_capabilities.length) {
 reasons.push(`缺少必需能力：${payload.missing_capabilities.join("、")}`);
 }
 }
 return {
 ready: reasons.length === 0,
 reasons: [...new Set(reasons)],
 payload: payload && typeof payload === "object" ? payload : null,
 };
}

export function installApiContractFetch(target = globalThis) {
 if (!target?.fetch || target.__workbenchContractFetchInstalled) return;
 const nativeFetch = target.fetch.bind(target);
 target.fetch = (input, init = {}) => {
 const rawUrl = typeof input === "string"
 ? input
 : input instanceof URL
 ? input.href
 : input?.url || "";
 const currentOrigin = target.location?.origin || "http://127.0.0.1";
 const resolved = new URL(rawUrl, currentOrigin);
 if (resolved.origin !== currentOrigin || !resolved.pathname.startsWith("/api/")) {
 return nativeFetch(input, init);
 }
 const requestHeaders = typeof Request !== "undefined" && input instanceof Request
 ? input.headers
 : undefined;
 const headers = new Headers(requestHeaders);
 new Headers(init.headers || {}).forEach((value, key) => headers.set(key, value));
 headers.set(runtimeExpectation.clientContractHeader, runtimeExpectation.apiContractVersion);
 headers.set("X-Workbench-Frontend-Build", runtimeExpectation.frontendBuildId);
 return nativeFetch(input, { ...init, headers });
 };
 target.__workbenchContractFetchInstalled = true;
}

:root {
 color: #20242a;
 background: #f6f7f9;
 font-family: Inter, "Noto Sans SC", "PingFang SC", "Microsoft YaHei", Arial, sans-serif;
 font-size: 14px;
 line-height: 1.45;
 --orange: #f37021;
 --orange-dark: #d95710;
 --text: #20242a;
 --muted: #65707c;
 --line: #dfe3e8;
 --soft-line: #edf0f3;
 --surface: #ffffff;
 --page: #f6f7f9;
 --info: #2f6fd6;
 --info-bg: #eef5ff;
 --warning: #b96b00;
 --warning-bg: #fff6e6;
 --danger: #c92a2a;
 --danger-bg: #fff0f0;
 --success: #1f7a42;
 --success-bg: #edf8f1;
}

* {
 box-sizing: border-box;
}

body {
 margin: 0;
 min-width: 0;
 min-height: 100vh;
 -webkit-font-smoothing: antialiased;
}

button,
input,
textarea {
 font: inherit;
}

button {
 cursor: pointer;
}

button:disabled {
 cursor: not-allowed;
 opacity: 0.5;
}

.app {
 min-height: 100vh;
 display: grid;
 grid-template-columns: 180px minmax(0, 1fr);
 background: var(--page);
}

.app.writing-active {
 grid-template-columns: 64px minmax(0, 1fr);
}

.app.writing-active .sidebar {
 position: relative;
 z-index: 40;
 width: 64px;
 overflow: hidden;
}

.app.writing-active .brand {
 width: 64px;
 padding: 0 8px;
 overflow: hidden;
 justify-content: flex-start;
}

.app.writing-active .brand img {
 width: 48px;
 height: 24px;
 object-fit: cover;
 object-position: left center;
 flex: 0 0 auto;
}

.app.writing-active .nav {
 width: 180px;
}

.app.writing-active .nav-item span,
.app.writing-active .sidebar-footer {
 opacity: 0;
 transition: opacity 100ms ease;
}

.sidebar {
 background: var(--surface);
 border-right: 1px solid var(--line);
 display: flex;
 flex-direction: column;
 min-height: 100vh;
}

.brand {
 height: 72px;
 border: 0;
 border-bottom: 1px solid var(--line);
 background: var(--surface);
 display: flex;
 align-items: center;
 padding: 0 18px;
}

.brand img {
 width: 137px;
 height: auto;
 display: block;
}

.nav {
 display: grid;
 gap: 4px;
 padding: 14px 10px;
}

.nav-item {
 border: 1px solid transparent;
 background: transparent;
 color: #35404a;
 min-height: 38px;
 display: flex;
 align-items: center;
 gap: 10px;
 padding: 0 10px;
 border-radius: 4px;
 text-align: left;
}

.nav-item:hover {
 background: #f3f5f7;
}

.nav-item.active {
 background: #fff4ed;
 color: var(--orange-dark);
 border-color: #ffd9c2;
 font-weight: 700;
}

.sidebar-footer {
 margin-top: auto;
 border-top: 1px solid var(--line);
 padding: 14px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 color: var(--muted);
 font-size: 12px;
}

.workspace {
