 gap: 2px;
}

.monitoring-batch-confirmation small {
 color: #73502c;
}

.monitoring-batch-confirmation textarea {
 min-height: 64px;
 resize: vertical;
}

.monitoring-batch-confirmation > button {
 justify-self: end;
}

.monitoring-batch-inline-note {
 color: #8c4a0f;
}

.monitoring-batch-message {
 display: flex;
 align-items: center;
 gap: 6px;
 color: var(--success);
}

.monitoring-batch-error {
 color: var(--danger);
}

.monitoring-batch-mapping-entry {
 border-left-color: var(--orange);
 background: #fffdfa;
}

.monitoring-protocol-prep-entry {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
 padding: 5px 9px;
 border: 1px solid #cfd9d3;
 background: #f8faf9;
 color: #385345;
 font-size: 12px;
 font-weight: 600;
 white-space: nowrap;
}

.monitoring-protocol-prep-entry:hover {
 border-color: #9db2a5;
 background: #f1f6f3;
}

.monitoring-protocol-prep-host {
 position: fixed;
 inset: 0;
 z-index: 64;
}

.monitoring-protocol-prep-backdrop {
 position: absolute;
 inset: 0;
 width: 100%;
 height: 100%;
 padding: 0;
 border: 0;
 border-radius: 0;
 background: rgba(28, 37, 45, 0.3);
}

.monitoring-protocol-prep-drawer {
 position: absolute;
 top: 0;
 right: 0;
 width: min(680px, 100vw);
 height: 100vh;
 display: grid;
 grid-template-rows: auto minmax(0, 1fr) auto;
 border-left: 1px solid var(--line);
 background: #fff;
 box-shadow: -14px 0 32px rgba(28, 37, 45, 0.16);
 overflow: hidden;
}

.monitoring-protocol-prep-head {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 14px;
 padding: 15px 16px 12px;
 border-bottom: 1px solid var(--line);
 background: #fbfcfd;
}

.monitoring-protocol-prep-head > div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.monitoring-protocol-prep-head span,
.monitoring-protocol-prep-head small {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.monitoring-protocol-prep-head strong {
 font-size: 16px;
}

.monitoring-protocol-prep-body {
 min-height: 0;
 padding: 12px 14px 18px;
 overflow: auto;
}

.monitoring-protocol-version-row {
 display: grid;
 grid-template-columns: 72px minmax(0, 1fr);
 align-items: center;
 gap: 10px;
 min-height: 42px;
 padding-bottom: 10px;
 border-bottom: 1px solid var(--soft-line);
}

.monitoring-protocol-version-row label {
 color: var(--muted);
 font-size: 11px;
}

.monitoring-protocol-version-row strong {
 overflow: hidden;
 color: var(--text-secondary);
 font-size: 12px;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.monitoring-protocol-version-row select {
 width: 100%;
 min-height: 34px;
 border: 1px solid var(--line);
 background: #fff;
}

.monitoring-protocol-version-row p {
 margin: 0;
 color: var(--muted);
 font-size: 12px;
}

.monitoring-protocol-prep-summary {
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 align-items: center;
 gap: 8px 12px;
 padding: 12px 0 10px;
}

.monitoring-protocol-prep-summary > div:first-child {
 display: grid;
 gap: 2px;
}

.monitoring-protocol-prep-summary > div:first-child span,
.monitoring-protocol-prep-summary > small {
 color: var(--muted);
 font-size: 11px;
}

.monitoring-protocol-prep-summary > div:first-child strong {
 font-size: 13px;
}

.monitoring-protocol-prep-actions {
 display: flex;
 align-items: center;
 gap: 7px;
}

.monitoring-protocol-prep-actions .primary-button {
 min-height: 32px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.monitoring-protocol-progress {
 grid-column: 1 / -1;
 height: 4px;
 background: #e9edef;
 overflow: hidden;
}

.monitoring-protocol-progress > i {
 display: block;
 height: 100%;
 background: linear-gradient(90deg, #d66f19 0%, #526e5d 100%);
 transition: width 180ms ease;
}

.monitoring-protocol-prep-summary > small {
 grid-column: 1 / -1;
}

.monitoring-protocol-loading {
 display: inline-flex;
 align-items: center;
 gap: 7px;
 margin: 12px 0;
 color: var(--muted);
 font-size: 12px;
}

.monitoring-protocol-loading svg,
.monitoring-protocol-prep-spinner {
 animation: monitoring-spin 900ms linear infinite;
}

.monitoring-protocol-prep-error {
 display: grid;
 grid-template-columns: auto minmax(0, 1fr) auto;
 align-items: center;
 gap: 8px;
 margin: 4px 0 10px;
 padding: 8px 10px;
 border-left: 3px solid var(--danger);
 background: #fff5f4;
 color: #9b352d;
 font-size: 12px;
}

.monitoring-protocol-prep-error button {
 border: 0;
 background: transparent;
 color: #8d2d25;
 font-weight: 600;
}

.monitoring-protocol-topic-list {
 border-top: 1px solid var(--line);
}

.monitoring-protocol-topic-list > details {
 border-bottom: 1px solid var(--line);
}

.monitoring-protocol-topic-list summary {
 min-height: 46px;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr) auto auto;
 align-items: center;
 gap: 8px;
 padding: 8px 4px;
 cursor: pointer;
 list-style: none;
}

.monitoring-protocol-topic-list summary::-webkit-details-marker {
 display: none;
}

.monitoring-protocol-topic-list summary:hover {
 background: #fafbfc;
}

.monitoring-protocol-topic-list summary strong {
 min-width: 0;
 font-size: 12px;
}

.monitoring-protocol-topic-list summary > span {
 color: var(--muted);
 font-size: 11px;
 white-space: nowrap;
}

.monitoring-protocol-topic-list summary em {
 min-width: 72px;
 padding: 2px 6px;
 border: 1px solid var(--line);
 border-radius: 3px;
 background: #f8fafb;
 color: var(--text-secondary);
 font-size: 11px;
 font-style: normal;
 text-align: center;
 white-space: nowrap;
}

.monitoring-protocol-topic-list summary em.success {
 border-color: #b8d9c2;
 background: var(--success-bg);
 color: var(--success);
}

.monitoring-protocol-topic-list summary em.warning {
 border-color: #f0c989;
 background: var(--warning-bg);
 color: #a4540a;
}

.monitoring-protocol-topic-list summary em.info {
 border-color: #c8d8ef;
 background: #f3f7fd;
 color: #315b97;
}

.monitoring-protocol-topic-list summary em.muted {
 color: var(--muted);
}

.monitoring-protocol-topic-list summary em.danger {
 border-color: #edc3bf;
 background: #fff5f4;
 color: #a1362e;
}

.monitoring-protocol-topic-detail {
 display: grid;
 gap: 10px;
 padding: 0 4px 14px 27px;
}

.monitoring-protocol-topic-detail > p {
 margin: 0;
 color: var(--muted);
 font-size: 12px;
 line-height: 1.55;
}

.monitoring-protocol-candidate {
 display: grid;
 gap: 10px;
 padding: 12px 0 2px;
 border-top: 1px solid var(--soft-line);
}

.monitoring-protocol-candidate > header > div {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
}

.monitoring-protocol-candidate > header strong {
 font-size: 12px;
}

.monitoring-protocol-candidate > header span {
 padding: 2px 6px;
 border: 1px solid #f0c989;
 border-radius: 3px;
 background: var(--warning-bg);
 color: #a4540a;
 font-size: 11px;
 white-space: nowrap;
}

.monitoring-protocol-candidate > header span.accepted {
 border-color: #b8d9c2;
 background: var(--success-bg);
 color: var(--success);
}

.monitoring-protocol-candidate > header span.rejected,
.monitoring-protocol-candidate > header span.superseded {
 border-color: #d7dde2;
 background: #f5f7f8;
 color: var(--muted);
}

.monitoring-protocol-confidence {
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 align-items: baseline;
 gap: 5px 8px;
 padding: 7px 9px;
 border-left: 3px solid #7d9586;
 background: #f6f9f7;
 color: #385345;
 font-size: 10px;
 line-height: 1.45;
}

.monitoring-protocol-confidence > span {
 color: var(--muted);
}

.monitoring-protocol-confidence.low {
 border-left-color: #c49047;
 background: #fffaf2;
 color: #765324;
}

.monitoring-protocol-confidence p {
 grid-column: 1 / -1;
 margin: 0;
 color: #765324;
}

.monitoring-protocol-candidate-text {
 display: grid;
 grid-template-columns: 76px minmax(0, 1fr);
 gap: 10px;
}

.monitoring-protocol-candidate-text > span,
.monitoring-protocol-structured-fields dt {
 color: var(--muted);
 font-size: 11px;
}

.monitoring-protocol-candidate-text p,
.monitoring-protocol-structured-fields p {
 margin: 0;
 color: var(--text-secondary);
 font-size: 12px;
 line-height: 1.6;
}

.monitoring-protocol-structured-fields {
 margin: 0;
 border-top: 1px solid var(--soft-line);
}

.monitoring-protocol-structured-fields > div {
 display: grid;
 grid-template-columns: 76px minmax(0, 1fr);
 gap: 10px;
 padding: 7px 0;
 border-bottom: 1px solid var(--soft-line);
}

.monitoring-protocol-structured-fields dd {
 display: grid;
 gap: 3px;
 margin: 0;
}

.monitoring-protocol-structured-fields dd p::before {
 content: "•";
 margin-right: 6px;
 color: #d66f19;
}

.monitoring-protocol-evidence {
 display: grid;
 gap: 7px;
}

.monitoring-protocol-evidence > strong {
 font-size: 11px;
}

.monitoring-protocol-evidence blockquote {
 display: grid;
 gap: 5px;
 margin: 0;
 padding: 8px 10px;
 border-left: 3px solid #a9b8af;
 background: #f8faf9;
}

.monitoring-protocol-evidence blockquote p {
 margin: 0;
 color: var(--text-secondary);
 font-size: 12px;
 line-height: 1.6;
}

.monitoring-protocol-evidence blockquote small {
 color: var(--muted);
 font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
 font-size: 10px;
 overflow-wrap: anywhere;
}

.monitoring-protocol-candidate-decision {
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 align-items: end;
 gap: 8px 10px;
 padding-top: 9px;
 border-top: 1px solid var(--soft-line);
}

.monitoring-protocol-candidate-decision > label,
.monitoring-protocol-rejection > label {
 display: grid;
 gap: 4px;
}

.monitoring-protocol-candidate-decision label > span,
.monitoring-protocol-rejection label > span {
 color: var(--muted);
 font-size: 10px;
}

.monitoring-protocol-candidate-decision select,
.monitoring-protocol-rejection input,
.monitoring-protocol-confidence-confirmation textarea {
 min-height: 32px;
 border: 1px solid var(--line);
 background: #fff;
 color: var(--text-secondary);
 font-size: 12px;
}

.monitoring-protocol-confidence-confirmation {
 grid-column: 1 / -1;
 display: grid;
 gap: 4px;
}

.monitoring-protocol-confidence-confirmation textarea {
 width: 100%;
 min-height: 52px;
 padding: 6px 8px;
 resize: vertical;
 line-height: 1.45;
}

.monitoring-protocol-candidate-actions {
 display: flex;
 align-items: center;
 justify-content: flex-end;
 gap: 7px;
}

.monitoring-protocol-candidate-actions button,
.monitoring-protocol-rejection button {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 5px;
 padding: 4px 9px;
 border: 1px solid var(--line);
 background: #fff;
 color: var(--text-secondary);
 font-size: 11px;
 font-weight: 600;
}

.monitoring-protocol-candidate-actions button:disabled,
.monitoring-protocol-rejection button:disabled {
 cursor: not-allowed;
 opacity: 0.55;
}

.monitoring-protocol-candidate-accept {
 border-color: #8fbe9e !important;
 background: var(--success-bg) !important;
 color: #25633b !important;
}

.monitoring-protocol-candidate-reject {
 color: #91362f !important;
}

.monitoring-protocol-rejection {
 grid-column: 1 / -1;
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 align-items: end;
 gap: 8px;
}

.monitoring-protocol-rejection > div {
 display: flex;
 gap: 7px;
}

.monitoring-protocol-candidate-error {
 grid-column: 1 / -1;
 margin: 0;
 color: var(--danger);
 font-size: 11px;
 line-height: 1.45;
}

.monitoring-protocol-prep-empty {
 min-height: 170px;
 display: grid;
 place-items: center;
 align-content: center;
 gap: 8px;
 color: var(--muted);
}

.monitoring-protocol-prep-empty p {
 margin: 0;
 font-size: 12px;
}

.monitoring-protocol-prep-foot {
 padding: 9px 14px;
 border-top: 1px solid var(--line);
 background: #fbfcfd;
}

.monitoring-protocol-prep-foot span {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.monitoring-daily-run {
 display: grid;
 gap: 10px;
 padding: 11px 12px;
 border: 1px solid #d7dde2;
 border-left: 3px solid #526e5d;
 background: #fff;
}

.monitoring-daily-run-head,
.monitoring-daily-run-action {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 14px;
}

.monitoring-daily-run-head > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.monitoring-daily-run-head span,
.monitoring-daily-run-action > span {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.monitoring-daily-run-steps {
 display: grid;
 grid-template-columns: repeat(5, minmax(110px, 1fr));
 gap: 0;
 margin: 0;
 padding: 0;
 list-style: none;
 border: 1px solid var(--line);
 background: #fafbfc;
}

.monitoring-daily-run-steps > li {
 position: relative;
 min-height: 38px;
 display: flex;
 align-items: center;
 gap: 7px;
 padding: 7px 10px;
 border-right: 1px solid var(--soft-line);
 color: #7a838d;
 font-size: 12px;
 white-space: nowrap;
}

.monitoring-daily-run-steps > li:last-child {
 border-right: 0;
}

.monitoring-daily-run-steps > li.completed {
 color: var(--success);
 background: #f7fbf8;
}

.monitoring-daily-run-steps > li.active {
 color: #8f4309;
 background: #fff8f2;
 box-shadow: inset 0 -2px 0 var(--orange);
 font-weight: 700;
}

.monitoring-daily-run-attention {
 display: flex;
 align-items: flex-start;
 gap: 7px;
 padding: 8px 9px;
 border: 1px solid #efcf9b;
 background: #fff9ef;
 color: #8c4a0f;
 font-size: 12px;
 line-height: 1.5;
}

.monitoring-daily-run-attention svg {
 flex: 0 0 auto;
 margin-top: 1px;
}

.monitoring-daily-run-action {
 min-height: 34px;
 padding-top: 2px;
}

.monitoring-daily-run-action .primary-button {
 min-width: 150px;
 justify-content: center;
}

.monitoring-daily-run-error {
 margin: 0;
 color: var(--danger);
 font-size: 12px;
 line-height: 1.5;
}

.monitoring-daily-run .is-spinning {
 animation: monitoring-spin 900ms linear infinite;
}

@keyframes monitoring-spin {
 to {
 transform: rotate(360deg);
 }
}

.monitoring-mapping-panel {
 display: grid;
 gap: 10px;
 border: 1px solid #d9dee3;
 background: #fff;
}

.monitoring-mapping-head,
.monitoring-mapping-progress,
.monitoring-mapping-review,
.monitoring-mapping-start,
.monitoring-mapping-confirm {
 display: flex;
 align-items: center;
 gap: 12px;
}

.monitoring-mapping-head {
 justify-content: space-between;
 min-height: 52px;
 padding: 8px 10px;
 border-bottom: 1px solid var(--soft-line);
}

.monitoring-mapping-head > div:first-child {
 min-width: 0;
 display: grid;
 gap: 1px;
}

.monitoring-mapping-head span,
.monitoring-mapping-head small,
.monitoring-mapping-start span,
.monitoring-mapping-progress > span,
.monitoring-mapping-review span {
 color: var(--muted);
 font-size: 11px;
}

.monitoring-mapping-head strong {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.monitoring-mapping-start {
 min-height: 76px;
 padding: 10px 12px;
}

.monitoring-mapping-start > svg {
 flex: 0 0 auto;
 color: var(--orange-dark);
}

.monitoring-mapping-start > div,
.monitoring-mapping-review > div {
 min-width: 0;
 flex: 1;
 display: grid;
 gap: 3px;
}

.monitoring-mapping-progress {
 min-height: 42px;
 padding: 6px 10px;
 background: #fafbfc;
 border-bottom: 1px solid var(--soft-line);
}

.monitoring-mapping-progress > div:first-child {
 min-width: 230px;
 display: flex;
 align-items: center;
 gap: 7px;
}

.monitoring-mapping-progress > span {
 flex: 1;
}

.monitoring-mapping-review {
 justify-content: space-between;
 padding: 10px 12px;
}

.monitoring-mapping-review .primary-button {
 display: inline-flex;
 align-items: center;
 gap: 5px;
}

.monitoring-mapping-editor {
 position: relative;
 display: grid;
 min-height: 420px;
}

.monitoring-mapping-toolbar {
 display: grid;
 grid-template-columns: 150px 150px minmax(240px, 1fr) auto;
 align-items: center;
 gap: 8px;
 padding: 8px 10px;
 border-bottom: 1px solid var(--soft-line);
}

.monitoring-mapping-toolbar select,
.monitoring-mapping-toolbar input,
.monitoring-mapping-field-editor input,
.monitoring-mapping-field-editor select,
.monitoring-mapping-field-editor textarea,
.monitoring-mapping-confirm input {
 width: 100%;
 min-height: 34px;
 border: 1px solid var(--line);
 border-radius: 3px;
 background: #fff;
 color: var(--text);
 padding: 6px 8px;
}

.monitoring-mapping-toolbar > span {
 color: var(--muted);
 font-size: 11px;
 white-space: nowrap;
}

.monitoring-mapping-table {
 max-height: 440px;
 overflow: auto;
}

.monitoring-mapping-row {
 width: 100%;
 min-height: 38px;
 display: grid;
 grid-template-columns: minmax(150px, 1fr) minmax(220px, 1.35fr) minmax(130px, 0.8fr) 72px 24px;
 align-items: center;
 gap: 10px;
 padding: 5px 10px;
 border: 0;
 border-bottom: 1px solid var(--soft-line);
 background: #fff;
 color: var(--text);
 text-align: left;
}

.monitoring-mapping-row:not(.header):hover,
.monitoring-mapping-row.active {
 background: #fff8f2;
}

.monitoring-mapping-row.header {
 position: sticky;
 z-index: 2;
 top: 0;
 min-height: 32px;
 background: #f7f8fa;
 color: var(--muted);
 font-size: 11px;
 font-weight: 600;
}

.monitoring-mapping-row > span {
 min-width: 0;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.monitoring-mapping-row > span:first-child {
 display: flex;
 align-items: center;
 gap: 7px;
}

.monitoring-mapping-row > span:first-child b {
 min-width: 34px;
 color: #8a4a16;
 font-size: 10px;
}

.monitoring-mapping-row .low {
 color: var(--warning);
 font-weight: 700;
}

.monitoring-mapping-field-editor {
 position: absolute;
 z-index: 5;
 top: 49px;
 right: 0;
 bottom: 58px;
 width: min(420px, 44%);
 display: grid;
 align-content: start;
 gap: 10px;
 padding: 12px;
 border-left: 1px solid #d9dee3;
 background: #fff;
 box-shadow: -10px 0 24px rgba(32, 36, 42, 0.1);
 overflow-y: auto;
}

.monitoring-mapping-field-editor > div:first-child {
 display: flex;
 align-items: center;
 justify-content: space-between;
}

.monitoring-mapping-field-editor label {
 display: grid;
 gap: 4px;
 color: var(--text-secondary);
 font-size: 11px;
}

.monitoring-mapping-field-editor textarea {
 resize: vertical;
}

.monitoring-mapping-evidence,
.monitoring-mapping-lineage {
 min-width: 0;
 display: grid;
 gap: 6px;
 margin: 0;
 padding: 9px;
 border: 1px solid var(--soft-line);
 border-radius: 3px;
 background: #fafbfc;
}

.monitoring-mapping-evidence > div,
.monitoring-mapping-evidence > span,
.monitoring-mapping-evidence > small {
 min-width: 0;
 overflow-wrap: anywhere;
}

.monitoring-mapping-evidence > div {
 display: grid;
 gap: 2px;
}

.monitoring-mapping-evidence small {
 color: var(--muted);
 font-size: 10px;
}

.monitoring-mapping-lineage {
 grid-template-columns: 1fr;
}

.monitoring-mapping-lineage legend {
 padding: 0 4px;
 color: var(--text-secondary);
 font-size: 11px;
 font-weight: 700;
}

.monitoring-mapping-field-editor > .primary-button {
 justify-self: end;
}

.monitoring-mapping-confirm {
 min-height: 56px;
 padding: 8px 10px;
 border-top: 1px solid var(--line);
 background: #fafbfc;
}

.monitoring-mapping-confirm label {
 min-width: 0;
 flex: 1;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 align-items: center;
 gap: 8px;
}

.monitoring-mapping-confirm label > span {
 color: var(--muted);
 font-size: 11px;
}

.monitoring-mapping-change-summary {
 min-width: 128px;
 display: grid;
 gap: 1px;
}

.monitoring-mapping-change-summary span {
 color: var(--muted);
 font-size: 10px;
}

.monitoring-mapping-quality-summary {
 min-width: 220px;
 max-width: 420px;
 display: grid;
 gap: 1px;
 padding-left: 8px;
 border-left: 3px solid var(--success);
}

.monitoring-mapping-quality-summary strong {
 font-size: 11px;
}

.monitoring-mapping-quality-summary span {
 color: var(--muted);
 font-size: 10px;
 line-height: 1.35;
}

.monitoring-mapping-quality-summary.blocked {
 border-left-color: var(--danger);
}

.monitoring-mapping-quality-summary.restricted,
.monitoring-mapping-quality-summary.warning {
 border-left-color: var(--warning);
}

.monitoring-mapping-message,
.monitoring-mapping-error,
.monitoring-mapping-success {
 margin: 0;
 padding: 0 10px 9px;
 font-size: 12px;
 line-height: 1.5;
}

.monitoring-mapping-message,
.monitoring-mapping-success {
 color: var(--success);
}

.monitoring-mapping-success {
 display: flex;
 align-items: center;
 gap: 6px;
}

.monitoring-mapping-error {
 color: var(--danger);
}

.monitoring-mapping-error:has(.text-button) {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
}

.gate-steps {
 display: grid;
 grid-template-columns: repeat(4, minmax(120px, 1fr));
 gap: 8px;
 margin-bottom: 12px;
}

.gate-steps > div {
 min-height: 40px;
 border: 1px solid var(--line);
 border-radius: 4px;
 display: flex;
 align-items: center;
 gap: 8px;
 padding: 0 10px;
 color: var(--muted);
 background: #fbfcfd;
}

.gate-steps > div.done {
 border-color: #bfe4c9;
 color: var(--success);
 background: var(--success-bg);
}

.upload-grid {
 display: grid;
 grid-template-columns: minmax(240px, 0.8fr) minmax(360px, 1fr) minmax(320px, 0.9fr);
 gap: 12px;
}

.content-confirmation {
 border: 1px solid #f0c989;
 border-left: 3px solid #ea580c;
 border-radius: 4px;
 background: #fffaf3;
 padding: 10px 12px;
 display: grid;
 gap: 8px;
 font-size: 12px;
 grid-column: 1 / -1;
}

.content-confirmation-head {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
 min-height: 24px;
}

.content-confirmation-head strong {
 margin-right: auto;
}

.content-confirmation p,
.content-confirmation small {
 margin: 0;
 color: #5a3a1a;
 line-height: 1.45;
}

.content-confirmation-checks {
 display: grid;
 gap: 4px;
}

.content-confirmation-checks > div {
 display: grid;
 grid-template-columns: 96px 56px minmax(0, 1fr);
 gap: 8px;
 align-items: start;
 padding-top: 4px;
 border-top: 1px solid #f3e2c4;
 color: #4a3015;
}

.content-confirmation-checks b {
 font-size: 11px;
 color: #9a3412;
}

.content-confirmation-checks small {
 min-width: 0;
 max-height: 42px;
 overflow: auto;
 overflow-wrap: anywhere;
 word-break: break-word;
 color: var(--muted);
}

.content-confirmation-override {
 border-top: 1px solid #f3e2c4;
 padding-top: 8px;
 display: grid;
 gap: 7px;
}

.content-confirmation-override textarea {
 min-height: 64px;
 resize: vertical;
 width: 100%;
}

.content-confirmation-override-warning {
 display: flex;
 align-items: flex-start;
 gap: 6px;
 color: #9a3412;
 font-size: 11px;
 line-height: 1.45;
}

.content-confirmation-override-warning svg {
 flex: 0 0 auto;
 margin-top: 1px;
}

.content-confirmation-override fieldset {
 min-width: 0;
 margin: 0;
 padding: 8px;
 border: 1px solid #fed7aa;
 border-radius: 4px;
 display: grid;
 gap: 6px;
 background: #fff;
}

.content-confirmation-override legend {
 padding: 0 4px;
 color: var(--muted);
 font-size: 11px;
}

.content-confirmation-override-check {
 display: grid;
 grid-template-columns: 16px minmax(0, 1fr);
 align-items: start;
 gap: 7px;
 cursor: pointer;
}

.content-confirmation-override-check input {
 margin: 2px 0 0;
}

.content-confirmation-override-check span,
.content-confirmation-override-check small {
 min-width: 0;
 display: block;
}

.content-confirmation-override-check small {
 margin-top: 2px;
 overflow-wrap: anywhere;
 color: var(--muted);
 line-height: 1.4;
}

.content-confirmation-record {
 display: grid;
 grid-template-columns: max-content minmax(0, 1fr);
 align-items: start;
 gap: 8px;
 padding: 8px;
 border: 1px solid #bfdbfe;
 border-radius: 4px;
 background: #eff6ff;
}

.content-confirmation-record p {
 min-width: 0;
 margin: 0;
 overflow-wrap: anywhere;
 font-size: 11px;
 line-height: 1.45;
}

.content-confirmation-record strong {
 display: block;
 margin-bottom: 2px;
}

@media (max-width: 1100px) {
 .upload-grid {
 grid-template-columns: minmax(0, 1fr);
 }
}

.drop-zone {
 min-height: 170px;
 border: 1px dashed #b6c0cb;
 border-radius: 4px;
 display: grid;
 place-items: center;
 align-content: center;
 gap: 8px;
 padding: 16px;
 text-align: center;
 color: var(--muted);
 background: #fbfcfd;
}

.drop-zone input {
 display: none;
}

.drop-zone strong {
 color: var(--text);
}

.mapping-table {
 border: 1px solid var(--line);
 border-radius: 4px;
 overflow: hidden;
}

.mapping-table > div {
 min-height: 36px;
 display: grid;
 grid-template-columns: 1fr 1fr auto;
 gap: 8px;
 align-items: center;
 padding: 6px 10px;
 border-bottom: 1px solid var(--soft-line);
}

.mapping-table > div:first-child {
 background: #fbfcfd;
}

.mapping-table > div:last-child {
 border-bottom: 0;
}

.diff-summary {
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 12px;
 display: grid;
 align-content: start;
 gap: 8px;
 background: #fbfcfd;
}

.diff-summary p {
 margin: 0;
 color: var(--muted);
}

.gate-result {
 color: var(--success) !important;
}

.gate-error {
 color: var(--danger) !important;
}

.upload-status {
 color: var(--info) !important;
}

.filter-strip button,
.editor-toolbar button,
.button-row button,
.button-grid button,
.segmented button {
 min-height: 30px;
 border: 1px solid var(--line);
 background: var(--surface);
 border-radius: 4px;
 padding: 0 9px;
 display: inline-flex;
 align-items: center;
 gap: 5px;
}

.monitoring-layout {
 display: grid;
 grid-template-columns: minmax(360px, 0.72fr) minmax(620px, 1.12fr);
 gap: 12px;
 align-items: start;
}

.monitoring-layout.unified-risk-layout {
 display: grid;
 grid-template-columns: minmax(0, 1fr);
}

.unified-risk-ledger {
 min-width: 0;
}

.risk-scope-switch {
 display: inline-flex;
 align-items: center;
 border: 1px solid var(--line);
 border-radius: 4px;
 overflow: hidden;
 background: #fff;
}

.risk-scope-switch button {
 min-height: 30px;
 padding: 0 12px;
 border: 0;
 border-right: 1px solid var(--line);
 background: #fff;
 color: var(--muted);
}

.risk-scope-switch button:last-child {
 border-right: 0;
}

.risk-scope-switch button.active {
 background: #fff3eb;
 color: var(--brand);
 font-weight: 800;
}

.risk-checklist-table {
 width: 100%;
 overflow-x: auto;
 background: #fff;
}

.risk-checklist-column-state {
 min-height: 34px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
 padding: 4px 10px;
 border-bottom: 1px solid var(--soft-line);
 color: var(--muted);
 font-size: 11px;
}

.risk-checklist-actions {
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.risk-checklist-actions .icon-button {
 width: 34px;
 min-width: 34px;
 height: 34px;
}

.risk-checklist-header,
.risk-checklist-row {
 min-width: 1120px;
 display: grid;
 grid-template-columns: 118px 92px 94px 188px minmax(320px, 1fr) 152px 156px;
 align-items: stretch;
}

.risk-checklist-header {
 min-height: 38px;
 position: sticky;
 top: 0;
 z-index: 2;
 background: #f7f9fb;
 border-bottom: 1px solid var(--line);
 color: #59636e;
 font-size: 11px;
 font-weight: 800;
}

.risk-checklist-header-cell {
 min-width: 0;
 position: relative;
 display: grid;
 grid-template-columns: minmax(0, 1fr) 30px;
 align-items: stretch;
 border-right: 1px solid var(--soft-line);
}

.risk-checklist-sort,
.risk-checklist-filter-trigger {
 min-width: 0;
 border: 0;
 background: transparent;
 color: inherit;
 display: flex;
 align-items: center;
 font: inherit;
}

.risk-checklist-sort {
 padding: 0 4px 0 9px;
 justify-content: space-between;
 gap: 5px;
 text-align: left;
}

.risk-checklist-filter-trigger {
 justify-content: center;
 padding: 0;
}

.risk-checklist-sort:hover,
.risk-checklist-sort.active,
.risk-checklist-filter-trigger:hover,
.risk-checklist-filter-trigger.active {
 background: #eef2f6;
 color: var(--text);
}

.risk-checklist-sort:disabled {
 cursor: default;
 opacity: 1;
}

.risk-checklist-sort:disabled svg {
 display: none;
}

.risk-checklist-filter-trigger.active {
 color: var(--brand);
}

.risk-checklist-filter-popover {
 width: 258px;
 position: absolute;
 z-index: 8;
 top: calc(100% + 4px);
 left: 6px;
 padding: 10px;
 border: 1px solid var(--line);
 border-radius: 6px;
 background: #fff;
 box-shadow: 0 10px 24px rgba(35, 42, 50, 0.14);
 display: grid;
 gap: 8px;
 color: var(--text);
 font-size: 12px;
 font-weight: 500;
}

.risk-checklist-header-cell:nth-child(n + 6) .risk-checklist-filter-popover {
 right: 6px;
 left: auto;
}

.risk-checklist-filter-popover > strong {
 font-size: 12px;
}

.risk-checklist-filter-popover input,
.risk-checklist-filter-popover select {
 width: 100%;
 min-width: 0;
 height: 32px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
 padding: 0 8px;
 font-size: 12px;
}

.risk-checklist-filter-popover > div {
 display: flex;
 justify-content: flex-end;
 gap: 6px;
}

.risk-checklist-filter-popover > div button {
 min-height: 28px;
 padding: 0 10px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
}

.risk-checklist-filter-popover > div button.primary {
 border-color: var(--brand);
 background: var(--brand);
 color: #fff;
}

.risk-checklist-filter-chips {
 min-height: 38px;
 padding: 5px 10px;
 border-bottom: 1px solid var(--soft-line);
 display: flex;
 align-items: center;
 gap: 6px;
 flex-wrap: wrap;
 background: #fbfcfd;
}

.risk-checklist-filter-chips button {
 min-height: 26px;
 max-width: 260px;
 padding: 0 7px;
 border: 1px solid #d9dee4;
 border-radius: 4px;
 background: #fff;
 color: var(--muted);
 display: inline-flex;
 align-items: center;
 gap: 5px;
 font-size: 11px;
}

.risk-checklist-filter-chips button strong {
 min-width: 0;
 overflow: hidden;
 text-overflow: ellipsis;
 color: var(--text);
}

.risk-checklist-filter-chips button.clear-all {
 color: var(--brand);
 border-color: transparent;
 background: transparent;
}

.risk-checklist-stale,
.risk-checklist-error {
 min-height: 36px;
 padding: 7px 10px;
 border-bottom: 1px solid var(--soft-line);
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
 font-size: 12px;
}

.risk-checklist-stale {
 color: #7b541f;
 background: #fffaf1;
}

.risk-checklist-stale button {
 min-height: 26px;
 padding: 0 8px;
 border: 1px solid #e7c98d;
 border-radius: 4px;
 background: #fff;
 color: #7b541f;
 display: inline-flex;
 align-items: center;
 gap: 5px;
}

.risk-checklist-error {
 color: var(--danger);
 background: var(--danger-bg);
}

.risk-checklist-error button {
 min-height: 26px;
 padding: 0 8px;
 border: 1px solid #e2b6b6;
 border-radius: 4px;
 background: #fff;
 color: var(--danger);
 display: inline-flex;
 align-items: center;
 gap: 5px;
 white-space: nowrap;
}

.risk-checklist-row > span {
 min-width: 0;
 padding: 8px;
 border-right: 1px solid var(--soft-line);
 display: flex;
 align-items: center;
 gap: 4px;
 overflow-wrap: anywhere;
}

.risk-checklist-row {
 min-height: 52px;
 border-bottom: 1px solid var(--soft-line);
 color: var(--text);
 font-size: 12px;
 cursor: pointer;
}

.risk-checklist-row:hover,
.risk-checklist-row.selected {
 background: #fff8f3;
}

.risk-checklist-row:focus-visible {
 outline: 2px solid var(--brand);
 outline-offset: -2px;
}

.risk-category-cell,
.risk-title-cell {
 align-content: center;
 align-items: flex-start !important;
}

.risk-category-cell {
 flex-wrap: wrap;
}

.risk-checklist-row .tag {
 max-width: 100%;
}

.risk-title-cell strong {
 line-height: 1.45;
}

.risk-unread-dot {
 width: 6px;
 height: 6px;
 flex: none;
 margin-top: 5px;
 border-radius: 50%;
 background: #d66f19;
}

.risk-checklist-row.skeleton {
 cursor: default;
}

.risk-checklist-row.skeleton > span i {
 width: 70%;
 height: 10px;
 border-radius: 3px;
 background: #edf0f3;
}

.risk-checklist-pagination {
 min-height: 40px;
 padding: 5px 10px;
 border-top: 1px solid var(--soft-line);
 display: flex;
 align-items: center;
 justify-content: flex-end;
 gap: 8px;
 color: var(--muted);
 font-size: 11px;
 background: #fbfcfd;
}

.risk-checklist-pagination label {
 display: inline-flex;
 align-items: center;
 gap: 4px;
}

.risk-checklist-pagination select {
 height: 28px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
}

.risk-index-error {
 padding: 8px 12px;
 margin: 0;
 border-bottom: 1px solid var(--soft-line);
}

.monitoring-empty-snapshot,
.monitoring-run-message {
 margin: 0;
 padding: 9px 12px;
 border-bottom: 1px solid var(--soft-line);
 background: #fff;
 color: var(--muted);
 font-size: 13px;
}

.monitoring-empty-snapshot {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
}

.monitoring-empty-snapshot button {
 min-height: 30px;
 padding: 0 12px;
 border: 1px solid #d88343;
 border-radius: 4px;
 background: #fff8f2;
 color: #9b4b18;
 font-weight: 600;
}

.monitoring-run-message {
 color: #376b4b;
 background: #f5faf7;
}

.risk-evidence-dock {
 position: fixed;
 right: 18px;
 bottom: 18px;
 z-index: 40;
 width: min(1320px, calc(100vw - 230px));
 height: min(560px, calc(100vh - 130px));
 min-height: 360px;
 resize: vertical;
 overflow: hidden;
 display: grid;
 grid-template-rows: auto auto minmax(0, 1fr);
 border: 1px solid #efb58f;
 border-radius: 6px;
 background: #fff;
 box-shadow: 0 18px 50px rgba(45, 52, 60, 0.2);
}

.risk-evidence-dock-head {
 min-height: 48px;
 padding: 8px 12px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 border-bottom: 1px solid var(--line);
 background: #fffaf6;
}

.risk-evidence-dock-head > div {
 min-width: 0;
 display: flex;
 align-items: center;
 gap: 8px;
}

.risk-evidence-dock-head strong {
 min-width: 0;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.risk-evidence-dock-head span:last-child {
 color: var(--muted);
 font-size: 12px;
 white-space: nowrap;
}

.risk-evidence-shape-warning {
 flex: 0 0 auto;
 color: var(--danger) !important;
 font-size: 11px !important;
 font-weight: 700;
 white-space: nowrap;
}

.risk-evidence-tabs {
 min-height: 38px;
 padding: 0 10px;
 display: flex;
 align-items: end;
 gap: 2px;
 border-bottom: 1px solid var(--line);
 background: #f8f9fa;
}

.risk-evidence-tabs button {
 min-height: 36px;
 padding: 0 12px;
 border: 0;
 border-bottom: 2px solid transparent;
 background: transparent;
 color: var(--muted);
}

.risk-evidence-tabs button.active {
 border-bottom-color: var(--brand);
 color: var(--brand);
 font-weight: 800;
}

.risk-evidence-dock-body {
 min-height: 0;
 overflow: auto;
 padding: 12px;
}

.risk-detail-embedded {
 min-height: 0;
 border: 0;
}

.risk-dock-evidence-view {
 display: grid;
 gap: 12px;
}

.risk-dock-view-head {
 display: flex;
 justify-content: space-between;
 align-items: center;
 gap: 12px;
}

.risk-dock-view-head > div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.risk-dock-view-head span {
 color: var(--muted);
 font-size: 12px;
}

.risk-dock-event-list {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 6px 12px;
}

.risk-dock-event-list > div {
 min-width: 0;
 min-height: 38px;
 display: grid;
 grid-template-columns: 92px 92px minmax(0, 1fr);
 align-items: center;
 gap: 7px;
 padding: 6px 8px;
 border-bottom: 1px solid var(--soft-line);
 font-size: 12px;
}

.risk-dock-event-list > div span:last-child {
 min-width: 0;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.risk-dock-metric-grid {
 display: grid;
 grid-template-columns: repeat(4, minmax(0, 1fr));
 gap: 8px;
}

.risk-dock-metric-grid > div {
 min-width: 0;
 padding: 9px;
 display: grid;
 gap: 5px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
}

.risk-dock-metric-grid > div > span {
 color: var(--muted);
 font-size: 12px;
}

.embedded-risk-timeline .reference-timeline-svg {
 min-width: 1120px;
}

.risk-focus-summary {
 display: grid;
 gap: 6px;
 border: 1px solid #efb58f;
 border-radius: 4px;
 background: #fffaf6;
 padding: 10px;
}

.risk-focus-event.reference-svg-event-block {
 stroke: #e66b20;
 stroke-width: 4;
 filter: drop-shadow(0 0 3px rgba(230, 107, 32, 0.48));
}

.timeline-detail-row.risk-focus-event {
 border: 2px solid #e66b20;
 border-left-width: 5px;
 border-radius: 4px;
 background: #fff5ed;
}

.chart-point.risk-focus-point {
 fill: #fff;
 stroke: #e66b20;
 stroke-width: 4;
 filter: drop-shadow(0 0 3px rgba(230, 107, 32, 0.45));
}

.metric-point-list > div.risk-focus-point {
 border: 2px solid #e66b20;
 border-radius: 4px;
 background: #fff5ed;
 padding: 6px 8px;
}

.risk-source-groups {
 display: grid;
 gap: 10px;
}

.risk-source-groups > section {
 min-width: 0;
 display: grid;
 align-content: start;
 gap: 7px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fbfcfd;
 padding: 10px;
}

.risk-evidence-sequence {
 display: grid;
 gap: 9px;
}

.risk-evidence-stage {
 min-width: 0;
 display: grid;
 gap: 7px;
 border: 1px solid var(--line);
 border-radius: 6px;
 background: #fbfcfd;
 padding: 10px;
}

.risk-evidence-stage.fact { border-left: 4px solid #4f91a7; }
.risk-evidence-stage.protocol { border-left: 4px solid #7d8fb0; }
.risk-evidence-stage.rule { border-left: 4px solid #b1864d; }
.risk-evidence-stage.locator { border-left: 4px solid #aebbc2; background: #f8fafb; }

.risk-evidence-stage > header {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.risk-evidence-stage > header strong {
 color: var(--text);
 font-size: 13px;
}

.risk-evidence-stage > header span,
.risk-evidence-missing,
.risk-evidence-more {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.5;
}

.risk-evidence-missing,
.risk-evidence-more {
 margin: 0;
}

.risk-evidence-more {
 color: #55788a;
}

.risk-evidence-rule-copy {
 display: grid;
 gap: 4px;
 border: 1px solid #eadfcf;
 border-radius: 4px;
 background: #fffaf1;
 padding: 8px 9px;
}

.risk-evidence-rule-copy > span {
 color: #8b641b;
 font-size: 11px;
 font-weight: 700;
}

.risk-evidence-rule-copy p,
.risk-evidence-rule-copy em {
 margin: 0;
 color: var(--text);
 font-size: 12px;
 line-height: 1.55;
 font-style: normal;
 overflow-wrap: anywhere;
}

.risk-evidence-rule-copy em {
 color: #7a6a58;
 font-size: 11px;
}

.risk-evidence-sequence.compact .risk-evidence-stage {
 padding: 8px;
}

.risk-evidence-sequence.compact .risk-evidence-stage > header span {
 font-size: 10px;
}

.risk-source-reference-actions {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 justify-content: flex-end;
 flex-wrap: wrap;
 gap: 8px;
}

.risk-source-locator,
.source-fragment-locator {
 min-width: 0;
 color: var(--muted);
 font-size: 11px;
}

.risk-source-locator summary,
.source-fragment-locator summary {
 cursor: pointer;
 color: #55788a;
 font-size: 11px;
 user-select: none;
}

.risk-source-locator code,
.source-fragment-locator code {
 display: block;
 max-width: 100%;
 margin-top: 5px;
 color: var(--muted);
 font-size: 11px;
 white-space: normal;
 overflow-wrap: anywhere;
}

.risk-source-reference {
 min-width: 0;
 display: grid;
 gap: 7px;
 padding-top: 7px;
 border-top: 1px solid var(--soft-line);
}

.risk-source-primary {
 min-width: 0;
 display: grid;
 gap: 4px;
}

.risk-source-primary span {
 min-width: 0;
 color: var(--text);
 font-weight: 600;
 line-height: 1.55;
 overflow-wrap: anywhere;
}

.risk-source-primary em {
 min-width: 0;
 color: var(--text-secondary);
 font-size: 12px;
 font-style: normal;
 line-height: 1.45;
 overflow-wrap: anywhere;
}

.risk-source-reference footer {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 8px;
}

.source-fragment-panel {
 min-width: 0;
 display: grid;
 gap: 10px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 padding: 12px;
}

.source-fragment-head {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 16px;
}

.source-fragment-head > div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.source-fragment-head strong,
.source-fragment-head span,
.source-fragment-panel > code {
 overflow-wrap: anywhere;
}

.source-fragment-head span,
.source-fragment-context > span,
.source-fragment-panel > code {
 color: var(--muted);
 font-size: 12px;
}

.source-fragment-lineage {
 min-width: 0;
