}

.source-fragment-context p {
 min-width: 0;
 grid-column: 2;
 margin: 0;
 color: var(--text-secondary);
 line-height: 1.55;
 overflow-wrap: anywhere;
}

.source-fragment-fields {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 column-gap: 20px;
}

.source-fragment-fields > div {
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(120px, 0.4fr) minmax(0, 1fr);
 gap: 10px;
 border-bottom: 1px solid var(--soft-line);
 padding: 7px 0;
}

.source-fragment-fields span,
.source-fragment-fields strong {
 min-width: 0;
 overflow-wrap: anywhere;
}

.source-fragment-fields span {
