 display: grid;
 grid-template-columns: 140px 110px minmax(170px, 0.8fr) minmax(210px, 1fr) 170px minmax(190px, 0.9fr);
 align-items: center;
 background: #fff;
}

.risk-history-entry {
 border-bottom: 1px solid var(--soft-line);
 background: #fff;
}

.risk-history-entry:last-child {
