 background: #fffaf6;
}

.risk-history-entry.current .risk-history-row {
 background: transparent;
}

.risk-history-row > span,
.risk-history-row > code {
 min-width: 0;
 padding: 7px 9px;
 overflow-wrap: anywhere;
 font-size: 12px;
}

.risk-history-row > span small {
 display: block;
 margin-top: 2px;
 color: var(--muted);
}

.risk-history-row > code {
 color: var(--muted);
}

.risk-history-instance-cell {
 display: grid;
 gap: 5px;
}

.risk-history-instance-cell > code {
 color: var(--muted);
 font-size: 11px;
}

.risk-history-evidence {
 border-top: 1px solid var(--soft-line);
 padding: 7px 12px 10px;
}

.risk-history-evidence summary {
 color: var(--brand-deep);
 cursor: pointer;
 font-weight: 700;
}

.risk-history-evidence-list {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 8px;
 margin-top: 7px;
 padding: 4px 0 0;
}

.risk-history-evidence-list > div {
 border-left: 2px solid var(--soft-line);
 padding: 3px 8px;
}

.risk-history-evidence-list p {
 margin: 3px 0;
 color: var(--text-secondary);
 line-height: 1.45;
}

.risk-history-evidence-list code {
 color: var(--muted);
 font-size: 10px;
 overflow-wrap: anywhere;
}

.risk-history-prior-disposition small {
 color: var(--muted);
}

.risk-history-prior-disposition button {
 margin-top: 6px;
 border-color: color-mix(in srgb, var(--brand) 34%, var(--line));
 color: var(--brand-deep);
 font-weight: 700;
}

.risk-reassessment-seed {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 16px;
 border-left: 3px solid var(--brand);
 background: #fff8f2;
 padding: 10px 12px;
}

.risk-reassessment-seed > div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.risk-reassessment-seed span,
.risk-reassessment-seed small {
 color: var(--text-secondary);
 line-height: 1.45;
}

.risk-history-dispositions > div {
 min-height: 36px;
 display: grid;
 grid-template-columns: 110px minmax(0, 1fr) 220px;
 align-items: center;
 gap: 8px;
 padding: 5px 0;
 border-bottom: 1px solid var(--soft-line);
 font-size: 12px;
}

.risk-history-dispositions small {
 color: var(--muted);
 text-align: right;
}

.ledger-panel {
 padding: 0;
 overflow: hidden;
}

.risk-ledger-head {
 min-height: 62px;
 padding: 12px;
 border-bottom: 1px solid var(--soft-line);
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 background: #fbfcfd;
}

.risk-ledger-head > div {
 display: grid;
 gap: 3px;
 min-width: 0;
}

.risk-ledger-head span {
 color: var(--muted);
 font-size: 12px;
}

.risk-index-loading-status {
