 font-size: 14px;
}

.full-draft-panel {
 margin-top: 12px;
 border: 1px solid #b8d9cd;
 border-radius: 10px;
 padding: 12px;
 background: linear-gradient(145deg, #f4fbf8 0%, #ffffff 72%);
}

.full-draft-panel-head {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 10px;
}

.full-draft-panel-head > div {
