 border-radius: 8px;
 padding: 9px 10px;
 background: #fff;
}

.full-draft-review-item-head {
 display: flex;
 align-items: baseline;
 justify-content: space-between;
 gap: 8px;
 color: #195d4b;
 font-size: 12px;
}

.full-draft-review-item-head span {
