 font-size: 12px;
 font-weight: 700;
}

.revision-form select,
.revision-form textarea,
.revision-thread textarea {
 width: 100%;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 padding: 8px;
 color: var(--ink);
