 gap: 4px;
 color: #5d6470;
 font-size: 12px;
 line-height: 1.5;
 overflow-wrap: anywhere;
}

.revision-message,
.revision-boundary-line {
 border: 1px solid var(--line);
 border-radius: 4px;
