 gap: 8px;
 max-height: 520px;
 overflow-y: auto;
 padding-right: 3px;
}

.revision-turn {
 min-width: 0;
 border: 1px solid var(--line);
 border-left: 3px solid #a9b2bc;
 border-radius: 4px;
 background: #fff;
}

.revision-turn.current {
