 background: #fffaf6;
}

.revision-turn > header,
.revision-turn > footer {
 display: flex;
 justify-content: space-between;
 gap: 8px;
 align-items: center;
 padding: 7px 9px;
}

.revision-turn > header {
 border-bottom: 1px solid var(--soft-line);
}

.revision-turn > header > div {
 min-width: 0;
 display: flex;
 gap: 8px;
 align-items: baseline;
}

.revision-turn > header strong {
 font-size: 13px;
}

.revision-turn > header span,
.revision-turn > footer span {
 color: var(--muted);
 font-size: 11px;
 overflow-wrap: anywhere;
}

.revision-turn-grid {
