 grid-template-columns: minmax(0, 0.78fr) minmax(0, 1.22fr);
}

.revision-turn-request,
.revision-turn-candidate {
 min-width: 0;
 display: grid;
 align-content: start;
 gap: 4px;
 padding: 9px;
}

.revision-turn-request {
 border-right: 1px solid var(--soft-line);
 background: #fbfcfd;
}

.revision-turn-request > span,
.revision-turn-candidate > span {
 color: var(--muted);
 font-size: 11px;
 font-weight: 800;
}

.revision-turn-request p,
.revision-turn-candidate p {
 margin: 0 0 5px;
 color: var(--ink);
 font-size: 12px;
 line-height: 1.48;
 overflow-wrap: anywhere;
}

.table-cell-revision-diff {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 6px;
}

.table-cell-revision-diff > div {
 min-width: 0;
 border: 1px solid var(--soft-line);
 padding: 7px;
 background: #fbfcfd;
}

.table-cell-revision-diff > div:last-child {
 border-color: #e7b58f;
 background: #fffaf6;
}

.table-cell-revision-diff span {
 display: block;
 margin-bottom: 4px;
 color: var(--muted);
 font-size: 10px;
 font-weight: 800;
}

.revision-local-diff,
.revision-impact-panel {
 display: grid;
 gap: 5px;
 margin: 3px 0 7px;
 border: 1px solid var(--soft-line);
 padding: 7px;
 background: #fbfcfd;
}

.revision-local-diff > span,
.revision-impact-panel > span {
 color: var(--muted);
 font-size: 10px;
 font-weight: 800;
}

.revision-local-diff-text {
 white-space: pre-wrap;
 overflow-wrap: anywhere;
 font-size: 12px;
 line-height: 1.55;
}

.revision-local-diff-text mark {
 padding: 1px 2px;
 color: inherit;
}

.revision-diff-equal {
 background: transparent;
}

.revision-diff-delete {
 background: #ffe2e0;
 color: #9f2f27;
 text-decoration: line-through;
}

.revision-diff-insert {
 background: #dff5e6;
 color: #176b38;
}

.revision-local-diff small,
.revision-impact-panel small {
 color: var(--muted);
 font-size: 10px;
}

.revision-impact-panel.unresolved {
 border-color: #e7b58f;
 background: #fffaf6;
}

.revision-impact-panel p {
 margin: 0;
 font-size: 11px;
}

.revision-impact-panel ul {
 display: grid;
 gap: 4px;
 margin: 0;
 padding-left: 15px;
}

.revision-impact-panel li {
 display: grid;
 gap: 1px;
 font-size: 11px;
}

.revision-impact-panel li span {
 color: var(--ink);
}

.revision-impact-panel li small {
 overflow-wrap: anywhere;
}

.revision-impact-downstream strong {
 color: #a15e12;
}

.revision-impact-unresolved strong {
 color: #9f2f27;
}

.revision-protected-token-panel {
 display: grid;
 gap: 5px;
 margin: 3px 0 7px;
 border: 1px solid #b7d2c0;
 padding: 7px;
 background: #f5fbf7;
}

.revision-protected-token-panel > span {
 color: #35734b;
 font-size: 10px;
 font-weight: 800;
}

.revision-protected-token-panel p {
 margin: 0;
 font-size: 11px;
}

.revision-protected-token-panel ul {
 display: grid;
 gap: 4px;
 margin: 0;
 padding-left: 15px;
}

.revision-protected-token-panel li {
 display: grid;
 gap: 1px;
 font-size: 11px;
}

.revision-protected-token-panel li span {
 color: var(--ink);
}

.revision-protected-token-panel.unresolved {
 border-color: #e7b58f;
 background: #fffaf6;
}

.revision-protected-token-panel.unresolved > span {
 color: #a15e12;
}

.revision-protected-token-panel.violated {
 border-color: #e0aaa6;
 background: #fff5f4;
}

.revision-protected-token-panel.violated > span,
.revision-protected-token-panel.violated li strong {
 color: #9f2f27;
}

.revision-turn > footer {
 justify-content: flex-start;
 flex-wrap: wrap;
 border-top: 1px solid var(--soft-line);
 background: #fbfcfd;
}

.revision-current-action {
 display: grid;
 gap: 8px;
 border-top: 1px solid var(--soft-line);
 padding-top: 9px;
}

.revision-current-action > strong {
 font-size: 13px;
}

.revision-current-action textarea {
 min-height: 66px;
}

.revision-application-band {
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 gap: 10px;
 align-items: center;
 border: 1px solid var(--line);
 border-left: 3px solid var(--orange);
 border-radius: 4px;
 background: #fffaf6;
 padding: 10px;
}

.revision-application-band > div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.revision-application-band strong {
 font-size: 13px;
}

.revision-application-band span {
 color: var(--muted);
 font-size: 12px;
 line-height: 1.45;
 overflow-wrap: anywhere;
}

.revision-application-band.pending {
 border-left-color: #d68a15;
 background: var(--warning-bg);
}

.revision-application-band.needs-write-retry {
 border-left-color: #d68a15;
 background: #fffaf2;
}

.revision-application-band.applied {
 border-left-color: var(--success);
 background: var(--success-bg);
}

.revision-application-actions {
 min-width: max-content;
 display: inline-flex;
 align-items: center;
 justify-content: flex-end;
 gap: 7px;
}

.source-ref-list {
 display: flex;
 flex-wrap: wrap;
 gap: 6px;
 margin-top: 8px;
}

.source-ref-list span {
 max-width: 100%;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fbfcfd;
 color: #4a5662;
 padding: 4px 7px;
 font-size: 12px;
 line-height: 1.35;
 overflow-wrap: anywhere;
}

.boundary-note {
 border-left: 3px solid #e67b2c;
 background: #fff7ed;
 padding: 7px 9px;
}

.checklist {
 display: grid;
 grid-template-columns: repeat(2, minmax(180px, 1fr));
 gap: 8px;
}

.checklist h3 {
 grid-column: 1 / -1;
}

.checklist label {
 display: flex;
 align-items: center;
 gap: 8px;
 min-height: 30px;
}

.checklist input[type="checkbox"] {
 width: auto;
 min-width: 14px;
}

textarea,
input {
 width: 100%;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 9px;
 color: var(--text);
 background: #fff;
}

textarea {
 min-height: 72px;
 resize: vertical;
}

.subject-shortcut {
 display: grid;
 grid-template-columns: minmax(220px, 1fr) auto;
 gap: 12px;
 align-items: center;
 color: var(--muted);
}

.subject-shortcut > div:first-child {
 display: grid;
 gap: 3px;
}

.subject-grid {
 display: grid;
 grid-template-columns: minmax(520px, 1.2fr) minmax(260px, 0.7fr) minmax(300px, 0.8fr);
 gap: 12px;
 margin-top: 12px;
}

.segmented {
 border: 1px solid var(--line);
 border-radius: 4px;
 display: flex;
 overflow: hidden;
}

.segmented button {
 border: 0;
 border-right: 1px solid var(--line);
 border-radius: 0;
}

.segmented button.active {
 background: var(--orange);
 color: #fff;
}

.subject-catalog-select {
 display: block;
 min-width: min(320px, 100%);
}

.subject-catalog-select select {
 width: 100%;
 height: 34px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
 font: inherit;
 font-size: 13px;
 padding: 0 10px;
}

.timeline {
 min-height: 170px;
 display: grid;
 grid-template-columns: repeat(7, minmax(80px, 1fr));
 grid-auto-columns: minmax(80px, 1fr);
 align-items: center;
 gap: 8px;
 position: relative;
 padding-top: 22px;
 overflow-x: auto;
}

.timeline::before {
 content: "";
 position: absolute;
 left: 18px;
 right: 18px;
 top: 86px;
 height: 2px;
 background: var(--line);
}

.timeline-event {
 min-height: 96px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 display: grid;
 align-content: center;
 gap: 4px;
 padding: 8px;
 position: relative;
}

.timeline-event::before {
 content: "";
 width: 10px;
 height: 10px;
 border-radius: 50%;
 position: absolute;
 left: 10px;
 top: -16px;
 background: var(--info);
}

.timeline-event.critical {
 border-color: #ffc9c9;
 background: var(--danger-bg);
}

.timeline-event.critical::before {
 background: var(--danger);
}

.timeline-event.warning {
 border-color: #ffd99d;
 background: var(--warning-bg);
}

.timeline-event.warning::before {
 background: var(--warning);
}

.timeline-event.good::before {
 background: var(--success);
}

.timeline-event span,
.timeline-event em {
 font-size: 12px;
 color: var(--muted);
 font-style: normal;
}

.trend-chart {
 min-height: 180px;
 display: flex;
 align-items: flex-end;
 gap: 14px;
 padding: 8px 4px 0;
}

.empty-state {
 width: 100%;
 min-height: 150px;
 border: 1px dashed var(--line);
 border-radius: 4px;
 display: grid;
 place-items: center;
 color: var(--muted);
 font-size: 13px;
}

.trend-col {
 flex: 1;
 display: grid;
 justify-items: center;
 gap: 5px;
}

.trend-col span {
 width: 22px;
 min-height: 20px;
 max-height: 120px;
 background: var(--info);
 border-radius: 4px 4px 0 0;
}

.trend-col b {
 font-size: 12px;
}

.trend-col em {
 font-size: 12px;
 color: var(--muted);
 font-style: normal;
}

.profile-summary {
 display: grid;
 gap: 10px;
}

.profile-summary > span {
 color: var(--muted);
}

.lab-list {
 display: grid;
 gap: 6px;
}

.lab-list > div,
.detail-grid > div {
 min-height: 36px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 display: grid;
 grid-template-columns: 80px 1fr auto;
 gap: 8px;
 align-items: center;
 padding: 6px 8px;
}

.risk-list p {
 display: flex;
 align-items: center;
 gap: 6px;
 color: var(--warning);
}

.review-focus {
 border-top: 1px solid var(--soft-line);
 padding-top: 10px;
 display: grid;
 gap: 6px;
}

.review-focus h3 {
 margin: 0;
 font-size: 13px;
}

.review-focus p {
 margin: 0;
 color: var(--muted);
 font-size: 13px;
}

.timeline-toolbar {
 display: grid;
 grid-template-columns: 260px minmax(320px, 1fr) 220px;
 gap: 12px;
 margin-bottom: 12px;
 align-items: end;
}

.timeline-toolbar > div {
 display: grid;
 gap: 6px;
}

.reference-timeline-page {
 --ref-ink: #2d2926;
 --ref-muted: #746f68;
 --ref-line: #eadfce;
 --ref-axis: #cdbb8f;
 --ref-brown: #9a6a19;
 --ref-orange: #bf5a00;
 --ref-card-bg: #fffaf2;
 background: #fffdf8;
 color: var(--ref-ink);
}

.reference-subject-head {
 border: 1px solid var(--ref-line);
 border-radius: 4px;
 background: #fffdf8;
 padding: 16px 16px 12px;
 display: flex;
 justify-content: space-between;
 gap: 16px;
 margin-bottom: 10px;
}

.reference-subject-head h2 {
 margin: 0 0 4px;
 font-size: 24px;
 letter-spacing: 0;
}

.reference-subject-head strong {
 color: var(--ref-brown);
}

.reference-subject-head p {
 margin: 6px 0 0;
 color: var(--ref-muted);
 font-size: 13px;
}

.reference-subject-actions {
 min-width: 170px;
 display: flex;
 flex-direction: column;
 align-items: flex-end;
 justify-items: end;
 gap: 8px;
 color: var(--ref-ink);
 font-weight: 700;
}

.reference-subject-actions button {
 white-space: nowrap;
}

.reference-subject-switch {
 border: 1px solid var(--ref-line);
 border-radius: 4px;
 background: #fffefa;
 padding: 8px 10px;
 display: flex;
 align-items: center;
 gap: 10px;
 margin-bottom: 10px;
}

.reference-subject-switch > span {
 color: var(--ref-muted);
 font-weight: 800;
 font-size: 13px;
}

.reference-subject-switch .segmented {
 max-width: 320px;
}

.reference-subject-switch .subject-catalog-select {
 max-width: 380px;
 flex: 1 1 280px;
}

.reference-risk-cards {
 display: grid;
 grid-template-columns: repeat(3, minmax(260px, 1fr));
 gap: 12px;
 margin-bottom: 12px;
}

.reference-risk-card {
 min-height: 88px;
 border: 1px solid #e4c7a1;
 border-left: 4px solid #d47a1d;
 border-radius: 6px;
 background: var(--ref-card-bg);
 padding: 12px 14px;
 display: grid;
 gap: 7px;
 align-content: start;
 overflow: hidden;
}

.reference-risk-card.plain {
 border-left-width: 1px;
}

.reference-risk-card h3 {
 margin: 0;
 font-size: 16px;
}

.reference-risk-card p {
 margin: 0;
 color: var(--ref-muted);
 line-height: 1.55;
 font-size: 13px;
 overflow-wrap: anywhere;
}

.timeline-context-summary {
 min-height: 42px;
 border: 1px solid var(--ref-line);
 border-left: 3px solid #708090;
 border-radius: 4px;
 background: #fffefa;
 padding: 8px 12px;
 display: flex;
 align-items: baseline;
 gap: 12px;
 margin-bottom: 10px;
}

.timeline-context-summary.focused {
 border-left-color: var(--orange);
 background: #fff9f1;
}

.timeline-context-summary strong {
 flex: 0 0 auto;
 font-size: 13px;
}

.timeline-context-summary span {
 color: var(--ref-muted);
 font-size: 12px;
}

.profile-data-warning {
 margin: 10px 0 0;
 padding: 9px 12px;
 border: 1px solid color-mix(in srgb, var(--danger) 32%, var(--ref-line));
 border-radius: 8px;
 color: var(--danger);
 background: color-mix(in srgb, var(--danger) 7%, white);
 font-size: 12px;
 line-height: 1.55;
}

.timeline-context-summary .profile-data-warning {
 flex-basis: 100%;
}

.reference-timeline-shell {
 border: 1px solid var(--ref-line);
 border-radius: 6px;
 background: #fffefa;
 padding: 0;
 overflow: hidden;
}

.timeline-category-legend {
 display: flex;
 flex-wrap: wrap;
 gap: 8px;
 padding: 10px 14px;
 min-width: 0;
}

.timeline-shell-toolbar {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 border-bottom: 1px solid #f1e8db;
 background: #fffefa;
}

.timeline-zoom-control {
 display: inline-flex;
 align-items: center;
 gap: 4px;
 flex: 0 0 auto;
 padding-right: 12px;
}

.timeline-zoom-control button {
 width: 30px;
 height: 30px;
 padding: 0;
 display: grid;
 place-items: center;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
}

.timeline-zoom-control span {
 width: 46px;
 text-align: center;
 font-size: 12px;
 font-weight: 700;
 color: var(--muted);
}

.timeline-category-chip {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 min-height: 24px;
 border: 1px solid var(--category-stroke, #b8c0ca);
 border-radius: 999px;
 background: var(--category-tint, #f6f7f9);
 color: #2b2f35;
 padding: 3px 9px;
 font-size: 12px;
 font-weight: 700;
 white-space: nowrap;
}

.timeline-category-chip > span {
 width: 10px;
 height: 10px;
 border-radius: 3px;
 background: var(--category-fill, #b7d4ea);
 box-shadow: inset 0 0 0 1px var(--category-stroke, #506270);
}

.reference-timeline-scroll {
 overflow-x: auto;
 padding: 0;
}

.reference-timeline-canvas {
 min-width: 0;
 min-height: 0;
 position: relative;
 padding: 0;
}

.reference-timeline-svg {
 width: 100%;
 min-width: 1180px;
 height: auto;
 display: block;
 background: #fffefa;
 padding: 8px;
}

.reference-svg-axis {
 stroke: var(--ref-axis);
 stroke-width: 4;
 stroke-linecap: round;
}

.reference-svg-date,
.reference-svg-visit-label,
.reference-svg-visit-date,
.reference-svg-event-label,
.reference-svg-event-empty {
 fill: var(--ref-muted);
 font-weight: 700;
}

.reference-svg-date {
 font-size: 12px;
}

.reference-svg-visit-line {
 stroke: #eee5d5;
 stroke-width: 1;
}

.reference-svg-visit-dot {
 fill: #8c6a2b;
 stroke: #fffefa;
 stroke-width: 2;
}

.reference-svg-visit-dot.unscheduled {
 fill: #fffefa;
 stroke: #bf5a00;
 stroke-width: 2.5;
}

.reference-svg-visit-label,
.reference-svg-visit-date {
 font-size: 10px;
}

.reference-svg-lane-title {
 fill: var(--ref-ink);
 font-size: 15px;
 font-weight: 800;
}

.reference-svg-lane-rule {
 stroke: #f1e8db;
 stroke-width: 1;
}

.reference-svg-lane-rule.soft {
 stroke: #f7f1e8;
}

.reference-svg-event-label {
 font-size: 10px;
 fill: #4b463f;
}

.reference-svg-event-empty {
 font-size: 10px;
 fill: #aaa198;
}

.reference-svg-event-block {
 fill: var(--category-fill, var(--lane-fill, #b7d4ea));
