.timeline-toolbar span {
 color: var(--muted);
 font-size: 12px;
 line-height: 1.5;
}

.timeline-risk-cards {
 display: grid;
 grid-template-columns: repeat(3, minmax(220px, 1fr));
 gap: 12px;
 margin-bottom: 12px;
}

.timeline-risk-card {
 border: 1px solid #ffd6a8;
 border-left: 4px solid var(--orange);
 border-radius: 4px;
 background: #fffaf2;
 padding: 12px;
 display: grid;
 gap: 6px;
}

.timeline-risk-card span {
 color: var(--muted);
 font-size: 12px;
}

.timeline-canvas {
 min-height: 390px;
 overflow-x: auto;
}

.visit-axis-panel {
 overflow: hidden;
}

.visit-axis-scroll {
 overflow-x: auto;
 padding-bottom: 6px;
}

.visit-axis-canvas {
 min-width: 980px;
 min-height: 500px;
 position: relative;
 padding: 74px 28px 24px;
}

.visit-axis-line {
 position: absolute;
 left: 46px;
 right: 46px;
 top: 96px;
 height: 2px;
 background: var(--line);
}

.visit-marker {
 width: 116px;
 position: absolute;
 top: 38px;
 transform: translateX(-50%);
 display: grid;
 justify-items: center;
 gap: 4px;
 text-align: center;
}

.visit-marker.below {
 top: 106px;
}

.visit-marker b {
 width: 10px;
 height: 10px;
 border-radius: 50%;
 background: var(--orange);
 border: 2px solid #fff;
 box-shadow: 0 0 0 2px #ffd6a8;
}

.visit-marker span {
 font-weight: 800;
}

.visit-marker em {
 color: var(--muted);
 font-style: normal;
 font-size: 12px;
}

.event-lanes {
 display: grid;
 gap: 10px;
 margin-top: 112px;
}

.timeline-lane-track {
 min-height: 70px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fbfcfd;
 display: grid;
 grid-template-columns: 120px minmax(0, 1fr);
 align-items: stretch;
 overflow: hidden;
}

.timeline-lane-track > strong {
 display: flex;
 align-items: center;
 padding: 10px;
 border-right: 1px solid var(--soft-line);
 background: #fff;
}

.timeline-lane-track > div {
 position: relative;
 min-height: 70px;
}

.lane-event-pin {
 max-width: 190px;
 min-width: 128px;
 position: absolute;
 top: 10px;
 transform: translateX(-12px);
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 padding: 6px 8px;
 display: grid;
 gap: 2px;
 text-align: left;
 white-space: normal;
}

.lane-event-pin.critical {
 border-color: #ffc9c9;
 background: var(--danger-bg);
}

.lane-event-pin.warning {
 border-color: #ffd99d;
 background: var(--warning-bg);
}

.lane-event-pin.good {
 border-color: #bfe7ce;
 background: var(--success-bg);
}

.lane-event-pin span,
.lane-event-pin em {
 color: var(--muted);
 font-size: 11px;
 font-style: normal;
}

.lane-event-pin b {
 font-size: 12px;
 line-height: 1.3;
}

.timeline-axis {
 min-width: 860px;
 display: grid;
 grid-template-columns: repeat(7, minmax(110px, 1fr));
 align-items: center;
 padding: 20px 30px 8px;
 border-bottom: 4px solid #d8c59e;
}

.axis-point {
 display: grid;
 justify-items: center;
 gap: 5px;
 color: var(--muted);
 font-size: 12px;
}

.axis-point b {
 width: 9px;
 height: 9px;
 border-radius: 50%;
 background: #9a7130;
}

.axis-point em {
 font-style: normal;
 text-align: center;
}

.timeline-lanes {
 min-width: 860px;
 display: grid;
 gap: 14px;
 padding: 18px 18px 8px;
}

.lane-row {
 display: grid;
 grid-template-columns: 120px 1fr;
 gap: 12px;
 align-items: start;
}

.lane-row > div {
 display: flex;
 flex-wrap: wrap;
 gap: 8px;
}

.lane-event {
 min-height: 28px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 padding: 4px 8px;
}

.lane-event.critical,
.lane-event.warning {
 border-color: #ffd6a8;
 background: #fff7ec;
 color: var(--warning);
}

.timeline-detail-grid,
.profile-two-col {
 display: grid;
 grid-template-columns: repeat(2, minmax(320px, 1fr));
 gap: 12px;
 margin-top: 12px;
}

.timeline-detail-grid .panel:last-child {
 grid-column: 1 / -1;
}

.timeline-detail-card {
 min-height: 0;
}

.timeline-detail-row {
 border-bottom: 1px solid var(--soft-line);
 border-left: 4px solid var(--category-fill, transparent);
 background: linear-gradient(90deg, var(--category-tint, transparent), transparent 74%);
 padding: 8px 10px;
 display: grid;
 grid-template-columns: minmax(104px, max-content) minmax(0, 1fr);
 gap: 10px;
 align-items: start;
}

.timeline-detail-row:last-child {
 border-bottom: 0;
}

.timeline-detail-row div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.timeline-detail-row > .tag {
 justify-self: start;
 max-width: 150px;
 white-space: normal;
 text-align: center;
 line-height: 1.25;
}

.timeline-detail-row span,
.timeline-detail-row em {
 color: var(--muted);
 font-size: 12px;
 line-height: 1.5;
 font-style: normal;
}

.timeline-detail-more {
 width: 100%;
 border: 0;
 border-top: 1px solid var(--soft-line);
 background: #fafbfc;
 color: var(--muted);
 padding: 9px 12px;
 font-size: 12px;
 text-align: center;
}

.chart-baseline line {
 stroke: #66574d;
 stroke-width: 1.2;
 stroke-dasharray: 5 4;
 opacity: 0.72;
}

.chart-baseline text {
 fill: #66574d;
 font-size: 9px;
 font-weight: 700;
}

.metric-chart-head .metric-baseline-note {
 color: #6a5d54;
 font-size: 11px;
 line-height: 1.45;
}

.chart-point.baseline {
 stroke: #4d3c30;
 stroke-width: 2;
}

.metric-points-toggle {
 width: 100%;
 border: 0;
 border-top: 1px solid var(--soft-line);
 background: #fafbfc;
 color: var(--muted);
 padding: 8px 12px;
 font-size: 12px;
 text-align: center;
}

.profile-hero {
 min-height: 98px;
 border-radius: 4px;
 background: #202136;
 color: #fff;
