 outline: none;
}

.profile-workbench {
 display: grid;
 grid-template-columns: 240px minmax(0, 1fr);
 gap: 12px;
 min-width: 0;
}

.profile-subject-list {
 display: grid;
 align-content: start;
 gap: 7px;
 min-width: 0;
 max-height: calc(100vh - 240px);
 overflow-y: auto;
}

.profile-subject-list > .section-title {
 position: sticky;
 top: 0;
 z-index: 2;
 margin: -2px -2px 0;
 padding: 2px 2px 8px;
 background: #fff;
}

.profile-subject-list button {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fff;
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 gap: 4px;
 align-items: center;
 padding: 8px;
 text-align: left;
 min-width: 0;
}

.profile-subject-list button.selected {
 border-color: var(--orange);
 background: #fff8f3;
 scroll-margin-block: 8px;
}

.profile-subject-list button > span {
 grid-column: 1 / -1;
}

.profile-subject-list span {
 color: var(--muted);
 font-size: 12px;
 overflow-wrap: anywhere;
}

.profile-tree {
 display: grid;
 gap: 10px;
}

.profile-tree-group {
 display: grid;
 gap: 6px;
}

.profile-tree-center {
 min-height: 30px;
 border-bottom: 1px solid var(--soft-line);
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
 color: var(--text);
}

.profile-main {
 display: grid;
 gap: 12px;
 min-width: 0;
}

.profile-summary-band {
 display: grid;
 grid-template-columns: repeat(4, minmax(140px, 1fr));
 gap: 10px;
 min-width: 0;
}

.profile-summary-band > div {
 min-width: 0;
 min-height: 70px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 display: grid;
 place-items: center;
 align-content: center;
 background: #fbfcfd;
}

.profile-summary-band strong {
 font-size: 22px;
 color: var(--orange);
 max-width: 100%;
 overflow-wrap: anywhere;
 text-align: center;
}

.profile-summary-band span {
 color: var(--muted);
 font-size: 12px;
 text-align: center;
}

.profile-section {
 min-width: 0;
}

.profile-info-grid {
 display: grid;
 grid-template-columns: repeat(4, minmax(0, 1fr));
 gap: 8px;
}

.profile-info-grid > div {
 min-width: 0;
 min-height: 58px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 display: grid;
 align-content: center;
 gap: 3px;
 padding: 8px 10px;
 background: #fbfcfd;
}

.profile-info-grid span {
 color: var(--muted);
 font-size: 12px;
}

.profile-info-grid strong {
 min-width: 0;
 overflow-wrap: anywhere;
}

.profile-context-list {
 display: grid;
 gap: 6px;
 margin-top: 10px;
}

.profile-context-list p,
.profile-review-focus p {
 margin: 0;
 border-left: 3px solid var(--orange);
 padding: 6px 8px;
 background: #fff8f3;
 overflow-wrap: anywhere;
}

.profile-trend-table {
 border: 1px solid var(--line);
 border-radius: 4px;
 overflow: hidden;
}

.profile-trend-table > div {
 display: grid;
 grid-template-columns: 120px 100px 1fr;
 gap: 12px;
 align-items: center;
 min-height: 38px;
 padding: 7px 10px;
 border-bottom: 1px solid var(--soft-line);
}

.profile-trend-table > div:first-child {
 background: #f7f8fa;
}

.profile-trend-table > div:last-child {
 border-bottom: 0;
}

.metric-chart-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(min(100%, 360px), 1fr));
 gap: 12px;
 min-width: 0;
}

.metric-chart {
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 padding: 10px;
 overflow: hidden;
 min-width: 0;
}

.metric-chart-head {
 display: flex;
 justify-content: space-between;
 gap: 8px;
 margin-bottom: 8px;
 min-width: 0;
}

.metric-chart-head div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.metric-chart-head strong {
 min-width: 0;
 overflow-wrap: anywhere;
}

.metric-chart-head span {
 color: var(--muted);
 font-size: 12px;
 overflow-wrap: anywhere;
}

.metric-chart svg {
 width: 100%;
 height: auto;
 display: block;
 background: #fbfcfd;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
}

.chart-axis-line {
 stroke: #d5dae0;
 stroke-width: 1;
}

.chart-ref-line {
 stroke: #b96b00;
 stroke-dasharray: 5 4;
 stroke-width: 1;
}

.chart-point-reference line {
 stroke: #b68a4c;
 stroke-width: 1;
 opacity: 0.7;
}

.chart-line {
 fill: none;
 stroke: var(--info);
 stroke-width: 2.5;
}

.chart-point {
 fill: #fff;
 stroke: var(--info);
 stroke-width: 2;
}

.chart-point.risk {
 stroke: var(--danger);
 fill: var(--danger-bg);
}

.chart-label,
.chart-value {
 fill: var(--muted);
 font-size: 11px;
}

.profile-domain-footnote {
 margin: 2px 2px 0;
 color: var(--muted);
 font-size: 11px;
}

.chart-value {
 fill: var(--text);
 font-weight: 700;
}

.metric-point-list {
 display: grid;
 gap: 5px;
 margin-top: 8px;
}

.metric-point-list > div {
 min-height: 30px;
 display: grid;
 grid-template-columns: 44px minmax(0, 1fr) minmax(58px, auto);
 gap: 8px;
 align-items: center;
 border-bottom: 1px solid var(--soft-line);
 padding-bottom: 5px;
 min-width: 0;
}

.metric-point-list > div:last-child {
 border-bottom: 0;
}

.metric-point-list span {
 color: var(--muted);
 font-size: 12px;
 min-width: 0;
 overflow-wrap: anywhere;
}

.profile-risk-prompts p {
 align-items: flex-start;
}

.profile-risk-prompts span {
 color: var(--warning);
 line-height: 1.5;
}

.profile-review-focus {
 display: grid;
 gap: 6px;
 margin-top: 10px;
}

.profile-pd-query-grid {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 12px;
}

.profile-pd-query-grid h3 {
 margin: 0 0 8px;
 font-size: 14px;
}

.profile-query-card {
 min-width: 0;
 min-height: 44px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 gap: 8px;
 align-items: flex-start;
 padding: 8px;
 margin-bottom: 7px;
 background: #fbfcfd;
}

.profile-query-card div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.profile-query-card strong,
.profile-query-card span {
 min-width: 0;
 overflow-wrap: anywhere;
}

.profile-query-card span {
 color: var(--muted);
 font-size: 12px;
 line-height: 1.5;
}

.profile-event-index {
 display: grid;
 gap: 6px;
}

.profile-event-index > div {
 min-height: 34px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 display: grid;
 grid-template-columns: 46px minmax(0, 1fr);
 gap: 8px;
 align-items: center;
 padding: 6px 8px;
}

.profile-event-index span {
 overflow-wrap: anywhere;
}

.eligibility-layout {
 display: grid;
 grid-template-columns: 300px minmax(420px, 1fr) 360px;
 gap: 12px;
}

.eligibility-status {
 min-height: 68px;
 display: grid;
 grid-template-columns: 1.1fr 1.2fr 0.85fr 1fr 1fr;
 gap: 10px;
 margin-bottom: 12px;
}

.source-admission-band {
 display: grid;
 gap: 10px;
 margin-bottom: 12px;
 border-left: 3px solid var(--orange);
}

.source-admission-head {
 display: grid;
 grid-template-columns: 18px max-content minmax(0, 1fr) 32px;
 align-items: center;
 gap: 8px;
}

.source-admission-head > span {
 min-width: 0;
 color: var(--muted);
 font-size: 12px;
 overflow-wrap: anywhere;
}

.source-admission-cards {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 border-top: 1px solid var(--soft-line);
}

.source-admission-card {
 min-width: 0;
 display: grid;
 align-content: start;
 gap: 8px;
 padding: 10px 12px 4px 0;
}

.source-admission-card + .source-admission-card {
 border-left: 1px solid var(--soft-line);
 padding-left: 12px;
 padding-right: 0;
}

.source-admission-card.needs-confirmation {
 box-shadow: inset 3px 0 0 #f59e0b;
 padding-left: 10px;
}

.source-admission-card-head,
.source-admission-card-foot,
.content-confirmation-actions {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.module-source-admission {
 margin: 12px 0;
 border: 1px solid var(--line);
 border-left: 3px solid var(--warning);
 border-radius: 4px;
 background: #fffdf9;
 min-width: 0;
}

.module-source-admission.ready {
 border-left-color: var(--success);
 background: #fbfdfb;
}

.module-source-admission-head {
 min-height: 42px;
 display: grid;
 grid-template-columns: auto auto minmax(220px, 1fr) auto auto auto;
 gap: 8px;
 align-items: center;
 padding: 6px 10px;
 min-width: 0;
}

.module-source-admission-head > span {
 color: var(--muted);
 font-size: 12px;
 min-width: 0;
 overflow-wrap: anywhere;
}

.module-source-admission-toggle {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 gap: 4px;
 padding: 4px 8px;
}

.module-source-admission-toggle svg {
 transition: transform 140ms ease;
}

.module-source-admission-toggle svg.expanded {
 transform: rotate(90deg);
}

.module-source-admission-body {
 border-top: 1px solid var(--soft-line);
 padding: 10px;
 min-width: 0;
}

.module-source-admission-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
 gap: 8px;
 min-width: 0;
}

.module-source-admission-source {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fff;
 padding: 9px;
 display: grid;
 align-content: start;
 gap: 8px;
 min-width: 0;
}

.module-source-admission-source.needs-confirmation {
 border-color: #e6b36d;
 background: #fffaf3;
}

.module-source-admission-source-head {
 display: flex;
 justify-content: space-between;
 gap: 8px;
 align-items: flex-start;
 min-width: 0;
}

.module-source-admission-source-head > div:first-child {
 display: grid;
 gap: 2px;
 min-width: 0;
}

.module-source-admission-source-head > div:first-child span,
.module-source-admission-source > p,
.module-source-confirmed-record span,
.module-source-confirmed-record small {
 min-width: 0;
 overflow-wrap: anywhere;
}

.module-source-admission-source-head > div:first-child span,
.module-source-admission-source > p,
.module-source-confirmed-record small {
 color: var(--muted);
 font-size: 12px;
}

.module-source-admission-source-head > div:last-child {
 display: flex;
 flex-wrap: wrap;
 justify-content: flex-end;
 gap: 4px;
}

.module-source-admission-source > p {
 margin: 0;
 line-height: 1.45;
}

.module-source-admission-checks {
 display: grid;
 border-top: 1px solid var(--soft-line);
}

.module-source-admission-checks > div {
 min-height: 34px;
 display: grid;
 grid-template-columns: minmax(78px, 0.8fr) auto minmax(120px, 1.8fr);
 gap: 7px;
 align-items: center;
 border-bottom: 1px solid var(--soft-line);
 padding: 5px 0;
 min-width: 0;
}

.module-source-admission-checks b,
.module-source-admission-checks small {
 font-size: 12px;
}

.module-source-admission-checks small {
 color: var(--muted);
 min-width: 0;
 overflow-wrap: anywhere;
 display: -webkit-box;
 -webkit-box-orient: vertical;
 -webkit-line-clamp: 3;
 overflow: hidden;
}

.module-source-admission-source > button {
 justify-self: start;
 display: inline-flex;
 align-items: center;
 gap: 5px;
}

.module-source-confirmed-record {
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 gap: 7px;
 align-items: center;
 padding: 6px 8px;
 border-left: 3px solid var(--success);
 background: var(--success-bg);
}

.module-source-confirmed-record small {
 grid-column: 2;
}

.module-source-confirmation {
 max-height: 44vh;
 overflow-y: auto;
 margin-top: 10px;
 border: 1px solid #e6b36d;
 border-radius: 4px;
 background: #fffaf3;
 padding: 10px;
 display: grid;
 gap: 9px;
}

.module-source-confirmation > p,
.module-source-confirmation > small {
 margin: 0;
 color: var(--muted);
 line-height: 1.5;
}

.module-source-confirmation fieldset {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 display: grid;
 gap: 6px;
 padding: 8px;
}

.module-source-confirmation legend {
 padding: 0 5px;
 font-weight: 700;
}

.module-source-confirmation-reason {
 display: grid;
 gap: 5px;
}

.module-source-confirmation-reason textarea {
 width: 100%;
 resize: vertical;
}

.source-admission-card-tags {
 display: flex;
 flex-wrap: wrap;
 justify-content: flex-end;
 gap: 5px;
}

.source-admission-card-body {
 display: grid;
 grid-template-columns: minmax(0, 1.2fr) max-content max-content;
 gap: 6px 12px;
 color: var(--muted);
 font-size: 11px;
}

.source-admission-card-body > span {
 min-width: 0;
 overflow-wrap: anywhere;
}

.source-admission-card-body > span:last-child {
 grid-column: 1 / -1;
}

.source-admission-raw-note {
 margin: 0;
 padding: 6px 8px;
 color: #7c4a03;
 background: #fffaf0;
 border-left: 2px solid #f59e0b;
 font-size: 11px;
 line-height: 1.45;
}

.source-admission-checks {
 display: grid;
 border-top: 1px solid var(--soft-line);
}

.source-admission-checks > div {
 min-width: 0;
 display: grid;
 grid-template-columns: 100px 56px minmax(0, 1fr);
 gap: 8px;
 padding: 5px 0;
 border-bottom: 1px solid var(--soft-line);
 font-size: 11px;
}

.source-admission-checks small {
 min-width: 0;
 max-height: 38px;
 overflow: auto;
 color: var(--muted);
 overflow-wrap: anywhere;
}

.source-admission-card-foot {
 justify-content: flex-end;
}

.source-admission-band > .content-confirmation {
 grid-column: auto;
}

.content-confirmation-actions {
 justify-content: flex-start;
}

@media (max-width: 1260px) {
 .eligibility-status {
 grid-template-columns: repeat(3, minmax(0, 1fr));
 }

 .source-admission-cards {
 grid-template-columns: minmax(0, 1fr);
 }

 .source-admission-card + .source-admission-card {
 border-left: 0;
 border-top: 1px solid var(--soft-line);
 padding-left: 0;
 }
}

.eligibility-status > div {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 10px;
 display: grid;
 gap: 4px;
 background: #fbfcfd;
}

.eligibility-status span {
 color: var(--muted);
 font-size: 12px;
}

.eligibility-raw-intake {
 display: grid;
 gap: 10px;
 margin-bottom: 12px;
 border-left: 3px solid var(--orange);
}

.raw-intake-head {
 min-height: 30px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
}

.raw-intake-head > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.raw-intake-head span,
.eligibility-raw-intake p,
.raw-intake-grid span {
 color: var(--muted);
 font-size: 12px;
}

.raw-intake-head strong {
 overflow-wrap: anywhere;
}

.raw-intake-grid {
 display: grid;
 grid-template-columns: repeat(4, minmax(160px, 1fr));
 gap: 8px;
}

.raw-intake-grid > div {
 min-height: 58px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fbfcfd;
 padding: 8px;
 display: grid;
 gap: 4px;
}

.eligibility-raw-intake p {
 margin: 0;
 line-height: 1.5;
 overflow-wrap: anywhere;
}

.search-row {
 height: 38px;
 display: grid;
 grid-template-columns: 18px 1fr;
 gap: 8px;
 align-items: center;
 margin-bottom: 10px;
}

.candidate-panel,
.rule-tree,
.review-panel,
.evidence-tree {
 min-height: 0;
}

.candidate-row {
 grid-template-columns: 82px 62px 46px minmax(96px, 1fr);
 padding: 7px;
 margin-bottom: 6px;
}

.candidate-row.selected,
.approval-list button.selected,
.section-tree button.active {
 border-color: var(--orange);
 background: #fff8f3;
}

.candidate-row em {
 color: var(--muted);
 font-style: normal;
 font-size: 12px;
 line-height: 1.25;
}

.rule-node,
.evidence-node {
 min-height: 38px;
 border-bottom: 1px solid var(--soft-line);
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
}

.rule-node.warning {
 color: var(--warning);
}

.review-result {
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 12px;
 background: #fbfcfd;
 margin-bottom: 12px;
}

.eligibility-side {
 display: grid;
 gap: 12px;
}

.verdict-strip {
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 12px;
 background: #fbfcfd;
 display: grid;
 gap: 7px;
 margin-bottom: 12px;
}

.verdict-strip span {
 color: var(--muted);
}

.review-report {
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 12px;
 margin-bottom: 12px;
}

.review-report h3,
.review-report p {
 margin-top: 0;
}

.report-grid {
 display: grid;
 grid-template-columns: repeat(2, minmax(180px, 1fr));
 gap: 8px;
}

.report-grid > div {
 min-height: 56px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 8px;
 display: grid;
 gap: 4px;
 background: #fbfcfd;
}

.report-grid span {
 color: var(--muted);
 font-size: 12px;
}

.review-result h3 {
 margin: 8px 0 5px;
}

.button-grid {
 display: grid;
 grid-template-columns: repeat(2, minmax(120px, 1fr));
 gap: 8px;
 margin-bottom: 12px;
}

.evidence-node {
 justify-content: flex-start;
}

.evidence-node div {
 display: grid;
}

.evidence-node span {
 color: var(--muted);
 font-size: 12px;
}

.eligibility-controls {
 display: grid;
 grid-template-columns: minmax(0, 1fr) 300px;
 gap: 12px;
 margin-bottom: 12px;
}

.phase-tabs {
 display: flex;
 gap: 8px;
 overflow-x: auto;
 min-width: 0;
}

.phase-tabs > div {
 min-width: 190px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 padding: 9px 10px;
 display: grid;
 gap: 3px;
 text-align: left;
}

.phase-tabs > div.active {
 border-color: var(--orange);
 background: #fff8f3;
}

.phase-tabs span,
.phase-cell span,
.quiet-text {
 color: var(--muted);
 font-size: 12px;
}

.eligibility-workbench {
 display: grid;
 grid-template-columns: minmax(420px, 0.9fr) minmax(520px, 1.25fr) minmax(280px, 0.65fr);
 grid-template-areas: "subjects review side";
 gap: 12px;
 align-items: start;
}

.eligibility-workbench > * {
 min-width: 0;
}

.eligibility-subjects-panel {
 grid-area: subjects;
}

.eligibility-subjects-panel .eligibility-table-wrap {
 max-height: 720px;
 overflow: auto;
}

.eligibility-review-panel {
 grid-area: review;
}

.eligibility-side {
 grid-area: side;
}

.eligibility-table-wrap,
.rule-review-table-wrap {
 width: 100%;
 overflow-x: auto;
 border: 1px solid var(--line);
 border-radius: 4px;
}

.eligibility-subject-table,
.rule-review-table {
 width: 100%;
 min-width: 780px;
 table-layout: fixed;
 border-collapse: collapse;
 background: #fff;
}

.eligibility-subject-table {
 min-width: 100%;
}

.rule-review-table {
 min-width: 920px;
}

.eligibility-subject-table th,
.eligibility-subject-table td,
.rule-review-table th,
.rule-review-table td {
 border-bottom: 1px solid var(--soft-line);
 padding: 8px;
 text-align: left;
 vertical-align: top;
 font-size: 12px;
 overflow-wrap: anywhere;
 word-break: break-word;
}

.eligibility-subject-table th:nth-child(1) { width: 28%; }
.eligibility-subject-table th:nth-child(2) { width: 18%; }
.eligibility-subject-table th:nth-child(3) { width: 24%; }
.eligibility-subject-table th:nth-child(4) { width: 30%; }

.eligibility-subject-table th,
.rule-review-table th {
 color: var(--muted);
 background: #f7f8fa;
 font-weight: 700;
 white-space: nowrap;
}

.eligibility-subject-table tr.selected td {
 background: #fff8f3;
}

.raw-subject-summary {
 display: grid;
 grid-template-columns: repeat(5, minmax(0, 1fr));
 gap: 8px;
 margin-bottom: 10px;
}

.raw-subject-summary > div {
 min-width: 0;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fbfcfd;
 padding: 8px;
}

.raw-subject-summary strong,
.raw-subject-summary span {
 display: block;
 min-width: 0;
 overflow-wrap: anywhere;
}

.raw-subject-summary span {
 color: var(--muted);
 font-size: 11px;
 margin-top: 2px;
}

.raw-pending-state {
 color: var(--muted);
 font-size: 13px;
 line-height: 1.65;
 overflow-wrap: anywhere;
}

.legacy-comparison {
 border-color: #e0d6c3;
 background: #fffdf8;
}

.subject-link {
 border: 0;
 background: transparent;
 color: var(--info);
 font-weight: 800;
 padding: 0;
}

.phase-cell {
 width: 100%;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fff;
 display: grid;
 gap: 4px;
 padding: 6px;
 text-align: left;
}

.phase-cell.active {
 border-color: var(--orange);
 background: #fff8f3;
}

.eligibility-verdict {
 grid-template-columns: auto minmax(130px, 0.7fr) minmax(220px, 1fr);
 align-items: center;
}

.eligibility-verdict span:last-child {
 grid-column: 1 / -1;
}

.eligibility-report-grid {
 margin-bottom: 12px;
}

.criteria-list,
.action-list,
.evidence-list {
 display: grid;
 gap: 6px;
 max-height: 360px;
 overflow-y: auto;
 padding-right: 2px;
}

.criteria-row,
.action-item {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fff;
 min-width: 0;
 padding: 8px;
 display: grid;
 gap: 8px;
}

.criteria-row {
 grid-template-columns: 58px minmax(0, 1fr);
}

.criteria-row div,
.action-item div,
.evidence-node div {
 min-width: 0;
}

.criteria-row strong,
.action-item strong,
.evidence-node strong {
 display: block;
 overflow-wrap: anywhere;
}

.criteria-row span,
.action-item span,
.evidence-node span {
 overflow-wrap: anywhere;
}

.action-item {
 grid-template-columns: 18px minmax(0, 1fr);
 color: var(--warning);
 background: var(--warning-bg);
 border-color: #ffd99d;
}

.eligibility-rule-tabs {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 6px;
 margin-bottom: 8px;
}

.eligibility-rule-tabs button {
 min-width: 0;
 min-height: 34px;
 padding: 6px 8px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 font-size: 12px;
}

.eligibility-rule-tabs button.active {
 border-color: var(--orange);
 background: #fff8f3;
 color: var(--orange-dark);
 font-weight: 800;
}

.eligibility-rule-source {
 display: grid;
 gap: 3px;
 padding: 8px;
 margin-bottom: 8px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fbfcfd;
}

.eligibility-rule-source strong {
 font-size: 12px;
}

.eligibility-rule-source span,
.eligibility-rule-boundary {
 color: var(--muted);
 font-size: 11px;
 overflow-wrap: anywhere;
}

.eligibility-rule-tree-scroll {
 max-height: 520px;
 overflow-y: auto;
 padding-right: 3px;
 scrollbar-width: thin;
}

.eligibility-rule-node {
 margin-left: calc(var(--rule-depth) * 10px);
 padding-left: calc(var(--rule-depth) * 2px);
}

.eligibility-rule-node-main {
 min-width: 0;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 gap: 7px;
 align-items: start;
 border-left: 2px solid #dbe1e8;
 border-bottom: 1px solid var(--soft-line);
 padding: 7px 5px 7px 8px;
}

.eligibility-rule-node-main > div {
 min-width: 0;
}

.eligibility-rule-node-main strong,
.eligibility-rule-node-main span {
 display: block;
 overflow-wrap: anywhere;
}

.eligibility-rule-node-main strong {
 font-size: 12px;
 line-height: 1.55;
}

.eligibility-rule-node-main span {
 margin-top: 3px;
 color: var(--muted);
 font-size: 10px;
}

.eligibility-rule-boundary {
 margin: 8px 0 0;
 padding-top: 8px;
 border-top: 1px solid var(--soft-line);
 line-height: 1.55;
}

.eligibility-rule-task-panel .criteria-list {
 max-height: 180px;
}

.eligibility-boundary-line {
 margin: -2px 0 12px;
 padding: 8px 10px;
 border-left: 3px solid var(--warning);
 background: #fffaf2;
 color: #66512f;
 font-size: 12px;
 line-height: 1.5;
}

.eligibility-conflict-banner {
 min-height: 44px;
 margin-bottom: 12px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 border-color: #e4b067;
 background: #fffaf2;
}

.eligibility-workbench {
 grid-template-columns: 270px minmax(430px, 1fr) 400px;
 grid-template-areas: "subjects review side";
 align-items: stretch;
 min-height: 620px;
 height: min(730px, calc(100vh - 270px));
}

.eligibility-workbench > .panel {
 min-height: 0;
 height: 100%;
 overflow: hidden;
}

.eligibility-subjects-panel,
.eligibility-criterion-ledger,
.eligibility-inspector {
 display: flex;
 flex-direction: column;
}

.eligibility-subject-summary {
 min-height: 34px;
 margin-bottom: 8px;
 padding: 7px 8px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fbfcfd;
 color: var(--muted);
 font-size: 11px;
}

.eligibility-subject-summary strong {
 color: var(--text);
}

.eligibility-subject-search {
 flex: 0 0 38px;
 margin-bottom: 8px;
}

.eligibility-subjects-panel .eligibility-table-wrap {
 flex: 1;
 max-height: none;
 overflow-y: auto;
 overflow-x: hidden;
}

.eligibility-subject-table th:nth-child(1) { width: 38%; }
.eligibility-subject-table th:nth-child(2) { width: 20%; }
.eligibility-subject-table th:nth-child(3) { width: 42%; }

.eligibility-criterion-ledger {
 grid-area: review;
}

.eligibility-criterion-ledger .eligibility-rule-tabs {
 flex: 0 0 38px;
}

.eligibility-rule-tabs button {
 display: flex;
 align-items: center;
 justify-content: center;
 gap: 6px;
}

.eligibility-rule-tabs button span {
 min-width: 44px;
 color: inherit;
 font-size: 11px;
}

.eligibility-aggregate-strip {
 flex: 0 0 auto;
 min-height: 42px;
 margin-bottom: 8px;
 padding: 7px 8px;
 display: flex;
 align-items: center;
 flex-wrap: wrap;
 gap: 6px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fbfcfd;
}

.eligibility-aggregate-strip > span:last-child {
 color: var(--muted);
 font-size: 11px;
}

.eligibility-criterion-list {
 min-height: 0;
 flex: 1;
 overflow-y: auto;
 border: 1px solid var(--line);
 border-radius: 4px;
 scrollbar-width: thin;
}

.eligibility-criterion-row {
 width: 100%;
 min-height: 58px;
 padding: 8px;
 display: grid;
 grid-template-columns: 58px minmax(0, 1fr) minmax(104px, auto);
 gap: 8px;
 align-items: start;
 border: 0;
 border-bottom: 1px solid var(--soft-line);
 background: #fff;
 color: var(--text);
 text-align: left;
}

.eligibility-criterion-row:last-child {
 border-bottom: 0;
}

.eligibility-criterion-row:hover,
.eligibility-criterion-row.selected {
 background: #fff8f3;
}

.eligibility-criterion-row.selected {
 box-shadow: inset 3px 0 0 var(--orange);
}

.eligibility-criterion-id {
 color: var(--orange-dark);
 font-weight: 800;
 font-size: 12px;
}

.eligibility-criterion-text {
 display: -webkit-box;
 min-width: 0;
 overflow: hidden;
 -webkit-box-orient: vertical;
 -webkit-line-clamp: 3;
 font-size: 12px;
 line-height: 1.45;
 overflow-wrap: anywhere;
}

.eligibility-criterion-row .tag {
 max-width: 132px;
 white-space: normal;
 min-height: 26px;
 height: auto;
 line-height: 1.25;
 text-align: center;
}

.eligibility-inspector {
 grid-area: side;
}

.eligibility-inspector .icon-button {
 width: 34px;
 height: 34px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
}

.eligibility-inspector-scroll {
 min-height: 0;
 flex: 1;
 overflow-y: auto;
 padding-right: 3px;
 scrollbar-width: thin;
}

.eligibility-criterion-detail,
.eligibility-evidence-section,
.eligibility-ai-draft-block,
.eligibility-decision-block,
.eligibility-current-state {
 padding: 10px 0;
 border-top: 1px solid var(--soft-line);
}

.eligibility-criterion-detail {
 padding-top: 0;
 border-top: 0;
}

.eligibility-inspector-kicker,
.eligibility-subsection-head {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.eligibility-inspector-kicker > span,
.eligibility-subsection-head > span,
.eligibility-source-locator {
 color: var(--muted);
 font-size: 11px;
 overflow-wrap: anywhere;
}

.eligibility-criterion-detail > p,
.eligibility-ai-draft-block > p {
 margin: 8px 0;
 font-size: 13px;
 line-height: 1.55;
}

.eligibility-child-criteria {
 margin-top: 9px;
 display: grid;
 gap: 5px;
}

.eligibility-child-criteria > div {
 display: grid;
 grid-template-columns: 48px minmax(0, 1fr);
 gap: 7px;
 padding: 6px 7px;
 background: #f7f8fa;
}

.eligibility-child-criteria span {
 color: var(--muted);
 font-size: 11px;
}

.eligibility-child-criteria p {
 margin: 0;
 font-size: 11px;
 line-height: 1.45;
}

.eligibility-evidence-section {
 display: grid;
 gap: 6px;
}

.eligibility-evidence-option {
 min-width: 0;
 padding: 7px;
 display: grid;
 grid-template-columns: 18px minmax(0, 1fr) auto;
 gap: 7px;
 align-items: start;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fff;
}

.eligibility-evidence-option.selected {
 border-color: #db9b52;
 background: #fffaf5;
}

.eligibility-evidence-option > span {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.eligibility-evidence-option strong,
.eligibility-evidence-option small {
 overflow-wrap: anywhere;
}

.eligibility-evidence-option small {
 color: var(--muted);
 font-size: 10px;
 line-height: 1.35;
}

.eligibility-ai-draft-block {
 background: #f8fbff;
 padding-left: 8px;
 padding-right: 8px;
}

.eligibility-decision-block {
 display: grid;
 gap: 8px;
}

.eligibility-decision-block label {
 display: grid;
 gap: 5px;
 color: #4a5560;
 font-size: 12px;
 font-weight: 700;
}

.eligibility-decision-block select,
.eligibility-decision-block textarea {
 width: 100%;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
 padding: 8px;
 font: inherit;
 font-weight: 400;
 resize: vertical;
}

.eligibility-inline-warning {
 margin: 0;
 padding: 7px 8px;
 color: #7a3a0c;
 background: #fff6e7;
 font-size: 11px;
}

.eligibility-action-grid {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 7px;
}

.eligibility-action-grid button,
.eligibility-ai-draft-block .secondary-button,
.eligibility-conflict-banner .secondary-button,
.eligibility-review-retry {
 min-height: 34px;
 padding: 0 9px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 6px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
 font-weight: 700;
}

.eligibility-action-grid .primary-button {
 border-color: var(--orange);
 background: var(--orange);
 color: #fff;
}

.eligibility-action-grid button:disabled,
.eligibility-ai-draft-block button:disabled,
.eligibility-inspector .icon-button:disabled {
 cursor: not-allowed;
 opacity: 0.45;
}

.eligibility-current-state {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 4px 10px;
 color: var(--muted);
 font-size: 11px;
}

.eligibility-current-state strong {
 grid-column: 1 / -1;
 color: var(--text);
}

.eligibility-support-band {
 margin-top: 12px;
 display: grid;
 grid-template-columns: repeat(4, minmax(0, 1fr));
 gap: 0;
 padding: 0;
 overflow: hidden;
}

.eligibility-support-band > div {
 min-width: 0;
 min-height: 58px;
 padding: 9px 10px;
 display: grid;
 align-content: center;
 gap: 4px;
 border-right: 1px solid var(--soft-line);
 background: #fbfcfd;
}

.eligibility-support-band > div:last-child {
 border-right: 0;
}

.eligibility-support-band span {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.4;
 overflow-wrap: anywhere;
}

.eligibility-head-actions,
.eligibility-qc-pane-head,
.eligibility-qc-image-tools,
.eligibility-qc-paging,
.eligibility-qc-message {
 display: flex;
 align-items: center;
}

.eligibility-head-actions {
 justify-content: flex-end;
 gap: 8px;
}

.eligibility-qc-entry,
.eligibility-qc-return,
.eligibility-qc-message .secondary-button {
 min-height: 34px;
 padding: 0 10px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 6px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
 font-weight: 700;
}

.eligibility-qc-entry:hover,
.eligibility-qc-return:hover,
.eligibility-qc-message .secondary-button:hover {
 border-color: #d99854;
 background: #fff8f3;
}

.eligibility-qc-page {
 min-width: 0;
 height: calc(100vh - 72px);
 display: flex;
 flex-direction: column;
 overflow: hidden;
}

.eligibility-qc-boundary {
 min-height: 42px;
 margin-bottom: 10px;
 padding: 8px 10px;
 display: flex;
 align-items: center;
 gap: 8px;
 border: 1px solid #f0d4aa;
 border-left: 3px solid var(--warning);
 border-radius: 4px;
 background: #fffaf2;
 color: #66512f;
 font-size: 12px;
 line-height: 1.45;
}

.eligibility-qc-boundary svg {
 flex: 0 0 auto;
}

.eligibility-qc-message {
 min-height: 42px;
 margin-bottom: 10px;
 padding: 7px 10px;
 justify-content: space-between;
 gap: 12px;
 border: 1px solid var(--line);
 border-radius: 4px;
 font-size: 12px;
}

.eligibility-qc-message.error,
.eligibility-qc-message.conflict {
 border-color: #e4b067;
 background: #fffaf2;
 color: #744812;
}

.eligibility-qc-message.success {
 border-color: #aad0b7;
 background: var(--success-bg);
 color: var(--success);
}

.eligibility-qc-overflow {
 min-height: 0;
 flex: 1;
 overflow: auto;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: var(--surface);
}

.eligibility-qc-workspace {
 min-width: 1220px;
 min-height: 680px;
 height: 100%;
 display: grid;
 grid-template-columns: 300px minmax(520px, 1fr) 410px;
 background: #fff;
}

.eligibility-qc-queue-pane,
.eligibility-qc-image-pane,
.eligibility-qc-review-pane {
 min-width: 0;
 min-height: 0;
 display: flex;
 flex-direction: column;
 overflow: hidden;
}

.eligibility-qc-queue-pane,
.eligibility-qc-image-pane {
 border-right: 1px solid var(--line);
}

.eligibility-qc-pane-head {
 flex: 0 0 56px;
 min-width: 0;
 padding: 8px 10px;
 justify-content: space-between;
 gap: 10px;
 border-bottom: 1px solid var(--line);
 background: #fbfcfd;
}

.eligibility-qc-pane-head > div:first-child {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.eligibility-qc-pane-head strong {
 font-size: 13px;
}

.eligibility-qc-pane-head span {
 min-width: 0;
 color: var(--muted);
 font-size: 11px;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.eligibility-qc-pane-head .icon-button {
 width: 32px;
 height: 32px;
 flex: 0 0 auto;
}

.eligibility-qc-progress {
 padding: 8px 10px;
 display: grid;
 gap: 5px;
 border-bottom: 1px solid var(--soft-line);
 background: #fff;
}

.eligibility-qc-progress > div {
 display: flex;
 align-items: center;
 justify-content: space-between;
 color: var(--muted);
 font-size: 11px;
}

.eligibility-qc-progress > div strong {
 color: var(--text);
}

.eligibility-qc-progress > span {
 height: 5px;
 overflow: hidden;
 border-radius: 2px;
 background: #e9edf1;
}

.eligibility-qc-progress i {
 height: 100%;
 display: block;
 background: var(--orange);
}

.eligibility-qc-filters {
 padding: 7px 8px;
 display: grid;
 grid-template-columns: repeat(5, minmax(0, 1fr));
 gap: 4px;
 border-bottom: 1px solid var(--soft-line);
 background: #fbfcfd;
}

.eligibility-qc-filters button,
.eligibility-qc-image-tools button,
.eligibility-qc-paging button,
.eligibility-qc-result-options button {
 min-height: 30px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--muted);
 font-size: 11px;
}

.eligibility-qc-filters button.active,
.eligibility-qc-image-tools button.active {
 border-color: #d99854;
 background: #fff6ee;
 color: var(--orange-dark);
 font-weight: 700;
}

.eligibility-qc-queue-list {
 min-height: 0;
 flex: 1;
 overflow-y: auto;
 scrollbar-width: thin;
}

.eligibility-qc-queue-list > button {
 width: 100%;
 min-height: 58px;
 padding: 7px 8px;
 display: grid;
 grid-template-columns: 32px minmax(0, 1fr) auto;
 align-items: center;
 gap: 7px;
 border: 0;
 border-bottom: 1px solid var(--soft-line);
 background: #fff;
 color: var(--text);
 text-align: left;
}

.eligibility-qc-queue-list > button:hover,
.eligibility-qc-queue-list > button.selected {
 background: #fff8f3;
}

.eligibility-qc-queue-list > button.selected {
 box-shadow: inset 3px 0 0 var(--orange);
}

.eligibility-qc-sequence {
 color: #8a949e;
 font-size: 11px;
 font-variant-numeric: tabular-nums;
}

.eligibility-qc-queue-copy {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.eligibility-qc-queue-copy strong,
.eligibility-qc-queue-copy small {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.eligibility-qc-queue-copy strong {
 font-size: 12px;
}

.eligibility-qc-queue-copy small {
 color: var(--muted);
 font-size: 10px;
}

.eligibility-qc-queue-list .tag {
 max-width: 76px;
 min-height: 24px;
 padding: 2px 5px;
 white-space: normal;
 line-height: 1.2;
 text-align: center;
}

.eligibility-qc-empty {
 margin: 0;
 padding: 18px 12px;
 color: var(--muted);
 font-size: 12px;
 text-align: center;
}

.eligibility-qc-paging {
 flex: 0 0 42px;
 padding: 6px 8px;
 justify-content: space-between;
 gap: 6px;
 border-top: 1px solid var(--line);
 background: #fbfcfd;
}

.eligibility-qc-paging button {
 min-width: 64px;
 padding: 0 7px;
}

.eligibility-qc-paging span {
 color: var(--muted);
 font-size: 10px;
}

.eligibility-qc-image-tools {
 flex: 0 0 auto;
 gap: 4px;
}

.eligibility-qc-image-tools button {
 min-width: 32px;
 padding: 0 7px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
}

.eligibility-qc-image-tools span {
 width: 42px;
 color: var(--text);
 text-align: center;
 font-variant-numeric: tabular-nums;
}

.eligibility-qc-image-stage {
 min-height: 0;
 flex: 1;
 padding: 18px;
 overflow: auto;
 background: #eef1f4;
 text-align: center;
}

.eligibility-qc-image-stage img {
 display: block;
 max-width: none;
 margin: 0 auto;
 background: #fff;
 box-shadow: 0 1px 6px rgba(32, 36, 42, 0.18);
}

.eligibility-qc-image-stage img.fit {
 width: auto;
 height: auto;
 max-width: 100%;
 max-height: 100%;
}

.eligibility-qc-empty-stage {
 min-height: 100%;
 display: flex;
 align-items: center;
 justify-content: center;
 flex-direction: column;
 gap: 8px;
 color: var(--muted);
 font-size: 12px;
}

.eligibility-qc-review-scroll {
 min-height: 0;
 flex: 1;
 overflow-y: auto;
 scrollbar-width: thin;
}

.eligibility-qc-meta {
 margin: 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 border-bottom: 1px solid var(--line);
}

.eligibility-qc-meta > div {
 min-width: 0;
 padding: 8px 10px;
 display: grid;
 gap: 2px;
 border-right: 1px solid var(--soft-line);
 border-bottom: 1px solid var(--soft-line);
}

.eligibility-qc-meta > div:nth-child(2n) {
 border-right: 0;
}

.eligibility-qc-meta dt {
 color: var(--muted);
 font-size: 10px;
}

.eligibility-qc-meta dd {
 min-width: 0;
 margin: 0;
 overflow: hidden;
 color: var(--text);
 font-size: 11px;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.eligibility-qc-text-block,
.eligibility-qc-form {
 padding: 10px;
 border-bottom: 1px solid var(--line);
}

.eligibility-qc-text-block > div {
 margin-bottom: 7px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.eligibility-qc-text-block > div span {
 color: var(--muted);
 font-size: 10px;
}

.eligibility-qc-text-block pre {
 min-height: 220px;
 max-height: 330px;
 margin: 0;
 padding: 9px;
 overflow: auto;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fbfcfd;
 color: #30363d;
 font-family: inherit;
 font-size: 12px;
 line-height: 1.65;
 white-space: pre-wrap;
 word-break: break-word;
}

.eligibility-qc-form {
 display: grid;
 gap: 9px;
 border-bottom: 0;
}

.eligibility-qc-result-options {
 display: grid;
 grid-template-columns: repeat(3, minmax(0, 1fr));
 gap: 5px;
}

.eligibility-qc-result-options button {
 min-height: 38px;
 padding: 4px 6px;
 color: var(--text);
 line-height: 1.25;
}

.eligibility-qc-result-options button.active {
 font-weight: 700;
}

.eligibility-qc-result-options button.active.success {
 border-color: #83bb97;
 background: var(--success-bg);
 color: var(--success);
}

.eligibility-qc-result-options button.active.danger {
 border-color: #e3a5a5;
 background: var(--danger-bg);
 color: var(--danger);
}

