 background: #fbfcfd;
 display: grid;
 grid-template-columns: minmax(300px, 0.75fr) minmax(0, 1.55fr);
 align-items: center;
 gap: 6px;
}

.writing-intervention-projection-conflict {
 min-height: 42px;
 margin-bottom: 7px;
 padding: 7px 9px;
 border: 1px solid #e5b56f;
 border-left: 3px solid #b85c20;
 background: #fffaf2;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
}

.writing-intervention-projection-conflict > div:first-child {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 gap: 8px;
 color: #7e4219;
}

.writing-intervention-projection-conflict span {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.writing-intervention-projection-conflict strong {
 font-size: 12px;
}

.writing-intervention-projection-conflict small {
 color: #8b6849;
 font-size: 11px;
 overflow-wrap: anywhere;
}

.writing-intervention-projection-conflict-actions {
 display: flex;
 flex: 0 0 auto;
 gap: 6px;
}

.writing-intervention-projection-conflict-actions button {
 min-height: 30px;
 white-space: nowrap;
}

.working-copy-status-main {
 display: flex;
 gap: 6px;
 align-items: center;
 min-width: 0;
}

.working-copy-status-main > .working-copy-identity {
 min-width: 0;
 display: flex;
 align-items: baseline;
 gap: 5px;
}

.working-copy-status-main span,
.working-copy-status-main time,
.working-copy-status-bar > p {
 color: var(--muted);
 font-size: 11px;
}

.working-copy-status-main strong {
 min-width: 0;
 font-size: 12px;
 overflow-wrap: anywhere;
}

.working-copy-status-main .working-copy-save-state {
 padding-left: 6px;
 border-left: 1px solid var(--soft-line);
 white-space: nowrap;
}

.working-copy-status-main time {
 margin-left: auto;
 white-space: nowrap;
}

.working-copy-status-bar > p {
 margin: 0;
}

.working-copy-actions {
 display: flex;
 flex-wrap: nowrap;
 justify-content: flex-end;
 gap: 5px;
 overflow-x: auto;
}

.working-copy-actions button {
 min-height: 26px;
 padding: 0 7px;
 display: inline-flex;
 align-items: center;
 gap: 4px;
 font-size: 12px;
}

.working-copy-actions .content-quality-trigger.has-blocking {
 border-color: #efb58f;
 background: #fff7f2;
 color: #a44712;
}

.working-copy-actions .content-quality-trigger.is-clear {
 border-color: #b9d9c2;
 background: #f3fbf5;
 color: #24663a;
}

.document-export-progress {
 grid-column: 1 / -1;
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(120px, 0.3fr) minmax(0, 1fr) auto;
 align-items: center;
 gap: 8px;
 padding: 2px 2px 0;
 color: var(--muted);
 font-size: 11px;
}

.document-export-progress-track {
 height: 4px;
 border-radius: 2px;
 overflow: hidden;
 background: #e2e7ed;
}

.document-export-progress-track > span {
 display: block;
 height: 100%;
 border-radius: inherit;
 background: var(--orange);
 transition: width 180ms ease;
}

.document-export-progress strong {
 min-width: 0;
 overflow: hidden;
 color: var(--text);
 font-size: 11px;
 font-weight: 600;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.document-export-progress > span {
 white-space: nowrap;
}

.medical-writing-preview-panel {
 margin: 0 0 8px;
 padding: 10px 12px;
 border: 1px solid #e4b36f;
 border-left: 3px solid #c87919;
 border-radius: 6px;
 background: #fffaf2;
 color: var(--text);
}

.medical-writing-preview-panel.verified {
 border-color: #b8d9c0;
 border-left-color: #2f7b45;
 background: #f5fbf6;
}

.medical-writing-preview-panel.stale {
 border-color: #e5b3b3;
 border-left-color: #b33d3d;
 background: #fff7f7;
}

.medical-writing-preview-panel-header,
.medical-writing-preview-panel-actions,
.medical-writing-preview-summary,
.medical-writing-preview-meta {
 display: flex;
 align-items: center;
}

.medical-writing-preview-panel-header {
 justify-content: space-between;
 gap: 10px;
}

.medical-writing-preview-panel-header > div:first-child {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.medical-writing-preview-eyebrow {
 color: var(--muted);
 font-size: 10px;
}

.medical-writing-preview-panel-header strong {
 font-size: 13px;
}

.medical-writing-preview-panel-actions {
 gap: 4px;
}

.medical-writing-preview-panel-actions button {
 min-height: 25px;
 padding: 0 7px;
 display: inline-flex;
 align-items: center;
 gap: 4px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
 font-size: 11px;
}

.medical-writing-preview-panel-actions .medical-writing-preview-close {
 width: 25px;
 justify-content: center;
 padding: 0;
}

.medical-writing-preview-summary {
 align-items: flex-start;
 gap: 12px;
 margin-top: 8px;
}

.medical-writing-preview-page-count {
 flex: 0 0 auto;
 display: flex;
 align-items: center;
 gap: 6px;
 color: #a44712;
}

.medical-writing-preview-panel.verified .medical-writing-preview-page-count {
 color: #24663a;
}

.medical-writing-preview-page-count span {
 display: grid;
 gap: 1px;
}

.medical-writing-preview-page-count strong {
 font-size: 16px;
}

.medical-writing-preview-page-count small {
 color: var(--muted);
 font-size: 10px;
 white-space: nowrap;
}

.medical-writing-preview-summary p,
.medical-writing-preview-warning,
.medical-writing-preview-message,
.medical-writing-preview-more {
 margin: 0;
 font-size: 11px;
 line-height: 1.5;
}

.medical-writing-preview-summary p {
 color: var(--muted);
}

.medical-writing-preview-warning {
 margin-top: 7px;
 color: #7e4b10;
}

.medical-writing-preview-panel.verified .medical-writing-preview-warning {
 color: #24663a;
}

.medical-writing-preview-message {
 margin-top: 6px;
 color: #a44712;
}

.medical-writing-preview-meta {
 flex-wrap: wrap;
 gap: 8px 14px;
 margin-top: 8px;
 color: var(--muted);
 font-size: 10px;
}

.medical-writing-preview-meta code {
 padding: 1px 3px;
 border-radius: 3px;
 background: rgba(0, 0, 0, 0.04);
 color: var(--text);
 font-size: 10px;
}

.medical-writing-preview-pages {
 display: grid;
 grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
 gap: 5px;
 margin: 8px 0 0;
 padding: 0;
 list-style: none;
}

.medical-writing-preview-pages li {
 min-width: 0;
 padding: 5px 7px;
 display: grid;
 gap: 2px;
 border: 1px solid rgba(123, 91, 45, 0.18);
 border-radius: 4px;
 background: rgba(255, 255, 255, 0.7);
}

.medical-writing-preview-pages li span {
 font-size: 11px;
 font-weight: 650;
}

.medical-writing-preview-pages li small {
 color: var(--muted);
 font-size: 10px;
}

.medical-writing-preview-more {
 margin-top: 7px;
 color: var(--muted);
}

.approval-lock button {
 min-height: 28px;
 flex: 0 0 auto;
 white-space: nowrap;
}

.writing-editor-blocker {
 min-height: 34px;
 margin-bottom: 5px;
 padding: 4px 7px;
 border: 1px solid #e5b56f;
 border-left: 3px solid #c87919;
 border-radius: 3px;
 background: #fffaf2;
 display: flex;
 align-items: center;
 gap: 7px;
 color: #7e4b10;
}

.writing-editor-blocker > strong {
 min-width: 0;
 flex: 1 1 auto;
 color: var(--text);
 font-size: 12px;
 line-height: 1.35;
}

.writing-editor-blocker details {
 position: relative;
 flex: 0 0 auto;
 color: var(--muted);
 font-size: 11px;
}

.writing-editor-blocker summary {
 cursor: pointer;
 white-space: nowrap;
}

.writing-editor-blocker details[open] {
 align-self: flex-start;
 max-width: min(520px, 48vw);
}

.writing-editor-blocker details p {
 margin: 5px 0 0;
 color: var(--muted);
 line-height: 1.45;
 overflow-wrap: anywhere;
}

.writing-editor-blocker > button {
 min-height: 26px;
 padding: 0 8px;
 flex: 0 0 auto;
 white-space: nowrap;
 font-size: 12px;
}

.writing-drafting-readiness {
 margin-bottom: 5px;
 padding: 7px 9px;
 border: 1px solid #c9d8e9;
 border-left: 3px solid #4e78a5;
 border-radius: 3px;
 background: #f7faff;
 display: flex;
 align-items: flex-start;
 gap: 8px;
 color: #315b86;
}

.writing-drafting-readiness > div {
 min-width: 0;
 flex: 1 1 auto;
 display: grid;
 gap: 2px;
}

.writing-drafting-readiness strong {
 color: var(--text);
 font-size: 12px;
 line-height: 1.35;
}

.writing-drafting-readiness span,
.writing-drafting-readiness summary,
.writing-drafting-readiness li {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.writing-drafting-readiness summary {
 width: fit-content;
 cursor: pointer;
}

.writing-drafting-readiness ul {
 margin: 4px 0 0;
 padding-left: 18px;
}

.writing-drafting-readiness > button {
 min-height: 28px;
 padding: 0 9px;
 flex: 0 0 auto;
 white-space: nowrap;
}

.writing-version-panel {
 min-width: 0;
 display: grid;
 align-content: start;
 gap: 12px;
}

.writing-version-panel > header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
 padding-bottom: 9px;
 border-bottom: 1px solid var(--line);
}

.writing-version-panel > header > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.writing-version-panel > header span,
.writing-version-summary span,
.writing-quarantine-entry span,
.writing-freeze-history-list span {
 color: var(--muted);
 font-size: 11px;
}

.writing-version-panel > header strong {
 font-size: 15px;
}

.writing-version-panel > header button,
.writing-binding-recovery-actions button {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.writing-version-summary {
 display: grid;
 grid-template-columns: repeat(3, minmax(0, 1fr));
 gap: 8px;
}

.writing-version-summary > div {
 min-width: 0;
 display: grid;
 align-content: start;
 gap: 4px;
}

.writing-version-summary strong {
 font-size: 12px;
 overflow-wrap: anywhere;
}

.writing-version-message,
.writing-version-readiness p,
.writing-quarantine-entry p {
 margin: 0;
 font-size: 12px;
 line-height: 1.55;
 overflow-wrap: anywhere;
}

.writing-version-message.danger {
 padding: 7px 8px;
 border-left: 3px solid var(--danger);
 background: var(--danger-bg);
 color: var(--danger);
}

.writing-version-readiness {
 display: grid;
 justify-items: start;
 gap: 6px;
 padding: 8px 0;
 border-top: 1px solid var(--line);
 border-bottom: 1px solid var(--line);
}

.writing-version-disclosure {
 min-width: 0;
 border-bottom: 1px solid var(--line);
 padding-bottom: 8px;
}

.writing-version-disclosure > summary {
 min-height: 32px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
 cursor: pointer;
 font-size: 12px;
 font-weight: 700;
 list-style: none;
}

.writing-version-disclosure > summary::-webkit-details-marker {
 display: none;
}

.writing-quarantine-entry,
.writing-freeze-history-list {
 display: grid;
 gap: 8px;
 padding-top: 8px;
}

.writing-quarantine-entry > div:first-child,
.writing-freeze-history-list > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.writing-quarantine-entry > p {
 color: #7e4b10;
}

.writing-binding-recovery-form {
 display: grid;
 gap: 9px;
 padding-top: 9px;
 border-top: 1px dashed #d5ad74;
}

.writing-binding-recovery-form > label:not(.writing-binding-recovery-check) {
 display: grid;
 gap: 5px;
 font-size: 12px;
 font-weight: 700;
}

.writing-binding-recovery-form textarea {
 min-height: 84px;
 resize: vertical;
}

.writing-binding-recovery-check {
 display: grid;
 grid-template-columns: 16px minmax(0, 1fr);
 align-items: start;
 gap: 7px;
 color: var(--muted);
 font-size: 11px;
 line-height: 1.5;
}

.writing-binding-recovery-check input {
 margin: 2px 0 0;
}

.writing-binding-recovery-actions {
 display: flex;
 flex-wrap: wrap;
 justify-content: flex-end;
 gap: 7px;
}

.writing-freeze-history-list > div {
 padding: 7px 0;
 border-top: 1px solid #edf0f3;
}

.writing-freeze-history-list > div:first-child {
 border-top: 0;
}

.writing-freeze-history-list > div.is-current {
 padding-left: 7px;
 border-left: 3px solid var(--success);
}

.writing-freeze-history-list > div > div {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.writing-freeze-history-list strong {
 font-size: 12px;
}

.writing-content-quality-dock {
 position: fixed;
 right: 18px;
 bottom: 18px;
 z-index: 52;
 width: min(1080px, calc(100vw - 230px));
 height: min(680px, calc(100vh - 112px));
 min-height: 480px;
 display: grid;
 grid-template-rows: auto auto auto auto minmax(0, 1fr) auto;
 overflow: hidden;
 border: 1px solid #efb58f;
 border-radius: 6px;
 background: #fff;
 box-shadow: 0 18px 50px rgba(45, 52, 60, 0.22);
}

.writing-content-quality-head {
 min-height: 52px;
 padding: 8px 12px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 border-bottom: 1px solid var(--line);
 background: #fffaf6;
}

.writing-content-quality-head > div {
 min-width: 0;
 display: flex;
 align-items: center;
 gap: 8px;
}

.writing-content-quality-head > div:first-child {
 overflow: hidden;
}

.writing-content-quality-head strong {
 flex: 0 0 auto;
 font-size: 15px;
}

.writing-content-quality-head span:not(.tag) {
 min-width: 0;
 color: var(--muted);
 font-size: 12px;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.writing-content-quality-summary {
 min-height: 44px;
 padding: 6px 12px;
 display: flex;
 align-items: center;
 gap: 18px;
 border-bottom: 1px solid var(--soft-line);
 background: #fbfcfd;
 color: var(--muted);
 font-size: 12px;
}

.writing-content-quality-summary span {
 display: inline-flex;
 align-items: baseline;
 gap: 4px;
 white-space: nowrap;
}

.writing-content-quality-summary strong {
 color: var(--text);
 font-size: 15px;
}

.writing-content-quality-summary button,
.writing-content-disposition-actions button {
 min-height: 32px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.writing-content-quality-summary button {
 margin-left: auto;
}

.writing-content-quality-message,
.writing-content-quality-unsaved {
 margin: 0;
 padding: 7px 12px;
 border-bottom: 1px solid var(--soft-line);
 background: var(--info-bg);
 color: var(--info);
 font-size: 12px;
 overflow-wrap: anywhere;
}

.writing-content-quality-message.danger {
 background: var(--danger-bg);
 color: var(--danger);
}

.writing-content-quality-unsaved {
 background: var(--warning-bg);
 color: var(--warning);
}

.writing-content-quality-body {
 min-height: 0;
 display: grid;
 grid-template-columns: 290px minmax(0, 1fr);
}

.writing-content-quality-list {
 min-width: 0;
 min-height: 0;
 padding: 8px;
 display: grid;
 align-content: start;
 gap: 6px;
 overflow-y: auto;
 border-right: 1px solid var(--line);
 background: #f8f9fa;
}

.writing-content-quality-list > button {
 width: 100%;
 min-width: 0;
 min-height: 92px;
 padding: 9px;
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 gap: 5px 8px;
 text-align: left;
 background: #fff;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
}

.writing-content-quality-list > button:hover,
.writing-content-quality-list > button.active {
 border-color: #efb58f;
 background: #fff9f5;
}

.writing-content-quality-list > button > span:first-child {
 min-width: 0;
 color: #8b4a21;
 font-size: 12px;
 font-weight: 700;
 overflow-wrap: anywhere;
}

.writing-content-quality-list > button > strong {
 grid-column: 1 / -1;
 min-width: 0;
 max-height: 42px;
 color: var(--text);
 font-size: 12px;
 line-height: 1.5;
 overflow: hidden;
 overflow-wrap: anywhere;
}

.writing-content-quality-list .tag {
 justify-self: end;
}

.writing-content-quality-detail {
 min-width: 0;
 min-height: 0;
 padding: 14px 16px;
 overflow-y: auto;
}

.writing-content-primary-evidence {
 padding: 0 0 14px 12px;
 border-left: 3px solid var(--orange);
 border-bottom: 1px solid var(--soft-line);
}

.writing-content-primary-evidence > div {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 color: var(--muted);
 font-size: 12px;
}

.writing-content-primary-evidence blockquote {
 max-height: 210px;
 margin: 10px 0;
 padding: 10px 12px;
 overflow-y: auto;
 border: 1px solid #f0d7c6;
 border-radius: 4px;
 background: #fffaf6;
 color: #2f3338;
 font-size: 15px;
 line-height: 1.7;
 overflow-wrap: anywhere;
}

.writing-content-primary-evidence mark {
 padding: 1px 3px;
 background: #ffd6bd;
 color: #8f3100;
 font-weight: 800;
}

.writing-content-primary-evidence p {
 margin: 0;
 color: #515861;
 font-size: 13px;
 line-height: 1.55;
}

.writing-content-traceability {
 padding: 10px 0;
 border-bottom: 1px solid var(--soft-line);
}

.writing-content-traceability summary {
 color: var(--muted);
 font-size: 12px;
 cursor: pointer;
}

.writing-content-traceability dl {
 margin: 10px 0 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 8px 14px;
}

.writing-content-traceability dl > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.writing-content-traceability dt {
 color: var(--muted);
 font-size: 11px;
}

.writing-content-traceability dd {
 margin: 0;
 color: var(--text);
 font-size: 12px;
 overflow-wrap: anywhere;
}

.writing-content-prior-disposition {
 padding: 10px 0;
 border-bottom: 1px solid var(--soft-line);
}

.writing-content-prior-disposition span,
.writing-content-prior-disposition small {
 color: var(--muted);
 font-size: 11px;
}

.writing-content-prior-disposition p {
 margin: 5px 0;
 color: var(--text);
 font-size: 13px;
 line-height: 1.5;
 overflow-wrap: anywhere;
}

.writing-content-disposition-form {
 padding-top: 12px;
 display: grid;
 gap: 10px;
}

.writing-content-disposition-form > label:first-child {
 display: grid;
 gap: 6px;
 color: var(--text);
 font-size: 12px;
 font-weight: 700;
}

.writing-content-disposition-form textarea {
 min-height: 78px;
 resize: vertical;
 font-weight: 400;
}

.writing-content-acknowledgement {
 display: grid;
 grid-template-columns: 16px minmax(0, 1fr);
 align-items: start;
 gap: 7px;
 color: #5e5148;
 font-size: 12px;
 line-height: 1.5;
}

.writing-content-acknowledgement input {
 margin-top: 2px;
}

.writing-content-disposition-actions {
 display: flex;
 flex-wrap: wrap;
 gap: 8px;
}

.writing-content-quality-clear {
 min-height: 0;
 display: grid;
 place-content: center;
 justify-items: center;
 gap: 8px;
 padding: 28px;
 color: var(--success);
 text-align: center;
}

.writing-content-quality-clear p {
 max-width: 560px;
 margin: 0;
 color: var(--muted);
 font-size: 12px;
}

.writing-content-quality-dock > footer {
 min-height: 32px;
 padding: 7px 12px;
 border-top: 1px solid var(--line);
 background: #fbfcfd;
 color: var(--muted);
 font-size: 11px;
}

.working-copy-message {
 border: 1px solid #c9ddff;
 border-radius: 4px;
 background: var(--info-bg);
 color: var(--info);
 padding: 8px 10px;
 margin-bottom: 10px;
 font-size: 12px;
 overflow-wrap: anywhere;
}

.working-copy-message.danger {
 border-color: #ffc9c9;
 background: var(--danger-bg);
 color: var(--danger);
}

.working-copy-load-error,
.working-copy-recovery-prompt {
 min-height: 42px;
 margin-bottom: 8px;
 padding: 8px 10px;
 border: 1px solid #efb58f;
 border-left: 3px solid #b85c20;
 background: #fff8f3;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 color: #7e4219;
 font-size: 12px;
}

.working-copy-load-error > span {
 min-width: 0;
 overflow-wrap: anywhere;
}

.working-copy-load-error button,
.working-copy-recovery-prompt button {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 gap: 5px;
 white-space: nowrap;
}

.working-copy-recovery-prompt {
 border-color: #c9ddff;
 border-left-color: #4f7fc4;
 background: #f5f9ff;
 color: #315f9f;
}

.working-copy-recovery-prompt.is-conflict {
 border-color: #efb58f;
 border-left-color: #b85c20;
 background: #fff8f3;
 color: #7e4219;
}

.working-copy-recovery-prompt > div:first-child {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.working-copy-recovery-prompt > div:last-child {
 display: flex;
 flex: 0 0 auto;
 gap: 6px;
}

.working-copy-recovery-prompt span,
.working-copy-recovery-prompt small {
 overflow-wrap: anywhere;
}

.writing-unsaved-navigation-backdrop {
 position: fixed;
 inset: 0;
 z-index: 150;
 padding: 24px;
 background: rgba(28, 35, 42, 0.32);
 display: grid;
 place-items: center;
}

.writing-unsaved-navigation-backdrop.app-navigation-guard {
 z-index: 180;
}

.writing-unsaved-navigation-dialog {
 width: min(520px, calc(100vw - 48px));
 padding: 18px;
 border: 1px solid #e0a96a;
 border-radius: 6px;
 background: #fff;
 box-shadow: 0 22px 64px rgba(24, 33, 42, 0.28);
 display: grid;
 gap: 18px;
}

.writing-unsaved-navigation-dialog > header {
 display: grid;
 grid-template-columns: 22px minmax(0, 1fr);
 gap: 10px;
 color: #8a520d;
}

.writing-unsaved-navigation-dialog > header > div {
 min-width: 0;
 display: grid;
 gap: 5px;
}

.writing-unsaved-navigation-dialog > header strong {
 color: var(--text);
 font-size: 16px;
}

.writing-unsaved-navigation-dialog > header span {
 color: var(--muted);
 line-height: 1.55;
 overflow-wrap: anywhere;
}

.writing-unsaved-navigation-actions {
 display: flex;
 justify-content: flex-end;
 gap: 8px;
}

.writing-unsaved-navigation-actions button {
 min-height: 34px;
}

@media (min-width: 1281px) and (max-height: 920px) {
 .writing-editor-first-layout {
 height: calc(100vh - 154px);
 min-height: 0;
 }

 .writing-editor-core,
 .writing-ai-core {
 min-height: 0;
 }

 .working-copy-status-bar {
 flex: 0 0 auto;
 }
}

.rich-editor-shell {
 flex: 1;
 display: flex;
 flex-direction: column;
 gap: 10px;
 min-height: 0;
 overflow: hidden;
}

.rich-editor-shell.document-fullscreen {
 position: fixed;
 inset: 8px;
 z-index: 120;
 padding: 10px 12px 12px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 box-shadow: 0 18px 54px rgba(24, 33, 42, 0.24);
}

.rich-editor-fullscreen-actions {
 min-width: 0;
 margin-left: auto;
 display: flex;
 align-items: center;
 gap: 5px;
}

.rich-editor-fullscreen-actions > span {
 max-width: 150px;
 padding: 4px 7px;
 border: 1px solid var(--line);
 background: #f7f8fa;
 color: var(--muted);
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.rich-editor-fullscreen-actions > span.is-dirty {
 border-color: #e5b56f;
 background: #fff9ef;
 color: #8a520d;
}

.rich-editor-fullscreen-actions button {
 min-height: 28px;
 padding: 0 8px;
 display: inline-flex;
 align-items: center;
 gap: 5px;
 white-space: nowrap;
}

.rich-editor-fullscreen-actions .rich-editor-fullscreen-save {
 border-color: var(--orange);
 background: #fff8f3;
 color: var(--orange-dark);
 font-weight: 700;
}

.rich-editor-shell.document-fullscreen .rich-editor-fullscreen-button {
 margin-left: 0;
 flex: 0 0 auto;
}

.real-document-session-blocked .blocked-editor-canvas {
 min-height: 520px;
 padding: 32px 36px;
 background: #fbfcfd;
 color: var(--muted);
}

.real-document-session-blocked .blocked-editor-canvas h2 {
 color: var(--text);
 font-size: 20px;
 margin: 0 0 16px;
}

.authoring-journey-shell {
 flex: 1;
 min-height: 0;
 display: flex;
 flex-direction: column;
 gap: 10px;
 padding: 3px 2px 2px;
 overflow: hidden;
}

/* Authoring details must follow native disclosure semantics. Component-level
 display rules otherwise keep collapsed field cards in the layout, so the
 journey scroll container cannot expose the controls when the user opens it. */
.authoring-journey-shell details:not([open]) > :not(summary) {
 display: none !important;
}

.authoring-journey-header,
.authoring-journey-footer,
.authoring-stage-strip,
.authoring-group-tabs,
.authoring-impact-actions,
.authoring-corpus-stage > header,
.authoring-search-plan > div:first-child,
.authoring-writing-entry,
.authoring-writing-entry > div {
 display: flex;
 align-items: center;
}

.authoring-journey-header {
 min-height: 48px;
 justify-content: space-between;
 gap: 16px;
 padding-bottom: 9px;
 border-bottom: 1px solid var(--line);
}

.authoring-journey-header > div:first-child,
.authoring-journey-state,
.authoring-field-section > header,
.authoring-corpus-stage > header > div,
.authoring-search-plan > div:first-child > span,
.authoring-writing-entry > div > span {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.authoring-journey-header span,
.authoring-journey-state small,
.authoring-field-section > header span,
.authoring-field > span,
.authoring-corpus-stage > header span,
.authoring-search-plan small,
.authoring-writing-entry small,
.authoring-journey-footer > span {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.authoring-journey-header h2 {
 margin: 0;
 color: var(--text);
 font-size: 18px;
 line-height: 1.35;
}

.authoring-focus-context {
 width: fit-content;
 max-width: 100%;
 overflow: hidden;
 border-left: 2px solid var(--brand);
 padding-left: 7px;
 color: var(--text-secondary) !important;
 font-size: 11px;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.authoring-journey-state {
 grid-template-columns: auto auto;
 column-gap: 8px;
 text-align: right;
}

.authoring-journey-state small {
 grid-column: 1 / -1;
}

.authoring-entry-mode,
.synopsis-import-stage {
 min-width: 0;
 display: grid;
 gap: 12px;
 align-content: start;
}

.authoring-entry-mode > header,
.synopsis-import-stage > header,
.synopsis-source-review > header,
.synopsis-extraction-review > header,
.synopsis-validation-review > header,
.synopsis-findings-grid section > header {
 min-width: 0;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
}

.authoring-entry-mode > header > div,
.synopsis-import-stage > header > div,
.synopsis-extraction-review > header > div,
.synopsis-validation-review > header > div,
.synopsis-validation-review > header > div > span {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.authoring-entry-mode > header span,
.synopsis-import-stage > header span,
.synopsis-source-review > header small,
.synopsis-extraction-review > header span,
.synopsis-extraction-review > header small,
.synopsis-validation-review > header small {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.authoring-entry-mode-options {
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
}

.authoring-entry-mode-options > button {
 width: 100%;
 min-width: 0;
 min-height: 64px;
 display: grid;
 grid-template-columns: 28px minmax(0, 1fr) auto;
 align-items: center;
 gap: 10px;
 border: 0;
 border-bottom: 1px solid var(--line);
 border-radius: 0;
 padding: 10px 12px;
 background: #fff;
 color: var(--text);
 text-align: left;
}

.authoring-entry-mode-options > button:last-child {
 border-bottom: 0;
}

.authoring-entry-mode-options > button:hover:not(:disabled),
.authoring-entry-mode-options > button:focus-visible {
 background: #fff7f1;
 color: var(--brand);
}

.authoring-entry-mode-options > button > span {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.authoring-entry-mode-options small,
.authoring-entry-mode > p {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.authoring-entry-mode > p {
 display: flex;
 align-items: center;
 gap: 6px;
 margin: 0;
}

.synopsis-import-status,
.synopsis-validation {
 display: inline-flex;
 align-items: center;
 width: max-content;
 max-width: 100%;
 border: 1px solid currentColor;
 border-radius: 3px;
 padding: 3px 6px;
 font-size: 11px;
 line-height: 1.2;
}

.synopsis-import-status.pending,
.synopsis-validation.not_assessed {
 background: #f7f8fa;
 color: var(--muted);
}

.synopsis-import-status.review,
.synopsis-validation.warning {
 background: var(--warning-bg);
 color: var(--warning);
}

.synopsis-validation.mismatch {
 background: var(--danger-bg);
 color: var(--danger);
}

.synopsis-validation.matched {
 background: var(--success-bg);
 color: var(--success);
}

.synopsis-upload-bar {
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 align-items: stretch;
 gap: 8px;
}

.synopsis-file-picker {
 min-width: 0;
 min-height: 54px;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 align-items: center;
 gap: 9px;
 border: 1px dashed #d6aa8a;
 border-radius: 4px;
 padding: 8px 10px;
 background: #fffaf6;
 color: var(--brand);
 cursor: pointer;
}

.synopsis-file-picker input {
 position: absolute;
 width: 1px;
 height: 1px;
 overflow: hidden;
 clip: rect(0 0 0 0);
 white-space: nowrap;
 clip-path: inset(50%);
}

.synopsis-file-picker > span {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.synopsis-file-picker strong,
.synopsis-file-picker small {
 min-width: 0;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.synopsis-file-picker small {
 color: var(--muted);
 font-size: 11px;
}

.synopsis-upload-bar > button,
.synopsis-import-footer > button {
 min-height: 36px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 6px;
}

.synopsis-source-review,
.synopsis-extraction-review,
.synopsis-validation-review {
 min-width: 0;
 display: grid;
 gap: 9px;
 border-top: 1px solid var(--line);
 padding-top: 10px;
}

.synopsis-source-review dl {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(3, minmax(0, 1fr));
 margin: 0;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
}

.synopsis-source-review dl > div {
 min-width: 0;
 display: grid;
 grid-template-columns: 72px minmax(0, 1fr);
 align-items: center;
 gap: 8px;
 padding: 8px 9px;
 border-right: 1px solid var(--soft-line);
 border-bottom: 1px solid var(--soft-line);
}

.synopsis-source-review dl > div:nth-child(3n) {
 border-right: 0;
}

.synopsis-source-review dl > div:nth-last-child(-n + 3) {
 border-bottom: 0;
}

.synopsis-source-review dt {
 color: var(--muted);
 font-size: 11px;
}

.synopsis-source-review dd {
 min-width: 0;
 margin: 0;
 overflow: hidden;
 color: var(--text);
 font-size: 12px;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.synopsis-findings-grid {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 8px;
}

.synopsis-findings-grid section {
 min-width: 0;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 9px 10px;
 background: #fff;
}

.synopsis-findings-grid section > header span {
 color: var(--muted);
 font-size: 11px;
}

.synopsis-findings-grid ul {
 display: flex;
 flex-wrap: wrap;
 gap: 5px;
 margin: 8px 0 0;
 padding: 0;
 list-style: none;
}

.synopsis-findings-grid li {
 border: 1px solid #e8cba7;
 border-radius: 3px;
 padding: 3px 6px;
 background: #fffaf1;
 color: var(--text-secondary);
 font-size: 11px;
 overflow-wrap: anywhere;
}

.synopsis-findings-grid p {
 margin: 8px 0 0;
 color: var(--muted);
 font-size: 11px;
}

.synopsis-instrument-candidates {
 min-width: 0;
 display: grid;
 gap: 8px;
 border-top: 1px solid var(--line);
 padding-top: 10px;
}

.synopsis-instrument-candidates > header {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 16px;
}

.synopsis-instrument-candidates > header > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.synopsis-instrument-candidates > header span,
.synopsis-instrument-candidates > header small {
 color: var(--muted);
 font-size: 11px;
}

.synopsis-instrument-candidates > div {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 6px;
}

.synopsis-instrument-candidates article {
 min-width: 0;
 display: grid;
 grid-template-columns: 52px minmax(0, 1fr) auto;
 align-items: start;
 gap: 9px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 8px 9px;
 background: #fff;
}

.synopsis-instrument-candidates article > span {
 overflow: hidden;
 border-radius: 3px;
 padding: 4px 5px;
 background: #eef5ff;
 color: #2559a7;
 font-size: 11px;
 font-weight: 700;
 text-align: center;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.synopsis-instrument-summary {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.synopsis-instrument-candidates article strong,
.synopsis-instrument-candidates article small {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.synopsis-instrument-candidates article small {
 color: var(--muted);
 font-size: 11px;
}

.synopsis-instrument-candidates article em {
 color: var(--warning);
 font-size: 11px;
 font-style: normal;
 white-space: nowrap;
}

.synopsis-instrument-evidence {
 min-width: 0;
 grid-column: 1 / -1;
 display: grid;
 gap: 5px;
 border-top: 1px solid #e6ebf1;
 padding-top: 7px;
}

.synopsis-instrument-evidence > div,
.synopsis-instrument-evidence details > div {
 min-width: 0;
 display: grid;
 grid-template-columns: 34px minmax(0, 1fr);
 gap: 3px 7px;
}

.synopsis-instrument-evidence span {
 color: #2559a7;
 font-size: 10px;
 font-weight: 700;
}

.synopsis-instrument-evidence blockquote,
.synopsis-instrument-evidence p {
 min-width: 0;
 max-height: 74px;
 overflow: auto;
 margin: 0;
 color: var(--text-secondary);
 font-size: 11px;
 line-height: 1.55;
 overflow-wrap: anywhere;
}

.synopsis-instrument-evidence small {
 grid-column: 2;
 overflow: hidden;
 color: var(--muted);
 font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
 font-size: 9px;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.synopsis-instrument-evidence details {
 min-width: 0;
}

.synopsis-instrument-evidence details[open] {
 display: grid;
 gap: 6px;
}

.synopsis-instrument-evidence summary {
 width: max-content;
 max-width: 100%;
 cursor: pointer;
 color: #2559a7;
 font-size: 10px;
}

.synopsis-instrument-evidence.missing p {
 color: var(--danger);
}

.synopsis-validation-review > header > div {
 grid-template-columns: auto minmax(0, 1fr);
 align-items: start;
 color: var(--warning);
}

.synopsis-validation-review > header > span {
 color: var(--warning);
 font-size: 11px;
 font-weight: 700;
}

.synopsis-validation-review > div {
 border: 1px solid #efca93;
 border-radius: 4px;
 background: var(--warning-bg);
}

.synopsis-validation-review > div > label {
 min-width: 0;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 align-items: start;
 gap: 8px;
 padding: 8px 10px;
 border-bottom: 1px solid #efca93;
}

.synopsis-validation-review > div > label:last-child {
 border-bottom: 0;
}

.synopsis-validation-review input {
 width: auto;
 margin: 2px 0 0;
}

.synopsis-validation-review label > span {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.synopsis-validation-review label small,
.synopsis-override-reason > span {
 color: var(--muted);
 font-size: 11px;
}

.synopsis-override-reason {
 display: grid;
 gap: 5px;
}

.synopsis-override-reason textarea,
.synopsis-extraction-review input,
.synopsis-extraction-review select,
.synopsis-extraction-review textarea {
 width: 100%;
 min-width: 0;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 7px 9px;
 background: #fff;
 color: var(--text);
 font: inherit;
 font-size: 12px;
 line-height: 1.5;
}

.synopsis-extraction-review input,
.synopsis-extraction-review select {
 height: 34px;
 padding-top: 0;
 padding-bottom: 0;
}

.synopsis-extraction-review textarea,
.synopsis-override-reason textarea {
 resize: vertical;
}

.synopsis-import-footer {
 flex: 0 0 auto;
}

.authoring-stage-strip {
 min-height: 42px;
 gap: 0;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
}

.authoring-stage-strip button {
 min-width: 0;
 flex: 1;
 min-height: 40px;
 justify-content: center;
 display: inline-flex;
 align-items: center;
 gap: 7px;
 border: 0;
 border-right: 1px solid var(--line);
 border-radius: 0;
 background: transparent;
 color: var(--muted);
}

.authoring-stage-strip button:last-child {
 border-right: 0;
}

.authoring-stage-strip button.active {
 background: #fff5ee;
 color: var(--brand);
}

.authoring-stage-strip button.done > span {
 color: var(--success);
}

.authoring-stage-strip button.exception > span {
 color: var(--warning);
}

.authoring-stage-strip button > span {
 width: 22px;
 height: 22px;
 display: grid;
 place-items: center;
 border: 1px solid currentColor;
 border-radius: 50%;
 font-size: 10px;
}

.authoring-group-tabs {
 gap: 4px;
 border-bottom: 1px solid var(--line);
}

.authoring-group-tabs button {
 min-height: 32px;
 border: 0;
 border-bottom: 2px solid transparent;
 border-radius: 0;
 background: transparent;
 color: var(--muted);
}

.authoring-group-tabs button.active {
 border-bottom-color: var(--brand);
 color: var(--brand);
 font-weight: 600;
}

.authoring-journey-body {
 min-height: 0;
 flex: 1;
 overflow-y: auto;
 padding-right: 2px;
}

.authoring-journey-fieldset {
 min-width: 0;
 margin: 0;
 padding: 0;
 border: 0;
}

.authoring-field-section,
.authoring-corpus-stage {
 min-width: 0;
 display: grid;
 gap: 12px;
 align-content: start;
}

.authoring-field-section > header,
.authoring-corpus-stage > header {
 padding: 2px 0 8px;
 border-bottom: 1px solid var(--soft-line);
}

.authoring-field-grid {
 display: grid;
 gap: 10px;
}

.authoring-field-grid.two {
 grid-template-columns: repeat(2, minmax(0, 1fr));
}

.authoring-field-grid.four {
 grid-template-columns: repeat(4, minmax(110px, 1fr));
}

.authoring-field-grid .span-2 {
 grid-column: span 2;
}

.authoring-field-grid .span-4 {
 grid-column: 1 / -1;
}

.authoring-field {
 min-width: 0;
 display: grid;
 gap: 5px;
}

.authoring-field > span b {
 margin-left: 3px;
 color: var(--danger);
}

.authoring-field input,
.authoring-field select,
.authoring-field textarea,
.authoring-override textarea {
 width: 100%;
 min-width: 0;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 7px 9px;
 background: #fff;
 color: var(--text);
 font: inherit;
 font-size: 12px;
 line-height: 1.5;
}

.authoring-field input,
.authoring-field select {
 height: 34px;
 padding-top: 0;
 padding-bottom: 0;
}

.authoring-field textarea,
.authoring-override textarea {
 resize: vertical;
}

.authoring-structured-list {
 min-width: 0;
 margin: 0;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 9px;
 background: #fff;
}

.authoring-structured-list.span-2 {
 grid-column: span 2;
}

.authoring-structured-list legend {
 padding: 0 5px;
 color: var(--text-secondary);
 font-size: 11px;
 font-weight: 600;
}

.authoring-structured-list legend b {
 margin-left: 3px;
 color: var(--danger);
}

.authoring-structured-list-rows {
 display: grid;
 gap: 6px;
}

.authoring-structured-list-rows > p {
 margin: 0;
 border: 1px dashed var(--line);
 padding: 10px;
 color: var(--muted);
 font-size: 11px;
 line-height: 1.5;
}

.authoring-structured-list-row {
 min-width: 0;
 display: grid;
 grid-template-columns: 58px minmax(0, 1fr) 30px;
 align-items: start;
 gap: 6px;
}

.authoring-structured-list-row > span {
 min-height: 34px;
 display: flex;
 align-items: center;
 justify-content: center;
 border: 1px solid var(--soft-line);
 border-radius: 3px;
 background: #f7f8fa;
 color: var(--text-secondary);
 font-size: 10px;
 font-weight: 700;
}

.authoring-structured-list-row textarea {
 width: 100%;
 min-width: 0;
 min-height: 48px;
 border: 1px solid var(--line);
 border-radius: 3px;
 padding: 6px 8px;
 background: #fff;
 color: var(--text);
 font: inherit;
 font-size: 12px;
 line-height: 1.45;
 resize: vertical;
}

.authoring-structured-list-row .icon-button {
 width: 30px;
 min-width: 30px;
 height: 30px;
 padding: 0;
 color: var(--danger);
}

.authoring-structured-list-add {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 gap: 5px;
 margin-top: 7px;
 padding: 0 9px;
}

.intervention-rules-editor {
 min-width: 0;
 display: grid;
 gap: 0;
 grid-column: 1 / -1;
 margin-top: 4px;
 border: 1px solid var(--line);
 border-radius: 6px;
 background: #fafbfc;
 overflow: hidden;
}

.intervention-rules-head {
 min-height: 38px;
 display: flex;
 align-items: center;
 gap: 8px;
 padding: 7px 10px;
 border-bottom: 1px solid var(--soft-line);
 background: #f0f2f5;
 cursor: pointer;
 user-select: none;
}

.intervention-rules-head > div {
 min-width: 0;
 display: flex;
 flex-direction: column;
 gap: 1px;
 flex: 1;
}

.intervention-rules-head strong {
 font-size: 12px;
 font-weight: 600;
 color: var(--text);
}

.intervention-rules-head small {
 font-size: 10px;
 color: var(--muted);
 line-height: 1.4;
}

.intervention-rules-toggle {
 display: flex;
 align-items: center;
 color: var(--text-secondary);
}

.intervention-rules-authority {
 flex-shrink: 0;
 padding: 2px 8px;
 border-radius: 10px;
 font-size: 10px;
 font-weight: 600;
 line-height: 1.5;
}

.intervention-rules-authority.legacy {
 background: #e8eaed;
 color: var(--text-secondary);
}

.intervention-rules-authority.structured {
 background: #e6f4ea;
 color: #137333;
}

.intervention-rules-segments {
 display: flex;
 gap: 0;
 border-bottom: 1px solid var(--soft-line);
 padding: 0 4px;
 background: #fff;
}

.intervention-rules-segments button {
 min-height: 30px;
 padding: 0 12px;
 border: 0;
 border-bottom: 2px solid transparent;
 border-radius: 0;
 background: transparent;
 color: var(--muted);
 font-size: 11px;
 font-weight: 500;
 white-space: nowrap;
}

.intervention-rules-segments button.active {
 border-bottom-color: var(--brand);
 color: var(--brand);
 font-weight: 600;
}

.intervention-rules-body {
 padding: 10px;
 min-width: 0;
}

.intervention-rules-panel {
 min-width: 0;
 display: grid;
 gap: 8px;
}

.intervention-rules-panel-hint {
 margin: 0;
 font-size: 10px;
 color: var(--muted);
 line-height: 1.5;
}

.intervention-rules-policy-bar {
 display: flex;
 flex-wrap: wrap;
 gap: 8px;
 padding: 8px 10px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fff;
}

.intervention-rules-row {
 min-width: 0;
 display: grid;
 grid-template-columns: 36px minmax(0, 1fr) 28px;
 align-items: start;
 gap: 6px;
 padding: 8px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fff;
}

.intervention-rules-row-index {
 min-height: 28px;
 display: flex;
 align-items: center;
 justify-content: center;
 border: 1px solid var(--soft-line);
 border-radius: 3px;
 background: #f7f8fa;
 color: var(--text-secondary);
 font-size: 10px;
 font-weight: 700;
}

.intervention-rules-row-fields {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(4, minmax(100px, 1fr));
 gap: 5px;
}

.intervention-rules-row-delete {
 width: 28px;
 min-width: 28px;
 height: 28px;
 padding: 0;
 color: var(--danger);
}

.intervention-rules-mini {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.intervention-rules-mini.span-2 {
 grid-column: span 2;
}

.intervention-rules-mini.span-full {
 grid-column: 1 / -1;
}

.intervention-rules-mini > span {
 font-size: 10px;
 font-weight: 600;
 color: var(--text-secondary);
 line-height: 1.3;
}

.intervention-rules-mini input,
.intervention-rules-mini select,
.intervention-rules-mini textarea {
 width: 100%;
 min-width: 0;
 border: 1px solid var(--line);
 border-radius: 3px;
 padding: 4px 6px;
 background: #fff;
 color: var(--text);
 font: inherit;
 font-size: 11px;
 line-height: 1.4;
}

.intervention-rules-mini input,
.intervention-rules-mini select {
 min-height: 26px;
}

.intervention-rules-mini textarea {
 resize: vertical;
 min-height: 34px;
}

.intervention-rules-empty {
 margin: 0;
 padding: 12px 10px;
 border: 1px dashed var(--line);
 border-radius: 4px;
 color: var(--muted);
 font-size: 11px;
 line-height: 1.5;
}

.intervention-rules-add {
 min-height: 28px;
 display: inline-flex;
 align-items: center;
 gap: 4px;
 padding: 0 10px;
 font-size: 11px;
 font-weight: 500;
}

.intervention-rules-links {
 margin-top: 8px;
 padding-top: 8px;
 border-top: 1px solid var(--soft-line);
 display: grid;
 gap: 8px;
}

.intervention-rules-links > header {
 display: flex;
 align-items: baseline;
 gap: 8px;
}

.intervention-rules-links > header span {
 font-size: 10px;
 color: var(--muted);
}

@media (max-width: 768px) {
 .intervention-rules-row-fields {
 grid-template-columns: repeat(2, minmax(120px, 1fr));
 }

 .intervention-rules-mini.span-2 {
 grid-column: 1 / -1;
 }
}

.authoring-instrument-registry {
 min-width: 0;
 display: grid;
 gap: 10px;
 border-top: 1px solid var(--line);
 padding-top: 12px;
}

.authoring-instrument-registry > header,
.authoring-instrument-editor-head,
.authoring-instrument-governance section > header,
.authoring-instrument-confirm {
 min-width: 0;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
}

.authoring-instrument-registry > header > div,
.authoring-instrument-editor-head > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.authoring-instrument-registry > header span,
.authoring-instrument-editor-head span,
.authoring-instrument-governance header span {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.authoring-instrument-registry > header button,
.authoring-instrument-empty button,
.authoring-instrument-editor-head button,
.authoring-instrument-confirm button {
 min-height: 32px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 5px;
 white-space: nowrap;
}

.authoring-instrument-empty {
 min-height: 74px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 16px;
 border: 1px dashed #d8c1af;
 border-radius: 4px;
 padding: 12px;
 background: #fffaf6;
}

.authoring-instrument-empty p {
 margin: 0;
 color: var(--text-secondary);
 font-size: 12px;
 line-height: 1.55;
}

.authoring-instrument-layout {
 min-width: 0;
 display: grid;
 grid-template-columns: 250px minmax(0, 1fr);
 align-items: start;
 gap: 10px;
}

.authoring-instrument-list,
.authoring-instrument-editor {
 min-width: 0;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
}

.authoring-instrument-list {
 max-height: 620px;
 overflow-y: auto;
}

.authoring-instrument-list > button {
 width: 100%;
 min-width: 0;
 min-height: 52px;
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 align-items: center;
 gap: 8px;
 border: 0;
 border-bottom: 1px solid var(--soft-line);
 border-radius: 0;
 padding: 8px 9px;
 background: #fff;
 color: var(--text);
 text-align: left;
}

.authoring-instrument-list > button:last-child {
 border-bottom: 0;
}

.authoring-instrument-list > button.selected {
 background: #fff6ef;
 box-shadow: inset 3px 0 0 var(--brand);
}

.authoring-instrument-list > button > span {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.authoring-instrument-list small {
 overflow: hidden;
 color: var(--muted);
 font-size: 10px;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.instrument-state {
 border: 1px solid var(--line);
 border-radius: 3px;
 padding: 2px 5px;
 color: var(--muted);
 font-size: 10px;
 font-style: normal;
}

.instrument-state.confirmed {
 border-color: #9fc5a9;
 background: #f2faf4;
 color: var(--success);
}

.instrument-state.needs_review {
 border-color: #efca93;
 background: var(--warning-bg);
 color: var(--warning);
}

.authoring-instrument-editor {
 display: grid;
 gap: 12px;
 padding: 11px;
}

.authoring-instrument-editor-head {
 padding-bottom: 8px;
 border-bottom: 1px solid var(--soft-line);
}

.authoring-instrument-editor-head .danger-quiet {
 border-color: #edb8b8;
 color: var(--danger);
}

.authoring-instrument-bindings {
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(0, 1.5fr) minmax(240px, 0.8fr);
 gap: 12px;
 margin: 0;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 10px;
}

.authoring-instrument-bindings legend {
 padding: 0 5px;
 color: var(--text-secondary);
 font-size: 11px;
 font-weight: 600;
}

.authoring-instrument-bindings > div {
 display: flex;
 flex-wrap: wrap;
 align-content: start;
 gap: 6px;
}

.authoring-instrument-bindings > div label,
.authoring-instrument-confirm > label {
 display: inline-flex;
 align-items: flex-start;
 gap: 6px;
 color: var(--text-secondary);
 font-size: 11px;
 line-height: 1.4;
}

.authoring-instrument-bindings input,
.authoring-instrument-confirm input {
 width: auto;
 min-width: 14px;
 margin: 1px 0 0;
}

.authoring-instrument-governance {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 10px;
}

.authoring-instrument-governance section {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 8px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 9px;
 background: #fafbfc;
}

.authoring-instrument-governance section > header {
 grid-column: 1 / -1;
}

.authoring-instrument-governance label {
 min-width: 0;
 display: grid;
 gap: 4px;
}

.authoring-instrument-governance label:last-child {
 grid-column: 1 / -1;
}

.authoring-instrument-governance label > span {
 color: var(--muted);
 font-size: 10px;
}

.authoring-instrument-governance input,
.authoring-instrument-governance select {
 width: 100%;
 min-width: 0;
 height: 32px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 0 8px;
 background: #fff;
 color: var(--text);
 font: inherit;
 font-size: 11px;
}

.authoring-instrument-confirm {
 justify-content: flex-start;
 flex-wrap: wrap;
 border-top: 1px solid var(--soft-line);
 padding-top: 10px;
}

.authoring-instrument-confirm button {
 margin-left: auto;
}

.authoring-instrument-confirm button.confirmed {
 border-color: #9fc5a9;
 background: #f2faf4;
 color: var(--success);
}

.authoring-instrument-appendix {
 min-width: 0;
 display: grid;
 gap: 9px;
 border: 1px solid #dfc8b5;
 border-radius: 4px;
 padding: 10px;
 background: #fffaf6;
}

.authoring-instrument-appendix > header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
}

.authoring-instrument-appendix > header > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.authoring-instrument-appendix > header span,
.authoring-instrument-appendix p,
.authoring-instrument-appendix-result small,
.authoring-instrument-appendix-actions small {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.authoring-instrument-appendix > header em {
 flex: 0 0 auto;
 border: 1px solid var(--line);
 border-radius: 3px;
 padding: 3px 6px;
 color: var(--muted);
 background: #fff;
 font-size: 10px;
 font-style: normal;
}

.authoring-instrument-appendix > header em.ready {
 border-color: #9fc5a9;
 color: var(--success);
 background: #f2faf4;
}

.authoring-instrument-appendix-result {
 min-width: 0;
 display: flex;
 align-items: center;
 gap: 8px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 8px;
 background: #fff;
}

.authoring-instrument-appendix-result > span {
 min-width: 0;
 display: grid;
}

.authoring-instrument-appendix-result strong {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.authoring-instrument-appendix-actions {
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 gap: 8px;
}

.authoring-instrument-appendix-actions label {
 min-width: 0;
 min-height: 40px;
 display: flex;
 align-items: center;
 gap: 8px;
 border: 1px dashed #cfaa8b;
 border-radius: 4px;
 padding: 7px 9px;
 background: #fff;
 cursor: pointer;
}

.authoring-instrument-appendix-actions label > input {
 position: absolute;
 width: 1px;
 height: 1px;
 overflow: hidden;
 opacity: 0;
}

.authoring-instrument-appendix-actions label > span {
 min-width: 0;
 display: grid;
}

.authoring-instrument-appendix-actions label strong {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.authoring-instrument-appendix-actions button {
 min-height: 40px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 5px;
 white-space: nowrap;
}

.authoring-instrument-appendix > p {
 margin: 0;
}

.authoring-instrument-appendix > p.success {
 color: var(--success);
}

.authoring-instrument-appendix > p.warning {
 color: var(--warning);
}

.authoring-choice-grid {
 display: grid;
 grid-template-columns: repeat(4, minmax(0, 1fr));
 gap: 7px;
}

.authoring-choice-grid label {
 min-width: 0;
 min-height: 38px;
 display: flex;
 align-items: center;
 gap: 7px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 7px 9px;
 background: #fff;
 color: var(--text);
 font-size: 12px;
}

.authoring-choice-grid label.selected {
 border-color: #f3b98f;
 background: #fff6ef;
}

.authoring-choice-grid input,
.authoring-gate-checklist input {
 width: auto;
 min-width: 14px;
 flex: 0 0 auto;
 margin: 0;
}

.authoring-prefill-panel {
 min-width: 0;
 display: grid;
 gap: 12px;
 margin-bottom: 12px;
 border-top: 2px solid var(--orange);
 border-bottom: 1px solid var(--line);
 padding: 12px 0 14px;
 background: #fff;
}

.authoring-prefill-panel > header,
.authoring-prefill-panel > header > div,
.authoring-prefill-panel > header span {
 min-width: 0;
 display: flex;
 align-items: center;
}

.authoring-prefill-panel > header {
 justify-content: space-between;
 gap: 12px;
}

.authoring-prefill-panel > header > div {
 gap: 8px;
 color: var(--orange-dark);
}

.authoring-prefill-panel > header span {
 align-items: flex-start;
 flex-direction: column;
 gap: 2px;
 color: var(--text);
}

.authoring-prefill-panel > header small {
 color: var(--muted);
 font-size: 11px;
}

.authoring-prefill-panel > header button {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 0 9px;
 background: #fff;
 color: var(--text);
 font-size: 12px;
}

.authoring-prefill-header-actions,
.authoring-prefill-preparation,
.authoring-prefill-section-tabs,
.authoring-prefill-primary-actions {
 min-width: 0;
 display: flex;
 align-items: center;
}

.authoring-prefill-header-actions {
 flex: 0 0 auto;
 gap: 6px;
}

.authoring-prefill-panel > header .authoring-prefill-batch-button {
 border-color: #d7a47d;
 background: #fff8f2;
 color: #8f430f;
 font-weight: 700;
}

/* W4-A recommendation-first composite package panel */
.authoring-package-panel {
 min-width: 0;
 display: grid;
 gap: 8px;
 margin: 4px 0 12px;
 border: 1px solid #e6d2c0;
 border-radius: 6px;
 padding: 10px 12px;
 background: linear-gradient(180deg, #fffaf5 0%, #fff 42%);
}

.authoring-package-panel.empty {
 background: #fafafa;
 border-color: var(--line);
}

.authoring-package-panel > header {
 display: flex;
 align-items: flex-start;
 gap: 8px;
 color: var(--orange-dark);
}

.authoring-package-panel > header > div {
 display: grid;
 gap: 2px;
 color: var(--text);
}

.authoring-package-panel > header small {
 color: var(--muted);
 font-size: 11px;
}

.authoring-package-guidance-checklist {
 margin: 6px 0 0;
 padding-left: 18px;
 color: var(--text);
 font-size: 12px;
 line-height: 1.5;
}

.authoring-package-guidance-checklist li + li {
 margin-top: 2px;
}

.authoring-package-module-includes,
.authoring-package-why-recommend {
 display: grid;
 gap: 4px;
}

.authoring-package-module-includes > strong,
.authoring-package-why-recommend > strong,
.authoring-package-tradeoffs > strong {
 font-size: 11px;
 color: #8f430f;
}

.authoring-package-module-includes ul,
.authoring-package-tradeoffs ul {
 margin: 0;
 padding-left: 18px;
 font-size: 12px;
 line-height: 1.45;
}


.authoring-package-tabs {
 display: flex;
 flex-wrap: wrap;
 gap: 6px;
}

.authoring-package-tabs button {
 min-height: 34px;
 display: inline-flex;
 flex-direction: column;
 align-items: flex-start;
 gap: 1px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 5px 10px;
 background: #fff;
 color: var(--text);
 font-size: 12px;
}

.authoring-package-tabs button.active {
 border-color: #d7a47d;
 background: #fff4ea;
 color: #8f430f;
 font-weight: 700;
}

.authoring-package-tabs button small {
 color: var(--muted);
 font-size: 10px;
 font-weight: 400;
}

.authoring-package-workspace {
 display: grid;
 grid-template-columns: minmax(0, 1fr) minmax(220px, 260px);
 gap: 12px;
 align-items: start;
}

.authoring-package-candidates {
 min-width: 0;
 display: grid;
 gap: 6px;
}

.authoring-package-candidate {
 min-width: 0;
 border: 1px solid var(--line);
 border-radius: 5px;
 background: #fff;
 overflow: hidden;
}

.authoring-package-candidate.recommended {
 border-color: #d7a47d;
 box-shadow: inset 3px 0 0 #e87524;
}

.authoring-package-candidate.selected {
 border-color: #c57a3a;
 background: #fffdfb;
}

.authoring-package-candidate.pending {
 border-style: dashed;
}

.authoring-package-candidate.confirmed {
 border-color: #b8d5c1;
 box-shadow: inset 3px 0 0 #4f9b6a;
}

.authoring-package-candidate-select {
 width: 100%;
 min-height: 44px;
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 8px;
 border: 0;
 padding: 7px 10px 8px;
 background: #fafbfc;
 color: var(--text);
 font-size: 12px;
 text-align: left;
}

.authoring-package-candidate.selected .authoring-package-candidate-select {
 border-bottom: 1px solid var(--soft-line, #e8ebef);
 background: #fff9f4;
}

.authoring-package-candidate-select-copy {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.authoring-package-candidate-role {
 display: inline-flex;
 align-items: center;
 gap: 5px;
 color: #8f430f;
 font-size: 10px;
 font-weight: 700;
}

.authoring-package-candidate-select-copy > strong {
 min-width: 0;
 overflow: hidden;
 color: var(--text);
 font-size: 12px;
 line-height: 1.35;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.authoring-package-candidate-select-copy > small {
 display: -webkit-box;
 overflow: hidden;
 color: var(--muted);
 font-size: 11px;
 font-weight: 400;
 line-height: 1.35;
 -webkit-box-orient: vertical;
 -webkit-line-clamp: 1;
}

.authoring-package-candidate-confidence {
 flex: 0 0 auto;
 padding-top: 1px;
 color: var(--muted);
 font-size: 10px;
 white-space: nowrap;
}

.authoring-package-candidate-body {
 display: grid;
 gap: 7px;
 padding: 8px 10px 10px;
}

.authoring-package-rationale,
.authoring-package-insufficient-flag,
.authoring-package-no-alternatives,
.authoring-package-pending-hint {
 margin: 0;
 color: var(--muted);
 font-size: 12px;
 line-height: 1.45;
}

.authoring-package-insufficient-flag {
 color: #9a4b12;
}

.authoring-package-evidence {
 display: grid;
 gap: 6px;
}

.authoring-package-source-text {
 margin: 0;
 border-left: 3px solid #e87524;
 padding: 7px 10px;
 background: #fff8f2;
}

.authoring-package-source-text span,
.authoring-package-evidence.insufficient > span {
 display: block;
 margin-bottom: 3px;
 color: #8f430f;
 font-size: 11px;
 font-weight: 700;
}

.authoring-package-source-text p,
.authoring-package-evidence.insufficient p {
 margin: 0;
 color: var(--text);
 font-size: 12px;
 line-height: 1.5;
 white-space: pre-wrap;
}

.authoring-package-evidence.insufficient {
 border: 1px dashed #e0b48d;
 border-radius: 4px;
 padding: 8px 10px;
 background: #fffaf5;
}

.authoring-package-trace-details,
.authoring-package-review-details,
.authoring-package-run-meta,
.authoring-package-optional-overrides {
 border-top: 1px solid var(--soft-line, #e8ebef);
 padding-top: 6px;
}

.authoring-package-trace-details > summary,
.authoring-package-review-details > summary,
.authoring-package-run-meta > summary,
.authoring-package-optional-overrides > summary {
 cursor: pointer;
 color: var(--muted);
 font-size: 11px;
}

.authoring-package-review-details[open] > summary {
 margin-bottom: 7px;
 color: #8f430f;
 font-weight: 700;
}

.authoring-package-review-grid {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 8px 14px;
}

.authoring-package-trace-details ul,
.authoring-package-tradeoffs ul,
.authoring-package-gaps ul,
.authoring-package-limitations ul,
.authoring-package-targets ul {
 margin: 4px 0 0;
 padding-left: 16px;
 color: var(--text);
 font-size: 12px;
}

.authoring-package-tradeoffs,
.authoring-package-gaps,
.authoring-package-limitations,
.authoring-package-targets {
 display: grid;
 gap: 3px;
}

.authoring-package-tradeoffs > strong,
.authoring-package-gaps > strong,
.authoring-package-limitations > strong,
.authoring-package-targets > strong {
 font-size: 11px;
 color: var(--muted);
}

.authoring-package-run-meta dl {
 display: grid;
 gap: 4px;
 margin: 6px 0 0;
}

.authoring-package-run-meta dl > div {
 display: grid;
 grid-template-columns: 72px minmax(0, 1fr);
 gap: 6px;
 font-size: 11px;
}

.authoring-package-run-meta dt {
 color: var(--muted);
}

.authoring-package-run-meta dd {
 margin: 0;
 overflow-wrap: anywhere;
}

.authoring-package-path-decisions {
 display: grid;
 gap: 8px;
 border: 1px solid #e6d2c0;
 border-radius: 4px;
 padding: 8px;
 background: #fffaf5;
}

.authoring-package-path-decisions > header {
 display: flex;
 align-items: flex-start;
 gap: 6px;
 color: #8f430f;
 font-size: 12px;
}

.authoring-package-path-row {
