 flex-wrap: wrap;
 align-items: baseline;
 justify-content: space-between;
 gap: 4px 8px;
}

.authoring-package-path-head small {
 color: var(--muted);
 font-size: 10px;
}

.authoring-package-path-candidate span,
.authoring-package-path-override span {
 display: block;
 margin-bottom: 2px;
 color: var(--muted);
 font-size: 11px;
}

.authoring-package-path-candidate p {
 margin: 0;
 font-size: 12px;
 line-height: 1.4;
 white-space: pre-wrap;
}

.authoring-package-path-override textarea {
 width: 100%;
 min-height: 52px;
 border: 1px solid var(--line);
 border-radius: 3px;
 padding: 6px 8px;
 font: inherit;
 font-size: 12px;
 resize: vertical;
}

.authoring-package-path-skip {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 font-size: 12px;
 color: var(--muted);
}

.authoring-package-actions {
 min-width: 0;
 display: grid;
 gap: 10px;
 border: 1px solid var(--line);
 border-radius: 5px;
 padding: 10px;
 background: #fff;
 position: sticky;
 top: 8px;
}

.authoring-package-action-summary {
 display: grid;
 gap: 4px;
}

.authoring-package-action-summary p {
 margin: 0;
 color: var(--muted);
 font-size: 12px;
 line-height: 1.45;
}

.authoring-package-adopt-button {
 min-height: 36px;
 width: 100%;
 justify-content: center;
}

.authoring-package-pending-badge {
 display: inline-flex;
 align-items: center;
 gap: 4px;
 margin: 0;
 color: #8f430f;
 font-size: 12px;
 font-weight: 700;
}

.authoring-package-receipt {
 display: grid;
 gap: 8px;
 border: 1px solid #b8d5c1;
 border-radius: 5px;
 padding: 10px;
 background: #f3faf5;
}

.authoring-package-receipt.replayed {
 border-color: #9bb8d6;
 background: #f3f7fc;
}

.authoring-package-receipt.stale {
 border-color: #e0b48d;
 background: #fff8f2;
}

.authoring-package-receipt > header {
 display: flex;
 align-items: flex-start;
 gap: 8px;
}

.authoring-package-receipt > header > div {
 display: grid;
 gap: 2px;
}

.authoring-package-receipt > header small {
 color: var(--muted);
 font-size: 11px;
}

.authoring-package-receipt-flag {
 margin: 0;
 font-size: 12px;
 font-weight: 700;
}

.authoring-package-receipt-flag.replayed {
 color: #2f5f8f;
}

.authoring-package-receipt-flag.stale {
 color: #9a4b12;
}

.authoring-package-receipt-categories {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
 gap: 8px;
}

.authoring-package-receipt-category {
 border-radius: 4px;
 padding: 7px 8px;
 background: #fff;
 border: 1px solid var(--line);
}

.authoring-package-receipt-category.applied {
 border-color: #b8d5c1;
 background: #f7fcf8;
}

.authoring-package-receipt-category.overridden {
 border-color: #c7b0e0;
 background: #faf7fd;
}

.authoring-package-receipt-category.derived {
 border-color: #9bb8d6;
 background: #f5f9fd;
}

.authoring-package-receipt-category.skipped {
 border-color: #d7dbe1;
 background: #f7f8fa;
}

.authoring-package-receipt-category.invalidated {
 border-color: #e0b48d;
 background: #fffaf5;
}

.authoring-package-receipt-category strong {
 display: block;
 margin-bottom: 4px;
 font-size: 11px;
}

.authoring-package-receipt-category ul {
 margin: 0;
 padding-left: 14px;
 font-size: 11px;
 line-height: 1.4;
}

.authoring-package-receipt-category li small {
 display: block;
 color: var(--muted);
}

@media (max-width: 1366px) {
 .authoring-package-workspace {
 grid-template-columns: 1fr;
 }

 .authoring-package-actions {
 position: static;
 }
}

.authoring-prefill-preparation {
 gap: 8px;
}

.authoring-prefill-preparation span {
 min-height: 30px;
