 padding: 0 9px;
 background: #fff;
 color: var(--muted);
 font-size: 11px;
}

.authoring-prefill-preparation span.done {
 border-color: #b8d5c1;
 background: #f3faf5;
 color: #2d7144;
}

.authoring-prefill-preparation span.running {
 border-color: #efc8aa;
 background: #fff8f2;
 color: #9b4e18;
}

.authoring-prefill-progress {
 position: relative;
 min-height: 24px;
 display: flex;
 align-items: center;
 gap: 9px;
 overflow: hidden;
 border-radius: 3px;
 padding: 0 8px;
 background: #f3f4f6;
 font-size: 11px;
}

.authoring-prefill-progress > span {
 position: absolute;
 inset: 0 auto 0 0;
 background: #f6e8da;
 opacity: 0.72;
}

.authoring-prefill-progress strong,
.authoring-prefill-progress small {
 position: relative;
 z-index: 1;
}

.authoring-prefill-progress small {
 color: var(--muted);
}

.authoring-prefill-batch-state {
 min-height: 30px;
 display: flex;
 align-items: center;
 gap: 10px;
 border-left: 3px solid #4f9b6a;
 padding: 5px 9px;
 background: #f3faf5;
 color: #2d7144;
 font-size: 11px;
}

.authoring-prefill-batch-state.stopped {
 border-left-color: #d18a28;
 background: #fff8ec;
 color: #8a5917;
}

.authoring-prefill-workspace {
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(0, 1fr) 240px;
 gap: 16px;
 align-items: start;
}

.authoring-prefill-main {
 min-width: 0;
}

.authoring-prefill-section-tabs {
 gap: 2px;
 border-bottom: 1px solid var(--line);
}

.authoring-prefill-section-tabs button {
 min-width: 138px;
 min-height: 40px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
