 padding: 0 10px;
 background: transparent;
 color: var(--muted);
 font-size: 12px;
}

.authoring-prefill-section-tabs button.active {
 border-bottom-color: var(--orange);
 color: var(--text);
 font-weight: 700;
}

.authoring-prefill-section-tabs small {
 color: var(--muted);
 font-size: 10px;
 font-weight: 500;
}

.authoring-prefill-fields {
