 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.authoring-prefill-candidate-copy > div span {
 display: inline-flex;
 align-items: center;
 gap: 4px;
 color: #a45116;
 font-size: 10px;
 font-weight: 700;
}

.authoring-prefill-candidates > section.selected .authoring-prefill-candidate-copy > div span {
 color: #2d7144;
}

.authoring-prefill-candidate-copy > div small,
.authoring-prefill-candidate-copy p {
