 font-size: 10px;
}

.authoring-prefill-candidate-copy > strong {
 overflow-wrap: anywhere;
 font-size: 12px;
 line-height: 1.5;
}

.authoring-prefill-candidate-copy p {
 margin: 0;
 line-height: 1.45;
}

.authoring-prefill-candidate-actions {
 display: flex;
 align-items: flex-start;
 gap: 5px;
}

.authoring-prefill-candidate-actions button,
.authoring-prefill-edit button {
 min-height: 28px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 0 8px;
 background: #fff;
 color: var(--text);
 font-size: 11px;
 white-space: nowrap;
}

.authoring-prefill-candidate-actions button.primary-button,
.authoring-prefill-edit button.primary-button {
