}

.authoring-applicability-row select,
.authoring-applicability-row textarea {
 width: 100%;
 min-width: 0;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 7px 9px;
 background: #fff;
 color: var(--text);
 font: inherit;
 font-size: 12px;
}

.authoring-applicability-confirm {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 gap: 7px;
 color: var(--text);
 font-size: 11px;
 line-height: 1.4;
}

.authoring-applicability-summary {
 min-width: 0;
 display: grid;
 gap: 7px;
