}

.authoring-ib-current small {
 max-width: 520px;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.authoring-ib-intake > p {
 margin: 0;
}

.authoring-conversation {
 min-width: 0;
 display: grid;
 gap: 10px;
 margin-top: 12px;
 padding: 10px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: var(--surface, #ffffff);
}

.authoring-conversation > header {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 10px;
}

.authoring-conversation > header > div {
 display: flex;
 align-items: flex-start;
 gap: 8px;
 min-width: 0;
}

.authoring-conversation > header svg {
 flex-shrink: 0;
 color: var(--primary, #4a6cf7);
 margin-top: 1px;
}

.authoring-conversation > header > div > div {
 display: grid;
 gap: 2px;
 min-width: 0;
}

.authoring-conversation > header strong {
 font-size: 13px;
 color: var(--text);
}

.authoring-conversation > header span {
 font-size: 11px;
 color: var(--text-secondary, #6c757d);
 line-height: 1.5;
}

.authoring-conversation > header > small {
 font-size: 10px;
 color: var(--text-secondary, #6c757d);
 white-space: nowrap;
 flex-shrink: 0;
}

.authoring-conversation-input {
 display: flex;
 gap: 8px;
 align-items: flex-end;
}

.authoring-conversation-input textarea {
 flex: 1 1 0;
 min-width: 0;
 min-height: 70px;
 padding: 8px;
 border: 1px solid var(--line);
 border-radius: 4px;
 font-size: 13px;
 line-height: 1.5;
 resize: vertical;
 font-family: inherit;
}

.authoring-conversation-input button {
 flex-shrink: 0;
 min-height: 34px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.authoring-conversation-empty {
 margin: 0;
 padding: 8px;
 font-size: 11px;
 color: var(--text-secondary, #6c757d);
 line-height: 1.5;
 background: var(--surface-muted, #f8f9fa);
 border-radius: 4px;
}

.authoring-conversation-turns {
 display: grid;
 gap: 10px;
}

.authoring-conversation-turn {
 display: grid;
 gap: 6px;
 padding: 8px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: var(--surface-muted, #f8f9fa);
}

.authoring-conversation-user small,
.authoring-conversation-ai small {
 font-size: 10px;
 color: var(--text-secondary, #6c757d);
 text-transform: uppercase;
 letter-spacing: 0.3px;
}

.authoring-conversation-user p {
 margin: 2px 0 0;
 font-size: 12px;
 color: var(--text);
 line-height: 1.5;
 white-space: pre-wrap;
 word-break: break-word;
}

.authoring-conversation-ai {
 display: grid;
 gap: 8px;
}

.authoring-fact-proposals {
 display: grid;
 gap: 6px;
}

.authoring-fact-proposal {
 min-width: 0;
 display: grid;
 gap: 5px;
 padding: 8px;
 border: 1px solid var(--line);
 border-left: 3px solid var(--text-secondary, #6c757d);
 border-radius: 4px;
 background: var(--surface, #ffffff);
}

.authoring-fact-proposal.fact {
 border-left-color: var(--success, #28a745);
}

.authoring-fact-proposal.inference {
 border-left-color: var(--primary, #4a6cf7);
}

.authoring-fact-proposal.unknown {
 border-left-color: var(--text-secondary, #6c757d);
}

.authoring-fact-proposal.conflict {
 border-left-color: var(--warning, #ffc107);
}

.authoring-fact-proposal.gap {
 border-left-color: var(--danger, #dc3545);
}

.authoring-fact-proposal.decided {
 opacity: 0.7;
}

.authoring-fact-proposal-head {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.authoring-fact-proposal-field {
 font-size: 12px;
 font-weight: 600;
 color: var(--text);
}

.authoring-fact-proposal-evidence {
 font-size: 10px;
 color: var(--text-secondary, #6c757d);
 white-space: nowrap;
}

.authoring-fact-proposal-value {
 margin: 0;
 font-size: 12px;
 color: var(--text);
 line-height: 1.5;
}

.authoring-fact-proposal-source,
.authoring-fact-proposal-conflict {
 font-size: 10px;
 color: var(--text-secondary, #6c757d);
 line-height: 1.4;
}

.authoring-fact-proposal-conflict {
 color: var(--warning, #856404);
}

.authoring-fact-proposal-edit {
 display: grid;
 gap: 5px;
}

.authoring-fact-proposal-edit textarea {
 min-height: 44px;
 padding: 6px;
 border: 1px solid var(--line);
 border-radius: 3px;
 font-size: 12px;
 line-height: 1.5;
 resize: vertical;
 font-family: inherit;
}

.authoring-fact-proposal-edit-actions {
 display: flex;
 gap: 6px;
}

.authoring-fact-proposal-edit-actions button {
 min-height: 28px;
 padding: 0 10px;
 font-size: 11px;
}

.authoring-fact-proposal-actions {
 display: flex;
 gap: 5px;
 flex-wrap: wrap;
}

.authoring-fact-proposal-actions button {
 min-height: 26px;
 padding: 0 8px;
 font-size: 11px;
 display: inline-flex;
 align-items: center;
 gap: 4px;
 border: 1px solid var(--line);
 border-radius: 3px;
 background: var(--surface, #ffffff);
 color: var(--text);
 cursor: pointer;
}

.authoring-fact-proposal-actions button.decided {
 background: var(--success-bg, #e8f5e9);
 border-color: var(--success, #28a745);
 color: var(--success, #28a745);
 cursor: default;
}

.authoring-conversation-gaps,
.authoring-conversation-questions {
 padding: 6px 8px;
 border-radius: 3px;
 background: var(--surface-muted, #f8f9fa);
}

.authoring-conversation-gaps strong,
.authoring-conversation-questions strong {
 font-size: 11px;
 color: var(--text);
 display: block;
 margin-bottom: 3px;
}

.authoring-conversation-gaps ul,
.authoring-conversation-questions ol {
 margin: 0;
 padding-left: 18px;
}

.authoring-conversation-gaps li,
.authoring-conversation-questions li {
 font-size: 11px;
 color: var(--text);
 line-height: 1.6;
}

.authoring-conversation-gaps {
 border-left: 3px solid var(--danger, #dc3545);
}

.authoring-conversation-questions {
 border-left: 3px solid var(--primary, #4a6cf7);
}

.authoring-conversation-no-findings {
 margin: 0;
 font-size: 11px;
 color: var(--text-secondary, #6c757d);
}

.authoring-conversation-hint {
 margin: 0;
 font-size: 10px;
 color: var(--text-secondary, #6c757d);
 line-height: 1.5;
 padding: 4px 6px;
 background: var(--success-bg, #e8f5e9);
 border-radius: 3px;
}

.authoring-journey-footer {
 min-height: 44px;
 justify-content: space-between;
 gap: 12px;
 padding-top: 9px;
 border-top: 1px solid var(--line);
}

.authoring-journey-footer > div,
.authoring-impact-actions {
 display: flex;
 align-items: center;
 justify-content: flex-end;
 gap: 7px;
}

.authoring-journey-footer button,
.authoring-impact-actions button,
.authoring-search-plan button,
.authoring-override button,
.authoring-writing-entry button {
 min-height: 34px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.research-pipeline-banner {
 display: grid;
 gap: 6px;
 border: 1px solid #b9d4f1;
 border-left: 3px solid var(--info, #3b82f6);
 border-radius: 4px;
 padding: 8px 10px;
 background: var(--info-bg, #eef4fd);
 font-size: 11px;
}

.research-pipeline-banner.success {
 border-color: #b9dfc9;
 border-left-color: var(--success);
 background: var(--success-bg);
}

.research-pipeline-banner.danger {
 border-color: #ffc9c9;
 border-left-color: var(--danger);
 background: var(--danger-bg);
}

.research-pipeline-banner-head {
 display: flex;
 align-items: center;
 justify-content: space-between;
 font-weight: 600;
}

.research-pipeline-banner-stage {
 display: inline-flex;
 align-items: center;
 gap: 5px;
}

.research-pipeline-banner-spin {
 animation: research-pipeline-banner-spin 1.4s linear infinite;
}

@keyframes research-pipeline-banner-spin {
 from { transform: rotate(0deg); }
 to { transform: rotate(360deg); }
}

.research-pipeline-banner-track {
 height: 4px;
 border-radius: 2px;
 background: rgba(0, 0, 0, 0.08);
 overflow: hidden;
}

.research-pipeline-banner-track > div {
 height: 100%;
 background: var(--info, #3b82f6);
 transition: width 0.3s ease;
}

.research-pipeline-banner.success .research-pipeline-banner-track > div { background: var(--success); }
.research-pipeline-banner.danger .research-pipeline-banner-track > div { background: var(--danger); }

.research-pipeline-banner p {
 margin: 0;
 color: inherit;
 opacity: 0.85;
}

.research-pipeline-banner-actions {
 display: flex;
 gap: 6px;
 justify-content: flex-end;
}

.research-pipeline-banner-actions button {
 display: inline-flex;
 align-items: center;
 gap: 4px;
 font-size: 11px;
 padding: 4px 8px;
}

.authoring-impact-panel {
 display: grid;
 gap: 8px;
 border: 1px solid #f1c27d;
 border-left: 3px solid var(--warning);
 border-radius: 4px;
 padding: 10px;
 background: var(--warning-bg);
}

.authoring-impact-panel > div:first-child {
 display: flex;
 align-items: flex-start;
 gap: 8px;
 color: var(--warning);
}

.authoring-impact-panel > div:first-child span {
 display: grid;
 gap: 2px;
}

.authoring-impact-panel small {
 font-size: 11px;
}

.authoring-impact-panel ul {
 display: flex;
 flex-wrap: wrap;
 gap: 5px;
 margin: 0;
 padding: 0;
 list-style: none;
}

.authoring-impact-panel li {
 border: 1px solid #efca93;
 border-radius: 3px;
 padding: 3px 6px;
 background: #fff;
 font-size: 11px;
}

.authoring-journey-message,
.authoring-journey-loading {
 margin: 0;
 border: 1px solid #b9dfc9;
 border-radius: 4px;
 padding: 8px 10px;
 background: var(--success-bg);
 color: var(--success);
 font-size: 11px;
}

.authoring-journey-message.danger {
 border-color: #ffc9c9;
 background: var(--danger-bg);
 color: var(--danger);
}

.authoring-journey-loading {
 display: flex;
 align-items: center;
 gap: 7px;
}

.authoring-journey-load-failure {
 min-height: 72px;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr) auto;
 align-items: center;
 gap: 10px;
 border: 1px solid #e4b067;
 border-left: 3px solid var(--warning);
 border-radius: 4px;
 padding: 12px;
 background: var(--warning-bg);
 color: var(--warning);
}

.authoring-journey-load-failure > div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.authoring-journey-load-failure span {
 color: var(--text-secondary);
 font-size: 12px;
 overflow-wrap: anywhere;
}

.authoring-journey-load-failure button {
 min-height: 34px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.authoring-corpus-stage > header {
 justify-content: space-between;
 gap: 12px;
}

.authoring-gate-status {
 flex: 0 0 auto;
 border: 1px solid currentColor;
 border-radius: 3px;
 padding: 4px 7px;
}

.authoring-gate-status.blocked {
 background: var(--warning-bg);
 color: var(--warning);
}

.authoring-gate-status.allowed {
 background: var(--success-bg);
 color: var(--success);
}

.authoring-gate-status.exception {
 background: var(--warning-bg);
 color: var(--warning);
}

.authoring-search-plan,
.authoring-gate-checklist,
.authoring-override,
.authoring-writing-entry {
 border-top: 1px solid var(--soft-line);
 padding-top: 10px;
}

.authoring-search-plan {
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 gap: 8px 12px;
}

.authoring-search-plan > div:first-child {
 gap: 8px;
}

.authoring-search-plan ol,
.authoring-search-plan p {
 grid-column: 1 / -1;
 margin: 0;
 font-size: 11px;
 line-height: 1.5;
}

.authoring-search-plan ol {
 padding-left: 22px;
 color: var(--muted);
}

.authoring-search-plan p {
 color: var(--text);
}

.authoring-search-plan .authoring-search-contract-error {
 color: var(--danger);
 font-weight: 600;
}

.authoring-search-contract {
 grid-column: 1 / -1;
 display: grid;
 grid-template-columns: minmax(360px, 0.9fr) minmax(420px, 1.1fr);
 border-top: 1px solid var(--soft-line);
 border-bottom: 1px solid var(--soft-line);
}

.authoring-search-contract > section {
 min-width: 0;
 padding: 10px 12px;
}

.authoring-search-contract > section + section {
 border-left: 1px solid var(--soft-line);
}

.authoring-search-contract > section > strong {
 display: block;
 margin-bottom: 7px;
 color: var(--text);
 font-size: 12px;
}

.authoring-search-contract dl,
.authoring-search-contract ul {
 margin: 0;
}

.authoring-search-contract dl {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 6px 14px;
}

.authoring-search-contract dl > div,
.authoring-search-contract li {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.authoring-search-contract dt,
.authoring-search-contract li b {
 color: var(--muted);
 font-size: 10px;
 font-weight: 500;
}

.authoring-search-contract dd,
.authoring-search-contract li span {
 margin: 0;
 color: var(--text);
 font-size: 11px;
 line-height: 1.45;
 overflow-wrap: anywhere;
}

.authoring-search-contract ul {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 7px 14px;
 padding: 0;
 list-style: none;
}

.authoring-gate-checklist {
 display: grid;
 gap: 7px;
}

.authoring-gate-checklist label {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 gap: 8px;
 border-bottom: 1px solid var(--soft-line);
 padding: 5px 0 8px;
 color: var(--text);
 font-size: 12px;
 line-height: 1.5;
}

.authoring-gate-checklist label > span {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.authoring-gate-checklist label > span small {
 color: var(--muted);
 font-size: 11px;
}

.authoring-gate-checklist label.satisfied {
 color: var(--success);
}

.authoring-override {
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 gap: 10px;
 align-items: end;
}

.authoring-override > summary {
 grid-column: 1 / -1;
 cursor: pointer;
 color: var(--warning);
 font-size: 12px;
 font-weight: 700;
}

.authoring-override label {
 display: grid;
 gap: 5px;
}

.authoring-override label > span {
 color: var(--muted);
 font-size: 11px;
}

.authoring-writing-entry {
 justify-content: space-between;
 gap: 12px;
}

.authoring-writing-entry > div {
 gap: 8px;
 color: var(--success);
}

@media (max-width: 1500px) {
 .authoring-prefill-fields {
 grid-template-columns: 1fr;
 }

 .authoring-field-grid.four,
 .authoring-choice-grid {
 grid-template-columns: repeat(2, minmax(0, 1fr));
 }

 .authoring-field-grid.four .span-4 {
 grid-column: 1 / -1;
 }

 .authoring-design-archetypes {
 grid-template-columns: repeat(2, minmax(0, 1fr));
 }

 .authoring-applicability-row {
 grid-template-columns: minmax(180px, 0.8fr) minmax(160px, 0.55fr) minmax(280px, 1.2fr) minmax(170px, 0.7fr);
 }
}

@media (max-width: 1399px) {
 .writing-layout:not(.writing-pre-document-layout) {
 grid-template-columns: minmax(0, 1.38fr) minmax(310px, 0.72fr);
 grid-template-areas:
 "editor ai"
 "map map";
 }

 .writing-layout:not(.writing-pre-document-layout) .writing-document-map {
 min-height: 0;
 height: 380px;
 }

 .writing-layout:not(.writing-pre-document-layout) .writing-section-buttons {
 grid-template-columns: repeat(4, minmax(0, 1fr));
 }
}

.greenfield-setup-shell {
 flex: 1;
 min-height: 0;
 display: flex;
 flex-direction: column;
 gap: 12px;
 padding: 4px 2px 2px;
 overflow-y: auto;
}

.greenfield-setup-head,
.greenfield-subhead,
.greenfield-setup-footer {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
}

.greenfield-setup-head {
 padding: 2px 0 10px;
 border-bottom: 1px solid var(--line);
}

.greenfield-setup-head > div {
 min-width: 0;
}

.greenfield-setup-head span,
.greenfield-project-fields label > span,
.greenfield-design-summary > span,
.greenfield-subhead > span,
.greenfield-setup-footer > span {
 color: var(--muted);
 font-size: 11px;
}

.greenfield-setup-head h2 {
 margin: 3px 0 0;
 color: var(--text);
 font-size: 18px;
 line-height: 1.35;
}

.greenfield-project-fields {
 display: grid;
 grid-template-columns: repeat(4, minmax(120px, 1fr));
 gap: 8px;
}

.greenfield-project-fields label,
.greenfield-design-summary {
 min-width: 0;
 display: grid;
 gap: 5px;
}

.greenfield-project-fields input,
.greenfield-design-summary textarea,
.greenfield-decision-list input {
 width: 100%;
 min-width: 0;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 color: var(--text);
}

.greenfield-project-fields input {
 height: 34px;
 padding: 0 9px;
}

.greenfield-title-field {
 grid-column: 1 / -1;
}

.greenfield-design-summary textarea {
 min-height: 58px;
 padding: 8px 9px;
 resize: vertical;
}

.greenfield-setup-grid {
 min-height: 0;
 display: grid;
 grid-template-columns: minmax(0, 1.18fr) minmax(280px, 0.82fr);
 gap: 10px;
}

.greenfield-setup-grid > section {
 min-width: 0;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fbfcfd;
 padding: 10px;
}

.greenfield-subhead {
 min-height: 28px;
 padding-bottom: 8px;
 border-bottom: 1px solid var(--soft-line);
}

.greenfield-subhead strong {
 min-width: 0;
 color: var(--text);
 font-size: 13px;
}

.greenfield-subhead button {
 min-height: 28px;
 display: inline-flex;
 align-items: center;
 gap: 5px;
}

.greenfield-section-options {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 5px 8px;
 padding-top: 8px;
}

.greenfield-section-options label {
 min-width: 0;
 min-height: 34px;
 display: grid;
 grid-template-columns: 16px minmax(0, 1fr);
 grid-template-rows: auto auto;
 align-items: start;
 column-gap: 6px;
 padding: 4px 5px;
 border-left: 2px solid transparent;
}

.greenfield-section-options label.nested {
 margin-left: 12px;
 border-left-color: #d8dde4;
}

.greenfield-section-options input {
 grid-row: 1 / 3;
 margin: 2px 0 0;
}

.greenfield-section-options span,
.greenfield-section-options small {
 min-width: 0;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.greenfield-section-options span {
 color: var(--text);
 font-size: 12px;
}

.greenfield-section-options small {
 color: var(--muted);
 font-size: 9px;
}

.greenfield-decision-list {
 display: grid;
 gap: 6px;
 padding-top: 8px;
}

.greenfield-decision-list > div:not(.greenfield-decision-empty) {
 min-width: 0;
 display: grid;
 grid-template-columns: 24px minmax(0, 1fr) 30px;
 gap: 6px;
 align-items: center;
}

.greenfield-decision-list > div > span {
 color: var(--muted);
 font-size: 10px;
 text-align: center;
}

.greenfield-decision-list input {
 height: 32px;
 padding: 0 8px;
}

.greenfield-decision-list button {
 width: 30px;
 height: 30px;
 display: grid;
 place-items: center;
 padding: 0;
}

.greenfield-decision-empty {
 min-height: 72px;
 display: grid;
 place-items: center;
 padding: 12px;
 color: var(--muted);
 font-size: 11px;
 text-align: center;
}

.greenfield-setup-footer {
 min-height: 42px;
 margin-top: auto;
 padding-top: 10px;
 border-top: 1px solid var(--line);
}

.greenfield-setup-footer > span {
 max-width: 70%;
}

.greenfield-setup-footer button {
 min-height: 34px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
}

.greenfield-decision-review {
 min-width: 0;
 display: grid;
 gap: 10px;
}

.greenfield-decision-review > header,
.greenfield-decision-review-head,
.greenfield-decision-review-actions {
 display: flex;
 align-items: center;
 gap: 8px;
}

.greenfield-decision-review > header {
 justify-content: space-between;
 padding-bottom: 9px;
 border-bottom: 1px solid var(--line);
}

.greenfield-decision-review > header > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.greenfield-decision-review > header span,
.greenfield-decision-review-form label > span,
.greenfield-decision-review-summary p > span {
 color: var(--muted);
 font-size: 11px;
}

.greenfield-decision-boundary,
.greenfield-decision-message {
 margin: 0;
 border: 1px solid #ffd99d;
 border-radius: 4px;
 padding: 8px;
 background: var(--warning-bg);
 color: var(--warning);
 font-size: 11px;
 line-height: 1.5;
}

.greenfield-decision-message:not(.danger) {
 border-color: #b9dfc9;
 background: var(--success-bg);
 color: var(--success);
}

.greenfield-decision-message.danger {
 border-color: #ffc9c9;
 background: var(--danger-bg);
 color: var(--danger);
}

.greenfield-decision-review-list {
 display: grid;
 gap: 8px;
}

.greenfield-decision-review-list > section {
 min-width: 0;
 border: 1px solid var(--line);
 border-left: 3px solid var(--warning);
 border-radius: 4px;
 padding: 9px;
 background: #fff;
}

.greenfield-decision-review-list > section.resolved {
 border-left-color: var(--success);
}

