 gap: 4px 8px;
 align-items: center;
 background: #fbfcfd;
}

.revision-evidence-package strong,
.revision-evidence-package span {
 min-width: 0;
}

.revision-evidence-package span {
 color: var(--muted);
 font-size: 12px;
}

.revision-evidence-package button {
 grid-column: 2;
 grid-row: 1 / span 2;
 min-height: 30px;
}

.mixed-ocr-review-panel {
 margin: 10px 0 14px;
 border: 1px solid #ead8bd;
 border-left: 3px solid #c26b22;
 border-radius: 6px;
 background: #fffdf9;
 color: #2d3137;
}

.mixed-ocr-review-summary {
 min-height: 58px;
 padding: 10px 12px;
 display: grid;
 grid-template-columns: minmax(260px, 1fr) auto auto;
 align-items: center;
 gap: 10px;
}

.mixed-ocr-review-summary > div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.mixed-ocr-review-summary strong {
 font-size: 14px;
 font-weight: 650;
}

.mixed-ocr-review-summary span,
.mixed-ocr-review-details p,
.mixed-ocr-review-message {
 color: #6b7280;
 font-size: 12px;
 line-height: 1.55;
}

.mixed-ocr-review-summary button {
 min-height: 34px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
 white-space: nowrap;
}

.mixed-ocr-review-details {
 border-top: 1px solid #eee3d2;
 padding: 0 12px 8px;
}

.mixed-ocr-review-details article {
 padding: 9px 0;
 display: grid;
 grid-template-columns: minmax(180px, 230px) minmax(0, 1fr);
 gap: 12px;
 border-bottom: 1px solid #f0ece5;
}

.mixed-ocr-review-details article:last-child {
 border-bottom: 0;
}

.mixed-ocr-review-details article > div {
 display: grid;
 align-content: start;
 gap: 2px;
}

.mixed-ocr-review-details article span {
 overflow: hidden;
 color: #7b818a;
 font-size: 11px;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.mixed-ocr-review-details p {
 margin: 0;
}

.mixed-ocr-review-message {
 margin: 0;
 padding: 0 12px 10px;
}

@media (max-width: 980px) {
 .mixed-ocr-review-summary {
 grid-template-columns: minmax(0, 1fr) auto;
 }

 .mixed-ocr-review-summary .primary-button {
 grid-column: 1 / -1;
 justify-content: center;
 }
}

.writing-reference-panel {
 width: 100%;
 min-width: 0;
 max-width: 100%;
 min-height: 0;
 display: flex;
 flex-direction: column;
 gap: 10px;
}

.writing-reference-panel.authoring-mode {
 min-height: 560px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 10px;
 background: #fff;
}

.writing-reference-panel.authoring-mode .writing-reference-views {
 grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
}

.writing-reference-panel.authoring-mode .writing-reference-list {
 max-height: 420px;
}

.shared-phase1-corpus {
 min-width: 0;
 display: grid;
 gap: 10px;
}

.shared-phase1-corpus-header {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 16px;
 padding-bottom: 9px;
 border-bottom: 1px solid var(--soft-line);
}

.shared-phase1-corpus-header > div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.shared-phase1-corpus-header span,
.shared-phase1-corpus-header small {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.shared-phase1-corpus-header strong {
 font-size: 15px;
}

.shared-phase1-corpus-metrics {
 display: grid;
 grid-template-columns: repeat(4, minmax(0, 1fr));
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #f8f9fa;
}

.shared-phase1-corpus-metrics span {
 min-width: 0;
 padding: 8px 12px;
 border-right: 1px solid var(--line);
 color: var(--muted);
 font-size: 11px;
}

.shared-phase1-corpus-metrics span:last-child {
 border-right: 0;
}

.shared-phase1-corpus-metrics b {
 margin-right: 4px;
 color: var(--text);
 font-size: 16px;
}

.shared-phase1-corpus-filters {
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(260px, 1fr) 190px 190px;
 gap: 8px;
}

.shared-phase1-corpus-filters label {
 min-width: 0;
 display: flex;
 align-items: center;
 gap: 6px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 0 8px;
 background: #fff;
}

.shared-phase1-corpus-filters input,
.shared-phase1-corpus-filters select {
 width: 100%;
 min-width: 0;
 height: 34px;
 border: 0;
 outline: 0;
 background: #fff;
}

.shared-phase1-corpus-filters > select {
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 0 8px;
}

.shared-phase1-corpus-message {
 margin: 0;
 border: 1px solid #bfe7ce;
 border-radius: 4px;
 padding: 8px 10px;
 color: var(--success);
 background: var(--success-bg);
 font-size: 12px;
}

.shared-phase1-corpus-message.danger {
 border-color: #ffc9c9;
 color: var(--danger);
 background: var(--danger-bg);
}

.shared-phase1-corpus-workspace {
 min-width: 0;
 min-height: 610px;
 display: grid;
 grid-template-columns: 290px minmax(0, 1fr);
 border: 1px solid var(--line);
 border-radius: 4px;
 overflow: hidden;
 background: #fff;
}

.shared-phase1-corpus-workspace > nav {
 min-width: 0;
 max-height: 740px;
 overflow-y: auto;
 border-right: 1px solid var(--line);
 background: #f8f9fa;
}

.shared-phase1-corpus-workspace > nav > button {
 width: 100%;
 min-width: 0;
 min-height: 96px;
 display: grid;
 gap: 5px;
 border: 0;
 border-bottom: 1px solid var(--line);
 border-radius: 0;
 padding: 10px 12px;
 color: var(--text);
 background: transparent;
 text-align: left;
}

.shared-phase1-corpus-workspace > nav > button.active {
 box-shadow: inset 3px 0 0 var(--orange);
 background: #fff7f2;
}

.shared-phase1-corpus-workspace > nav > button > span {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.shared-phase1-corpus-workspace > nav small {
 color: var(--muted);
 font-size: 10px;
 line-height: 1.35;
 overflow-wrap: anywhere;
}

.shared-phase1-corpus-workspace > nav > p,
.shared-phase1-corpus-empty {
 margin: 0;
 padding: 18px;
 color: var(--muted);
 font-size: 12px;
}

.shared-phase1-corpus-detail {
 min-width: 0;
 display: grid;
 align-content: start;
 gap: 12px;
 padding: 14px;
}

.shared-phase1-corpus-detail > header {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 12px;
}

.shared-phase1-corpus-detail > header > div:first-child {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.shared-phase1-corpus-detail > header > div:last-child {
 display: flex;
 flex-wrap: wrap;
 justify-content: flex-end;
 gap: 5px;
}

.shared-phase1-corpus-detail > header span,
.shared-phase1-corpus-detail > header small {
 color: var(--muted);
 font-size: 11px;
}

.shared-phase1-applicability,
.shared-phase1-review-comment {
 margin: 0;
 display: flex;
 align-items: flex-start;
 gap: 8px;
 border-left: 3px solid var(--info);
 padding: 7px 10px;
 color: #34495e;
 background: var(--info-bg);
 font-size: 12px;
 line-height: 1.5;
}

.shared-phase1-applicability span,
.shared-phase1-review-comment {
 min-width: 0;
 overflow-wrap: anywhere;
}

.shared-phase1-applicability b,
.shared-phase1-review-comment b {
 margin-right: 6px;
}

.shared-phase1-text-compare {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 border: 1px solid var(--line);
 border-radius: 4px;
 overflow: hidden;
}

.shared-phase1-text-compare > section {
 min-width: 0;
 display: grid;
 grid-template-rows: auto minmax(260px, auto);
}

.shared-phase1-text-compare > section + section {
 border-left: 1px solid var(--line);
}

.shared-phase1-text-compare header {
 min-height: 38px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
 padding: 8px 10px;
 border-bottom: 1px solid var(--line);
 background: #f7f8fa;
}

.shared-phase1-text-compare header span,
.shared-phase1-text-compare header a {
 color: var(--muted);
 font-size: 10px;
}

.shared-phase1-text-compare header a {
 display: inline-flex;
 align-items: center;
 gap: 4px;
}

.shared-phase1-text-compare p {
 min-width: 0;
 max-height: 390px;
 margin: 0;
 overflow-y: auto;
 padding: 12px;
 white-space: pre-wrap;
 overflow-wrap: anywhere;
 color: #26323d;
 font-size: 12px;
 line-height: 1.65;
}

.shared-phase1-lineage {
 border-top: 1px solid var(--soft-line);
 padding-top: 8px;
 color: var(--muted);
 font-size: 11px;
}

.shared-phase1-lineage summary {
 cursor: pointer;
 color: #425466;
}

.shared-phase1-lineage dl {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 6px 14px;
}

.shared-phase1-lineage dl > div {
 min-width: 0;
 display: grid;
 grid-template-columns: 62px minmax(0, 1fr);
 gap: 6px;
}

.shared-phase1-lineage dd {
 margin: 0;
 overflow-wrap: anywhere;
}

.shared-phase1-review-actions {
 min-width: 0;
 display: grid;
 gap: 8px;
 border-top: 1px solid var(--line);
 padding-top: 10px;
}

.shared-phase1-review-actions label {
 min-width: 0;
 display: grid;
 gap: 5px;
 color: var(--muted);
 font-size: 11px;
 font-weight: 700;
}

.shared-phase1-review-actions textarea {
 min-height: 68px;
 resize: vertical;
}

.shared-phase1-review-actions > div {
 display: flex;
 justify-content: flex-end;
 gap: 7px;
}

.writing-reference-candidate-filters {
 display: grid;
 grid-template-columns: minmax(280px, 1fr) 170px auto;
 gap: 8px;
 align-items: center;
}

.writing-reference-candidate-filters label {
 min-width: 0;
 display: flex;
 align-items: center;
 gap: 6px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 0 8px;
 background: #fff;
}

.writing-reference-candidate-filters input {
 min-width: 0;
 width: 100%;
 height: 32px;
 border: 0;
 outline: 0;
}

.writing-reference-candidate-filters select {
 height: 34px;
}

.writing-reference-candidate-filters > span,
.writing-reference-pagination span {
 color: var(--muted);
 font-size: 11px;
}

.writing-reference-pagination {
 display: flex;
 justify-content: flex-end;
 align-items: center;
 gap: 8px;
}

.writing-reference-triage-finalize,
.writing-reference-alignment {
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 gap: 8px 12px;
 align-items: end;
 border-top: 1px solid var(--soft-line);
 padding-top: 10px;
}

.writing-reference-triage-finalize > div,
.writing-reference-alignment > div {
 grid-column: 1 / -1;
 display: grid;
 gap: 2px;
}

.writing-reference-triage-finalize > div span,
.writing-reference-alignment > div span {
 color: var(--muted);
 font-size: 11px;
}

.writing-reference-triage-finalize label,
.writing-reference-alignment label {
 min-width: 0;
 display: grid;
 gap: 4px;
 color: var(--muted);
 font-size: 11px;
 font-weight: 700;
}

.writing-reference-triage-finalize textarea,
.writing-reference-alignment textarea {
 min-height: 64px;
 resize: vertical;
}

.writing-reference-alignment label:last-of-type {
 grid-column: 1 / -1;
}

.writing-reference-alignment button {
 grid-column: 2;
 justify-self: end;
}

.writing-reference-header {
 min-height: 36px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
 border-bottom: 1px solid var(--soft-line);
 padding-bottom: 8px;
}

.writing-reference-header > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.writing-reference-header span {
 color: var(--muted);
 font-size: 11px;
}

.writing-reference-header strong {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.writing-reference-header .icon-button {
 width: 32px;
 min-width: 32px;
 min-height: 30px;
 padding: 0;
 display: inline-flex;
 align-items: center;
 justify-content: center;
}

.writing-reference-boundary,
.writing-reference-message,
.writing-reference-invalid,
.writing-reference-admitted {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 8px;
 font-size: 12px;
 line-height: 1.5;
}

.writing-reference-boundary {
 color: #38516a;
 background: var(--info-bg);
 border-color: #c9ddff;
}

.writing-reference-message {
 color: var(--success);
 background: var(--success-bg);
 border-color: #bfe7ce;
}

.writing-reference-message.danger,
.writing-reference-invalid {
 color: var(--danger);
 background: var(--danger-bg);
 border-color: #ffc9c9;
}

.writing-reference-invalid,
.writing-reference-admitted {
 display: flex;
 align-items: flex-start;
 gap: 6px;
}

.writing-reference-admitted {
 color: var(--success);
 background: var(--success-bg);
 border-color: #bfe7ce;
}

.writing-reference-views {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 4px;
}

.writing-reference-views button {
 min-width: 0;
 min-height: 30px;
 padding: 0 6px;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
 background: #f7f8fa;
 border: 1px solid var(--line);
 color: var(--text);
}

.writing-reference-views button.active {
 color: var(--orange-dark);
 border-color: #f6b58e;
 background: #fff6f0;
 font-weight: 700;
}

.writing-reference-view {
 width: 100%;
 min-width: 0;
 min-height: 0;
 display: flex;
 flex: 1;
 flex-direction: column;
 gap: 10px;
}

.writing-reference-manual-upload {
 display: grid;
 grid-template-columns: minmax(0, 1fr) minmax(112px, 160px);
 gap: 8px;
 align-items: end;
 border: 1px solid var(--line);
 border-left: 3px solid var(--info);
 border-radius: 4px;
 padding: 9px;
 background: #f8fbff;
}

.writing-reference-panel.authoring-mode .writing-reference-manual-upload {
 grid-template-columns: minmax(260px, 1.5fr) minmax(130px, 0.6fr) minmax(150px, 0.7fr) max-content;
}

.writing-reference-manual-upload-head {
 grid-column: 1 / -1;
 display: flex;
 align-items: flex-start;
 gap: 8px;
}

.writing-reference-manual-upload-head > span {
 width: 28px;
 height: 28px;
 flex: 0 0 auto;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 border: 1px solid #bfdbfe;
 border-radius: 4px;
 color: var(--info);
 background: #fff;
}

.writing-reference-manual-upload-head > div,
.writing-reference-manual-upload label {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.writing-reference-manual-upload-head small,
.writing-reference-manual-upload label,
.writing-reference-manual-upload-state {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.4;
}

.writing-reference-manual-upload input,
.writing-reference-manual-upload select {
 width: 100%;
 min-width: 0;
 height: 34px;
}

.writing-reference-manual-upload input[type="file"] {
 padding: 5px 7px;
 border: 1px solid var(--line);
 border-radius: 4px;
 background: #fff;
 font-size: 11px;
}

.writing-reference-manual-upload .primary-button {
 min-height: 34px;
 white-space: nowrap;
}

.writing-reference-manual-upload-state {
 grid-column: 1 / -1;
 overflow-wrap: anywhere;
}

.writing-reference-document-row.manual {
 border-left: 3px solid var(--info);
}

.writing-reference-document-row.manual > div {
 flex-wrap: wrap;
}

.writing-reference-search {
 display: grid;
 grid-template-columns: minmax(0, 1fr) 104px;
 gap: 7px;
}

.writing-reference-search label,
.writing-reference-actions label,
.writing-reference-review label,
.writing-reference-select {
 display: grid;
 gap: 4px;
 color: var(--muted);
 font-size: 12px;
 font-weight: 700;
}

.writing-reference-search .primary-button {
 grid-column: 1 / -1;
 justify-content: center;
}

.writing-reference-snapshot {
 margin: 0;
 color: var(--muted);
 font-size: 11px;
 overflow-wrap: anywhere;
}

.writing-reference-list {
 min-height: 0;
 display: flex;
 flex: 1;
 flex-direction: column;
 gap: 6px;
 overflow-y: auto;
 padding-right: 2px;
}

.writing-reference-list > button,
.writing-reference-document-row,
.writing-reference-brief {
 width: 100%;
 min-width: 0;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 8px;
 background: #fff;
 text-align: left;
}

.writing-reference-list > button {
 display: grid;
 gap: 5px;
}

.writing-reference-list > button.active {
 border-color: #f6b58e;
 box-shadow: inset 3px 0 0 var(--orange);
 background: #fffaf7;
}

.writing-reference-list > button > span,
.writing-reference-document-row > div,
.writing-reference-selection-head,
.writing-reference-review-state {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 7px;
}

.writing-reference-validation {
 min-width: 0;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 8px;
 display: grid;
 gap: 7px;
 background: #fff;
 font-size: 12px;
}

.writing-reference-validation.requires-review {
 border-color: #f0c989;
 background: #fffbf3;
}

.writing-reference-validation > div:first-child {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 8px;
}

.writing-reference-validation p,
.writing-reference-validation small {
 margin: 0;
 color: var(--muted);
 line-height: 1.45;
}

.writing-reference-structure-review {
 min-width: 0;
 border: 1px solid #f0c989;
 border-left: 3px solid #ea580c;
 border-radius: 4px;
 padding: 8px;
 display: grid;
 gap: 7px;
 background: #fffaf5;
 font-size: 12px;
}

.writing-reference-structure-review.approved {
 border-color: #bfe7ce;
 border-left-color: var(--success);
 background: var(--success-bg);
}

.writing-reference-structure-review > div:first-child,
.writing-reference-anchor-list {
 display: flex;
 align-items: center;
 gap: 6px;
}

.writing-reference-structure-review > div:first-child {
 justify-content: space-between;
}

.writing-reference-structure-review p,
.writing-reference-structure-review small {
 margin: 0;
 color: var(--muted);
 line-height: 1.45;
 overflow-wrap: anywhere;
}

.writing-reference-structure-review label {
 display: grid;
 gap: 4px;
 color: var(--muted);
 font-size: 12px;
 font-weight: 700;
}

.writing-reference-structure-review textarea {
 min-height: 58px;
 resize: vertical;
}

.writing-reference-structure-review .button-row {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 5px;
}

.writing-reference-anchor-list {
 flex-wrap: wrap;
}

.writing-reference-anchor-list span {
 border: 1px solid #d9dee5;
 border-radius: 3px;
 padding: 2px 5px;
 background: #fff;
 color: #4c5967;
 font-size: 10px;
}

.writing-reference-span-controls {
 width: 100%;
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(150px, 0.8fr) minmax(240px, 1.4fr) auto;
 align-items: end;
 gap: 8px;
}

.writing-reference-span-pager {
 min-height: 34px;
 display: flex;
 align-items: center;
 justify-content: flex-end;
 gap: 5px;
 color: var(--muted);
 font-size: 11px;
 white-space: nowrap;
}

.writing-reference-span-pager button {
 width: 30px;
 min-width: 30px;
 height: 30px;
 padding: 0;
}

.writing-reference-select,
.writing-reference-span-controls label,
.writing-reference-span-controls select {
 min-width: 0;
 max-width: 100%;
}

.writing-reference-select select,
.writing-reference-span-controls select {
 width: 100%;
}

@media (max-width: 1399px) {
 .writing-reference-span-controls {
 grid-template-columns: minmax(140px, 0.8fr) minmax(220px, 1.2fr);
 }

 .writing-reference-span-pager {
 grid-column: 1 / -1;
 }
}

.writing-reference-panel:not(.authoring-mode) .writing-reference-span-controls {
 grid-template-columns: minmax(0, 1fr);
}

.writing-reference-panel:not(.authoring-mode) .writing-reference-span-pager {
 grid-column: 1;
 justify-content: flex-start;
 white-space: normal;
}

.writing-reference-validation-checks {
 display: grid;
 gap: 4px;
}

.writing-reference-validation-checks > div {
 display: grid;
 grid-template-columns: 64px 48px minmax(0, 1fr);
 gap: 6px;
 align-items: start;
 padding-top: 4px;
 border-top: 1px solid var(--soft-line);
}

.writing-reference-validation-checks b {
 font-size: 11px;
}

.writing-reference-validation-checks small {
 min-width: 0;
 overflow-wrap: anywhere;
 word-break: break-word;
}

.writing-reference-override {
 border-top: 1px solid var(--soft-line);
 padding-top: 7px;
 display: grid;
 gap: 6px;
}

.writing-reference-validation.requires-review {
 border-left: 3px solid #ea580c;
 background: #fffaf5;
}

.writing-reference-override textarea {
 min-height: 64px;
 resize: vertical;
}

.writing-reference-override-warning {
 display: flex;
 align-items: flex-start;
 gap: 6px;
 color: #9a3412;
 font-size: 11px;
 line-height: 1.45;
}

.writing-reference-override-warning svg {
 flex: 0 0 auto;
 margin-top: 1px;
}

.writing-reference-override fieldset {
 min-width: 0;
 margin: 0;
 padding: 7px;
 border: 1px solid #fed7aa;
 border-radius: 4px;
 display: grid;
 gap: 6px;
}

.writing-reference-override legend {
 padding: 0 4px;
 color: var(--muted);
 font-size: 11px;
}

.writing-reference-override-check {
 display: grid;
 grid-template-columns: 16px minmax(0, 1fr);
 align-items: start;
 gap: 6px;
 cursor: pointer;
}

.writing-reference-override-check input {
 margin: 2px 0 0;
}

.writing-reference-override-check span,
.writing-reference-override-check small {
 min-width: 0;
 display: block;
}

.writing-reference-override-check small {
 margin-top: 2px;
 overflow-wrap: anywhere;
 color: var(--muted);
 line-height: 1.4;
}

.writing-reference-override-record {
 display: grid;
 grid-template-columns: max-content minmax(0, 1fr);
 align-items: start;
 gap: 8px;
 padding: 7px;
 border: 1px solid #bfdbfe;
 border-radius: 4px;
 background: #eff6ff;
}

.writing-reference-override-record p {
 min-width: 0;
 margin: 0;
 overflow-wrap: anywhere;
 font-size: 11px;
 line-height: 1.45;
}

.writing-reference-override-record strong {
 display: block;
 margin-bottom: 2px;
}

.writing-reference-list > button strong,
.writing-reference-list > button small,
.writing-reference-document-row strong,
.writing-reference-brief strong,
.writing-reference-brief small {
 min-width: 0;
 overflow-wrap: anywhere;
}

.writing-reference-list > button > strong {
 display: -webkit-box;
 -webkit-box-orient: vertical;
 -webkit-line-clamp: 2;
 overflow: hidden;
 line-height: 1.4;
}

.writing-reference-list small,
.writing-reference-document-row p,
.writing-reference-brief small {
 margin: 0;
 color: var(--muted);
 font-size: 11px;
 line-height: 1.4;
}

.writing-reference-actions,
.writing-reference-review {
 min-width: 0;
 border-top: 1px solid var(--soft-line);
 padding-top: 9px;
 display: grid;
 gap: 8px;
}

.writing-reference-actions textarea,
.writing-reference-review textarea {
 min-height: 68px;
 resize: vertical;
}

.writing-reference-actions .button-row,
.writing-reference-review .button-row {
 display: grid;
 grid-template-columns: repeat(3, minmax(0, 1fr));
 gap: 5px;
}

.writing-reference-actions .button-row button,
.writing-reference-review .button-row button {
 min-width: 0;
 min-height: 34px;
 padding: 4px 6px;
 white-space: normal;
 line-height: 1.25;
}

.writing-reference-document-row {
 display: grid;
 gap: 7px;
}

.writing-reference-document-row > div {
 justify-content: flex-start;
}

.writing-reference-document-row code,
.writing-reference-source code,
.writing-reference-brief code {
 color: #4c5967;
 font-size: 10px;
 overflow-wrap: anywhere;
 white-space: normal;
}

.writing-reference-document-row a,
.writing-reference-document-row button {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 5px;
}

.writing-reference-document-row a {
 border: 1px solid var(--line);
 border-radius: 4px;
 color: var(--text);
 text-decoration: none;
}

.writing-reference-source,
.writing-reference-translation {
 min-width: 0;
 max-width: 100%;
 display: grid;
 gap: 6px;
}

.writing-reference-source > span,
.writing-reference-translation > span {
 color: var(--muted);
 font-size: 11px;
 font-weight: 700;
}

.writing-reference-source p,
.writing-reference-translation p {
 min-width: 0;
 max-width: 100%;
 max-height: 180px;
 margin: 0;
 overflow-y: auto;
 overflow-wrap: anywhere;
 word-break: break-word;
 white-space: pre-wrap;
 line-height: 1.55;
}

.writing-reference-cross-page-source {
 border-top: 1px solid var(--soft-line);
 padding-top: 6px;
}

.writing-reference-cross-page-source summary {
 color: #314a61;
 cursor: pointer;
 font-size: 11px;
 font-weight: 700;
}

.writing-reference-cross-page-source > div {
 margin-top: 6px;
 display: grid;
 gap: 7px;
}

.writing-reference-cross-page-source section {
 min-width: 0;
 border-left: 2px solid #d0a55d;
 padding-left: 8px;
}

.writing-reference-cross-page-source section p {
 max-height: 96px;
 margin-top: 3px;
 font-size: 12px;
}

.writing-reference-cross-page-source small {
 color: var(--muted);
 font-size: 10px;
}

.writing-reference-translation {
 border-top: 1px solid var(--soft-line);
 padding-top: 8px;
}

.writing-reference-review-state {
 align-items: flex-start;
 justify-content: flex-start;
 color: var(--muted);
 font-size: 12px;
}

.writing-reference-selection-head {
 min-height: 30px;
 border-bottom: 1px solid var(--soft-line);
 padding-bottom: 7px;
}

.writing-reference-selection-head span {
