}

.approval-blockers {
 color: var(--warning);
 background: var(--warning-bg);
 border-color: #ffd99d;
}

.approval-clear {
 color: var(--success);
 background: var(--success-bg);
 border-color: #bfe4c9;
}

.approval-pending {
 color: var(--info);
 background: var(--info-bg);
 border-color: #c9d9ee;
}

.approval-blockers p,
.approval-clear p,
.approval-pending p,
.approval-message {
