 align-items: center;
 gap: 6px;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 0 8px;
 min-height: 34px;
}

.evidence-search-row input {
 flex: 1;
 border: 0;
 background: transparent;
 outline: none;
 font-size: 13px;
 min-width: 0;
}

.evidence-search-row button {
 border: 0;
 background: transparent;
 padding: 2px;
 color: var(--muted);
}

.evidence-refresh-button {
 display: inline-flex;
 align-items: center;
 gap: 4px;
 border: 1px solid var(--line);
 background: #fbfcfd;
 border-radius: 4px;
 min-height: 30px;
 padding: 0 10px;
 font-size: 12px;
}

.evidence-picos-stats {
 display: grid;
 grid-template-columns: repeat(3, 1fr);
 gap: 8px;
 margin-bottom: 8px;
}

.evidence-picos-stats > div {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 6px;
 text-align: center;
}

.evidence-picos-stats strong {
 display: block;
 font-size: 16px;
}

.evidence-picos-stats span {
 font-size: 11px;
 color: var(--muted);
}

.evidence-candidate-panel,
.evidence-picos-panel {
 display: flex;
 flex-direction: column;
 gap: 10px;
 min-height: 0;
 flex: 1;
}

.evidence-synthesis-strip {
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 gap: 6px 12px;
 align-items: center;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #fbfcfd;
 padding: 8px 10px;
}

.evidence-synthesis-strip > div {
 display: flex;
 flex-wrap: wrap;
 gap: 5px;
}

.evidence-synthesis-strip span {
 border-left: 2px solid #e97828;
 color: var(--muted);
 font-size: 11px;
 padding: 2px 6px;
}

.evidence-synthesis-strip p {
 grid-column: 1 / -1;
 color: var(--warning);
 font-size: 11px;
 margin: 0;
}

.evidence-table-toolbar {
 display: flex;
 align-items: center;
 gap: 10px;
 flex-wrap: wrap;
}

.evidence-table-range {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 color: var(--muted);
 font-size: 12px;
}

.evidence-table-paging {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 margin-left: auto;
}

.evidence-table-paging button {
 border: 1px solid var(--line);
 background: #fff;
 border-radius: 4px;
 width: 28px;
 height: 28px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
}

.evidence-table-paging button:disabled {
 opacity: 0.5;
 cursor: not-allowed;
}

.evidence-table-scroll {
 flex: 1;
 overflow: auto;
 border: 1px solid var(--line);
 border-radius: 4px;
 min-height: 0;
}

.evidence-candidate-table {
 width: 100%;
 min-width: 920px;
 border-collapse: collapse;
 font-size: 13px;
}

.evidence-candidate-table th,
.evidence-candidate-table td {
 border-bottom: 1px solid var(--soft-line);
 padding: 8px 10px;
 text-align: left;
 vertical-align: top;
 white-space: nowrap;
}

.evidence-candidate-table th {
 background: #fbfcfd;
 color: var(--muted);
 font-weight: 600;
 font-size: 12px;
 position: sticky;
 top: 0;
 z-index: 1;
}

.evidence-candidate-table tbody tr:hover {
 background: #f8fafc;
 cursor: pointer;
}

.evidence-candidate-table tbody tr.selected {
 background: #fff6ef;
}

.evidence-candidate-table td strong {
 display: block;
 font-weight: 600;
 max-width: 220px;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.evidence-candidate-table .evidence-subtype {
 display: block;
 color: var(--muted);
 font-size: 11px;
}

.evidence-candidate-table td:nth-child(2) {
 white-space: normal;
 min-width: 200px;
}

.evidence-col-check {
 width: 28px;
 padding: 0 8px;
 text-align: center;
}

.evidence-empty-state,
.evidence-quiet {
 color: var(--muted);
 font-size: 13px;
 padding: 16px 0;
}

.evidence-error,
.evidence-error-message {
 color: var(--danger);
 background: var(--danger-bg);
 border: 1px solid #ffc9c9;
 border-radius: 4px;
 padding: 8px 10px;
 font-size: 13px;
}

.evidence-detail-panel,
.evidence-picos-right,
.evidence-ai-panel {
 display: flex;
 flex-direction: column;
 gap: 12px;
}

.evidence-detail-panel h4,
.evidence-picos-right h4,
.evidence-ai-panel h4 {
 margin: 0;
 font-size: 14px;
 font-weight: 600;
 border-bottom: 1px solid var(--soft-line);
 padding-bottom: 8px;
}

.evidence-detail-head {
 display: grid;
 gap: 6px;
}

.evidence-detail-head strong {
 font-size: 14px;
 line-height: 1.4;
}

.evidence-detail-head span {
 color: var(--muted);
 font-size: 12px;
}

.evidence-detail-meta {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: 8px;
}

.evidence-detail-meta > div,
.evidence-detail-refs > div,
.evidence-detail-metadata > div {
 display: flex;
 flex-direction: column;
 gap: 2px;
 font-size: 12px;
}

.evidence-detail-meta span,
.evidence-detail-refs > span,
.evidence-detail-metadata > span {
 color: var(--muted);
 font-size: 11px;
}

.evidence-detail-refs > div,
.evidence-detail-metadata {
 display: grid;
 gap: 6px;
}

.evidence-detail-refs > div span,
.evidence-detail-metadata strong {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 4px 6px;
 background: #f8fafc;
 font-size: 12px;
 word-break: break-all;
}

.evidence-detail-actions,
.evidence-picos-actions,
.evidence-ai-proposal-actions {
 display: flex;
 flex-wrap: wrap;
 gap: 8px;
}

.evidence-detail-actions button,
.evidence-picos-actions button,
.evidence-ai-proposal-actions button,
.evidence-picos-handoff button,
.evidence-ai-panel button.primary-button {
 display: inline-flex;
 align-items: center;
 gap: 4px;
 border: 1px solid var(--line);
 background: #fbfcfd;
 border-radius: 4px;
 min-height: 32px;
 padding: 0 10px;
 font-size: 12px;
}

.evidence-detail-actions button.primary-button,
.evidence-picos-actions button.primary-button,
.evidence-ai-panel button.primary-button,
.evidence-picos-handoff button.primary-button,
.evidence-ai-apply button.primary-button {
 background: var(--orange);
 border-color: var(--orange);
 color: #fff;
}

.evidence-detail-actions button:disabled,
.evidence-picos-actions button:disabled,
.evidence-ai-proposal-actions button:disabled,
.evidence-picos-handoff button:disabled,
.evidence-ai-panel button:disabled {
 opacity: 0.5;
 cursor: not-allowed;
}

.evidence-picos-handoff button.evidence-complete-button:disabled {
 background: #edf8f1;
 border-color: #b9dfc8;
 color: #237a49;
 opacity: 1;
}

.writing-page button.writing-complete-button:disabled {
 background: #edf8f1;
 border-color: #b9dfc8;
 color: #237a49;
 opacity: 1;
}

.evidence-detail-reason,
.evidence-picos-rationale,
.evidence-ai-instruction,
.evidence-ai-rewrite {
 display: grid;
 gap: 6px;
}

.evidence-detail-reason span,
.evidence-picos-rationale span,
.evidence-ai-instruction span,
.evidence-ai-rewrite span {
 color: var(--muted);
 font-size: 12px;
}

.evidence-detail-reason textarea,
.evidence-picos-rationale textarea,
.evidence-ai-instruction textarea,
.evidence-ai-rewrite textarea {
 min-height: 80px;
 resize: vertical;
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 8px;
 font-size: 13px;
}

.evidence-detail-section {
 border-top: 1px solid var(--soft-line);
 padding-top: 12px;
 display: grid;
 gap: 8px;
}

.evidence-detail-section h5 {
 margin: 0;
 font-size: 13px;
 font-weight: 600;
}

.evidence-extraction-row {
 display: grid;
 grid-template-columns: 1fr 1fr auto;
 gap: 6px;
 align-items: center;
}

.evidence-extraction-row input,
.evidence-detail-reason textarea:disabled {
 border: 1px solid var(--line);
 border-radius: 4px;
 padding: 6px 8px;
 font-size: 12px;
}

.evidence-add-row,
.evidence-save-extraction,
.evidence-save-appraisal {
 justify-self: start;
}

.evidence-appraisal-options {
 display: flex;
 gap: 6px;
}

.evidence-appraisal-options button {
 border: 1px solid var(--line);
 background: #fff;
 border-radius: 4px;
 padding: 6px 10px;
 font-size: 12px;
}

.evidence-appraisal-options button.selected {
 border-color: #e97828;
 background: #fff6ef;
}

.evidence-review-message,
.evidence-picos-message {
 border: 1px solid #bfe7ce;
 background: #edf8f1;
 color: var(--success);
 border-radius: 4px;
 padding: 8px 10px;
 font-size: 12px;
}

.evidence-picos-panel {
 min-height: 0;
}

.evidence-picos-editor {
 display: flex;
 flex-direction: column;
 gap: 14px;
}

.evidence-picos-question {
 display: grid;
 gap: 8px;
}

.evidence-picos-question h3 {
 margin: 0;
 font-size: 15px;
}

.evidence-picos-question p {
 margin: 0;
 color: var(--muted);
 font-size: 13px;
 line-height: 1.55;
}

.evidence-picos-sources {
 display: flex;
 flex-wrap: wrap;
 gap: 5px;
}

.evidence-picos-sources span {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 background: #f8fafc;
 color: var(--muted);
 font-size: 11px;
 padding: 3px 6px;
 overflow-wrap: anywhere;
}

.evidence-picos-options {
 display: grid;
 gap: 8px;
}

.evidence-picos-options button {
 text-align: left;
 border: 1px solid var(--soft-line);
 background: #fff;
 border-radius: 4px;
 padding: 10px;
 font-size: 13px;
}

.evidence-picos-options button.selected {
 border-color: #e97828;
 background: #fff6ef;
}

.evidence-picos-options button strong {
 display: block;
 font-weight: 600;
 margin-bottom: 4px;
}

.evidence-picos-options button span {
 display: block;
 color: var(--text);
 font-size: 12px;
 margin-bottom: 4px;
}

.evidence-picos-options button em {
 display: block;
 color: var(--muted);
 font-size: 12px;
 font-style: normal;
}

.evidence-picos-summary,
.evidence-picos-handoff {
 display: grid;
 gap: 10px;
}

.evidence-picos-summary > div,
.evidence-picos-handoff > div {
 display: flex;
 flex-direction: column;
 gap: 2px;
 font-size: 12px;
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 8px;
}

.evidence-picos-summary span,
.evidence-picos-handoff span {
 color: var(--muted);
 font-size: 11px;
}

.evidence-picos-handoff-note {
 color: var(--muted);
 font-size: 12px;
 line-height: 1.55;
 margin: 0;
}

.evidence-ai-panel {
 gap: 10px;
}

.evidence-ai-boundary {
 border: 1px solid #ffd99d;
 background: #fff6e6;
 color: #7a3a0c;
 border-radius: 4px;
 padding: 8px 10px;
 font-size: 12px;
}

.evidence-ai-disabled {
 display: flex;
 align-items: center;
 gap: 8px;
 border: 1px solid #ffc9c9;
 background: var(--danger-bg);
 color: var(--danger);
 border-radius: 4px;
 padding: 8px 10px;
 font-size: 12px;
}

.evidence-ai-anchors {
 display: grid;
 gap: 4px;
 font-size: 12px;
}

.evidence-ai-anchors span {
 color: var(--muted);
 font-size: 11px;
}

.evidence-ai-anchors > div {
 display: flex;
 flex-wrap: wrap;
 gap: 4px;
 max-height: 84px;
 overflow: auto;
}

.evidence-ai-anchors > div > span {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 3px 6px;
 background: #f8fafc;
 font-size: 11px;
 max-width: 120px;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.evidence-ai-threads {
 display: grid;
 gap: 12px;
 max-height: 420px;
 overflow: auto;
}

.evidence-ai-thread {
 border: 1px solid var(--soft-line);
 border-radius: 4px;
 padding: 10px;
 display: grid;
 gap: 8px;
}

.evidence-ai-thread-head {
 display: flex;
 justify-content: space-between;
 font-size: 12px;
 color: var(--muted);
 border-bottom: 1px solid var(--soft-line);
 padding-bottom: 6px;
}

.evidence-ai-proposal {
 display: grid;
 gap: 8px;
}

.evidence-ai-proposal > div {
 display: grid;
 gap: 2px;
 font-size: 12px;
}

.evidence-ai-proposal > div span {
 color: var(--muted);
 font-size: 11px;
}

.evidence-ai-proposal > div p {
 margin: 0;
 line-height: 1.5;
}

.evidence-ai-proposal > div strong {
 font-weight: 600;
}

.evidence-ai-rewrite textarea {
 min-height: 60px;
}

.evidence-ai-apply {
 border-top: 1px solid var(--soft-line);
 padding-top: 8px;
}

.spin {
 animation: spin 1s linear infinite;
}

@keyframes spin {
 from { transform: rotate(0deg); }
 to { transform: rotate(360deg); }
}

@media (max-width: 1279px) {
 .evidence-workspace-grid {
 grid-template-columns: 1fr;
 grid-template-rows: auto 1fr auto;
 height: auto;
 }
}

.writing-reference-preparation-batch {
 border: 1px solid var(--line);
 background: var(--surface);
 display: grid;
 gap: 12px;
 padding: 14px;
}

.writing-reference-batch-head {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 16px;
}

.writing-reference-batch-head > div {
 display: grid;
 gap: 3px;
 min-width: 0;
}

.writing-reference-batch-head > div > span,
.writing-reference-batch-head small {
 color: var(--muted);
 font-size: 12px;
}

.writing-reference-batch-head strong {
 font-size: 15px;
}

.writing-reference-batch-status,
.writing-reference-stage {
 border: 1px solid var(--line);
 border-radius: 4px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 min-height: 24px;
 padding: 2px 7px;
 font-size: 12px;
 font-weight: 600;
 white-space: nowrap;
}

.writing-reference-batch-status.accepted,
.writing-reference-batch-status.running,
.writing-reference-stage.info {
 color: var(--info);
 background: var(--info-bg);
 border-color: #c9daf7;
}

.writing-reference-batch-status.partial_failure,
.writing-reference-batch-status.failed,
.writing-reference-stage.danger {
 color: var(--danger);
 background: var(--danger-bg);
 border-color: #f0c2c2;
}

.writing-reference-batch-status.completed_with_review_required,
.writing-reference-batch-status.completed_with_manual_upload_required,
.writing-reference-batch-status.not_started,
.writing-reference-stage.warning {
 color: var(--warning);
 background: var(--warning-bg);
 border-color: #ead19f;
}

.writing-reference-batch-status.completed,
.writing-reference-stage.success {
 color: var(--success);
 background: var(--success-bg);
 border-color: #bbdfc8;
}

.writing-reference-batch-summary {
 border-block: 1px solid var(--soft-line);
 display: grid;
 grid-template-columns: repeat(5, minmax(110px, 1fr));
}

.writing-reference-batch-summary > span {
 display: flex;
 align-items: baseline;
 gap: 5px;
 min-height: 44px;
 padding: 10px 12px;
 color: var(--muted);
 font-size: 12px;
}

.writing-reference-batch-summary > span + span {
 border-left: 1px solid var(--soft-line);
}

.writing-reference-batch-summary b {
 color: var(--text);
 font-size: 16px;
}

.writing-reference-batch-summary .danger,
.writing-reference-batch-summary .danger b {
 color: var(--danger);
}

.writing-reference-batch-summary .warning,
.writing-reference-batch-summary .warning b {
 color: var(--warning);
}

/* Writing reference progress journey */
.writing-reference-progress-compact {
 display: flex;
 align-items: center;
 padding: 8px 12px;
 background: #f8f9fb;
 border: 1px solid var(--soft-line);
 border-radius: 6px;
 margin: 8px 0;
}

.writing-reference-progress-content {
 display: grid;
 width: 100%;
 gap: 7px;
}

.writing-reference-progress-compact .progress-summary {
 display: flex;
 flex-wrap: wrap;
 gap: 12px;
 font-size: 13px;
 color: var(--text);
}

.writing-reference-progress-compact .success {
 color: var(--success);
}

.writing-reference-progress-compact .danger {
 color: var(--danger);
}

.writing-reference-progress-compact .info {
 color: var(--info);
}

.writing-reference-progress-compact .muted {
 color: var(--muted);
}

.writing-reference-progress-journey {
 padding: 12px;
 background: #f8f9fb;
 border: 1px solid var(--soft-line);
 border-radius: 6px;
 margin: 8px 0;
}

.writing-reference-progress-journey .progress-header {
 display: flex;
 justify-content: space-between;
 align-items: center;
 margin-bottom: 10px;
 font-size: 13px;
}

.writing-reference-progress-journey .progress-header strong {
 color: var(--text);
}

.writing-reference-progress-track {
 width: 100%;
 height: 5px;
 overflow: hidden;
 background: #e6e9ee;
 border-radius: 3px;
}

.writing-reference-progress-track > span {
 display: block;
 height: 100%;
 min-width: 0;
 background: var(--cms-orange);
 border-radius: inherit;
 transition: width 180ms ease-out;
}

.writing-reference-progress-journey > .writing-reference-progress-track {
 margin-bottom: 10px;
}

.writing-reference-progress-journey .progress-stats .success {
 color: var(--success);
 margin-left: 6px;
}

.writing-reference-progress-journey .progress-stats .danger {
 color: var(--danger);
 margin-left: 6px;
}

.writing-reference-progress-journey .progress-stages {
 display: flex;
 gap: 6px;
 flex-wrap: wrap;
}

.writing-reference-progress-journey .progress-stage {
 display: flex;
 align-items: center;
 gap: 4px;
 padding: 4px 8px;
 background: #fff;
 border: 1px solid var(--line);
 border-radius: 4px;
 font-size: 12px;
 color: var(--muted);
}

.writing-reference-progress-journey .progress-stage.active {
 background: var(--info-bg);
 border-color: var(--info);
 color: var(--info);
}

.writing-reference-progress-journey .progress-stage.complete {
 background: var(--success-bg);
 border-color: var(--success);
 color: var(--success);
}

.writing-reference-progress-journey .progress-stage .stage-label {
 font-weight: 500;
}

.writing-reference-progress-journey .progress-stage .stage-count {
 font-weight: 600;
 min-width: 18px;
 text-align: center;
}

.writing-reference-progress-journey .progress-stage svg.success {
 color: var(--success);
}

.writing-reference-progress-journey .progress-stage svg.danger {
 color: var(--danger);
}

.writing-reference-progress-journey .progress-stage svg.spin {
 color: var(--info);
 animation: spin 1s linear infinite;
}

.writing-reference-progress-journey .progress-stage svg.muted {
 color: var(--muted);
}

.writing-reference-batch-actions,
.writing-reference-single-document-entry {
 display: flex;
 align-items: center;
 flex-wrap: wrap;
 gap: 8px;
}

.writing-reference-batch-actions button,
.writing-reference-single-document-entry button,
.writing-reference-batch-table button {
 display: inline-flex;
 align-items: center;
 gap: 5px;
}

.writing-reference-batch-actions > span,
.writing-reference-single-document-entry > span {
 color: var(--muted);
 font-size: 12px;
}

.writing-reference-batch-message {
 margin: 0;
 padding: 8px 10px;
 background: var(--info-bg);
 color: var(--info);
 font-size: 12px;
}

.writing-reference-batch-message.danger {
 background: var(--danger-bg);
 color: var(--danger);
}

.writing-reference-batch-table-wrap {
 border: 1px solid var(--line);
 overflow-x: auto;
}

.writing-reference-batch-table {
 width: 100%;
 min-width: 960px;
 border-collapse: collapse;
 table-layout: fixed;
}

.writing-reference-batch-table th,
.writing-reference-batch-table td {
 border-bottom: 1px solid var(--soft-line);
 padding: 9px 10px;
 text-align: left;
 vertical-align: top;
}

.writing-reference-batch-table th {
 background: var(--page);
 color: var(--muted);
 font-size: 12px;
 font-weight: 600;
}

.writing-reference-batch-table th:nth-child(1) { width: 18%; }
.writing-reference-batch-table th:nth-child(2) { width: 25%; }
.writing-reference-batch-table th:nth-child(3) { width: 11%; }
.writing-reference-batch-table th:nth-child(4) { width: 12%; }
.writing-reference-batch-table th:nth-child(5) { width: 13%; }
.writing-reference-batch-table th:nth-child(6) { width: 21%; }

.writing-reference-batch-table tr:last-child td {
 border-bottom: 0;
}

.writing-reference-batch-table tr.requires-attention td {
 background: #fffdf8;
}

.writing-reference-batch-table td > strong,
.writing-reference-batch-table td > small,
.writing-reference-batch-table td > em {
 display: block;
 overflow-wrap: anywhere;
}

.writing-reference-batch-table td > small {
 margin-top: 3px;
 color: var(--muted);
 font-size: 11px;
}

.writing-reference-batch-table td > em {
 margin-top: 5px;
 color: var(--danger);
 font-size: 11px;
 font-style: normal;
}

.writing-reference-next-step {
 display: inline-flex;
 align-items: center;
 gap: 5px;
 color: var(--success);
 font-size: 12px;
}

.writing-reference-next-step-cell {
 display: grid;
 justify-items: start;
 gap: 7px;
}

.writing-reference-batch-empty {
 padding: 18px;
 color: var(--muted);
 text-align: center;
}

.writing-reference-single-document-entry {
 border-top: 1px solid var(--soft-line);
 padding-top: 10px;
}

.writing-reference-single-document-tools {
 display: grid;
 gap: 12px;
 scroll-margin-top: 16px;
}

.writing-reference-translation-batch {
 min-width: 0;
 border: 1px solid var(--line);
 background: var(--surface);
 display: grid;
 gap: 10px;
 padding: 12px;
}

.writing-reference-translation-batch-head {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 14px;
}

.writing-reference-translation-batch-head > div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.writing-reference-translation-batch-head > div > span {
 display: inline-flex;
 align-items: center;
 gap: 5px;
 color: var(--muted);
 font-size: 12px;
}

.writing-reference-translation-batch-head strong {
 font-size: 15px;
}

.writing-reference-translation-batch-head small {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.writing-reference-translation-batch-head code {
 max-width: 220px;
 border: 1px solid var(--soft-line);
 padding: 4px 7px;
 background: var(--page);
 color: #4c5967;
 font-size: 10px;
 overflow-wrap: anywhere;
}

.writing-reference-translation-summary {
 min-width: 0;
 border-block: 1px solid var(--soft-line);
 display: grid;
 grid-template-columns: repeat(8, minmax(82px, 1fr));
}

.writing-reference-translation-summary > span {
 min-width: 0;
 min-height: 48px;
 display: grid;
 align-content: center;
 gap: 2px;
 padding: 7px 9px;
}

.writing-reference-translation-summary > span + span {
 border-left: 1px solid var(--soft-line);
}

.writing-reference-translation-summary small {
 color: var(--muted);
 font-size: 10px;
 white-space: nowrap;
}

.writing-reference-translation-summary b {
 min-width: 0;
 font-size: 15px;
 overflow-wrap: anywhere;
}

.writing-reference-translation-summary b.not_started,
.writing-reference-translation-summary b.queued,
.writing-reference-translation-summary b.completed_with_review_required,
.writing-reference-translation-summary .warning,
.writing-reference-translation-summary .warning b {
 color: var(--warning);
}

.writing-reference-translation-summary b.accepted,
.writing-reference-translation-summary b.running,
.writing-reference-translation-summary b.in_progress {
 color: var(--info);
}

.writing-reference-translation-summary b.completed {
 color: var(--success);
}

.writing-reference-translation-summary b.failed,
.writing-reference-translation-summary b.partial_failure,
.writing-reference-translation-summary b.completed_with_blocked,
.writing-reference-translation-summary b.completed_with_failures,
.writing-reference-translation-summary .danger,
.writing-reference-translation-summary .danger b {
 color: var(--danger);
}

.writing-reference-translation-scope {
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(360px, 1.4fr) minmax(250px, 0.8fr) max-content;
 gap: 10px;
 align-items: end;
}

.writing-reference-translation-scope fieldset {
 min-width: 0;
 margin: 0;
 padding: 7px 9px 8px;
 border: 1px solid var(--soft-line);
}

.writing-reference-translation-scope legend {
 padding: 0 4px;
 color: var(--muted);
 font-size: 11px;
 font-weight: 700;
}

.writing-reference-translation-anchor-options {
 min-width: 0;
 max-height: 82px;
 display: flex;
 flex-wrap: wrap;
 gap: 5px 10px;
 overflow-y: auto;
}

.writing-reference-translation-anchor-options label {
 min-width: 0;
 display: inline-flex;
 align-items: center;
 gap: 4px;
 color: var(--text);
 font-size: 11px;
 cursor: pointer;
}

.writing-reference-translation-anchor-options input {
 margin: 0;
}

.writing-reference-translation-anchor-options > span {
 color: var(--muted);
 font-size: 11px;
}

.writing-reference-translation-preview {
 min-height: 55px;
 border: 1px solid var(--soft-line);
 display: grid;
 grid-template-columns: repeat(3, minmax(72px, 1fr));
}

.writing-reference-translation-preview span {
 min-width: 0;
 display: grid;
 align-content: center;
 gap: 2px;
 padding: 6px 8px;
 color: var(--muted);
 font-size: 10px;
 line-height: 1.25;
}

.writing-reference-translation-preview span + span {
 border-left: 1px solid var(--soft-line);
}

.writing-reference-translation-preview b {
 color: var(--text);
 font-size: 14px;
}

.writing-reference-translation-actions {
 display: flex;
 flex-wrap: wrap;
 justify-content: flex-end;
 gap: 6px;
}

.writing-reference-translation-actions button,
.writing-reference-translation-table td button {
 min-height: 30px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 5px;
 white-space: nowrap;
}

.writing-reference-translation-message {
 margin: 0;
 padding: 7px 9px;
 background: var(--info-bg);
 color: var(--info);
 font-size: 11px;
 line-height: 1.45;
}

.writing-reference-translation-message.danger {
 background: var(--danger-bg);
 color: var(--danger);
}

.writing-reference-translation-empty {
 min-height: 82px;
 border-block: 1px solid var(--soft-line);
 display: grid;
 place-content: center;
 gap: 4px;
 padding: 14px;
 text-align: center;
}

.writing-reference-translation-empty span {
 max-width: 760px;
 color: var(--muted);
 font-size: 11px;
 line-height: 1.5;
}

.writing-reference-translation-table-tools {
 min-width: 0;
 display: flex;
 align-items: end;
 gap: 8px;
}

.writing-reference-translation-table-tools label {
 min-width: 160px;
 display: grid;
 gap: 3px;
 color: var(--muted);
 font-size: 10px;
 font-weight: 700;
}

.writing-reference-translation-table-tools select {
 width: 100%;
 height: 32px;
}

.writing-reference-translation-table-tools > span {
 margin-left: auto;
 padding-bottom: 8px;
 color: var(--muted);
 font-size: 11px;
}

.writing-reference-translation-table-wrap {
 min-width: 0;
 border: 1px solid var(--line);
 overflow-x: auto;
}

.writing-reference-translation-table {
 width: 100%;
 min-width: 1160px;
 border-collapse: collapse;
 table-layout: fixed;
}

.writing-reference-translation-table th,
.writing-reference-translation-table td {
 border-bottom: 1px solid var(--soft-line);
 padding: 8px 9px;
 text-align: left;
 vertical-align: top;
}

.writing-reference-translation-table th {
 background: var(--page);
}

.writing-reference-translation-table th button {
 width: 100%;
 min-width: 0;
 min-height: 24px;
 border: 0;
 padding: 0;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 4px;
 background: transparent;
 color: var(--muted);
 font-size: 11px;
 font-weight: 700;
 text-align: left;
}

.writing-reference-translation-table th button.active {
 color: var(--orange-dark);
}

.writing-reference-translation-table th:nth-child(1) { width: 18%; }
.writing-reference-translation-table th:nth-child(2) { width: 22%; }
.writing-reference-translation-table th:nth-child(3) { width: 11%; }
.writing-reference-translation-table th:nth-child(4) { width: 13%; }
.writing-reference-translation-table th:nth-child(5) { width: 11%; }
.writing-reference-translation-table th:nth-child(6) { width: 9%; }
.writing-reference-translation-table th:nth-child(7) { width: 16%; }

.writing-reference-translation-table tr:last-child td {
 border-bottom: 0;
}

.writing-reference-translation-table td > strong,
.writing-reference-translation-table td > small,
.writing-reference-translation-table td > span {
 display: block;
 min-width: 0;
 overflow-wrap: anywhere;
}

.writing-reference-translation-table td > small {
 margin-top: 3px;
 color: var(--muted);
 font-size: 10px;
 line-height: 1.4;
}

.writing-reference-translation-table td > span:not(.tag) {
 margin-bottom: 6px;
 color: var(--muted);
 font-size: 11px;
 line-height: 1.4;
}

.writing-reference-translation-table .tag {
 max-width: 100%;
 white-space: normal;
 text-align: center;
}

.writing-reference-translation-table-empty {
 padding: 16px;
 color: var(--muted);
 font-size: 11px;
 text-align: center;
}

.writing-reference-translation-exclusions {
 border-top: 1px solid var(--soft-line);
 padding-top: 8px;
}

.writing-reference-translation-exclusions summary {
 color: var(--muted);
 font-size: 11px;
 font-weight: 700;
 cursor: pointer;
}

.writing-reference-translation-exclusions > div {
 margin-top: 7px;
 border-top: 1px solid var(--soft-line);
 display: grid;
}

.writing-reference-translation-exclusions > div > strong,
.writing-reference-translation-exclusions p {
 min-width: 0;
 margin: 0;
 padding: 6px 7px;
 display: grid;
 grid-template-columns: minmax(130px, 0.35fr) minmax(0, 1fr);
 gap: 8px;
 border-bottom: 1px solid var(--soft-line);
 font-size: 11px;
}

.writing-reference-translation-exclusions > div > strong {
 grid-template-columns: minmax(0, 1fr) auto;
 background: var(--page);
}

.writing-reference-translation-exclusions > div > strong span,
.writing-reference-translation-exclusions p span,
.writing-reference-translation-exclusions > p {
 color: var(--muted);
 font-size: 11px;
 overflow-wrap: anywhere;
}

.writing-reference-translation-review-anchor {
 scroll-margin-top: 14px;
}

@media (max-width: 1199px) {
 .writing-reference-translation-summary {
 grid-template-columns: repeat(4, minmax(90px, 1fr));
 }

 .writing-reference-translation-summary > span:nth-child(5) {
 border-left: 0;
 }

 .writing-reference-translation-summary > span:nth-child(n + 5) {
 border-top: 1px solid var(--soft-line);
 }

 .writing-reference-translation-scope {
 grid-template-columns: minmax(0, 1fr) minmax(250px, 0.7fr);
 }

 .writing-reference-translation-actions {
 grid-column: 1 / -1;
 justify-content: flex-start;
 }
}

@media (max-width: 900px) {
 .writing-reference-batch-head {
 align-items: stretch;
 flex-direction: column;
 }

 .writing-reference-batch-status {
 align-self: flex-start;
 }

 .writing-reference-batch-summary {
 grid-template-columns: repeat(2, minmax(110px, 1fr));
 }

 .writing-reference-batch-summary > span:nth-child(odd):not(:first-child) {
 border-left: 0;
 border-top: 1px solid var(--soft-line);
 }

 .writing-reference-batch-summary > span:nth-child(even):not(:nth-child(2)) {
 border-top: 1px solid var(--soft-line);
 }

 .writing-reference-translation-batch-head {
 flex-direction: column;
 }

 .writing-reference-translation-batch-head code {
 max-width: 100%;
 }

 .writing-reference-translation-summary {
 grid-template-columns: repeat(2, minmax(100px, 1fr));
 }

 .writing-reference-translation-summary > span:nth-child(odd) {
 border-left: 0;
 }

 .writing-reference-translation-summary > span:nth-child(n + 3) {
 border-top: 1px solid var(--soft-line);
 }

 .writing-reference-translation-scope {
 grid-template-columns: minmax(0, 1fr);
 }

 .writing-reference-translation-actions {
 grid-column: 1;
 }

 .writing-reference-translation-table-tools {
 align-items: stretch;
 flex-direction: column;
 }

 .writing-reference-translation-table-tools label {
 width: 100%;
 }

 .writing-reference-translation-table-tools > span {
 margin-left: 0;
 padding-bottom: 0;
 }
}


/* W4-B/C: early competitor drawer + instrument appendix page preview */
.authoring-competitor-toolbar {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 margin: 0 0 10px;
 padding: 10px 12px;
 border: 1px solid var(--line);
 background: #f8fafb;
}

.authoring-competitor-toolbar > div {
 min-width: 0;
 display: flex;
 align-items: flex-start;
 gap: 8px;
}

.authoring-competitor-toolbar span {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.authoring-competitor-toolbar strong {
 font-size: 13px;
}

.authoring-competitor-toolbar small {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.authoring-open-competitor-drawer {
 flex: 0 0 auto;
 min-height: 34px;
 display: inline-flex;
 align-items: center;
 gap: 6px;
 white-space: nowrap;
}

.authoring-competitor-drawer-host {
 position: fixed;
 inset: 0;
 z-index: 48;
 pointer-events: none;
}

.authoring-competitor-drawer-host.is-open {
 pointer-events: auto;
}

.authoring-competitor-drawer-backdrop {
 position: absolute;
 inset: 0;
 border: 0;
 padding: 0;
 margin: 0;
 background: rgba(29, 39, 49, 0.28);
 opacity: 0;
 transition: opacity 0.18s ease;
 cursor: pointer;
}

.authoring-competitor-drawer-host.is-open .authoring-competitor-drawer-backdrop {
 opacity: 1;
}

.authoring-competitor-drawer {
 position: absolute;
 top: 0;
 right: 0;
 width: min(560px, 100vw);
 height: 100vh;
 border: 0;
 border-left: 1px solid var(--line);
 border-radius: 0;
 display: grid;
 grid-template-rows: auto minmax(0, 1fr);
 gap: 0;
 padding: 0;
 background: #fff;
 box-shadow: -12px 0 30px rgba(29, 39, 49, 0.16);
 transform: translateX(100%);
 visibility: hidden;
 transition: transform 0.18s ease, visibility 0.18s ease;
 overflow: hidden;
}

.authoring-competitor-drawer-host.is-open .authoring-competitor-drawer {
 transform: translateX(0);
 visibility: visible;
}

.authoring-competitor-drawer-header {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 12px;
 padding: 16px 16px 12px;
 border-bottom: 1px solid var(--line);
 background: #fbfcfd;
}

.authoring-competitor-drawer-header > div {
 min-width: 0;
 display: grid;
 gap: 3px;
}

.authoring-competitor-drawer-header span,
.authoring-competitor-drawer-header small {
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.authoring-competitor-drawer-header strong {
 font-size: 16px;
}

.authoring-competitor-drawer-close {
 flex: 0 0 auto;
}

.authoring-competitor-drawer-body {
 min-height: 0;
 overflow-y: auto;
 overflow-x: hidden;
 padding: 12px 14px 18px;
}

.authoring-competitor-drawer-empty {
 border: 1px dashed var(--line);
 padding: 16px;
 background: #fafbfc;
 display: grid;
 gap: 6px;
}

.authoring-competitor-drawer-empty p {
 margin: 0;
 color: var(--muted);
 font-size: 12px;
 line-height: 1.5;
}

.writing-reference-panel.is-embedded {
 min-height: 0;
 min-width: 0;
 max-width: 100%;
 gap: 10px;
}

.writing-reference-panel.is-embedded .writing-reference-candidate-filters {
 grid-template-columns: minmax(0, 1fr) minmax(120px, 0.45fr) auto;
}

.writing-reference-panel.is-embedded .writing-reference-boundary.is-embedded {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
 font-size: 12px;
}

.writing-reference-panel.is-embedded .writing-reference-list > button {
 min-height: 54px;
}

.writing-reference-panel.is-compact .writing-reference-list > button strong,
.writing-reference-panel.is-compact .writing-reference-list > button small {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.writing-reference-snapshot-details,
.writing-reference-provenance-details {
 border: 1px solid var(--soft-line);
 border-radius: 3px;
 padding: 6px 8px;
 background: #fafbfc;
}

.writing-reference-snapshot-details > summary,
.writing-reference-provenance-details > summary {
 cursor: pointer;
 color: var(--muted);
 font-size: 11px;
}

.writing-reference-snapshot-details .writing-reference-snapshot,
.writing-reference-provenance-details code {
 display: block;
 margin-top: 6px;
 font-size: 11px;
 word-break: break-all;
}

.writing-reference-panel.is-embedded .writing-reference-document-row > div > code,
.writing-reference-panel.is-embedded article > span > code {
 display: none;
}

.instrument-appendix-preview {
 min-width: 0;
 display: grid;
 gap: 8px;
}

.instrument-appendix-preview-head {
 display: flex;
 align-items: baseline;
 justify-content: space-between;
 gap: 10px;
}

.instrument-appendix-preview-head span,
.instrument-appendix-consistency-notice,
.instrument-appendix-preview.is-empty p {
 margin: 0;
 color: var(--muted);
 font-size: 11px;
 line-height: 1.45;
}

.instrument-appendix-consistency-notice {
 border: 1px solid #e4d2b5;
 border-radius: 3px;
 padding: 6px 8px;
 background: #fffaf0;
 color: #8a5a12;
}

.instrument-appendix-thumbnail-grid {
 display: grid;
 grid-template-columns: repeat(auto-fill, minmax(118px, 1fr));
 gap: 8px;
}

.instrument-appendix-thumbnail {
 position: relative;
 min-width: 0;
 min-height: 148px;
 display: grid;
 align-content: stretch;
 border: 1px solid var(--line);
 border-radius: 3px;
 padding: 0;
 overflow: hidden;
 background: #fff;
 cursor: pointer;
}

.instrument-appendix-thumbnail img {
 width: 100%;
 height: 132px;
 object-fit: contain;
 background: #f4f6f8;
}

.instrument-appendix-thumbnail-missing {
 display: grid;
 place-items: center;
 min-height: 132px;
 padding: 8px;
 color: var(--muted);
 font-size: 11px;
}

.instrument-appendix-thumbnail em {
 position: absolute;
 right: 5px;
 bottom: 5px;
 border: 1px solid var(--line);
 border-radius: 2px;
 padding: 1px 5px;
 background: rgba(255, 255, 255, 0.94);
 color: var(--ink);
 font-size: 10px;
 font-style: normal;
}

.instrument-appendix-review-overlay {
 position: fixed;
 inset: 0;
 z-index: 60;
 display: grid;
 place-items: center;
}

.instrument-appendix-review-backdrop {
 position: absolute;
 inset: 0;
 background: rgba(18, 24, 31, 0.55);
}

.instrument-appendix-review-panel {
 position: relative;
 z-index: 1;
 width: min(980px, calc(100vw - 48px));
 height: min(860px, calc(100vh - 48px));
 display: grid;
 grid-template-rows: auto minmax(0, 1fr) auto;
 border: 1px solid var(--line);
 background: #fff;
 box-shadow: 0 18px 48px rgba(18, 24, 31, 0.28);
}

.instrument-appendix-review-panel > header,
.instrument-appendix-review-controls {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 padding: 12px 14px;
 border-bottom: 1px solid var(--line);
 background: #fbfcfd;
}

.instrument-appendix-review-controls {
 border-bottom: 0;
 border-top: 1px solid var(--line);
}

.instrument-appendix-review-panel > header > div {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.instrument-appendix-review-panel > header span {
 color: var(--muted);
 font-size: 11px;
}

.instrument-appendix-review-stage {
 min-height: 0;
 overflow: auto;
 display: grid;
 place-items: center;
 padding: 14px;
 background: #eef1f4;
}

.instrument-appendix-review-stage img {
 max-width: 100%;
 max-height: 100%;
 object-fit: contain;
 background: #fff;
 box-shadow: 0 1px 4px rgba(18, 24, 31, 0.12);
}

.instrument-appendix-page-selector {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 color: var(--muted);
 font-size: 12px;
}

.instrument-appendix-page-selector select {
 min-height: 32px;
}

.instrument-appendix-page-indicator {
 min-width: 56px;
 text-align: center;
 font-variant-numeric: tabular-nums;
 font-size: 12px;
}

.instrument-appendix-review-controls button {
 min-height: 34px;
 display: inline-flex;
 align-items: center;
 gap: 4px;
}

.legacy-bootstrap-bar {
 min-height: 50px;
 margin: 0 0 10px;
 padding: 8px 12px;
 border: 1px solid #f1c79f;
 border-left: 3px solid var(--orange);
 background: #fffaf5;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 16px;
}

.legacy-bootstrap-bar.is-error {
 border-color: #edb1b1;
 border-left-color: var(--danger);
 background: var(--danger-bg);
}

.legacy-bootstrap-bar > div,
.legacy-bootstrap-bar > div > span {
 min-width: 0;
 display: flex;
 align-items: center;
 gap: 9px;
}

.legacy-bootstrap-bar > div > span {
 display: grid;
 gap: 1px;
}

.legacy-bootstrap-bar small {
 color: var(--muted);
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.legacy-bootstrap-bar > button,
.legacy-bootstrap-drawer button {
 min-height: 34px;
 border: 1px solid var(--line);
 background: #fff;
 color: var(--text);
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 5px;
}

.legacy-bootstrap-layer {
 position: fixed;
 z-index: 180;
 inset: 0;
 background: rgba(24, 29, 35, 0.24);
 display: flex;
 justify-content: flex-end;
}

.legacy-bootstrap-drawer {
 width: min(760px, calc(100vw - 96px));
 height: 100vh;
 background: #fff;
 box-shadow: -14px 0 34px rgba(23, 30, 38, 0.16);
 display: grid;
 grid-template-rows: auto auto minmax(0, 1fr) auto;
}

.legacy-bootstrap-drawer > header,
.legacy-bootstrap-drawer > footer {
 min-height: 62px;
 padding: 12px 16px;
 border-bottom: 1px solid var(--line);
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
}

.legacy-bootstrap-drawer > header > div {
 display: grid;
 gap: 2px;
}

.legacy-bootstrap-drawer > header span {
 color: var(--muted);
 font-size: 11px;
}

.legacy-bootstrap-drawer > header strong {
 font-size: 17px;
}

.legacy-bootstrap-drawer > header > button {
 width: 34px;
 padding: 0;
}

.legacy-bootstrap-source {
 min-width: 0;
 min-height: 58px;
 padding: 10px 16px;
 border-bottom: 1px solid var(--soft-line);
 background: #fafbfc;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr) auto;
 align-items: center;
 gap: 10px;
}

.legacy-bootstrap-source span {
 min-width: 0;
 display: grid;
 gap: 2px;
}

.legacy-bootstrap-source strong,
.legacy-bootstrap-source small {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}

.legacy-bootstrap-source small {
 color: var(--muted);
 font-size: 11px;
}

.legacy-bootstrap-source em {
 padding: 3px 7px;
 border: 1px solid #f1c79f;
 background: #fff7ee;
 color: var(--orange-dark);
 font-size: 11px;
 font-style: normal;
}

.legacy-bootstrap-start,
.legacy-bootstrap-progress,
.legacy-bootstrap-review {
 min-height: 0;
 overflow: auto;
 padding: 18px;
}

.legacy-bootstrap-start {
 align-content: start;
 display: grid;
 gap: 12px;
}

.legacy-bootstrap-progress {
 place-content: center;
 justify-items: center;
 text-align: center;
 display: grid;
 gap: 8px;
 color: var(--muted);
}

.legacy-bootstrap-progress strong {
 color: var(--text);
 font-size: 16px;
}

.legacy-bootstrap-progress ol {
 width: min(520px, 100%);
 margin: 14px 0 0;
 padding: 0;
 display: grid;
 grid-template-columns: repeat(3, minmax(0, 1fr));
 list-style: none;
}

.legacy-bootstrap-progress li {
 min-width: 0;
 min-height: 34px;
 padding: 0 8px;
 border-top: 2px solid var(--line);
 color: var(--muted);
 font-size: 12px;
 display: flex;
 align-items: center;
 justify-content: center;
 gap: 5px;
}

.legacy-bootstrap-progress li.is-complete {
 border-top-color: #5e9a70;
 color: #38734b;
}

.legacy-bootstrap-progress li.is-active {
 border-top-color: var(--orange);
 color: var(--orange-dark);
 font-weight: 600;
}

.legacy-bootstrap-review {
 display: grid;
 gap: 20px;
}

.legacy-bootstrap-review > section {
 display: grid;
 gap: 10px;
}

.legacy-bootstrap-review > section + section {
 padding-top: 18px;
 border-top: 1px solid var(--line);
}

.legacy-bootstrap-review section > header,
.legacy-bootstrap-role > div {
 display: flex;
 align-items: baseline;
 justify-content: space-between;
 gap: 12px;
}

.legacy-bootstrap-review header small,
.legacy-bootstrap-role small {
 color: var(--muted);
 font-size: 11px;
}

.legacy-bootstrap-role {
 grid-template-columns: minmax(0, 1fr) 180px;
 align-items: end;
}

.legacy-bootstrap-role > div {
 display: grid;
 justify-content: start;
 gap: 2px;
}

.legacy-bootstrap-role > label {
 grid-column: 1 / -1;
}

.legacy-bootstrap-grid {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 10px 12px;
}

.legacy-bootstrap-grid label,
.legacy-bootstrap-role label,
.legacy-bootstrap-warnings > label:last-child {
 min-width: 0;
 display: grid;
 gap: 5px;
}

.legacy-bootstrap-grid label > span,
.legacy-bootstrap-role label > span,
.legacy-bootstrap-warnings > label:last-child > span {
 color: var(--muted);
 font-size: 11px;
}

.legacy-bootstrap-grid .span-2 {
 grid-column: 1 / -1;
}

.legacy-bootstrap-grid input,
.legacy-bootstrap-grid textarea,
.legacy-bootstrap-role select,
.legacy-bootstrap-role textarea,
.legacy-bootstrap-warnings textarea {
 width: 100%;
 min-height: 36px;
 border: 1px solid var(--line);
 background: #fff;
 color: var(--text);
 padding: 7px 9px;
 resize: vertical;
}

.legacy-bootstrap-grid input:focus,
.legacy-bootstrap-grid textarea:focus,
.legacy-bootstrap-role select:focus,
.legacy-bootstrap-role textarea:focus,
.legacy-bootstrap-warnings textarea:focus {
 outline: 2px solid rgba(243, 112, 33, 0.18);
 border-color: var(--orange);
}

.legacy-bootstrap-warnings > label:not(:last-child) {
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 align-items: start;
 gap: 8px;
 padding: 8px 0;
 border-bottom: 1px solid var(--soft-line);
}

.legacy-bootstrap-drawer > footer {
 border-top: 1px solid var(--line);
 border-bottom: 0;
}

.legacy-bootstrap-drawer > footer > span {
 min-width: 0;
 color: var(--muted);
 font-size: 12px;
}

.legacy-bootstrap-drawer > footer > div {
 display: flex;
 gap: 8px;
}

.legacy-bootstrap-drawer .primary-button {
 border-color: var(--orange);
 background: var(--orange);
 color: #fff;
}

.legacy-bootstrap-drawer .danger {
 color: var(--danger);
}

@media (max-width: 1440px) {
 .authoring-competitor-drawer {
 width: min(520px, 100vw);
 }
}

@media (max-width: 1400px) {
 .authoring-competitor-drawer {
 width: min(480px, 100vw);
 }

 .instrument-appendix-thumbnail-grid {
 grid-template-columns: repeat(auto-fill, minmax(104px, 1fr));
 }
}

@media (max-width: 1366px) {
 .authoring-competitor-drawer {
 width: min(480px, 100vw);
 }

 .authoring-competitor-toolbar {
 flex-wrap: wrap;
 }
}
'
